; berryvp.library Stage 3D / BerryVP 9.2 backend integration
; Experimental hardware test: H.264 Annex-B -> BerryVP 9.2 VCHIQ/MMAL -> video_render/HVS.
; AAC is deliberately not exposed yet.
;
; Public vectors stay compatible with Stage 1.

        section code,code

BVPL_RT_MATCHWORD     equ $4AFC
BVPL_RTF_AUTOINIT     equ $80
BVPL_NT_LIBRARY       equ 9
BVPL_LN_TYPE          equ 8
BVPL_LN_PRI           equ 9
BVPL_LN_NAME          equ 10
BVPL_LIB_FLAGS        equ 14
BVPL_LIB_VERSION      equ 20
BVPL_LIB_REVISION     equ 22
BVPL_LIB_IDSTRING     equ 24
BVPL_LIB_OPENCNT      equ 32
BVPL_LIBB_DELEXP      equ 3
BVPL_OLDOPENLIB       equ -408
BVPL_CLOSELIB         equ -414
BVPL_OUTPUT           equ -60

BVP_API_VERSION       equ 3
BVP_API_REVISION      equ 2
BVP_VERSION_PACK      equ $00030002
BVP_OK                equ 0
BVPERR_BADSTATE       equ -1
BVPERR_BADPARAM       equ -2
BVPERR_UNSUPPORTED    equ -3
BVPERR_BUSY           equ -4
BVPERR_TIMEOUT        equ -5
BVPERR_BACKEND        equ -6
; N80: OpenStream flag. The caller will not call ConfigAudio (no HDMI
; audio: Paula, --no-audio, or a format the Pi side does not play).
; Bit 8: the low byte carries the P96 window size (10/25/50/75).
BVP_OPENF_NO_HDMI_AUDIO equ $100
BVPERR_CONFIG         equ -7
BVPERR_TOOLARGE       equ -8
BVPERR_NOBACKEND      equ -10
BVPERR_CONFIG_SPS      equ -11
BVPERR_CONFIG_PPS      equ -12
BVPERR_CONFIG_EXTRA    equ -13
BVPERR_CONFIG_GEOM     equ -14
BVPERR_CONFIG_COMPAT   equ -15

BVP_CAP_API_V1        equ $00000001
BVP_CAP_PTS64         equ $00000002
BVP_CAP_H264_HW       equ $00000100
BVP_CAP_DIRECT_HVS    equ $00000400
BVP_CAP_FRAME_FLAGS   equ $00000800
BVP_CAP_INPUT_PTS     equ $00001000
; N80: OpenStream honours BVP_OPENF_NO_HDMI_AUDIO (video without HDMI audio).
BVP_CAP_NO_HDMI_AUDIO equ $00002000
; MintVID VC1: ConfigVideo takes the codec ids below as well as H.264.
BVP_CAP_MULTI_CODEC   equ $00004000
BVP_CAP_AV_KEYS       equ $00008000   ; MintVID: +/- 1/2 counted at p96w_sync+96/+100
BVP_CAPS_STAGE3       equ BVP_CAP_API_V1+BVP_CAP_PTS64+BVP_CAP_H264_HW+BVP_CAP_DIRECT_HVS+BVP_CAP_FRAME_FLAGS+BVP_CAP_INPUT_PTS+BVP_CAP_NO_HDMI_AUDIO+BVP_CAP_MULTI_CODEC+BVP_CAP_AV_KEYS

BVP_CODEC_NONE        equ 0
BVP_CODEC_H264        equ 1
BVP_CODEC_AAC         equ 2
; MintVID VC1: other VideoCore decoders.  3/4 are AC-3/E-AC-3 (audio).
; MPEG-2 and VC-1 decode only with the Pi's licence key in config.txt
; (decode_MPG2=, decode_WVC1=), and only on a Pi 3 or older.
BVP_CODEC_MPEG4       equ 5      ; MPEG-4 Part 2 (DivX/Xvid)
BVP_CODEC_H263        equ 6
BVP_CODEC_MJPEG       equ 7
BVP_CODEC_MPEG1       equ 8
BVP_CODEC_MPEG2       equ 9
BVP_CODEC_VC1         equ 10     ; WVC1 (VC-1 Advanced)
BVP_STATE_IDLE        equ 0
BVP_STATE_OPEN        equ 1
BVP_STATE_PAUSED      equ 2
BVP_CFG_VIDEO         equ 1
BVP_CFG_AUDIO         equ 2
BVP_CTRL_FLUSH        equ 1
BVP_CTRL_PAUSE        equ 2
BVP_CTRL_RESUME       equ 3
BVP_CTRL_RESET        equ 4
BVP_CTRL_IDLE         equ 5      ; P96W45: keep the window alive (pause)
BVP_CTRL_TIMESHIFT    equ 6      ; P96W47: D1 = us the caller paused
BVP_CTRL_CLOCKSTART   equ 7      ; CLK81: D0 = Pi timer when the free clock started (0 = none)
BVP_CTRL_FORCEISP     equ 8      ; ISP82: D1 = 1 cinema always via ISP (test), 0 = normal
BVP_CTRL_OSD          equ 10     ; O1: D1 = OSD request block (test), 0 = none
BVP_CTRL_MUTE         equ 14     ; v96.87: D1 = 1 HDMI sound muted (PCM zeros, clock runs), 0 = on
BVP_CTRL_OSDCLOCK     equ 13     ; S1: D1 = 1 query the Pi clock ~1/s; D0 = clock block
BVP_CTRL_OSDPIC       equ 12     ; O3: D1 = new RGBA picture (same w x h) while the film plays
BVP_CTRL_OSDSHOW      equ 11     ; O2: D1 = 1 show OSD, 0 hide (while the film plays)
BVP_CTRL_ISPOUT       equ 9      ; N84: D1 = 0 normal, -1 no N83 upscale, (W<<16)|H ISP output size (test)
BVP_PKT_CONFIG        equ 1
BVP_PKT_FRAME_START   equ 2
BVP_PKT_FRAME_END     equ 4
BVP_PKT_KEY           equ 8

BVP_SYSBASE           equ 36
BVP_STATE             equ 40
BVP_STREAM_FLAGS      equ 44
BVP_CONFIG_FLAGS      equ 48
BVP_LAST_ERROR        equ 52
BVP_VIDEO_CODEC       equ 56
BVP_VIDEO_WIDTH       equ 60
BVP_VIDEO_HEIGHT      equ 64
BVP_VIDEO_TIMESCALE   equ 68
BVP_AUDIO_CODEC       equ 72
BVP_AUDIO_RATE        equ 76
BVP_AUDIO_CHANNELS    equ 80
BVP_AUDIO_TIMESCALE   equ 84
BVP_VIDEO_ATTEMPTS    equ 88
BVP_AUDIO_ATTEMPTS    equ 92
BVP_LAST_VPTS_HI      equ 96
BVP_LAST_VPTS_LO      equ 100
BVP_LAST_APTS_HI      equ 104
BVP_LAST_APTS_LO      equ 108
BVP_LAST_VIDEO_LEN    equ 112
BVP_LAST_AUDIO_LEN    equ 116
BVP_BASE_SIZE         equ 128

BVPL_Resident:
        dc.w    BVPL_RT_MATCHWORD
        dc.l    BVPL_Resident
        dc.l    BVPL_ModuleEnd
        dc.b    BVPL_RTF_AUTOINIT
        dc.b    BVP_API_VERSION
        dc.b    BVPL_NT_LIBRARY
        dc.b    0
        dc.l    BVPL_LibName
        dc.l    BVPL_IdString
        dc.l    BVPL_InitTable

BVPL_InitTable:
        dc.l    BVP_BASE_SIZE
        dc.l    BVPL_FuncTable
        dc.l    0
        dc.l    BVPL_LibInit

BVPL_FuncTable:
        dc.l    BVPL_LibOpen
        dc.l    BVPL_LibClose
        dc.l    BVPL_LibExpunge
        dc.l    BVPL_LibReserved
        dc.l    BVP_GetVersionN9
        dc.l    BVP_GetCaps
        dc.l    BVP_OpenStream
        dc.l    BVP_CloseStreamN9
        dc.l    BVP_ConfigVideo
        dc.l    ac307_ConfigAudio
        dc.l    BVP_SendVideo
        dc.l    BVP_SendAudioN9
        dc.l    BVP_Control
        dc.l    BVP_GetStatus
        dc.l    -1

BVPL_LibInit:
        move.l  d0,a1
        move.b  #BVPL_NT_LIBRARY,BVPL_LN_TYPE(a1)
        clr.b   BVPL_LN_PRI(a1)
        move.l  #BVPL_LibName,BVPL_LN_NAME(a1)
        clr.b   BVPL_LIB_FLAGS(a1)
        move.w  #BVP_API_VERSION,BVPL_LIB_VERSION(a1)
        move.w  #BVP_API_REVISION,BVPL_LIB_REVISION(a1)
        move.l  #BVPL_IdString,BVPL_LIB_IDSTRING(a1)
        move.l  a6,BVP_SYSBASE(a1)
        clr.l   BVP_STATE(a1)
        clr.l   BVP_STREAM_FLAGS(a1)
        clr.l   BVP_CONFIG_FLAGS(a1)
        clr.l   BVP_LAST_ERROR(a1)
        clr.l   BVP_VIDEO_CODEC(a1)
        clr.l   BVP_VIDEO_WIDTH(a1)
        clr.l   BVP_VIDEO_HEIGHT(a1)
        clr.l   BVP_VIDEO_TIMESCALE(a1)
        clr.l   BVP_AUDIO_CODEC(a1)
        clr.l   BVP_AUDIO_RATE(a1)
        clr.l   BVP_AUDIO_CHANNELS(a1)
        clr.l   BVP_AUDIO_TIMESCALE(a1)
        clr.l   BVP_VIDEO_ATTEMPTS(a1)
        clr.l   BVP_AUDIO_ATTEMPTS(a1)
        clr.l   BVP_LAST_VPTS_HI(a1)
        clr.l   BVP_LAST_VPTS_LO(a1)
        clr.l   BVP_LAST_APTS_HI(a1)
        clr.l   BVP_LAST_APTS_LO(a1)
        clr.l   BVP_LAST_VIDEO_LEN(a1)
        clr.l   BVP_LAST_AUDIO_LEN(a1)
        clr.l   bvp_library_mode
        clr.l   bvp_backend_ready
        clr.l   bvp_dos_base
        clr.l   bvp_libbase_global
        move.l  a1,d0
        rts

BVPL_LibOpen:
        addq.w  #1,BVPL_LIB_OPENCNT(a6)
        bclr    #BVPL_LIBB_DELEXP,BVPL_LIB_FLAGS(a6)
        move.l  a6,d0
        rts
BVPL_LibClose:
        tst.w   BVPL_LIB_OPENCNT(a6)
        beq.s   BVPL_LibCloseDone
        subq.w  #1,BVPL_LIB_OPENCNT(a6)
BVPL_LibCloseDone:
        moveq   #0,d0
        rts
BVPL_LibExpunge:
BVPL_LibReserved:
        moveq   #0,d0
        rts

BVP_GetVersion:
        move.l  #BVP_VERSION_PACK,d0
        rts
BVP_GetCaps:
        move.l  #BVP_CAPS_STAGE3,d0
        rts

BVP_OpenStream:
        tst.l   BVP_STATE(a6)
        beq.s   BVP_OS_Open
        moveq   #BVPERR_BUSY,d0
        move.l  d0,BVP_LAST_ERROR(a6)
        rts
BVP_OS_Open:
        move.l  d0,d1
        andi.l  #BVP_OPENF_NO_HDMI_AUDIO,d1
        move.l  d1,n80_no_hdmi_audio
        andi.l  #$FF,d0                  ; window size only (0 = cinema)
        move.l  d0,BVP_STREAM_FLAGS(a6)
        clr.l   hdmi_v40o_hvs_saved
        move.l  #BVP_STATE_OPEN,BVP_STATE(a6)
        clr.l   BVP_CONFIG_FLAGS(a6)
        clr.l   BVP_LAST_ERROR(a6)
        clr.l   BVP_VIDEO_ATTEMPTS(a6)
        clr.l   BVP_LAST_VPTS_HI(a6)
        clr.l   BVP_LAST_VPTS_LO(a6)
        clr.l   BVP_LAST_VIDEO_LEN(a6)
        clr.l   bvp_backend_ready
        clr.l   bvp_pending_ptr
        clr.l   bvp_pending_len
        clr.l   p96w_async_on
        clr.l   p96w_async_pending
        clr.l   p96w_coll_bytes
        clr.l   p96w_coll_samples
        clr.l   p96w_coll_force
        clr.l   p96w12_empty
        clr.l   p96w20_fast
        clr.l   n66_video_pending
        clr.l   n66_video_pending_len
        clr.l   n66_video_pending_flags
        clr.l   n66_video_pending_pts_hi
        clr.l   n66_video_pending_pts_lo
        clr.l   n66_video_enqueued
        clr.l   n66_video_service_calls
        clr.l   n66_video_service_submits
        clr.l   n66_video_service_defers
        clr.l   n66_video_forced_waits
        clr.l   n66_video_service_failures
        clr.l   n69_dispatch_entries
        clr.l   n69_dispatch_loops
        clr.l   n69_dispatch_audio_calls
        clr.l   n69_dispatch_failures
        clr.l   n79_first_video_trace_state
        clr.l   n79p96g_audio_trace_state
        clr.l   n70_early_due_count
        clr.l   n70_late_due_count
        clr.l   n70_early_lead_max_us
        clr.l   n73_scheduler_graph_ready
        clr.l   n81_tried                 ; CLK81: per stream
        clr.l   n81_active
        clr.l   n81_active_sys
        clr.l   n81_free_mode
        clr.l   n73_clock_armed
        clr.l   n80_last_defer
        clr.l   n73_first_pcm_published
        clr.l   n73_prime_flushes
        clr.l   n73_clock_arm_attempts
        clr.l   n73_clock_arm_failures
        clr.l   n73_video_pts_valid
        clr.l   n73_video_pts_unknown
        clr.l   vpv116_clock_probe_done
        moveq   #BVP_OK,d0
        rts

BVP_ConfigVideo:
        cmp.l   #BVP_STATE_OPEN,BVP_STATE(a6)
        beq.s   BVP_CV_StateOK
        cmp.l   #BVP_STATE_PAUSED,BVP_STATE(a6)
        beq.s   BVP_CV_StateOK
        moveq   #BVPERR_BADSTATE,d0
        bra.s   BVP_CV_Err
BVP_CV_StateOK:
        ; MintVID VC1: codec id -> MMAL encoding (bvp_codec_table).
        lea     bvp_codec_table,a0
BVP_CV_Find:
        tst.l   (a0)
        beq.s   BVP_CV_Unsup
        cmp.l   (a0),d0
        beq.s   BVP_CV_Found
        addq.l  #8,a0
        bra.s   BVP_CV_Find
BVP_CV_Found:
        tst.l   d1
        beq.s   BVP_CV_Bad
        tst.l   d2
        beq.s   BVP_CV_Bad
        tst.l   d3
        beq.s   BVP_CV_Bad
        move.l  4(a0),bvp_video_encoding
        move.l  d0,BVP_VIDEO_CODEC(a6)
        move.l  d1,BVP_VIDEO_WIDTH(a6)
        move.l  d2,BVP_VIDEO_HEIGHT(a6)
        move.l  d3,BVP_VIDEO_TIMESCALE(a6)
        ori.l   #BVP_CFG_VIDEO,BVP_CONFIG_FLAGS(a6)
        clr.l   BVP_LAST_ERROR(a6)
        moveq   #BVP_OK,d0
        rts
BVP_CV_Unsup:
        moveq   #BVPERR_UNSUPPORTED,d0
        bra.s   BVP_CV_Err
BVP_CV_Bad:
        moveq   #BVPERR_BADPARAM,d0
BVP_CV_Err:
        move.l  d0,BVP_LAST_ERROR(a6)
        rts

; MintVID VC1: ConfigVideo codec id, MMAL input encoding.  0 ends the list.
        cnop    0,4
bvp_codec_table:
        dc.l    BVP_CODEC_H264,MMAL_ENCODING_H264
        dc.l    BVP_CODEC_MPEG4,MMAL_ENCODING_MP4V
        dc.l    BVP_CODEC_H263,MMAL_ENCODING_H263
        dc.l    BVP_CODEC_MJPEG,MMAL_ENCODING_MJPEG
        dc.l    BVP_CODEC_MPEG1,MMAL_ENCODING_MP1V
        dc.l    BVP_CODEC_MPEG2,MMAL_ENCODING_MP2V
        dc.l    BVP_CODEC_VC1,MMAL_ENCODING_WVC1
        dc.l    0,0

; Stage 3 deliberately keeps AAC outside the public backend until H264 is proven.
BVP_ConfigAudio:
BVP_SendAudio:
        moveq   #BVPERR_UNSUPPORTED,d0
        move.l  d0,BVP_LAST_ERROR(a6)
        rts

; A0=data, D0=len, D1/D2=PTS hi/lo, D3=BVP_PKT_*.
; BVP_PKT_CONFIG: Annex-B bytes containing SPS+PPS. Initializes MMAL but does not
; submit those bytes as a stream chunk. Normal packets are synchronous Annex-B chunks.
BVP_SendVideo:
        move.l  a6,bvp_libbase_global
        movem.l d4-d7/a1-a5,-(sp)
        move.l  d0,d4
        move.l  d1,d5
        move.l  d2,d6
        move.l  d3,d7

        cmp.l   #BVP_STATE_OPEN,BVP_STATE(a6)
        beq.s   BVP_SV_StateOK
        cmp.l   #BVP_STATE_PAUSED,BVP_STATE(a6)
        beq.s   BVP_SV_StateOK
        moveq   #BVPERR_BADSTATE,d0
        bra.w   BVP_SV_Done
BVP_SV_StateOK:
        move.l  BVP_CONFIG_FLAGS(a6),d0
        btst    #0,d0
        beq.w   BVP_SV_BadState
        move.l  a0,d0
        beq.w   BVP_SV_BadParam
        tst.l   d4
        beq.w   BVP_SV_BadParam
        addq.l  #1,BVP_VIDEO_ATTEMPTS(a6)
        move.l  d5,BVP_LAST_VPTS_HI(a6)
        move.l  d6,BVP_LAST_VPTS_LO(a6)
        move.l  d4,BVP_LAST_VIDEO_LEN(a6)

        move.l  d7,d0
        andi.l  #BVP_PKT_CONFIG,d0
        beq.s   BVP_SV_Data
        clr.l   n11_video_returns
        clr.l   v93_event_count          ; v96.93
        move.l  a0,bvp_pending_ptr
        move.l  d4,bvp_pending_len
        bsr     bvp_backend_init_from_config
        bra.w   BVP_SV_Done

BVP_SV_Data:
        tst.l   s1_enabled                ; S1: Pi clock for subtitles
        beq.s   s1_sv_none
        jsr     s1_clk_maybe
s1_sv_none:
        tst.l   o3_req                    ; O3: new OSD picture pending
        beq.s   o3_sv_none
        jsr     o3_apply
o3_sv_none:
        tst.l   o2_req                    ; O2: OSD show/hide wish pending
        beq.s   o2_sv_none
        jsr     o2_apply
o2_sv_none:
        tst.l   bvp_p96_mode
        beq.s   p96w20_sv_nofast
        move.l  #1,p96w20_fast
        jsr     p96w_clk_maybe
        jsr     p96w38_poll_keys          ; P96W38: Esc/0/close in the video window
        jsr     p96w_present
p96w20_sv_nofast:
        ; P96W4: collect a finished CPU1 AAC batch without waiting.
        tst.l   p96w_async_on
        beq.s   p96w_sv_no_poll
        jsr     p96w_async_poll_nb
p96w_sv_no_poll:
        tst.l   n79_first_video_trace_state
        bne.s   n79_sv_seen
        move.l  #1,n79_first_video_trace_state
        lea     n79_v01,a1
        jsr     n12_log
n79_sv_seen:
        tst.l   bvp_backend_ready
        beq.w   BVP_SV_NoBackend
        cmpi.l  #$0003FFFC,d4
        bhi.w   BVP_SV_TooLarge

        ; N69: break the synchronous video-pacer/API boundary.  VPr8 owns the
        ; demux and can keep accepting AAC while the next video AU is not due;
        ; mrberry cannot do that while blocked inside SendVideo.  Keep exactly
        ; one compressed AU in library-owned Fast/BSS storage and return to the
        ; caller immediately.  Audio packet calls then get a chance to arrive
        ; before this AU is published at its native deadline.
        bsr     vpv98_read_sys_us
        move.l  d0,n63_video_send_start_us

        ; First give previously deferred Audio/Video work one opportunity.
        ; Preserve the new caller AU pointer/length while bvp_engine_env owns D4.
        move.l  a0,-(sp)
        move.l  d4,-(sp)
        bsr     bvp_engine_env
        jsr     n65_service_pending_audio
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v02
        lea     n79_v02,a1
        jsr     n12_log
n79_no_v02:
        tst.l   d0
        bne.s   N69_SV_ServiceFailRestore
        jsr     n66_service_pending_video
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v03
        lea     n79_v03,a1
        jsr     n12_log
n79_no_v03:
        tst.l   d0
        bne.s   N69_SV_ServiceFailRestore

        ; A single pending slot is deliberate.  By the time the next VIDEO AU
        ; reaches us, all interleaved AAC packets from MintVID have already had
        ; their public SendAudio calls.  Only if that previous AU is still not
        ; due do we wait here; the force loop continues servicing deferred PCM.
        tst.l   n66_video_pending
        beq.s   N69_SV_OldClear
        addq.l  #1,n66_video_forced_waits
        jsr     n66_force_pending_video
        tst.l   d0
        bne.s   N69_SV_ServiceFailRestore
N69_SV_OldClear:
        move.l  (sp)+,d4
        move.l  (sp)+,a0
        bra.s   N69_SV_CopyIncoming
N69_SV_ServiceFailRestore:
        move.l  (sp)+,d4
        move.l  (sp)+,a0
        bra.w   BVP_SV_Backend

N69_SV_CopyIncoming:
        ; Copy now because mr_packet storage is borrowed only until the next
        ; mr_demux_next_packet().  Longword copy keeps the extra host cost low.
        lea     n66_video_buffer,a1
        move.l  a0,a2
        move.l  d4,d3
        move.l  d3,d2
        lsr.l   #2,d2
        beq.s   N69_SV_CopyTail
N69_SV_CopyLong:
        move.l  (a2)+,(a1)+
        subq.l  #1,d2
        bne.s   N69_SV_CopyLong
N69_SV_CopyTail:
        andi.l  #3,d3
        beq.s   N69_SV_CopyDone
N69_SV_CopyByte:
        move.b  (a2)+,(a1)+
        subq.l  #1,d3
        bne.s   N69_SV_CopyByte
N69_SV_CopyDone:
        move.l  d4,n66_video_pending_len
        move.l  d7,n66_video_pending_flags
        move.l  d5,n66_video_pending_pts_hi
        move.l  d6,n66_video_pending_pts_lo
        cmpi.l  #$80000000,d5
        beq.s   n73_sv_pts_unknown
        addq.l  #1,n73_video_pts_valid
        bra.s   n73_sv_pts_counted
n73_sv_pts_unknown:
        addq.l  #1,n73_video_pts_unknown
n73_sv_pts_counted:
        move.l  #1,n66_video_pending
        addq.l  #1,n66_video_enqueued
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v04
        lea     n79_v04,a1
        jsr     n12_log
n79_no_v04:

        ; N69: VPr8-style library dispatcher boundary.  Do NOT return to mrberry
        ; while this FRAME_START is still waiting for its native deadline.
        ; Keep servicing deferred Audio on every wait pass and re-test video_due
        ; until this AU has actually been submitted.  Unlike N65, the precise
        ; frame wait is therefore not a pure video busy-loop; unlike N66, timing
        ; ownership remains inside one central service loop until publish.
        bsr     bvp_engine_env
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v05
        lea     n79_v05,a1
        jsr     n12_log
n79_no_v05:
        jsr     n69_dispatch_pending_video
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v14
        lea     n79_v14,a1
        jsr     n12_log
n79_no_v14:
        tst.l   d0
        bne.w   BVP_SV_Backend

        bsr     vpv98_read_sys_us
        sub.l   n63_video_send_start_us,d0
        add.l   d0,n63_video_send_total_us
        cmp.l   n63_video_send_max_us,d0
        bls.s   N69_SV_SendMaxOK
        move.l  d0,n63_video_send_max_us
N69_SV_SendMaxOK:
        addq.l  #1,n11_video_returns
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v15
        lea     n79_v15,a1
        jsr     n12_log
        move.l  #2,n79_first_video_trace_state
n79_no_v15:
        jsr     v90_hvs_probe
        moveq   #BVP_OK,d0
        bra.w   BVP_SV_Done
BVP_SV_BadState:
        moveq   #BVPERR_BADSTATE,d0
        bra.s   BVP_SV_Done
BVP_SV_BadParam:
        moveq   #BVPERR_BADPARAM,d0
        bra.s   BVP_SV_Done
BVP_SV_NoBackend:
        moveq   #BVPERR_NOBACKEND,d0
        bra.s   BVP_SV_Done
BVP_SV_TooLarge:
        moveq   #BVPERR_TOOLARGE,d0
        bra.s   BVP_SV_Done
BVP_SV_Backend:
        lea     n12_msg_v_feed_err,a1
        jsr     n12_log
        lea     n11_name_verr,a1
        jsr     n12_log
        moveq   #BVPERR_BACKEND,d0
BVP_SV_Done:
        move.l  bvp_libbase_global,a6
        move.l  d0,BVP_LAST_ERROR(a6)
        movem.l (sp)+,d4-d7/a1-a5
        rts

BVP_CloseStream:
        move.l  a6,bvp_libbase_global
        movem.l d2-d7/a0-a5,-(sp)
        moveq   #BVP_OK,d7
        tst.l   bvp_backend_ready
        beq.w   BVP_CS_NoBackend
        bsr     bvp_engine_env

        ; N30: real library-owned EOS/drain with pipelined normal input slots.
        ; SendVideo now waits only for the serialized BULK_TX completion; up to
        ; four normal H264 buffers may still be VideoCore-owned here. This is the
        ; same ownership model used by VPr8. Do NOT wait for every normal input
        ; return before EOS: the decoder is allowed to retain one or more inputs
        ; until the official EOS marker arrives. We only require the transport
        ; itself to be idle, then publish EOS and let the common dispatcher reap
        ; both normal returns and the EOS return during bvp_wait_eos.
        tst.l   p96w_wait_timeouts        ; P96W40: VideoCore dead -> no EOS
        beq.s   BVP_CS_NoDeadVC
        moveq   #BVPERR_TIMEOUT,d7
        bra.w   BVP_CS_ForceCleanup
BVP_CS_NoDeadVC:
        tst.l   input_bulk_pending
        beq.s   BVP_CS_TransportIdle
        bsr     bvp_wait_video_bulk_done
        tst.l   d0
        beq.s   BVP_CS_TransportIdle
        moveq   #BVPERR_TIMEOUT,d7
        bra.s   BVP_CS_ForceCleanup
BVP_CS_TransportIdle:
        move.l  #1,input_eof_seen
        tst.l   eos_sent
        bne.s   BVP_CS_EOSAlreadySent
        jsr     h19a_send_eos
BVP_CS_EOSAlreadySent:
        jsr     bvp_wait_eos
        tst.l   d0
        beq.s   BVP_CS_EOSDrained
        moveq   #BVPERR_TIMEOUT,d7
        bra.s   BVP_CS_ForceCleanup

BVP_CS_EOSDrained:
        ; h19a_send_eos uses D7 as its standalone poll counter. Re-establish the
        ; public CloseStream result only after the bounded library EOS wait.
        moveq   #BVP_OK,d7
        ; Direct-HVS mode has no host output callback carrying terminal EOS.
        ; Match BerryVP's proven HDMI completion path: give video_render 0.5 s
        ; with VCHIQ shared RAM DMA-owned, then arm the cleanup gate explicitly.
        jsr     dma_pre_all
        move.l  a5,a6
        move.l  #25,d1
        jsr     Delay(a6)
        jsr     dma_post_all
        move.l  #1,hdmi_v40o_drain_done
        move.l  #1,output_eos_seen

BVP_CS_ForceCleanup:
        ; v9_cleanup_all expects shared VCHIQ RAM DMA-owned. With successful EOS
        ; all four safety gates are now true, so renderer disable/destroy, MMAL
        ; service CLOSE and the saved Workbench HVS-list restore are executed.
        jsr     dma_pre_all
        jsr     v9_cleanup_all
        jsr     hdmi_v40o_close_window
        ; N80: v9_cleanup_all only tears down after a drained EOS.  If it
        ; left the MMAL service open, reset the VideoCore side anyway.
        tst.l   mmal_remote_port
        beq.s   BVP_CS_Cleaned
        jsr     n80_failed_reset
BVP_CS_Cleaned:
        clr.l   bvp_backend_ready
        clr.l   bvp_library_mode
        bra.s   BVP_CS_Done
BVP_CS_NoBackend:
        ; N80: a stream whose setup failed never got bvp_backend_ready, so
        ; nothing was torn down and the next open failed with -6 until a
        ; reboot.  Close its MMAL service and give the display back.
        tst.l   mmal_remote_port
        beq.s   BVP_CS_Done
        bsr     bvp_engine_env
        jsr     n80_failed_reset
        clr.l   bvp_library_mode
BVP_CS_Done:
        bsr     bvp_close_dos
        move.l  bvp_libbase_global,a6
        clr.l   BVP_STATE(a6)
        clr.l   BVP_STREAM_FLAGS(a6)
        clr.l   BVP_CONFIG_FLAGS(a6)
        move.l  d7,BVP_LAST_ERROR(a6)
        move.l  d7,d0
        movem.l (sp)+,d2-d7/a0-a5
        rts

; N80: reset the VideoCore side after a failed or undrained stream.
; Closing this invocation's MMAL service makes the VideoCore delete every
; component it owns (the same step a normal cleanup ends with).  Then
; the Workbench HVS list saved before the renderer took over is put back.
; Stream DMA memory is deliberately not freed: the VideoCore may still
; own it.  Entered with shared RAM DMA-owned; leaves it DMA-owned.
; Needs a5 = DOS base (bvp_engine_env).
n80_failed_reset:
        movem.l d0-d7/a0-a4/a6,-(sp)
        lea     n80_msg_fail_reset,a1
        jsr     n12_log
        jsr     dma_post_all
        jsr     v9_close_service
        lea     n80_pfx_reset_close,a1
        jsr     n15_log_hex32
        jsr     dma_pre_all
        move.l  a5,a6
        move.l  #25,d1
        jsr     Delay(a6)
        jsr     dma_post_all
        move.l  hdmi_v40o_hvs_saved,d0
        beq.s   n80_reset_no_hvs
        jsr     hdmi_v40o_restore_hvs_ptr
        lea     n80_pfx_reset_hvs,a1
        jsr     n15_log_hex32
n80_reset_no_hvs:
        clr.l   component_handle
        clr.l   hdmi_v40o_renderer_handle
        clr.l   v12a_isp_handle
        clr.l   mmal_remote_port
        jsr     dma_pre_all
        movem.l (sp)+,d0-d7/a0-a4/a6
        rts

BVP_Control:
        cmpi.l  #BVP_CTRL_PAUSE,d0
        beq.s   BVP_CTL_Pause
        cmpi.l  #BVP_CTRL_RESUME,d0
        beq.s   BVP_CTL_Resume
        cmpi.l  #BVP_CTRL_FLUSH,d0
        beq.s   BVP_CTL_OK
        cmpi.l  #BVP_CTRL_RESET,d0
        beq.s   BVP_CTL_OK
        cmpi.l  #BVP_CTRL_IDLE,d0
        beq.s   BVP_CTL_Idle
        cmpi.l  #BVP_CTRL_TIMESHIFT,d0
        beq.s   BVP_CTL_TimeShift
        cmpi.l  #BVP_CTRL_CLOCKSTART,d0
        beq.s   BVP_CTL_ClockStart
        cmpi.l  #BVP_CTRL_FORCEISP,d0
        beq.s   BVP_CTL_ForceIsp
        cmpi.l  #BVP_CTRL_ISPOUT,d0
        beq.s   BVP_CTL_IspOut
        cmpi.l  #BVP_CTRL_OSD,d0
        beq.s   BVP_CTL_Osd
        cmpi.l  #BVP_CTRL_OSDSHOW,d0
        beq.s   BVP_CTL_OsdShow
        cmpi.l  #BVP_CTRL_OSDPIC,d0
        beq.w   BVP_CTL_OsdPic
        cmpi.l  #BVP_CTRL_OSDCLOCK,d0
        beq.w   BVP_CTL_OsdClock
        cmpi.l  #BVP_CTRL_MUTE,d0
        beq.w   BVP_CTL_Mute
        moveq   #BVPERR_UNSUPPORTED,d0
        move.l  d0,BVP_LAST_ERROR(a6)
        rts
BVP_CTL_Pause:
        cmp.l   #BVP_STATE_OPEN,BVP_STATE(a6)
        bne.s   BVP_CTL_Bad
        move.l  #BVP_STATE_PAUSED,BVP_STATE(a6)
        move.l  #1,vpx_pause_active
        bra.s   BVP_CTL_OK
BVP_CTL_Resume:
        cmp.l   #BVP_STATE_PAUSED,BVP_STATE(a6)
        bne.s   BVP_CTL_Bad
        move.l  #BVP_STATE_OPEN,BVP_STATE(a6)
        clr.l   vpx_pause_active
        bra.s   BVP_CTL_OK
; P96W47: after a pause mrberry moves its own frame clock forward by the
; pause time; the library's window pacer (v04_pace_new_frame, absolute grid
; on vpv98_timer_base_us) must move by the same amount.  Otherwise every
; later frame is "late" for it, it never waits again, and the window ran
; into the Pi bulk hang 45-90 s after a pause (cinema: pacer unused, no
; hang).  Same as VPr8's vpx_pause_release.
BVP_CTL_TimeShift:
        add.l   d1,vpv98_timer_base_us
        add.l   d1,v41e_hr_base
        add.l   d1,vpx_pause_total_us
        addq.l  #1,p96w47_shifts
        ; P96W48: no more sound-clock queries after a pause.  Tests: with the
        ; queries the Pi bulk engine stalled 45-90 s after a pause (7 of 9
        ; runs); NOSYNC (no queries) 3 of 3 fine; VPr8 never queries.  The
        ; window hold goes on with the last clock sample, extrapolated with
        ; the Pi system timer; the clock stood still while paused, so the
        ; sample time moves forward by the pause.
        tst.l   bvp_p96_mode
        beq.s   BVP_CTL_OK
        add.l   d1,p96w_sync+16
        move.l  #1,p96w48_clk_frozen
        move.l  #1,p96w49_first          ; P96W49: new window after the pause
        clr.l   p96w49_win_n
BVP_CTL_OK:
        clr.l   BVP_LAST_ERROR(a6)
        moveq   #BVP_OK,d0
        rts
BVP_CTL_ClockStart:
        clr.l   BVP_LAST_ERROR(a6)
        move.l  n81_active_sys,d0
        rts
; ISP82: grid-line test.  The direct cinema graph (decoder -> scheduler ->
; renderer) shows green 1-pixel grid lines when the HVS has to upscale the
; picture (user report, 960x720 on a 1280x1024 screen).  D1 = 1 sends every
; cinema film through the ISP graph instead.  Set before OpenStream.
BVP_CTL_ForceIsp:
        move.l  d1,n82_force_isp
        bra.s   BVP_CTL_OK
; N84: green-stripe test (720x404 anime, 28.10.2026).  D1 = 0 normal N83,
; -1 = no N83 upscale (old N79J path, as P96W31), else (W<<16)|H = ISP
; output size for the N83 upscale.  Set before OpenStream.
BVP_CTL_IspOut:
        move.l  d1,n84_isp_out
        bra.s   BVP_CTL_OK
; O1: OSD test request block (see o1_setup).  Set before OpenStream.
BVP_CTL_Osd:
        move.l  d1,o1_req
        bra.s   BVP_CTL_OK
; O2: show/hide the OSD layer while the film plays.  Only notes the wish;
; the PARAMETER_SET goes out at the start of the next SendVideo (o2_apply),
; where the library owns the VCHIQ queues (same place as the window clock
; queries).  Its reply is consumed by the normal dispatcher (o2_reply).
BVP_CTL_OsdShow:
        tst.l   o1_ok
        beq.s   BVP_CTL_OsdNo
        move.l  d1,o2_want
        move.l  #1,o2_req
        addq.l  #1,o2_requests
        bra.s   BVP_CTL_OK
BVP_CTL_OsdNo:
        moveq   #BVPERR_UNSUPPORTED,d0
        move.l  d0,BVP_LAST_ERROR(a6)
        rts
; S1: subtitles need the film time on screen.  In cinema with HDMI sound the
; Pi audio clock is the master; while enabled the library asks it about once
; a second (PARAMETER_GET CLOCK_TIME, fire and forget at SendVideo start, as
; the window clock queries) and keeps the last answer in s1_block:
;   +0 replies  +4 media time hi  +8 media time lo (us)  +12 Pi timer of the
;   sample  +16 queries  +20 lost/failed
; v96.87: mute.  The PCM keeps flowing to audio_render (its clock is the
; master), only zeros are copied into the DMA slot instead of the sound.
BVP_CTL_Mute:
        move.l  d1,m1_mute
        bra.w   BVP_CTL_OK
BVP_CTL_OsdClock:
        tst.l   o1_ok                     ; only with a working OSD layer
        bne.s   s1_ctl_ok
        moveq   #0,d0
        rts
s1_ctl_ok:
        move.l  d1,s1_enabled
        lea     s1_block,a0
        move.l  a0,d0
        clr.l   BVP_LAST_ERROR(a6)
        rts
; O3: new OSD picture.  Copied at once into the library's DMA buffer (the
; caller may reuse its memory); sent at the start of the next SendVideo.
BVP_CTL_OsdPic:
        tst.l   o1_ok
        beq.s   BVP_CTL_OsdNo
        tst.l   o3_dead
        bne.s   BVP_CTL_OsdNo
        tst.l   d1
        beq.s   BVP_CTL_OsdNo
        movem.l d1/a0-a1/a6,-(sp)
        move.l  d1,a0
        move.l  o1_buf,a1
        move.l  o1_bytes,d0
        lsr.l   #2,d0
        subq.l  #1,d0
o3_ctl_copy:
        move.l  (a0)+,(a1)+
        subq.l  #1,d0
        bpl.s   o3_ctl_copy
        move.l  4.w,a6
        move.l  o1_bytes,o1_dma_len
        move.l  o1_buf,a0
        lea     o1_dma_len,a1
        moveq   #0,d0
        jsr     CachePreDMA(a6)
        move.l  o1_bytes,o1_dma_len
        move.l  o1_buf,a0
        lea     o1_dma_len,a1
        moveq   #0,d0
        jsr     CachePostDMA(a6)
        movem.l (sp)+,d1/a0-a1/a6
        move.l  #1,o3_req
        addq.l  #1,o3_requests
        bra.w   BVP_CTL_OK
BVP_CTL_Bad:
        moveq   #BVPERR_BADSTATE,d0
        move.l  d0,BVP_LAST_ERROR(a6)
        rts
; P96W45: mrberry calls this about every 40 ms while it pauses (it sends no
; packets then).  In the window: window keys (Esc/0/close/Space), VCHIQ
; callback service, draw due held frames (P96W46: no clock queries).
; Cinema mode: nothing to do.
BVP_CTL_Idle:
        cmp.l   #BVP_STATE_OPEN,BVP_STATE(a6)
        bne.s   BVP_CTL_OK
        tst.l   bvp_p96_mode
        beq.s   BVP_CTL_OK
        tst.l   bvp_backend_ready
        beq.s   BVP_CTL_OK
        tst.l   p96w_wait_timeouts       ; stream already broken: leave it alone
        bne.s   BVP_CTL_OK
        movem.l d2-d7/a2-a6,-(sp)
        move.l  a6,bvp_libbase_global
        jsr     p96w38_poll_keys          ; P96W46: no clock queries while paused
        jsr     bvp_engine_env
        jsr     p96w9_idle_poll
        movem.l (sp)+,d2-d7/a2-a6
        bra.s   BVP_CTL_OK

BVP_GetStatus:
        move.l  a0,d0
        beq.s   BVP_GS_Bad
        move.l  #BVP_VERSION_PACK,(a0)+
        move.l  #BVP_CAPS_STAGE3,(a0)+
        move.l  BVP_STATE(a6),(a0)+
        move.l  BVP_CONFIG_FLAGS(a6),(a0)+
        move.l  BVP_LAST_ERROR(a6),(a0)+
        move.l  BVP_VIDEO_ATTEMPTS(a6),(a0)+
        move.l  BVP_AUDIO_ATTEMPTS(a6),(a0)+
        move.l  BVP_LAST_VPTS_HI(a6),(a0)+
        move.l  BVP_LAST_VPTS_LO(a6),(a0)+
        move.l  BVP_LAST_APTS_HI(a6),(a0)+
        move.l  BVP_LAST_APTS_LO(a6),(a0)+
        move.l  bvp_backend_ready,(a0)
        moveq   #BVP_OK,d0
        rts
BVP_GS_Bad:
        moveq   #BVPERR_BADPARAM,d0
        move.l  d0,BVP_LAST_ERROR(a6)
        rts

; Set BerryVP 9.2's permanent register environment for a library call.
bvp_engine_env:
        move.l  bvp_libbase_global,a0
        move.l  BVP_SYSBASE(a0),a4
        move.l  bvp_dos_base,a5
        move.l  bvp_output_handle,d4
        rts

bvp_open_dos:
        tst.l   bvp_dos_base
        bne.s   bvp_open_dos_ok
        move.l  bvp_libbase_global,a0
        move.l  BVP_SYSBASE(a0),a6
        lea     dosname,a1
        jsr     BVPL_OLDOPENLIB(a6)
        tst.l   d0
        beq.s   bvp_open_dos_fail
        move.l  d0,bvp_dos_base
        move.l  d0,a6
        jsr     BVPL_OUTPUT(a6)
        move.l  d0,bvp_output_handle
        tst.l   d0
        beq.s   bvp_open_dos_fail_close
bvp_open_dos_ok:
        moveq   #0,d0
        rts
bvp_open_dos_fail_close:
        move.l  bvp_libbase_global,a0
        move.l  BVP_SYSBASE(a0),a6
        move.l  bvp_dos_base,a1
        jsr     BVPL_CLOSELIB(a6)
        clr.l   bvp_dos_base
bvp_open_dos_fail:
        moveq   #1,d0
        rts

bvp_close_dos:
        move.l  bvp_dos_base,d0
        beq.s   bvp_close_dos_done
        move.l  bvp_libbase_global,a0
        move.l  BVP_SYSBASE(a0),a6
        move.l  d0,a1
        jsr     BVPL_CLOSELIB(a6)
        clr.l   bvp_dos_base
        clr.l   bvp_output_handle
bvp_close_dos_done:
        rts

; Parse SPS/PPS from caller-provided Annex-B config then start the proven 9.2
; MMAL graph in direct C/video_render mode. D0 = public BVP result.
bvp_backend_init_from_config:
        tst.l   bvp_backend_ready
        beq.s   bvp_bi_start
        moveq   #BVP_OK,d0
        rts
bvp_bi_start:
        move.l  bvp_pending_len,d0
        cmpi.l  #4096,d0
        bhi.w   bvp_bi_config_fail
        ; MintVID VC1: other codecs send 'BVPX' + their extradata (>= 4).
        cmpi.l  #4,d0
        bcs.w   bvp_bi_config_fail
        cmpi.l  #MMAL_ENCODING_H264,bvp_video_encoding
        bne.s   bvp_bi_len_ok
        cmpi.l  #8,d0
        bcs.w   bvp_bi_config_fail
bvp_bi_len_ok:
        bsr     bvp_open_dos
        tst.l   d0
        bne.w   bvp_bi_backend_fail
        bsr     bvp_engine_env
        lea     n10d_name_01,a1
        jsr     n12_log

        ; quiet process/log state expected by reused BerryVP helpers
        clr.l   mkvr7_log_mode
        clr.l   mkvr7_log_handle
        clr.l   mkvr7_log_started
        clr.l   vpv21f_log_handle
        clr.l   v15_stop_requested
        clr.l   vpx_pause_active
        clr.l   v32r_restart_cycle
        clr.l   v32r_restart_armed
        clr.l   v32r_fastforward
        clr.l   v40j_time_seek_active
        clr.l   v005r5_seek_valid
        clr.l   v10b_input_is_mkv
        clr.l   v10_timecode_scale
        clr.l   v10_first_pts_found
        ; OpenStream flags select the display mode.
        ;   10/25/50/75 = VPr8 P96 window (ISP BGR24 -> host -> P96)
        ;   everything else = direct VideoCore/HVS cinema (unchanged).
        clr.l   bvp_p96_mode
        move.l  #203,v40j_cli_mode
        move.l  #3,v41_display_style
        move.l  bvp_libbase_global,a0
        move.l  BVP_STREAM_FLAGS(a0),d0
        cmpi.l  #10,d0
        beq.s   p96w_mode_window
        cmpi.l  #25,d0
        beq.s   p96w_mode_window
        cmpi.l  #50,d0
        beq.s   p96w_mode_window
        cmpi.l  #75,d0
        bne.s   p96w_mode_done
p96w_mode_window:
        move.l  d0,v40j_cli_mode
        clr.l   v41_display_style
        move.l  #1,bvp_p96_mode
        lea     p96w_msg_window_mode,a1
        jsr     n12_log
        move.l  v40j_cli_mode,d0
        lea     p96w_pfx_mode,a1
        jsr     n15_log_hex32
p96w_mode_done:
        jsr     p96w_clk_open
        move.l  #1,bvp_library_mode
        clr.l   bvp_n21_feed_retries

        ; MintVID VC1: no SPS for other codecs; geometry and rate come from
        ; ConfigVideo instead (bvpx_config_other).
        cmpi.l  #MMAL_ENCODING_H264,bvp_video_encoding
        beq.s   bvp_bi_h264_config
        bsr     bvpx_config_other
        tst.l   d0
        bne.w   bvp_bi_geom_fail
        bra.w   bvp_bi_timing_ok
bvp_bi_h264_config:
        ; Copy caller config into the probe buffer used by BerryVP's proven Annex-B scanner.
        move.l  bvp_pending_ptr,a0
        lea     h264_probe_buf,a1
        move.l  bvp_pending_len,d0
        move.l  d0,h264_probe_read
        move.l  d0,d1
bvp_bi_copy_probe:
        move.b  (a0)+,(a1)+
        subq.l  #1,d1
        bne.s   bvp_bi_copy_probe
        clr.l   h264_codec_config_len
        clr.l   h264_sps_len
        clr.l   h264_pps_len

        moveq   #7,d0
        jsr     h264_find_nal
        tst.l   d0
        beq.w   bvp_bi_sps_fail
        move.l  a0,h264_sps_ptr
        move.l  d1,h264_sps_len
        moveq   #8,d0
        jsr     h264_find_nal
        tst.l   d0
        beq.w   bvp_bi_pps_fail
        move.l  a0,h264_pps_ptr
        move.l  d1,h264_pps_len
        move.l  h264_sps_len,d0
        add.l   h264_pps_len,d0
        tst.l   d0
        beq.w   bvp_bi_extra_fail
        cmpi.l  #128,d0
        bhi.w   bvp_bi_extra_fail
        move.l  d0,h264_codec_config_len
        lea     n10d_name_02,a1
        jsr     n12_log

        lea     h264_file_extradata,a0
        moveq   #31,d1
bvp_bi_clear_extra:
        clr.l   (a0)+
        dbra    d1,bvp_bi_clear_extra
        move.l  h264_sps_ptr,a0
        lea     h264_file_extradata,a1
        move.l  h264_sps_len,d1
        subq.l  #1,d1
bvp_bi_copy_sps:
        move.b  (a0)+,(a1)+
        dbra    d1,bvp_bi_copy_sps
        move.l  h264_pps_ptr,a0
        move.l  h264_pps_len,d1
        subq.l  #1,d1
bvp_bi_copy_pps:
        move.b  (a0)+,(a1)+
        dbra    d1,bvp_bi_copy_pps

        jsr     v6_parse_sps_geometry
        tst.l   d0
        bne.w   bvp_bi_geom_fail

        ; N16: persist the exact SPS facts that drive lazy decoder allocation.
        move.l  v6_profile_idc,d0
        lea     n15_pfx_sps_profile,a1
        jsr     n15_log_hex32
        lea     v6_sps_rbsp,a0
        moveq   #0,d0
        move.b  2(a0),d0                ; level_idc
        lea     n15_pfx_sps_level,a1
        jsr     n15_log_hex32
        move.l  v10j_max_num_ref_frames,d0
        lea     n15_pfx_sps_refs,a1
        jsr     n15_log_hex32
        move.l  v6_src_visible_w,d0
        lea     n15_pfx_vis_w,a1
        jsr     n15_log_hex32
        move.l  v6_src_visible_h,d0
        lea     n15_pfx_vis_h,a1
        jsr     n15_log_hex32
        move.l  v6_src_aligned_w,d0
        lea     n15_pfx_align_w,a1
        jsr     n15_log_hex32
        move.l  v6_src_aligned_h,d0
        lea     n15_pfx_align_h,a1
        jsr     n15_log_hex32

        jsr     v10p_check_unsupported_sps
        tst.l   d0
        bne.w   bvp_bi_compat_fail
        ; MintVID supplies packet PTS, therefore SPS VUI timing is useful but
        ; must not be mandatory for the hardware backend.  Try the original
        ; BerryVP timing parser first; if VUI timing is absent/out-of-range,
        ; install a safe 25/1 format/scheduler default.  Input PTS remains the
        ; authoritative presentation timeline in Stage 3.
        jsr     v7_setup_timing
        tst.l   d0
        beq.s   bvp_bi_timing_ok
        bsr     bvp_set_default_timing
bvp_bi_timing_ok:
        jsr     v04_timing_reset
        clr.l   n63_video_send_start_us
        clr.l   n63_video_phase_start_us
        clr.l   n63_video_saved_result
        clr.l   n63_video_send_total_us
        clr.l   n63_video_send_max_us
        clr.l   n63_video_pacer_calls
        clr.l   n63_video_pacer_total_us
        clr.l   n63_video_pacer_max_us
        clr.l   n63_video_pacer_gt20ms
        clr.l   n63_video_submit_total_us
        clr.l   n63_video_submit_max_us
        clr.l   n63_video_bulk_total_us
        clr.l   n63_video_bulk_max_us
        ; N65 startup proof: record the native SPS/VUI rate driving the
        ; absolute 1-MHz host pacer.
        move.l  v7_fps_num,d0
        lea     n59_pfx_fps_num,a1
        jsr     n15_log_hex32
        move.l  v7_fps_den,d0
        lea     n59_pfx_fps_den,a1
        jsr     n15_log_hex32
        lea     n10d_name_03,a1
        jsr     n12_log

        ; Backend success paths are patched below to RTS instead of entering BerryVP's file loop.
        ; Stage 4H: pure Stage-3D video isolation. Only save a safe return
        ; anchor around the inherited VCHIQ/MMAL entry; video logic is unchanged.
        lea     n10d_name_04,a1
        jsr     n12_log
        jsr     BVP4H_VchiqEntryWrapper
        tst.l   d0
        bne.w   bvp_bi_backend_fail
        move.l  hdmi_v40o_displayregion_ok,d0
        lea     n64_pfx_displayregion_ok,a1
        jsr     n15_log_hex32
        lea     n64_msg_no_window,a1
        jsr     n12_log
        lea     n10d_name_05,a1
        jsr     n12_log
        move.l  #1,bvp_backend_ready
        moveq   #BVP_OK,d0
        rts
bvp_bi_sps_fail:
        clr.l   bvp_library_mode
        moveq   #BVPERR_CONFIG_SPS,d0
        rts
bvp_bi_pps_fail:
        clr.l   bvp_library_mode
        moveq   #BVPERR_CONFIG_PPS,d0
        rts
bvp_bi_extra_fail:
        clr.l   bvp_library_mode
        moveq   #BVPERR_CONFIG_EXTRA,d0
        rts
bvp_bi_geom_fail:
        clr.l   bvp_library_mode
        moveq   #BVPERR_CONFIG_GEOM,d0
        rts
bvp_bi_compat_fail:
        clr.l   bvp_library_mode
        moveq   #BVPERR_CONFIG_COMPAT,d0
        rts
bvp_bi_config_fail:
        clr.l   bvp_library_mode
        moveq   #BVPERR_CONFIG,d0
        rts
bvp_bi_backend_fail:
        clr.l   bvp_library_mode
        moveq   #BVPERR_BACKEND,d0
        rts

; --------------------------------------------------------------------
; MintVID VC1: set up a non-H.264 stream.  The config packet is 'BVPX'
; followed by up to 128 bytes of codec extradata (MPEG-4 VOL, VC-1
; sequence header; nothing for MJPEG/H.263/MPEG-1/2, whose headers are
; in the stream).  The SPS facts the H.264 path parses are set from
; ConfigVideo's width/height, and its 4th argument carries the frame
; rate as (num<<16)|den (num <= 32767), 0 = unknown (25 fps).
; D0 = 0 ok, 1 = bad geometry/extradata.
; --------------------------------------------------------------------
bvpx_config_other:
        movem.l d1-d3/a0-a2,-(sp)
        move.l  bvp_pending_ptr,a0
        cmpi.l  #$42565058,(a0)+           ; 'BVPX'
        bne.w   bvpx_fail
        move.l  bvp_pending_len,d0
        subq.l  #4,d0
        cmpi.l  #128,d0
        bhi.w   bvpx_fail
        move.l  d0,h264_codec_config_len
        clr.l   h264_sps_len
        clr.l   h264_pps_len
        lea     h264_file_extradata,a1
        moveq   #31,d1
bvpx_extra_clear:
        clr.l   (a1)+
        dbra    d1,bvpx_extra_clear
        lea     h264_file_extradata,a1
        move.l  h264_codec_config_len,d1
        beq.s   bvpx_extra_done
        subq.l  #1,d1
bvpx_extra_copy:
        move.b  (a0)+,(a1)+
        dbra    d1,bvpx_extra_copy
bvpx_extra_done:
        move.l  bvp_libbase_global,a2
        move.l  BVP_VIDEO_WIDTH(a2),d1
        move.l  BVP_VIDEO_HEIGHT(a2),d2
        andi.l  #$FFFFFFFE,d1
        andi.l  #$FFFFFFFE,d2
        cmpi.l  #16,d1
        bcs.w   bvpx_fail
        cmpi.l  #V6_MAX_SRC_W,d1
        bhi.w   bvpx_fail
        cmpi.l  #16,d2
        bcs.w   bvpx_fail
        cmpi.l  #V6_MAX_SRC_H,d2
        bhi.w   bvpx_fail
        move.l  d1,v6_src_visible_w
        move.l  d2,v6_src_visible_h
        clr.l   v6_src_crop_x
        clr.l   v6_src_crop_y
        clr.l   v6_crop_left
        clr.l   v6_crop_right
        clr.l   v6_crop_top
        clr.l   v6_crop_bottom
        move.l  d1,d0
        add.l   #15,d0
        and.l   #$FFFFFFF0,d0
        move.l  d0,v6_src_coded_w
        add.l   #31,d0
        and.l   #$FFFFFFE0,d0
        move.l  d0,v6_src_aligned_w
        move.l  d2,d0
        add.l   #15,d0
        and.l   #$FFFFFFF0,d0
        move.l  d0,v6_src_coded_h
        move.l  d0,v6_src_aligned_h
        clr.l   v6_profile_idc
        clr.l   v10d_high_profile
        move.l  #1,v10d_chroma_format_idc
        clr.l   v10d_bit_depth_luma_m8
        clr.l   v10d_bit_depth_chroma_m8
        clr.l   v10d_scaling_matrix_present
        move.l  #1,v6_frame_mbs_only
        move.l  #2,v10j_max_num_ref_frames
        ; frame rate: v7_setup_timing reads fps = time_scale / (2 * units)
        clr.l   v7_timing_present
        move.l  BVP_VIDEO_TIMESCALE(a2),d0
        move.l  d0,d1
        andi.l  #$00007FFF,d1              ; den
        beq.s   bvpx_default_rate
        lsr.l   #8,d0
        lsr.l   #8,d0                      ; num
        beq.s   bvpx_default_rate
        cmpi.l  #32767,d0
        bhi.s   bvpx_default_rate
        add.l   d0,d0
        move.l  d0,v7_time_scale
        move.l  d1,v7_num_units_in_tick
        move.l  #1,v7_timing_present
        jsr     v7_setup_timing
        tst.l   d0
        beq.s   bvpx_rate_done
bvpx_default_rate:
        bsr     bvp_set_default_timing
bvpx_rate_done:
        lea     bvpx_msg_other,a1
        jsr     n12_log
        move.l  bvp_video_encoding,d0
        lea     bvpx_pfx_encoding,a1
        jsr     n15_log_hex32
        move.l  v6_src_visible_w,d0
        lea     n15_pfx_vis_w,a1
        jsr     n15_log_hex32
        move.l  v6_src_visible_h,d0
        lea     n15_pfx_vis_h,a1
        jsr     n15_log_hex32
        move.l  h264_codec_config_len,d0
        lea     bvpx_pfx_extra,a1
        jsr     n15_log_hex32
        moveq   #0,d0
        bra.s   bvpx_done
bvpx_fail:
        moveq   #1,d0
bvpx_done:
        movem.l (sp)+,d1-d3/a0-a2
        rts

; Stage 3A fallback for streams without usable SPS VUI timing.
; This only supplies MMAL's nominal input format and the inherited BerryVP
; scheduler state.  MintVID/Stage3 packet PTS are still forwarded separately.
bvp_set_default_timing:
        move.l  #25,v7_fps_num
        move.l  #1,v7_fps_den
        move.l  #2,v7_sched_step_num
        move.l  #1,v7_sched_step_den
        clr.l   v7_sched_accum
        move.l  #1,t8c_cap25_mode
        move.l  #25,t8c_select_step
        clr.l   t8c_select_accum
        rts

; h22_load_frame_data calls this path when bvp_library_mode != 0.
; It copies exactly one caller chunk into the selected 256-KiB input slot.
bvp_load_direct_packet:
        move.l  bvp_pending_len,d0
        tst.l   d0
        beq.s   bvp_ldp_fail
        cmpi.l  #$0003FFFC,d0
        bhi.s   bvp_ldp_fail
        move.l  bvp_pending_ptr,a0
        move.l  bulk_data_ptr,a1
        move.l  d0,d1
bvp_ldp_copy:
        move.b  (a0)+,(a1)+
        subq.l  #1,d1
        bne.s   bvp_ldp_copy
        move.l  bvp_pending_len,d0
        move.l  d0,t23_last_read
        ; Stage 3: MintVID hands us one access unit at a time. Preserve the
        ; public FRAME_START/FRAME_END/KEY bits; their values match MMAL's
        ; buffer-header flags (2/4/8). CONFIG is handled before this path.
        move.l  bvp_pending_flags,d0
        andi.l  #$0000000E,d0
        move.l  d0,current_h264_flags
        moveq   #0,d0
        rts
bvp_ldp_fail:
        moveq   #1,d0
        rts

; N30: common quiet RX pump used by the library-mode pipelined video path.
; It intentionally keeps the exact VPr8 dispatcher and ownership rules.
;
; bvp_wait_video_submit_ready:
;   wait until the globally serialized VIDEO BULK_TX transport is idle AND
;   fewer than INPUT_POOL_COUNT normal H264 slots are VideoCore-owned.
;
; bvp_wait_video_bulk_done:
;   after publishing one AU, wait only for BULK_TX_DONE.  A matching
;   BUFFER_TO_HOST may arrive in the same poll pass and is consumed normally,
;   but it is NOT required before returning to MintVID.
;
; Both helpers return with shared VCHIQ RAM CPU-owned.
bvp_wait_video_submit_ready:
        jsr     p96w_wait_budget          ; P96W35: max ~6 s in the window
bvp_wvsr_check_now:
        tst.l   input_bulk_pending
        bne.s   bvp_wvsr_need_poll
        ; N79P96G: direct-HVS N79 had no host BULK_RX, but P96 does.
        ; Match the proven mkvr7 rule: active output RX blocks any new TX.
        tst.l   output_bulk_queued
        bne.s   bvp_wvsr_need_poll
        move.l  input_in_use_count,d0
        cmpi.l  #INPUT_POOL_COUNT,d0
        bcs.s   bvp_wvsr_ok
bvp_wvsr_need_poll:
        ; Entry from the public library ABI is CPU-owned. Hand shared VCHIQ
        ; RAM back to DMA/VideoCore before waiting for a callback to arrive.
        jsr     dma_pre_all
bvp_wvsr_poll:
        move.l  #1,p96w_where        ; P96W33 hang marker
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     60(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bls.s   bvp_wvsr_no_msg
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   bvp_wvsr_fail_map
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,bulk_rx_size
        jsr     v9g_h19_dispatch
        tst.l   v10h_error_seen
        bne.w   bvp_wvsr_fail_backend
        tst.l   input_bulk_pending
        bne.s   bvp_wvsr_more
        tst.l   output_bulk_queued
        bne.s   bvp_wvsr_more
        move.l  input_in_use_count,d0
        cmpi.l  #INPUT_POOL_COUNT,d0
        bcs.s   bvp_wvsr_ok
bvp_wvsr_more:
        jsr     dma_pre_all
        bra.s   bvp_wvsr_tick
bvp_wvsr_no_msg:
        tst.l   input_bulk_pending
        bne.s   bvp_wvsr_not_ready
        tst.l   output_bulk_queued
        bne.s   bvp_wvsr_not_ready
        move.l  input_in_use_count,d0
        cmpi.l  #INPUT_POOL_COUNT,d0
        bcs.s   bvp_wvsr_ok
bvp_wvsr_not_ready:
        jsr     dma_pre_all
bvp_wvsr_tick:
        subq.l  #1,bvp_wait_count
        jsr     p96w12_kick_maybe
        tst.l   bvp_wait_count            ; P96W12: flags for loop test
        bne.w   bvp_wvsr_poll
        jsr     dma_post_all
        jsr     p96w_dump_state
        lea     n21_msg_submit_timeout,a1
        jsr     n12_log
        moveq   #BVPERR_TIMEOUT,d0
        rts
bvp_wvsr_fail_map:
        lea     n21_msg_submit_map_fail,a1
        jsr     n12_log
        moveq   #BVPERR_BACKEND,d0
        rts
bvp_wvsr_fail_backend:
        lea     n21_msg_submit_dispatch_err,a1
        jsr     n12_log
        move.l  v10h_error_status,d0
        jsr     n13_log_dispatch_status
        moveq   #BVPERR_BACKEND,d0
        rts
bvp_wvsr_ok:
        moveq   #BVP_OK,d0
        rts

bvp_wait_video_bulk_done:
        jsr     p96w_wait_budget          ; P96W35: max ~6 s in the window
bvp_wvbd_loop:
        move.l  #2,p96w_where        ; P96W33 hang marker
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     60(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bls.s   bvp_wvbd_check
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   bvp_wvbd_fail_map
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,bulk_rx_size
        jsr     v9g_h19_dispatch
        tst.l   v10h_error_seen
        bne.w   bvp_wvbd_fail_backend
bvp_wvbd_check:
        tst.l   input_bulk_pending
        beq.s   bvp_wvbd_ok
        jsr     p96w41_rescue_rx          ; P96W41: break TX/RX standoff
        tst.l   v10h_error_seen
        bne.w   bvp_wvbd_fail_backend
        jsr     dma_pre_all
        subq.l  #1,bvp_wait_count
        jsr     p96w12_kick_maybe
        tst.l   bvp_wait_count            ; P96W12: flags for loop test
        bne.w   bvp_wvbd_loop
        jsr     dma_post_all
        jsr     p96w_dump_state
        lea     n21_msg_bulk_timeout,a1
        jsr     n12_log
        moveq   #BVPERR_TIMEOUT,d0
        rts
bvp_wvbd_fail_map:
        lea     n21_msg_bulk_map_fail,a1
        jsr     n12_log
        moveq   #BVPERR_BACKEND,d0
        rts
bvp_wvbd_fail_backend:
        lea     n21_msg_bulk_dispatch_err,a1
        jsr     n12_log
        move.l  v10h_error_status,d0
        jsr     n13_log_dispatch_status
        moveq   #BVPERR_BACKEND,d0
        rts
bvp_wvbd_ok:
        moveq   #BVP_OK,d0
        rts

; Full input-ownership drain helper. N65 no longer calls this after every AU;
; it remains available for diagnostics/teardown where complete ownership is
; explicitly required. Shared RAM is DMA-owned on entry and CPU-owned on return.
bvp_wait_input_return:
        ; N19: no persistent success-path trace here; errors remain persistent.
        move.l  #$00040000,bvp_wait_count
bvp_wir_loop:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     60(a0),a0              ; MASTER_TXPOS = MASTER_BASE(32)+28
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bls.s   bvp_wir_no_msg
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   bvp_wir_fail_map
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,bulk_rx_size

        ; N19: skip per-RX diagnostic logger; dispatcher itself is unchanged.
        jsr     v9g_h19_dispatch
        tst.l   v10h_error_seen
        beq.s   bvp_wir_after_dispatch_ok
        lea     n13_msg_v_dispatch_err,a1
        jsr     n12_log
        move.l  v10h_error_status,d0
        jsr     n13_log_dispatch_status
        bra.w   bvp_wir_fail_backend
bvp_wir_after_dispatch_ok:
        tst.l   input_bulk_pending
        bne.s   bvp_wir_more
        tst.l   input_in_use_count
        beq.s   bvp_wir_ok
bvp_wir_more:
        jsr     dma_pre_all
        bra.s   bvp_wir_tick
bvp_wir_no_msg:
        tst.l   input_bulk_pending
        bne.s   bvp_wir_no_done
        tst.l   input_in_use_count
        beq.s   bvp_wir_ok
bvp_wir_no_done:
        jsr     dma_pre_all
bvp_wir_tick:
        subq.l  #1,bvp_wait_count
        bne.w   bvp_wir_loop
        jsr     dma_post_all
        lea     n13_msg_v_timeout,a1
        jsr     n12_log
        moveq   #BVPERR_TIMEOUT,d0
        rts

bvp_wir_fail_map:
        lea     n13_msg_v_map_fail,a1
        jsr     n12_log
        moveq   #BVPERR_BACKEND,d0
        rts

bvp_wir_fail_backend:
        moveq   #BVPERR_BACKEND,d0
        rts

bvp_wir_ok:
        moveq   #BVP_OK,d0
        rts

n13_trace_video_rx:
        movem.l d0-d4/a0-a2,-(sp)
        move.l  bulk_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_BULK_TX_DONE,d0
        beq.w   n13_rx_btx
        cmp.l   #VCHIQ_MSG_BULK_RX_DONE,d0
        beq.w   n13_rx_brx
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   n13_rx_other

        move.l  bulk_rx_size,d0
        cmpi.l  #24,d0
        bcs.w   n13_rx_data_short
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_BUFFER_TO_HOST,d0
        beq.w   n13_rx_bth
        cmp.l   #MMAL_EVENT_TO_HOST,d0
        beq.w   n13_rx_event
        lea     n13_msg_rx_data_other,a1
        jsr     n12_log
        bra.w   n13_rx_done

n13_rx_data_short:
        lea     n13_msg_rx_data_short,a1
        jsr     n12_log
        bra.w   n13_rx_done

n13_rx_event:
        lea     n13_msg_rx_event,a1
        jsr     n12_log
        bra.w   n13_rx_done

n13_rx_bth:
        move.l  bulk_rx_size,d0
        cmpi.l  #164,d0
        bcs.w   n13_rx_bth_short
        lea     44(a2),a0
        jsr     load_le32
        move.l  d0,d1

        move.l  d1,d2
        sub.l   #VPV47_AUDIO_CONTEXT_BASE,d2
        cmpi.l  #VPV47_AUDIO_SLOTS,d2
        bcs.w   n13_rx_bth_audio
        cmp.l   #VPV01_BUFFER_CONTEXT,d1
        beq.w   n13_rx_bth_audio_legacy
        cmp.l   #MMAL_EOS_BUFFER_CONTEXT,d1
        beq.w   n13_rx_bth_video_eos

        move.l  d1,d2
        sub.l   #MMAL_BUFFER_CONTEXT_BASE,d2
        bcs.s   n13_rx_bth_check_output
        cmpi.l  #INPUT_POOL_COUNT,d2
        bcs.w   n13_rx_bth_video_input

n13_rx_bth_check_output:
        move.l  d1,d2
        sub.l   #MMAL_OUTPUT_BUFFER_CONTEXT0,d2
        bcs.w   n13_rx_bth_other
        cmp.l   v10j_output_req_count,d2
        bcs.w   n13_rx_bth_video_output
        bra.w   n13_rx_bth_other

n13_rx_bth_audio:
        cmpi.l  #5,n79p96g_audio_trace_state
