n13_log_dispatch_status:
        jsr     p96w_log_err
        movem.l d0-d2/a1,-(sp)
        cmpi.l  #MMAL_SUCCESS,d0
        beq.w   n13_stat_success
        cmpi.l  #MMAL_ENOMEM,d0
        beq.w   n13_stat_enomem
        cmpi.l  #MMAL_ENOSPC,d0
        beq.w   n13_stat_enospc
        cmpi.l  #MMAL_EINVAL,d0
        beq.w   n13_stat_einval
        cmpi.l  #MMAL_ENOSYS,d0
        beq.w   n13_stat_enosys
        cmpi.l  #MMAL_ENOENT,d0
        beq.w   n13_stat_enoent
        cmpi.l  #MMAL_ENXIO,d0
        beq.w   n13_stat_enxio
        cmpi.l  #MMAL_EIO,d0
        beq.w   n13_stat_eio
        cmpi.l  #MMAL_ESPIPE,d0
        beq.w   n13_stat_espipe
        cmpi.l  #MMAL_ECORRUPT,d0
        beq.w   n13_stat_ecorrupt
        cmpi.l  #MMAL_ENOTREADY,d0
        beq.w   n13_stat_enotready
        cmpi.l  #MMAL_ECONFIG,d0
        beq.w   n13_stat_econfig
        cmpi.l  #MMAL_EISCONN,d0
        beq.w   n13_stat_eisconn
        cmpi.l  #MMAL_ENOTCONN,d0
        beq.w   n13_stat_enotconn
        cmpi.l  #MMAL_EAGAIN,d0
        beq.w   n13_stat_eagain
        cmpi.l  #MMAL_EFAULT,d0
        beq.w   n13_stat_efault
        cmpi.l  #$FFFFFFF0,d0
        beq.w   n13_stat_internal_generic
        cmpi.l  #$FFFFFFF1,d0
        beq.w   n13_stat_internal_badreply
        cmpi.l  #$FFFFFFF2,d0
        beq.w   n13_stat_internal_recycle
        cmpi.l  #$FFFFFFF3,d0
        beq.w   n13_stat_internal_requeue
        lea     n13_msg_status_unknown,a1
        bra.w   n13_stat_emit
