bvp_wait_eos:
        move.l  #$00040000,bvp_wait_count
bvp_we_loop:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     60(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bls.s   bvp_we_check
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.s   bvp_we_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,bulk_rx_size
        jsr     v9g_h19_dispatch
bvp_we_check:
        tst.l   eos_bulk_done
        beq.s   bvp_we_more
        tst.l   eos_return_seen
        beq.s   bvp_we_more
        ; N30: EOS may release normal decoder inputs that were intentionally
        ; still VideoCore-owned when CloseStream began. Teardown is safe only
        ; after every normal input context has returned too.
        tst.l   input_in_use_count
        bne.s   bvp_we_more
        move.l  input_return_total,d0
        cmp.l   input_bulk_total,d0
        beq.s   bvp_we_ok
bvp_we_more:
        jsr     dma_pre_all
        subq.l  #1,bvp_wait_count
        bne.w   bvp_we_loop
        jsr     dma_post_all
bvp_we_fail:
        moveq   #1,d0
        rts
bvp_we_ok:
        moveq   #0,d0
        rts

; Second-start persistent-VCHIQ path: v9f returns DMA-owned. Prepare exactly
; the same input pool as first start, but stop before BerryVP's file feeder.
bvp_prepare_second_stream:
        jsr     dma_post_all
        move.l  #$00001000,port_query_index
        clr.l   t30_frames_ptr
        clr.l   t30_chip_ptr
        clr.l   v9i_chip_alloc_base
        clr.l   t33_fast_ptr
        clr.l   t56_shadow_ptr
        jsr     h264_output_test
        rts

        section data,data
        cnop    0,2
