H264_MAX_DATA_LEN     equ INPUT_DATA_SIZE
TEST26_INPUT_TARGET   equ 0       ; TEST33: Anzahl Inputbloecke wird dynamisch gezaehlt
BULK_ALLOC_SIZE       equ INPUT_POOL_ALLOC_SIZE
BULK_DMA_SIZE         equ INPUT_DMA_SPAN
PAGELIST_WRITE      equ 0
PAGELIST_READ       equ 1

; Amiga Exec CachePreDMA/PostDMA flag:
; DMA device reads FROM RAM (used for pagelist/control memory).
DMA_ReadFromRAM     equ 8

; TEST19 output buffer
MMAL_OUTPUT_BUFFER_CONTEXT0 equ $19000002
MMAL_OUTPUT_BUFFER_CONTEXT1 equ $19000003
MMAL_OUTPUT_BUFFER_CONTEXT  equ MMAL_OUTPUT_BUFFER_CONTEXT0
MMAL_EOS_BUFFER_CONTEXT    equ $19E00001
MMAL_BUFFER_FLAG_EOS       equ 1
MMAL_BUFFER_FLAG_FRAME_START equ 2
MMAL_BUFFER_FLAG_FRAME_END   equ 4
MMAL_BUFFER_FLAG_CONFIG      equ 32
MMAL_BUFFER_FLAG_FRAME       equ 6
MMAL_ES_FORMAT_FLAG_FRAMED     equ 1
H264_CODEC_CONFIG_MAX          equ 128
H264_PROBE_SIZE                equ 4096
EOS_BULK_LEN               equ 8
OUTPUT_SLOT_STRIDE         equ $007F9000 ; V40J: one max 1920x1088 BGRA slot incl. alignment/guard
OUTPUT_POOL_MAX            equ 20        ; V10P: host output pool cap
OUTPUT_ALLOC_EXTRA         equ $00003000 ; alignment + one serialized pagelist + guard slack
OUTPUT_MAX_DMA             equ $007F8000 ; V40J: 1920x1088 aligned BGRA maximum
V6_MAX_SRC_W               equ 1920
V6_MAX_SRC_H               equ 1080
V12_MAX_ALIGNED_H           equ 1088
MMAL_ENCODING_I420         equ $30323449
MMAL_ENCODING_RGBA         equ $41424752 ; bytes R,G,B,A in host memory
MMAL_ENCODING_BGRA         equ $41524742 ; bytes B,G,R,A in host memory
MMAL_ENCODING_BGR24        equ $33524742 ; bytes B,G,R in host memory
MMAL_ENCODING_OPAQUE       equ $5651504F        ; 'OPQV' - VideoCore opaque/zero-copy frame handle

MMAL_BUFFER_DATA_COOKIE equ $1700DA7A

MMAL_PORT_CONTROL     equ 1
MMAL_PORT_INPUT       equ 2
MMAL_PORT_OUTPUT      equ 3
MMAL_PORT_CLOCK       equ 4
MMAL_ES_AUDIO         equ 2
MMAL_ES_VIDEO         equ 3
MMAL_ENCODING_H264    equ $34363248
MMAL_ENCODING_MP4V    equ $5634504D      ; 'MP4V'
MMAL_ENCODING_H263    equ $33363248      ; 'H263'
MMAL_ENCODING_MJPEG   equ $47504A4D      ; 'MJPG'
MMAL_ENCODING_MP1V    equ $5631504D      ; 'MP1V'
MMAL_ENCODING_MP2V    equ $5632504D      ; 'MP2V'
MMAL_ENCODING_WVC1    equ $31435657      ; 'WVC1'
; VPv01: MMAL_ENCODING_PCM_SIGNED_LE = MMAL_FOURCC('p','c','m','s')
MMAL_ENCODING_PCM_SIGNED_LE equ $736d6370
MMAL_PARAMETER_GROUP_AUDIO equ $00030000
MMAL_PARAMETER_AUDIO_DESTINATION equ MMAL_PARAMETER_GROUP_AUDIO
; VPv124: MMAL clock port parameter IDs (official Raspberry Pi userland).
MMAL_PARAMETER_GROUP_CLOCK equ $00040000
MMAL_PARAMETER_CLOCK_REFERENCE equ MMAL_PARAMETER_GROUP_CLOCK
MMAL_PARAMETER_CLOCK_ACTIVE equ MMAL_PARAMETER_GROUP_CLOCK+$0001
MMAL_PARAMETER_CLOCK_SCALE equ MMAL_PARAMETER_GROUP_CLOCK+$0002
MMAL_PARAMETER_CLOCK_TIME equ MMAL_PARAMETER_GROUP_CLOCK+$0003
MMAL_PARAMETER_CLOCK_ENABLE_BUFFER_INFO equ MMAL_PARAMETER_GROUP_CLOCK+$0007
MMAL_INPUT_USERDATA   equ $24681357
MMAL_TEST_CONTEXT    equ $12345678
MMAL_COMP_CONTEXT    equ $87654321
MMAL_CLIENT_COMPONENT equ $13572468

; ---- Pi3 MMIO mapped by Emu68 /soc/ranges ----
MBOX_READ       equ $F200B880
MBOX_STATUS     equ $F200B898
MBOX_WRITE      equ $F200B8A0

; VCHIQ node is bus 7e00b840 -> Emu68 f200b840.
; RusPiRo rings VC BELL2 at physical b848 => Emu68 f200b848.
VCHIQ_BELL2     equ $F200B848

MBOX_TX_FULL    equ $80000000
MBOX_RX_EMPTY   equ $40000000
MBOX_PROPERTY   equ 8

TIMEOUT         equ $00400000
POLL_COUNT      equ 100
VPV183_LARGE_POLL_COUNT equ 800
MKVR7_C_SCHED_STALL_US equ 5000000 ; true-C wall-clock stall window
VPV005R2_T_FAST_POLL_COUNT equ 4096 ; T:/restart fast-forward: tolerate saturated decoder without false timeout
VPV183_LARGE_FRAME_THRESHOLD equ $00080000
V10_CLEANUP_POLL_COUNT equ 4096
POLL_DELAY      equ $00020000
V5_SPIN_TIMEOUT equ $04000000   ; watchdog only for formerly unbounded RGB/VBlank waits
INTB_VERTB      equ 5
NT_INTERRUPT    equ 2

start:
        ; V40 keeps the original CLI bytes alive while the player engine may
        ; perform a complete cleanup + restart cycle after a size request.
        move.l  d0,v32r_root_cli_len
        move.l  a0,v32r_root_cli_ptr
        clr.l   v32r_restart_cycle
        clr.l   v32r_restart_armed
        clr.l   v32r_fastforward
        clr.l   v32r_restart_count
        clr.l   mkvr7_log_mode
        clr.l   mkvr7_log_handle
        clr.l   mkvr7_log_started
        clr.b   mkvr7_log_name
        ; mkvr7 resume/bookmark state is per CLI invocation and deliberately
        ; survives an internal P96->C restart cycle.
        clr.l   mkvr7_resume_pending
        clr.l   mkvr7_resume_pts_ticks
        clr.l   mkvr7_resume_mode
        clr.l   mkvr7_natural_eos
        clr.b   mkvr7_resume_name
        ; VPr8: user-facing resume-from-.t state.  Kept across an internal
        ; P96->C restart, but reset for every new CLI invocation.
        clr.l   vpr8_resume_requested
        clr.l   vpr8_resume_loaded
        clr.l   vpr8_resume_time_secs
        clr.l   vpr8_resume_file_mode
        clr.l   vpr8_cli_w_explicit

v32r_process_loop:
        move.l  v32r_root_cli_len,d0
        move.l  v32r_root_cli_ptr,a0
        bsr     h264rgb_main
        tst.l   v32r_restart_armed
        beq.s   v32r_process_done
        clr.l   v32r_restart_armed
        move.l  #1,v32r_restart_cycle
        addq.l  #1,v32r_restart_count
        bra.w   v32r_process_loop
v32r_process_done:
        rts

; --------------------------------------------------------------------
; h264rgb V1 command-line parser
;
; AmigaDOS CLI entry: D0 = command line length, A0 = command line bytes.
; Copies the first argument into t23_file_name. Quoted paths are accepted.
; Return D0=0 on success, D0=1 if no usable filename was supplied.
; --------------------------------------------------------------------
h264rgb_parse_arg:
        movem.l d1-d3/a0-a1,-(sp)

        move.l  h264rgb_cli_ptr,a0
        move.l  h264rgb_cli_len,d0
        tst.l   d0
        beq.w   h264rgb_parse_fail

h264rgb_skip_ws:
        tst.l   d0
        beq.w   h264rgb_parse_fail
        move.b  (a0),d1
        cmpi.b  #$20,d1
        beq.s   h264rgb_skip_one
        cmpi.b  #9,d1
        bne.s   h264rgb_arg_begin
h264rgb_skip_one:
        addq.l  #1,a0
        subq.l  #1,d0
        bra.s   h264rgb_skip_ws

h264rgb_arg_begin:
        lea     t23_file_name,a1
        clr.l   d3
        moveq   #0,d2
        cmpi.b  #$22,d1
        bne.s   h264rgb_copy_loop
        moveq   #1,d2
        addq.l  #1,a0
        subq.l  #1,d0

h264rgb_copy_loop:
        tst.l   d0
        beq.s   h264rgb_copy_done
        move.b  (a0)+,d1
        subq.l  #1,d0

        tst.b   d2
        beq.s   h264rgb_check_plain_end
        cmpi.b  #$22,d1
        beq.s   h264rgb_copy_done
        bra.s   h264rgb_store_char

h264rgb_check_plain_end:
        cmpi.b  #$20,d1
        beq.s   h264rgb_copy_done
        cmpi.b  #9,d1
        beq.s   h264rgb_copy_done
        cmpi.b  #10,d1
        beq.s   h264rgb_copy_done
        cmpi.b  #13,d1
        beq.s   h264rgb_copy_done

h264rgb_store_char:
        cmpi.l  #255,d3
        bcc.s   h264rgb_parse_fail
        move.b  d1,(a1)+
        addq.l  #1,d3
        bra.s   h264rgb_copy_loop

h264rgb_copy_done:
        tst.l   d3
        beq.s   h264rgb_parse_fail
        clr.b   (a1)
        moveq   #0,d0
        bra.s   h264rgb_parse_done

h264rgb_parse_fail:
        moveq   #1,d0
h264rgb_parse_done:
        movem.l (sp)+,d1-d3/a0-a1
        rts

; --------------------------------------------------------------------
; mkvr7 optional logging selector.
;   no token       -> mode 0: quiet, only FEHLER/ERROR/ABBRUCH to Shell
;   log            -> mode 1: complete diagnostics to Shell
;   log:<filename> -> mode 2: complete diagnostics to file only
; Token may appear anywhere after the movie filename.
; Return D0=0 OK/no token, D0=1 malformed log: token.
; --------------------------------------------------------------------
mkvr7_parse_log_arg:
        movem.l d1-d7/a0-a2,-(sp)
        clr.l   mkvr7_log_mode
        clr.b   mkvr7_log_name
        move.l  h264rgb_cli_ptr,a0
        move.l  h264rgb_cli_len,d7
        tst.l   d7
        beq.w   mkvr7_pl_ok

; Skip leading whitespace.
mkvr7_pl_skip0:
        tst.l   d7
        beq.w   mkvr7_pl_ok
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.s   mkvr7_pl_skip0_one
        cmpi.b  #9,d0
        bne.s   mkvr7_pl_file
mkvr7_pl_skip0_one:
        addq.l  #1,a0
        subq.l  #1,d7
        bra.s   mkvr7_pl_skip0

; Skip first argument (movie filename), honoring quotes.
mkvr7_pl_file:
        moveq   #0,d6
        cmpi.b  #$22,d0
        bne.s   mkvr7_pl_file_loop
        moveq   #1,d6
        addq.l  #1,a0
        subq.l  #1,d7
mkvr7_pl_file_loop:
        tst.l   d7
        beq.w   mkvr7_pl_ok
        move.b  (a0)+,d0
        subq.l  #1,d7
        tst.b   d6
        beq.s   mkvr7_pl_file_plain
        cmpi.b  #$22,d0
        beq.s   mkvr7_pl_next
        bra.s   mkvr7_pl_file_loop
mkvr7_pl_file_plain:
        cmpi.b  #$20,d0
        beq.s   mkvr7_pl_next
        cmpi.b  #9,d0
        beq.s   mkvr7_pl_next
        cmpi.b  #10,d0
        beq.w   mkvr7_pl_ok
        cmpi.b  #13,d0
        beq.w   mkvr7_pl_ok
        bra.s   mkvr7_pl_file_loop

; Scan each remaining whitespace-delimited token.
mkvr7_pl_next:
mkvr7_pl_skip_ws:
        tst.l   d7
        beq.w   mkvr7_pl_ok
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.s   mkvr7_pl_ws_one
        cmpi.b  #9,d0
        beq.s   mkvr7_pl_ws_one
        cmpi.b  #10,d0
        beq.w   mkvr7_pl_ok
        cmpi.b  #13,d0
        beq.w   mkvr7_pl_ok
        bra.s   mkvr7_pl_token
mkvr7_pl_ws_one:
        addq.l  #1,a0
        subq.l  #1,d7
        bra.s   mkvr7_pl_skip_ws

mkvr7_pl_token:
        move.l  a0,a2
        moveq   #0,d5
mkvr7_pl_count:
        cmp.l   d7,d5
        bcc.s   mkvr7_pl_count_done
        move.b  0(a2,d5.l),d0
        cmpi.b  #$20,d0
        beq.s   mkvr7_pl_count_done
        cmpi.b  #9,d0
        beq.s   mkvr7_pl_count_done
        cmpi.b  #10,d0
        beq.s   mkvr7_pl_count_done
        cmpi.b  #13,d0
        beq.s   mkvr7_pl_count_done
        addq.l  #1,d5
        bra.s   mkvr7_pl_count
mkvr7_pl_count_done:
        cmpi.l  #3,d5
        bcs.s   mkvr7_pl_advance

        move.b  (a2),d0
        ori.b   #$20,d0
        cmpi.b  #'l',d0
        bne.s   mkvr7_pl_advance
        move.b  1(a2),d0
        ori.b   #$20,d0
        cmpi.b  #'o',d0
        bne.s   mkvr7_pl_advance
        move.b  2(a2),d0
        ori.b   #$20,d0
        cmpi.b  #'g',d0
        bne.s   mkvr7_pl_advance

        ; Exact "log" -> complete diagnostics to Shell.
        cmpi.l  #3,d5
        bne.s   mkvr7_pl_file_token
        move.l  #1,mkvr7_log_mode
        moveq   #0,d0
        bra.w   mkvr7_pl_done

mkvr7_pl_file_token:
        cmpi.b  #':',3(a2)
        bne.s   mkvr7_pl_advance          ; e.g. "logger" is not our token
        cmpi.l  #4,d5
        beq.s   mkvr7_pl_fail             ; "log:" without filename
        move.l  d5,d4
        subq.l  #4,d4
        cmpi.l  #255,d4
        bhi.s   mkvr7_pl_fail
        lea     mkvr7_log_name,a1
        lea     4(a2),a2
        move.l  d4,d3
mkvr7_pl_copy_name:
        tst.l   d3
        beq.s   mkvr7_pl_name_done
        move.b  (a2)+,(a1)+
        subq.l  #1,d3
        bra.s   mkvr7_pl_copy_name
mkvr7_pl_name_done:
        clr.b   (a1)
        move.l  #2,mkvr7_log_mode
        moveq   #0,d0
        bra.s   mkvr7_pl_done

mkvr7_pl_advance:
        add.l   d5,a0
        sub.l   d5,d7
        bra.w   mkvr7_pl_next

mkvr7_pl_fail:
        clr.l   mkvr7_log_mode
        clr.b   mkvr7_log_name
        moveq   #1,d0
        bra.s   mkvr7_pl_done
mkvr7_pl_ok:
        moveq   #0,d0
mkvr7_pl_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Open log:<filename>. First engine entry truncates/creates; an internal
; restart in the same CLI process reopens and appends to the same file.
; D0=0 success/not requested, D0=1 file could not be opened.
mkvr7_open_log:
        movem.l d1-d3/a0/a6,-(sp)
        clr.l   mkvr7_log_handle
        cmpi.l  #2,mkvr7_log_mode
        bne.s   mkvr7_open_log_ok
        move.l  a5,a6
        lea     mkvr7_log_name,a0
        move.l  a0,d1
        tst.l   mkvr7_log_started
        bne.s   mkvr7_open_log_old
        move.l  #MODE_NEWFILE,d2
        jsr     Open(a6)
        bra.s   mkvr7_open_log_have
mkvr7_open_log_old:
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        bne.s   mkvr7_open_log_seek_end
        ; If the previous file disappeared, create it again.
        lea     mkvr7_log_name,a0
        move.l  a0,d1
        move.l  #MODE_NEWFILE,d2
        jsr     Open(a6)
        bra.s   mkvr7_open_log_have
mkvr7_open_log_seek_end:
        move.l  d0,mkvr7_log_handle
        move.l  d0,d1
        moveq   #0,d2
        move.l  #OFFSET_END,d3
        jsr     Seek(a6)
        move.l  mkvr7_log_handle,d0
mkvr7_open_log_have:
        tst.l   d0
        beq.s   mkvr7_open_log_fail
        move.l  d0,mkvr7_log_handle
        move.l  #1,mkvr7_log_started
mkvr7_open_log_ok:
        moveq   #0,d0
        bra.s   mkvr7_open_log_done
mkvr7_open_log_fail:
        clr.l   mkvr7_log_handle
        clr.l   mkvr7_log_mode
        moveq   #1,d0
mkvr7_open_log_done:
        movem.l (sp)+,d1-d3/a0/a6
        rts

; Close/flush a persistent log file before dos.library is closed.
mkvr7_close_log:
        movem.l d0-d1/a6,-(sp)
        move.l  mkvr7_log_handle,d0
        beq.s   mkvr7_close_log_done
        move.l  vpv102_saved_dos_base,a6
        cmpa.l  #0,a6
        beq.s   mkvr7_close_log_forget
        move.l  d0,d1
        jsr     Flush(a6)
        move.l  mkvr7_log_handle,d1
        jsr     Close(a6)
mkvr7_close_log_forget:
        clr.l   mkvr7_log_handle
mkvr7_close_log_done:
        movem.l (sp)+,d0-d1/a6
        rts

; --------------------------------------------------------------------
; mkvr7 persistent movie resume bookmark.
;
; User stop (Esc/0, window close or Ctrl-C) captures the current Matroska
; video PTS immediately, before EOS/drain can advance/reset parser state.
; The value stored in <movie>.t is intentionally 30 seconds earlier so a
; later resume gives the viewer a short memory recap.  The actual DOS file
; I/O is deferred until after MMAL/VCHIQ cleanup.
;
; Text file format:
;   T:HH:MM:SS
;   W:10|25|50|75|C
; --------------------------------------------------------------------
mkvr7_capture_resume:
        movem.l d0-d2,-(sp)
        tst.l   mkvr7_resume_pending
        bne.s   mkvr7_capture_done
        tst.l   v10b_input_is_mkv
        beq.s   mkvr7_capture_done

        move.l  v10b_last_pts_ticks,d0
        tst.l   v10b_pts_valid
        bne.s   mkvr7_capture_have_pts
        moveq   #0,d0
mkvr7_capture_have_pts:
        ; 30-second recap, saturating at movie start.
        cmpi.l  #30000,d0
        bcs.s   mkvr7_capture_zero
        subi.l  #30000,d0
        bra.s   mkvr7_capture_store
mkvr7_capture_zero:
        moveq   #0,d0
mkvr7_capture_store:
        move.l  d0,mkvr7_resume_pts_ticks

        ; v32_fixed_mode follows the actually active presentation mode,
        ; including a live/internal switch to cinema (203).
        move.l  v32_fixed_mode,d1
        cmpi.l  #203,d1
        beq.s   mkvr7_capture_mode_ok
        cmpi.l  #10,d1
        beq.s   mkvr7_capture_mode_ok
        cmpi.l  #25,d1
        beq.s   mkvr7_capture_mode_ok
        cmpi.l  #50,d1
        beq.s   mkvr7_capture_mode_ok
        cmpi.l  #75,d1
        beq.s   mkvr7_capture_mode_ok
        ; Very early stop before fixed-mode setup: fall back to parsed CLI mode.
        move.l  v40j_cli_mode,d1
        cmpi.l  #203,d1
        beq.s   mkvr7_capture_mode_ok
        cmpi.l  #10,d1
        beq.s   mkvr7_capture_mode_ok
        cmpi.l  #25,d1
        beq.s   mkvr7_capture_mode_ok
        cmpi.l  #50,d1
        beq.s   mkvr7_capture_mode_ok
        cmpi.l  #75,d1
        beq.s   mkvr7_capture_mode_ok
        move.l  #25,d1
mkvr7_capture_mode_ok:
        move.l  d1,mkvr7_resume_mode
        move.l  #1,mkvr7_resume_pending
        clr.l   mkvr7_natural_eos
mkvr7_capture_done:
        movem.l (sp)+,d0-d2
        rts

; Build <movie>.t next to the movie.  t23_file_name is already unquoted.
mkvr7_build_resume_name:
        movem.l d0-d4/a0-a2,-(sp)
        lea     t23_file_name,a0
        lea     mkvr7_resume_name,a1
        suba.l  a2,a2                    ; A2 = last '.' after last path separator
        moveq   #0,d4                    ; copied length
mkvr7_name_copy:
        move.b  (a0)+,d0
        beq.s   mkvr7_name_end
        cmpi.l  #255,d4
        bcc.s   mkvr7_name_end
        move.b  d0,(a1)+
        addq.l  #1,d4
        cmpi.b  #':',d0
        beq.s   mkvr7_name_sep
        cmpi.b  #'/',d0
        beq.s   mkvr7_name_sep
        cmpi.b  #'.',d0
        bne.s   mkvr7_name_copy
        lea     -1(a1),a2
        bra.s   mkvr7_name_copy
mkvr7_name_sep:
        suba.l  a2,a2
        bra.s   mkvr7_name_copy
mkvr7_name_end:
        clr.b   (a1)
        cmpa.l  #0,a2
        bne.s   mkvr7_name_replace_ext
        ; No extension: append .t if there is room.
        cmpi.l  #252,d4
        bhi.s   mkvr7_name_done
        move.b  #'.',(a1)+
        move.b  #'t',(a1)+
        clr.b   (a1)
        bra.s   mkvr7_name_done
mkvr7_name_replace_ext:
        move.b  #'.',(a2)+
        move.b  #'t',(a2)+
        clr.b   (a2)
mkvr7_name_done:
        movem.l (sp)+,d0-d4/a0-a2
        rts

; A0=destination, D0=0..99. Appends two decimal digits, returns A0 advanced.
mkvr7_put_2digits:
        movem.l d1-d2,-(sp)
        move.l  d0,d1
        moveq   #10,d2
        divu.w  d2,d1
        moveq   #0,d0
        move.w  d1,d0
        addi.b  #'0',d0
        move.b  d0,(a0)+
        swap    d1
        addi.b  #'0',d1
        move.b  d1,(a0)+
        movem.l (sp)+,d1-d2
        rts

; Format resume payload and publish length in mkvr7_resume_len.
mkvr7_format_resume:
        movem.l d0-d5/a0-a1,-(sp)
        lea     mkvr7_resume_buf,a0
        move.b  #'T',(a0)+
        move.b  #':',(a0)+

        ; ticks are Matroska milliseconds. Store whole seconds only.
        move.l  mkvr7_resume_pts_ticks,d0
        move.l  #1000,d1
        divu.w  d1,d0
        moveq   #0,d5
        move.w  d0,d5                    ; D5 = whole seconds (movie-scale range)

        move.l  d5,d1
        move.l  #3600,d2
        divu.w  d2,d1
        moveq   #0,d3
        move.w  d1,d3                    ; hours
        cmpi.l  #99,d3
        bls.s   mkvr7_hours_ok
        moveq   #99,d3
mkvr7_hours_ok:
        swap    d1
        moveq   #0,d4
        move.w  d1,d4                    ; remainder seconds within hour
        move.l  d3,d0
        jsr     mkvr7_put_2digits
        move.b  #':',(a0)+

        move.l  d4,d1
        moveq   #60,d2
        divu.w  d2,d1
        moveq   #0,d0
        move.w  d1,d0                    ; minutes
        jsr     mkvr7_put_2digits
        move.b  #':',(a0)+
        swap    d1
        moveq   #0,d0
        move.w  d1,d0                    ; seconds
        jsr     mkvr7_put_2digits
        move.b  #10,(a0)+

        move.b  #'W',(a0)+
        move.b  #':',(a0)+
        move.l  mkvr7_resume_mode,d0
        cmpi.l  #203,d0
        beq.s   mkvr7_format_wc
        cmpi.l  #10,d0
        beq.s   mkvr7_format_w10
        cmpi.l  #50,d0
        beq.s   mkvr7_format_w50
        cmpi.l  #75,d0
        beq.s   mkvr7_format_w75
        ; default / 25
        move.b  #'2',(a0)+
        move.b  #'5',(a0)+
        bra.s   mkvr7_format_w_done
mkvr7_format_w10:
        move.b  #'1',(a0)+
        move.b  #'0',(a0)+
        bra.s   mkvr7_format_w_done
mkvr7_format_w50:
        move.b  #'5',(a0)+
        move.b  #'0',(a0)+
        bra.s   mkvr7_format_w_done
mkvr7_format_w75:
        move.b  #'7',(a0)+
        move.b  #'5',(a0)+
        bra.s   mkvr7_format_w_done
mkvr7_format_wc:
        move.b  #'C',(a0)+
mkvr7_format_w_done:
        move.b  #10,(a0)+
        clr.b   (a0)
        move.l  a0,d0
        lea     mkvr7_resume_buf,a1
        move.l  a1,d1
        sub.l   d1,d0
        move.l  d0,mkvr7_resume_len
        movem.l (sp)+,d0-d5/a0-a1
        rts

; Commit a captured bookmark, or remove a stale bookmark after natural EOS.
; Errors while writing are user-visible even in quiet mode via the word FEHLER.
mkvr7_commit_resume:
        movem.l d0-d4/a0-a2/a6,-(sp)
        tst.l   mkvr7_resume_pending
        bne.s   mkvr7_commit_write
        tst.l   mkvr7_natural_eos
        beq.w   mkvr7_commit_done
        jsr     mkvr7_build_resume_name
        move.l  vpv102_saved_dos_base,a6
        cmpa.l  #0,a6
        beq.s   mkvr7_commit_clear_natural
        lea     mkvr7_resume_name,a0
        move.l  a0,d1
        jsr     DosDeleteFile(a6)
mkvr7_commit_clear_natural:
        clr.l   mkvr7_natural_eos
        bra.w   mkvr7_commit_done

mkvr7_commit_write:
        jsr     mkvr7_build_resume_name
        jsr     mkvr7_format_resume
        move.l  vpv102_saved_dos_base,a6
        cmpa.l  #0,a6
        beq.s   mkvr7_commit_fail
        lea     mkvr7_resume_name,a0
        move.l  a0,d1
        move.l  #MODE_NEWFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.s   mkvr7_commit_fail
        move.l  d0,d4
        move.l  d4,d1
        lea     mkvr7_resume_buf,a0
        move.l  a0,d2
        move.l  mkvr7_resume_len,d3
        jsr     Write(a6)
        move.l  d0,mkvr7_resume_io
        move.l  d4,d1
        jsr     Close(a6)
        move.l  mkvr7_resume_io,d0
        cmp.l   mkvr7_resume_len,d0
        bne.s   mkvr7_commit_fail
        lea     msg_mkvr7_resume_saved,a1
        move.l  #msg_mkvr7_resume_saved_end-msg_mkvr7_resume_saved,d3
        jsr     print
        clr.l   mkvr7_resume_pending
        clr.l   mkvr7_natural_eos
        bra.s   mkvr7_commit_done
mkvr7_commit_fail:
        lea     msg_mkvr7_resume_fail,a1
        move.l  #msg_mkvr7_resume_fail_end-msg_mkvr7_resume_fail,d3
        jsr     print
        clr.l   mkvr7_resume_pending
        clr.l   mkvr7_natural_eos
mkvr7_commit_done:
        movem.l (sp)+,d0-d4/a0-a2/a6
        rts

; ====================================================================
; VPr8 - explicit resume command (R / RESUME).
;
; The .t file is still written by the proven mkvr7 bookmark path.  VPr8 only
; adds the inverse operation at process start:
;   VPr8 <movie.mkv> R
;   VPr8 <movie.mkv> resume
;
; The token may appear anywhere after the filename.  The loaded values are
; defaults only: an explicit CLI T: overrides the stored T:, and an explicit
; CLI W: (or legacy first size token) overrides the stored W:.
; ====================================================================

; Scan remaining CLI tokens for exact R or RESUME (case-insensitive).
; D0=0 always; result in vpr8_resume_requested.
vpr8_parse_resume_arg:
        movem.l d1-d7/a0-a2,-(sp)
        clr.l   vpr8_resume_requested
        move.l  h264rgb_cli_ptr,a0
        move.l  h264rgb_cli_len,d7
        tst.l   d7
        beq.w   vpr8_pr_done

vpr8_pr_skip0:
        tst.l   d7
        beq.w   vpr8_pr_done
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.s   vpr8_pr_skip0_one
        cmpi.b  #9,d0
        bne.s   vpr8_pr_file
vpr8_pr_skip0_one:
        addq.l  #1,a0
        subq.l  #1,d7
        bra.s   vpr8_pr_skip0

; Skip filename, honoring quotes.
vpr8_pr_file:
        moveq   #0,d6
        cmpi.b  #$22,d0
        bne.s   vpr8_pr_file_loop
        moveq   #1,d6
        addq.l  #1,a0
        subq.l  #1,d7
vpr8_pr_file_loop:
        tst.l   d7
        beq.w   vpr8_pr_done
        move.b  (a0)+,d0
        subq.l  #1,d7
        tst.b   d6
        beq.s   vpr8_pr_file_plain
        cmpi.b  #$22,d0
        beq.s   vpr8_pr_next
        bra.s   vpr8_pr_file_loop
vpr8_pr_file_plain:
        cmpi.b  #$20,d0
        beq.s   vpr8_pr_next
        cmpi.b  #9,d0
        beq.s   vpr8_pr_next
        cmpi.b  #10,d0
        beq.w   vpr8_pr_done
        cmpi.b  #13,d0
        beq.w   vpr8_pr_done
        bra.s   vpr8_pr_file_loop

vpr8_pr_next:
vpr8_pr_skip_ws:
        tst.l   d7
        beq.w   vpr8_pr_done
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.s   vpr8_pr_ws_one
        cmpi.b  #9,d0
        beq.s   vpr8_pr_ws_one
        cmpi.b  #10,d0
        beq.w   vpr8_pr_done
        cmpi.b  #13,d0
        beq.w   vpr8_pr_done
        bra.s   vpr8_pr_token
vpr8_pr_ws_one:
        addq.l  #1,a0
        subq.l  #1,d7
        bra.s   vpr8_pr_skip_ws

vpr8_pr_token:
        move.l  a0,a2
        moveq   #0,d5
vpr8_pr_count:
        cmp.l   d7,d5
        bcc.s   vpr8_pr_count_done
        move.b  0(a2,d5.l),d0
        cmpi.b  #$20,d0
        beq.s   vpr8_pr_count_done
        cmpi.b  #9,d0
        beq.s   vpr8_pr_count_done
        cmpi.b  #10,d0
        beq.s   vpr8_pr_count_done
        cmpi.b  #13,d0
        beq.s   vpr8_pr_count_done
        addq.l  #1,d5
        bra.s   vpr8_pr_count
vpr8_pr_count_done:
        cmpi.l  #1,d5
        bne.s   vpr8_pr_try_resume
        move.b  (a2),d0
        ori.b   #$20,d0
        cmpi.b  #'r',d0
        bne.s   vpr8_pr_advance
        move.l  #1,vpr8_resume_requested
        bra.s   vpr8_pr_advance

vpr8_pr_try_resume:
        cmpi.l  #6,d5
        bne.s   vpr8_pr_advance
        moveq   #0,d4
vpr8_pr_resume_loop:
        move.b  0(a2,d4.l),d0
        ori.b   #$20,d0
        lea     vpr8_resume_word,a1
        cmp.b   0(a1,d4.l),d0
        bne.s   vpr8_pr_advance
        addq.l  #1,d4
        cmpi.l  #6,d4
        bcs.s   vpr8_pr_resume_loop
        move.l  #1,vpr8_resume_requested

vpr8_pr_advance:
        add.l   d5,a0
        sub.l   d5,d7
        bra.w   vpr8_pr_next

vpr8_pr_done:
        moveq   #0,d0
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Read and parse <movie>.t.  Returns:
;   D0=0 success / not requested
;   D0=1 requested but file missing/open failed
;   D0=2 requested but read/content invalid
vpr8_load_resume_file:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpr8_resume_requested
        beq.w   vpr8_lrf_ok
        tst.l   vpr8_resume_loaded
        bne.w   vpr8_lrf_ok

        jsr     mkvr7_build_resume_name
        move.l  a5,a6
        lea     mkvr7_resume_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   vpr8_lrf_missing
        move.l  d0,d6

        move.l  d6,d1
        lea     mkvr7_resume_buf,a0
        move.l  a0,d2
        move.l  #31,d3
        jsr     Read(a6)
        move.l  d0,d7
        move.l  d6,d1
        jsr     Close(a6)
        tst.l   d7
        ble.w   vpr8_lrf_invalid
        cmpi.l  #31,d7
        bhi.w   vpr8_lrf_invalid
        lea     mkvr7_resume_buf,a0
        adda.l  d7,a0
        clr.b   (a0)
        lea     mkvr7_resume_buf,a0

        ; Strictly parse the format written by mkvr7_format_resume:
        ; T:HH:MM:SS\nW:10|25|50|75|C\n  (CRLF also accepted).
        move.l  d7,d6
        cmpi.l  #10,d6
        bcs.w   vpr8_lrf_invalid
        move.b  (a0)+,d0
        ori.b   #$20,d0
        cmpi.b  #'t',d0
        bne.w   vpr8_lrf_invalid
        cmpi.b  #':',(a0)+
        bne.w   vpr8_lrf_invalid
        subq.l  #2,d6

        ; HH
        jsr     vpr8_parse_2digits
        tst.l   d1
        bne.w   vpr8_lrf_invalid
        move.l  d0,d4                    ; hours
        subq.l  #2,d6
        tst.l   d6
        beq.w   vpr8_lrf_invalid
        cmpi.b  #':',(a0)+
        bne.w   vpr8_lrf_invalid
        subq.l  #1,d6
        ; MM
        jsr     vpr8_parse_2digits
        tst.l   d1
        bne.w   vpr8_lrf_invalid
        cmpi.l  #59,d0
        bhi.w   vpr8_lrf_invalid
        move.l  d0,d5                    ; minutes
        subq.l  #2,d6
        tst.l   d6
        beq.w   vpr8_lrf_invalid
        cmpi.b  #':',(a0)+
        bne.w   vpr8_lrf_invalid
        subq.l  #1,d6
        ; SS
        jsr     vpr8_parse_2digits
        tst.l   d1
        bne.w   vpr8_lrf_invalid
        cmpi.l  #59,d0
        bhi.w   vpr8_lrf_invalid
        move.l  d0,d3                    ; seconds
        subq.l  #2,d6

        move.l  d4,d0
        mulu.w  #3600,d0
        move.l  d5,d1
        mulu.w  #60,d1
        add.l   d1,d0
        add.l   d3,d0
        move.l  d0,vpr8_resume_time_secs

        ; End of first line: LF or CRLF.
        jsr     vpr8_consume_line_end
        tst.l   d0
        bne.w   vpr8_lrf_invalid

        cmpi.l  #3,d6
        bcs.w   vpr8_lrf_invalid
        move.b  (a0)+,d0
        ori.b   #$20,d0
        cmpi.b  #'w',d0
        bne.w   vpr8_lrf_invalid
        cmpi.b  #':',(a0)+
        bne.w   vpr8_lrf_invalid
        subq.l  #2,d6
        tst.l   d6
        beq.w   vpr8_lrf_invalid

        move.b  (a0),d0
        ori.b   #$20,d0
        cmpi.b  #'c',d0
        bne.s   vpr8_lrf_w_numeric
        addq.l  #1,a0
        subq.l  #1,d6
        move.l  #203,vpr8_resume_file_mode
        bra.s   vpr8_lrf_w_done

vpr8_lrf_w_numeric:
        cmpi.l  #2,d6
        bcs.w   vpr8_lrf_invalid
        jsr     vpr8_parse_2digits
        tst.l   d1
        bne.w   vpr8_lrf_invalid
        subq.l  #2,d6
        cmpi.l  #10,d0
        beq.s   vpr8_lrf_w_store
        cmpi.l  #25,d0
        beq.s   vpr8_lrf_w_store
        cmpi.l  #50,d0
        beq.s   vpr8_lrf_w_store
        cmpi.l  #75,d0
        bne.w   vpr8_lrf_invalid
vpr8_lrf_w_store:
        move.l  d0,vpr8_resume_file_mode
vpr8_lrf_w_done:
        ; Permit only trailing CR/LF after W:.
vpr8_lrf_tail:
        tst.l   d6
        beq.s   vpr8_lrf_valid
        move.b  (a0)+,d0
        subq.l  #1,d6
        cmpi.b  #10,d0
        beq.s   vpr8_lrf_tail
        cmpi.b  #13,d0
        beq.s   vpr8_lrf_tail
        bra.w   vpr8_lrf_invalid

vpr8_lrf_valid:
        move.l  #1,vpr8_resume_loaded
        moveq   #0,d0
        bra.s   vpr8_lrf_done
vpr8_lrf_ok:
        moveq   #0,d0
        bra.s   vpr8_lrf_done
vpr8_lrf_missing:
        moveq   #1,d0
        bra.s   vpr8_lrf_done
vpr8_lrf_invalid:
        clr.l   vpr8_resume_loaded
        moveq   #2,d0
vpr8_lrf_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; A0 points at two ASCII digits. D0=value, D1=0 OK/1 fail, A0 advanced.
vpr8_parse_2digits:
        moveq   #1,d1
        moveq   #0,d0
        move.b  (a0)+,d0
        cmpi.b  #'0',d0
        bcs.s   vpr8_p2_done
        cmpi.b  #'9',d0
        bhi.s   vpr8_p2_done
        subi.b  #'0',d0
        andi.l  #$000000FF,d0
        mulu.w  #10,d0
        moveq   #0,d2
        move.b  (a0)+,d2
        cmpi.b  #'0',d2
        bcs.s   vpr8_p2_done
        cmpi.b  #'9',d2
        bhi.s   vpr8_p2_done
        subi.b  #'0',d2
        andi.l  #$000000FF,d2
        add.l   d2,d0
        moveq   #0,d1
vpr8_p2_done:
        rts

; Consume LF or CRLF from A0/D6. D0=0 OK, 1 invalid.
vpr8_consume_line_end:
        moveq   #1,d0
        tst.l   d6
        beq.s   vpr8_cle_done
        cmpi.b  #13,(a0)
        bne.s   vpr8_cle_lf
        addq.l  #1,a0
        subq.l  #1,d6
        tst.l   d6
        beq.s   vpr8_cle_done
vpr8_cle_lf:
        cmpi.b  #10,(a0)
        bne.s   vpr8_cle_done
        addq.l  #1,a0
        subq.l  #1,d6
        moveq   #0,d0
vpr8_cle_done:
        rts

; Apply file values only where the CLI did not explicitly override them.
vpr8_apply_resume_defaults:
        tst.l   vpr8_resume_requested
        beq.s   vpr8_ard_done
        tst.l   vpr8_resume_loaded
        beq.s   vpr8_ard_done
        tst.l   vpr8_cli_w_explicit
        bne.s   vpr8_ard_time
        move.l  vpr8_resume_file_mode,v40j_cli_mode
vpr8_ard_time:
        tst.l   v40j_start_time_valid
        bne.s   vpr8_ard_done
        move.l  vpr8_resume_time_secs,v40j_start_time_secs
        move.l  #1,v40j_start_time_valid
vpr8_ard_done:
        rts

; Show a resume failure on the Shell even when log:<file> was selected.
; A1=prefix, D3=prefix length.  The .t path is appended.
vpr8_print_resume_error_path:
        movem.l d0-d7/a0-a2,-(sp)
        move.l  mkvr7_log_mode,d7
        clr.l   mkvr7_log_mode
        jsr     print
        lea     mkvr7_resume_name,a1
        move.l  a1,a0
        moveq   #0,d3
vpr8_pre_len:
        tst.b   (a0)+
        beq.s   vpr8_pre_len_done
        addq.l  #1,d3
        bra.s   vpr8_pre_len
vpr8_pre_len_done:
        jsr     print
        lea     msg_nl,a1
        moveq   #1,d3
        jsr     print
        ; Keep the agreed user hint visible in quiet mode as a continuation.
        move.l  #1,v41l_error_line
        lea     msg_vpr8_resume_hint,a1
        move.l  #msg_vpr8_resume_hint_end-msg_vpr8_resume_hint,d3
        jsr     print
        move.l  d7,mkvr7_log_mode
        movem.l (sp)+,d0-d7/a0-a2
        rts

; --------------------------------------------------------------------
; H264RGB4 - find SPS/PPS NAL units in the selected raw Annex-B H264 file.
;
; The probe reads the first 4096 bytes, recognises both 00 00 01 and
; 00 00 00 01 start codes, and extracts the first SPS (NAL type 7) and
; first PPS (NAL type 8), including their original Annex-B start codes.
; The two NAL units are concatenated into h264_file_extradata and the
; actual combined length is sent as MMAL extradata_size (max 128 bytes).
;
; Playback later reopens the same file from byte 0, so the stable live
; streaming path is unchanged.
;
; h264_find_nal input: D0 = wanted NAL type (7=SPS, 8=PPS)
; output: D0=1 found / 0 not found, A0=start-code pointer, D1=NAL bytes
;         through (but excluding) the following Annex-B start code.
; --------------------------------------------------------------------
h264_find_nal:
        movem.l d2-d7/a1-a3,-(sp)
        move.l  d0,d7
        lea     h264_probe_buf,a1
        move.l  h264_probe_read,d6
        move.l  a1,a3
        add.l   d6,a3

h264_find_scan:
        move.l  a3,d0
        sub.l   a1,d0
        cmp.l   #5,d0
        bcs.w   h264_find_not_found

        tst.b   (a1)
        bne.s   h264_find_advance
        tst.b   1(a1)
        bne.s   h264_find_advance
        cmp.b   #1,2(a1)
        beq.s   h264_find_start3
        tst.b   2(a1)
        bne.s   h264_find_advance
        cmp.b   #1,3(a1)
        beq.s   h264_find_start4

h264_find_advance:
        addq.l  #1,a1
        bra.w   h264_find_scan

h264_find_start3:
        moveq   #3,d2
        moveq   #0,d0
        move.b  3(a1),d0
        bra.s   h264_find_check_type

h264_find_start4:
        moveq   #4,d2
        moveq   #0,d0
        move.b  4(a1),d0

h264_find_check_type:
        and.l   #$1F,d0
        cmp.l   d7,d0
        beq.s   h264_find_target

        ; Skip this complete start code and its NAL header so a 4-byte
        ; start code cannot be rediscovered one byte later as a 3-byte code.
        add.l   d2,a1
        addq.l  #1,a1
        bra.w   h264_find_scan

h264_find_target:
        move.l  a1,a0
        move.l  a1,a2
        add.l   d2,a2
        addq.l  #1,a2

        ; Find the next Annex-B start code, which defines the end of this NAL.
h264_find_next:
        move.l  a3,d0
        sub.l   a2,d0
        cmp.l   #3,d0
        bcc.s   h264_find_next_have_room
        ; Stage 3A / library config semantics:
        ; BVP_PKT_CONFIG is a finite Annex-B configuration blob.  MintVID's
        ; avcC->Annex-B converter normally returns exactly SPS followed by PPS,
        ; so the final PPS has no following start code.  In that case the end
        ; of the caller buffer is the legal NAL boundary.
        move.l  a3,d1
        sub.l   a0,d1
        tst.l   d1
        beq.w   h264_find_not_found
        moveq   #1,d0
        bra.w   h264_find_done
h264_find_next_have_room:

        tst.b   (a2)
        bne.s   h264_find_next_advance
        tst.b   1(a2)
        bne.s   h264_find_next_advance
        cmp.b   #1,2(a2)
        beq.s   h264_find_boundary
        cmp.l   #4,d0
        bcs.s   h264_find_next_advance
        tst.b   2(a2)
        bne.s   h264_find_next_advance
        cmp.b   #1,3(a2)
        beq.s   h264_find_boundary

h264_find_next_advance:
        addq.l  #1,a2
        bra.w   h264_find_next

h264_find_boundary:
        move.l  a2,d1
        sub.l   a0,d1
        moveq   #1,d0
        bra.s   h264_find_done

h264_find_not_found:
        moveq   #0,d0
        clr.l   d1

h264_find_done:
        movem.l (sp)+,d2-d7/a1-a3
        rts


h264rgb_load_file_extradata:
        movem.l d1-d7/a0-a3/a6,-(sp)

        clr.l   h264_probe_handle
        clr.l   h264_probe_read
        clr.l   h264_codec_config_len
        clr.l   h264_sps_len
        clr.l   h264_pps_len

        move.l  a5,a6
        lea     t23_file_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   h264rgb_probe_open_fail
        move.l  d0,h264_probe_handle

        move.l  d0,d1
        lea     h264_probe_buf,a0
        move.l  a0,d2
        move.l  #H264_PROBE_SIZE,d3
        move.l  a5,a6
        jsr     Read(a6)
        move.l  d0,h264_probe_read

        move.l  h264_probe_handle,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   h264_probe_handle

        move.l  h264_probe_read,d0
        cmp.l   #8,d0
        bcs.w   h264rgb_probe_read_fail

        moveq   #7,d0
        bsr     h264_find_nal
        tst.l   d0
        beq.w   h264rgb_probe_no_sps
        move.l  a0,h264_sps_ptr
        move.l  d1,h264_sps_len

        moveq   #8,d0
        bsr     h264_find_nal
        tst.l   d0
        beq.w   h264rgb_probe_no_pps
        move.l  a0,h264_pps_ptr
        move.l  d1,h264_pps_len

        move.l  h264_sps_len,d0
        add.l   h264_pps_len,d0
        tst.l   d0
        beq.w   h264rgb_probe_no_sps
        move.l  d0,h264_codec_config_len
        cmp.l   #H264_CODEC_CONFIG_MAX,d0
        bhi.w   h264rgb_probe_too_large

        ; Clear max-sized destination then concatenate SPS followed by PPS.
        lea     h264_file_extradata,a0
        moveq   #31,d7
h264rgb_extra_clear:
        clr.l   (a0)+
        dbra    d7,h264rgb_extra_clear

        move.l  h264_sps_ptr,a0
        lea     h264_file_extradata,a1
        move.l  h264_sps_len,d7
        subq.l  #1,d7
h264rgb_copy_sps:
        move.b  (a0)+,(a1)+
        dbra    d7,h264rgb_copy_sps

        move.l  h264_pps_ptr,a0
        move.l  h264_pps_len,d7
        subq.l  #1,d7
h264rgb_copy_pps:
        move.b  (a0)+,(a1)+
        dbra    d7,h264rgb_copy_pps

        lea     msg_hr4_sps,a1
        move.l  #msg_hr4_sps_end-msg_hr4_sps,d3
        jsr     print
        move.l  h264_sps_len,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_hr4_pps,a1
        move.l  #msg_hr4_pps_end-msg_hr4_pps,d3
        jsr     print
        move.l  h264_pps_len,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_hr4_extra,a1
        move.l  #msg_hr4_extra_end-msg_hr4_extra,d3
        jsr     print
        move.l  h264_codec_config_len,d0
        jsr     print_hex32
        jsr     newline

        moveq   #0,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_open_fail:
        lea     e_hr4_probe_open,a1
        move.l  #e_hr4_probe_open_end-e_hr4_probe_open,d3
        jsr     print
        moveq   #1,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_read_fail:
        lea     e_hr4_probe_read,a1
        move.l  #e_hr4_probe_read_end-e_hr4_probe_read,d3
        jsr     print
        move.l  h264_probe_read,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_no_sps:
        lea     e_hr4_no_sps,a1
        move.l  #e_hr4_no_sps_end-e_hr4_no_sps,d3
        jsr     print
        moveq   #1,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_no_pps:
        lea     e_hr4_no_pps,a1
        move.l  #e_hr4_no_pps_end-e_hr4_no_pps,d3
        jsr     print
        moveq   #1,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_too_large:
        lea     e_hr4_too_large,a1
        move.l  #e_hr4_too_large_end-e_hr4_too_large,d3
        jsr     print
        move.l  h264_codec_config_len,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0

h264rgb_probe_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


; ====================================================================
; V10 EXTERNAL LUT LOADER
; Keeps the executable small while preserving the exact same Fast-RAM
; lookup access pattern during HAM6 conversion.
; ====================================================================
; Input: D0=size, A0=filename, A1=address of pointer variable
; Output: D0=0 success, D0=1 failure. On failure this allocation is freed.
v9m_load_one_lut:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  d0,d7
        move.l  a0,a2
        move.l  a1,a3
        clr.l   (a3)

        move.l  a4,a6
        move.l  d7,d0
        move.l  #MEMF_FAST,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.s   v9m_load_one_fail
        move.l  d0,(a3)

        move.l  a5,a6
        move.l  a2,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.s   v9m_load_one_free_fail
        move.l  d0,d6

        move.l  d6,d1
        move.l  (a3),d2
        move.l  d7,d3
        move.l  a5,a6
        jsr     Read(a6)
        move.l  d0,d5

        move.l  d6,d1
        move.l  a5,a6
        jsr     Close(a6)

        cmp.l   d7,d5
        bne.s   v9m_load_one_free_fail
        moveq   #0,d0
        bra.s   v9m_load_one_done

v9m_load_one_free_fail:
        move.l  (a3),d0
        beq.s   v9m_load_one_fail
        move.l  d0,a1
        move.l  d7,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   (a3)

v9m_load_one_fail:
        moveq   #1,d0
v9m_load_one_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

v9m_load_luts:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   v9m_ham_lut_ptr
        clr.l   v9m_edge_lut_ptr
        clr.l   v9m_state_lut_ptr

        lea     msg_v9m_lut_start,a1
        move.l  #msg_v9m_lut_start_end-msg_v9m_lut_start,d3
        jsr     print

        lea     v9m_ham_name,a0
        move.l  #V10_HAM_LUT_SIZE,d0
        lea     v9m_ham_lut_ptr,a1
        jsr     v9m_load_one_lut
        tst.l   d0
        bne.s   v9m_load_ham_fail
        lea     msg_v9m_ham_ok,a1
        move.l  #msg_v9m_ham_ok_end-msg_v9m_ham_ok,d3
        jsr     print

        lea     v9m_edge_name,a0
        move.l  #V10_EDGE_LUT_SIZE,d0
        lea     v9m_edge_lut_ptr,a1
        jsr     v9m_load_one_lut
        tst.l   d0
        bne.s   v9m_load_edge_fail
        lea     msg_v9m_edge_ok,a1
        move.l  #msg_v9m_edge_ok_end-msg_v9m_edge_ok,d3
        jsr     print

        lea     v9m_state_name,a0
        move.l  #V10_STATE_LUT_SIZE,d0
        lea     v9m_state_lut_ptr,a1
        jsr     v9m_load_one_lut
        tst.l   d0
        bne.s   v9m_load_state_fail
        lea     msg_v9m_state_ok,a1
        move.l  #msg_v9m_state_ok_end-msg_v9m_state_ok,d3
        jsr     print

        lea     msg_v9m_lut_all_ok,a1
        move.l  #msg_v9m_lut_all_ok_end-msg_v9m_lut_all_ok,d3
        jsr     print
        moveq   #0,d0
        bra.s   v9m_load_luts_done

v9m_load_ham_fail:
        lea     e_v9m_ham,a1
        move.l  #e_v9m_ham_end-e_v9m_ham,d3
        bsr     print
        bra.s   v9m_load_luts_fail
v9m_load_edge_fail:
        lea     e_v9m_edge,a1
        move.l  #e_v9m_edge_end-e_v9m_edge,d3
        bsr     print
        bra.s   v9m_load_luts_fail
v9m_load_state_fail:
        lea     e_v9m_state,a1
        move.l  #e_v9m_state_end-e_v9m_state,d3
        bsr     print
v9m_load_luts_fail:
        jsr     v9m_free_luts
        moveq   #1,d0
v9m_load_luts_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

v9m_free_luts:
        movem.l d0-d7/a0-a3/a6,-(sp)
        move.l  v9m_ham_lut_ptr,d0
        or.l    v9m_edge_lut_ptr,d0
        or.l    v9m_state_lut_ptr,d0
        beq.w   v9m_free_luts_done

        lea     msg_v9m_lut_free,a1
        move.l  #msg_v9m_lut_free_end-msg_v9m_lut_free,d3
        bsr     print

        move.l  a4,a6
        move.l  v9m_ham_lut_ptr,d0
        beq.s   v9m_free_no_ham
        move.l  d0,a1
        move.l  #V10_HAM_LUT_SIZE,d0
        jsr     FreeMem(a6)
        clr.l   v9m_ham_lut_ptr
v9m_free_no_ham:
        move.l  v9m_edge_lut_ptr,d0
        beq.s   v9m_free_no_edge
        move.l  d0,a1
        move.l  #V10_EDGE_LUT_SIZE,d0
        jsr     FreeMem(a6)
        clr.l   v9m_edge_lut_ptr
v9m_free_no_edge:
        move.l  v9m_state_lut_ptr,d0
        beq.s   v9m_free_no_state
        move.l  d0,a1
        move.l  #V10_STATE_LUT_SIZE,d0
        jsr     FreeMem(a6)
        clr.l   v9m_state_lut_ptr
v9m_free_no_state:
        lea     msg_v9m_lut_free_ok,a1
        move.l  #msg_v9m_lut_free_ok_end-msg_v9m_lut_free_ok,d3
        bsr     print
v9m_free_luts_done:
        movem.l (sp)+,d0-d7/a0-a3/a6
        rts


; --------------------------------------------------------------------
; V10P - Raspberry Pi firmware memory split diagnostic, AFTER the
; already-proven VCHIQ_INIT property transaction.
;
; Reuses the exact property buffer/physical mapping that successfully
; completed VCHIQ_INIT.  Queries are deliberately sent one at a time:
;   0x00010005 GET_ARM_MEMORY -> base,size
;   0x00010006 GET_VC_MEMORY  -> base,size
; For each reply the complete mailbox response word (address+channel)
; must equal the request word.  Failure is non-fatal.
; --------------------------------------------------------------------
v10l_query_firmware_memory_after_init:
        movem.l d0-d7/a0-a3/a6,-(sp)
        clr.l   v10k_arm_base
        clr.l   v10k_arm_size
        clr.l   v10k_vc_base
        clr.l   v10k_vc_size
        clr.l   v10k_query_result

        lea     msg_v10k_mem_start,a1
        move.l  #msg_v10k_mem_start_end-msg_v10k_mem_start,d3
        jsr     print

        ; The normal VCHIQ_INIT path has already proven all three facts below.
        move.l  prop_alloc,d0
        beq.w   v10l_mem_fail_precondition
        move.l  prop_ptr,d0
        beq.w   v10l_mem_fail_precondition
        cmp.l   prop_phys,d0
        bne.w   v10l_mem_fail_precondition

        lea     msg_v10l_reuse,a1
        move.l  #msg_v10l_reuse_end-msg_v10l_reuse,d3
        jsr     print
        move.l  prop_phys,d0
        jsr     print_hex32
        jsr     newline

        ; Query ARM memory first.
        move.l  #$00010005,d0
        jsr     v10l_query_one_memory_tag
        tst.l   d0
        bne.w   v10l_mem_fail_arm
        move.l  d1,v10k_arm_base
        move.l  d2,v10k_arm_size

        ; Query VideoCore memory separately.
        move.l  #$00010006,d0
        jsr     v10l_query_one_memory_tag
        tst.l   d0
        bne.w   v10l_mem_fail_vc
        move.l  d1,v10k_vc_base
        move.l  d2,v10k_vc_size

        lea     msg_v10k_arm,a1
        move.l  #msg_v10k_arm_end-msg_v10k_arm,d3
        jsr     print
        move.l  v10k_arm_base,d0
        jsr     print_hex32
        lea     msg_v10k_sep,a1
        move.l  #msg_v10k_sep_end-msg_v10k_sep,d3
        jsr     print
        move.l  v10k_arm_size,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_v10k_vc,a1
        move.l  #msg_v10k_vc_end-msg_v10k_vc,d3
        jsr     print
        move.l  v10k_vc_base,d0
        jsr     print_hex32
        lea     msg_v10k_sep,a1
        move.l  #msg_v10k_sep_end-msg_v10k_sep,d3
        jsr     print
        move.l  v10k_vc_size,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_v10k_vc_mib,a1
        move.l  #msg_v10k_vc_mib_end-msg_v10k_vc_mib,d3
        jsr     print
        move.l  v10k_vc_size,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        jsr     print_hex32
        lea     msg_v10k_mib_suffix,a1
        move.l  #msg_v10k_mib_suffix_end-msg_v10k_mib_suffix,d3
        jsr     print
        moveq   #0,d6
        bra.w   v10l_mem_done

v10l_mem_fail_precondition:
        lea     msg_v10l_mem_precond_fail,a1
        move.l  #msg_v10l_mem_precond_fail_end-msg_v10l_mem_precond_fail,d3
        jsr     print
        moveq   #1,d6
        bra.s   v10l_mem_done
v10l_mem_fail_arm:
        lea     msg_v10l_arm_fail,a1
        move.l  #msg_v10l_arm_fail_end-msg_v10l_arm_fail,d3
        jsr     print
        moveq   #1,d6
        bra.s   v10l_mem_done
v10l_mem_fail_vc:
        lea     msg_v10l_vc_fail,a1
        move.l  #msg_v10l_vc_fail_end-msg_v10l_vc_fail,d3
        jsr     print
        moveq   #1,d6

v10l_mem_done:
        move.l  d6,v10k_query_result
        movem.l (sp)+,d0-d7/a0-a3/a6
        rts

; D0 = property tag. Returns D0=0 success, D1=base, D2=size.
; Returns nonzero on failure. Uses only the already-proven prop_ptr buffer.
v10l_query_one_memory_tag:
        movem.l d3-d7/a0-a2/a6,-(sp)
        move.l  d0,d3                  ; requested tag
        clr.l   d1
        clr.l   d2

        move.l  prop_ptr,a2
        cmpa.l  #0,a2
        beq.w   v10l_q_fail

        ; 32-byte property message with one 8-byte memory tag.
        move.l  a2,a0
        move.l  #32,d0
        jsr     store_le32
        lea     4(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  d3,d0
        jsr     store_le32
        lea     12(a2),a0
        moveq   #8,d0
        jsr     store_le32
        lea     16(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     20(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     24(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     28(a2),a0
        moveq   #0,d0
        jsr     store_le32

        ; Same CachePreDMA/physical identity convention as proven VCHIQ_INIT.
        move.l  #32,prop_len
        move.l  a2,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        move.l  d0,d4                  ; returned physical address
        cmp.l   prop_ptr,d0
        bne.w   v10l_q_post_fail

        and.l   #$fffffff0,d0
        or.l    #MBOX_PROPERTY,d0
        move.l  d0,d6                  ; exact request word (phys+channel)

        move.l  #TIMEOUT,d7
v10l_q_tx_wait:
        move.l  MBOX_STATUS,d0
        jsr     bswap32
        and.l   #MBOX_TX_FULL,d0
        beq.s   v10l_q_tx_ready
        subq.l  #1,d7
        bne.s   v10l_q_tx_wait
        bra.w   v10l_q_post_fail
v10l_q_tx_ready:
        move.l  d6,d0
        jsr     bswap32
        move.l  d0,MBOX_WRITE

        move.l  #TIMEOUT,d7
v10l_q_rx_wait:
        move.l  MBOX_STATUS,d0
        jsr     bswap32
        and.l   #MBOX_RX_EMPTY,d0
        beq.s   v10l_q_rx_ready
        subq.l  #1,d7
        bne.s   v10l_q_rx_wait
        bra.w   v10l_q_post_fail
v10l_q_rx_ready:
        move.l  MBOX_READ,d0
        jsr     bswap32
        cmp.l   d6,d0                  ; V10P: exact address+channel match
        beq.s   v10l_q_got_exact
        subq.l  #1,d7
        bne.s   v10l_q_rx_wait
        bra.w   v10l_q_post_fail

v10l_q_got_exact:
        move.l  #32,prop_len
        move.l  prop_ptr,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)

        move.l  prop_ptr,a2
        lea     4(a2),a0
        jsr     load_le32
        cmp.l   #$80000000,d0
        bne.s   v10l_q_fail_no_post
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   d3,d0
        bne.s   v10l_q_fail_no_post
        lea     16(a2),a0
        jsr     load_le32
        cmp.l   #$80000008,d0
        bne.s   v10l_q_fail_no_post
        lea     20(a2),a0
        jsr     load_le32
        move.l  d0,d1
        lea     24(a2),a0
        jsr     load_le32
        move.l  d0,d2
        moveq   #0,d0
        bra.s   v10l_q_done

v10l_q_post_fail:
        ; CachePreDMA has begun: always close the phase before returning.
        move.l  #32,prop_len
        move.l  prop_ptr,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
v10l_q_fail_no_post:
v10l_q_fail:
        moveq   #1,d0
v10l_q_done:
        movem.l (sp)+,d3-d7/a0-a2/a6
        rts

; --------------------------------------------------------------------
; v96.89 (05.11.2026): PiStorm32 lite / CM4 (BCM2711, VideoCore VI).
;
; v89_query_tag: like v10l_query_one_memory_tag (same prop_ptr buffer, same
; CachePreDMA/PostDMA and exact reply-word match), but the firmware may
; answer with 4 or 8 value bytes.  D0 = tag.  Returns D0=0 ok, D1/D2 = the
; two value words (D2 = 0 for a 4-byte answer); D0<>0 on failure.
; --------------------------------------------------------------------
v89_query_tag:
        movem.l d3-d7/a0-a2/a6,-(sp)
        move.l  d0,d3
        clr.l   d1
        clr.l   d2
        move.l  prop_alloc,d0
        beq.w   v89_q_fail
        move.l  prop_ptr,a2
        cmpa.l  #0,a2
        beq.w   v89_q_fail

        move.l  a2,a0
        move.l  #32,d0
        jsr     store_le32
        lea     4(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  d3,d0
        jsr     store_le32
        lea     12(a2),a0
        moveq   #8,d0
        jsr     store_le32
        lea     16(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     20(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     24(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     28(a2),a0
        moveq   #0,d0
        jsr     store_le32

        move.l  #32,prop_len
        move.l  a2,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        cmp.l   prop_ptr,d0
        bne.w   v89_q_post_fail

        and.l   #$fffffff0,d0
        or.l    #MBOX_PROPERTY,d0
        move.l  d0,d6

        move.l  #TIMEOUT,d7
v89_q_tx_wait:
        move.l  MBOX_STATUS,d0
        jsr     bswap32
        and.l   #MBOX_TX_FULL,d0
        beq.s   v89_q_tx_ready
        subq.l  #1,d7
        bne.s   v89_q_tx_wait
        bra.w   v89_q_post_fail
v89_q_tx_ready:
        move.l  d6,d0
        jsr     bswap32
        move.l  d0,MBOX_WRITE

        move.l  #TIMEOUT,d7
v89_q_rx_wait:
        move.l  MBOX_STATUS,d0
        jsr     bswap32
        and.l   #MBOX_RX_EMPTY,d0
        beq.s   v89_q_rx_ready
        subq.l  #1,d7
        bne.s   v89_q_rx_wait
        bra.w   v89_q_post_fail
v89_q_rx_ready:
        move.l  MBOX_READ,d0
        jsr     bswap32
        cmp.l   d6,d0
        beq.s   v89_q_got
        subq.l  #1,d7
        bne.s   v89_q_rx_wait
        bra.w   v89_q_post_fail

v89_q_got:
        move.l  #32,prop_len
        move.l  prop_ptr,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  4.w,a6
        jsr     CachePostDMA(a6)

        move.l  prop_ptr,a2
        lea     4(a2),a0
        jsr     load_le32
        cmp.l   #$80000000,d0
        bne.s   v89_q_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   d3,d0
        bne.s   v89_q_fail
        lea     16(a2),a0
        jsr     load_le32
        cmp.l   #$80000004,d0
        beq.s   v89_q_len_ok
        cmp.l   #$80000008,d0
        bne.s   v89_q_fail
v89_q_len_ok:
        move.l  d0,d4
        lea     20(a2),a0
        jsr     load_le32
        move.l  d0,d1
        cmp.l   #$80000008,d4
        bne.s   v89_q_ok
        lea     24(a2),a0
        jsr     load_le32
        move.l  d0,d2
v89_q_ok:
        moveq   #0,d0
        bra.s   v89_q_done

v89_q_post_fail:
        move.l  #32,prop_len
        move.l  prop_ptr,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  4.w,a6
        jsr     CachePostDMA(a6)
v89_q_fail:
        moveq   #1,d0
v89_q_done:
        movem.l (sp)+,d3-d7/a0-a2/a6
        rts

; v96.99 (06.11.2026): the attach path (VCHIQ already running) never asked
; the firmware for the board, so v89_vc6 kept whatever an earlier session of
; this library instance left behind - 0 after the library was reloaded, or
; when another program (e.g. ami264test) started VCHIQ first.  On the CM4
; that selected the Pi 3 HVS/pagelist layout and the start failed after
; "N79 OUT PRE".  Allocate the property buffer if needed (freed at close as
; before) and run the same board detection as the first start.
v9699_attach_board:
        movem.l d0-d1/a0-a1/a6,-(sp)
        tst.l   prop_alloc
        bne.s   v9699_ab_have_prop
        move.l  a4,a6
        move.l  #$200,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.s   v9699_ab_done
        move.l  d0,prop_alloc
        add.l   #127,d0
        and.l   #$ffffff80,d0
        move.l  d0,prop_ptr
v9699_ab_have_prop:
        jsr     v89_detect_board
v9699_ab_done:
        movem.l (sp)+,d0-d1/a0-a1/a6
        rts

; v89_detect_board: GET_BOARD_REVISION ($00010002).  New-style revision
; codes (bit 23) carry the SoC in bits 15..12: 3 = BCM2711 (Pi 4, Pi 400,
; CM4).  Sets v89_vc6 = 1 only then; on any failure the Pi 3 behaviour stays.
v89_detect_board:
        movem.l d0-d2/a1,-(sp)
        move.l  #$00010002,d0
        jsr     v89_query_tag
        tst.l   d0
        bne.s   v89_db_done
        move.l  d1,v89_board_rev
        clr.l   v89_vc6
        btst    #23,d1
        beq.s   v89_db_log
        move.l  d1,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        andi.l  #$0000000f,d0
        cmpi.l  #3,d0
        bne.s   v89_db_log
        move.l  #1,v89_vc6
v89_db_log:
        move.l  v89_board_rev,d0
        lea     v89_pfx_board_rev,a1
        jsr     n15_log_hex32
        move.l  v89_vc6,d0
        lea     v89_pfx_vc6,a1
        jsr     n15_log_hex32
v89_db_done:
        movem.l (sp)+,d0-d2/a1
        rts

; v96.90 diagnostic: HVS state during playback (read only).  Logged after
; the 2nd, 50th, 200th and 500th video packet: active list pointers of all
; three channels, DISPCTRL0..2 and DISPSTAT0..2.
; v96.91: firmware display number for video_render.  Pi 3: 0 (main
; display, as before).  Pi 4 / CM4: 2 = HDMI0 (on the Pi 4 the firmware
; counts its displays as 0 = DSI LCD, 2 = HDMI0, 7 = HDMI1).
v91_display_num:
        tst.l   v89_vc6
        beq.s   v91_dn_done
        moveq   #2,d0
v91_dn_done:
        rts

; v96.93: MMAL events from the VideoCore (format changed, errors, EOS ...)
; into N79_TRACE.TXT.  The first 24 are written in full (A2 = message).
v93_log_event:
        movem.l d0/a0-a1,-(sp)
        addq.l  #1,v93_event_count
        cmpi.l  #24,v93_event_count
        bhi.s   v93_le_done
        move.l  v93_event_count,d0
        lea     v93_pfx_ev_no,a1
        jsr     n15_log_hex32
        move.l  event_port_type,d0
        lea     v93_pfx_ev_ptype,a1
        jsr     n15_log_hex32
        move.l  event_port_num,d0
        lea     v93_pfx_ev_pnum,a1
        jsr     n15_log_hex32
        move.l  buffer_event_cmd,d0
        lea     v93_pfx_ev_cmd,a1
        jsr     n15_log_hex32
        move.l  buffer_event_length,d0
        lea     v93_pfx_ev_len,a1
        jsr     n15_log_hex32
        move.l  bulk_rx_size,d0
        cmpi.l  #56,d0
        bcs.s   v93_le_done
        lea     52(a2),a0
        jsr     load_le32
        lea     v93_pfx_ev_data,a1
        jsr     n15_log_hex32
v93_le_done:
        movem.l (sp)+,d0/a0-a1
        rts

; --------------------------------------------------------------------
; v96.94 (05.11.2026): VCHIQ pagelist addresses on the BCM2711.
; Pi 3: addrs[k] = bus page ($C0000000 alias) | (pages - 1), up to 4096
; pages per entry.  Pi 4 / CM4: the firmware expects the 36-bit form
; (Linux vchiq_arm.c, bcm2711_drvdata.use_36bit_addrs):
;   addrs[k] = ((phys >> 4) & ~$FF) | (pages - 1), at most 256 pages each.
; The old form made the VideoCore read far outside the RAM (all ones):
; white subtitle box, no decoded picture on the CM4.
; A0 = &addrs[0], D0 = entry in the Pi 3 form.  Writes one or more
; entries.  D0 is destroyed (like store_le32), all else kept.
; --------------------------------------------------------------------
v94_pl_store:
        tst.l   v89_vc6
        bne.s   v94_ps_vc6
        jmp     store_le32
v94_ps_vc6:
        movem.l d1-d3/a0,-(sp)
        move.l  d0,d1
        andi.l  #$00000fff,d1
        addq.l  #1,d1                    ; pages
        move.l  d0,d2
        andi.l  #$3ffff000,d2            ; physical page (no bus alias)
        lsr.l   #4,d2                    ; page id << 8
v94_ps_loop:
        move.l  d1,d3
        cmpi.l  #256,d3
        bls.s   v94_ps_n_ok
        move.l  #256,d3
v94_ps_n_ok:
        move.l  d3,d0
        subq.l  #1,d0
        or.l    d2,d0
        jsr     store_le32
        addq.l  #4,a0
        addq.l  #1,v94_pl_entries
        sub.l   d3,d1
        move.l  d3,d0
        lsl.l   #8,d0
        add.l   d0,d2
        tst.l   d1
        bne.s   v94_ps_loop
        movem.l (sp)+,d1-d3/a0
        rts

v90_hvs_probe:
        ifeq    V97_HVS_PROBE
        rts                              ; v96.97: probe switched off
        endc
        movem.l d0-d1/a0-a2,-(sp)
        ; v96.96: only once (2nd packet).  The long dumps at packet 50/200/
        ; 500 wrote ~70 trace lines during playback; with HDMI sound the
        ; picture froze right after the one at packet 500.
        move.l  n11_video_returns,d0
        cmpi.l  #2,d0
        bne.w   v90_hp_done
v90_hp_go:
        lea     v90_pfx_count,a1
        jsr     n15_log_hex32
        move.l  v93_event_count,d0
        lea     v93_pfx_ev_total,a1
        jsr     n15_log_hex32
        move.l  v94_pl_entries,d0
        lea     v94_pfx_pl,a1
        jsr     n15_log_hex32
        lea     v90_hvs_regs,a2
v90_hp_loop:
        move.l  (a2)+,d1
        beq.s   v90_hp_regs_done
        move.l  (a2)+,a1
        move.l  d1,a0
        jsr     load_le32
        jsr     n15_log_hex32
        bra.s   v90_hp_loop
v90_hp_regs_done:
        ; v96.92: on the CM4 also dump the active list and look for other
        ; planes (the video) anywhere in the HVS5 list memory.
        tst.l   v89_vc6
        beq.s   v90_hp_done
        jsr     v92_dlist_dump
v90_hp_done:
        movem.l (sp)+,d0-d1/a0-a2
        rts

; v96.92: dump 24 words at the active channel-1 list and scan the whole
; HVS5 list memory (4096 words) for valid plane control words that are not
; RGBA8888 (format 7).  Logs at most 8 hits (index, word).  Read only.
v92_dlist_dump:
        movem.l d0-d7/a0-a1,-(sp)
        move.l  #$F2400024,a0
        jsr     load_le32
        move.l  d0,d6
        cmpi.l  #$00000fe0,d6
        bcc.s   v92_dd_scan
        lea     v92_pfx_dl_at,a1
        jsr     n15_log_hex32
        move.l  #V89_HVS5_DLIST_BASE,a0
        move.l  d6,d1
        lsl.l   #2,d1
        adda.l  d1,a0
        moveq   #23,d7
v92_dd_word:
        jsr     load_le32
        lea     v92_pfx_dl_word,a1
        jsr     n15_log_hex32
        addq.l  #4,a0
        dbra    d7,v92_dd_word
v92_dd_scan:
        move.l  #V89_HVS5_DLIST_BASE,a0
        moveq   #0,d6                    ; index
        moveq   #0,d5                    ; hits
v92_dd_scan_loop:
        jsr     load_le32
        move.l  d0,d1
        andi.l  #$C0000000,d1
        cmpi.l  #$40000000,d1            ; VALID, not END
        bne.s   v92_dd_next
        move.l  d0,d1
        andi.l  #$3F000000,d1            ; words 1..63
        beq.s   v92_dd_next
        move.l  d0,d1
        andi.l  #$0000001f,d1
        cmpi.l  #7,d1
        beq.s   v92_dd_next
        move.l  d0,d7
        move.l  d6,d0
        lea     v92_pfx_hit_idx,a1
        jsr     n15_log_hex32
        move.l  d7,d0
        lea     v92_pfx_hit_word,a1
        jsr     n15_log_hex32
        addq.l  #1,d5
        cmpi.l  #8,d5
        bcc.s   v92_dd_done
v92_dd_next:
        addq.l  #4,a0
        addq.l  #1,d6
        cmpi.l  #4096,d6
        bcs.s   v92_dd_scan_loop
v92_dd_done:
        move.l  d5,d0
        lea     v92_pfx_hits,a1
        jsr     n15_log_hex32
        movem.l (sp)+,d0-d7/a0-a1
        rts

; --------------------------------------------------------------------
; V14 - shell-local Ctrl-C stop support.
;
; AmigaDOS sends SIGBREAKF_CTRL_C to the running CLI process.  Poll it with
; Exec SetSignal(0,mask), which returns and clears only the selected break bit.
; No raw keyboard/ESC hook is installed, so Workbench applications keep normal
; keyboard ownership while the film is visible on RGB.
; --------------------------------------------------------------------
v15_clear_ctrl_c:
        movem.l d1/a6,-(sp)
        moveq   #0,d0
        move.l  #SIGBREAKF_CTRL_C,d1
        move.l  a4,a6
        jsr     SetSignal(a6)
        movem.l (sp)+,d1/a6
        rts

; Return D0=1 only when a fresh Ctrl-C was observed on this poll.
; The persistent flag remains set until the process finishes its controlled EOS.
v15_poll_ctrl_c:
        movem.l d1-d2/a6,-(sp)
        tst.l   bvp_p96_mode
        bne.w   p96w43_poll_stop          ; P96W43: window streaming
        clr.l   d2
        moveq   #0,d0
        move.l  #SIGBREAKF_CTRL_C,d1
        move.l  a4,a6
        jsr     SetSignal(a6)
        and.l   #SIGBREAKF_CTRL_C,d0
        beq.s   v15_poll_ctrl_c_no_shell
        move.l  #1,v15_stop_requested
        jsr     mkvr7_capture_resume
        moveq   #1,d2
v15_poll_ctrl_c_no_shell:
        ; HDMI_v41L: the native Intuition close gadget is another clean-stop source.
        bsr     hdmi_v40o_poll_window_close
        or.l    d0,d2
        ; VPv149: when the user closes a frozen player, capture the untouched
        ; live VCHIQ/MMAL state BEFORE the central stop dispatcher sends EOS.
        ; This is deliberately event-driven: no new live timer/poll/watchdog.
        tst.l   d2
        beq.s   vpv147_stop_snapshot_skip
        tst.l   vpv147_stop_snapshot_done
        bne.s   vpv147_stop_snapshot_skip
        tst.l   vpv126_data_graph_ok
        beq.s   vpv147_stop_snapshot_skip
        tst.l   output_frame_total
        beq.s   vpv147_stop_snapshot_skip
        move.l  #1,vpv147_stop_snapshot_done
        jsr     vpv147_stop_snapshot
vpv147_stop_snapshot_skip:
        move.l  d2,d0
        movem.l (sp)+,d1-d2/a6
        rts


; --------------------------------------------------------------------
; VPv149 - STOP-triggered live-state snapshot.
; Called only after a fresh Ctrl-C/window-close has been observed, while
; h19_poll still owns the current VCHIQ CPU phase and BEFORE EOS promotion.
; Read-only apart from DOS/log output.  No VCHIQ queue or clock state changes.
; --------------------------------------------------------------------
vpv147_stop_snapshot:
        movem.l d0-d7/a0-a6,-(sp)

        lea     msg_vpv147_stop_vchiq,a1
        move.l  #msg_vpv147_stop_vchiq_end-msg_vpv147_stop_vchiq,d3
        jsr     print
        move.l  rx_recycle_total,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  rx_recycle_last_slot,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  rx_recycle_last_q,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  port_rx_pos,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        move.l  d0,vpv147_snap_mastertx ; remote/master absolute txpos
        sub.l   port_rx_pos,d0
        move.l  d0,vpv147_snap_rxgap
        move.l  vpv147_snap_mastertx,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv147_snap_rxgap,d0   ; unread VCHIQ control bytes
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print

        move.l  slot_ptr,a0
        lea     MASTER_RECYCLEQ(a0),a0
        jsr     load_le32
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  slot_ptr,a0
        lea     MASTER_RECYCLE_ARM(a0),a0
        jsr     load_le32
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  slot_ptr,a0
        lea     MASTER_RECYCLE_FIR(a0),a0
        jsr     load_le32
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  port_tx_pos,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        jsr     load_le32
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  slot_ptr,a0
        lea     SLAVE_RECYCLEQ(a0),a0
        jsr     load_le32
        jsr     print_hex32
        jsr     newline

        lea     msg_vpv147_stop_pipe,a1
        move.l  #msg_vpv147_stop_pipe_end-msg_vpv147_stop_pipe,d3
        jsr     print
        move.l  input_in_use_count,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        ; four-bit video input ownership mask
        moveq   #0,d0
        tst.l   input_slot_state
        beq.s   vpv147_sm1
        bset    #0,d0
vpv147_sm1:
        tst.l   input_slot_state+4
        beq.s   vpv147_sm2
        bset    #1,d0
vpv147_sm2:
        tst.l   input_slot_state+8
        beq.s   vpv147_sm3
        bset    #2,d0
vpv147_sm3:
        tst.l   input_slot_state+12
        beq.s   vpv147_sm_done
        bset    #3,d0
vpv147_sm_done:
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  input_return_total,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  input_bulk_total,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv140_input_pool_exhausted,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  input_bulk_pending,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  output_bulk_queued,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  output_deferred_count,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv47_inflight,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv39_audio_bulk_pending,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv66_audio_returns,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv39_audio_blocks_done,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv48_batch_count,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv45_prefetch_ready,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv41_decoder_live,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv43_a_source_eof,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv43_audio_next_pts_ticks,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv131_schedwall_last_pts,d0
        jsr     print_hex32
        jsr     newline

        movem.l (sp)+,d0-d7/a0-a6
        rts

; --------------------------------------------------------------------
; HDMI_v41L - real-time video pacing with ZERO Exec interrupt installation.
;
; v02 used AddIntServer(INTB_VERTB) only as a 50-Hz clock. That was intended
; to be display-neutral, but v04 removes even that variable while diagnosing
; Workbench/RTG ownership. The only Amiga custom-chip access here is READ-ONLY:
; VPOSR/VHPOSR are sampled in a busy wait and vertical raster wrap increments
; a private software tick counter. No Copper, bitplane, DMA or interrupt state
; is changed by the HDMI timing path.
;
; v7_setup_timing has already validated v7_fps_num / v7_fps_den. One frame
; advances by 50*fps_den/fps_num PAL refreshes. Absolute rational deadlines
; retain the v02 cadence (25 fps = 2 ticks; 23.976/30 fps use mixed intervals).
; --------------------------------------------------------------------
v04_timing_reset:
        movem.l d0-d2,-(sp)
        clr.l   v04_clock_started
        clr.l   v04_clock_accum
        clr.l   v04_clock_target
        clr.l   v04_paced_frames
        clr.l   v04_clock_counter
        clr.l   v04_last_raster
        clr.l   vpv98_timer_base_us
        clr.l   vpv98_timer_last_elapsed_us
        clr.l   vpv98_timer_target_us
        clr.l   vpv98_timer_late_count
        clr.l   vpv98_timer_max_late_us
        ; VPv150: generic deadline-lateness diagnostics retained for MKV pacing.
        clr.l   vpv150_late_gt1ms
        clr.l   vpv150_late_gt5ms
        clr.l   vpv150_late_gt_frame
        clr.l   hdmi_v40o_dump_count
        clr.l   hdmi_v40o_dump_first_offset
        clr.l   hdmi_v40o_dump_second_offset
        clr.l   hdmi_v40o_merge_count
        clr.l   hdmi_v40o_merge_last_src
        clr.l   hdmi_v40o_merge_fail
        clr.l   hdmi_v40o_merge_retry
        clr.l   hdmi_v40o_slot_a
        clr.l   hdmi_v40o_slot_b
        clr.l   hdmi_v40o_slots_reported
        clr.l   hdmi_v40o_last_patched
        clr.l   hdmi_v40o_live_line_valid
        clr.l   hdmi_v40o_live_last_line
        clr.l   hdmi_v40o_live_shadow_sel
        clr.l   hdmi_v40o_live_switches
        clr.l   hdmi_v40o_live_misses
        clr.l   hdmi_v40o_live_reasserts
        move.l  v7_fps_den,d0
        mulu.w  #50,d0
        move.l  d0,v04_clock_step_num
        move.l  v7_fps_num,d0
        move.l  d0,v04_clock_step_den
        ; Explicit proof that HDMI timing never publishes an RGB display ptr.
        clr.l   t30_active_ptr
        clr.l   t31s_vblank_installed
        bsr     v41e_hr_timing_reset
        movem.l (sp)+,d0-d2
        rts

; VPv102: read VideoCore.card's 1-MHz BCM2835 system timer.
vpv98_read_sys_us:
        movem.l a0,-(sp)
        move.l  #VPV97_SYS_TIMER_CLO,a0
        jsr     load_le32
        movem.l (sp)+,a0
        rts

; Read stable 9-bit PAL raster line into D0 (0..311 typical).
; VPOSR bit 0 is vertical bit 8, VHPOSR high byte carries vertical bits 7..0.
; If vertical bit 8 changes between the two samples, retry to avoid a false
; 255->256 transition looking like a frame wrap.
v04_sample_raster:
        movem.l d1-d3/a0,-(sp)
        lea     CUSTOM_BASE,a0
v04_sample_raster_retry:
        moveq   #0,d1
        move.w  VPOSR(a0),d1
        moveq   #0,d2
        move.w  VHPOSR(a0),d2
        moveq   #0,d3
        move.w  VPOSR(a0),d3
        eor.w   d1,d3
        btst    #0,d3
        bne.s   v04_sample_raster_retry
        andi.w  #$0001,d1
        lsl.w   #8,d1
        lsr.w   #8,d2
        andi.w  #$00ff,d2
        or.w    d2,d1
        moveq   #0,d0
        move.w  d1,d0
        movem.l (sp)+,d1-d3/a0
        rts

; Update passive 50-Hz clock by detecting 311->0 raster wrap.
v04_clock_poll:
        movem.l d1,-(sp)
        bsr     v04_sample_raster
        move.l  v04_last_raster,d1
        cmp.l   d1,d0
        bcc.s   v04_clock_no_wrap
        addq.l  #1,v04_clock_counter
v04_clock_no_wrap:
        move.l  d0,v04_last_raster
        move.l  v04_clock_counter,d0
        movem.l (sp)+,d1
        rts

; VPv174: D0 <- next exact P96 frame interval in MICROSECONDS.
; Reuse the exact rational interval already derived by v41e_hr_timing_reset,
; but keep an independent P96 fractional accumulator in v04_clock_accum.
; This removes the historical 20-ms PAL quantization from 25/50/75.
v04_next_interval:
        movem.l d1-d2,-(sp)
        move.l  v41e_hr_step_num,d0
        move.l  v04_clock_accum,d1
        add.l   v41e_hr_last_line,d1
        move.l  v41e_hr_step_den,d2
        tst.l   d2
        beq.s   v04_next_interval_fallback
        cmp.l   d2,d1
        bcs.s   v04_next_interval_store
        sub.l   d2,d1
        addq.l  #1,d0
v04_next_interval_store:
        move.l  d1,v04_clock_accum
        tst.l   d0
        bne.s   v04_next_interval_done
v04_next_interval_fallback:
        moveq   #1,d0
v04_next_interval_done:
        movem.l (sp)+,d1-d2
        rts

; Pace one new container video access unit. First frame is immediate. Later
; frames wait for an absolute passive-raster deadline. Ctrl-C remains sampled.
v04_pace_new_frame:
        ; V41I: hidden restart catch-up must be unpaced in EVERY display style,
        ; including mode 3. V41E/G sent the hidden mode-3 pre-roll at native FPS,
        ; making the cinema switch wait roughly the already-played movie time.
        tst.l   v32r_fastforward
        bne.s   v41i_pace_fastforward
        cmpi.l  #3,v41_display_style
        beq.w   v41e_hr_pace_new_frame
        movem.l d1-d4,-(sp)
        bra.s   v32r_pace_normal
v41i_pace_fastforward:
        movem.l d1-d4,-(sp)
        addq.l  #1,v04_paced_frames
        bsr     v15_poll_ctrl_c
        bra.w   v04_pace_done
v32r_pace_normal:
        jsr     hdmi_v40o_probe_video_dlist
        jsr     hdmi_v40o_live_merge_poll
        move.l  v04_clock_started,d0
        bne.s   v04_pace_wait
        ; VPv102: absolute 1-MHz Pi system-timer anchor. Unlike the old PAL
        ; raster-wrap counter, real elapsed time cannot lose whole frames while
        ; decoder/ISP/P96 work keeps execution away from the pacing poll loop.
        bsr     vpv98_read_sys_us
        move.l  d0,vpv98_timer_base_us
        clr.l   vpv98_timer_last_elapsed_us
        clr.l   v04_clock_counter
        move.l  #1,v04_clock_started
        clr.l   v04_clock_target
        bsr     v04_next_interval
        add.l   d0,v04_clock_target
        move.l  v04_clock_target,vpv98_timer_target_us
        addq.l  #1,v04_paced_frames
        bra.s   v04_pace_done

v04_pace_wait:
        move.l  v04_clock_target,d3
        move.l  d3,d2
        move.l  d2,vpv98_timer_target_us
v04_pace_wait_loop:
        bsr     vpv98_read_sys_us
        sub.l   vpv98_timer_base_us,d0
        move.l  d0,d4
        move.l  d0,vpv98_timer_last_elapsed_us
        jsr     hdmi_v40o_live_merge_poll
        cmp.l   d2,d4
        bcc.s   v04_pace_reached
        bsr     v15_poll_ctrl_c
        move.l  v15_stop_requested,d0
        tst.l   d0
        bne.s   v04_pace_reached
        bra.s   v04_pace_wait_loop
v04_pace_reached:
        ; Keep the deadline grid absolute. Late processing never moves it.
        cmp.l   d2,d4
        bcs.s   vpv98_pace_not_late
        move.l  d4,d1
        sub.l   d2,d1
        beq.s   vpv98_pace_not_late
        addq.l  #1,vpv98_timer_late_count
        bsr     vpv150_record_lateness
        cmp.l   vpv98_timer_max_late_us,d1
        bls.s   vpv98_pace_not_late
        move.l  d1,vpv98_timer_max_late_us
vpv98_pace_not_late:
        bsr     v04_next_interval
        add.l   d0,v04_clock_target
        addq.l  #1,v04_paced_frames
v04_pace_done:
        movem.l (sp)+,d1-d4
        rts

; --------------------------------------------------------------------
; HDMI_v41L mode 3 high-resolution software pacing.
; The old host feeder advanced only on 50-Hz PAL frame boundaries (20 ms),
; which quantized 29.97/30-fps delivery into visibly uneven 20/40-ms bursts.
; VPv102 mode 3 uses the BCM2835 1-MHz system timer, exactly like VPv97 P96.
; Native-fps deadlines are absolute and rational; no PAL/beamline clock remains
; in the live C timeline. Modes 1/2 retain the established historical path.
; --------------------------------------------------------------------
v41e_hr_timing_reset:
        ; VPv102: mode 3 now uses the SAME absolute 1-MHz Pi system timer as
        ; the hardware-proven VPv97 P96 path.  Build an exact rational native
        ; frame interval without 64-bit multiplication:
        ;   1,000,000 * fps_den / fps_num
        ; = (q*fps_den) + (r*fps_den)/fps_num, where
        ;   1,000,000 = q*fps_num + r.
        ; v41e_hr_step_num  = whole microseconds per frame
        ; v41e_hr_last_line = fractional remainder increment
        ; v41e_hr_step_den  = fractional denominator (fps_num)
        ; v41e_hr_accum     = carried fractional remainder.
        movem.l d0-d6,-(sp)
        clr.l   v41e_hr_started
        clr.l   v41e_hr_base
        clr.l   v41e_hr_last_line
        clr.l   v41e_hr_target
        clr.l   v41e_hr_accum

        move.l  v7_fps_num,d1
        tst.l   d1
        beq.s   v41e_hr_reset_fallback
        move.l  #1000000,d0
        jsr     v10_udiv32              ; D0=q, D1=r
        move.l  d0,d2                   ; q
        move.l  d1,d3                   ; r (< fps_num <= 65535)
        move.l  v7_fps_den,d4           ; fps_den <= fps_num for >=1 fps

        ; D2 = q * fps_den. Generic 32x16 shift/add, 16 iterations.
        ; The mathematical result is <= 1,000,000 for accepted >=1-fps input.
        move.l  d2,d5
        move.l  d4,d6
        clr.l   d2
        moveq   #15,d0
v41e_hr_mul_qden_loop:
        btst    #0,d6
        beq.s   v41e_hr_mul_qden_noadd
        add.l   d5,d2
v41e_hr_mul_qden_noadd:
        lsl.l   #1,d5
        lsr.l   #1,d6
        dbra    d0,v41e_hr_mul_qden_loop

        ; r and fps_den are both 16-bit. Divide their exact 32-bit product by
        ; fps_num; quotient joins the whole-us interval, remainder is carried.
        move.l  d3,d0
        mulu.w  d4,d0
        move.l  v7_fps_num,d1
        jsr     v10_udiv32              ; D0=fraction quotient, D1=remainder
        add.l   d0,d2
        move.l  d2,v41e_hr_step_num
        move.l  d1,v41e_hr_last_line
        move.l  v7_fps_num,v41e_hr_step_den
        bra.s   v41e_hr_reset_done

v41e_hr_reset_fallback:
        move.l  #40000,v41e_hr_step_num ; defensive 25-fps fallback only
        clr.l   v41e_hr_last_line
        move.l  #1,v41e_hr_step_den
v41e_hr_reset_done:
        movem.l (sp)+,d0-d6
        rts

; D0 <- elapsed microseconds from the mode-3 system-timer anchor.
; 32-bit subtraction intentionally wraps modulo 2^32 together with targets.
v41e_hr_clock_poll:
        bsr     vpv98_read_sys_us
        sub.l   v41e_hr_base,d0
        move.l  d0,vpv98_timer_last_elapsed_us
        rts

; D0 <- next exact native-frame interval in microseconds.
; Fractional microseconds are carried forever, so 30/29.97/23.976 do not drift.
v41e_hr_next_interval:
        movem.l d1-d2,-(sp)
        move.l  v41e_hr_step_num,d0
        move.l  v41e_hr_accum,d1
        add.l   v41e_hr_last_line,d1
        move.l  v41e_hr_step_den,d2
        tst.l   d2
        beq.s   v41e_hr_interval_fallback
        cmp.l   d2,d1
        bcs.s   v41e_hr_interval_store
        sub.l   d2,d1
        addq.l  #1,d0
v41e_hr_interval_store:
        move.l  d1,v41e_hr_accum
        tst.l   d0
        bne.s   v41e_hr_interval_done
v41e_hr_interval_fallback:
        moveq   #1,d0
v41e_hr_interval_done:
        movem.l (sp)+,d1-d2
        rts

; VPv102 mode-3 feeder pacing. First visible AU is immediate; every later AU
; is released on an ABSOLUTE 1-MHz system-timer deadline. Late work never moves
; the deadline grid. Hidden restart fast-forward remains deliberately unpaced.
v41e_hr_pace_new_frame:
        movem.l d1-d4,-(sp)
        tst.l   v32r_fastforward
        beq.s   v41e_hr_normal
        addq.l  #1,v04_paced_frames
        bsr     v15_poll_ctrl_c
        bra.w   v41e_hr_done
v41e_hr_normal:
        tst.l   v41e_hr_started
        bne.s   v41e_hr_wait
        bsr     vpv98_read_sys_us
        move.l  d0,v41e_hr_base
        move.l  d0,vpv98_timer_base_us
        clr.l   vpv98_timer_last_elapsed_us
        clr.l   v41e_hr_target
        move.l  #1,v41e_hr_started
        bsr     v41e_hr_next_interval
        add.l   d0,v41e_hr_target
        move.l  v41e_hr_target,vpv98_timer_target_us
        addq.l  #1,v04_paced_frames
        bra.s   v41e_hr_done
v41e_hr_wait:
        ; N65: VPr8 principle - while Video is not due yet, give a deferred
        ; MintVID PCM batch one service opportunity instead of pure busy-wait.
        ; The helper never leaves a VCHIQ BULK outstanding across this call.
        tst.l   n65_audio_pending
        beq.s   v41e_hr_n65_audio_done
        jsr     n65_service_pending_audio
v41e_hr_n65_audio_done:
        move.l  v41e_hr_target,d3
        move.l  d3,vpv98_timer_target_us
v41e_hr_wait_loop:
        move.l  #3,p96w_where        ; P96W33 hang marker
        bsr     v41e_hr_clock_poll
        move.l  d0,d4
        cmp.l   d3,d4
        bcc.s   v41e_hr_reached
        jsr     p96w9_idle_poll
        bsr     v15_poll_ctrl_c
        tst.l   v15_stop_requested
        bne.s   v41e_hr_reached
        bra.s   v41e_hr_wait_loop
v41e_hr_reached:
        ; Same VPv97 rule as P96: lateness is measured, never accumulated into
        ; the next deadline.  This is the critical C-mode A/V drift fix.
        cmp.l   d3,d4
        bcs.s   v41e_hr_not_late
        move.l  d4,d1
        sub.l   d3,d1
        beq.s   v41e_hr_not_late
        addq.l  #1,vpv98_timer_late_count
        bsr     vpv150_record_lateness
        cmp.l   vpv98_timer_max_late_us,d1
        bls.s   v41e_hr_not_late
        move.l  d1,vpv98_timer_max_late_us
v41e_hr_not_late:
        bsr     v41e_hr_next_interval
        add.l   d0,v41e_hr_target
        addq.l  #1,v04_paced_frames
v41e_hr_done:
        movem.l (sp)+,d1-d4
        rts

; --------------------------------------------------------------------
; VPv150 - classify actual deadline misses.
; D1 = lateness in microseconds (>0).  This is diagnostics only.
; Preserve D0 so the established pacing path stays bit-for-bit semantic.
; --------------------------------------------------------------------
vpv150_record_lateness:
        movem.l d0,-(sp)
        cmpi.l  #1000,d1
        bls.s   vpv150_late_no_1ms
        addq.l  #1,vpv150_late_gt1ms
vpv150_late_no_1ms:
        cmpi.l  #5000,d1
        bls.s   vpv150_late_no_5ms
        addq.l  #1,vpv150_late_gt5ms
vpv150_late_no_5ms:
        move.l  v41e_hr_step_num,d0
        tst.l   d0
        beq.s   vpv150_late_done
        cmp.l   d0,d1
        bls.s   vpv150_late_done
        addq.l  #1,vpv150_late_gt_frame
vpv150_late_done:
        movem.l (sp)+,d0
        rts

; --------------------------------------------------------------------
; VPv72 - nonblocking test for whether the next video access unit is due.
;
; Return D0=1 when feeding the next paced video AU will NOT busy-wait.
; Return D0=0 while the next deadline is still in the future.
; The helper samples only the active timing clock state; it never feeds
; video, touches BULK ownership, or changes the established RR turn.
; --------------------------------------------------------------------
vpv72_video_due_now:
        movem.l d1,-(sp)
        tst.l   v32r_fastforward
        bne.s   vpv72_video_due_yes
        cmpi.l  #3,v41_display_style
        beq.s   vpv72_video_due_hr

        tst.l   v04_clock_started
        beq.s   vpv72_video_due_yes
        ; VPv174: P96 target is now exact microseconds, not 50-Hz ticks.
        bsr     vpv98_read_sys_us
        sub.l   vpv98_timer_base_us,d0
        cmp.l   v04_clock_target,d0
        bcc.s   vpv72_video_due_yes
        moveq   #0,d0
        bra.s   vpv72_video_due_done

vpv72_video_due_hr:
        tst.l   v41e_hr_started
        beq.s   vpv72_video_due_yes
        bsr     v41e_hr_clock_poll
        cmp.l   v41e_hr_target,d0
        bcc.s   vpv72_video_due_yes
        moveq   #0,d0
        bra.s   vpv72_video_due_done

vpv72_video_due_yes:
        moveq   #1,d0
vpv72_video_due_done:
        movem.l (sp)+,d1
        rts

; --------------------------------------------------------------------
; VPv156 - hybrid deadline gate for the central dispatcher.
;
; P96/legacy scheduler-backed paths keep the exact VPv72 due test.
; Direct C/Modus-3 returns D0=1 up to 5000 us BEFORE the absolute
; deadline, so the proven v41e_hr_pace_new_frame performs only the final
; short precision wait. This keeps Audio/VCHIQ service alive for most of
; the ~41.7-ms frame interval without accepting the coarse central-poll
; overshoot measured by VPv155. No target/accumulator is advanced here.
; --------------------------------------------------------------------
vpv156_video_due_dispatch:
        cmpi.l  #3,v41_display_style
        bne.w   vpv72_video_due_now
        movem.l d1,-(sp)
        tst.l   v32r_fastforward
        bne.s   vpv156_video_due_yes
        tst.l   v41e_hr_started
        beq.s   vpv156_video_due_yes
        bsr     v41e_hr_clock_poll
        cmp.l   v41e_hr_target,d0
        bcc.s   vpv156_video_due_yes
        move.l  v41e_hr_target,d1
        sub.l   d0,d1
        cmpi.l  #5000,d1
        bhi.s   vpv156_video_due_no
        addq.l  #1,vpv156_c_lead_entries
vpv156_video_due_yes:
        moveq   #1,d0
        bra.s   vpv156_video_due_done
vpv156_video_due_no:
        moveq   #0,d0
vpv156_video_due_done:
        movem.l (sp)+,d1
        rts

; --------------------------------------------------------------------
; mkvr7 - bounded TRUE feed-ahead gate for direct C scheduler mode.
;
; Fresh Matroska access units may occupy at most three of the four normal
; H264 input slots. Continuation fragments of an already-started Matroska
; AVC block are always allowed so a large frame cannot be stranded.
; Presentation remains owned by the VideoCore scheduler + Audio-Master clock.
;
; Return D0=1 feed may proceed, D0=0 defer this fresh AU.
; --------------------------------------------------------------------
vpv167_feedahead_can_feed:
        movem.l d1,-(sp)
        tst.l   vpv166_c_sched_feedahead
        beq.s   vpv167_feedahead_yes
        tst.l   v10b_input_is_mkv
        beq.s   vpv167_feedahead_yes
        tst.l   v10b_block_remaining
        bne.s   vpv167_feedahead_continuation
        tst.l   v10b_nal_remaining
        bne.s   vpv167_feedahead_continuation

vpv179_feedahead_fresh:
        move.l  input_in_use_count,d1
        cmpi.l  #VPV167_FEEDAHEAD_FRESH_CAP,d1
        bcs.s   vpv167_feedahead_yes
        addq.l  #1,vpv167_feedahead_cap_blocks
        moveq   #0,d0
        bra.s   vpv167_feedahead_done
vpv167_feedahead_continuation:
        addq.l  #1,vpv167_feedahead_cont_bypass
vpv167_feedahead_yes:
        moveq   #1,d0
vpv167_feedahead_done:
        movem.l (sp)+,d1
        rts

; --------------------------------------------------------------------
; VPv157 - safe window for synchronous CPU1/FAAD predecode.
;
; CPU1 normally replies in the fast coherent-poll phase, but a slow reply
; falls back to DOS Delay(1), which can block the 68k dispatcher for roughly
; one OS tick.  In direct C mode launch that optional future-audio decode only
; when >=30000 us remain before the next video deadline.  If the deadline is
; due/late, or the remaining window is smaller, defer: existing renderer-owned
; PCM buffers provide hundreds of milliseconds of audio reserve.
; D0=1 safe to launch optional FAAD predecode now, D0=0 defer.
; No timer target or audio/video PTS state is changed.
; --------------------------------------------------------------------
vpv157_audio_decode_safe_now:
        movem.l d1,-(sp)
        cmpi.l  #3,v41_display_style
        bne.s   vpv157_audio_decode_safe_yes
        tst.l   v32r_fastforward
        bne.s   vpv157_audio_decode_safe_yes
        tst.l   v41e_hr_started
        beq.s   vpv157_audio_decode_safe_yes
        bsr     v41e_hr_clock_poll
        cmp.l   v41e_hr_target,d0
        bcc.s   vpv157_audio_decode_safe_no
        move.l  v41e_hr_target,d1
        sub.l   d0,d1
        cmpi.l  #30000,d1
        bcs.s   vpv157_audio_decode_safe_no
vpv157_audio_decode_safe_yes:
        moveq   #1,d0
        bra.s   vpv157_audio_decode_safe_done
vpv157_audio_decode_safe_no:
        moveq   #0,d0
vpv157_audio_decode_safe_done:
        movem.l (sp)+,d1
        rts

; VPv157 timing wrapper for the unchanged BerryFAAD03 predecode routine.
; D0 retains vpv45_prefetch_live_pcm status. Diagnostics only.
vpv157_audio_decode_timed:
        movem.l d1-d2/d7,-(sp)
        bsr     vpv98_read_sys_us
        move.l  d0,d2
        jsr     vpv45_prefetch_live_pcm
        move.l  d0,d7
        bsr     vpv98_read_sys_us
        sub.l   d2,d0
        addq.l  #1,vpv157_audio_decode_calls
        add.l   d0,vpv157_audio_decode_total_us
        cmp.l   vpv157_audio_decode_max_us,d0
        bls.s   vpv157_audio_decode_no_max
        move.l  d0,vpv157_audio_decode_max_us
vpv157_audio_decode_no_max:
        cmpi.l  #20000,d0
        bls.s   vpv157_audio_decode_no_20ms
        addq.l  #1,vpv157_audio_decode_gt20ms
vpv157_audio_decode_no_20ms:
        move.l  v41e_hr_step_num,d1
        tst.l   d1
        beq.s   vpv157_audio_decode_time_done
        cmp.l   d1,d0
        bls.s   vpv157_audio_decode_time_done
        addq.l  #1,vpv157_audio_decode_gtframe
vpv157_audio_decode_time_done:
        move.l  d7,d0
        movem.l (sp)+,d1-d2/d7
        rts

; ====================================================================
; VPv21T PRELOG PROOF
; Exact same DOS sequence as the separately hardware-proven WriteTest:
;   Open sd0:log/resvpv183mkv.txt (MODE_NEWFILE) -> Write -> Flush -> Close.
; This runs before ANY AAC/MMAL/VCHIQ/large-memory setup.  A one-second
; Delay follows Close so the filesystem/device gets time to commit the new
; directory entry before the dangerous A/V path begins.
; ====================================================================
vpv21i_prelog_create:
        movem.l d0-d7/a0-a2/a6,-(sp)
        clr.l   vpv21i_prelog_ok

        move.l  a5,a6
        lea     vpv21f_log_name,a0
        move.l  a0,d1
        move.l  #MODE_NEWFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.s   vpv21i_prelog_done
        move.l  d0,d5

        move.l  d5,d1
        lea     msg_vpv21i_prelog,a0
        move.l  a0,d2
        move.l  #msg_vpv21i_prelog_end-msg_vpv21i_prelog,d3
        move.l  a5,a6
        jsr     Write(a6)
        cmp.l   #msg_vpv21i_prelog_end-msg_vpv21i_prelog,d0
        bne.s   vpv21i_prelog_close

        move.l  d5,d1
        move.l  a5,a6
        jsr     Flush(a6)
        move.l  #1,vpv21i_prelog_ok

vpv21i_prelog_close:
        move.l  d5,d1
        move.l  a5,a6
        jsr     Close(a6)

        ; Give FFS/device caching time to commit before A/V can crash.
        moveq   #50,d1
        move.l  a5,a6
        jsr     Delay(a6)

vpv21i_prelog_done:
        movem.l (sp)+,d0-d7/a0-a2/a6
        rts

h264rgb_main:
        movem.l d2-d7/a2-a6,-(sp)
        ; VPv102: permanent tail-safety anchors. close_prog is reached only by
        ; BRA/JMP from this frame, so this SP is the exact movem restore point.
        move.l  sp,vpv102_main_frame_sp

        ; Preserve AmigaDOS command line before any library call clobbers D0/A0.
        move.l  d0,h264rgb_cli_len
        move.l  a0,h264rgb_cli_ptr

        ; mkvr7: T: owns a true Matroska media-time target, separate
        ; from the legacy frame-count restart/resume mechanism.
        clr.l   v40j_time_seek_active
        clr.l   v40j_time_target_ticks
        clr.l   v40j_time_target_us_lo
        clr.l   v40j_time_target_us_hi
        clr.l   v40j_time_target_input_count
        clr.l   v40j_time_target_input_valid
        clr.l   v40j_time_video_start_ticks
        clr.l   v40j_time_latest_video_ticks
        clr.l   v40j_time_latest_video_valid
        clr.l   v005r5_seek_valid
        clr.l   v005r5_seek_primed
        clr.l   v005r5_seek_request_ticks
        clr.l   v005r5_seek_pts_ticks
        clr.l   v005r5_seek_payload_pos
        clr.l   v005r5_seek_payload_len
        clr.l   v005r5_seek_cluster_end
        clr.l   v005r5_seek_blockgroup_end
        clr.l   v005r5_seek_cluster_tc
        clr.l   v005r5_seek_segment_end

        move.l  4.w,a4
        move.l  a4,vpv102_saved_exec_base
        move.l  a4,a6
        lea     dosname,a1
        jsr     OldOpenLibrary(a6)
        tst.l   d0
        bne.s   h264rgb_dos_open_ok_v32
        jmp     exit_prog
h264rgb_dos_open_ok_v32:
        move.l  d0,a5
        move.l  a5,vpv102_saved_dos_base

        ; V40: a state file is consumed only by an armed restart cycle.
        ; A normal fresh launch removes any stale file left by a crash/reboot.
        tst.l   v32r_restart_cycle
        bne.s   v32r_keep_restart_state
        jsr     v32r_delete_state
v32r_keep_restart_state:

        move.l  a5,a6
        jsr     Output(a6)
        move.l  d0,d4
        move.l  d0,h264rgb_output_handle
        bne.s   v32r_output_handle_ok
        jmp     close_prog
v32r_output_handle_ok:
        ; mkvr7: logging is opt-in. Parse before the first diagnostic line.
        ;   no log token -> quiet, only critical FEHLER/ERROR/ABBRUCH to Shell
        ;   log          -> full diagnostics to Shell
        ;   log:file.txt -> full diagnostics to file only
        clr.l   vpv21f_log_handle
        jsr     mkvr7_parse_log_arg
        tst.l   d0
        beq.s   mkvr7_log_arg_ok
        lea     msg_mkvr7_bad_log,a1
        move.l  #msg_mkvr7_bad_log_end-msg_mkvr7_bad_log,d3
        jsr     print
        jmp     vpv19_cli_fail_exit
mkvr7_log_arg_ok:
        jsr     mkvr7_open_log
        tst.l   d0
        beq.s   mkvr7_log_open_ok
        ; mkvr7_open_log fell back to quiet mode, so this critical line is
        ; deliberately visible in the Shell. Playback may still continue.
        lea     msg_mkvr7_log_open_fail,a1
        move.l  #msg_mkvr7_log_open_fail_end-msg_mkvr7_log_open_fail,d3
        jsr     print
mkvr7_log_open_ok:
        lea     msg_vpv21n_trace_start,a1
        move.l  #msg_vpv21n_trace_start_end-msg_vpv21n_trace_start,d3
        jsr     vpv21n_trace
        jmp     vpv19_cli_entry

        ; V1 change: filename comes from the AmigaDOS command line.
        bsr     h264rgb_parse_arg
        tst.l   d0
        beq.s   h264rgb_arg_ok

        lea     msg_usage,a1
        move.l  #msg_usage_end-msg_usage,d3
        jsr     print_force

        ; Nothing has been allocated yet, so usage can exit directly.
        jsr     mkvr7_close_log
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

h264rgb_arg_ok:
        ; VPr8: R/resume is resolved before any MMAL/VCHIQ setup.  The .t file
        ; may live on the same device as the movie (including USB:).
        clr.l   vpr8_cli_w_explicit
        jsr     vpr8_parse_resume_arg
        tst.l   vpr8_resume_requested
        beq.s   vpr8_resume_ready
        jsr     vpr8_load_resume_file
        tst.l   d0
        beq.s   vpr8_resume_ready
        cmpi.l  #1,d0
        bne.s   vpr8_resume_bad_file
        lea     msg_vpr8_resume_missing,a1
        move.l  #msg_vpr8_resume_missing_end-msg_vpr8_resume_missing,d3
        jsr     vpr8_print_resume_error_path
        bra.s   vpr8_resume_abort
vpr8_resume_bad_file:
        lea     msg_vpr8_resume_invalid,a1
        move.l  #msg_vpr8_resume_invalid_end-msg_vpr8_resume_invalid,d3
        jsr     vpr8_print_resume_error_path
vpr8_resume_abort:
        jsr     mkvr7_close_log
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts
vpr8_resume_ready:

        ; V40J: optional start geometry token. Missing token defaults to g25.
        jsr     v40j_parse_size_arg
        tst.l   d0
        beq.s   h264rgb_size_arg_ok
        lea     msg_v40j_bad_size,a1
        move.l  #msg_v40j_bad_size_end-msg_v40j_bad_size,d3
        jsr     print
        lea     msg_usage,a1
        move.l  #msg_usage_end-msg_usage,d3
        jsr     print_force
        jsr     mkvr7_close_log
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts
h264rgb_size_arg_ok:
        ; mkvr7: legacy size parsing only consumes the first optional
        ; token. Scan explicit W: anywhere so T:1 W:C and W:C T:1 match.
        jsr     v005r4_parse_w_anywhere
        tst.l   d0
        beq.s   v005r4_w_anywhere_ok
        lea     msg_v40j_bad_size,a1
        move.l  #msg_v40j_bad_size_end-msg_v40j_bad_size,d3
        jsr     print
        lea     msg_usage,a1
        move.l  #msg_usage_end-msg_usage,d3
        jsr     print_force
        jsr     mkvr7_close_log
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts
v005r4_w_anywhere_ok:
        ; v005: optionaler T:-Start-Zeit-Token (T:MM / T:MM:SS / T:HH:MM:SS),
        ; kann vor oder nach dem Groessen-Token stehen. Fehlt er, bleibt
        ; v40j_start_time_valid=0 und es aendert sich nichts am Verhalten.
        jsr     v40j_parse_time_arg
        tst.l   d0
        beq.s   h264rgb_time_arg_ok
        lea     msg_v40j_bad_time,a1
        move.l  #msg_v40j_bad_time_end-msg_v40j_bad_time,d3
        jsr     print
        lea     msg_usage,a1
        move.l  #msg_usage_end-msg_usage,d3
        jsr     print_force
        jsr     mkvr7_close_log
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts
h264rgb_time_arg_ok:
        ; VPr8: file values are defaults. Explicit CLI T:/W: already parsed
        ; above and therefore win over the .t bookmark.
        jsr     vpr8_apply_resume_defaults

        ; V14: discard a stale break from before program start. Any Ctrl-C
        ; received after this point remains pending until the streaming poll sees it.
        clr.l   v15_stop_requested
        bsr     v15_clear_ctrl_c

        ; V10P: bounded-memory live MKV demux.  The V10F metadata probe still
        ; reads only a fixed 2-MiB window to discover Tracks/avcC.  During actual
        ; playback h22_load_frame_data converts only the selected AVC blocks
        ; directly into the 256-KiB MMAL input slot.  No whole-file buffer and
        ; no temporary Annex-B file are created.
        clr.l   v10b_input_is_mkv
h264rgb_check_mkv:
        jsr     v10_is_mkv
        tst.l   d0
        beq.w   h264rgb_raw_prepare
        move.l  #1,v10b_input_is_mkv
        jsr     v10_mkv_probe
        tst.l   v10_h264_found
        beq.w   h264rgb_mkv_prepare_fail
        tst.l   v10_avcc_ok
        beq.w   h264rgb_mkv_prepare_fail
        tst.l   v10_video_track_num
        beq.w   h264rgb_mkv_prepare_fail
        lea     msg_v10b_stream_ready,a1
        move.l  #msg_v10b_stream_ready_end-msg_v10b_stream_ready,d3
        jsr     print
        bra.w   h264rgb_have_extradata

h264rgb_mkv_prepare_fail:
        lea     msg_v10b_prepare_fail,a1
        move.l  #msg_v10b_prepare_fail_end-msg_v10b_prepare_fail,d3
        jsr     print
        jsr     mkvr7_close_log
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

; V10P: early unsupported-stream exit. Nothing decoder-related has been
; allocated or started yet, therefore this is a normal shell return and does
; NOT require the persistent-VCHIQ/MMAL cleanup path or a reboot.
h264rgb_unsupported_exit:
        lea     msg_v10p_unsupported,a1
        move.l  #msg_v10p_unsupported_end-msg_v10p_unsupported,d3
        jsr     print
        move.l  t23_file_handle,d0
        beq.s   h264rgb_unsupported_file_closed
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
h264rgb_unsupported_file_closed:
        jsr     mkvr7_close_log
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

h264rgb_raw_prepare:
        ; Raw Annex-B keeps the hardware-proven V9M/V10F probe unchanged.
        bsr     h264rgb_load_file_extradata
        tst.l   d0
        beq.s   v32r_raw_extradata_ok
        jmp     close_prog
v32r_raw_extradata_ok:

h264rgb_have_extradata:
        ; For MKV, v10_parse_avcc already copied SPS/PPS into the same
        ; h264_file_extradata buffer and set h264_sps_ptr/h264_pps_ptr.
        jsr     v6_parse_sps_geometry
        tst.l   d0
        beq.s   v32r_sps_geometry_ok
        jmp     close_prog
v32r_sps_geometry_ok:
        ; V10P compatibility guard.  The exact SPS used by the known failing
        ; stream has now been hardware-tested through CONFIG removal, full-frame
        ; START|END input, 19 real host output buffers and a DPB-15 experiment.
        ; VideoCore still returns MMAL_ENOSPC before producing frame 0.  Reject
        ; this exact SPS BEFORE LUT allocation, VCHIQ_INIT or MMAL creation so
        ; the CLI returns cleanly and no reboot is required.  The bitstream is
        ; never modified.
        jsr     v10p_check_unsupported_sps
        tst.l   d0
        bne.w   h264rgb_unsupported_exit
        jsr     v7_setup_timing
        tst.l   d0
        beq.s   v40_timing_ok
        jmp     close_prog
v40_timing_ok:
        ; v005: T:-Sekunden erst jetzt in eine Ziel-Videoblockzahl umrechnen,
        ; da die Container/SPS-FPS (v7_fps_num/v7_fps_den) gerade erst
        ; feststehen. v40j_initial_cli_selector aktiviert damit spaeter den
        ; vorhandenen Restart/Fastforward-Mechanismus fuer den Kaltstart.
        bsr     v40j_apply_start_time
        bsr     v04_timing_reset

vpv01_vchiq_entry:
        ; VPv05 reuses only the hardware-proven VCHIQ/MMAL transport substrate.
        ; No video/HAM6/ISP state is required for this isolated HDMI-audio test.
        clr.l   v9m_ham_lut_ptr
        clr.l   v9m_edge_lut_ptr
        clr.l   v9m_state_lut_ptr
        lea     msg_hdmi_v40o_no_luts,a1
        move.l  #msg_hdmi_v40o_no_luts_end-msg_hdmi_v40o_no_luts,d3
        jsr     print

        lea     msg_vpv01_start,a1
        move.l  #msg_vpv01_start_end-msg_vpv01_start,d3
        jsr     print_force

        ; V12F: generic MMAL worker helpers default to local VCHIQ port 0.
        clr.l   v12f_local_port
        clr.l   v12f_local_bits

        ; V10: on a second CLI invocation, attach to the persistent VCHIQ
        ; transport and probe a fresh MMAL service on local port 1.
        jsr     v9d_try_attach
        tst.l   d0
        beq.s   v9d_first_start
        cmpi.l  #1,d0
        beq.s   v40c_attach_second
        jmp     v9d_attach_exit
v40c_attach_second:
        jsr     v9699_attach_board       ; v96.99: Pi 3 or CM4 also on attach
        jsr     v9d_second_start_probe
        tst.l   bvp_library_mode
        beq.s   v40c_attach_second_legacy
        rts
v40c_attach_second_legacy:
        jmp     v9d_attach_exit
v9d_first_start:

        ; HDMI_v41L: pure HDMI path. Do not allocate or touch the legacy HAM6
        ; Chip/Fast display buffers. The VBlank interrupt is used only as a
        ; 50-Hz timebase; t30_active_ptr remains zero, so its ISR never writes
        ; Amiga bitplane registers.
        clr.l   t30_frames_ptr
        clr.l   t30_chip_ptr
        clr.l   v9i_chip_alloc_base
        clr.l   t33_fast_ptr
        clr.l   t56_shadow_ptr
        lea     msg_hdmi_v40o_no_rgb_buffers,a1
        move.l  #msg_hdmi_v40o_no_rgb_buffers_end-msg_hdmi_v40o_no_rgb_buffers,d3
        jsr     print

        clr.l   t31s_display_started
        clr.l   t31s_vblank_installed
        clr.l   t31s_vblank_counter
        clr.l   t31s_pending_ptr
        clr.l   t31s_switch_vblank
        clr.l   t31s_pending_valid
        clr.l   t31s_next_switch_vblank
        clr.l   t8a_isr_late_promote
        clr.l   v7_sched_accum
        clr.l   t31s_missed_deadlines
        clr.l   t31x_slack1
        clr.l   t31x_slack2
        clr.l   t31x_slack3plus
        clr.l   t31x_at_target
        clr.l   t31x_past_target
        move.l  #-1,t31x_miss1_frame
        clr.l   t31x_miss1_target
        clr.l   t31x_miss1_current
        clr.l   t31x_miss1_delta
        move.l  #-1,t31x_miss2_frame
        clr.l   t31x_miss2_target
        clr.l   t31x_miss2_current
        clr.l   t31x_miss2_delta
        clr.l   t31x_max_past_delta
        clr.l   t31u_last_stream_end_vblank
        clr.l   t31u_gap_total
        clr.l   t31u_gap_max
        clr.l   t31u_gap_nonzero
        clr.l   t31u_buffer_total
        clr.l   t31u_buffer_max
        clr.l   t31u_buffer_nonzero
        clr.l   t31u_convert_total
        clr.l   t31u_convert_max
        clr.l   t31u_convert_nonzero
        clr.l   t31w_copy_total
        clr.l   t31w_copy_max
        clr.l   t31w_copy_nonzero
        clr.l   t56_dirty_long_total
        clr.l   t56_dirty_long_max
        clr.l   t57_early_release_total
        clr.l   t61_deferred_total
        clr.l   t61_slot0_frames
        clr.l   t61_slot1_frames
        clr.l   t63_preroll_ptr
        clr.l   t63_preroll_frames
        clr.l   t65_same_vblank_total
        clr.l   t65_same_vblank_late
        clr.l   t65_catchup_debt
        clr.l   t65_debt_added_total
        clr.l   t65_catchup_total
        clr.l   t65_debt_max
        clr.l   t66_current_slack
        clr.l   t66_catchup_deferred
        clr.l   t31u_post_total
        clr.l   t31u_post_max
        clr.l   t31u_post_nonzero
        clr.l   t31u_stage_start_vblank
        clr.l   t31u_run_start_vblank
        clr.l   t30_active_ptr
        clr.l   t30_display_ptr
        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        jsr     print

; --------------------------------------------------------------------
; 1. Allocate and initialize shared VCHIQ memory
; --------------------------------------------------------------------
        lea     msg_alloc,a1
        move.l  #msg_alloc_end-msg_alloc,d3
        jsr     print

        move.l  a4,a6
        move.l  #ALLOC_SIZE,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        bne.s   vpv76_alloc_ok
        jmp     fail_alloc
vpv76_alloc_ok:
        move.l  d0,slot_alloc

        add.l   #$00000fff,d0
        and.l   #$fffff000,d0
        move.l  d0,slot_ptr
        move.l  d0,a3

        move.l  a3,d6
        cmp.l   #$3f000000,d6
        bcs.s   vpv76_range_ok
        jmp     fail_range
vpv76_range_ok:
        or.l    #$c0000000,d6
        move.l  d6,slot_bus

        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        jsr     print

        lea     msg_layout,a1
        move.l  #msg_layout_end-msg_layout,d3
        jsr     print

        ; SlotZero header
        move.l  a3,a0
        move.l  #VCHIQ_MAGIC,d0
        jsr     store_le32

        ; version/version_min are u16 fields in little endian.
        ; For v8/min3 this produces bytes 08 00 03 00.
        move.b  #8,4(a3)
        move.b  #0,5(a3)
        move.b  #3,6(a3)
        move.b  #0,7(a3)

        lea     8(a3),a0
        move.l  #SLOTZERO_SIZE,d0
        jsr     store_le32

        lea     12(a3),a0
        move.l  #SLOT_SIZE,d0
        jsr     store_le32

        lea     16(a3),a0
        move.l  #MAX_SLOTS,d0
        jsr     store_le32

        lea     20(a3),a0
        move.l  #MAX_SIDE,d0
        jsr     store_le32

        ; Pi3 fragment area starts directly after the 65 slots.
        move.l  d6,d0
        add.l   #SLOT_MEM_SIZE,d0
        lea     24(a3),a0
        jsr     store_le32

        lea     28(a3),a0
        move.l  #64,d0
        jsr     store_le32

        ; VideoCore/master side: sync 1, data 2..32
        lea     MASTER_FIRST(a3),a0
        move.l  #2,d0
        jsr     store_le32
        lea     MASTER_LAST(a3),a0
        move.l  #32,d0
        jsr     store_le32
        lea     MASTER_SYNC(a3),a0
        move.l  #1,d0
        jsr     store_le32

        ; Host/slave side: sync 33, data 34..64
        lea     SLAVE_FIRST(a3),a0
        move.l  #34,d0
        jsr     store_le32
        lea     SLAVE_LAST(a3),a0
        move.l  #64,d0
        jsr     store_le32
        lea     SLAVE_SYNC(a3),a0
        move.l  #33,d0
        jsr     store_le32

        ; Host slot queue: 34..64
        lea     SLAVE_QUEUE(a3),a2
        move.l  #34,d5
        move.l  #30,d7
queue_init_loop:
        move.l  d5,d0
        jsr     bswap32
        move.l  d0,(a2)+
        addq.l  #1,d5
        dbra    d7,queue_init_loop

        lea     SLAVE_RECYCLEQ(a3),a0
        move.l  #31,d0
        jsr     store_le32

        ; Linux initializes local sync_release.fired = 1.
        lea     SLAVE_SYNCREL_F(a3),a0
        move.l  #1,d0
        jsr     store_le32

        lea     SLAVE_DEBUG0(a3),a0
        move.l  #11,d0
        jsr     store_le32

        ; Local sync slot 33 starts with PADDING. AllocMem CLEAR already
        ; gives msgid=0,size=0, so no extra writes are needed.

        ; Set local initialized last.
        lea     SLAVE_INIT(a3),a0
        move.l  #1,d0
        jsr     store_le32

        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        jsr     print

; --------------------------------------------------------------------
; 2. Verify DMA mapping and hand initial shared region to VideoCore
; --------------------------------------------------------------------
        lea     msg_dma,a1
        move.l  #msg_dma_end-msg_dma,d3
        jsr     print

        move.l  #DMA_MEM_SIZE,dma_len
        move.l  a3,a0
        lea     dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        move.l  d0,slot_phys

        move.l  dma_len,d1
        cmp.l   #DMA_MEM_SIZE,d1
        bcs.l   fail_dma_len

        cmp.l   slot_ptr,d0
        bne.l   fail_identity

        lea     msg_phys,a1
        move.l  #msg_phys_end-msg_phys,d3
        jsr     print
        move.l  slot_phys,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_bus,a1
        move.l  #msg_bus_end-msg_bus,d3
        jsr     print
        move.l  slot_bus,d0
        jsr     print_hex32
        jsr     newline

; --------------------------------------------------------------------
; 3. Build firmware property request
; --------------------------------------------------------------------
        lea     msg_prop,a1
        move.l  #msg_prop_end-msg_prop,d3
        jsr     print

        move.l  a4,a6
        move.l  #$200,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.l   fail_prop_alloc
        move.l  d0,prop_alloc

        add.l   #127,d0
        and.l   #$ffffff80,d0
        move.l  d0,prop_ptr
        move.l  d0,a2

        move.l  a2,a0
        move.l  #28,d0
        bsr     store_le32

        lea     4(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     8(a2),a0
        move.l  #$00048010,d0
        bsr     store_le32

        lea     12(a2),a0
        moveq   #4,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  slot_bus,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        move.l  #28,prop_len
        move.l  a2,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        move.l  d0,prop_phys

        cmp.l   prop_ptr,d0
        beq.s   vpv84_prop_identity_ok
        jmp     fail_prop_identity
vpv84_prop_identity_ok:

        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        bsr     print

; --------------------------------------------------------------------
; 4. VCHIQ_INIT via firmware property mailbox
; --------------------------------------------------------------------
        lea     msg_init,a1
        move.l  #msg_init_end-msg_init,d3
        bsr     print

        move.l  prop_phys,d0
        and.l   #$fffffff0,d0
        or.l    #MBOX_PROPERTY,d0
        move.l  d0,d5

        move.l  #TIMEOUT,d7
mbox_tx_wait:
        move.l  MBOX_STATUS,d0
        bsr     bswap32
        and.l   #MBOX_TX_FULL,d0
        beq.w   mbox_tx_ready
        subq.l  #1,d7
        bne.w   mbox_tx_wait
        jmp     fail_tx_timeout

mbox_tx_ready:
        move.l  d5,d0
        bsr     bswap32
        move.l  d0,MBOX_WRITE

        move.l  #TIMEOUT,d7
mbox_rx_wait:
        move.l  MBOX_STATUS,d0
        bsr     bswap32
        and.l   #MBOX_RX_EMPTY,d0
        beq.w   mbox_rx_ready
        subq.l  #1,d7
        bne.w   mbox_rx_wait
        jmp     fail_rx_timeout

mbox_rx_ready:
        move.l  MBOX_READ,d0
        bsr     bswap32
        move.l  d0,d5

        move.l  d5,d0
        and.l   #$f,d0
        cmp.l   #MBOX_PROPERTY,d0
        beq.w   mbox_got_prop
        subq.l  #1,d7
        bne.w   mbox_rx_wait
        bra.w   fail_rx_timeout

mbox_got_prop:
        move.l  #28,prop_len
        move.l  prop_ptr,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)

        move.l  prop_ptr,a0
        move.l  4(a0),d0
        bsr     bswap32
        cmp.l   #$80000000,d0
        bne.w   fail_fw_status

        move.l  20(a0),d0
        bsr     bswap32
        tst.l   d0
        bne.w   fail_channelbase

        lea     msg_init_ok,a1
        move.l  #msg_init_ok_end-msg_init_ok,d3
        bsr     print

        ; V10P: only now, after the exact same property-mailbox path has
        ; demonstrably succeeded, query ARM and VC memory one tag at a time.
        jsr     v10l_query_firmware_memory_after_init
        ; v96.89: Pi 3 (VC4) or Pi 4 / CM4 (VC6)? Board revision via mailbox.
        jsr     v89_detect_board

        ; N16: persist the *actual* firmware ARM/VC split reported by mailbox.
        ; This is directly relevant to MMAL_ENOSPC and survives a hard reset.
        move.l  v10k_query_result,d0
        lea     n16_pfx_mem_result,a1
        jsr     n15_log_hex32
        move.l  v10k_arm_base,d0
        lea     n16_pfx_arm_base,a1
        jsr     n15_log_hex32
        move.l  v10k_arm_size,d0
        lea     n16_pfx_arm_size,a1
        jsr     n15_log_hex32
        move.l  v10k_vc_base,d0
        lea     n16_pfx_vc_base,a1
        jsr     n15_log_hex32
        move.l  v10k_vc_size,d0
        lea     n16_pfx_vc_size,a1
        jsr     n15_log_hex32
        move.l  v10k_vc_size,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        lea     n16_pfx_vc_mib,a1
        jsr     n15_log_hex32

        ; N17: the old hardware-confirmed V12H/V13 path reproduced this exact
        ; first-AU MMAL_ENOSPC with 32 MiB VC RAM and succeeded with 64 MiB.
        ; Keep behavior unchanged, but make the active threshold explicit in
        ; the crash-persistent trace before any real H.264 AU is submitted.
        move.l  v10k_vc_size,d0
        cmpi.l  #$04000000,d0
        bcc.s   n17_vc64_ok
        lea     n17_msg_vc_low,a1
        jsr     n12_log
        bra.s   n17_vc64_done
n17_vc64_ok:
        lea     n17_msg_vc_ok,a1
        jsr     n12_log
n17_vc64_done:

; --------------------------------------------------------------------
; 5. Finish DMA phase, inspect VC/master shared state
; --------------------------------------------------------------------
        ; The shared block has been in a CachePreDMA phase since step 2.
        ; End it so CPU can safely observe VideoCore writes.
        bsr     dma_post_all

        ; Wait briefly for master.initialized if needed.
        move.l  #POLL_COUNT,d7
wait_master_init:
        move.l  slot_ptr,a0
        lea     MASTER_INIT(a0),a0
        bsr     load_le32
        tst.l   d0
        bne.w   master_is_ready

        bsr     dma_pre_all
        bsr     short_delay
        bsr     dma_post_all
        subq.l  #1,d7
        bne.w   wait_master_init
        bra.w   fail_master_init

master_is_ready:
        ; First invocation: publish the global VCHIQ slot block through a tiny
        ; persistent Exec resource. It is deliberately never removed/freed;
        ; firmware owns this transport until reboot.
        jsr     v9d_register_resource
        tst.l   d0
        bne.w   fail_v9d_resource

        lea     msg_master,a1
        move.l  #msg_master_end-msg_master,d3
        bsr     print

        lea     msg_master_init,a1
        move.l  #msg_master_init_end-msg_master_init,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_INIT(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        lea     msg_master_tx,a1
        move.l  #msg_master_tx_end-msg_master_tx,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,remote_tx_before
        bsr     print_hex32
        bsr     newline

        lea     msg_master_arm,a1
        move.l  #msg_master_arm_end-msg_master_arm,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,vc_armed
        bsr     print_hex32
        bsr     newline

        lea     msg_master_q0,a1
        move.l  #msg_master_q0_end-msg_master_q0,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a0
        bsr     load_le32
        move.l  d0,remote_slot0
        bsr     print_hex32
        bsr     newline

; --------------------------------------------------------------------
; 5a. Stabilization window after firmware VCHIQ_INIT.
;
; The sporadic failed boots show that master.initialized=1 and armed=1
; do not always mean that the VideoCore VCHIQ side is fully ready to
; process our CONNECT immediately. Give firmware 25 DOS ticks = 0.5 s.
;
; IMPORTANT: return shared memory to DMA ownership during Delay(), then
; reacquire it and refresh tx_pos / armed / fired before CONNECT.
; --------------------------------------------------------------------
        lea     msg_stabil_start,a1
        move.l  #msg_stabil_start_end-msg_stabil_start,d3
        bsr     print

        bsr     dma_pre_all

        move.l  a5,a6
        move.l  #25,d1
        tst.l   v32r_restart_armed
        beq.s   v40m_close_delay_ready
        ; V40M: a much larger gfull ISP graph is created immediately after this
        ; cleanup. Give firmware two seconds to retire service-owned ISP state.
        move.l  #100,d1
v40m_close_delay_ready:
        jsr     Delay(a6)

        bsr     dma_post_all

        lea     msg_stabil_tx,a1
        move.l  #msg_stabil_tx_end-msg_stabil_tx,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,remote_tx_before
        bsr     print_hex32
        bsr     newline

        lea     msg_stabil_arm,a1
        move.l  #msg_stabil_arm_end-msg_stabil_arm,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,vc_armed
        bsr     print_hex32
        bsr     newline

        lea     msg_stabil_fired,a1
        move.l  #msg_stabil_fired_end-msg_stabil_fired,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        bsr     load_le32
        move.l  d0,stabil_fired
        bsr     print_hex32
        bsr     newline

; --------------------------------------------------------------------
; 6. Check whether VideoCore CONNECT is ALREADY present.
; --------------------------------------------------------------------
        clr.l   remote_seen

        lea     msg_precheck,a1
        move.l  #msg_precheck_end-msg_precheck,d3
        bsr     print

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        lea     msg_master_tx,a1
        move.l  #msg_master_tx_end-msg_master_tx,d3
        bsr     print
        move.l  d5,d0
        bsr     print_hex32
        bsr     newline

        cmp.l   #8,d5
        bcs.w   pre_no_remote_yet

        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a0
        bsr     load_le32
        move.l  d0,remote_slot0

        lea     msg_rxslot,a1
        move.l  #msg_rxslot_end-msg_rxslot,d3
        bsr     print
        move.l  remote_slot0,d0
        bsr     print_hex32
        bsr     newline

        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_rx_slot
        cmp.l   #32,d0
        bhi.w   fail_rx_slot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0

        move.l  a0,a2
        bsr     load_le32
        move.l  d0,rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,rx_size

        lea     msg_rxid,a1
        move.l  #msg_rxid_end-msg_rxid,d3
        bsr     print
        move.l  rx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_rxsize,a1
        move.l  #msg_rxsize_end-msg_rxsize,d3
        bsr     print
        move.l  rx_size,d0
        bsr     print_hex32
        bsr     newline

        move.l  rx_msgid,d0
        cmp.l   #VCHIQ_MSG_CONNECT,d0
        bne.w   fail_wrong_msg

        move.l  rx_size,d0
        tst.l   d0
        bne.w   fail_wrong_size

        move.l  #1,remote_seen

        lea     msg_remote_ready,a1
        move.l  #msg_remote_ready_end-msg_remote_ready,d3
        bsr     print
        bra.w   queue_our_connect

pre_no_remote_yet:
        lea     msg_remote_later,a1
        move.l  #msg_remote_later_end-msg_remote_later,d3
        bsr     print

; --------------------------------------------------------------------
; 7. Queue OUR CONNECT in host slot 34.
; --------------------------------------------------------------------
queue_our_connect:
        ; One initial notification plus at most two re-notifications.
        ; IMPORTANT: the CONNECT message itself is written only once.
        move.l  #2,connect_retries

        lea     msg_connect,a1
        move.l  #msg_connect_end-msg_connect,d3
        bsr     print

        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0

        move.l  #VCHIQ_MSG_CONNECT,d0
        bsr     store_le32
        lea     4(a0),a0
        moveq   #0,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        moveq   #8,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        bsr     dma_pre_all

        move.l  vc_armed,d0
        tst.l   d0
        beq.w   connect_no_bell_a

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_bell,a1
        move.l  #msg_bell_end-msg_bell,d3
        bsr     print
        bra.w   after_notify_a

connect_no_bell_a:
        lea     msg_nobell,a1
        move.l  #msg_nobell_end-msg_nobell,d3
        bsr     print

after_notify_a:
        bsr     short_delay
        bsr     dma_post_all

        lea     msg_localtx,a1
        move.l  #msg_localtx_end-msg_localtx,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        lea     msg_fired_after,a1
        move.l  #msg_fired_after_end-msg_fired_after,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        tst.l   remote_seen
        bne.w   connect_success_a

; --------------------------------------------------------------------
; 8. If VC CONNECT was not present before our send, wait for it.
; --------------------------------------------------------------------
        lea     msg_wait,a1
        move.l  #msg_wait_end-msg_wait,d3
        bsr     print

        bsr     dma_pre_all
        move.l  #POLL_COUNT,d7

connect_poll_loop_a:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        cmp.l   #8,d0
        bcc.w   connect_response_seen_a

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   connect_poll_loop_a
        bra.w   fail_connect_timeout

connect_response_seen_a:
        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a0
        bsr     load_le32
        move.l  d0,remote_slot0

        lea     msg_rxslot,a1
        move.l  #msg_rxslot_end-msg_rxslot,d3
        bsr     print
        move.l  remote_slot0,d0
        bsr     print_hex32
        bsr     newline

        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_rx_slot
        cmp.l   #32,d0
        bhi.w   fail_rx_slot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0

        move.l  a0,a2
        bsr     load_le32
        move.l  d0,rx_msgid
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,rx_size

        lea     msg_rxid,a1
        move.l  #msg_rxid_end-msg_rxid,d3
        bsr     print
        move.l  rx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_rxsize,a1
        move.l  #msg_rxsize_end-msg_rxsize,d3
        bsr     print
        move.l  rx_size,d0
        bsr     print_hex32
        bsr     newline

        move.l  rx_msgid,d0
        cmp.l   #VCHIQ_MSG_CONNECT,d0
        bne.w   fail_wrong_msg

        move.l  rx_size,d0
        tst.l   d0
        bne.w   fail_wrong_size

connect_success_a:
        lea     msg_connect_ok,a1
        move.l  #msg_connect_ok_end-msg_connect_ok,d3
        bsr     print

; --------------------------------------------------------------------
; 9. Open the real MMAL control service.
;
; Linux VCHIQ open payload (12 bytes):
;   u32 fourcc, u32 client_id, u16 version, u16 version_min
; Official MMAL values: fourcc 'mmal', version 16, minimum 10.
;
; CONNECT consumed 8 bytes in host slot 34. OPEN stride is 24 bytes,
; so OPEN starts at slot 34 offset 8 and host tx_pos becomes 32.
; --------------------------------------------------------------------
        lea     msg_open,a1
        move.l  #msg_open_end-msg_open,d3
        bsr     print

        ; Slot 34 + offset 8.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  #8,a0

        ; Header: OPEN from local port 0, payload size 12.
        move.l  #VCHIQ_MSG_OPEN,d0
        bsr     store_le32
        lea     4(a0),a0
        move.l  #12,d0
        bsr     store_le32

        ; Payload fourcc.
        lea     4(a0),a0              ; now slot+16 = payload start
        move.l  #MMAL_FOURCC,d0
        bsr     store_le32

        ; client_id = 0.
        lea     4(a0),a0
        moveq   #0,d0
        bsr     store_le32

        ; u16 version=16, u16 version_min=10, little endian.
        lea     4(a0),a0
        move.b  #MMAL_VER,(a0)
        clr.b   1(a0)
        move.b  #MMAL_VER_MIN,2(a0)
        clr.b   3(a0)

        ; Publish total host stream position: 8 + 24 = 32.
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  #32,d0
        bsr     store_le32

        ; Signal VideoCore master trigger.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        ; Read current armed state before giving DMA ownership back.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,open_armed

        lea     msg_open_arm,a1
        move.l  #msg_open_arm_end-msg_open_arm,d3
        bsr     print
        move.l  open_armed,d0
        bsr     print_hex32
        bsr     newline

        bsr     dma_pre_all

        move.l  open_armed,d0
        tst.l   d0
        beq.w   open_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_open_bell,a1
        move.l  #msg_open_bell_end-msg_open_bell,d3
        bsr     print
        bra.w   open_wait_start

open_no_bell:
        lea     msg_open_nobell,a1
        move.l  #msg_open_nobell_end-msg_open_nobell,d3
        bsr     print

; --------------------------------------------------------------------
; 10. Wait for next VC message after CONNECT.
; The CONNECT occupies remote stream bytes 0..7. An OPENACK normally
; appears at slot 2 offset 8. RusPiRo shows OPENACK size=2 and the
; resulting remote tx_pos=24. A rejected OPEN may instead return CLOSE.
; --------------------------------------------------------------------
open_wait_start:
        lea     msg_open_wait,a1
        move.l  #msg_open_wait_end-msg_open_wait,d3
        bsr     print

        move.l  #POLL_COUNT,d7

open_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5
        cmp.l   #8,d5
        bhi.w   open_response_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   open_poll_loop
        bra.w   fail_open_timeout

open_response_seen:
        lea     msg_open_tx,a1
        move.l  #msg_open_tx_end-msg_open_tx,d3
        bsr     print
        move.l  d5,d0
        bsr     print_hex32
        bsr     newline

        ; Use first VC data slot, expected 2, and inspect offset 8.
        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a0
        bsr     load_le32
        move.l  d0,remote_slot0

        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_open_rxslot
        cmp.l   #32,d0
        bhi.w   fail_open_rxslot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  #8,a0

        move.l  a0,a2
        bsr     load_le32
        move.l  d0,open_msgid
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,open_size

        lea     msg_open_id,a1
        move.l  #msg_open_id_end-msg_open_id,d3
        bsr     print
        move.l  open_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_open_size,a1
        move.l  #msg_open_size_end-msg_open_size,d3
        bsr     print
        move.l  open_size,d0
        bsr     print_hex32
        bsr     newline

        ; Check message type first.
        move.l  open_msgid,d0
        and.l   #$FF000000,d0
        cmp.l   #VCHIQ_MSG_CLOSE,d0
        beq.w   fail_open_rejected
        cmp.l   #VCHIQ_MSG_OPENACK,d0
        bne.w   fail_open_wrongmsg

        ; OPENACK destination must be our local port 0.
        move.l  open_msgid,d0
        and.l   #$00000FFF,d0
        bne.w   fail_open_dstport

        ; Extract VideoCore remote source port.
        move.l  open_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000FFF,d0
        move.l  d0,mmal_remote_port

        lea     msg_open_port,a1
        move.l  #msg_open_port_end-msg_open_port,d3
        bsr     print
        move.l  mmal_remote_port,d0
        bsr     print_hex32
        bsr     newline

        ; OPENACK contains at least u16 peer version.
        move.l  open_size,d0
        cmp.l   #2,d0
        bcs.w   fail_open_short

        move.l  a2,a0
        adda.l  #8,a0
        bsr     load_le16
        move.l  d0,mmal_peer_ver

        lea     msg_open_ver,a1
        move.l  #msg_open_ver_end-msg_open_ver,d3
        bsr     print
        move.l  mmal_peer_ver,d0
        bsr     print_hex32
        bsr     newline

        ; We advertised compatibility down to worker version 10.
        move.l  mmal_peer_ver,d0
        cmp.l   #MMAL_VER_MIN,d0
        bcs.w   fail_open_version

        ; Save the current remote stream position. In the successful
        ; TEST11 run this was 0x18: CONNECT (8) + OPENACK (16).
        move.l  d5,mmal_rx_before

        lea     msg_open_success,a1
        move.l  #msg_open_success_end-msg_open_success,d3
        bsr     print

; --------------------------------------------------------------------
; 11. Send MMAL_WORKER_GET_VERSION as VCHIQ DATA.
;
; VCHIQ DATA msgid:
;   type DATA=5
;   source/local port = 0
;   destination/VC port = mmal_remote_port (TEST11 returned 0x55)
;
; MMAL payload is mmal_worker_version, 40 bytes:
;   0  magic          u32 = MMAL_MAGIC
;   4  msgid/type     u32 = GET_VERSION (3)
;   8  control_service u32 = 0
;  12  context/waiter u32 = test cookie
;  16  status         u32 = 0
;  20  dummy/padding  u32 = 0
;  24  flags          u32 = 0
;  28  major          u32 = 0 (reply field)
;  32  minor          u32 = 0 (reply field)
;  36  minimum        u32 = 0 (reply field)
;
; Local stream is currently at 32. DATA header 8 + payload 40 = 48,
; therefore new local tx_pos = 80 (0x50).
; --------------------------------------------------------------------
        lea     msg_getver,a1
        move.l  #msg_getver_end-msg_getver,d3
        bsr     print

        ; Host slot 34, stream offset 32.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  #32,a0
        move.l  a0,a2

        ; VCHIQ DATA msgid = 0x05000000 | remote_port.
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        move.l  d0,data_tx_msgid
        bsr     store_le32

        lea     4(a2),a0
        move.l  #40,d0
        bsr     store_le32

        ; MMAL worker payload starts at VCHIQ header + 8.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_GET_VERSION,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; control_service

        lea     20(a2),a0
        move.l  #MMAL_TEST_CONTEXT,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; status

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; dummy/padding

        lea     32(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; flags

        lea     36(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; major

        lea     40(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; minor

        lea     44(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; minimum

        lea     msg_data_txid,a1
        move.l  #msg_data_txid_end-msg_data_txid,d3
        bsr     print
        move.l  data_tx_msgid,d0
        bsr     print_hex32
        bsr     newline

        ; Publish local tx_pos 0x50.
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  #80,d0
        bsr     store_le32

        ; Signal VC.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,data_armed

        lea     msg_data_arm,a1
        move.l  #msg_data_arm_end-msg_data_arm,d3
        bsr     print
        move.l  data_armed,d0
        bsr     print_hex32
        bsr     newline

        ; Flush our DATA message to shared memory.
        bsr     dma_pre_all

        move.l  data_armed,d0
        tst.l   d0
        beq.w   data_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_data_bell,a1
        move.l  #msg_data_bell_end-msg_data_bell,d3
        bsr     print
        bra.w   data_wait_start

data_no_bell:
        lea     msg_data_nobell,a1
        move.l  #msg_data_nobell_end-msg_data_nobell,d3
        bsr     print

; --------------------------------------------------------------------
; 12. Wait for MMAL GET_VERSION reply.
; --------------------------------------------------------------------
data_wait_start:
        lea     msg_data_wait,a1
        move.l  #msg_data_wait_end-msg_data_wait,d3
        bsr     print

        move.l  #POLL_COUNT,d7

data_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5
        cmp.l   mmal_rx_before,d5
        bhi.w   data_response_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   data_poll_loop
        bra.w   fail_data_timeout

data_response_seen:
        ; This is the start position for the NEXT VideoCore reply.
        move.l  d5,comp_rx_before

        lea     msg_data_rxtx,a1
        move.l  #msg_data_rxtx_end-msg_data_rxtx,d3
        bsr     print
        move.l  d5,d0
        bsr     print_hex32
        bsr     newline

        ; Still in first VC data slot for this small test.
        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_data_rxslot
        cmp.l   #32,d0
        bhi.w   fail_data_rxslot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  mmal_rx_before,d0
        adda.l  d0,a0
        move.l  a0,a2

        ; VCHIQ DATA header.
        bsr     load_le32
        move.l  d0,data_rx_msgid
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,data_rx_size

        lea     msg_data_rxid,a1
        move.l  #msg_data_rxid_end-msg_data_rxid,d3
        bsr     print
        move.l  data_rx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_data_rxsize,a1
        move.l  #msg_data_rxsize_end-msg_data_rxsize,d3
        bsr     print
        move.l  data_rx_size,d0
        bsr     print_hex32
        bsr     newline

        ; Must be DATA.
        move.l  data_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   fail_data_wrongmsg

        ; Destination must be local port 0.
        move.l  data_rx_msgid,d0
        and.l   #$00000fff,d0
        bne.w   fail_data_dstport

        ; Source must be the VC MMAL service port from OPENACK.
        move.l  data_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   fail_data_srcport

        move.l  data_rx_size,d0
        cmp.l   #40,d0
        bcs.w   fail_data_short

        ; Parse MMAL worker reply.
        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,worker_magic

        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,worker_type

        lea     20(a2),a0
        bsr     load_le32
        move.l  d0,worker_context

        lea     24(a2),a0
        bsr     load_le32
        move.l  d0,worker_status

        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,worker_flags

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,worker_major

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,worker_minor

        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,worker_minimum

        lea     msg_worker_magic,a1
        move.l  #msg_worker_magic_end-msg_worker_magic,d3
        bsr     print
        move.l  worker_magic,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_type,a1
        move.l  #msg_worker_type_end-msg_worker_type,d3
        bsr     print
        move.l  worker_type,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_ctx,a1
        move.l  #msg_worker_ctx_end-msg_worker_ctx,d3
        bsr     print
        move.l  worker_context,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_status,a1
        move.l  #msg_worker_status_end-msg_worker_status,d3
        bsr     print
        move.l  worker_status,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_flags,a1
        move.l  #msg_worker_flags_end-msg_worker_flags,d3
        bsr     print
        move.l  worker_flags,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_major,a1
        move.l  #msg_worker_major_end-msg_worker_major,d3
        bsr     print
        move.l  worker_major,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_minor,a1
        move.l  #msg_worker_minor_end-msg_worker_minor,d3
        bsr     print
        move.l  worker_minor,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_min,a1
        move.l  #msg_worker_min_end-msg_worker_min,d3
        bsr     print
        move.l  worker_minimum,d0
        bsr     print_hex32
        bsr     newline

        ; Validate reply.
        move.l  worker_magic,d0
        cmp.l   #MMAL_MAGIC,d0
        bne.w   fail_worker_magic

        move.l  worker_type,d0
        cmp.l   #MMAL_GET_VERSION,d0
        bne.w   fail_worker_type

        move.l  worker_context,d0
        cmp.l   #MMAL_TEST_CONTEXT,d0
        bne.w   fail_worker_context

        move.l  worker_status,d0
        tst.l   d0
        bne.w   fail_worker_status

        move.l  worker_major,d0
        cmp.l   #MMAL_VER_MIN,d0
        bcs.w   fail_worker_version

        lea     msg_getver_success,a1
        move.l  #msg_getver_success_end-msg_getver_success,d3
        bsr     print

        ; VPv05: bridge the old fixed-offset first-start bootstrap to the
        ; generic V12A/V12F MMAL helpers used by the audio test.  The legacy
        ; bootstrap has just consumed GET_VERSION logically, but it has not yet
        ; initialised port_tx_pos/port_rx_pos.  Without this bridge the first
        ; audio COMPONENT_CREATE starts at stale stream position 0 and the RX
        ; parser sees an earlier short VCHIQ record (VPv03 stage 4).
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,port_tx_pos           ; expected 0x00000050 after GET_VERSION
        move.l  comp_rx_before,port_rx_pos ; first unread VC record begins here

        ; VPv21T: unlike the VPv05..20 audio-only branch, fall through to the
        ; original HDMI_v41L video component setup. Audio is queued only after
        ; the complete video graph is configured and before frame streaming.

; --------------------------------------------------------------------
; 13. COMPONENT_CREATE "ril.video_decode" (wire name)
;
; Official MMAL request payload:
;   u32 client_component
;   char name[128]
;   u32 pid
; = 136 bytes.
;
; MMAL header = 24 bytes, therefore MMAL DATA payload = 160 bytes.
; VCHIQ header = 8 bytes -> stream advance 168 bytes.
;
; Host stream before this request = 0x50 (80).
; New host tx_pos = 80 + 168 = 248 = 0xF8.
; --------------------------------------------------------------------
        lea     msg_comp_create,a1
        move.l  #msg_comp_create_end-msg_comp_create,d3
        bsr     print

        ; Host slot 34 + stream offset 0x50.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  #80,a0
        move.l  a0,a2

        ; VCHIQ DATA header -> destination MMAL VC port.
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        move.l  d0,comp_tx_msgid
        bsr     store_le32

        lea     4(a2),a0
        move.l  #160,d0
        bsr     store_le32

        ; MMAL worker header (24 bytes).
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_COMPONENT_CREATE,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; control_service

        lea     20(a2),a0
        move.l  #MMAL_COMP_CONTEXT,d0
        bsr     store_le32              ; synchronous context cookie

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; header status

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; padding

        ; Official host code sends its local MMAL_COMPONENT_T pointer here.
        ; For this bare-metal-style client we use a stable opaque cookie which
        ; VideoCore must only pass back to us in later events/callbacks.
        lea     32(a2),a0
        move.l  #MMAL_CLIENT_COMPONENT,d0
        bsr     store_le32

        ; Explicitly clear the 128-byte component name field.
        lea     36(a2),a0
        move.l  #31,d7
comp_name_clear_loop:
        clr.l   (a0)+
        dbra    d7,comp_name_clear_loop

        ; Copy NUL-terminated ASCII component name.
        lea     36(a2),a0
        lea     comp_name,a1
        move.l  #comp_name_end-comp_name-1,d7
comp_name_copy_loop:
        move.b  (a1)+,(a0)+
        dbra    d7,comp_name_copy_loop

        ; pid = 0
        lea     164(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     msg_comp_txid,a1
        move.l  #msg_comp_txid_end-msg_comp_txid,d3
        bsr     print
        move.l  comp_tx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_localpos,a1
        move.l  #msg_comp_localpos_end-msg_comp_localpos,d3
        bsr     print
        move.l  #$000000F8,d0
        bsr     print_hex32
        bsr     newline

        ; Publish local tx_pos = 0xF8.
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  #248,d0
        bsr     store_le32

        ; Signal VideoCore event.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,comp_armed

        lea     msg_comp_arm,a1
        move.l  #msg_comp_arm_end-msg_comp_arm,d3
        bsr     print
        move.l  comp_armed,d0
        bsr     print_hex32
        bsr     newline

        ; Flush complete shared-memory region before ringing VC.
        bsr     dma_pre_all

        move.l  comp_armed,d0
        tst.l   d0
        beq.w   comp_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_comp_bell,a1
        move.l  #msg_comp_bell_end-msg_comp_bell,d3
        bsr     print
        bra.w   comp_wait_start

comp_no_bell:
        lea     msg_comp_nobell,a1
        move.l  #msg_comp_nobell_end-msg_comp_nobell,d3
        bsr     print

; --------------------------------------------------------------------
; 14. Wait for COMPONENT_CREATE reply.
; --------------------------------------------------------------------
comp_wait_start:
        lea     msg_comp_wait,a1
        move.l  #msg_comp_wait_end-msg_comp_wait,d3
        bsr     print

        move.l  #POLL_COUNT,d7

comp_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   comp_rx_before,d5
        bhi.w   comp_response_seen

        ; Return shared region to VC before next polling interval.
        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   comp_poll_loop
        bra.w   fail_comp_timeout

comp_response_seen:
        ; Start position of the next VideoCore message.
        move.l  d5,port_rx_pos

        lea     msg_comp_rxtx,a1
        move.l  #msg_comp_rxtx_end-msg_comp_rxtx,d3
        bsr     print
        move.l  d5,d0
        bsr     print_hex32
        bsr     newline

        ; Response remains in the first VideoCore data slot.
        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_comp_rxslot
        cmp.l   #32,d0
        bhi.w   fail_comp_rxslot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  comp_rx_before,d0
        adda.l  d0,a0
        move.l  a0,a2

        ; VCHIQ header.
        bsr     load_le32
        move.l  d0,comp_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,comp_rx_size

        lea     msg_comp_rxid,a1
        move.l  #msg_comp_rxid_end-msg_comp_rxid,d3
        bsr     print
        move.l  comp_rx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_rxsize,a1
        move.l  #msg_comp_rxsize_end-msg_comp_rxsize,d3
        bsr     print
        move.l  comp_rx_size,d0
        bsr     print_hex32
        bsr     newline

        ; Must be VCHIQ DATA.
        move.l  comp_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   fail_comp_wrongmsg

        ; Destination local port must be 0.
        move.l  comp_rx_msgid,d0
        and.l   #$00000fff,d0
        bne.w   fail_comp_dstport

        ; Source must be our opened VideoCore MMAL port.
        move.l  comp_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   fail_comp_srcport

        ; Reply MMAL body: 24-byte header + 20-byte create_reply.
        move.l  comp_rx_size,d0
        cmp.l   #44,d0
        bcs.w   fail_comp_short

        ; MMAL header.
        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,comp_magic

        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,comp_type

        lea     20(a2),a0
        bsr     load_le32
        move.l  d0,comp_context

        lea     24(a2),a0
        bsr     load_le32
        move.l  d0,comp_hdr_status

        ; component_create_reply payload.
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,comp_reply_status

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,component_handle

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,component_inputs

        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,component_outputs

        lea     48(a2),a0
        bsr     load_le32
        move.l  d0,component_clocks

        ; Diagnostic output.
        lea     msg_comp_magic,a1
        move.l  #msg_comp_magic_end-msg_comp_magic,d3
        bsr     print
        move.l  comp_magic,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_type,a1
        move.l  #msg_comp_type_end-msg_comp_type,d3
        bsr     print
        move.l  comp_type,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_ctx,a1
        move.l  #msg_comp_ctx_end-msg_comp_ctx,d3
        bsr     print
        move.l  comp_context,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_hstatus,a1
        move.l  #msg_comp_hstatus_end-msg_comp_hstatus,d3
        bsr     print
        move.l  comp_hdr_status,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_rstatus,a1
        move.l  #msg_comp_rstatus_end-msg_comp_rstatus,d3
        bsr     print
        move.l  comp_reply_status,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_handle,a1
        move.l  #msg_comp_handle_end-msg_comp_handle,d3
        bsr     print
        move.l  component_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_inputs,a1
        move.l  #msg_comp_inputs_end-msg_comp_inputs,d3
        bsr     print
        move.l  component_inputs,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_outputs,a1
        move.l  #msg_comp_outputs_end-msg_comp_outputs,d3
        bsr     print
        move.l  component_outputs,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_clocks,a1
        move.l  #msg_comp_clocks_end-msg_comp_clocks,d3
        bsr     print
        move.l  component_clocks,d0
        bsr     print_hex32
        bsr     newline

        ; Validate synchronous MMAL reply.
        move.l  comp_magic,d0
        cmp.l   #MMAL_MAGIC,d0
        bne.w   fail_comp_magic

        move.l  comp_type,d0
        cmp.l   #MMAL_COMPONENT_CREATE,d0
        bne.w   fail_comp_type

        move.l  comp_context,d0
        cmp.l   #MMAL_COMP_CONTEXT,d0
        bne.w   fail_comp_context

        move.l  comp_hdr_status,d0
        tst.l   d0
        bne.w   fail_comp_hdr_status

        move.l  comp_reply_status,d0
        tst.l   d0
        bne.w   fail_comp_reply_status

        move.l  component_handle,d0
        tst.l   d0
        beq.w   fail_comp_handle

        lea     msg_comp_success,a1
        move.l  #msg_comp_success_end-msg_comp_success,d3
        bsr     print

        ; Host stream is at 0xF8 after COMPONENT_CREATE.
        move.l  #248,port_tx_pos

; --------------------------------------------------------------------
; 15. Query all four port classes which the official MMAL host code
;     queries after COMPONENT_CREATE.
; --------------------------------------------------------------------
        lea     msg_ports_start,a1
        move.l  #msg_ports_start_end-msg_ports_start,d3
        bsr     print

        lea     msg_port_control,a1
        move.l  #msg_port_control_end-msg_port_control,d3
        bsr     print
        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,control_port_handle

        lea     msg19c_control_enable,a1
        move.l  #msg19c_control_enable_end-msg19c_control_enable,d3
        bsr     print

        bsr     port_enable_control_current
        tst.l   d0
        bne.w   fail_control_enable_main

        lea     msg19c_control_action_ok,a1
        move.l  #msg19c_control_action_ok_end-msg19c_control_action_ok,d3
        bsr     print

        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,control_port_handle
        move.l  port_enabled,d0
        cmp.l   #1,d0
        bne.w   fail_control_enable_verify

        lea     msg19c_control_verify_ok,a1
        move.l  #msg19c_control_verify_ok_end-msg19c_control_verify_ok,d3
        bsr     print

        lea     msg_port_input,a1
        move.l  #msg_port_input_end-msg_port_input,d3
        bsr     print
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,input_port_handle

        move.l  port_buf_num,input_before_buf_num
        move.l  port_buf_size,input_before_buf_size

        lea     msg19c_format_prepare,a1
        move.l  #msg19c_format_prepare_end-msg19c_format_prepare,d3
        bsr     print

        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  bvp_video_encoding,port_fmt_encoding   ; MintVID VC1
        clr.l   port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        ; N16: mrberry supplies one complete MOV/MKV access unit per public
        ; SendVideo call and bvp_load_direct_packet maps it to FRAME_START|END.
        ; Therefore the MMAL compressed input format must be FRAMED as well.
        ; N14 inherited the raw-H264 UNFRAMED flag because bvp_library_mode
        ; clears v10b_input_is_mkv; that did not match the actual packet ABI.
        tst.l   bvp_library_mode
        bne.s   v107_first_fmt_framed
        tst.l   v10b_input_is_mkv
        beq.s   v10g_first_fmt_flags_done
v107_first_fmt_framed:
        move.l  #MMAL_ES_FORMAT_FLAG_FRAMED,port_fmt_flags
v10g_first_fmt_flags_done:
        move.l  h264_codec_config_len,d0
        move.l  d0,port_fmt_extra

        move.l  v6_src_aligned_w,port_video_width
        move.l  v6_src_aligned_h,port_video_height
        move.l  v6_src_crop_x,port_crop_x
        move.l  v6_src_crop_y,port_crop_y
        move.l  v6_src_visible_w,port_crop_width
        move.l  v6_src_visible_h,port_crop_height
        move.l  v7_fps_num,port_fps_num
        move.l  v7_fps_den,port_fps_den
        move.l  #1,port_par_num
        move.l  #1,port_par_den
        clr.l   port_color_space

        lea     input_extradata,a1
        moveq   #31,d7
t19c_extra_clear:
        clr.l   (a1)+
        dbra    d7,t19c_extra_clear

        lea     input_extradata,a1
        lea     h264_file_extradata,a0
        move.l  h264_codec_config_len,d7
        beq.s   t19c_extra_none                    ; MintVID VC1: none
        subq.l  #1,d7
t19c_extra_copy:
        move.b  (a0)+,(a1)+
        dbra    d7,t19c_extra_copy
t19c_extra_none:

        lea     msg19c_format_values,a1
        move.l  #msg19c_format_values_end-msg19c_format_values,d3
        bsr     print

        ; H264RGB4: codec extradata above is parsed SPS+PPS from the selected file.
        ; TEST33: commit the decoder-recommended input geometry instead of
        ; the TEST31D/E minimum 1 x 2048.  VideoCore reported 1 x 0x14000.
        move.l  #INPUT_PORT_BUFFER_COUNT,port_buf_num
        move.l  #INPUT_DATA_SIZE,port_buf_size

        lea     msg_set_start,a1
        move.l  #msg_set_start_end-msg_set_start,d3
        bsr     print

        bsr     port_info_set_input

        lea     msg19c_verify_input,a1
        move.l  #msg19c_verify_input_end-msg19c_verify_input,d3
        bsr     print

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get

        move.l  port_last_handle,d0
        cmp.l   input_port_handle,d0
        bne.w   fail_verify_input

        move.l  port_fmt_type,d0
        cmp.l   #MMAL_ES_VIDEO,d0
        bne.w   fail_verify_h264
        move.l  port_fmt_encoding,d0
        cmp.l   bvp_video_encoding,d0             ; MintVID VC1
        bne.w   fail_verify_h264

        move.l  port_fmt_flags,d0
        and.l   #MMAL_ES_FORMAT_FLAG_FRAMED,d0
        tst.l   bvp_library_mode
        bne.s   v107_first_verify_framed
        tst.l   v10b_input_is_mkv
        beq.s   v10g_first_verify_unframed
v107_first_verify_framed:
        cmpi.l  #MMAL_ES_FORMAT_FLAG_FRAMED,d0
        bne.w   fail_verify_h264
        bra.s   v10g_first_verify_flags_ok
v10g_first_verify_unframed:
        tst.l   d0
        bne.w   fail_verify_h264
v10g_first_verify_flags_ok:

        ; V41I: firmware may normalize aligned geometry/crop/PAR/extradata.
        ; Heidi 956x720 is returned as frame 956x720 although our DMA-side
        ; alignment is 960x720. Identity/encoding/framing/buffer capacity stay strict.
        move.l  port_buf_num,d0
        cmp.l   #INPUT_PORT_BUFFER_COUNT,d0
        bcs.w   fail_verify_input
        move.l  port_buf_size,d0
        cmp.l   #H264_MAX_DATA_LEN,d0
        bcs.w   fail_verify_input

        ; N16: persist the decoder compressed-input contract after SET/readback.
        move.l  port_fmt_flags,d0
        lea     n15_pfx_in_flags,a1
        jsr     n15_log_hex32
        move.l  port_buf_num,d0
        lea     n15_pfx_in_num,a1
        jsr     n15_log_hex32
        move.l  port_buf_size,d0
        lea     n15_pfx_in_size,a1
        jsr     n15_log_hex32

        move.l  port_buf_num,input_before_buf_num
        move.l  port_buf_size,input_before_buf_size
        move.l  port_fmt_extra,input_before_extra

        lea     msg19c_format_verified,a1
        move.l  #msg19c_format_verified_end-msg19c_format_verified,d3
        bsr     print

        lea     msg_port_output,a1
        move.l  #msg_port_output_end-msg_port_output,d3
        bsr     print
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,output_port_handle

        lea     msg_port_clock,a1
        move.l  #msg_port_clock_end-msg_port_clock,d3
        bsr     print
        move.l  #MMAL_PORT_CLOCK,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,clock_port_handle

        lea     msg_ports_summary,a1
        move.l  #msg_ports_summary_end-msg_ports_summary,d3
        bsr     print

        lea     msg_sum_control,a1
        move.l  #msg_sum_control_end-msg_sum_control,d3
        bsr     print
        move.l  control_port_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_sum_input,a1
        move.l  #msg_sum_input_end-msg_sum_input,d3
        bsr     print
        move.l  input_port_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_sum_output,a1
        move.l  #msg_sum_output_end-msg_sum_output,d3
        bsr     print
        move.l  output_port_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_sum_clock,a1
        move.l  #msg_sum_clock_end-msg_sum_clock,d3
        bsr     print
        move.l  clock_port_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_ports_success,a1
        move.l  #msg_ports_success_end-msg_ports_success,d3
        bsr     print

        ; VPv21T ISOLATION TEST: keep the exact AAC extraction + Helix predecode
        ; and the small PCM allocation, but DO NOT create/configure audio_render.
        ; If HDMI_v41L video is stable here, the host AAC/predecode/memory path is
        ; innocent and the fault begins only when a second MMAL audio component
        ; shares the service/worker RX stream.
        clr.l   vpv21_audio_prepared
        lea     msg_vpv21p_audio_skipped,a1
        move.l  #msg_vpv21p_audio_skipped_end-msg_vpv21p_audio_skipped,d3
        jsr     vpv21n_trace

; --------------------------------------------------------------------
; 18. Re-read INPUT 0 so port_* globals describe exactly this port,
;     then enable it with MMAL PORT_ACTION / ENABLE.
; --------------------------------------------------------------------
        lea     msg_enable_start,a1
        move.l  #msg_enable_start_end-msg_enable_start,d3
        bsr     print

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get

        move.l  port_last_handle,d0
        cmp.l   input_port_handle,d0
        bne.w   fail_enable_main

        lea     msg_enable_before,a1
        move.l  #msg_enable_before_end-msg_enable_before,d3
        bsr     print
        move.l  port_enabled,d0
        bsr     print_hex32
        bsr     newline

        bsr     port_enable_current
        tst.l   d0
        bne.w   fail_enable_main

        lea     msg_enable_action_ok,a1
        move.l  #msg_enable_action_ok_end-msg_enable_action_ok,d3
        bsr     print

; --------------------------------------------------------------------
; 19. Verify INPUT 0 reports enabled=1.
; --------------------------------------------------------------------
        lea     msg_enable_verify,a1
        move.l  #msg_enable_verify_end-msg_enable_verify,d3
        bsr     print

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get

        move.l  port_enabled,d0
        cmp.l   #1,d0
        bne.w   fail_enable_verify

        move.l  port_fmt_type,d0
        cmp.l   #MMAL_ES_VIDEO,d0
        bne.w   fail_enable_verify

        move.l  port_fmt_encoding,d0
        cmp.l   bvp_video_encoding,d0             ; MintVID VC1
        bne.w   fail_enable_verify

        lea     msg_enable_verify_ok,a1
        move.l  #msg_enable_verify_ok_end-msg_enable_verify_ok,d3
        bsr     print

; --------------------------------------------------------------------
; V12A. Decoder OUTPUT is no longer copied to host memory at source size.
; Build a VideoCore-only tunnel:
;   ril.video_decode OUTPUT -> ril.isp INPUT -> 192xN I420 OUTPUT -> host
; The old HAM6 scaler still receives an ordinary small I420 frame.
; --------------------------------------------------------------------
        lea     msg_v12a_graph_start,a1
        move.l  #msg_v12a_graph_start_end-msg_v12a_graph_start,d3
        bsr     print
        lea     msg_vpv21p_graph_before,a1
        move.l  #msg_vpv21p_graph_before_end-msg_vpv21p_graph_before,d3
        jsr     vpv21n_trace
        jsr     n79p_setup_graph_router
        tst.l   d0
        bne.w   vpv21p_graph_failed
        lea     msg_vpv21p_graph_after_ok,a1
        move.l  #msg_vpv21p_graph_after_ok_end-msg_vpv21p_graph_after_ok,d3
        jsr     vpv21n_trace
        bra.s   vpv21p_graph_return_ok
vpv21p_graph_failed:
        lea     msg_vpv21p_graph_after_fail,a1
        move.l  #msg_vpv21p_graph_after_fail_end-msg_vpv21p_graph_after_fail,d3
        jsr     vpv21n_trace
        bra.w   fail_output_enable_main
vpv21p_graph_return_ok:

        ; HDMI_v41L: no host I420/HAM6 output exists, so the old 192x144
        ; scaler/map preparation is intentionally skipped.

; --------------------------------------------------------------------
; 22. Enable decoder component.
; --------------------------------------------------------------------
        lea     msg_component_enable,a1
        move.l  #msg_component_enable_end-msg_component_enable,d3
        bsr     print

        bsr     component_enable_worker
        tst.l   d0
        bne.w   fail_component_enable_main

        lea     msg_component_enable_ok,a1
        move.l  #msg_component_enable_ok_end-msg_component_enable_ok,d3
        bsr     print

        tst.l   bvp_library_mode
        bne.w   bvp_first_video_ready

        ; VPv36 isolation stage: prove that a SECOND MMAL component can coexist
        ; on the same already-open MMAL service without configuring any audio
        ; ports and without sending PCM. This is deliberately one step beyond T.
        move.l  component_handle,vpv21_saved_component
        move.l  input_port_handle,vpv21_saved_input
        move.l  port_query_index,vpv21_saved_port_qidx
        move.l  port_buf_size,vpv21_saved_port_buf_size

        lea     msg_vpv21u_create_begin,a1
        move.l  #msg_vpv21u_create_begin_end-msg_vpv21u_create_begin,d3
        jsr     vpv21n_trace
        jsr     vpv01_create_audio_render
        move.l  d0,d7

        ; Restore the live video decoder globals immediately. The audio handle
        ; remains only in vpv01_audio_handle; no audio PORT_INFO_* is executed.
        move.l  vpv21_saved_component,component_handle
        move.l  vpv21_saved_input,input_port_handle
        move.l  vpv21_saved_port_qidx,port_query_index
        move.l  vpv21_saved_port_buf_size,port_buf_size

        tst.l   d7
        bne.w   vpv21u_audio_create_failed
        lea     msg_vpv21u_create_ok,a1
        move.l  #msg_vpv21u_create_ok_end-msg_vpv21u_create_ok,d3
        jsr     vpv21n_trace

        ; VPv36: one step beyond VPv21U. Query audio_render CONTROL 0, then INPUT 0.
        ; No PORT_INFO_SET, no enable, no PCM traffic.
        move.l  port_query_type,vpv23_saved_port_qtype
        lea     msg_vpv23_ctrl_get_begin,a1
        move.l  #msg_vpv23_ctrl_get_begin_end-msg_vpv23_ctrl_get_begin,d3
        jsr     vpv21n_trace
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        move.l  #1,v12a_local_get_active
        jsr     port_info_get
        clr.l   v12a_local_get_active
        move.l  d0,d7
        tst.l   d7
        bne.w   vpv23_ctrl_get_fail_local
        move.l  port_last_handle,vpv01_audio_control
        lea     msg_vpv23_ctrl_get_ok,a1
        move.l  #msg_vpv23_ctrl_get_ok_end-msg_vpv23_ctrl_get_ok,d3
        jsr     vpv21n_trace

        ; VPv36: next isolated step - query audio_render INPUT 0 only.
        ; Still no PORT_INFO_SET, enable, HDMI destination or PCM traffic.
        lea     msg_vpv24_input_get_begin,a1
        move.l  #msg_vpv24_input_get_begin_end-msg_vpv24_input_get_begin,d3
        jsr     vpv21n_trace
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        move.l  #1,v12a_local_get_active
        jsr     port_info_get
        clr.l   v12a_local_get_active
        move.l  d0,d7
        tst.l   d7
        bne.w   vpv24_input_get_fail_local
        move.l  port_last_handle,vpv01_audio_input
        lea     msg_vpv24_input_get_ok,a1
        move.l  #msg_vpv24_input_get_ok_end-msg_vpv24_input_get_ok,d3
        jsr     vpv21n_trace

        ; VPv36: isolated INPUT0 PORT_INFO_SET using the real Helix PCM format.
        ; No HDMI destination, no audio enable and no PCM buffer traffic yet.
        lea     msg_vpv26_input_set_begin,a1
        move.l  #msg_vpv26_input_set_begin_end-msg_vpv26_input_set_begin,d3
        jsr     vpv21n_trace
        move.l  vpv01_audio_handle,component_handle
        move.l  vpv01_audio_input,input_port_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        move.l  #MMAL_ES_AUDIO,port_fmt_type
        move.l  #MMAL_ENCODING_PCM_SIGNED_LE,port_fmt_encoding
        clr.l   port_fmt_variant
        move.l  v19_pcm_bitrate,d0
        move.l  d0,port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v19_pcm_channels,d0
        move.l  d0,port_video_width
        move.l  v19_pcm_rate,d0
        move.l  d0,port_video_height
        move.l  v19_pcm_bits,d0
        move.l  d0,port_crop_x
        move.l  v19_pcm_blockalign,d0
        move.l  d0,port_crop_y
        clr.l   port_crop_width
        clr.l   port_crop_height
        clr.l   port_fps_num
        clr.l   port_fps_den
        clr.l   port_par_num
        clr.l   port_par_den
        clr.l   port_color_space
        ; VPv83: actual first-start live A/V audio SET path.
        moveq   #2,d0
        move.l  d0,port_buf_num
        ; VPv36: use the exact buffer sizing already hardware-proven in VPv20.
        ; VPv25 used the retained PCM byte count (e.g. $BB80), which the
        ; audio renderer rejected. VPv20 commits a 64-KiB input buffer.
        move.l  #$00010000,d0
        cmp.l   port_buf_size_min,d0
        bcc.s   vpv26_fresh_set_size_ok
        move.l  port_buf_size_min,d0
vpv26_fresh_set_size_ok:
        cmp.l   #INPUT_DATA_SIZE,d0
        bhi.w   vpv26_input_set_fail_local
        move.l  d0,port_buf_size
        clr.l   vpv30_skipped
        clr.l   vpv30_async_skipped
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        move.l  d0,d7
        tst.l   vpv30_skipped
        beq.s   vpv30_fresh_no_skip_log
        lea     msg_vpv30_dispatch_skipped,a1
        move.l  #msg_vpv30_dispatch_skipped_end-msg_vpv30_dispatch_skipped,d3
        jsr     vpv21n_trace
        bra.s   vpv30_fresh_skip_log_done
vpv30_fresh_no_skip_log:
        lea     msg_vpv30_dispatch_direct,a1
        move.l  #msg_vpv30_dispatch_direct_end-msg_vpv30_dispatch_direct,d3
        jsr     vpv21n_trace
vpv30_fresh_skip_log_done:
        tst.l   d7
        bne.w   vpv26_input_set_fail_local
        lea     msg_vpv26_input_set_ok,a1
        move.l  #msg_vpv26_input_set_ok_end-msg_vpv26_input_set_ok,d3
        jsr     vpv21n_trace
        ; VPv83: read active first-start audio port back from VideoCore.
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        move.l  #1,v12a_local_get_active
        jsr     port_info_get
        clr.l   v12a_local_get_active
        tst.l   d0
        bne.w   vpv26_input_set_fail_local
        lea     msg_vpv81_port0_readback,a1
        move.l  #msg_vpv81_port0_readback_end-msg_vpv81_port0_readback,d3
        jsr     print_force
        move.l  port_buf_num,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  port_buf_size,d0
        jsr     print_hex32
        jsr     newline
        ; VPv36: first full audio-render configuration test.  The PCM format SET
        ; is now proven slot-safe in VPv32, so add only destination + INPUT enable
        ; + component enable.  No PCM buffer is queued yet.
        jsr     vpv35_finish_audio_enable
        tst.l   d0
        beq.s   vpv35_fresh_audio_enable_ok
        lea     msg_vpv35_enable_fail_continue,a1
        move.l  #msg_vpv35_enable_fail_continue_end-msg_vpv35_enable_fail_continue,d3
        jsr     vpv21n_trace
        bra.s   vpv35_fresh_audio_enable_done
vpv35_fresh_audio_enable_ok:
        lea     msg_vpv35_enable_ok,a1
        move.l  #msg_vpv35_enable_ok_end-msg_vpv35_enable_ok,d3
        jsr     vpv21n_trace
        ; VPv36: first real combined A/V proof. Queue the already-decoded
        ; short PCM prefix now, while no H264 input buffers are in flight.
        ; The queue helper is slot-safe and waits for BULK_TX_DONE before
        ; restoring the video globals. Audio may then play while video starts.
        jsr     vpv21_queue_audio_prefix
        tst.l   d0
        beq.s   vpv35_fresh_audio_queue_ok
        lea     msg_vpv35_queue_fail_continue,a1
        move.l  #msg_vpv35_queue_fail_continue_end-msg_vpv35_queue_fail_continue,d3
        jsr     vpv21n_trace
        bra.s   vpv35_fresh_audio_enable_done
vpv35_fresh_audio_queue_ok:
        lea     msg_vpv35_queue_proven,a1
        move.l  #msg_vpv35_queue_proven_end-msg_vpv35_queue_proven,d3
        jsr     vpv21n_trace
        ; VPv116 CLOCK-PROBE: only now, after the complete proven
        ; audio_render setup + first PCM queue, create the independent clock.
        tst.l   vpv116_clock_probe_done
        bne.s   vpv116_fresh_clock_probe_done
        move.l  #1,vpv116_clock_probe_done
        jsr     vpv116_probe_clock_component
vpv116_fresh_clock_probe_done:
vpv35_fresh_audio_enable_done:
        moveq   #0,d7
        bra.w   vpv23_ctrl_get_restore
vpv26_input_set_fail_local:
        lea     msg_vpv26_input_set_fail,a1
        move.l  #msg_vpv26_input_set_fail_end-msg_vpv26_input_set_fail,d3
        jsr     vpv21n_trace
        ; VPv36 diagnostic policy: audio SET failure must not suppress video.
        ; Continue with the proven HDMI_v41L stream, with audio still disabled.
        lea     msg_vpv26_set_fail_continue,a1
        move.l  #msg_vpv26_set_fail_continue_end-msg_vpv26_set_fail_continue,d3
        jsr     vpv21n_trace
        moveq   #0,d7
        bra.w   vpv23_ctrl_get_restore
vpv24_input_get_fail_local:
        lea     msg_vpv24_input_get_fail,a1
        move.l  #msg_vpv24_input_get_fail_end-msg_vpv24_input_get_fail,d3
        jsr     vpv21n_trace
        moveq   #1,d7
        bra.w   vpv23_ctrl_get_restore
vpv23_ctrl_get_fail_local:
        lea     msg_vpv23_ctrl_get_fail,a1
        move.l  #msg_vpv23_ctrl_get_fail_end-msg_vpv23_ctrl_get_fail,d3
        jsr     vpv21n_trace
        moveq   #1,d7
vpv23_ctrl_get_restore:
        ; Restore live video globals. TX/RX positions remain advanced because
        ; the CONTROL0 query is a real consumed VCHIQ transaction.
        move.l  vpv21_saved_component,component_handle
        move.l  vpv21_saved_input,input_port_handle
        move.l  vpv21_saved_port_qidx,port_query_index
        move.l  vpv21_saved_port_buf_size,port_buf_size
        move.l  vpv23_saved_port_qtype,port_query_type
        tst.l   d7
        bne.w   fail_buffer_main
        bra.s   vpv21u_audio_create_done
vpv21u_audio_create_failed:
        lea     msg_vpv21u_create_fail,a1
        move.l  #msg_vpv21u_create_fail_end-msg_vpv21u_create_fail,d3
        jsr     vpv21n_trace
        bra.w   fail_buffer_main
vpv21u_audio_create_done:
bvp_first_video_ready:

        ; CONTROL0 and INPUT0 were queried successfully; audio INPUT remains unmodified.
        lea     msg_vpv21p_before_video_stream,a1
        move.l  #msg_vpv21p_before_video_stream_end-msg_vpv21p_before_video_stream,d3
        jsr     vpv21n_trace

; --------------------------------------------------------------------
; 23..28. Queue one empty output buffer, read raw H264 in fixed 65536-byte
; unframed chunks with NO AU knowledge, recycle the same input buffer, and collect:
;   A) an OUTPUT EVENT_TO_HOST (typically format negotiation), or
;   B) an OUTPUT BUFFER_TO_HOST with real data, followed by BULK_RX.
; --------------------------------------------------------------------
        bsr     h264_output_test
        move.l  d0,d6
        lea     msg_vpv21t_h264_returned,a1
        move.l  #msg_vpv21t_h264_returned_end-msg_vpv21t_h264_returned,d3
        jsr     vpv21n_trace
        move.l  d6,d0
        tst.l   d0
        bne.w   fail_buffer_main

        tst.l   bvp_library_mode
        beq.s   bvp_first_stream_legacy_finish
        moveq   #0,d0
        rts
bvp_first_stream_legacy_finish:
        move.l  v15_stop_requested,d0
        tst.l   d0
        beq.s   v15_first_natural_success
        lea     msg_v15_stop_success,a1
        move.l  #msg_v15_stop_success_end-msg_v15_stop_success,d3
        bsr     print
        bra.s   v15_first_success_done
v15_first_natural_success:
        move.l  #1,mkvr7_natural_eos
        lea     msg_test19_success,a1
        move.l  #msg_test19_success_end-msg_test19_success,d3
        bsr     print
v15_first_success_done:

        ; V9: close_prog now performs ordered teardown instead of requiring reboot.
        bsr     dma_pre_all
        bra.w   close_prog

fail_control_enable_main:
        lea     e19c_control_enable,a1
        move.l  #e19c_control_enable_end-e19c_control_enable,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_control_enable_verify:
        lea     e19c_control_verify,a1
        move.l  #e19c_control_verify_end-e19c_control_verify,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_enable_main:
        lea     e_enable_main,a1
        move.l  #e_enable_main_end-e_enable_main,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_enable_verify:
        lea     e_enable_verify,a1
        move.l  #e_enable_verify_end-e_enable_verify,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_output_enable_main:
        lea     msg_vpv21p_fail_output_entry,a1
        move.l  #msg_vpv21p_fail_output_entry_end-msg_vpv21p_fail_output_entry,d3
        jsr     vpv21n_trace
        lea     e19_output_enable,a1
        move.l  #e19_output_enable_end-e19_output_enable,d3
        bsr     print
        bsr     dma_pre_all
        lea     msg_vpv21p_fail_output_after_dma,a1
        move.l  #msg_vpv21p_fail_output_after_dma_end-msg_vpv21p_fail_output_after_dma,d3
        jsr     vpv21n_trace
        bra.w   close_prog

fail_output_enable_verify:
        lea     e19_output_verify,a1
        move.l  #e19_output_verify_end-e19_output_verify,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_component_enable_main:
        lea     e_component_enable,a1
        move.l  #e_component_enable_end-e_component_enable,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_buffer_main:
        lea     e_buffer_main,a1
        move.l  #e_buffer_main_end-e_buffer_main,d3
        bsr     print
        ; h264_bulk_test returns with shared VCHIQ RAM CPU-owned.
        bsr     dma_pre_all
        bra.w   close_prog

; --------------------------------------------------------------------
; VPv36 minimal context-aware synchronous RX dispatcher.
;
; This is deliberately the small single-threaded/polled form used by our
; current Amiga player: only ONE synchronous MMAL request is outstanding.
; Every RX record is classified before it can satisfy the waiter.
;
; Expected values:
;   vpv30_expect_type
;   vpv30_expect_context
;
; Return:
;   D0=0, A2 -> matching current RX VCHIQ record, NOT consumed, CPU-owned
;   D0=1 on timeout/map/consume failure, CPU-owned
;
; For VPv36 proof only, unsolicited BUFFER_TO_HOST/EVENT_TO_HOST records seen
; during this pre-stream control transaction are consumed and counted. The
; final A/V implementation will route/queue those events instead of dropping
; them once audio/video buffer traffic is active.
; --------------------------------------------------------------------
vpv30_alloc_context:
        move.l  vpv30_context_counter,d0
        addq.l  #1,d0
        and.l   #$0FFFFFFF,d0
        bne.s   vpv30_ctx_nonzero
        moveq   #1,d0
vpv30_ctx_nonzero:
        move.l  d0,vpv30_context_counter
        or.l    #$30000000,d0
        rts

; N80: same matcher with the 4096-poll cleanup budget.
vpv30_wait_matching_long:
        movem.l d1-d7/a0-a1/a3,-(sp)
        move.l  #V10_CLEANUP_POLL_COUNT,d7
        bra.s   vpv30_wait_loop

vpv30_wait_matching:
        movem.l d1-d7/a0-a1/a3,-(sp)
        move.l  #POLL_COUNT,d7

vpv30_wait_loop:
        jsr     short_delay
        jsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   vpv30_wait_have

        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   vpv30_wait_loop

        ; Last iteration left shared memory DMA-owned.
        jsr     dma_post_all
        moveq   #1,d0
        bra.w   vpv30_wait_done

vpv30_wait_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   vpv30_wait_fail

        move.l  a2,a0
        jsr     load_le32
        move.l  d0,vpv30_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv30_rx_size

        ; VCHIQ DATA on the current local MMAL service only.
        move.l  vpv30_rx_msgid,d0
        and.l   #$FF000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   vpv30_wait_skip

        move.l  vpv30_rx_msgid,d0
        and.l   #$00000FFF,d0
        cmp.l   v12f_local_port,d0
        bne.w   vpv30_wait_skip

        move.l  vpv30_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000FFF,d0
        cmp.l   mmal_remote_port,d0
        bne.w   vpv30_wait_skip

        ; Need enough MMAL header bytes to inspect magic/type/context.
        move.l  vpv30_rx_size,d0
        cmp.l   #16,d0
        bcs.w   vpv30_wait_skip

        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   vpv30_wait_skip

        lea     12(a2),a0
        jsr     load_le32
        move.l  d0,d6

        ; Explicitly classify unsolicited messages before context matching.
        cmp.l   #MMAL_BUFFER_TO_HOST,d6
        beq.w   vpv30_wait_skip_async
        cmp.l   #MMAL_EVENT_TO_HOST,d6
        beq.w   vpv30_wait_skip_async

        cmp.l   vpv30_expect_type,d6
        bne.w   vpv30_wait_skip

        lea     20(a2),a0
        jsr     load_le32
        cmp.l   vpv30_expect_context,d0
        bne.w   vpv30_wait_skip

        ; Exact synchronous reply found. Leave it current/unconsumed.
        moveq   #0,d0
        bra.w   vpv30_wait_done

vpv30_wait_skip_async:
        addq.l  #1,vpv30_async_skipped
vpv30_wait_skip:
        addq.l  #1,vpv30_skipped
        move.l  vpv30_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.s   vpv30_wait_fail

        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv30_wait_loop

        jsr     dma_post_all
        moveq   #1,d0
        bra.s   vpv30_wait_done

vpv30_wait_fail:
        moveq   #1,d0
vpv30_wait_done:
        movem.l (sp)+,d1-d7/a0-a1/a3
        rts

; --------------------------------------------------------------------
; PORT_INFO_GET helper
;
; Inputs via globals:
;   port_query_type
;   port_query_index
;
; On success:
;   port_last_handle and diagnostic fields are updated.
;   Shared memory is CPU-owned on return.
;
; Request = MMAL header 24 + payload 12 = 36 bytes.
; VCHIQ stride = align8(8 + 36) = 48 bytes.
;
; Full firmware reply is normally:
;   MMAL header 24
;   port_info_get_reply 292
; = 316 VCHIQ payload bytes, stride 328.
; We calculate the actual returned stride from RX size.
; --------------------------------------------------------------------
port_info_get:
        ; V14 restart: the existing v9f local-1 PORT_INFO_GET helper has
        ; already been hardware-proven repeatedly during second-decoder setup.
        ; Reuse it for every ISP graph GET instead of the first-run polling path.
        tst.l   v12f_local_port
        beq.s   v12h_port_info_get_first
        jmp     v9f_port_info_get
v12h_port_info_get_first:
        movem.l d2-d7/a2-a3,-(sp)

        ; VPv36: every synchronous request gets a fresh opaque context token.
        ; This follows the reference MMAL client model: reply matching is by
        ; context, never by "next RX message".
        jsr     vpv30_alloc_context
        move.l  d0,port_query_context

        ; V12G restart: absolute TX position must be mapped through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_get_tx_legacy
        move.l  #48,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   fail_port_rxslot
        bra.s   v12g_get_tx_ready
v12g_get_tx_legacy:
        ; Original first-run mapping, intentionally unchanged.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_get_tx_ready:

        ; VCHIQ DATA header, destination = opened VC MMAL port.
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32

        lea     4(a2),a0
        move.l  #36,d0
        bsr     store_le32

        ; MMAL header.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_PORT_INFO_GET,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  port_query_context,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; port_info_get payload.
        lea     32(a2),a0
        move.l  component_handle,d0
        bsr     store_le32

        lea     36(a2),a0
        move.l  port_query_type,d0
        bsr     store_le32

        lea     40(a2),a0
        move.l  port_query_index,d0
        bsr     store_le32

        ; Advance host stream by one 48-byte VCHIQ stride.
        move.l  port_tx_pos,d0
        add.l   #48,d0
        move.l  d0,port_tx_pos

        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        ; Signal VC event.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,port_armed

        bsr     dma_pre_all

        move.l  port_armed,d0
        tst.l   d0
        beq.w   port_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2

port_no_bell:
        ; VPv36 dispatcher proof: do not assume the next VCHIQ/MMAL record is
        ; our reply. Consume unrelated records until type+context match.
        move.l  #MMAL_PORT_INFO_GET,vpv30_expect_type
        move.l  port_query_context,vpv30_expect_context
        jsr     vpv30_wait_matching
        tst.l   d0
        bne.w   fail_port_timeout
        bra.w   port_reply_seen

        ; Legacy polling loop retained below but no longer entered here.
        move.l  #POLL_COUNT,d7

port_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   port_rx_pos,d5
        bhi.w   port_reply_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   port_poll_loop
        bra.w   fail_port_timeout

port_reply_seen:
        ; V12D: extra ISP setup replies may be in the next MASTER slot.
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   fail_port_rxslot
        move.l  a2,a0

        ; VCHIQ header.
        bsr     load_le32
        move.l  d0,port_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,port_rx_size

        ; DATA type?
        move.l  port_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   fail_port_wrongmsg

        ; Destination local port 0?
        move.l  port_rx_msgid,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   fail_port_wrongport

        ; Source is the opened MMAL VC port?
        move.l  port_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   fail_port_wrongport

        ; Need enough bytes through video.color_space.
        move.l  port_rx_size,d0
        cmp.l   #188,d0
        bcs.w   fail_port_short

        ; MMAL header.
        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,port_mmal_magic

        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,port_mmal_type

        lea     20(a2),a0
        bsr     load_le32
        move.l  d0,port_mmal_context

        lea     24(a2),a0
        bsr     load_le32
        move.l  d0,port_mmal_hstatus

        ; port_info_get_reply fixed prefix.
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,port_reply_status

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,port_reply_component

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,port_reply_type

        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,port_reply_index

        lea     52(a2),a0
        bsr     load_le32
        move.l  d0,port_last_handle

        ; struct mmal_port begins at message offset 56.
        lea     72(a2),a0
        bsr     load_le32
        move.l  d0,port_enabled

        lea     80(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_num_min

        lea     84(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_size_min

        lea     88(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_align

        lea     92(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_num_rec

        lea     96(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_size_rec

        lea     100(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_num

        lea     104(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_size

        lea     116(a2),a0
        bsr     load_le32
        move.l  d0,port_caps

        ; struct mmal_es_format begins at message offset 120.
        lea     120(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_type

        lea     124(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_encoding

        lea     128(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_variant

        lea     136(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_bitrate

        lea     140(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_flags

        lea     144(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_extra

        ; union mmal_es_specific_format begins at offset 152.
        ; These fields are useful when format type is VIDEO.
        lea     152(a2),a0
        bsr     load_le32
        move.l  d0,port_video_width

        lea     156(a2),a0
        bsr     load_le32
        move.l  d0,port_video_height

        lea     160(a2),a0
        bsr     load_le32
        move.l  d0,port_crop_x

        lea     164(a2),a0
        bsr     load_le32
        move.l  d0,port_crop_y

        lea     168(a2),a0
        bsr     load_le32
        move.l  d0,port_crop_width

        lea     172(a2),a0
        bsr     load_le32
        move.l  d0,port_crop_height

        lea     176(a2),a0
        bsr     load_le32
        move.l  d0,port_fps_num

        lea     180(a2),a0
        bsr     load_le32
        move.l  d0,port_fps_den

        lea     184(a2),a0
        bsr     load_le32
        move.l  d0,port_par_num

        lea     188(a2),a0
        bsr     load_le32
        move.l  d0,port_par_den

        lea     192(a2),a0
        bsr     load_le32
        move.l  d0,port_color_space

        ; Preserve codec extradata only when this reply is INPUT 0.
        move.l  port_query_type,d0
        cmp.l   #MMAL_PORT_INPUT,d0
        bne.w   port_extra_done
        move.l  port_query_index,d0
        tst.l   d0
        bne.w   port_extra_done

        move.l  port_fmt_extra,d0
        cmp.l   #128,d0
        bhi.w   fail_port_extradata

        lea     input_extradata,a0
        move.l  #31,d7
port_extra_clear_loop:
        clr.l   (a0)+
        dbra    d7,port_extra_clear_loop

        move.l  port_fmt_extra,d7
        tst.l   d7
        beq.w   port_extra_done
        subq.l  #1,d7
        lea     196(a2),a0
        lea     input_extradata,a1
port_extra_copy_loop:
        move.b  (a0)+,(a1)+
        dbra    d7,port_extra_copy_loop

port_extra_done:
        ; Validate reply identity.
        move.l  port_mmal_magic,d0
        cmp.l   #MMAL_MAGIC,d0
        bne.w   fail_port_magic

        move.l  port_mmal_type,d0
        cmp.l   #MMAL_PORT_INFO_GET,d0
        bne.w   fail_port_type

        move.l  port_mmal_context,d0
        cmp.l   port_query_context,d0
        bne.w   fail_port_context

        move.l  port_mmal_hstatus,d0
        tst.l   d0
        bne.w   fail_port_status

        move.l  port_reply_status,d0
        tst.l   d0
        bne.w   fail_port_status

        move.l  port_reply_component,d0
        cmp.l   component_handle,d0
        bne.w   fail_port_component

        move.l  port_reply_type,d0
        cmp.l   port_query_type,d0
        bne.w   fail_port_identity

        move.l  port_reply_index,d0
        cmp.l   port_query_index,d0
        bne.w   fail_port_identity

        ; port_handle is opaque. Value 0 is VALID for the MMAL control
        ; port on real Raspberry Pi firmware, so do not reject it.

        ; Print compact but useful port information.
        lea     msg_p_handle,a1
        move.l  #msg_p_handle_end-msg_p_handle,d3
        bsr     print
        move.l  port_last_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_enabled,a1
        move.l  #msg_p_enabled_end-msg_p_enabled,d3
        bsr     print
        move.l  port_enabled,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_min,a1
        move.l  #msg_p_min_end-msg_p_min,d3
        bsr     print
        move.l  port_buf_num_min,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_buf_size_min,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_rec,a1
        move.l  #msg_p_rec_end-msg_p_rec,d3
        bsr     print
        move.l  port_buf_num_rec,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_buf_size_rec,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_cur,a1
        move.l  #msg_p_cur_end-msg_p_cur,d3
        bsr     print
        move.l  port_buf_num,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_buf_size,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_align,a1
        move.l  #msg_p_align_end-msg_p_align,d3
        bsr     print
        move.l  port_buf_align,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_caps,a1
        move.l  #msg_p_caps_end-msg_p_caps,d3
        bsr     print
        move.l  port_caps,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_format,a1
        move.l  #msg_p_format_end-msg_p_format,d3
        bsr     print
        move.l  port_fmt_type,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_fmt_encoding,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_fmt_variant,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_video,a1
        move.l  #msg_p_video_end-msg_p_video,d3
        bsr     print
        move.l  port_video_width,d0
        bsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        bsr     print
        move.l  port_video_height,d0
        bsr     print_hex32
        lea     msg_crop,a1
        move.l  #msg_crop_end-msg_crop,d3
        bsr     print
        move.l  port_crop_width,d0
        bsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        bsr     print
        move.l  port_crop_height,d0
        bsr     print_hex32
        bsr     newline

        ; Move to next VC stream message and recycle a crossed MASTER slot.
        move.l  port_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   fail_port_rxslot

        movem.l (sp)+,d2-d7/a2-a3
        rts


; --------------------------------------------------------------------
; PORT_INFO_SET current INPUT 0 state back to VideoCore.
;
; Request layout (wire, 32-bit pointers):
;   MMAL header                     24
;   component/type/index            12
;   mmal_port                       64
;   mmal_es_format                  32
;   mmal_es_specific_format         44
;   extradata                      128
; Total MMAL payload               304
; VCHIQ stride = align8(8+304)     312
;
; Per Linux/RPi implementation, only writable MMAL_PORT fields are sent:
;   buffer_num, buffer_size, userdata.
; Format + ES + extradata are copied from the preceding INPUT GET.
; --------------------------------------------------------------------
port_info_set_input:
        movem.l d2-d7/a2-a3,-(sp)

        ; Sanity before sending.
        move.l  port_query_type,d0
        cmp.l   #MMAL_PORT_INPUT,d0
        beq.s   v12_set_type_ok
        cmp.l   #MMAL_PORT_OUTPUT,d0
        bne.w   fail_set_identity
v12_set_type_ok:
        move.l  port_query_index,d0
        tst.l   d0
        bne.w   fail_set_identity
        move.l  port_fmt_extra,d0
        cmp.l   #128,d0
        bhi.w   fail_set_extradata

        ; VPv36: fresh context token for this SET request.
        jsr     vpv30_alloc_context
        move.l  d0,set_context

        ; VPv36: PORT_INFO_SET is a 312-byte VCHIQ record and must NEVER
        ; cross a 4-KiB slot boundary.  The old local-0/first-run path
        ; mapped slot 34 + absolute port_tx_pos directly and therefore
        ; became unsafe after the already large video-graph control traffic.
        ; Local-1 was already using h26a_reserve_tx.  Use the same proven
        ; slot-queue/PADDING reservation for BOTH local services.
        move.l  #312,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   fail_set_rxslot

        ; Clear complete 312-byte VCHIQ message first.
        move.l  a2,a0
        move.l  #77,d7
set_clear_loop:
        clr.l   (a0)+
        dbra    d7,set_clear_loop

        ; VCHIQ DATA header.
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32

        lea     4(a2),a0
        move.l  #304,d0
        bsr     store_le32

        ; MMAL worker header.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_PORT_INFO_SET,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  set_context,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; mmal_worker_port_info_set fixed prefix.
        lea     32(a2),a0
        move.l  component_handle,d0
        bsr     store_le32

        lea     36(a2),a0
        move.l  port_query_type,d0
        bsr     store_le32

        lea     40(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; mmal_port starts at 44.
        ; Only client-writable fields are meaningful for SET:
        ; buffer_num @ +44, buffer_size @ +48, userdata @ +56
        ; relative to mmal_port, therefore message offsets 88,92,100.
        lea     88(a2),a0
        move.l  port_buf_num,d0
        bsr     store_le32

        lea     92(a2),a0
        move.l  port_buf_size,d0
        bsr     store_le32

        lea     100(a2),a0
        move.l  #MMAL_INPUT_USERDATA,d0
        bsr     store_le32

        ; mmal_es_format starts at 108.
        lea     108(a2),a0
        move.l  port_fmt_type,d0
        bsr     store_le32

        lea     112(a2),a0
        move.l  port_fmt_encoding,d0
        bsr     store_le32

        lea     116(a2),a0
        move.l  port_fmt_variant,d0
        bsr     store_le32

        ; es pointer @120 remains zero.

        lea     124(a2),a0
        move.l  port_fmt_bitrate,d0
        bsr     store_le32

        lea     128(a2),a0
        move.l  port_fmt_flags,d0
        bsr     store_le32

        lea     132(a2),a0
        move.l  port_fmt_extra,d0
        bsr     store_le32

        ; extradata pointer @136 remains zero.

        ; mmal_es_specific_format.video starts at 140.
        lea     140(a2),a0
        move.l  port_video_width,d0
        bsr     store_le32

        lea     144(a2),a0
        move.l  port_video_height,d0
        bsr     store_le32

        lea     148(a2),a0
        move.l  port_crop_x,d0
        bsr     store_le32

        lea     152(a2),a0
        move.l  port_crop_y,d0
        bsr     store_le32

        lea     156(a2),a0
        move.l  port_crop_width,d0
        bsr     store_le32

        lea     160(a2),a0
        move.l  port_crop_height,d0
        bsr     store_le32

        lea     164(a2),a0
        move.l  port_fps_num,d0
        bsr     store_le32

        lea     168(a2),a0
        move.l  port_fps_den,d0
        bsr     store_le32

        lea     172(a2),a0
        move.l  port_par_num,d0
        bsr     store_le32

        lea     176(a2),a0
        move.l  port_par_den,d0
        bsr     store_le32

        lea     180(a2),a0
        move.l  port_color_space,d0
        bsr     store_le32

        ; Extradata begins at 184 and is already zeroed.
        move.l  port_fmt_extra,d7
        tst.l   d7
        beq.w   set_extra_done
        subq.l  #1,d7
        lea     input_extradata,a0
        lea     184(a2),a1
set_extra_copy_loop:
        move.b  (a0)+,(a1)+
        dbra    d7,set_extra_copy_loop

set_extra_done:
        lea     msg_set_tx,a1
        move.l  #msg_set_tx_end-msg_set_tx,d3
        bsr     print
        move.l  port_buf_num,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_buf_size,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_set_fmt,a1
        move.l  #msg_set_fmt_end-msg_set_fmt,d3
        bsr     print
        move.l  port_fmt_type,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_fmt_encoding,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_fmt_variant,d0
        bsr     print_hex32
        bsr     newline

        ; Advance local stream by 312 bytes and notify VC.
        move.l  port_tx_pos,d0
        add.l   #312,d0
        move.l  d0,port_tx_pos

        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,set_armed

        bsr     dma_pre_all

        move.l  set_armed,d0
        tst.l   d0
        beq.w   set_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2

set_no_bell:
        ; VPv36 dispatcher proof: wait for the exact PORT_INFO_SET context.
        ; Unrelated MMAL traffic is consumed instead of being misread as reply.
        move.l  #MMAL_PORT_INFO_SET,vpv30_expect_type
        move.l  set_context,vpv30_expect_context
        jsr     vpv30_wait_matching
        tst.l   d0
        bne.w   fail_set_timeout
        bra.w   set_reply_seen

        ; Legacy polling loop retained below but no longer entered here.
        move.l  #POLL_COUNT,d7

set_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   port_rx_pos,d5
        bhi.w   set_reply_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   set_poll_loop
        bra.w   fail_set_timeout

set_reply_seen:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   fail_set_rxslot
        move.l  a2,a0
        bsr     load_le32
        move.l  d0,set_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,set_rx_size

        ; VCHIQ DATA and correct remote/local ports.
        move.l  set_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   fail_set_wrongmsg

        move.l  set_rx_msgid,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   fail_set_wrongport

        move.l  set_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   fail_set_wrongport

        ; Need at least MMAL header + reply status/component/type/index.
        move.l  set_rx_size,d0
        cmp.l   #40,d0
        bcs.w   fail_set_short

        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,set_magic

        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,set_type

        lea     20(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_context

        lea     24(a2),a0
        bsr     load_le32
        move.l  d0,set_header_status

        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_status

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_component

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_port_type

        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_index

        lea     msg_set_reply,a1
        move.l  #msg_set_reply_end-msg_set_reply,d3
        bsr     print
        move.l  set_rx_size,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_set_status,a1
        move.l  #msg_set_status_end-msg_set_status,d3
        bsr     print
        move.l  set_reply_status,d0
        bsr     print_hex32
        bsr     newline

        ; Validate MMAL reply.
        move.l  set_magic,d0
        cmp.l   #MMAL_MAGIC,d0
        bne.w   fail_set_magic

        move.l  set_type,d0
        cmp.l   #MMAL_PORT_INFO_SET,d0
        bne.w   fail_set_type

        move.l  set_reply_context,d0
        cmp.l   set_context,d0
        bne.w   fail_set_context

        move.l  set_header_status,d0
        tst.l   d0
        bne.w   fail_set_status

        move.l  set_reply_status,d0
        tst.l   d0
        bne.w   fail_set_status

        move.l  set_reply_component,d0
        cmp.l   component_handle,d0
        bne.w   fail_set_identity

        move.l  set_reply_port_type,d0
        cmp.l   port_query_type,d0
        bne.w   fail_set_identity

        move.l  set_reply_index,d0
        tst.l   d0
        bne.w   fail_set_identity

        ; Advance VC stream slot-safely.
        move.l  set_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   fail_set_rxslot

        lea     msg_set_ok,a1
        move.l  #msg_set_ok_end-msg_set_ok,d3
        bsr     print

        movem.l (sp)+,d2-d7/a2-a3
        rts


; --------------------------------------------------------------------
; PORT_ACTION ENABLE helper for the port currently described by port_*.
;
; Request:
;   MMAL header                 24
;   component_handle             4
;   port_handle                  4
;   action                       4
;   struct mmal_port            64
; = MMAL DATA payload          100
; VCHIQ header + payload = 108 -> stride 112.
;
; Reply:
;   MMAL header 24 + status 4 = 28 -> VCHIQ stride 40.
;
; Returns D0=0 success, D0=1 failure.
; Always returns with shared memory CPU-owned.
; --------------------------------------------------------------------
port_enable_current:
        movem.l d2-d7/a2-a3,-(sp)

        move.l  #$16000002,enable_context

        ; VPv36: slot-safe reservation on local-0 as well.  PORT_ACTION is
        ; 112 bytes and, like PORT_INFO_SET, may not cross a 4-KiB VCHIQ slot.
        move.l  #112,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   enable_bad_reply

        ; Clear complete request area (112 bytes) first.
        move.l  a2,a0
        move.l  #27,d7
enable_clear_loop:
        clr.l   (a0)+
        dbra    d7,enable_clear_loop

        ; VCHIQ DATA header.
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32

        lea     4(a2),a0
        move.l  #100,d0
        bsr     store_le32

        ; MMAL header.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_PORT_ACTION,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  enable_context,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; PORT_ACTION payload.
        lea     32(a2),a0
        move.l  component_handle,d0
        bsr     store_le32

        lea     36(a2),a0
        move.l  input_port_handle,d0
        bsr     store_le32

        lea     40(a2),a0
        move.l  #MMAL_PORT_ACTION_ENABLE,d0
        bsr     store_le32

        ; struct mmal_port at offset 44.
        ; priv/name = 0
        lea     52(a2),a0               ; port.type
        move.l  #MMAL_PORT_INPUT,d0
        bsr     store_le32

        ; index/index_all both zero -> packed u16/u16 word remains zero.

        lea     60(a2),a0               ; is_enabled
        move.l  port_enabled,d0
        bsr     store_le32

        ; format pointer field at 64 remains zero.

        lea     68(a2),a0
        move.l  port_buf_num_min,d0
        bsr     store_le32

        lea     72(a2),a0
        move.l  port_buf_size_min,d0
        bsr     store_le32

        lea     76(a2),a0
        move.l  port_buf_align,d0
        bsr     store_le32

        lea     80(a2),a0
        move.l  port_buf_num_rec,d0
        bsr     store_le32

        lea     84(a2),a0
        move.l  port_buf_size_rec,d0
        bsr     store_le32

