out_enable_no_bell:
        ; N80 direct graph: the renderer is already set up, and the next RX
        ; record need not be this reply.  Wait for the exact PORT_ACTION +
        ; context the way v12a_connect_ports does, skipping MMAL events.
        tst.l   n80_direct_mode
        beq.s   out_enable_plain_wait
        move.l  #MMAL_PORT_ACTION,vpv30_expect_type
        move.l  out_enable_context,vpv30_expect_context
        jsr     vpv30_wait_matching_long
        tst.l   d0
        beq.w   out_enable_reply_mapped
        move.l  #2,n80_en_why
        bra.w   out_enable_bad_reply
out_enable_plain_wait:
        move.l  #POLL_COUNT,d7

out_enable_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   port_rx_pos,d5
        bhi.w   out_enable_reply_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   out_enable_poll_loop

        ; timeout: regain CPU ownership before returning
        bsr     dma_post_all
        move.l  #1,n80_en_why
        lea     e_enable_timeout,a1
        move.l  #e_enable_timeout_end-e_enable_timeout,d3
        bsr     print
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

out_enable_reply_seen:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   out_enable_bad_reply
out_enable_reply_mapped:
        move.l  a2,a0
        bsr     load_le32
        move.l  d0,out_enable_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,out_enable_rx_size

        ; VCHIQ DATA / local port 0 / source mmal VC port.
        move.l  out_enable_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   out_enable_bad_reply

        move.l  out_enable_rx_msgid,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   out_enable_bad_reply

        move.l  out_enable_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   out_enable_bad_reply

        move.l  out_enable_rx_size,d0
        cmp.l   #28,d0
        bcs.w   out_enable_bad_reply

        ; MMAL header.
        lea     8(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   out_enable_bad_reply

        lea     12(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.w   out_enable_bad_reply

        lea     20(a2),a0
        bsr     load_le32
        cmp.l   out_enable_context,d0
        bne.w   out_enable_bad_reply

        lea     24(a2),a0
        bsr     load_le32
        tst.l   d0
        bne.w   out_enable_bad_reply

        ; port_action_reply.status
        lea     32(a2),a0
