        dc.l $80808080,$20202020,$08080808,$02020202
        dc.l $C0808080,$30202020,$0C080808,$03020202
        dc.l $80C08080,$20302020,$080C0808,$02030202
        dc.l $C0C08080,$30302020,$0C0C0808,$03030202
        dc.l $8080C080,$20203020,$08080C08,$02020302
        dc.l $C080C080,$30203020,$0C080C08,$03020302
        dc.l $80C0C080,$20303020,$080C0C08,$02030302
        dc.l $C0C0C080,$30303020,$0C0C0C08,$03030302
        dc.l $808080C0,$20202030,$0808080C,$02020203
        dc.l $C08080C0,$30202030,$0C08080C,$03020203
        dc.l $80C080C0,$20302030,$080C080C,$02030203
        dc.l $C0C080C0,$30302030,$0C0C080C,$03030203
        dc.l $8080C0C0,$20203030,$08080C0C,$02020303
        dc.l $C080C0C0,$30203030,$0C080C0C,$03020303
        dc.l $80C0C0C0,$20303030,$080C0C0C,$02030303
        dc.l $C0C0C0C0,$30303030,$0C0C0C0C,$03030303

        section code,code
h22_bad_frame_size:
        lea     e22_frame_size,a1
        move.l  #e22_frame_size_end-e22_frame_size,d3
        bsr     print
        bsr     t31s_display_abort_cleanup
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

h22_bad_frame_sum:
        lea     e22_frame_sum,a1
        move.l  #e22_frame_sum_end-e22_frame_sum,d3
        bsr     print
        bsr     t31s_display_abort_cleanup
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

; --------------------------------------------------------------------
; TEST33 - compact MMAL output header diagnostic.
; Prints only for output #150 onward (or any zero-length output).
; --------------------------------------------------------------------
h31s_log_output_header:
        movem.l d0-d3/a1,-(sp)
        lea     msg31s_hdr,a1
        move.l  #msg31s_hdr_end-msg31s_hdr,d3
        bsr     print
        move.l  output_frame_total,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_length,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_offset,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_flags,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_cmd,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_pts_hi,d0
        bsr     print_hex32
        move.l  buffer_pts_lo,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_dts_hi,d0
        bsr     print_hex32
        move.l  buffer_dts_lo,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_payload,d0
        bsr     print_hex32
        bsr     newline
        movem.l (sp)+,d0-d3/a1
        rts

h19_mmal_data:
        ; Validate MMAL DATA ports.
        move.l  bulk_rx_msgid,d0
        jsr     v9g_rx_service_match
        tst.l   d0
        bne.w   h19_other_vchiq
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop

        move.l  bulk_rx_size,d0
        cmp.l   #24,d0
        bcs.w   h19_bad_reply

        lea     8(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   h19_bad_reply
        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,buffer_mmal_type


        move.l  buffer_mmal_type,d0
        cmp.l   #MMAL_BUFFER_TO_HOST,d0
        beq.w   h19_buffer_to_host
        cmp.l   #MMAL_EVENT_TO_HOST,d0
        beq.w   h19_event
        cmp.l   #MMAL_PORT_PARAMETER_SET,d0
        bne.s   o2_h19_not_set
        jmp     o2_reply                  ; O2: OSD reply (others consumed)
o2_h19_not_set:
        cmp.l   #MMAL_PORT_PARAMETER_GET,d0
        bne.w   h19_consume
        tst.l   s1_pending                ; S1: subtitle clock answer?
        beq.s   s1_h19_not
        jmp     s1_clk_reply
s1_h19_not:
        jmp     p96w_clk_reply

h19_buffer_to_host:
        ; VPv21T isolation: EXACT HDMI_v41L video BUFFER_TO_HOST path.
        ; No audio component exists in this build, therefore no audio-return
        ; interception is allowed here. This isolates the VPv21 audio hook.
        move.l  bulk_rx_size,d0
        cmp.l   #164,d0
        bcs.w   h19_bad_reply

        lea     24(a2),a0
        bsr     load_le32
        tst.l   d0
        bne.w   h19_bad_reply
        lea     32(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   h19_bad_reply

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,buffer_drv_port
        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,buffer_drv_context
        lea     72(a2),a0
        bsr     load_le32
        move.l  d0,buffer_cmd
        lea     84(a2),a0
        bsr     load_le32
        move.l  d0,buffer_length
        lea     88(a2),a0
        bsr     load_le32
        move.l  d0,buffer_offset
        lea     92(a2),a0
        bsr     load_le32
        move.l  d0,buffer_flags
        lea     96(a2),a0
        bsr     load_le32
        move.l  d0,buffer_pts_lo
        lea     100(a2),a0
        bsr     load_le32
        move.l  d0,buffer_pts_hi
        lea     104(a2),a0
        bsr     load_le32
        move.l  d0,buffer_dts_lo
        lea     108(a2),a0
        bsr     load_le32
        move.l  d0,buffer_dts_hi
        lea     168(a2),a0
        bsr     load_le32
        move.l  d0,buffer_payload

        ; VPv36 A/V: audio_render INPUT0 and video_decode INPUT0 both use
        ; port handle 1, so port handle alone cannot distinguish callbacks.
        ; The audio buffer uses its own unique context/cookie. Consume that
        ; return here before the video-input ownership checks see it.
        move.l  buffer_drv_context,d0
        ; O1: the OSD renderer gives its picture buffer back (e.g. on
        ; close) - not a video buffer, just consume it.
        cmp.l   #O1_BUFFER_CONTEXT,d0
        beq.w   h19_consume
        ; VPv47: two independent audio MMAL input contexts. Mark the exact
        ; renderer-owned slot returned without disturbing the other slot.
        move.l  d0,d1
        sub.l   #VPV47_AUDIO_CONTEXT_BASE,d1
        cmpi.l  #VPV47_AUDIO_SLOTS,d1
        bcc.s   h19_vpv47_not_audio_return
        jsr     p96w49_audio_return       ; P96W49: passive sound clock
        ; VPv135: passive audio-renderer wall-clock proof. D1 is the exact
        ; returned slot index and buffer_pts_* belongs to this BUFFER_TO_HOST.
        jsr     vpv135_measure_audio_return
        ; VPv66 diagnostic only: timestamp first renderer return awaiting refill.
        addq.l  #1,vpv66_audio_returns
        tst.l   input_bulk_pending
        beq.s   h19_vpv66_return_no_video_bulk
        addq.l  #1,vpv66_return_while_video_bulk
h19_vpv66_return_no_video_bulk:
        tst.l   vpv66_refill_wait_active
        bne.s   h19_vpv66_return_stamp_done
        move.l  #1,vpv66_refill_wait_active
        move.l  t31s_vblank_counter,vpv66_refill_start_vblank
        move.l  vpv83_poll_seq,vpv83_refill_poll_start
        move.l  vpv83_video_bulk_seq,vpv83_refill_video_seq_start
h19_vpv66_return_stamp_done:
        lsl.l   #2,d1
        lea     vpv47_slot_returned,a0
        adda.l  d1,a0
        move.l  #1,(a0)
        bra.w   h19_consume
h19_vpv47_not_audio_return:
        ; Keep the old single-buffer context recognized for legacy helpers.
        cmp.l   #VPV01_BUFFER_CONTEXT,d0
        bne.s   h19_vpv35_not_audio_return
        move.l  #1,vpv21_audio_returned
        bra.w   h19_consume
h19_vpv35_not_audio_return:

        ; Input callback? Nice diagnostic, but no bulk receive.
        move.l  buffer_drv_port,d0
        cmp.l   input_port_handle,d0
        bne.w   h19_check_output_buffer
        move.l  buffer_drv_context,d0
        cmp.l   #MMAL_EOS_BUFFER_CONTEXT,d0
        beq.w   h19a_eos_input_return

        ; Normal TEST33 pool contexts are BASE + slot (0..19).
        cmp.l   #MMAL_BUFFER_CONTEXT_BASE,d0
        bcs.w   h19_bad_reply
        sub.l   #MMAL_BUFFER_CONTEXT_BASE,d0
        cmp.l   #INPUT_POOL_COUNT,d0
        bcc.w   h19_bad_reply
        bra.w   h19a_normal_input_return

h19a_eos_input_return:
        ; EOS input buffer itself came back from VideoCore.
        move.l  #1,eos_return_seen
        lea     msg19a_eos_return,a1
        move.l  #msg19a_eos_return_end-msg19a_eos_return,d3
        bsr     print
        bra.w   h19_consume

h19a_normal_input_return:
        ; D0 = pool slot index.  A slot becomes reusable only here, not at
        ; BULK_TX_DONE.  Duplicate/unknown returns are treated as corruption.
        move.l  d0,d1
        lsl.l   #2,d1
        lea     input_slot_state,a0
        adda.l  d1,a0
        tst.l   (a0)
        beq.w   h19_bad_reply
        clr.l   (a0)
        subq.l  #1,input_in_use_count
        move.l  #1,buffer_seen
        addq.l  #1,input_return_total
        bra.w   h19_consume

h19_check_output_buffer:
        move.l  buffer_drv_port,d0
        cmp.l   output_port_handle,d0
        bne.w   h19_consume

        ; V10P: output contexts are BASE + slot for every offered host slot.
        move.l  buffer_drv_context,d0
        sub.l   #MMAL_OUTPUT_BUFFER_CONTEXT0,d0
        bcs.w   h19_consume
        cmp.l   v10j_output_req_count,d0
        bcc.w   h19_consume
        move.l  d0,output_header_idx

        ; H264RGB2: this is now proven to be an OUTPUT callback. TEST66's
        ; hardware log ends with a zero-length output carrying flags=EOS.
        ; Record EOS here (not on INPUT callbacks, whose EOS flag is separate).
        move.l  buffer_flags,d0
        and.l   #MMAL_BUFFER_FLAG_EOS,d0
        beq.s   h264rgb2_output_header_not_eos
        move.l  #1,output_eos_seen
h264rgb2_output_header_not_eos:

        move.l  #1,output_buffer_seen
        addq.l  #1,output_bth_total

        ; V9: no per-frame DOS/console output during streaming.
        ; V8D logged every OUTPUT header from frame 150 onward; on real Amiga
        ; hardware that means roughly 1650 long console lines for the anime and
        ; materially steals time from the 25-fps RGB path.  Keep only zero-length
        ; callbacks (notably terminal EOS) visible; all timing counters remain.
        move.l  buffer_length,d0
        tst.l   d0
        bne.w   h31s_after_hdr_log
        bsr     h31s_log_output_header
h31s_after_hdr_log:

        ; Empty callback: ownership returned without a bulk payload. Normal
        ; empties are requeued. An EOS empty is terminal. With two output
        ; buffers, if EOS arrives while one BULK_RX is active, that active
        ; payload is the last picture and must receive final-frame timing.
        move.l  buffer_length,d0
        bne.w   h61_nonempty_output
        addq.l  #1,output_empty_total
        move.l  output_header_idx,d0
        move.l  d0,output_empty_idx
        move.l  buffer_flags,d0
        and.l   #MMAL_BUFFER_FLAG_EOS,d0
        beq.s   h264rgb2_empty_not_eos
        move.l  output_bulk_queued,d0
        tst.l   d0
        beq.s   h264rgb2_empty_eos_marked
        move.l  #1,output_current_eos
h264rgb2_empty_eos_marked:
        move.l  #1,output_empty_requeue_pending
        bra.w   h19_consume
h264rgb2_empty_not_eos:
        move.l  #1,output_empty_requeue_pending
        bra.w   h19_consume

h61_nonempty_output:
        ; VPv136: timestamp the exact ISP OUTPUT BUFFER_TO_HOST arrival.
        ; This is passive: only the free-running Pi 1-MHz timer is read.
        bsr     vpv98_read_sys_us
        move.l  d0,vpv136_header_wall_now

        move.l  buffer_payload,d0
        tst.l   d0
        bne.w   h19_bad_output_payload

        move.l  buffer_length,d0
        cmp.l   output_buf_size_saved,d0
        bhi.w   h19_output_too_big
        addq.l  #3,d0
        and.l   #$fffffffc,d0

        ; Preserve whether this particular non-empty header carries EOS.
        moveq   #0,d2
        move.l  buffer_flags,d1
        and.l   #MMAL_BUFFER_FLAG_EOS,d1
        beq.s   h264rgb2_nonempty_eos_ready
        moveq   #1,d2
h264rgb2_nonempty_eos_ready:

        ; One host BULK_RX remains serialized. With up to 20 MMAL output
        ; buffers, several decoded headers may arrive while the current payload
        ; is being transferred/converted. Preserve them in decode order in a
        ; bounded FIFO instead of the old single deferred slot.
        ; VPv174: a classic MKV output RX must never be launched while
        ; a VIDEO or AUDIO BULK_TX is already active on the same MMAL service.
        ; Preserve the decoded output header in the existing FIFO instead.
        ; This closes the half-serialization hole left by VPv109: VPv109
        ; blocked NEW TX after RX start, but RX could still begin on top of an
        ; already-active TX.  25/50/75 all use this deterministic MKV rule.
        move.l  output_bulk_queued,d1
        tst.l   d1
        bne.s   vpv183_defer_output_header
        ; P96W18: keep strict decode order.  If older headers are still
        ; waiting in the FIFO, this newer header must queue BEHIND them;
        ; launching it now would receive the frames out of order and hand
        ; the wrong MMAL buffer back to the ISP (output pool lost -> stall).
        tst.l   bvp_p96_mode
        beq.s   p96w18_fifo_ok
        tst.l   output_deferred_count
        bne.s   vpv183_defer_output_header
p96w18_fifo_ok:

        ; mkvr7: host P96 BULK_RX must never start while compressed
        ; VIDEO or PCM AUDIO BULK_TX owns the shared VCHIQ bulk engine.
        ; Raw-H264 legacy behavior is left unchanged.
        tst.l   v10b_input_is_mkv
        bne.s   p96w15_rx_serial_check
        ; P96W15: the library never sets v10b_input_is_mkv (mrberry feeds
        ; the packets), so the VPv174 rule was skipped and a window-frame
        ; BULK_RX could start on top of an active AUDIO/VIDEO BULK_TX ->
        ; VideoCore bulk engine deadlock.  Apply the rule in the P96 window.
        tst.l   bvp_p96_mode
        beq.s   h61_output_bulk_now
p96w15_rx_serial_check:
        tst.l   input_bulk_pending
        bne.s   vpv183_defer_output_header
        tst.l   vpv39_audio_bulk_pending
        beq.s   h61_output_bulk_now
vpv183_defer_output_header:
        addq.l  #1,vpv183_bulk_rx_deferred_for_tx
        move.l  output_deferred_count,d1
        cmp.l   v10j_output_req_count,d1
        bcc.w   h19_bad_reply
        move.l  output_deferred_tail,d3
        move.l  d3,d4
        lsl.l   #2,d4
        lea     output_deferred_idx_q,a0
        move.l  output_header_idx,0(a0,d4.l)
        lea     output_deferred_len_q,a0
        move.l  d0,0(a0,d4.l)
        lea     output_deferred_eos_q,a0
        move.l  d2,0(a0,d4.l)
        ; VPv134: keep this exact frame's timestamp tuple beside the deferred
        ; payload. The shared buffer_pts/dts_* fields are overwritten by each
        ; later BUFFER_TO_HOST header while this frame waits for BULK_RX.
        lea     output_deferred_pts_lo_q,a0
        move.l  buffer_pts_lo,0(a0,d4.l)
        lea     output_deferred_pts_hi_q,a0
        move.l  buffer_pts_hi,0(a0,d4.l)
        lea     output_deferred_dts_lo_q,a0
        move.l  buffer_dts_lo,0(a0,d4.l)
        lea     output_deferred_dts_hi_q,a0
        move.l  buffer_dts_hi,0(a0,d4.l)
        ; VPv136: arrival time belongs to the same deferred frame as PTS/DTS.
        lea     output_deferred_header_wall_q,a0
        move.l  vpv136_header_wall_now,0(a0,d4.l)
        addq.l  #1,vpv134_pts_deferred_snapshots
        addq.l  #1,d3
        cmpi.l  #OUTPUT_POOL_MAX,d3
        bcs.s   v10j_deferred_tail_ok
        moveq   #0,d3
v10j_deferred_tail_ok:
        move.l  d3,output_deferred_tail
        addq.l  #1,output_deferred_count
        move.l  output_deferred_count,d1
        cmp.l   vpv136_deferred_depth_max,d1
        bls.s   vpv136_deferred_depth_ok
        move.l  d1,vpv136_deferred_depth_max
vpv136_deferred_depth_ok:
        addq.l  #1,t61_deferred_total
        bra.w   h19_consume

h61_output_bulk_now:
        move.l  d0,output_bulk_len
        move.l  d2,output_current_eos
        ; VPv134: bind timestamps to the payload before BULK_RX starts.
        ; Later MMAL headers may overwrite buffer_pts/dts_* without changing
        ; the timestamp owned by the currently receiving/displaying frame.
        move.l  buffer_pts_lo,output_current_pts_lo
        move.l  buffer_pts_hi,output_current_pts_hi
        move.l  buffer_dts_lo,output_current_dts_lo
        move.l  buffer_dts_hi,output_current_dts_hi
        move.l  vpv136_header_wall_now,output_current_header_wall
        addq.l  #1,vpv134_pts_immediate_snapshots
        move.l  output_header_idx,d0
        bsr     h61_select_output_idx
        tst.l   d0
        bne.w   h19_bad_reply

        ; Consume BUFFER_TO_HOST BEFORE publishing BULK_RX.
        move.l  bulk_rx_size,d0
        add.l   #15,d0
        and.l   #$fffffff8,d0
        add.l   port_rx_pos,d0
        move.l  d0,port_rx_pos

        ; VPv174: this direct BUFFER_TO_HOST -> BULK_RX path deliberately
        ; bypasses h19_consume, so reload the stream watchdog explicitly.
        ; Otherwise a fresh 50/75% RX can inherit an almost-expired budget.
        jsr     vpv183_reload_stream_poll_budget
        bra.w   h19_queue_bulk_rx

h19_event:
        move.l  #1,event_seen

        move.l  bulk_rx_size,d0
        cmp.l   #44,d0
        bcs.w   h19_consume

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,event_port_type
        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,event_port_num
        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,buffer_event_cmd
        lea     48(a2),a0
        bsr     load_le32
        move.l  d0,buffer_event_length
        jsr     v93_log_event            ; v96.93: every MMAL event to the trace

        lea     msg19_event,a1
        move.l  #msg19_event_end-msg19_event,d3
        bsr     print
        move.l  event_port_type,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  event_port_num,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_event_cmd,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_event_length,d0
        bsr     print_hex32
        bsr     newline

        move.l  event_port_type,d0
        cmp.l   #MMAL_PORT_OUTPUT,d0
        beq.w   h19c_output_event
        cmp.l   #MMAL_PORT_CONTROL,d0
        beq.w   h19c_control_event
        bra.w   h19_consume

h19c_output_event:
        move.l  #1,output_event_seen
        bra.w   h19_consume

h19c_control_event:
        move.l  #1,control_event_seen

        ; V10P: an MMAL ERROR event carries a 4-byte MMAL_STATUS_T in data[].
        ; Print exactly the first one together with the last submitted MKV/MMAL
        ; input context, then stop after consuming this VCHIQ record. This turns
        ; the previous endless ERRO flood into one deterministic diagnostic.
        move.l  buffer_event_cmd,d0
        cmpi.l  #MMAL_EVENT_ERROR,d0
        bne.w   h19c_control_event_normal
        move.l  buffer_event_length,d0
        cmpi.l  #4,d0
        bcs.w   h19c_control_event_short_error

        lea     52(a2),a0              ; mmal_worker_event_to_host.data[0]
        bsr     load_le32
        move.l  d0,v10h_error_status
        move.l  #1,v10h_error_seen

        lea     msg_v10h_error_status,a1
        move.l  #msg_v10h_error_status_end-msg_v10h_error_status,d3
        bsr     print
        move.l  v10h_error_status,d0
        bsr     print_hex32
        lea     msg_v10h_error_name,a1
        move.l  #msg_v10h_error_name_end-msg_v10h_error_name,d3
        bsr     print
        move.l  v10h_error_status,d0
        bsr     v10h_print_status_name
        bsr     newline

        lea     msg_v10h_error_ctx1,a1
        move.l  #msg_v10h_error_ctx1_end-msg_v10h_error_ctx1,d3
        bsr     print
        move.l  v10h_last_frame_no,d0
        bsr     print_hex32
        lea     msg_v10h_error_payload,a1
        move.l  #msg_v10h_error_payload_end-msg_v10h_error_payload,d3
        bsr     print
        move.l  v10h_last_frame_payload,d0
        bsr     print_hex32
        lea     msg_v10h_error_pts,a1
        move.l  #msg_v10h_error_pts_end-msg_v10h_error_pts,d3
        bsr     print
        move.l  v10h_last_pts_ticks,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_v10h_error_ctx2,a1
        move.l  #msg_v10h_error_ctx2_end-msg_v10h_error_ctx2,d3
        bsr     print
        move.l  v10h_last_nal_count,d0
        bsr     print_hex32
        lea     msg_v10h_error_frag,a1
        move.l  #msg_v10h_error_frag_end-msg_v10h_error_frag,d3
        bsr     print
        move.l  v10h_last_fragment_no,d0
        bsr     print_hex32
        lea     msg_v10h_error_len,a1
        move.l  #msg_v10h_error_len_end-msg_v10h_error_len,d3
        bsr     print
        move.l  v10h_last_chunk_len,d0
        bsr     print_hex32
        lea     msg_v10h_error_flags,a1
        move.l  #msg_v10h_error_flags_end-msg_v10h_error_flags,d3
        bsr     print
        move.l  v10h_last_chunk_flags,d0
        bsr     print_hex32
        lea     msg_v10h_error_naltype,a1
        move.l  #msg_v10h_error_naltype_end-msg_v10h_error_naltype,d3
        bsr     print
        move.l  v10h_last_nal_type,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_v10h_error_pipe,a1
        move.l  #msg_v10h_error_pipe_end-msg_v10h_error_pipe,d3
        bsr     print
        move.l  input_in_use_count,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  input_bulk_total,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  input_return_total,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  input_bulk_pending,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_v10h_error_stop,a1
        move.l  #msg_v10h_error_stop_end-msg_v10h_error_stop,d3
        bsr     print
        bra.w   h19_consume

h19c_control_event_short_error:
        move.l  #$FFFFFFFF,v10h_error_status
        move.l  #1,v10h_error_seen
        lea     msg_v10h_error_short,a1
        move.l  #msg_v10h_error_short_end-msg_v10h_error_short,d3
        bsr     print
        bra.w   h19_consume

h19c_control_event_normal:
        lea     msg19c_control_event,a1
        move.l  #msg19c_control_event_end-msg19c_control_event,d3
        bsr     print
        bra.w   h19_consume

; V10P status-name helper. D0=status.
v10h_print_status_name:
        movem.l d0-d3/a1,-(sp)
        cmpi.l  #MMAL_SUCCESS,d0
        beq.w   v10h_status_success
        cmpi.l  #MMAL_ENOMEM,d0
        beq.w   v10h_status_enomem
        cmpi.l  #MMAL_ENOSPC,d0
        beq.w   v10h_status_enospc
        cmpi.l  #MMAL_EINVAL,d0
        beq.w   v10h_status_einval
        cmpi.l  #MMAL_ENOSYS,d0
        beq.w   v10h_status_enosys
        cmpi.l  #MMAL_ENOENT,d0
        beq.w   v10h_status_enoent
        cmpi.l  #MMAL_ENXIO,d0
        beq.w   v10h_status_enxio
        cmpi.l  #MMAL_EIO,d0
        beq.w   v10h_status_eio
        cmpi.l  #MMAL_ESPIPE,d0
        beq.w   v10h_status_espipe
        cmpi.l  #MMAL_ECORRUPT,d0
        beq.w   v10h_status_ecorrupt
        cmpi.l  #MMAL_ENOTREADY,d0
        beq.w   v10h_status_enotready
        cmpi.l  #MMAL_ECONFIG,d0
        beq.w   v10h_status_econfig
        cmpi.l  #MMAL_EISCONN,d0
        beq.w   v10h_status_eisconn
        cmpi.l  #MMAL_ENOTCONN,d0
        beq.w   v10h_status_enotconn
        cmpi.l  #MMAL_EAGAIN,d0
        beq.w   v10h_status_eagain
        cmpi.l  #MMAL_EFAULT,d0
        beq.w   v10h_status_efault
        lea     msg_v10h_status_unknown,a1
        bra.w   v10h_status_print
v10h_status_success:   lea msg_v10h_status_success,a1
        bra.w v10h_status_print
v10h_status_enomem:    lea msg_v10h_status_enomem,a1
        bra.w v10h_status_print
v10h_status_enospc:    lea msg_v10h_status_enospc,a1
        bra.w v10h_status_print
v10h_status_einval:    lea msg_v10h_status_einval,a1
        bra.w v10h_status_print
v10h_status_enosys:    lea msg_v10h_status_enosys,a1
        bra.w v10h_status_print
v10h_status_enoent:    lea msg_v10h_status_enoent,a1
        bra.w v10h_status_print
v10h_status_enxio:     lea msg_v10h_status_enxio,a1
        bra.w v10h_status_print
v10h_status_eio:       lea msg_v10h_status_eio,a1
        bra.w v10h_status_print
v10h_status_espipe:    lea msg_v10h_status_espipe,a1
        bra.w v10h_status_print
v10h_status_ecorrupt:  lea msg_v10h_status_ecorrupt,a1
        bra.w v10h_status_print
v10h_status_enotready: lea msg_v10h_status_enotready,a1
        bra.w v10h_status_print
v10h_status_econfig:   lea msg_v10h_status_econfig,a1
        bra.w v10h_status_print
v10h_status_eisconn:   lea msg_v10h_status_eisconn,a1
        bra.w v10h_status_print
v10h_status_enotconn:  lea msg_v10h_status_enotconn,a1
        bra.w v10h_status_print
v10h_status_eagain:    lea msg_v10h_status_eagain,a1
        bra.w v10h_status_print
v10h_status_efault:    lea msg_v10h_status_efault,a1
v10h_status_print:
        moveq   #0,d3
v10h_status_len:
        tst.b   0(a1,d3.l)
        beq.s   v10h_status_len_done
        addq.l  #1,d3
        bra.s   v10h_status_len
v10h_status_len_done:
        bsr     print
        movem.l (sp)+,d0-d3/a1
        rts

; ------------------------------------------------------------
; Queue VCHIQ BULK_RX after an output BUFFER_TO_HOST announced data.
; Shared VCHIQ RAM is CPU-owned on entry.
; port_rx_pos already consumed the BUFFER_TO_HOST message.
; ------------------------------------------------------------
h19_queue_bulk_rx:

        ; Pagelist:
        ; u32 length
        ; u16 type=PAGELIST_READ (VC -> host RAM)
        ; u16 offset=0
        ; addrs[0] = base page | (number_of_pages - 1)
        move.l  output_pagelist_ptr,a0
        move.l  output_bulk_len,d0
        bsr     store_le32

        move.l  output_pagelist_ptr,a0
        move.b  #PAGELIST_READ,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)

        move.l  output_bulk_len,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        move.l  d0,output_pages
        subq.l  #1,d0
        and.l   #$00000fff,d0
        move.l  output_data_bus,d1
        and.l   #$fffff000,d1
        or.l    d0,d1
        move.l  output_pagelist_ptr,a0
        lea     8(a0),a0
        move.l  d1,d0
        jsr     v94_pl_store             ; v96.94: CM4 = 36-bit pagelist

        ; Pagelist is read FROM RAM by VideoCore.
        move.l  #12,output_pagelist_dma_len
        move.l  output_pagelist_ptr,a0
        lea     output_pagelist_dma_len,a1
        move.l  #DMA_ReadFromRAM,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        move.l  d0,output_pagelist_phys
        cmp.l   output_pagelist_ptr,d0
        bne.w   h19_pagelist_dma_fail
        move.l  output_pagelist_dma_len,d1
        cmp.l   #12,d1
        bcs.w   h19_pagelist_dma_fail
        move.l  #1,output_pagelist_dma_active

        ; Host VCHIQ BULK_RX control record (16-byte stride).
        move.l  #16,d0
        bsr     h26a_reserve_tx
        tst.l   d0
        bne.w   h19_bad_reply

        move.l  a2,a0
        move.l  #VCHIQ_MSG_BULK_RX,d0
        move.l  mmal_remote_port,d1
        or.l    d1,d0
        or.l    port_query_index,d0
        nop
        move.l  d0,output_bulk_rx_msgid
        bsr     store_le32
        lea     4(a2),a0
        move.l  #8,d0
        bsr     store_le32
        lea     8(a2),a0
        move.l  output_pagelist_bus,d0
        bsr     store_le32
        lea     12(a2),a0
        move.l  output_bulk_len,d0
        bsr     store_le32

        move.l  port_tx_pos,d0
        add.l   #16,d0
        move.l  d0,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,output_armed

        move.l  #1,output_bulk_queued

        bsr     dma_pre_all
        move.l  output_armed,d0
        tst.l   d0
        beq.w   h19_after_rx_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
h19_after_rx_bell:
        ; N79P96E library P96 path: return to the bounded API dispatcher.
        ; Standalone player retains its historical tail-enter into h19_poll.
        tst.l   bvp_library_mode
        beq.s   n79p96c_rx_player_poll
        tst.l   bvp_p96_mode
        beq.s   n79p96c_rx_player_poll
        ; N79P96G: h19_queue_bulk_rx called dma_pre_all before ringing VC.
        ; Public library calls must never return with the shared VCHIQ block
        ; still DMA-owned.  The separate output pagelist/data DMA remains live.
        jsr     dma_post_all
        moveq   #0,d0
        rts
n79p96c_rx_player_poll:
        bra.w   h19_poll

; VPv174 - central streaming watchdog reload.
; Preserve D0; set D7 only.  25% (0x0003C000) keeps the proven 100 polls.
; 50% (0x000E6000) and 75% (0x001FE000) get 800 polls on EVERY reload.
vpv183_reload_stream_poll_budget:
        move.l  d0,-(sp)
        ; v005R2: T:/restart catch-up deliberately drives the decoder unpaced.
        ; The normal 50/75%% watchdog can expire while VideoCore is simply busy
        ; with the saturated decode pipeline.  Only during hidden fast-forward
        ; allow the same bounded 4096-poll window already used by cleanup waits.
        ; Normal playback keeps the proven 100/800 budgets unchanged.
        tst.l   v32r_fastforward
        beq.s   vpv005r2_budget_normal_mode
        move.l  #VPV005R2_T_FAST_POLL_COUNT,d7
        bra.s   vpv108_budget_done
vpv005r2_budget_normal_mode:
        move.l  output_buf_size_saved,d0
        cmpi.l  #VPV183_LARGE_FRAME_THRESHOLD,d0
        bcs.s   vpv108_budget_normal
        move.l  #VPV183_LARGE_POLL_COUNT,d7
        bra.s   vpv108_budget_done
vpv108_budget_normal:
        move.l  #POLL_COUNT,d7
vpv108_budget_done:
        move.l  (sp)+,d0
        rts

h19_other_vchiq:
        ; TEST33: ignore expected non-MMAL housekeeping messages silently
        ; during streaming so redirected stdout cannot perturb timing.
        bra.w   h19_consume

h19_consume:
        ; VPv174: every consumed VCHIQ/MMAL message is real forward progress.
        ; Reload the SAME size-aware watchdog budget used after publishes/idle.
        ; 25% (<512 KiB) stays at 100 polls; 50%/75% use 800 throughout.
        jsr     vpv183_reload_stream_poll_budget

        ; TEST33: remember which remote stream slot owns the message
        ; we are about to release. If advancing reaches the next 4-KiB slot,
        ; the previous physical MASTER slot is now completely consumed and
        ; must be returned through master.slot_queue_recycle.
        move.l  port_rx_pos,d1
        move.l  d1,rx_pos_before_consume

        move.l  bulk_rx_size,d0
        add.l   #15,d0
        and.l   #$fffffff8,d0
        add.l   port_rx_pos,d0
        move.l  d0,port_rx_pos

        move.l  rx_pos_before_consume,d0
        move.l  d0,d1
        and.l   #$fffff000,d1
        move.l  port_rx_pos,d2
        and.l   #$fffff000,d2
        cmp.l   d1,d2
        beq.w   h31s_no_rx_slot_recycle
        bsr     h31s_recycle_rx_slot
        tst.l   d0
        bne.w   h31s_recycle_fail
h31s_no_rx_slot_recycle:

        ; TEST26 long run: report the first time either VCHIQ stream position
        ; reaches the next 4-KiB slot. This is diagnostic only; addressing is
        ; intentionally still the proven pre-TEST26 path so a boundary fault is visible.
        bsr     h26_log_slot_crossings

        ; V10P: never keep polling an ERRO storm. The first ERROR record has
        ; already been decoded and logged in h19c_control_event.
        move.l  v10h_error_seen,d0
        tst.l   d0
        bne.w   h19_v10h_error_abort

        ; TEST33: A zero-length OUTPUT BUFFER_TO_HOST still returns ownership
        ; of the output buffer. End its DMA phase and immediately offer the same
        ; header again. Without this, one empty return would leave the decoder
        ; permanently without an output buffer.
        move.l  output_empty_requeue_pending,d0
        tst.l   d0
        beq.w   h31s_no_empty_requeue
        clr.l   output_empty_requeue_pending

        move.l  output_empty_idx,d0
        bsr     h61_post_output_dma_idx
        tst.l   d0
        bne.w   h22_requeue_fail
h31s_empty_dma_closed:
        clr.l   output_buffer_seen
        move.l  output_eos_seen,d0
        tst.l   d0
        bne.s   h264rgb2_empty_terminal
        tst.l   v32_resize_pending
        bne.s   h31s_empty_hold_for_resize
        move.l  output_empty_idx,d0
        bsr     h61_queue_output_idx
        tst.l   d0
        bne.w   h22_requeue_fail
        addq.l  #1,output_empty_requeue_total
        bra.s   h31s_empty_requeue_done_v25
h31s_empty_hold_for_resize:
        addq.l  #1,v32_resize_held
        bra.s   h31s_no_empty_requeue
h31s_empty_requeue_done_v25:
        lea     msg31s_empty_requeued,a1
        move.l  #msg31s_empty_requeued_end-msg31s_empty_requeued,d3
        bsr     print
        move.l  output_frame_total,d0
        bsr     print_hex32
        bsr     newline
        bra.s   h31s_no_empty_requeue
h264rgb2_empty_terminal:
        lea     msg_h264rgb2_output_eos,a1
        move.l  #msg_h264rgb2_output_eos_end-msg_h264rgb2_output_eos,d3
        bsr     print
h31s_no_empty_requeue:

        tst.l   bvp_library_mode
        beq.w   bvp_h19_consume_legacy
        tst.l   bvp_p96_mode
        bne.w   n79p96c_library_output_maint
        moveq   #0,d0
        rts

; N79P96G: dedicated library-mode P96 output maintenance.
; Do not enter the standalone h19_poll/h25 feeder.  The public BerryVP API
; owns compressed input; here we only recycle/display host-facing ISP output.
;
; E fairness rule: after one host P96 BULK_RX completes, do NOT immediately
; chain the next deferred frame when MintVID already has Audio or Video work
; waiting.  Return transport ownership to the library dispatcher for exactly
; one TX turn.  The following TX completion may launch the next deferred RX.
; RX/TX therefore remain fully serialized (the D/mkvr7 safety rule stays).
n79p96c_library_output_maint:
        tst.l   output_bulk_done
        beq.s   n79p96c_try_deferred
        clr.l   output_bulk_done
        clr.l   output_buffer_seen
        clr.l   output_bulk_queued

        tst.l   output_eos_seen
        bne.s   n79p96c_recycle_done
        tst.l   v32_resize_pending
        bne.s   n79p96c_hold_current
        move.l  output_current_idx,d0
        bsr     h61_queue_output_idx
        tst.l   d0
        bne.w   h22_requeue_fail
        bra.s   n79p96c_recycle_done
n79p96c_hold_current:
        addq.l  #1,v32_resize_held
n79p96c_recycle_done:
        clr.l   output_current_eos

        ; N79P96G: a completed host RX opens one serialized TX window.
        ; Audio has first claim below in n66; otherwise pending Video may run.
        tst.l   n65_audio_pending
        bne.s   n79p96c_library_done
        tst.l   n66_video_pending
        bne.s   n79p96c_library_done

n79p96c_try_deferred:
        tst.l   output_deferred_count
        beq.s   n79p96c_library_done
        ; P96W19: never start a deferred BULK_RX while another window-frame
        ; BULK_RX is still in flight.  This maintenance runs after EVERY
        ; consumed message, so without this check a header that was just
        ; deferred (because an RX was active) got popped at once -> two RX
        ; outstanding -> VideoCore bulk engine stuck.
        tst.l   output_bulk_queued
        bne.s   n79p96c_library_done
        tst.l   input_bulk_pending
        bne.s   n79p96c_library_done
        tst.l   vpv39_audio_bulk_pending
        bne.s   n79p96c_library_done
        bra.w   vpv183_pop_deferred_output

n79p96c_library_done:
        moveq   #0,d0
        rts

bvp_h19_consume_legacy:

        ; mkvr7: if an MKV output header waited behind VIDEO/AUDIO BULK_TX,
        ; start its BULK_RX at the first callback where both TX owners are idle.
        tst.l   v10b_input_is_mkv
        beq.s   vpv183_no_tx_deferred_kick
        tst.l   output_bulk_queued
        bne.s   vpv183_no_tx_deferred_kick
        tst.l   output_deferred_count
        beq.s   vpv183_no_tx_deferred_kick
        tst.l   input_bulk_pending
        bne.s   vpv183_no_tx_deferred_kick
        tst.l   vpv39_audio_bulk_pending
        bne.s   vpv183_no_tx_deferred_kick

        addq.l  #1,vpv183_bulk_rx_launch_after_tx
        bra.w   vpv183_pop_deferred_output
vpv183_no_tx_deferred_kick:

        ; TEST26: input blocks and decoded output frames are deliberately independent.
        ; Output: after each completed BULK_RX, immediately recycle the one output buffer.
        move.l  output_bulk_done,d0
        tst.l   d0
        beq.w   h25_check_input_recycle

        clr.l   output_bulk_done
        clr.l   output_buffer_seen
        clr.l   output_bulk_queued

        ; H264RGB2: once decoder OUTPUT EOS has been observed, no more output
        ; buffers are needed. This also covers the case where the EOS-bearing
        ; final header is deferred behind the just-finished payload.
        move.l  output_eos_seen,d0
        tst.l   d0
        bne.s   h264rgb2_skip_current_requeue
        tst.l   v32_resize_pending
        bne.s   h264rgb2_hold_current_for_resize
        move.l  output_current_idx,d0
        bsr     h61_queue_output_idx
        tst.l   d0
        bne.w   h22_requeue_fail
        bra.s   h264rgb2_skip_current_requeue
h264rgb2_hold_current_for_resize:
        addq.l  #1,v32_resize_held
h264rgb2_skip_current_requeue:
        clr.l   output_current_eos

        ; V10P: start the oldest deferred output payload, if any.
        move.l  output_deferred_count,d0
        tst.l   d0
        beq.w   h25_check_input_recycle
        ; mkvr7: MKV keeps TX/RX fully serialized even when another
        ; decoded P96 output was already waiting behind the just-completed RX.
        tst.l   v10b_input_is_mkv
        beq.s   vpv183_pop_deferred_output
        tst.l   input_bulk_pending
        bne.w   h25_check_input_recycle
        tst.l   vpv39_audio_bulk_pending
        bne.w   h25_check_input_recycle

vpv183_pop_deferred_output:
        move.l  output_deferred_head,d3
        move.l  d3,d4
        lsl.l   #2,d4
        lea     output_deferred_idx_q,a0
        move.l  0(a0,d4.l),d0
        lea     output_deferred_len_q,a0
        move.l  0(a0,d4.l),d1
        move.l  d1,output_bulk_len
        lea     output_deferred_eos_q,a0
        move.l  0(a0,d4.l),d1
        move.l  d1,output_current_eos
        ; VPv134: restore the timestamp tuple owned by this FIFO entry.
        lea     output_deferred_pts_lo_q,a0
        move.l  0(a0,d4.l),output_current_pts_lo
        lea     output_deferred_pts_hi_q,a0
        move.l  0(a0,d4.l),output_current_pts_hi
        lea     output_deferred_dts_lo_q,a0
        move.l  0(a0,d4.l),output_current_dts_lo
        lea     output_deferred_dts_hi_q,a0
        move.l  0(a0,d4.l),output_current_dts_hi
        lea     output_deferred_header_wall_q,a0
        move.l  0(a0,d4.l),output_current_header_wall
        addq.l  #1,vpv134_pts_deferred_restores
        addq.l  #1,d3
        cmpi.l  #OUTPUT_POOL_MAX,d3
        bcs.s   v10j_deferred_head_ok
        moveq   #0,d3
v10j_deferred_head_ok:
        move.l  d3,output_deferred_head
        subq.l  #1,output_deferred_count
        bsr     h61_select_output_idx
        tst.l   d0
        bne.w   h22_requeue_fail
        bra.w   h19_queue_bulk_rx

h25_check_input_recycle:
        ; VPv83 retains the VPv74 central playback-control poll.
        bsr     v15_poll_ctrl_c
        ; Promote Taste-Esc only after Intuition event processing fully returned.
        tst.l   vpv81_key_stop_pending
        beq.s   vpv81_no_key_stop_promote
        clr.l   vpv81_key_stop_pending
        ; VPv184: key-repeat / RAWKEY+VANILLA duplicates must not re-arm an
        ; already active C sync-stop.  Re-arming used to reset the 2-second
        ; drain deadline on every repeated '0', making one press look ignored.
        tst.l   vpv169_sync_stop_pending
        bne.s   vpv81_no_key_stop_promote
        tst.l   v15_stop_requested
        bne.s   vpv81_no_key_stop_promote
        ; SPACE-PAUSE: Esc always ends an active pause before the stop starts.
        jsr     vpx_pause_force_resume
        ; mkvr7: freeze resume PTS/mode at the key event, before any C drain.
        jsr     mkvr7_capture_resume
        ; VPv169: TRUE C feed-ahead key-Esc first freezes new video feed, while
        ; Audio-Masterclock remains alive until queued video PTS is crossed.
        tst.l   vpv166_c_sched_feedahead
        beq.s   vpv169_key0_legacy_stop
        move.l  #1,vpv169_sync_stop_pending
        move.l  vpv169_video_submitted_max_pts,vpv169_sync_stop_target_pts
        move.l  vpv170_video_submitted_max_pts_hi,vpv170_sync_stop_target_pts_hi
        bsr     vpv98_read_sys_us
        move.l  d0,vpv169_sync_stop_start_us
        lea     msg_vpv169_sync_stop_arm,a1
        move.l  #msg_vpv169_sync_stop_arm_end-msg_vpv169_sync_stop_arm,d3
        jsr     print
        move.l  vpv170_sync_stop_target_pts_hi,d0
        jsr     print_hex32
        move.l  vpv169_sync_stop_target_pts,d0
        jsr     print_hex32
        jsr     newline
        bra.s   vpv169_key0_latch_done
vpv169_key0_legacy_stop:
        move.l  #1,v15_stop_requested
vpv169_key0_latch_done:
        lea     msg_v40j_key0_stop,a1
        move.l  #msg_v40j_key0_stop_end-msg_v40j_key0_stop,d3
        jsr     print
        ; VPv125 STOP-PROBE: res124 ended directly after the line above.
        ; Capture transport ownership once, without changing stop behaviour.
        lea     msg_vpv125_stop_probe,a1
        move.l  #msg_vpv125_stop_probe_end-msg_vpv125_stop_probe,d3
        jsr     print
        move.l  input_bulk_pending,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv39_audio_bulk_pending,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  output_bulk_queued,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  vpv47_inflight,d0
        jsr     print_hex32
        jsr     newline

vpv138_stop_feed_stats_done:
vpv81_no_key_stop_promote:
        ; VPv169 synchronous C stop: do not feed another video AU. Keep Audio
        ; and VCHIQ alive until an actual audio_renderer return has crossed the
        ; greatest PTS already handed to video_scheduler.
        tst.l   vpv169_sync_stop_pending
        beq.w   vpv169_sync_stop_not_pending
        addq.l  #1,vpv169_sync_stop_wait_polls
        move.l  vpv170_sync_stop_target_pts_hi,d2
        move.l  vpv169_sync_stop_target_pts,d0
        or.l    d2,d0
        beq.s   vpv169_sync_stop_promote
        move.l  vpv170_audio_last_pts_hi,d3
        cmp.l   d2,d3
        bhi.s   vpv169_sync_stop_reached
        bcs.s   vpv170_sync_stop_not_reached
        move.l  vpv135_audio_last_pts,d1
        cmp.l   vpv169_sync_stop_target_pts,d1
        bcc.s   vpv169_sync_stop_reached
vpv170_sync_stop_not_reached:
        tst.l   vpv39_audio_all_done
        bne.s   vpv169_sync_stop_reached
        bsr     vpv98_read_sys_us
        sub.l   vpv169_sync_stop_start_us,d0
        cmpi.l  #2000000,d0
        bcs.s   vpv169_sync_stop_keep_clock
        addq.l  #1,vpv169_sync_stop_timeouts
        lea     msg_vpv169_sync_stop_timeout,a1
        move.l  #msg_vpv169_sync_stop_timeout_end-msg_vpv169_sync_stop_timeout,d3
        jsr     print
        bra.s   vpv169_sync_stop_promote
vpv169_sync_stop_keep_clock:
        jsr     vpv47_audio_service
        jsr     vpv183_reload_stream_poll_budget
        bsr     dma_pre_all
        bra.w   h19_poll
vpv169_sync_stop_reached:
        lea     msg_vpv169_sync_stop_reached,a1
        move.l  #msg_vpv169_sync_stop_reached_end-msg_vpv169_sync_stop_reached,d3
        jsr     print
vpv169_sync_stop_promote:
        clr.l   vpv169_sync_stop_pending
        move.l  #1,v15_stop_requested
vpv169_sync_stop_not_pending:

        ; VPv83 safe stop: stop feeding immediately, but do not synthesize EOF
        ; until BOTH serialized BULK owners are idle.  This avoids entering the
        ; EOS worker path while a second-run Audio or Video DMA transaction is
        ; still completing.
        tst.l   v15_stop_requested
        beq.s   vpv76_stop_not_pending
        clr.l   vpv76_pair_window
        ; VPv126 STOP FIX: do not run Audio housekeeping while a VIDEO BULK
        ; may still own the serialized transport.  The stop path no longer
        ; waits for renderer-owned audio buffers, so reaping them here is
        ; unnecessary and can defer CachePostDMA until MMAL service close.
        ; Only transport BULK ownership gates VIDEO EOS.
        tst.l   input_eof_seen
        bne.s   vpv76_stop_not_pending
        tst.l   input_bulk_pending
        bne.w   vpv130_stop_wait_transport
        tst.l   vpv39_audio_bulk_pending
        bne.w   vpv130_stop_wait_transport
        bra.s   vpv130_stop_transport_idle

vpv130_stop_wait_transport:
        ; VPv130: force a fresh RX poll while a serialized BULK owner is still
        ; active.  h25_check_success/h19_more can reuse an old RX snapshot;
        ; that stranded VPv129 directly after STOP-PROBE with video-bulk=1.
        ; Audio service is already blocked by v15_stop_requested, so this is a
        ; pure transport drain until BULK_TX_DONE clears the owner flag.
        addq.l  #1,vpv130_stop_transport_polls
        tst.l   vpv130_stop_transport_logged
        bne.s   vpv130_stop_wait_no_log
        move.l  #1,vpv130_stop_transport_logged
        lea     msg_vpv130_stop_wait,a1
        move.l  #msg_vpv130_stop_wait_end-msg_vpv130_stop_wait,d3
        jsr     print
vpv130_stop_wait_no_log:
        jsr     vpv183_reload_stream_poll_budget
        bsr     dma_pre_all
        bra.w   h19_poll

vpv130_stop_transport_idle:
        ; VPv102 STOP FIX: renderer-owned audio buffers are NOT a transport
        ; hazard once both serialized BULK_TX owners are idle. Waiting for
        ; vpv47_inflight==0 here can deadlock because audio_render may retain
        ; one/two queued buffers until the MMAL service itself is closed.
        ; Promote VIDEO EOS now; audio DMA ownership is reclaimed only AFTER
        ; confirmed service close in close_prog.
        lea     msg_vpv125_stop_eos,a1
        move.l  #msg_vpv125_stop_eos_end-msg_vpv125_stop_eos,d3
        jsr     print
        move.l  #1,input_eof_seen
        addq.l  #1,vpv76_safe_stop_eos
        bra.w   h25_check_eos_ready
vpv78_stop_wait_audio:
        ; Legacy label retained for branch compatibility; no longer used by
        ; the VPv102 stop path.
        addq.l  #1,vpv78_stop_audio_wait_polls
        bra.w   h25_check_success
vpv76_stop_not_pending:

        ; V41B mode 3: renderer stays alpha=0 while the restart fast-forwards
        ; to the saved frame/sample position, then becomes visible exactly once.
        cmpi.l  #3,v41_display_style
        bne.s   v41b_no_renderer_resume_check
        jsr     v41b_renderer_maybe_show
        ; V41D: once the saved restart position has been reached, stop feeding
        ; new H264 blocks until all currently outstanding input/BULK callbacks
        ; have passed through the normal streaming dispatcher. DISPLAYREGION is
        ; then changed in a quiet RX window instead of racing those callbacks.
        tst.l   v41b_renderer_reveal_pending
        bne.w   h25_check_success
v41b_no_renderer_resume_check:
        ; V40: while a live size switch is active, pause only NEW H264 input.
        ; Existing decoder input/output traffic continues to drain through the
        ; normal callback engine until v40_resize_service advances the phases.
        tst.l   v40_resize_state
        bne.w   h25_check_success

        ; mkvr7: once a Matroska host BULK_RX has started, no new Audio or
        ; Video BULK_TX may be published until RX_DONE.
        tst.l   v10b_input_is_mkv
        beq.s   vpv183_no_active_rx_dispatch_gate
        tst.l   output_bulk_queued
        beq.s   vpv183_no_active_rx_dispatch_gate
        addq.l  #1,vpv183_bulk_tx_blocked_by_rx
        bra.w   h25_check_success
vpv183_no_active_rx_dispatch_gate:

        ; VPv83: one-shot post-VIDEO-BULK refill opportunity.
        ; The ticket is armed only if a renderer return was already waiting
        ; while VIDEO owned the globally serialized transport. Consume it
        ; exactly once. Existing PTS/slot guards stay in vpv47_audio_service.
        ; Success hands the next free transport turn to VIDEO. Failure falls
        ; through immediately to normal RR; this path never waits/free-runs.
        tst.l   vpv83_postvideo_ticket
        beq.s   vpv83_no_postvideo_dispatch
        clr.l   vpv83_postvideo_ticket
        tst.l   input_bulk_pending
        bne.s   vpv83_postvideo_miss
        tst.l   vpv39_audio_bulk_pending
        bne.s   vpv83_postvideo_miss
        jsr     vpv47_audio_service
        tst.l   d0
        beq.s   vpv83_postvideo_miss
        addq.l  #1,vpv83_postvideo_publishes
        move.l  #1,vpv70_rr_turn
        addq.l  #1,vpv70_rr_audio_wins
        jsr     vpv183_reload_stream_poll_budget
        bra.w   h19_poll
vpv83_postvideo_miss:
        addq.l  #1,vpv83_postvideo_misses
vpv83_no_postvideo_dispatch:

        ; VPv70: fair arbitration of the ONE serialized VCHIQ BULK_TX engine.
        ; The old poll loop always asked audio first and immediately restarted
        ; h19_poll after an audio publish. Removing/reducing the audio PTS gate
        ; therefore starved video structurally. Alternate first chance after
        ; every SUCCESSFUL publish instead: 0=audio first, 1=video first.
        ; A side that has nothing sendable falls through to the other side in
        ; the SAME dispatcher pass. No PTS/buffer/decoder policy is changed.
        ; Preserve VPv66 audio housekeeping even while either BULK owns the
        ; transport: reap completed slots/prefetch may run, but service itself
        ; cannot publish because its original BULK guards remain intact.

        ; VPv83 RX-pair window.  AUDIO BULK_TX_DONE has been consumed, so the
        ; global transport is free, while its BUFFER_TO_HOST has deliberately
        ; not yet been consumed. Give Audio ONE immediate chance to queue the
        ; other slot under the existing bounded PTS gate. A successful pair
        ; publish hands the next free transport turn straight back to Video.
        tst.l   vpv76_pair_window
        beq.w   vpv76_no_pair_window
        ; VPv83: VPv77 proved that exact pair bypass is valid but fatal during
        ; decoder startup.  Keep the exact RX window, but arm it only after
        ; 192 decoded/displayed outputs (~7.7 s at 25 fps), then require at
        ; least 8 further video outputs between successful pair publishes.
        ; This preserves video forward progress while placing Slot 2 before
        ; the first observed ~9-10 s audio underrun region.
        move.l  output_frame_total,d0
        cmpi.l  #$000000C0,d0
        bcc.s   vpv78_pair_startup_ok
        clr.l   vpv76_pair_window
        addq.l  #1,vpv78_pair_startup_skips
        bra.w   vpv76_no_pair_window
vpv78_pair_startup_ok:
        move.l  vpv78_pair_last_video,d1
        beq.s   vpv78_pair_cooldown_ok
        move.l  d0,d2
        sub.l   d1,d2
        cmpi.l  #8,d2
        bcc.s   vpv78_pair_cooldown_ok
        clr.l   vpv76_pair_window
        addq.l  #1,vpv78_pair_cooldown_skips
        bra.w   vpv76_no_pair_window
vpv78_pair_cooldown_ok:
        ; State 2 marks the exact AUDIO BULK_DONE -> matching BTH gap.
        ; The PTS gate may bypass only for Slot 2 while exactly one older
        ; renderer-owned slot is still present.
        move.l  #2,vpv76_pair_window
        tst.l   input_bulk_pending
        bne.s   vpv76_pair_missed
        tst.l   vpv39_audio_bulk_pending
        bne.s   vpv76_pair_missed
        jsr     vpv47_audio_service
        clr.l   vpv76_pair_window
        tst.l   d0
        beq.s   vpv76_pair_missed_counted
        addq.l  #1,vpv76_pair_publishes
        move.l  output_frame_total,vpv78_pair_last_video
        move.l  #1,vpv70_rr_turn
        addq.l  #1,vpv70_rr_audio_wins
        jsr     vpv183_reload_stream_poll_budget
        bra.w   h19_poll
vpv76_pair_missed:
        clr.l   vpv76_pair_window
vpv76_pair_missed_counted:
        addq.l  #1,vpv76_pair_misses
vpv76_no_pair_window:
        tst.l   input_bulk_pending
        bne.s   vpv70_bulk_busy_maintenance
        tst.l   vpv39_audio_bulk_pending
        beq.s   vpv70_bulk_idle
vpv70_bulk_busy_maintenance:
        jsr     vpv47_audio_service
        bra.w   h25_check_success
vpv70_bulk_idle:

        tst.l   vpv70_rr_turn
        bne.w   vpv70_video_first

vpv70_audio_first:
        jsr     vpv47_audio_service
        tst.l   d0
        beq.s   vpv70_audio_first_no_publish
        move.l  #1,vpv70_rr_turn
        addq.l  #1,vpv70_rr_audio_wins
        jsr     vpv183_reload_stream_poll_budget
        bra.w   h19_poll
vpv70_audio_first_no_publish:
        tst.l   vpv39_audio_bulk_pending
        bne.w   h25_check_success
        addq.l  #1,vpv70_rr_video_fallbacks
        bra.s   vpv70_try_video

vpv70_video_first:
        move.l  eos_sent,d0
        tst.l   d0
        bne.w   h25_check_success
        move.l  input_eof_seen,d0
        tst.l   d0
        bne.w   h25_check_eos_ready

vpv149_video_first_due:
        ; VPv167: TRUE feed-ahead is deliberately bounded.  When three input
        ; slots already own fresh AU/chunk data, do not enter the feeder again;
        ; give Audio/CPU1 one service opportunity and return to callback polling.
        tst.l   vpv166_c_sched_feedahead
        beq.s   vpv167_video_first_cap_ok
        bsr     vpv167_feedahead_can_feed
        tst.l   d0
        bne.s   vpv167_video_first_cap_ok
        addq.l  #1,vpv70_rr_audio_fallbacks
        jsr     vpv47_audio_service
        tst.l   d0
        beq.w   h25_check_success
        addq.l  #1,vpv167_feedahead_audio_wins
        move.l  #1,vpv70_rr_turn
        addq.l  #1,vpv70_rr_audio_wins
        jsr     vpv183_reload_stream_poll_budget
        bra.w   h19_poll
vpv167_video_first_cap_ok:
        ; VPv102: prevent a new VIDEO BULK from taking the serialized transport
        ; while Audio has only one renderer-owned slot and the next PCM block
        ; is already staged/prefetched. This uses the NORMAL PTS gate only.
        bsr     vpv84_prevideo_audio_guard
        tst.l   d0
        beq.s   vpv84_video_first_guard_done
        move.l  #1,vpv70_rr_turn
        addq.l  #1,vpv70_rr_audio_wins
        jsr     vpv183_reload_stream_poll_budget
        bra.w   h19_poll
vpv84_video_first_guard_done:
        bsr     t31s_feed_next_input
        cmp.l   #1,d0
        beq.w   h22_resend_fail
        tst.l   d0
        beq.w   vpv70_video_published
        cmpi.l  #2,d0
        beq.w   h25_check_eos_ready
        ; D0=3: no free video input slot. Give audio its fallback chance.
        addq.l  #1,vpv70_rr_audio_fallbacks
        jsr     vpv47_audio_service
        tst.l   d0
        beq.w   h25_check_success
        move.l  #1,vpv70_rr_turn
        addq.l  #1,vpv70_rr_audio_wins
        jsr     vpv183_reload_stream_poll_budget
        bra.w   h19_poll

vpv70_try_video:
        move.l  eos_sent,d0
        tst.l   d0
        bne.w   h25_check_success
        move.l  input_eof_seen,d0
        tst.l   d0
        bne.w   h25_check_eos_ready
        tst.l   input_bulk_pending
        bne.w   h25_check_success

vpv149_try_video_due:
        ; VPv167 bounded feed-ahead in the audio-first fallback path. Audio
        ; already had first chance in this dispatcher pass, so a full lead
        ; window simply returns to polling without touching the video feeder.
        tst.l   vpv166_c_sched_feedahead
        beq.s   vpv167_try_video_cap_ok
        bsr     vpv167_feedahead_can_feed
        tst.l   d0
        beq.w   h25_check_success
vpv167_try_video_cap_ok:
        ; Same preventive guard in the audio-first -> video fallback path.
        bsr     vpv84_prevideo_audio_guard
        tst.l   d0
        beq.s   vpv84_try_video_guard_done
        move.l  #1,vpv70_rr_turn
        addq.l  #1,vpv70_rr_audio_wins
        jsr     vpv183_reload_stream_poll_budget
        bra.w   h19_poll
vpv84_try_video_guard_done:
        bsr     t31s_feed_next_input
        cmp.l   #1,d0
        beq.w   h22_resend_fail
        tst.l   d0
        beq.s   vpv70_video_published
        bra.w   h25_check_eos_ready

vpv70_video_published:
        ; A new video block owns the serialized transport. AUDIO is first next.
        clr.l   vpv70_rr_turn
        addq.l  #1,vpv70_rr_video_wins
        addq.l  #1,frame_cycle
        jsr     vpv183_reload_stream_poll_budget
        bra.w   h19_poll

; VPv102: preventive Audio-underfill guard before a new VIDEO BULK.
; Return D0=1 only when one Audio buffer was actually published.
; VPv102 may bypass PTS only inside this exact one-shot guard; never loops/waits.
vpv84_prevideo_audio_guard:
        movem.l d1-d2,-(sp)
        moveq   #0,d0
        tst.l   vpv39_audio_armed
        beq.s   vpv84_prevideo_done
        tst.l   v15_stop_requested
        bne.s   vpv84_prevideo_done
        tst.l   input_eof_seen
        bne.s   vpv84_prevideo_done
        tst.l   input_bulk_pending
        bne.s   vpv84_prevideo_done
        tst.l   vpv39_audio_bulk_pending
        bne.s   vpv84_prevideo_done
        cmpi.l  #1,vpv47_inflight
        bne.s   vpv84_prevideo_done

        ; Do not trigger a CPU1 decode here. A preventive guard is eligible
        ; only when source PCM is already available locally: remaining staged
        ; bytes or the proven prefetched next FAAD batch.
        move.l  vpv53_stage_offset,d1
        cmp.l   vpv53_stage_total,d1
        bcs.s   vpv84_prevideo_source_ready
        tst.l   vpv45_prefetch_ready
        beq.s   vpv84_prevideo_done
vpv84_prevideo_source_ready:
        addq.l  #1,vpv84_prevideo_checks
        ; VPv102: exact one-shot PTS bypass scope.  The flag is live only
        ; for this preventive pre-video service call and only while the
        ; caller has already proven inflight=1 and staged PCM available.
        move.l  #1,vpv85_prevideo_window
        jsr     vpv47_audio_service
        clr.l   vpv85_prevideo_window
        tst.l   d0
        beq.s   vpv84_prevideo_miss
        addq.l  #1,vpv84_prevideo_publishes
        moveq   #1,d0
        bra.s   vpv84_prevideo_done
vpv84_prevideo_miss:
        addq.l  #1,vpv84_prevideo_no_publish
        moveq   #0,d0
vpv84_prevideo_done:
        movem.l (sp)+,d1-d2
        rts

h25_check_eos_ready:
        ; V40B: EOS strictly one-shot.  V40 could re-enter this label from
        ; h19_no_msg after a resize failure and resend EOS indefinitely.
        tst.l   eos_sent
        bne.w   h25_check_success

        ; Once the complete file and final normal BULK_TX are published,
        ; send EOS immediately through the dedicated EOS pool page. Do NOT
        ; wait for every normal MMAL buffer to return: the decoder may hold
        ; one or more input buffers until the EOS marker arrives.
        move.l  input_eof_seen,d0
        tst.l   d0
        beq.w   h25_check_success
        move.l  input_bulk_pending,d0
        tst.l   d0
        bne.w   h25_check_success

        ; TEST33: EOF + kein laufender BULK genuegt. Die Zahl der
        ; Dateibloecke haengt nur von der realen Dateigroesse ab.
        move.l  input_bulk_total,d0
        tst.l   d0
        beq.w   h22_resend_fail

        move.l  v15_stop_requested,d0
        tst.l   d0
        beq.s   v15_eos_natural_message
        lea     msg_v15_ctrlc_eos,a1
        move.l  #msg_v15_ctrlc_eos_end-msg_v15_ctrlc_eos,d3
        bsr     print
        bra.s   v15_eos_message_done
v15_eos_natural_message:
        lea     msg22_three_done,a1
        move.l  #msg22_three_done_end-msg22_three_done,d3
        bsr     print
v15_eos_message_done:
        bra.w   h19a_send_eos

h25_check_success:
        ; HDMI_v41L has no host output buffers. Completion is therefore based
        ; on complete input ownership return + official input EOS. Once that is
        ; true, give ril.video_render a bounded 0.5 s drain window, then consume
        ; any final MMAL/VCHIQ records before declaring the test complete.
        move.l  input_eof_seen,d0
        tst.l   d0
        beq.w   h19_more
        move.l  input_bulk_pending,d0
        tst.l   d0
        bne.w   h19_more
        move.l  input_bulk_total,d0
        cmp.l   input_return_total,d0
        bne.w   h19_more
        tst.l   d0
        beq.w   h19_more
        move.l  eos_bulk_done,d0
        tst.l   d0
        beq.w   h19_more
        move.l  eos_return_seen,d0
        tst.l   d0
        beq.w   h19_more
        move.l  input_in_use_count,d0
        tst.l   d0
        bne.w   h19_more
        move.l  bulk_dma_active,d0
        tst.l   d0
        bne.w   h19_more
        tst.l   vpv39_audio_bulk_pending
        bne.w   h19_more
        ; VPv168: TRUE C feed-ahead can reach compressed VIDEO EOF before
        ; presentation reaches the final PTS.  Natural completion therefore
        ; waits for complete AAC/PCM drain while the unchanged Audio-Masterclock
        ; continues to drive video_scheduler.  Explicit stop retains the proven
        ; immediate service-close path and never waits on renderer-owned PCM.
        tst.l   v15_stop_requested
        bne.s   vpv93_stop_skip_audio_return_wait
        tst.l   vpv166_c_sched_feedahead
        beq.s   vpv168_natural_legacy_audio_wait
        tst.l   vpv39_audio_all_done
        beq.w   h19_more
vpv168_natural_legacy_audio_wait:
        tst.l   vpv47_inflight
        bne.w   h19_more
        tst.l   vpv21_audio_dma_active
        bne.w   h19_more
vpv93_stop_skip_audio_return_wait:

        move.l  hdmi_v40o_drain_done,d0
        tst.l   d0
        bne.w   h19_more

        lea     msg_hdmi_v40o_drain,a1
        move.l  #msg_hdmi_v40o_drain_end-msg_hdmi_v40o_drain,d3
        bsr     print
        ; Delay() must run while the shared VCHIQ block is VideoCore/DMA-owned.
        bsr     dma_pre_all
        move.l  a5,a6
        move.l  #25,d1                 ; 25 DOS ticks = 0.5 s
        jsr     Delay(a6)
        bsr     dma_post_all
        move.l  #1,hdmi_v40o_drain_done
        ; No host output buffers exist in HDMI mode. Reuse the established
        ; cleanup gate bit after the bounded renderer drain has completed.
        move.l  #1,output_eos_seen
        jsr     vpv183_reload_stream_poll_budget
        bra.w   h19_poll


h19_more:
        cmp.l   port_rx_pos,d5
        bhi.w   h19_check

h19_no_msg:
        move.l  hdmi_v40o_drain_done,d0
        tst.l   d0
        bne.w   hdmi_v40o_stream_success

        ; V14: a Ctrl-C may arrive while no VCHIQ record is pending. Once the
        ; current input BULK is idle, route straight into the normal EOS path.
        move.l  v15_stop_requested,d0
        tst.l   d0
        beq.s   h19_no_msg_normal
        ; VPv102: persistent stop requests must re-enter the CENTRAL dispatcher,
        ; which owns the safe input_eof_seen promotion after BULKs are idle.
        ; The old direct jump to h25_check_eos_ready could loop forever with
        ; input_eof_seen still clear.
        bra.w   h25_check_input_recycle
h19_no_msg_normal:
        ; VPv169: key-Esc sync drain owns idle passes too; never re-enter feeder.
        tst.l   vpv169_sync_stop_pending
        bne.w   h25_check_input_recycle
        ; SPACE-PAUSE: callbacks are still drained by h19_poll, but no new video
        ; AU is fed and no new PCM is published.  Reload the stream watchdog so
        ; even a very long pause can never end in h19_timeout.
        tst.l   vpx_pause_active
        beq.s   vpx_not_paused_idle
        jsr     vpv183_reload_stream_poll_budget
        bsr     dma_pre_all
        bra.w   h19_poll
vpx_not_paused_idle:
        ; SPACE-PAUSE: first pass after a resume enters the central dispatcher
        ; once, exactly as if a VCHIQ message had just arrived.
        tst.l   vpx_resume_kick
        beq.s   vpx_no_resume_kick
        clr.l   vpx_resume_kick
        jsr     vpv183_reload_stream_poll_budget
        bra.w   h25_check_input_recycle
vpx_no_resume_kick:
        ; VPv168: compressed video EOF is not movie EOF in TRUE C feed-ahead.
        ; Keep Audio alive until its own EOF/all-done state, and keep polling
        ; stop controls while the final scheduler queue drains.
        tst.l   input_eof_seen
        beq.s   vpv168_no_natural_audio_drain
        tst.l   v15_stop_requested
        bne.s   vpv168_no_natural_audio_drain
        tst.l   vpv166_c_sched_feedahead
        beq.s   vpv168_no_natural_audio_drain
        tst.l   vpv39_audio_all_done
        bne.w   h25_check_success
        bsr     v15_poll_ctrl_c
        ; Key Esc is latched by the Intuition poll and promoted centrally.  This
        ; matters after compressed VIDEO EOF too, when no further VCHIQ message
        ; may otherwise revisit h25_check_input_recycle.
        tst.l   vpv81_key_stop_pending
        bne.w   h25_check_input_recycle
        tst.l   v15_stop_requested
        bne.w   h25_check_input_recycle
        jsr     vpv47_audio_service
        jsr     vpv183_reload_stream_poll_budget
        bsr     dma_pre_all
        bra.w   h19_poll
vpv168_no_natural_audio_drain:
        ; mkvr7: while a Matroska output BULK_RX is active this poll pass
        ; is RX-only. Do not let idle Audio publish BULK_TX over the host RX.
        tst.l   v10b_input_is_mkv
        beq.s   vpv183_no_active_rx_idle_gate
        tst.l   output_bulk_queued
        beq.s   vpv183_no_active_rx_idle_gate
        addq.l  #1,vpv183_bulk_rx_only_wait_polls
        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   h19_poll
        bsr     dma_post_all
        bra.w   h19_timeout
vpv183_no_active_rx_idle_gate:

        ; mkvr7fix: TRUE C may legitimately park up to three H264 AUs inside
        ; video_scheduler.  The old watchdog counted tight host polls, not time.
        ; D0=1 means the C wall-clock wait owns this idle pass.
        jsr     mkvr7_c_sched_wait_service
        tst.l   d0
        bne.w   h19_poll

        ; VPv72: VPv70 proved the RR arbitration, but its callback-driven
        ; dispatcher can become completely idle between paced video frames.
        ; VPv71 fixed liveness by entering the feeder immediately; that made
        ; v04_pace_new_frame busy-wait inside the feeder and blocked audio
        ; service long enough to recreate the periodic HDMI underruns.
        ;
        ; VPv149: even with the real VideoCore scheduler active, do not enter
vpv149_idle_legacy_deadline:

        ; Legacy paths still use the host-side input deadline.
        tst.l   frame_cycle
        beq.s   vpv72_no_dead_idle_wait
        tst.l   v40_resize_state
        bne.s   vpv72_no_dead_idle_wait
        tst.l   eos_sent
        bne.s   vpv72_no_dead_idle_wait
        tst.l   input_eof_seen
        bne.s   vpv72_no_dead_idle_wait
        tst.l   input_bulk_pending
        bne.s   vpv72_no_dead_idle_wait
        tst.l   vpv39_audio_bulk_pending
        bne.s   vpv72_no_dead_idle_wait
        tst.l   input_in_use_count
        bne.s   vpv72_no_dead_idle_wait

        bsr     vpv72_video_due_now
        tst.l   d0
        bne.s   vpv72_idle_video_due

        ; No video is due yet.  Keep Audio alive without entering the video
        ; feeder.  A successful Audio publish consumes this pass exactly like
        ; VPv70 and gives Video first chance on the next free transport slot.
vpv149_idle_video_not_due:
        jsr     vpv47_audio_service
        tst.l   d0
        beq.s   vpv72_idle_wait_only
        move.l  #1,vpv70_rr_turn
        addq.l  #1,vpv70_rr_audio_wins
        addq.l  #1,vpv72_idle_audio_publishes
        jsr     vpv183_reload_stream_poll_budget
        bra.w   h19_poll

vpv72_idle_wait_only:
        addq.l  #1,vpv72_idle_wait_polls
        jsr     vpv183_reload_stream_poll_budget
        bsr     dma_pre_all
        bra.w   h19_poll

vpv72_idle_video_due:
        addq.l  #1,vpv72_idle_due_kicks
        jsr     vpv183_reload_stream_poll_budget
        bra.w   h25_check_input_recycle

vpv72_no_dead_idle_wait:
        ; V40 resize has its own bounded wait counter. Avoid the generic
        ; 100-poll stream timeout while intentionally quiescing the pipeline.
        tst.l   v40_resize_state
        beq.s   v40_no_resize_wait
        jsr     vpv183_reload_stream_poll_budget
        bsr     dma_pre_all
        bra.w   h19_poll
v40_no_resize_wait:
        ; Before input BULK_TX_DONE use full timeout.
        move.l  bulk_done_seen,d0
        tst.l   d0
        beq.w   h19_long_wait

        ; H264RGB2: do not use the legacy EVENT grace path as a success
        ; condition. Completion is now tied to the decoder's real OUTPUT EOS,
        ; so a format/control event can never terminate the movie early.
h19_long_wait:
        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   h19_poll
        bsr     dma_post_all
        bra.w   h19_timeout

h19_event_grace:
        move.l  bulk_grace,d0
        subq.l  #1,d0
        move.l  d0,bulk_grace
        beq.w   h19_success_event
        bsr     dma_pre_all
        bra.w   h19_poll

; H264RGB2 final display drain. If the EOS marker arrived too late to mark
; the final I420 payload inside t31s_stream_current_frame, wait until any
; scheduled last frame has actually become ACTIVE, give it two PAL refreshes
; exactly like the old fixed-frame final path, then restore the system display.
t31s_finish_dynamic_stream:
        movem.l d0-d1,-(sp)
        move.l  t31s_display_started,d0
        tst.l   d0
        beq.s   t31s_finish_dynamic_done
        move.l  #V5_SPIN_TIMEOUT,d0
t31s_finish_dynamic_pending:
        move.l  t31s_pending_valid,d1
        tst.l   d1
        beq.s   t31s_finish_dynamic_pending_done
        subq.l  #1,d0
        bne.s   t31s_finish_dynamic_pending
        move.l  #4,v5_wait_stage
        bsr     v5_mark_wait_timeout
        bra.s   t31s_finish_dynamic_restore
t31s_finish_dynamic_pending_done:
        move.l  #4,v5_wait_stage
        bsr     t31s_wait_frame_start
t31s_finish_dynamic_restore:
        bsr     t30_display_end
        clr.l   t31s_display_started
t31s_finish_dynamic_done:
        movem.l (sp)+,d0-d1
        rts

hdmi_v40o_stream_success:
        lea     msg_vpv21t_stream_success_enter,a1
        move.l  #msg_vpv21t_stream_success_enter_end-msg_vpv21t_stream_success_enter,d3
        jsr     vpv21n_trace
        move.l  hdmi_v40o_live_switches,hdmi_v40o_merge_count
        move.l  hdmi_v40o_live_misses,hdmi_v40o_merge_retry
        lea     msg_hdmi_v40o_hvs_during,a1
        move.l  #msg_hdmi_v40o_hvs_during_end-msg_hdmi_v40o_hvs_during,d3
        bsr     print
        jsr     hdmi_v40o_log_hvs_ptr
        jsr     hdmi_v40o_log_hvs_all
        lea     msg_hdmi_v40o_dump_final,a1
        move.l  #msg_hdmi_v40o_dump_final_end-msg_hdmi_v40o_dump_final,d3
        bsr     print
        move.l  hdmi_v40o_hvs_last,d0
        jsr     hdmi_v40o_dump_dlist_at
        lea     msg_hdmi_v40o_merge_summary,a1
        move.l  #msg_hdmi_v40o_merge_summary_end-msg_hdmi_v40o_merge_summary,d3
        jsr     print
        move.l  hdmi_v40o_merge_count,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_merge_retry_summary,a1
        move.l  #msg_hdmi_v40o_merge_retry_summary_end-msg_hdmi_v40o_merge_retry_summary,d3
        jsr     print
        move.l  hdmi_v40o_merge_retry,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_reassert_summary,a1
        move.l  #msg_hdmi_v40o_reassert_summary_end-msg_hdmi_v40o_reassert_summary,d3
        jsr     print
        move.l  hdmi_v40o_live_reasserts,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_stream_ok,a1
        move.l  #msg_hdmi_v40o_stream_ok_end-msg_hdmi_v40o_stream_ok,d3
        bsr     print
        lea     msg_hdmi_v40o_stream_stats,a1
        move.l  #msg_hdmi_v40o_stream_stats_end-msg_hdmi_v40o_stream_stats,d3
        bsr     print
        move.l  input_bulk_total,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  input_return_total,d0
        bsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_paced_stats,a1
        move.l  #msg_hdmi_v40o_paced_stats_end-msg_hdmi_v40o_paced_stats,d3
        bsr     print
        move.l  v04_paced_frames,d0
        bsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_rtg_frames,a1
        move.l  #msg_hdmi_v40o_rtg_frames_end-msg_hdmi_v40o_rtg_frames,d3
        jsr     print
        move.l  hdmi_v40o_rtg_frames,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_v40c_window_skip_stats,a1
        move.l  #msg_v40c_window_skip_stats_end-msg_v40c_window_skip_stats,d3
        jsr     print
        move.l  v40c_window_wait_skips,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_resize_count,a1
        move.l  #msg_hdmi_v40o_resize_count_end-msg_hdmi_v40o_resize_count,d3
        jsr     print
        move.l  v32_switch_requests,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_resize_apply_count,a1
        move.l  #msg_hdmi_v40o_resize_apply_count_end-msg_hdmi_v40o_resize_apply_count,d3
        jsr     print
        move.l  v32_resize_applied,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  v32_resize_fail,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  v32_resize_held,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_vpv21t_stream_success_return,a1
        move.l  #msg_vpv21t_stream_success_return_end-msg_vpv21t_stream_success_return,d3
        jsr     vpv21n_trace
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

h19_success_frame:
        ; H264RGB2: if the final frame was not already closed by the live EOS
        ; timing path, drain it now before printing diagnostics.
        bsr     t31s_finish_dynamic_stream
        move.l  v5_wait_timeout_stage,d0
        tst.l   d0
        bne.w   h19_v5_wait_fail

        ; TEST33: prove that long-run VCHIQ receive slots were actually returned.
        lea     msg31s_recycle_stats,a1
        move.l  #msg31s_recycle_stats_end-msg31s_recycle_stats,d3
        bsr     print
        move.l  rx_recycle_total,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  rx_recycle_last_slot,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  rx_recycle_last_q,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_rx_pos,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        ; Streaming has already displayed all decoded frames while MMAL/file I/O
        ; were active. Dynamic EOS drain above has also completed the last frame.
        move.l  t31s_display_started,d0
        tst.l   d0
        beq.w   h31e_display_already_off
        bsr     t30_display_end
        clr.l   t31s_display_started
h31e_display_already_off:
        ; TEST33: print only after streaming is complete so diagnostics do not
        ; perturb the frame-critical path. Values are 50-Hz VBlank boundaries.
        lea     msg31u_timing_head,a1
        move.l  #msg31u_timing_head_end-msg31u_timing_head,d3
        bsr     print

        lea     msg31u_run,a1
        move.l  #msg31u_run_end-msg31u_run,d3
        bsr     print
        move.l  t31s_vblank_counter,d0
        bsr     print_hex32
        bsr     newline

        ; Counter 0->1 is the synchronization VBlank at which frame 1 becomes
        ; visible.  Subtract it to report the actual visible RGB interval.
        lea     msg63_visible,a1
        move.l  #msg63_visible_end-msg63_visible,d3
        bsr     print
        move.l  t31s_vblank_counter,d0
        tst.l   d0
        beq.s   t63_visible_zero
        subq.l  #1,d0
t63_visible_zero:
        bsr     print_hex32
        bsr     newline

        lea     msg31u_sum,a1
        move.l  #msg31u_sum_end-msg31u_sum,d3
        bsr     print
        move.l  t31u_gap_total,d0
        add.l   t31u_buffer_total,d0
        add.l   t31u_convert_total,d0
        add.l   t31w_copy_total,d0
        add.l   t31u_post_total,d0
        bsr     print_hex32
        bsr     newline

        lea     msg31u_gap,a1
        move.l  #msg31u_gap_end-msg31u_gap,d3
        bsr     print
        move.l  t31u_gap_total,d0
        bsr     print_hex32
        lea     msg31u_max,a1
        move.l  #msg31u_max_end-msg31u_max,d3
        bsr     print
        move.l  t31u_gap_max,d0
        bsr     print_hex32
        lea     msg31u_nonzero,a1
        move.l  #msg31u_nonzero_end-msg31u_nonzero,d3
        bsr     print
        move.l  t31u_gap_nonzero,d0
        bsr     print_hex32
        bsr     newline

        lea     msg31u_buffer,a1
        move.l  #msg31u_buffer_end-msg31u_buffer,d3
        bsr     print
        move.l  t31u_buffer_total,d0
        bsr     print_hex32
        lea     msg31u_max,a1
        move.l  #msg31u_max_end-msg31u_max,d3
        bsr     print
        move.l  t31u_buffer_max,d0
        bsr     print_hex32
        lea     msg31u_nonzero,a1
        move.l  #msg31u_nonzero_end-msg31u_nonzero,d3
        bsr     print
        move.l  t31u_buffer_nonzero,d0
        bsr     print_hex32
        bsr     newline

        lea     msg31u_convert,a1
        move.l  #msg31u_convert_end-msg31u_convert,d3
        bsr     print
        move.l  t31u_convert_total,d0
        bsr     print_hex32
        lea     msg31u_max,a1
        move.l  #msg31u_max_end-msg31u_max,d3
        bsr     print
        move.l  t31u_convert_max,d0
        bsr     print_hex32
        lea     msg31u_nonzero,a1
        move.l  #msg31u_nonzero_end-msg31u_nonzero,d3
        bsr     print
        move.l  t31u_convert_nonzero,d0
        bsr     print_hex32
        bsr     newline

        lea     msg31w_copy,a1
        move.l  #msg31w_copy_end-msg31w_copy,d3
        bsr     print
        move.l  t31w_copy_total,d0
        bsr     print_hex32
        lea     msg31u_max,a1
        move.l  #msg31u_max_end-msg31u_max,d3
        bsr     print
        move.l  t31w_copy_max,d0
        bsr     print_hex32
        lea     msg31u_nonzero,a1
        move.l  #msg31u_nonzero_end-msg31u_nonzero,d3
        bsr     print
        move.l  t31w_copy_nonzero,d0
        bsr     print_hex32
        bsr     newline

        lea     msg53_dirty,a1
        move.l  #msg53_dirty_end-msg53_dirty,d3
        bsr     print
        move.l  t56_dirty_long_total,d0
        bsr     print_hex32
        lea     msg31u_max,a1
        move.l  #msg31u_max_end-msg31u_max,d3
        bsr     print
        move.l  t56_dirty_long_max,d0
        bsr     print_hex32
        bsr     newline

        lea     msg57_early,a1
        move.l  #msg57_early_end-msg57_early,d3
        bsr     print
        move.l  t57_early_release_total,d0
        bsr     print_hex32
        bsr     newline

        lea     msg61_pipe,a1
        move.l  #msg61_pipe_end-msg61_pipe,d3
        bsr     print
        move.l  t61_deferred_total,d0
        bsr     print_hex32
        lea     msg61_slots,a1
        move.l  #msg61_slots_end-msg61_slots,d3
        bsr     print
        move.l  t61_slot0_frames,d0
        bsr     print_hex32
        lea     msg61_slash,a1
        move.l  #msg61_slash_end-msg61_slash,d3
        bsr     print
        move.l  t61_slot1_frames,d0
        bsr     print_hex32
