; --------------------------------------------------------------------
; TEST33 - release one completely consumed VideoCore/master VCHIQ slot.
;
; Input D0 = absolute RX stream position that belonged to the old slot.
;
; Linux/Broadcom VCHIQ release_slot() returns a fully released remote slot by
; writing its physical slot index to remote->slot_queue[slot_queue_recycle],
; incrementing remote->slot_queue_recycle, and signalling remote->recycle.
; Here VideoCore is MASTER/remote, so the host writes MASTER_QUEUE/RECYCLEQ.
; --------------------------------------------------------------------
h31s_recycle_rx_slot:
        movem.l d1-d7/a0-a2,-(sp)

        ; Map old absolute stream position -> MASTER_QUEUE ring entry.
        move.l  d0,d1
        lsr.l   #8,d1
        lsr.l   #4,d1
        and.l   #$0000003f,d1
        lsl.l   #2,d1
        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a1
        adda.l  d1,a1
        move.l  a1,a0
        bsr     load_le32
        move.l  d0,d5                  ; physical master slot index
        cmp.l   #2,d5
        bcs.w   h31s_recycle_bad
        cmp.l   #32,d5
        bhi.w   h31s_recycle_bad

        ; Append physical slot index to MASTER's recycled-slot ring.
        move.l  slot_ptr,a0
        lea     MASTER_RECYCLEQ(a0),a0
        bsr     load_le32
        move.l  d0,d6                  ; old recycle counter
        move.l  d6,d1
        and.l   #$0000003f,d1
        lsl.l   #2,d1
        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a1
        adda.l  d1,a1
        move.l  a1,a0
        move.l  d5,d0
        bsr     store_le32

        addq.l  #1,d6
        move.l  slot_ptr,a0
        lea     MASTER_RECYCLEQ(a0),a0
        move.l  d6,d0
        bsr     store_le32

        ; Signal MASTER.recycle. Publish queue/counter before ringing BELL2.
        move.l  slot_ptr,a0
        lea     MASTER_RECYCLE_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_RECYCLE_ARM(a0),a0
        bsr     load_le32
        move.l  d0,d4

        addq.l  #1,rx_recycle_total
        move.l  d5,rx_recycle_last_slot
        move.l  d6,rx_recycle_last_q

        ; CachePreDMA is the write barrier visible to VideoCore in this port.
        ; Briefly hand shared memory back, ring if armed, then reacquire it so
        ; the caller can continue parsing the RX stream safely.
        bsr     dma_pre_all
        tst.l   d4
        beq.w   h31s_recycle_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
h31s_recycle_no_bell:
        bsr     short_delay
        bsr     dma_post_all

        moveq   #0,d0
        movem.l (sp)+,d1-d7/a0-a2
        rts

h31s_recycle_bad:
        move.l  #1,rx_recycle_error
        moveq   #1,d0
        movem.l (sp)+,d1-d7/a0-a2
        rts

h31s_recycle_fail:
        tst.l   bvp_library_mode
        beq.s   h31s_recycle_fail_legacy_n10
        move.l  #$FFFFFFF2,v10h_error_status
        move.l  #1,v10h_error_seen
        moveq   #1,d0
        rts
h31s_recycle_fail_legacy_n10:
