; --------------------------------------------------------------------
h26_log_slot_crossings:
        movem.l d0-d3/a1,-(sp)

        move.l  h26_rx_cross_logged,d0
        tst.l   d0
        bne.w   h26_check_tx_cross
        move.l  port_rx_pos,d0
        cmp.l   #$00001000,d0
        bcs.w   h26_check_tx_cross
        move.l  #1,h26_rx_cross_logged
        lea     msg26_rx_cross,a1
        move.l  #msg26_rx_cross_end-msg26_rx_cross,d3
        bsr     print
        move.l  port_rx_pos,d0
        bsr     print_hex32
        bsr     newline

h26_check_tx_cross:
        move.l  h26_tx_cross_logged,d0
        tst.l   d0
        bne.w   h26_cross_done
        move.l  port_tx_pos,d0
        cmp.l   #$00001000,d0
        bcs.w   h26_cross_done
        move.l  #1,h26_tx_cross_logged
        lea     msg26_tx_cross,a1
        move.l  #msg26_tx_cross_end-msg26_tx_cross,d3
        bsr     print
        move.l  port_tx_pos,d0
        bsr     print_hex32
        bsr     newline

h26_cross_done:
