fail_port_timeout:
        lea     e_port_timeout,a1
        move.l  #e_port_timeout_end-e_port_timeout,d3
        bsr     print

        ; VPv21T: PORT_INFO_GET can be called nested from v12a_setup_isp_graph.
        ; On a nested error NEVER jump directly to close_prog, because the
        ; caller still owns its 44-byte MOVEM frame + return address.
        tst.l   v12a_local_get_active
        beq.s   fail_port_timeout_legacy
        ; Timeout loop has handed shared RAM to VideoCore with CachePreDMA.
        ; Reacquire CPU ownership before returning to the graph caller.
        bsr     dma_post_all
        movem.l (sp)+,d2-d7/a2-a3
        moveq   #1,d0
        rts
fail_port_timeout_legacy:
        movem.l (sp)+,d2-d7/a2-a3
        addq.l  #4,sp               ; discard direct BSR return address
        bra.w   close_prog

