input_extradata:
        dcb.b 128,0


        even
; H264RGB4: no test.h264 bytes are embedded here; SPS/PPS are parsed at runtime.

        even
v6_bit_masks:          dc.b $80,$40,$20,$10,$08,$04,$02,$01
        section bss,bss
        even
v6_sps_rbsp:          ds.b 256
v6_xmap_y:            ds.w 256
v6_xmap_c:            ds.w 128
v6_ymap_y:            ds.w 192
v6_ymap_c:            ds.w 96
v6_yrow0:             ds.b 256
v6_yrow1:             ds.b 256
v6_urow:              ds.b 128
v6_vrow:              ds.b 128
        even


; --------------------------------------------------------------------
; V9 private teardown state and routines.
; Kept after legacy state so old PC-relative state references retain range.
; --------------------------------------------------------------------
        even
v9_worker_type: ds.l 1
v9_worker_context: ds.l 1
v9_worker_port: ds.l 1
v9_worker_port_type: ds.l 1
v9_worker_action: ds.l 1
v9_worker_is_port: ds.l 1
v9_cleanup_rx_msgid: ds.l 1
v9_cleanup_rx_size: ds.l 1
v9_cleanup_hdr_status: ds.l 1
v9_cleanup_status: ds.l 1
v9_cleanup_armed: ds.l 1
v9_cleanup_old_rx: ds.l 1
v9_cleanup_failed: ds.l 1
v9_cleanup_stage: ds.l 1
v9_transport_closed: ds.l 1

; Consume current MASTER stream record and recycle the old slot if the
; absolute RX position crosses a 4-KiB VCHIQ slot boundary.
; Entry/return: shared VCHIQ RAM CPU-owned. D0 = payload size.
        section code,code
v9_consume_rx:
        movem.l d1-d3,-(sp)
        move.l  port_rx_pos,d1
        move.l  d1,v9_cleanup_old_rx
        move.l  d0,d2
        add.l   #15,d2
        and.l   #$fffffff8,d2
        add.l   d2,port_rx_pos
        move.l  d1,d2
        and.l   #$fffff000,d2
        move.l  port_rx_pos,d3
        and.l   #$fffff000,d3
        cmp.l   d2,d3
        beq.s   v9_consume_done
        move.l  v9_cleanup_old_rx,d0
        bsr     h31s_recycle_rx_slot
v9_consume_done:
        movem.l (sp)+,d1-d3
        rts

; Synchronous official MMAL worker command.
; For component commands the request is 24-byte MMAL header + handle (28).
; PORT_ACTION uses the official 100-byte request payload. DISABLE only needs
; component_handle/port_handle/action; the union remains zeroed.
; Return D0=0 success / 1 failure, shared RAM CPU-owned.
v9_worker_sync:
        movem.l d2-d7/a0-a3,-(sp)
        clr.l   v9_cleanup_hdr_status
        clr.l   v9_cleanup_status
        addq.l  #1,v9_worker_context
        move.l  v9_worker_context,d0
        and.l   #$00ffffff,d0
        or.l    #$59000000,d0
        move.l  d0,v9_worker_context

        move.l  v9_worker_is_port,d0
        tst.l   d0
        beq.s   v9_worker_component_req
        move.l  #112,d0
        bsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v9_worker_fail
        move.l  a2,a0
        moveq   #27,d7
v9_worker_clear112:
        clr.l   (a0)+
        dbra    d7,v9_worker_clear112
        move.l  #100,d6
        bra.s   v9_worker_build
v9_worker_component_req:
        move.l  #40,d0
        bsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v9_worker_fail
        move.l  a2,a0
        moveq   #9,d7
v9_worker_clear40:
        clr.l   (a0)+
        dbra    d7,v9_worker_clear40
        move.l  #28,d6

v9_worker_build:
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  port_query_index,d1
        and.l   #$000ff000,d1            ; local service: 0 first run, $1000 attached run
        or.l    d1,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32
        lea     4(a2),a0
        move.l  d6,d0
        bsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32
        lea     12(a2),a0
        move.l  v9_worker_type,d0
        bsr     store_le32
        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     20(a2),a0
        move.l  v9_worker_context,d0
        bsr     store_le32
        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     32(a2),a0
        move.l  component_handle,d0
        bsr     store_le32
        move.l  v9_worker_is_port,d0
        tst.l   d0
        beq.w   v9_worker_publish
        lea     36(a2),a0
        move.l  v9_worker_port,d0
        bsr     store_le32
        lea     40(a2),a0
        move.l  v9_worker_action,d0
        bsr     store_le32

        ; V10: PORT_ACTION DISABLE must carry a valid mmal_port snapshot,
        ; just like the proven ENABLE path. V9/V9A left this whole struct
        ; zeroed, so VideoCore ignored the request without a reply.
        lea     52(a2),a0               ; port.type
        move.l  v9_worker_port_type,d0
        bsr     store_le32
        lea     60(a2),a0               ; is_enabled
        move.l  port_enabled,d0
        bsr     store_le32
        lea     68(a2),a0
        move.l  port_buf_num_min,d0
        bsr     store_le32
        lea     72(a2),a0
        move.l  port_buf_size_min,d0
        bsr     store_le32
        lea     76(a2),a0
        move.l  port_buf_align,d0
        bsr     store_le32
        lea     80(a2),a0
        move.l  port_buf_num_rec,d0
        bsr     store_le32
        lea     84(a2),a0
        move.l  port_buf_size_rec,d0
        bsr     store_le32
        lea     88(a2),a0
        move.l  port_buf_num,d0
        bsr     store_le32
        lea     92(a2),a0
        move.l  port_buf_size,d0
        bsr     store_le32
        lea     100(a2),a0              ; opaque userdata cookie
        move.l  v9_worker_context,d0
        bsr     store_le32
        lea     104(a2),a0
        move.l  port_caps,d0
        bsr     store_le32

v9_worker_publish:
        move.l  v9_worker_is_port,d0
        tst.l   d0
        beq.s   v9_worker_stride40
        move.l  #112,d0
        bra.s   v9_worker_stride_ready
v9_worker_stride40:
        move.l  #40,d0
v9_worker_stride_ready:
        add.l   d0,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,v9_cleanup_armed
        bsr     dma_pre_all
        move.l  v9_cleanup_armed,d0
        tst.l   d0
        beq.s   v9_worker_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v9_worker_no_bell:
        move.l  #V10_CLEANUP_POLL_COUNT,d7

v9_worker_poll:
        bsr     short_delay
        bsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5
        cmp.l   port_rx_pos,d5
        bhi.s   v9_worker_have_rx
        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   v9_worker_poll
        bsr     dma_post_all
        bra.w   v9_worker_fail

v9_worker_have_rx:
        bsr     h26a_map_rx_current
        tst.l   d0
        bne.w   v9_worker_fail
        move.l  a2,a0
        bsr     load_le32
        move.l  d0,v9_cleanup_rx_msgid
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,v9_cleanup_rx_size
        move.l  v9_cleanup_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   v9_worker_skip_rx
        move.l  v9_cleanup_rx_msgid,d0
        and.l   #$00000fff,d0
        move.l  port_query_index,d4
        lsr.l   #8,d4
        lsr.l   #4,d4
        and.l   #$00000fff,d4
        cmp.l   d4,d0
        bne.w   v9_worker_skip_rx
        move.l  v9_cleanup_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   v9_worker_skip_rx
        move.l  v9_cleanup_rx_size,d0
        cmp.l   #28,d0
        bcs.w   v9_worker_skip_rx
        lea     8(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   v9_worker_skip_rx
        lea     12(a2),a0
        bsr     load_le32
        cmp.l   v9_worker_type,d0
        bne.w   v9_worker_skip_rx
        lea     20(a2),a0
        bsr     load_le32
        cmp.l   v9_worker_context,d0
        bne.w   v9_worker_skip_rx
        ; V10P: match the official Raspberry Pi MMAL client semantics.
        ; mmal_vc_sendwait_message() treats arrival of the reply as transport
        ; success and the command wrapper decides from mmal_worker_reply.status.
        ; The header.status field is preserved for diagnostics but is NOT the
        ; command result. V10D incorrectly rejected COMPONENT_DESTROY here even
        ; though its 28-byte mmal_worker_reply carried reply.status == 0.
        lea     24(a2),a0
        bsr     load_le32
        move.l  d0,v9_cleanup_hdr_status
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,v9_cleanup_status
        move.l  v9_cleanup_rx_size,d0
        bsr     v9_consume_rx
        move.l  v9_cleanup_status,d0
        tst.l   d0
        bne.w   v9_worker_fail
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a0-a3
        rts
v9_worker_skip_rx:
        move.l  v9_cleanup_rx_size,d0
        bsr     v9_consume_rx
        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   v9_worker_poll
        bsr     dma_post_all
v9_worker_fail:
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a0-a3
        rts

v9_disable_port:
        move.l  d0,v9_worker_port
        move.l  d1,v9_worker_port_type
        move.l  #MMAL_PORT_ACTION,v9_worker_type
        move.l  #MMAL_PORT_ACTION_DISABLE,v9_worker_action
        move.l  #1,v9_worker_is_port
        bsr     v9_worker_sync
        rts

v9_component_cmd:
        move.l  d0,v9_worker_type
        clr.l   v9_worker_is_port
        bsr     v9_worker_sync
        rts

; Close only the VCHIQ mmal service opened by this invocation.
v9_close_service:
        movem.l d2-d7/a0-a2,-(sp)
        move.l  #8,d0
        bsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v9_close_fail
        move.l  a2,a0
        move.l  #VCHIQ_MSG_CLOSE,d0
        move.l  port_query_index,d1
        and.l   #$000ff000,d1            ; local service source bits
        or.l    d1,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32
        lea     4(a2),a0
        moveq   #0,d0
        bsr     store_le32
        addq.l  #8,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,v9_cleanup_armed
        bsr     dma_pre_all
        move.l  v9_cleanup_armed,d0
        tst.l   d0
        beq.s   v9_close_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v9_close_no_bell:
        move.l  #V10_CLEANUP_POLL_COUNT,d7
v9_close_poll:
        bsr     short_delay
        bsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5
        cmp.l   port_rx_pos,d5
        bhi.s   v9_close_have_rx
        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   v9_close_poll
        bsr     dma_post_all
        bra.w   v9_close_fail
v9_close_have_rx:
        bsr     h26a_map_rx_current
        tst.l   d0
        bne.w   v9_close_fail
        move.l  a2,a0
        bsr     load_le32
        move.l  d0,v9_cleanup_rx_msgid
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,v9_cleanup_rx_size
        move.l  v9_cleanup_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_CLOSE,d0
        bne.w   v9_close_skip
        move.l  v9_cleanup_rx_msgid,d0
        and.l   #$00000fff,d0
        move.l  port_query_index,d4
        lsr.l   #8,d4
        lsr.l   #4,d4
        and.l   #$00000fff,d4
        cmp.l   d4,d0
        bne.w   v9_close_skip
        move.l  v9_cleanup_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   v9_close_skip
        move.l  v9_cleanup_rx_size,d0
        bsr     v9_consume_rx
        move.l  #1,v9_transport_closed
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a0-a2
        rts
v9_close_skip:
        move.l  v9_cleanup_rx_size,d0
        bsr     v9_consume_rx
        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   v9_close_poll
        bsr     dma_post_all
v9_close_fail:
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a0-a2
        rts

; --------------------------------------------------------------------
; V10 persistent transport rendezvous
; --------------------------------------------------------------------
; Return D0=0: no prior V10 transport resource (fresh boot / first start)
;        D0=1: existing transport found and validated; diagnostic printed
;        D0=2: resource exists but is invalid; diagnostic printed
v9d_try_attach:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  a4,a6
        lea     v9d_res_name,a1
        jsr     OpenResource(a6)
        tst.l   d0
        beq.w   v9d_attach_none
        move.l  d0,a2
        move.l  a2,v9d_res_ptr

        cmpi.l  #V10_RES_MAGIC,V10_RES_MAGIC_OFS(a2)
        bne.w   v9d_attach_bad
        cmpi.l  #V10_RES_VERSION,V10_RES_VER_OFS(a2)
        bne.w   v9d_attach_bad

        move.l  V10_RES_ALLOC_OFS(a2),slot_alloc
        move.l  V10_RES_PTR_OFS(a2),slot_ptr
        move.l  V10_RES_BUS_OFS(a2),slot_bus
        move.l  V10_RES_PHYS_OFS(a2),slot_phys

        move.l  slot_ptr,d0
        tst.l   d0
        beq.w   v9d_attach_bad
        cmp.l   #$3f000000,d0
        bcc.w   v9d_attach_bad

        ; Re-enter a legal cache/DMA phase for the old global slot block.
        move.l  #DMA_MEM_SIZE,dma_len
        move.l  slot_ptr,a0
        lea     dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        cmp.l   slot_ptr,d0
        bne.w   v9d_attach_bad_dma
        move.l  dma_len,d1
        cmp.l   #DMA_MEM_SIZE,d1
        bcs.w   v9d_attach_bad_dma_post
        move.l  d0,slot_phys

        bsr     dma_post_all

        ; Validate both VCHIQ sides without changing any transport field.
        move.l  slot_ptr,a0
        bsr     load_le32
        cmp.l   #VCHIQ_MAGIC,d0
        bne.w   v9d_attach_bad_cpu
        move.l  slot_ptr,a0
        lea     MASTER_INIT(a0),a0
        bsr     load_le32
        cmp.l   #1,d0
        bne.w   v9d_attach_bad_cpu
        move.l  slot_ptr,a0
        lea     SLAVE_INIT(a0),a0
        bsr     load_le32
        cmp.l   #1,d0
        bne.w   v9d_attach_bad_cpu

        lea     msg_v9d_attach_found,a1
        move.l  #msg_v9d_attach_found_end-msg_v9d_attach_found,d3
        bsr     print
        lea     msg_v9d_attach_ptr,a1
        move.l  #msg_v9d_attach_ptr_end-msg_v9d_attach_ptr,d3
        bsr     print
        move.l  slot_ptr,d0
        bsr     print_hex32
        bsr     newline
        lea     msg_v9d_attach_bus,a1
        move.l  #msg_v9d_attach_bus_end-msg_v9d_attach_bus,d3
        bsr     print
        move.l  slot_bus,d0
        bsr     print_hex32
        bsr     newline
        lea     msg_v9d_attach_mtx,a1
        move.l  #msg_v9d_attach_mtx_end-msg_v9d_attach_mtx,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline
        lea     msg_v9d_attach_stx,a1
        move.l  #msg_v9d_attach_stx_end-msg_v9d_attach_stx,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline
        lea     msg_v9d_attach_mrq,a1
        move.l  #msg_v9d_attach_mrq_end-msg_v9d_attach_mrq,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_RECYCLEQ(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline
        lea     msg_v9d_attach_srq,a1
        move.l  #msg_v9d_attach_srq_end-msg_v9d_attach_srq,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     SLAVE_RECYCLEQ(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        ; Leave global shared memory in DMA ownership exactly as a live VCHIQ
        ; transport expects. No CONNECT/OPEN or stream position is modified.
        bsr     dma_pre_all
        lea     msg_v9d_attach_ok,a1
        move.l  #msg_v9d_attach_ok_end-msg_v9d_attach_ok,d3
        bsr     print
        moveq   #1,d0
        bra.w   v9d_attach_done

v9d_attach_bad_cpu:
        ; CPU currently owns the slot block; return it before exiting.
        bsr     dma_pre_all
        bra.s   v9d_attach_bad
v9d_attach_bad_dma_post:
        move.l  #DMA_MEM_SIZE,dma_len
        move.l  slot_ptr,a0
        lea     dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
v9d_attach_bad_dma:
v9d_attach_bad:
        lea     msg_v9d_attach_bad,a1
        move.l  #msg_v9d_attach_bad_end-msg_v9d_attach_bad,d3
        bsr     print
        moveq   #2,d0
        bra.s   v9d_attach_done
v9d_attach_none:
        moveq   #0,d0
v9d_attach_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Publish the just-initialized slot block as a named persistent Exec resource.
; Return D0=0 success / 1 failure.
v9d_register_resource:
        movem.l d1-d7/a0-a3/a6,-(sp)

        ; Defensive: do not create a duplicate resource.
        move.l  a4,a6
        lea     v9d_res_name,a1
        jsr     OpenResource(a6)
        tst.l   d0
        bne.w   v9d_register_existing

        move.l  a4,a6
        move.l  #V10_RES_SIZE,d0
        move.l  #MEMF_PUBLICFASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   v9d_register_fail
        move.l  d0,a2
        move.l  d0,v9d_res_ptr

        ; Standard Exec Node header. ln_Succ/ln_Pred are filled by AddResource.
        move.b  #NT_RESOURCE,8(a2)
        clr.b   9(a2)
        lea     V10_RES_NAME_OFS(a2),a0
        move.l  a0,10(a2)

        ; Copy name into persistent memory; program text may be unloaded later.
        lea     v9d_res_name,a1
        move.l  #v9d_res_name_end-v9d_res_name,d7
        subq.l  #1,d7
v9d_register_name_loop:
        move.b  (a1)+,(a0)+
        dbra    d7,v9d_register_name_loop

        move.l  #V10_RES_MAGIC,d0
        move.l  d0,V10_RES_MAGIC_OFS(a2)
        move.l  #V10_RES_VERSION,d0
        move.l  d0,V10_RES_VER_OFS(a2)
        move.l  slot_alloc,d0
        move.l  d0,V10_RES_ALLOC_OFS(a2)
        move.l  slot_ptr,d0
        move.l  d0,V10_RES_PTR_OFS(a2)
        move.l  slot_bus,d0
        move.l  d0,V10_RES_BUS_OFS(a2)
        move.l  slot_phys,d0
        move.l  d0,V10_RES_PHYS_OFS(a2)

        move.l  a4,a6
        move.l  a2,a1
        jsr     AddResource(a6)

        ; Verify that Exec can resolve our persistent name immediately.
        move.l  a4,a6
        lea     v9d_res_name,a1
        jsr     OpenResource(a6)
        move.l  a2,d1
        cmp.l   d1,d0
        bne.w   v9d_register_fail

        lea     msg_v9d_register_ok,a1
        move.l  #msg_v9d_register_ok_end-msg_v9d_register_ok,d3
        bsr     print
        moveq   #0,d0
        bra.s   v9d_register_done

v9d_register_existing:
        ; This path should only happen after a partial same-boot retry. Treat the
        ; existing resource as success; startup probe normally catches it earlier.
        moveq   #0,d0
        bra.s   v9d_register_done
v9d_register_fail:
        moveq   #1,d0
v9d_register_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

v9_finish_data_dma:
        movem.l d0-d2/a0-a1/a6,-(sp)
        move.l  output_pagelist_dma_active,d0
        tst.l   d0
        beq.s   v9_dma_out0
        move.l  #12,output_pagelist_dma_len
        move.l  output_pagelist_ptr,a0
        lea     output_pagelist_dma_len,a1
        move.l  #DMA_ReadFromRAM,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   output_pagelist_dma_active
v9_dma_out0:
        moveq   #0,d0
        bsr     h61_post_output_dma_idx
        moveq   #1,d0
        bsr     h61_post_output_dma_idx
        move.l  bulk_dma_active,d0
        tst.l   d0
        beq.s   v9_dma_done
        move.l  #BULK_DMA_SIZE,bulk_dma_len
        move.l  bulk_data_ptr,a0
        lea     bulk_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   bulk_dma_active
v9_dma_done:
        movem.l (sp)+,d0-d2/a0-a1/a6
        rts

v9_free_var:
        movem.l d1/a1/a6,-(sp)
        move.l  (a0),a1
        cmpa.l  #0,a1
        beq.s   v9_free_done
        move.l  d0,d1
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   (a0)
v9_free_done:
        movem.l (sp)+,d1/a1/a6
        rts

v9_free_all:
        movem.l d0/a0,-(sp)
        jsr     v9i_free_chip_diagnostic
        lea     t33_fast_ptr,a0
        move.l  #T37_FAST_FRAME_BYTES,d0
        bsr     v9_free_var
        lea     t56_shadow_ptr,a0
        move.l  #T56_SHADOW_BYTES,d0
        bsr     v9_free_var
        lea     output_alloc,a0
        move.l  output_alloc_size_saved,d0
        bsr     v9_free_var
        lea     bulk_alloc,a0
        move.l  #BULK_ALLOC_SIZE,d0
        bsr     v9_free_var
        lea     prop_alloc,a0
        move.l  #$200,d0
        bsr     v9_free_var
        ; V10: slot_alloc is the global VCHIQ backing store. Firmware has no
        ; per-process VCHIQ deinit tag, so this block must stay valid until reboot.
        movem.l (sp)+,d0/a0
        rts

; V10: compatibility helper. V9I proved the guarded Chip free; V10 also
; reclaims the two exact-base CPU-only Fast RGB blocks.
v9h_free_cpu_rgb_only:
        jsr     v9j_free_cpu_rgb_all
        rts

v9_cleanup_all:
        movem.l d0-d7/a0-a1,-(sp)
        bsr     t31s_display_abort_cleanup
        clr.l   v9_cleanup_failed
        clr.l   v9_cleanup_stage

        ; V10P hypothesis: V10C leaves an enabled MMAL decoder/service alive
        ; after a successful MKV run.  Raw V9M tolerated that, but MKV second
        ; starts can receive an ERRO storm.  Keep ONLY the global VCHIQ transport
        ; persistent.  After a fully drained real EOS, tear down the current
        ; component/service without using PORT_ACTION DISABLE (known to time out
        ; in the older V9 teardown experiments).
        move.l  mmal_remote_port,d0
        tst.l   d0
        beq.w   v9_cleanup_not_safe
        move.l  component_handle,d0
        tst.l   d0
        beq.w   v9_cleanup_not_safe
        move.l  output_eos_seen,d0
        tst.l   d0
        beq.w   v9_cleanup_not_safe
        move.l  eos_return_seen,d0
        tst.l   d0
        beq.w   v9_cleanup_not_safe
        move.l  eos_bulk_done,d0
        tst.l   d0
        beq.w   v9_cleanup_not_safe
        move.l  input_eof_seen,d0
        tst.l   d0
        beq.w   v9_cleanup_not_safe

        ; Callers enter this routine with the persistent slot block DMA-owned.
        ; Regain CPU ownership for synchronous MMAL/VCHIQ teardown traffic.
        bsr     dma_post_all
        lea     msg_v9_cleanup_start,a1
        move.l  #msg_v9_cleanup_start_end-msg_v9_cleanup_start,d3
        bsr     print

        ; HDMI_v41L: tear the tunneled renderer graph down explicitly.
        ; Official MMAL connection teardown first disables the connected output,
        ; then disconnects it.  Only the renderer is COMPONENT_DESTROYed here;
        ; decoder teardown remains the hardware-proven V10P/V14
        ; COMPONENT_DISABLE -> service CLOSE sequence.
        move.l  component_handle,v04_saved_decoder_handle
        move.l  hdmi_v40o_renderer_handle,d0
        beq.w   hdmi_v40o_cleanup_no_renderer

        ; 1) Stop the connected decoder OUTPUT. For DISABLE the VC worker only
        ; consumes component/port/action; the action union is ignored.
        move.l  v04_saved_decoder_handle,component_handle
        move.l  v12a_decoder_output,d0
        move.l  #MMAL_PORT_OUTPUT,d1
        bsr     v9_disable_port
        tst.l   d0
        bne.s   hdmi_v40o_output_disable_warn
        lea     msg_hdmi_v40o_output_disable_ok,a1
        move.l  #msg_hdmi_v40o_output_disable_ok_end-msg_hdmi_v40o_output_disable_ok,d3
        bsr     print
        bra.s   hdmi_v40o_output_disable_done
hdmi_v40o_output_disable_warn:
        lea     msg_hdmi_v40o_output_disable_warn,a1
        move.l  #msg_hdmi_v40o_output_disable_warn_end-msg_hdmi_v40o_output_disable_warn,d3
        bsr     print
hdmi_v40o_output_disable_done:

        ; 2) Remove the active C-mode video tunnel. VPv166 classic container uses
        ; scheduler.output -> renderer.input. Legacy C paths retain decoder -> renderer.
        tst.l   vpv166_c_sched_feedahead
        beq.s   vpv166_cleanup_direct_disconnect
        move.l  vpv117_sched_handle,component_handle
        move.l  vpv117_sched_output0,d0
        move.l  #MMAL_PORT_OUTPUT,d1
        bsr     v9_disable_port
        move.l  vpv117_sched_handle,component_handle
        move.l  vpv117_sched_output0,v9_worker_port
        move.l  #MMAL_PORT_OUTPUT,v9_worker_port_type
        move.l  #MMAL_PORT_ACTION,v9_worker_type
        move.l  #MMAL_PORT_ACTION_DISCONNECT,v9_worker_action
        move.l  #1,v9_worker_is_port
        bsr     v9_worker_sync
        tst.l   d0
        bne.s   vpv166_cleanup_sched_disconnect_warn
        lea     msg_vpv166_sched_disconnect_ok,a1
        move.l  #msg_vpv166_sched_disconnect_ok_end-msg_vpv166_sched_disconnect_ok,d3
        bsr     print
        bra.s   hdmi_v40o_disconnect_done
vpv166_cleanup_sched_disconnect_warn:
        lea     msg_vpv166_sched_disconnect_warn,a1
        move.l  #msg_vpv166_sched_disconnect_warn_end-msg_vpv166_sched_disconnect_warn,d3
        bsr     print
        bra.s   hdmi_v40o_disconnect_done

vpv166_cleanup_direct_disconnect:
        ; Legacy direct decoder.output -> renderer.input tunnel.
        move.l  v04_saved_decoder_handle,component_handle
        move.l  v12a_decoder_output,v9_worker_port
        move.l  #MMAL_PORT_OUTPUT,v9_worker_port_type
        move.l  #MMAL_PORT_ACTION,v9_worker_type
        move.l  #MMAL_PORT_ACTION_DISCONNECT,v9_worker_action
        move.l  #1,v9_worker_is_port
        bsr     v9_worker_sync
        tst.l   d0
        bne.s   hdmi_v40o_disconnect_warn
        lea     msg_hdmi_v40o_disconnect_ok,a1
        move.l  #msg_hdmi_v40o_disconnect_ok_end-msg_hdmi_v40o_disconnect_ok,d3
        bsr     print
        bra.s   hdmi_v40o_disconnect_done
hdmi_v40o_disconnect_warn:
        lea     msg_hdmi_v40o_disconnect_warn,a1
        move.l  #msg_hdmi_v40o_disconnect_warn_end-msg_hdmi_v40o_disconnect_warn,d3
        bsr     print
hdmi_v40o_disconnect_done:

        ; 3) Disable renderer component.
        move.l  hdmi_v40o_renderer_handle,component_handle
        move.l  #MMAL_COMPONENT_DISABLE,d0
        bsr     v9_component_cmd
        tst.l   d0
        bne.s   hdmi_v40o_renderer_disable_warn
        lea     msg_hdmi_v40o_renderer_disable_ok,a1
        move.l  #msg_hdmi_v40o_renderer_disable_ok_end-msg_hdmi_v40o_renderer_disable_ok,d3
        bsr     print
        bra.s   hdmi_v40o_renderer_disable_done
hdmi_v40o_renderer_disable_warn:
        lea     msg_hdmi_v40o_renderer_disable_warn,a1
        move.l  #msg_hdmi_v40o_renderer_disable_warn_end-msg_hdmi_v40o_renderer_disable_warn,d3
        bsr     print
hdmi_v40o_renderer_disable_done:

        ; 4) Unlike the decoder, video_render is now explicitly destroyed so
        ; its display-layer ownership is released before this service closes.
        move.l  hdmi_v40o_renderer_handle,component_handle
        move.l  #MMAL_COMPONENT_DESTROY,d0
        bsr     v9_component_cmd
        tst.l   d0
        bne.s   hdmi_v40o_renderer_destroy_warn
        clr.l   hdmi_v40o_renderer_handle
        clr.l   v12a_isp_handle
        lea     msg_hdmi_v40o_renderer_destroy_ok,a1
        move.l  #msg_hdmi_v40o_renderer_destroy_ok_end-msg_hdmi_v40o_renderer_destroy_ok,d3
        bsr     print
        lea     msg_hdmi_v40o_hvs_after_destroy,a1
        move.l  #msg_hdmi_v40o_hvs_after_destroy_end-msg_hdmi_v40o_hvs_after_destroy,d3
        bsr     print
        jsr     hdmi_v40o_log_hvs_ptr
        bra.s   hdmi_v40o_cleanup_renderer_done
hdmi_v40o_renderer_destroy_warn:
        lea     msg_hdmi_v40o_renderer_destroy_warn,a1
        move.l  #msg_hdmi_v40o_renderer_destroy_warn_end-msg_hdmi_v40o_renderer_destroy_warn,d3
        bsr     print
hdmi_v40o_cleanup_renderer_done:
        move.l  v04_saved_decoder_handle,component_handle
hdmi_v40o_cleanup_no_renderer:
        move.l  v04_saved_decoder_handle,d0
        tst.l   d0
        beq.s   hdmi_v40o_cleanup_decoder_handle_ready
        move.l  d0,component_handle
hdmi_v40o_cleanup_decoder_handle_ready:
        move.l  #1,v9_cleanup_stage
        move.l  #MMAL_COMPONENT_DISABLE,d0
        bsr     v9_component_cmd
        tst.l   d0
        bne.w   v9_cleanup_fail
        lea     msg_v9a_step1_ok,a1
        move.l  #msg_v9a_step1_ok_end-msg_v9a_step1_ok,d3
        bsr     print

        ; V10P: do NOT send COMPONENT_DESTROY here. V10D/E hardware showed that
        ; COMPONENT_DISABLE answers, while the following DESTROY produces no new
        ; worker reply. Instead close this invocation's mmal VCHIQ service. The
        ; VideoCore MMAL service-close path owns cleanup of components associated
        ; with that service.
        move.l  #2,v9_cleanup_stage
        bsr     v9_close_service
        tst.l   d0
        bne.w   v9_cleanup_fail
        lea     msg_v9a_step2_ok,a1
        move.l  #msg_v9a_step2_ok_end-msg_v9a_step2_ok,d3
        bsr     print
        lea     msg_hdmi_v40o_hvs_after_close,a1
        move.l  #msg_hdmi_v40o_hvs_after_close_end-msg_hdmi_v40o_hvs_after_close,d3
        bsr     print
        jsr     hdmi_v40o_log_hvs_ptr

        ; CLOSE acknowledgement is transport-level. Give VideoCore's service-close
        ; worker 25 DOS ticks (0.5 s) to finish deleting service-owned state before
        ; a user can immediately launch the next CLI process. Shared RAM must be
        ; DMA-owned while DOS Delay() runs, matching the proven INIT stabilization.
        lea     msg_v10f2_close_wait,a1
        move.l  #msg_v10f2_close_wait_end-msg_v10f2_close_wait,d3
        bsr     print
        bsr     dma_pre_all
        move.l  a5,a6
        move.l  #25,d1
        jsr     Delay(a6)
        bsr     dma_post_all
        lea     msg_v10f2_close_wait_ok,a1
        move.l  #msg_v10f2_close_wait_ok_end-msg_v10f2_close_wait_ok,d3
        bsr     print

        ; HDMI_v41L: MMAL has now had its full close-stabilization window. Hand
        ; HVS ownership back to the exact VideoCore.card/Workbench list offset
        ; captured before renderer creation. This is the only new MMIO write in
        ; v05 and occurs on a raster-frame boundary.
        bsr     hdmi_v40o_restore_hvs_ptr

        ; The service is closed and can no longer initiate stream transfers.
        ; Finish host-side CachePreDMA mappings before the proven strict gate/free.
        bsr     v9_finish_data_dma

        clr.l   component_handle
        clr.l   hdmi_v40o_renderer_handle
        clr.l   v12a_isp_handle
        clr.l   mmal_remote_port

        ; CPU-only RGB buffers remain exact-base frees as proven by V9I/J.
        jsr     v9j_free_cpu_rgb_all
        ; Preserve V9K/M's strict stream-DMA gate even after component destroy.
        jsr     v9m_try_free_stream_dma
        move.l  d0,d6

        ; Leave the global VCHIQ backing store in the same DMA-owned state in
        ; which the persistent rendezvous expects it between CLI invocations.
        bsr     dma_pre_all

        tst.l   d6
        bne.s   v10d_cleanup_dma_kept
        lea     msg_v9_cleanup_ok,a1
        move.l  #msg_v9_cleanup_ok_end-msg_v9_cleanup_ok,d3
        bsr     print
        bra.w   v9_cleanup_done

v10d_cleanup_dma_kept:
        lea     msg_v10d_dma_kept,a1
        move.l  #msg_v10d_dma_kept_end-msg_v10d_dma_kept,d3
        bsr     print
        bra.w   v9_cleanup_done

v9_cleanup_not_safe:
        ; Failed/early runs have no proven EOS ownership state.  Do not attempt
        ; component/service teardown and do not free DMA-visible stream memory.
        ; The caller already put the persistent slot block into DMA ownership.
        bsr     v9h_free_cpu_rgb_only
        lea     msg_v9h_cpu_rgb_freed,a1
        move.l  #msg_v9h_cpu_rgb_freed_end-msg_v9h_cpu_rgb_freed,d3
        bsr     print
        lea     msg_v9_cleanup_partial,a1
        move.l  #msg_v9_cleanup_partial_end-msg_v9_cleanup_partial,d3
        bsr     print
        bra.w   v9_cleanup_done

v9_cleanup_fail:
        move.l  #1,v9_cleanup_failed
        lea     msg_v9_cleanup_fail,a1
        move.l  #msg_v9_cleanup_fail_end-msg_v9_cleanup_fail,d3
        bsr     print
        move.l  v9_cleanup_stage,d0
        bsr     print_hex32
        lea     msg_v9a_fail_rx,a1
        move.l  #msg_v9a_fail_rx_end-msg_v9a_fail_rx,d3
        bsr     print
        move.l  v9_cleanup_rx_msgid,d0
        bsr     print_hex32
        lea     msg_v9a_fail_size,a1
        move.l  #msg_v9a_fail_size_end-msg_v9a_fail_size,d3
        bsr     print
        move.l  v9_cleanup_rx_size,d0
        bsr     print_hex32
        lea     msg_v9a_fail_status,a1
        move.l  #msg_v9a_fail_status_end-msg_v9a_fail_status,d3
        bsr     print
        move.l  v9_cleanup_status,d0
        bsr     print_hex32
        lea     msg_v10e_fail_hdr_status,a1
        move.l  #msg_v10e_fail_hdr_status_end-msg_v10e_fail_hdr_status,d3
        bsr     print
        move.l  v9_cleanup_hdr_status,d0
        bsr     print_hex32
        bsr     newline

        ; Teardown failed while shared VCHIQ RAM is CPU-owned.  Reclaim only
        ; detached Amiga RGB memory; preserve all DMA-visible stream allocations.
        bsr     v9h_free_cpu_rgb_only
        lea     msg_v9h_cpu_rgb_freed,a1
        move.l  #msg_v9h_cpu_rgb_freed_end-msg_v9h_cpu_rgb_freed,d3
        bsr     print
        bsr     dma_pre_all
        lea     msg_v9a_fail_reboot,a1
        move.l  #msg_v9a_fail_reboot_end-msg_v9a_fail_reboot,d3
        bsr     print

v9_cleanup_done:
        movem.l (sp)+,d0-d7/a0-a1
        rts

        section data,data
