        move.l  #188,v9f_expect_min_abs
        move.l  #48,d0
        jsr     v9f_publish_wait
        tst.l   d0
        bne.w   v9f_get_fail

        ; Fixed PORT_INFO_GET reply identity.
        lea     32(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   v9f_get_bad_consume
        lea     36(a2),a0
        jsr     load_le32
        cmp.l   component_handle,d0
        bne.w   v9f_get_bad_consume
        lea     40(a2),a0
        jsr     load_le32
        cmp.l   port_query_type,d0
        bne.w   v9f_get_bad_consume
        lea     44(a2),a0
        jsr     load_le32
        cmp.l   port_query_index,d0
        bne.w   v9f_get_bad_consume

        lea     52(a2),a0
        jsr     load_le32
        move.l  d0,port_last_handle
        lea     72(a2),a0
        jsr     load_le32
        move.l  d0,port_enabled
        lea     80(a2),a0
        jsr     load_le32
        move.l  d0,port_buf_num_min
        lea     84(a2),a0
        jsr     load_le32
