; ====================================================================
; V10 - CHIP-RAM / FREEMEM DIAGNOSTIC
; ====================================================================
        even

; D0 = current free Chip bytes. AvailMem(attributes) takes attributes in D1.
        section code,code
v9i_avail_chip:
        movem.l d1/a6,-(sp)
        move.l  #MEMF_CHIP,d1
        move.l  a4,a6
        jsr     AvailMem(a6)
        movem.l (sp)+,d1/a6
        rts

v9i_print_chip_before_alloc:
        movem.l d0/d3/a1,-(sp)
        lea     msg_v9i_chip_before_alloc,a1
        move.l  #msg_v9i_chip_before_alloc_end-msg_v9i_chip_before_alloc,d3
        jsr     print
        jsr     v9i_avail_chip
        jsr     print_hex32
        jsr     newline
        movem.l (sp)+,d0/d3/a1
        rts

v9i_print_chip_after_alloc:
        movem.l d0/d3/a1,-(sp)
        lea     msg_v9i_chip_alloc_base,a1
        move.l  #msg_v9i_chip_alloc_base_end-msg_v9i_chip_alloc_base,d3
        jsr     print
        move.l  v9i_chip_alloc_base,d0
        jsr     print_hex32
        lea     msg_v9i_chip_frame_ptr,a1
        move.l  #msg_v9i_chip_frame_ptr_end-msg_v9i_chip_frame_ptr,d3
        jsr     print
        move.l  t30_chip_ptr,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_v9i_chip_after_alloc,a1
        move.l  #msg_v9i_chip_after_alloc_end-msg_v9i_chip_after_alloc,d3
        jsr     print
        jsr     v9i_avail_chip
        jsr     print_hex32
        jsr     newline
        movem.l (sp)+,d0/d3/a1
        rts

; Allocate exact Exec block with 64-byte canary before and after display bytes.
; Returns D0 = frame pointer (base+64), or 0.
v9i_alloc_chip_guarded:
        movem.l d1-d2/d7/a0/a6,-(sp)
        clr.l   v9i_chip_alloc_base
        clr.l   t30_chip_ptr
        move.l  a4,a6
        move.l  #V10_CHIP_ALLOC_BYTES,d0
        move.l  #MEMF_CHIPCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.s   v9i_alloc_chip_done
        move.l  d0,v9i_chip_alloc_base
        move.l  d0,a0
        moveq   #15,d7
v9i_guard_pre_fill:
        move.l  #V10_GUARD_PRE,(a0)+
        dbra    d7,v9i_guard_pre_fill
        move.l  v9i_chip_alloc_base,d0
        add.l   #V10_CHIP_GUARD,d0
        move.l  d0,t30_chip_ptr
        move.l  d0,a0
        add.l   #T30_CHIP_BYTES,a0
        moveq   #15,d7
v9i_guard_post_fill:
        move.l  #V10_GUARD_POST,(a0)+
        dbra    d7,v9i_guard_post_fill
        move.l  t30_chip_ptr,d0
v9i_alloc_chip_done:
        movem.l (sp)+,d1-d2/d7/a0/a6
        rts

; D0=0 both guards OK, 1 prefix changed, 2 suffix changed.
v9i_check_chip_guards:
        movem.l d1/d7/a0,-(sp)
        move.l  v9i_chip_alloc_base,d0
        tst.l   d0
        beq.s   v9i_guard_none
        move.l  d0,a0
        moveq   #15,d7
v9i_guard_pre_check:
        cmp.l   #V10_GUARD_PRE,(a0)+
        bne.s   v9i_guard_bad_pre
        dbra    d7,v9i_guard_pre_check
        move.l  t30_chip_ptr,d0
        move.l  d0,a0
        add.l   #T30_CHIP_BYTES,a0
        moveq   #15,d7
v9i_guard_post_check:
        cmp.l   #V10_GUARD_POST,(a0)+
        bne.s   v9i_guard_bad_post
        moveq   #0,d0
        bra.s   v9i_guard_done
v9i_guard_bad_pre:
        moveq   #1,d0
        bra.s   v9i_guard_done
v9i_guard_bad_post:
        moveq   #2,d0
        bra.s   v9i_guard_done
v9i_guard_none:
        moveq   #0,d0
v9i_guard_done:
        movem.l (sp)+,d1/d7/a0
        rts

; Exact guarded Chip free. If a canary changed, deliberately DO NOT call FreeMem:
; preserving a leak until reboot is safer than damaging Exec's memory lists.
v9i_free_chip_diagnostic:
        movem.l d0-d3/d7/a0-a2/a6,-(sp)
        move.l  v9i_chip_alloc_base,d0
        tst.l   d0
        beq.w   v9i_free_chip_none

        lea     msg_v9i_free_begin,a1
        move.l  #msg_v9i_free_begin_end-msg_v9i_free_begin,d3
        jsr     print
        lea     msg_v9i_free_base,a1
        move.l  #msg_v9i_free_base_end-msg_v9i_free_base,d3
        jsr     print
        move.l  v9i_chip_alloc_base,d0
        jsr     print_hex32
        lea     msg_v9i_free_frame,a1
        move.l  #msg_v9i_free_frame_end-msg_v9i_free_frame,d3
        jsr     print
        move.l  t30_chip_ptr,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_v9i_free_avail_before,a1
        move.l  #msg_v9i_free_avail_before_end-msg_v9i_free_avail_before,d3
        jsr     print
        jsr     v9i_avail_chip
        jsr     print_hex32
        jsr     newline

        jsr     v9i_check_chip_guards
        move.l  d0,d7
        tst.l   d7
        beq.s   v9i_guards_ok
        cmpi.l  #1,d7
        beq.s   v9i_guard_pre_report
        lea     msg_v9i_guard_post_bad,a1
        move.l  #msg_v9i_guard_post_bad_end-msg_v9i_guard_post_bad,d3
        jsr     print
        bra.s   v9i_free_chip_skip
v9i_guard_pre_report:
        lea     msg_v9i_guard_pre_bad,a1
        move.l  #msg_v9i_guard_pre_bad_end-msg_v9i_guard_pre_bad,d3
        jsr     print
        bra.s   v9i_free_chip_skip

v9i_guards_ok:
        lea     msg_v9i_guards_ok,a1
        move.l  #msg_v9i_guards_ok_end-msg_v9i_guards_ok,d3
        jsr     print
        lea     msg_v9i_freemem_now,a1
        move.l  #msg_v9i_freemem_now_end-msg_v9i_freemem_now,d3
        jsr     print

        move.l  v9i_chip_alloc_base,a1
        move.l  #V10_CHIP_ALLOC_BYTES,d0
        move.l  a4,a6
        jsr     FreeMem(a6)

        ; If AN_BadFreeAddr is raised inside FreeMem, this line is the critical
        ; marker: hardware will not reach it before the alert dialog.
        lea     msg_v9i_freemem_returned,a1
        move.l  #msg_v9i_freemem_returned_end-msg_v9i_freemem_returned,d3
        jsr     print
        clr.l   v9i_chip_alloc_base
        clr.l   t30_chip_ptr
        lea     msg_v9i_free_avail_after,a1
        move.l  #msg_v9i_free_avail_after_end-msg_v9i_free_avail_after,d3
        jsr     print
        jsr     v9i_avail_chip
        jsr     print_hex32
        jsr     newline
        bra.s   v9i_free_chip_done

v9i_free_chip_skip:
        lea     msg_v9i_free_skipped,a1
        move.l  #msg_v9i_free_skipped_end-msg_v9i_free_skipped,d3
        jsr     print
        bra.s   v9i_free_chip_done
v9i_free_chip_none:
        lea     msg_v9i_free_none,a1
        move.l  #msg_v9i_free_none_end-msg_v9i_free_none,d3
        jsr     print
v9i_free_chip_done:
        movem.l (sp)+,d0-d3/d7/a0-a2/a6
        rts

        section data,data
msg_v9i_chip_before_alloc:
        dc.b "[V10P] Chip frei VOR guarded HAM6-Alloc: 0x"
msg_v9i_chip_before_alloc_end:
msg_v9i_chip_alloc_base:
        dc.b "[V10P] Chip Alloc-Basis=0x"
msg_v9i_chip_alloc_base_end:
msg_v9i_chip_frame_ptr:
        dc.b "  Frame-Pointer=0x"
msg_v9i_chip_frame_ptr_end:
msg_v9i_chip_after_alloc:
        dc.b "[V10P] Chip frei NACH guarded HAM6-Alloc: 0x"
msg_v9i_chip_after_alloc_end:
msg_v9i_free_begin:
        dc.b 10,"[V10P] CHIP-FREEMEM-DIAGNOSE beginnt.",10
msg_v9i_free_begin_end:
msg_v9i_free_base:
        dc.b "[V10P] gespeicherte Alloc-Basis=0x"
msg_v9i_free_base_end:
msg_v9i_free_frame:
        dc.b "  Frame-Pointer=0x"
msg_v9i_free_frame_end:
msg_v9i_free_avail_before:
        dc.b "[V10P] Chip frei direkt VOR FreeMem: 0x"
msg_v9i_free_avail_before_end:
msg_v9i_guards_ok:
        dc.b "[V10P] Guard VOR/NACH HAM6-Puffer: OK.",10
msg_v9i_guards_ok_end:
msg_v9i_guard_pre_bad:
        dc.b "[V10P] FEHLER: vorderer Chip-Guard wurde veraendert. FreeMem wird NICHT aufgerufen.",10
msg_v9i_guard_pre_bad_end:
msg_v9i_guard_post_bad:
        dc.b "[V10P] FEHLER: hinterer Chip-Guard wurde veraendert. FreeMem wird NICHT aufgerufen.",10
msg_v9i_guard_post_bad_end:
msg_v9i_freemem_now:
        dc.b "[V10P] Rufe jetzt FreeMem(exakte Alloc-Basis,41600) auf ...",10
msg_v9i_freemem_now_end:
msg_v9i_freemem_returned:
        dc.b "[V10P] FreeMem ist normal zurueckgekehrt: OK.",10
msg_v9i_freemem_returned_end:
msg_v9i_free_avail_after:
        dc.b "[V10P] Chip frei NACH FreeMem: 0x"
msg_v9i_free_avail_after_end:
msg_v9i_free_skipped:
        dc.b "[V10P] Chip-Free aus Sicherheitsgruenden uebersprungen; jetzt rebooten.",10
msg_v9i_free_skipped_end:
msg_v9i_free_none:
        dc.b "[V10P] Kein guarded Chip-Block vorhanden; nichts freizugeben.",10
msg_v9i_free_none_end:
        even

; ====================================================================
; V10 - FAST RGB FREE + DMA RETENTION DIAGNOSTICS
; ====================================================================
        even

; AvailMem(MEMF_FAST) for before/after accounting.
        section code,code
v9j_avail_fast:
        movem.l d1/a6,-(sp)
        move.l  #MEMF_FAST,d1
        move.l  a4,a6
        jsr     AvailMem(a6)
        movem.l (sp)+,d1/a6
        rts

; Free only blocks that are provably CPU/Amiga-display-owned after the display
; teardown. t33_fast_ptr and t56_shadow_ptr are the exact AllocMem return values;
; unlike the HAM display pointer they are never interior/aligned pointers.
v9j_free_cpu_rgb_all:
        movem.l d0-d3/a0-a2/a6,-(sp)

        ; Keep the V9I guarded/exact-base Chip path unchanged.
        jsr     v9i_free_chip_diagnostic

        lea     msg_v9j_fast_begin,a1
        move.l  #msg_v9j_fast_begin_end-msg_v9j_fast_begin,d3
        jsr     print
        lea     msg_v9j_fast_avail_before,a1
        move.l  #msg_v9j_fast_avail_before_end-msg_v9j_fast_avail_before,d3
        jsr     print
        jsr     v9j_avail_fast
        jsr     print_hex32
        jsr     newline

        move.l  t33_fast_ptr,d0
        beq.s   v9j_fast_scratch_none
        lea     msg_v9j_fast_scratch,a1
        move.l  #msg_v9j_fast_scratch_end-msg_v9j_fast_scratch,d3
        jsr     print
        move.l  t33_fast_ptr,d0
        jsr     print_hex32
        jsr     newline
        move.l  t33_fast_ptr,a1
        move.l  #T37_FAST_FRAME_BYTES,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   t33_fast_ptr
        lea     msg_v9j_fast_scratch_ok,a1
        move.l  #msg_v9j_fast_scratch_ok_end-msg_v9j_fast_scratch_ok,d3
        jsr     print
v9j_fast_scratch_none:

        move.l  t56_shadow_ptr,d0
        beq.s   v9j_fast_shadow_none
        lea     msg_v9j_fast_shadow,a1
        move.l  #msg_v9j_fast_shadow_end-msg_v9j_fast_shadow,d3
        jsr     print
        move.l  t56_shadow_ptr,d0
        jsr     print_hex32
        jsr     newline
        move.l  t56_shadow_ptr,a1
        move.l  #T56_SHADOW_BYTES,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   t56_shadow_ptr
        lea     msg_v9j_fast_shadow_ok,a1
        move.l  #msg_v9j_fast_shadow_ok_end-msg_v9j_fast_shadow_ok,d3
        jsr     print
v9j_fast_shadow_none:

        lea     msg_v9j_fast_avail_after,a1
        move.l  #msg_v9j_fast_avail_after_end-msg_v9j_fast_avail_after,d3
        jsr     print
        jsr     v9j_avail_fast
        jsr     print_hex32
        jsr     newline
        lea     msg_v9j_cpu_free_ok,a1
        move.l  #msg_v9j_cpu_free_ok_end-msg_v9j_cpu_free_ok,d3
        jsr     print

        movem.l (sp)+,d0-d3/a0-a2/a6
        rts

; V10 deliberately does NOT free VideoCore-visible output/input DMA blocks yet.
; The old component/service cannot be disabled reliably, so ownership must be
; proven before reuse/free. Log all relevant host-side flags so the next step
; can distinguish a reclaimable input pool from a possibly VC-owned output slot.
v9j_report_dma_retained:
        movem.l d0-d3/a1,-(sp)
        lea     msg_v9j_dma_head,a1
        move.l  #msg_v9j_dma_head_end-msg_v9j_dma_head,d3
        jsr     print
        lea     msg_v9j_dma_output,a1
        move.l  #msg_v9j_dma_output_end-msg_v9j_dma_output,d3
        jsr     print
        move.l  output_alloc,d0
        jsr     print_hex32
        lea     msg_v9j_dma_bulk,a1
        move.l  #msg_v9j_dma_bulk_end-msg_v9j_dma_bulk,d3
        jsr     print
        move.l  bulk_alloc,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_v9j_dma_outflags,a1
        move.l  #msg_v9j_dma_outflags_end-msg_v9j_dma_outflags,d3
        jsr     print
        jsr     v10j_count_output_dma_active
        jsr     print_hex32
        lea     msg_v9j_slash,a1
        move.l  #msg_v9j_slash_end-msg_v9j_slash,d3
        jsr     print
        move.l  output_pagelist_dma_active,d0
        jsr     print_hex32
        lea     msg_v9j_slash,a1
        move.l  #msg_v9j_slash_end-msg_v9j_slash,d3
        jsr     print
        move.l  output_bulk_queued,d0
        jsr     print_hex32
        lea     msg_v9j_slash,a1
        move.l  #msg_v9j_slash_end-msg_v9j_slash,d3
        jsr     print
        move.l  output_deferred_count,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_v9j_dma_inflags,a1
        move.l  #msg_v9j_dma_inflags_end-msg_v9j_dma_inflags,d3
        jsr     print
        move.l  input_in_use_count,d0
        jsr     print_hex32
        lea     msg_v9j_slash,a1
        move.l  #msg_v9j_slash_end-msg_v9j_slash,d3
        jsr     print
        move.l  input_bulk_pending,d0
        jsr     print_hex32
        lea     msg_v9j_slash,a1
        move.l  #msg_v9j_slash_end-msg_v9j_slash,d3
        jsr     print
        move.l  bulk_dma_active,d0
        jsr     print_hex32
        lea     msg_v9j_slash,a1
        move.l  #msg_v9j_slash_end-msg_v9j_slash,d3
        jsr     print
        move.l  input_return_total,d0
        jsr     print_hex32
        lea     msg_v9j_slash,a1
        move.l  #msg_v9j_slash_end-msg_v9j_slash,d3
        jsr     print
        move.l  input_bulk_total,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_v9j_dma_keep,a1
        move.l  #msg_v9j_dma_keep_end-msg_v9j_dma_keep,d3
        jsr     print
        movem.l (sp)+,d0-d3/a1
        rts

        section data,data
msg_v9j_fast_begin:
        dc.b "[V10P] Fast-RGB-Freigabe: exakte AllocMem-Basen fuer Scratch/Shadow.",10
msg_v9j_fast_begin_end:
msg_v9j_fast_avail_before:
        dc.b "[V10P] Fast frei VOR RGB-Free: 0x"
msg_v9j_fast_avail_before_end:
msg_v9j_fast_scratch:
        dc.b "[V10P] FreeMem Fast-Scratch 20736 @ 0x"
msg_v9j_fast_scratch_end:
msg_v9j_fast_scratch_ok:
        dc.b "[V10P] Fast-Scratch FreeMem: OK.",10
msg_v9j_fast_scratch_ok_end:
msg_v9j_fast_shadow:
        dc.b "[V10P] FreeMem Fast-Shadow 41472 @ 0x"
msg_v9j_fast_shadow_end:
msg_v9j_fast_shadow_ok:
        dc.b "[V10P] Fast-Shadow FreeMem: OK.",10
msg_v9j_fast_shadow_ok_end:
msg_v9j_fast_avail_after:
        dc.b "[V10P] Fast frei NACH RGB-Free: 0x"
msg_v9j_fast_avail_after_end:
msg_v9j_cpu_free_ok:
        dc.b "[V10P] CPU-only RGB komplett freigegeben: Chip + 62208 Byte Fast.",10
msg_v9j_cpu_free_ok_end:
msg_v9j_dma_head:
        dc.b "[V10P] DMA-Reststatus (Referenzfunktion):",10
msg_v9j_dma_head_end:
msg_v9j_dma_output:
        dc.b "[V10P] output_alloc=0x"
msg_v9j_dma_output_end:
msg_v9j_dma_bulk:
        dc.b "  bulk_alloc=0x"
msg_v9j_dma_bulk_end:
msg_v9j_dma_outflags:
        dc.b "[V10P] OUT active/pagelist/bulkqueued/deferred=0x"
msg_v9j_dma_outflags_end:
msg_v9j_dma_inflags:
        dc.b "[V10P] IN inuse/bulkpending/bulkdma/returned/sent=0x"
msg_v9j_dma_inflags_end:
msg_v9j_slash:
        dc.b "/"
msg_v9j_slash_end:
msg_v9j_dma_keep:
        dc.b "[V10P] Referenz: Outputpool + Input-Pool dynamisch; VPv140 Input-Pool=0x0014B000; der globale VCHIQ-Slotblock bleibt persistent.",10
        dc.b "[V10P] Normalpfad verwendet stattdessen den streng gegateten DMA-Free-Test.",10
msg_v9j_dma_keep_end:
        even

; ====================================================================
; V10 - STRICT EOS/OWNERSHIP-GATED STREAM DMA FREE
; ====================================================================
        even

; V9J hardware evidence after several real streams:
;   OUT dma0/dma1/pagelist/bulkqueued = 0/0/0/0
;   IN  inuse/bulkpending/bulkdma      = 0/0/0
;   returned == sent
; and real decoder OUTPUT EOS + input EOS completion were observed.
;
; V10 frees output_alloc and bulk_alloc only if ALL of those conditions still
; hold in the current run. output_alloc/bulk_alloc are the original exact
; AllocMem return values; aligned output_data_ptr*/bulk_pool_base are NEVER
; passed to FreeMem. The global VCHIQ slot backing store is not touched.
;
; Return D0=0: DMA blocks freed (or already zero)
;        D0=1: gate refused; DMA blocks deliberately kept resident
        section code,code
v9m_try_free_stream_dma:
        movem.l d1-d7/a0-a2/a6,-(sp)

        lea     msg_v9m_dma_begin,a1
        move.l  #msg_v9m_dma_begin_end-msg_v9m_dma_begin,d3
        jsr     print

        ; Print exact AllocMem bases first.
        lea     msg_v9m_dma_ptrs,a1
        move.l  #msg_v9m_dma_ptrs_end-msg_v9m_dma_ptrs,d3
        jsr     print
        move.l  output_alloc,d0
        jsr     print_hex32
        lea     msg_v9m_dma_bulkptr,a1
        move.l  #msg_v9m_dma_bulkptr_end-msg_v9m_dma_bulkptr,d3
        jsr     print
        move.l  bulk_alloc,d0
        jsr     print_hex32
        jsr     newline

        ; Mirror V9J's hardware-relevant ownership state in the log.
        lea     msg_v9m_dma_outflags,a1
        move.l  #msg_v9m_dma_outflags_end-msg_v9m_dma_outflags,d3
        jsr     print
        jsr     v10j_count_output_dma_active
        jsr     print_hex32
        lea     msg_v9m_slash,a1
        move.l  #msg_v9m_slash_end-msg_v9m_slash,d3
        jsr     print
        move.l  output_pagelist_dma_active,d0
        jsr     print_hex32
        lea     msg_v9m_slash,a1
        move.l  #msg_v9m_slash_end-msg_v9m_slash,d3
        jsr     print
        move.l  output_bulk_queued,d0
        jsr     print_hex32
        lea     msg_v9m_slash,a1
        move.l  #msg_v9m_slash_end-msg_v9m_slash,d3
        jsr     print
        move.l  output_deferred_count,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_v9m_dma_inflags,a1
        move.l  #msg_v9m_dma_inflags_end-msg_v9m_dma_inflags,d3
        jsr     print
        move.l  input_in_use_count,d0
        jsr     print_hex32
        lea     msg_v9m_slash,a1
        move.l  #msg_v9m_slash_end-msg_v9m_slash,d3
        jsr     print
        move.l  input_bulk_pending,d0
        jsr     print_hex32
        lea     msg_v9m_slash,a1
        move.l  #msg_v9m_slash_end-msg_v9m_slash,d3
        jsr     print
        move.l  bulk_dma_active,d0
        jsr     print_hex32
        lea     msg_v9m_slash,a1
        move.l  #msg_v9m_slash_end-msg_v9m_slash,d3
        jsr     print
        move.l  input_return_total,d0
        jsr     print_hex32
        lea     msg_v9m_slash,a1
        move.l  #msg_v9m_slash_end-msg_v9m_slash,d3
        jsr     print
        move.l  input_bulk_total,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_v9m_dma_eosflags,a1
        move.l  #msg_v9m_dma_eosflags_end-msg_v9m_dma_eosflags,d3
        jsr     print
        move.l  input_eof_seen,d0
        jsr     print_hex32
        lea     msg_v9m_slash,a1
        move.l  #msg_v9m_slash_end-msg_v9m_slash,d3
        jsr     print
        move.l  eos_bulk_done,d0
        jsr     print_hex32
        lea     msg_v9m_slash,a1
        move.l  #msg_v9m_slash_end-msg_v9m_slash,d3
        jsr     print
        move.l  eos_return_seen,d0
        jsr     print_hex32
        lea     msg_v9m_slash,a1
        move.l  #msg_v9m_slash_end-msg_v9m_slash,d3
        jsr     print
        move.l  output_eos_seen,d0
        jsr     print_hex32
        jsr     newline

        ; Strict no-active-DMA gate.
        jsr     v10j_count_output_dma_active
        tst.l   d0
        bne.w   v9m_dma_gate_refuse
        tst.l   output_pagelist_dma_active
        bne.w   v9m_dma_gate_refuse
        tst.l   output_bulk_queued
        bne.w   v9m_dma_gate_refuse
        tst.l   output_bulk_done
        bne.w   v9m_dma_gate_refuse
        tst.l   output_deferred_count
        bne.w   v9m_dma_gate_refuse
        tst.l   output_empty_requeue_pending
        bne.w   v9m_dma_gate_refuse
        tst.l   input_in_use_count
        bne.w   v9m_dma_gate_refuse
        tst.l   input_bulk_pending
        bne.w   v9m_dma_gate_refuse
        tst.l   bulk_dma_active
        bne.w   v9m_dma_gate_refuse

        ; Every normal input MMAL buffer must have come back.
        move.l  input_return_total,d0
        cmp.l   input_bulk_total,d0
        bne.w   v9m_dma_gate_refuse
        tst.l   d0
        beq.w   v9m_dma_gate_refuse

        ; Require the full real-EOF / input-EOS / decoder-output-EOS sequence.
        tst.l   input_eof_seen
        beq.w   v9m_dma_gate_refuse
        tst.l   eos_bulk_done
        beq.w   v9m_dma_gate_refuse
        tst.l   eos_return_seen
        beq.w   v9m_dma_gate_refuse
        tst.l   output_eos_seen
        beq.w   v9m_dma_gate_refuse

        lea     msg_v9m_dma_gate_ok,a1
        move.l  #msg_v9m_dma_gate_ok_end-msg_v9m_dma_gate_ok,d3
        jsr     print

        ; Accounting before freeing. MEMF_FAST total is sufficient here because
        ; both stream blocks were allocated with MEMF_FASTCLEAR.
        lea     msg_v9m_dma_fast_before,a1
        move.l  #msg_v9m_dma_fast_before_end-msg_v9m_dma_fast_before,d3
        jsr     print
        jsr     v9m_avail_fast
        move.l  d0,d7
        jsr     print_hex32
        jsr     newline

        ; Exact AllocMem base: output_alloc, NOT aligned output_data_ptr0.
        move.l  output_alloc,d0
        beq.s   v9m_dma_output_done
        lea     msg_v9m_dma_free_output,a1
        move.l  #msg_v9m_dma_free_output_end-msg_v9m_dma_free_output,d3
        jsr     print
        move.l  output_alloc,d0
        jsr     print_hex32
        jsr     newline
        move.l  output_alloc,a1
        move.l  output_alloc_size_saved,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   output_alloc
        clr.l   output_data_ptr
        clr.l   output_data_ptr0
        clr.l   output_data_ptr1
        clr.l   output_data_bus
        clr.l   output_pagelist_ptr
        clr.l   output_pagelist_bus
        clr.l   output_pagelist_phys
        lea     msg_v9m_dma_free_output_ok,a1
        move.l  #msg_v9m_dma_free_output_ok_end-msg_v9m_dma_free_output_ok,d3
        jsr     print
v9m_dma_output_done:

        ; Exact AllocMem base: bulk_alloc, NOT aligned bulk_pool_base/data ptr.
        move.l  bulk_alloc,d0
        beq.s   v9m_dma_bulk_done
        lea     msg_v9m_dma_free_bulk,a1
        move.l  #msg_v9m_dma_free_bulk_end-msg_v9m_dma_free_bulk,d3
        jsr     print
        move.l  bulk_alloc,d0
        jsr     print_hex32
        jsr     newline
        move.l  bulk_alloc,a1
        move.l  #BULK_ALLOC_SIZE,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   bulk_alloc
        clr.l   bulk_pool_base
        clr.l   bulk_data_ptr
        clr.l   bulk_data_bus
        clr.l   bulk_pagelist_ptr
        clr.l   bulk_pagelist_bus
        clr.l   bulk_phys
        lea     msg_v9m_dma_free_bulk_ok,a1
        move.l  #msg_v9m_dma_free_bulk_ok_end-msg_v9m_dma_free_bulk_ok,d3
        jsr     print
v9m_dma_bulk_done:

        lea     msg_v9m_dma_fast_after,a1
        move.l  #msg_v9m_dma_fast_after_end-msg_v9m_dma_fast_after,d3
        jsr     print
        jsr     v9m_avail_fast
        move.l  d0,d6
        jsr     print_hex32
        jsr     newline
        lea     msg_v9m_dma_delta,a1
        move.l  #msg_v9m_dma_delta_end-msg_v9m_dma_delta,d3
        jsr     print
        move.l  d6,d0
        sub.l   d7,d0
        move.l  d0,d5
        jsr     print_hex32
        move.l  output_alloc_size_saved,d4
        add.l   #BULK_ALLOC_SIZE,d4
        cmp.l   d4,d5
        bne.s   v9m_dma_delta_bad
        lea     msg_v9m_dma_delta_ok,a1
        move.l  #msg_v9m_dma_delta_ok_end-msg_v9m_dma_delta_ok,d3
        jsr     print
        bra.s   v9m_dma_delta_done
v9m_dma_delta_bad:
        lea     msg_v9m_dma_delta_warn,a1
        move.l  #msg_v9m_dma_delta_warn_end-msg_v9m_dma_delta_warn,d3
        jsr     print
v9m_dma_delta_done:
        lea     msg_v9m_dma_free_ok,a1
        move.l  #msg_v9m_dma_free_ok_end-msg_v9m_dma_free_ok,d3
        jsr     print
        moveq   #0,d0
        bra.s   v9m_dma_free_done

v9m_dma_gate_refuse:
        lea     msg_v9m_dma_gate_refuse,a1
        move.l  #msg_v9m_dma_gate_refuse_end-msg_v9m_dma_gate_refuse,d3
        jsr     print
        moveq   #1,d0
v9m_dma_free_done:
        movem.l (sp)+,d1-d7/a0-a2/a6
        rts

v9m_avail_fast:
        movem.l d1/a6,-(sp)
        move.l  #MEMF_FAST,d1
        move.l  a4,a6
        jsr     AvailMem(a6)
        movem.l (sp)+,d1/a6
        rts

        section data,data
msg_v9m_dma_begin:
        dc.b "[V10P] DMA-FREE-TEST nach echtem EOS: pruefe Ownership-Gate.",10
msg_v9m_dma_begin_end:
msg_v9m_dma_ptrs:
        dc.b "[V10P] output_alloc=0x"
msg_v9m_dma_ptrs_end:
msg_v9m_dma_bulkptr:
        dc.b "  bulk_alloc=0x"
msg_v9m_dma_bulkptr_end:
msg_v9m_dma_outflags:
        dc.b "[V10P] OUT active/pagelist/bulkqueued/deferred=0x"
msg_v9m_dma_outflags_end:
msg_v9m_dma_inflags:
        dc.b "[V10P] IN inuse/bulkpending/bulkdma/returned/sent=0x"
msg_v9m_dma_inflags_end:
msg_v9m_dma_eosflags:
        dc.b "[V10P] EOS eof/eosbulk/eosreturn/outeos=0x"
msg_v9m_dma_eosflags_end:
msg_v9m_slash:
        dc.b "/"
msg_v9m_slash_end:
msg_v9m_dma_gate_ok:
        dc.b "[V10P] DMA Ownership-Gate: OK. Keine beobachtete DMA/Bulk-Aktivitaet; alle Inputs zurueck; echtes EOS komplett.",10
msg_v9m_dma_gate_ok_end:
msg_v9m_dma_fast_before:
        dc.b "[V10P] Fast frei VOR Stream-DMA-Free: 0x"
msg_v9m_dma_fast_before_end:
msg_v9m_dma_free_output:
        dc.b "[V10P] FreeMem dynamischer output_alloc @ 0x"
msg_v9m_dma_free_output_end:
msg_v9m_dma_free_output_ok:
        dc.b "[V10P] output_alloc FreeMem: OK.",10
msg_v9m_dma_free_output_ok_end:
msg_v9m_dma_free_bulk:
        dc.b "[V10P] FreeMem bulk_alloc 0x0014B000 @ 0x"
msg_v9m_dma_free_bulk_end:
msg_v9m_dma_free_bulk_ok:
        dc.b "[V10P] bulk_alloc FreeMem: OK.",10
msg_v9m_dma_free_bulk_ok_end:
msg_v9m_dma_fast_after:
        dc.b "[V10P] Fast frei NACH Stream-DMA-Free: 0x"
msg_v9m_dma_fast_after_end:
msg_v9m_dma_delta:
        dc.b "[V10P] Rueckgewonnener Fast-RAM-Delta: 0x"
msg_v9m_dma_delta_end:
msg_v9m_dma_delta_ok:
        dc.b "  = dynamischer Output-Pool + 0x0014B000 Input-Pool: OK.",10
msg_v9m_dma_delta_ok_end:
msg_v9m_dma_delta_warn:
        dc.b "  WARNUNG: Delta passt nicht zur dynamischen Poolgroesse.",10
msg_v9m_dma_delta_warn_end:
msg_v9m_dma_free_ok:
        dc.b "[V10P] STREAM-DMA FREIGEGEBEN: dynamischer Output-Pool + 0x0014B000 Input-Pool. VCHIQ-Slotblock bleibt persistent.",10
msg_v9m_dma_free_ok_end:
msg_v9m_dma_gate_refuse:
        dc.b "[V10P] DMA Ownership-Gate NICHT sauber: output_alloc/bulk_alloc werden NICHT freigegeben. Danach bitte rebooten und Log schicken.",10
msg_v9m_dma_gate_refuse_end:
        even

; ====================================================================
; V10 - COMPLETE SECOND PLAYBACK ON FRESH LOCAL-1 SERVICE
; ====================================================================
        even
        section bss,bss
v9g_rgb_alloc_stage_abs: ds.l 1

; RX dispatcher for the legacy streaming engine. It lives after the LUTs,
; so all transfers back into the old core use absolute JMPs.
        section code,code
v9g_h19_dispatch:
        move.l  bulk_rx_msgid,d0
        jsr     v9g_rx_service_match
        tst.l   d0
        bne.s   v9g_h19_other
        move.l  bulk_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_BULK_TX_DONE,d0
        bne.s   v9g_h19_not_btx
        jmp     h19_input_bulk_done
v9g_h19_not_btx:
        cmp.l   #VCHIQ_MSG_BULK_RX_DONE,d0
        bne.s   v9g_h19_not_brx
        jmp     h19_output_bulk_done_msg
v9g_h19_not_brx:
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.s   v9g_h19_other
        jmp     h19_mmal_data
v9g_h19_other:
        jmp     h19_other_vchiq

; D0=VCHIQ msgid. Return D0=0 match, D0=1 other service.
; port_query_index is deliberately reused as shifted local bits while the
; streaming engine runs: 0 on first run, 0x1000 on V10 second run.
v9g_rx_service_match:
        movem.l d1-d2,-(sp)
        move.l  d0,d1
        and.l   #$00000fff,d1
        move.l  port_query_index,d2
        lsr.l   #8,d2
        lsr.l   #4,d2
        cmp.l   d2,d1
        bne.s   v9g_rx_service_no
        move.l  d0,d1
        lsr.l   #8,d1
        lsr.l   #4,d1
        and.l   #$00000fff,d1
        cmp.l   mmal_remote_port,d1
        bne.s   v9g_rx_service_no
        moveq   #0,d0
        bra.s   v9g_rx_service_done
v9g_rx_service_no:
        moveq   #1,d0
v9g_rx_service_done:
        movem.l (sp)+,d1-d2
        rts

v9g_second_playback:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  #1,v9g_rgb_alloc_stage_abs

        ; V9F returned with shared VCHIQ RAM DMA-owned. Legacy stream engine
        ; expects CPU ownership before its first h26a_reserve_tx.
        jsr     dma_post_all

        ; During streaming port_query_index is no longer a query index; it is
        ; the already-shifted host local-service field used by size-neutral
        ; patches in the old worker/BULK constructors.
        move.l  #$00001000,port_query_index

        ; VPv36: local-1 audio_render CREATE + CONTROL0 + INPUT0 GET were already
        ; completed in v9f_second_configure; playback itself still sends no PCM.
        lea     msg_vpv21p_second_audio_skipped,a1
        move.l  #msg_vpv21p_second_audio_skipped_end-msg_vpv21p_second_audio_skipped,d3
        jsr     vpv21n_trace

        lea     msg_v9g_play_begin,a1
        move.l  #msg_v9g_play_begin_end-msg_v9g_play_begin,d3
        jsr     print

        ; HDMI_v41L second run: no legacy RGB/HAM6 buffers are allocated.
        clr.l   v9g_rgb_alloc_stage_abs
        clr.l   t30_frames_ptr
        clr.l   t30_chip_ptr
        clr.l   v9i_chip_alloc_base
        clr.l   t33_fast_ptr
        clr.l   t56_shadow_ptr
        lea     msg_hdmi_v40o_no_rgb_buffers,a1
        move.l  #msg_hdmi_v40o_no_rgb_buffers_end-msg_hdmi_v40o_no_rgb_buffers,d3
        jsr     print

        ; Same display/timing reset as normal first-start path. Source timing
        ; selector itself remains from v7_setup_timing executed before attach.
        clr.l   t31s_display_started
        clr.l   t31s_vblank_installed
        clr.l   t31s_vblank_counter
        clr.l   t31s_pending_ptr
        clr.l   t31s_switch_vblank
        clr.l   t31s_pending_valid
        clr.l   t31s_next_switch_vblank
        clr.l   t8a_isr_late_promote
        clr.l   v7_sched_accum
        clr.l   t31s_missed_deadlines
        clr.l   t31x_slack1
        clr.l   t31x_slack2
        clr.l   t31x_slack3plus
        clr.l   t31x_at_target
        clr.l   t31x_past_target
        move.l  #-1,t31x_miss1_frame
        clr.l   t31x_miss1_target
        clr.l   t31x_miss1_current
        clr.l   t31x_miss1_delta
        move.l  #-1,t31x_miss2_frame
        clr.l   t31x_miss2_target
        clr.l   t31x_miss2_current
        clr.l   t31x_miss2_delta
        clr.l   t31x_max_past_delta
        clr.l   t31u_last_stream_end_vblank
        clr.l   t31u_gap_total
        clr.l   t31u_gap_max
        clr.l   t31u_gap_nonzero
        clr.l   t31u_buffer_total
        clr.l   t31u_buffer_max
        clr.l   t31u_buffer_nonzero
        clr.l   t31u_convert_total
        clr.l   t31u_convert_max
        clr.l   t31u_convert_nonzero
        clr.l   t31w_copy_total
        clr.l   t31w_copy_max
        clr.l   t31w_copy_nonzero
        clr.l   t56_dirty_long_total
        clr.l   t56_dirty_long_max
        clr.l   t57_early_release_total
        clr.l   t61_deferred_total
        clr.l   t61_slot0_frames
        clr.l   t61_slot1_frames
        clr.l   t63_preroll_ptr
        clr.l   t63_preroll_frames
        clr.l   t65_same_vblank_total
        clr.l   t65_same_vblank_late
        clr.l   t65_catchup_debt
        clr.l   t65_debt_added_total
        clr.l   t65_catchup_total
        clr.l   t65_debt_max
        clr.l   t66_current_slack
        clr.l   t66_catchup_deferred
        clr.l   t31u_post_total
        clr.l   t31u_post_max
        clr.l   t31u_post_nonzero
        clr.l   t31u_stage_start_vblank
        clr.l   t31u_run_start_vblank
        clr.l   t30_active_ptr
        clr.l   t30_display_ptr

        ; HDMI_v41L: no HAM6 scaler in the HDMI-only second run.

        lea     msg_v9g_play_stream,a1
        move.l  #msg_v9g_play_stream_end-msg_v9g_play_stream,d3
        jsr     print

        ; V40M: an internal fullscreen restart must begin with a completely fresh
        ; bounded-reader/demux state.  The previous run already closed its stream,
        ; but reset once more here before the fresh decoder receives any AU.
        jsr     v10b_stream_reset
        jsr     h264_output_test
        move.l  d0,d7

        ; Second path bypasses close_prog, so close the raw-H264 DOS handle here.
        move.l  t23_file_handle,d0
        beq.s   v9g_file_closed
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
v9g_file_closed:
        jsr     v10b_stream_reset
        tst.l   d7
        bne.s   v9g_play_stream_fail
        move.l  v15_stop_requested,d0
        tst.l   d0
        beq.s   v15_second_natural_success
        lea     msg_v15_second_stop_ok,a1
        move.l  #msg_v15_second_stop_ok_end-msg_v15_second_stop_ok,d3
        jsr     print
        bra.s   v15_second_success_done
v15_second_natural_success:
        move.l  #1,mkvr7_natural_eos
        lea     msg_v9g_play_ok,a1
        move.l  #msg_v9g_play_ok_end-msg_v9g_play_ok,d3
        jsr     print
v15_second_success_done:
        moveq   #0,d7
        bra.s   v9g_play_finish

v9g_play_stream_fail:
        lea     msg_v9g_play_stream_fail,a1
        move.l  #msg_v9g_play_stream_fail_end-msg_v9g_play_stream_fail,d3
        jsr     print
        moveq   #1,d7
        bra.s   v9g_play_finish

v9g_play_scale_fail:
        lea     msg_v9g_play_scale_fail,a1
        move.l  #msg_v9g_play_scale_fail_end-msg_v9g_play_scale_fail,d3
        jsr     print
        moveq   #1,d7
        bra.s   v9g_play_finish

v9g_play_alloc_fail:
        lea     msg_v9g_play_alloc_fail,a1
        move.l  #msg_v9g_play_alloc_fail_end-msg_v9g_play_alloc_fail,d3
        jsr     print
        move.l  v9g_rgb_alloc_stage_abs,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d7

v9g_play_finish:
        ; h264_output_test returns with shared VCHIQ RAM CPU-owned.  Enter the
        ; common V10P cleanup with the same DMA-owned contract as close_prog.
        jsr     dma_pre_all
        jsr     v9_cleanup_all
        jsr     vpv41_audio_decoder_cleanup
        jsr     vpv21_free_pcm
        ; This path bypasses close_prog; commit/clear the movie bookmark here.
        jsr     mkvr7_commit_resume
v9g_free_shadow_done:
v9g_free_scratch_done:
v9g_free_chip_done:
        move.l  d7,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

        section data,data
msg_v9g_play_begin:
        dc.b "[HDMI_v41L] Zweiter Decoder aktiv: reiner HDMI-Streaminglauf ohne HAM6-Puffer.",10
msg_v9g_play_begin_end:
msg_v9g_play_stream:
        dc.b "[HDMI_v41L] Zweiter H264-Stream startet auf local port 1; Decoder -> HDMI-Renderer.",10
msg_v9g_play_stream_end:
msg_v9g_play_ok:
        dc.b "[HDMI_v41L] ZWEITE H264/HDMI-WIEDERGABE BIS EOS: OK.",10
        dc.b "[HDMI_v41L] Renderer-freier ISP/P96-Lauf beendet; Cleanup folgt.",10
msg_v9g_play_ok_end:
msg_v15_second_stop_ok:
        dc.b "[HDMI_v41L] ZWEITER LAUF PER CTRL-C GESTOPPT: Decoder-EOS erreicht; Cleanup wird normal fortgesetzt.",10
msg_v15_second_stop_ok_end:
msg_v9g_play_stream_fail:
        dc.b "[HDMI_v41L] FEHLER: zweiter Streaming-/EOS-/HDMI-Pfad fehlgeschlagen. Danach bitte rebooten.",10
msg_v9g_play_stream_fail_end:
msg_v9g_play_scale_fail:
        dc.b "[HDMI_v41L] FEHLER: unerwarteter Legacy-Scale-Pfad erreicht.",10
msg_v9g_play_scale_fail_end:
msg_v9g_play_alloc_fail:
        dc.b "[HDMI_v41L] FEHLER: unerwarteter Legacy-RGB-Allokationspfad, Stufe 0x"
msg_v9g_play_alloc_fail_end:
        even


; ====================================================================
; V10 - FIRST MATROSKA / MKV DEMUX PROBE
; ====================================================================
; This path is intentionally isolated from MMAL playback. It reads the first
; 2 MiB of an .mkv file, walks EBML/Matroska elements, prints tracks/codecs,
; TimecodeScale, H264 AVCDecoderConfigurationRecord (avcC) information and the
; first video block timestamp seen in the probe window.
;
; Supported in this diagnostic stage:
;   - EBML IDs up to 4 bytes
;   - EBML sizes up to 32 bit plus normal "unknown size" master elements
;   - TrackEntry / CodecID / CodecPrivate / DefaultDuration / Video dimensions
;   - Cluster Timecode + SimpleBlock/Block first PTS for the selected AVC track
;   - avcC first SPS/PPS extraction into Annex-B form for the next V10 stage
;
; No MKV video is sent to VideoCore in V10 yet.

        section code,code

; D0=1 if t23_file_name ends in .mkv (case-insensitive), else D0=0.
v10_is_mkv:
        movem.l d1-d3/a0-a1,-(sp)
        lea     t23_file_name,a0
        move.l  a0,a1
        clr.l   d1
v10_ext_len:
        tst.b   (a1)
        beq.s   v10_ext_len_done
        addq.l  #1,a1
        addq.l  #1,d1
        bra.s   v10_ext_len
v10_ext_len_done:
        cmpi.l  #4,d1
        bcs.s   v10_ext_no
        subq.l  #4,a1
        cmpi.b  #$2E,(a1)               ; '.'
        bne.s   v10_ext_no
        moveq   #0,d2
        move.b  1(a1),d2
        ori.b   #$20,d2
        cmpi.b  #$6D,d2                 ; m
        bne.s   v10_ext_no
        moveq   #0,d2
        move.b  2(a1),d2
        ori.b   #$20,d2
        cmpi.b  #$6B,d2                 ; k
        bne.s   v10_ext_no
        moveq   #0,d2
        move.b  3(a1),d2
        ori.b   #$20,d2
        cmpi.b  #$76,d2                 ; v
        bne.s   v10_ext_no
        moveq   #1,d0
        bra.s   v10_ext_done
v10_ext_no:
        moveq   #0,d0
v10_ext_done:
        movem.l (sp)+,d1-d3/a0-a1
        rts

; A0=current, A1=end. Returns D0=ID, D1=ID-byte-count, D2=0 success/1 fail.
v10_ebml_read_id:
        moveq   #1,d2
        cmpa.l  a1,a0
        bcc.w   v10_id_done
        moveq   #0,d0
        move.b  (a0),d0
        btst    #7,d0
        bne.s   v10_id_len1
        btst    #6,d0
        bne.s   v10_id_len2
        btst    #5,d0
        bne.s   v10_id_len3
        btst    #4,d0
        bne.s   v10_id_len4
        bra.w   v10_id_done
v10_id_len1:
        moveq   #1,d1
        bra.s   v10_id_have_len
v10_id_len2:
        moveq   #2,d1
        bra.s   v10_id_have_len
v10_id_len3:
        moveq   #3,d1
        bra.s   v10_id_have_len
v10_id_len4:
        moveq   #4,d1
v10_id_have_len:
        move.l  a1,d3
        sub.l   a0,d3
        cmp.l   d1,d3
        bcs.w   v10_id_done
        moveq   #0,d0
        move.b  (a0),d0
        cmpi.l  #1,d1
        beq.s   v10_id_ok
        moveq   #0,d3
        move.b  1(a0),d3
        lsl.l   #8,d0
        or.l    d3,d0
        cmpi.l  #2,d1
        beq.s   v10_id_ok
        moveq   #0,d3
        move.b  2(a0),d3
        lsl.l   #8,d0
        or.l    d3,d0
        cmpi.l  #3,d1
        beq.s   v10_id_ok
        moveq   #0,d3
        move.b  3(a0),d3
        lsl.l   #8,d0
        or.l    d3,d0
v10_id_ok:
        moveq   #0,d2
v10_id_done:
        rts

; A0=size VINT, A1=end. Returns D0=size (FFFFFFFF=unknown), D1=VINT bytes,
; D2=0 success, 1 malformed/truncated, 2 finite size exceeds 32 bit.
v10_ebml_read_size:
        moveq   #1,d2
        cmpa.l  a1,a0
        bcc.w   v10_size_done
        moveq   #0,d3
        move.b  (a0),d3
        btst    #7,d3
        bne.s   v10_size_l1
        btst    #6,d3
        bne.s   v10_size_l2
        btst    #5,d3
        bne.s   v10_size_l3
        btst    #4,d3
        bne.s   v10_size_l4
        btst    #3,d3
        bne.s   v10_size_l5
        btst    #2,d3
        bne.s   v10_size_l6
        btst    #1,d3
        bne.s   v10_size_l7
        btst    #0,d3
        bne.s   v10_size_l8
        bra.w   v10_size_done
v10_size_l1:
        moveq   #1,d1
        moveq   #$7F,d4
        bra.s   v10_size_len_ready
v10_size_l2:
        moveq   #2,d1
        moveq   #$3F,d4
        bra.s   v10_size_len_ready
v10_size_l3:
        moveq   #3,d1
        moveq   #$1F,d4
        bra.s   v10_size_len_ready
v10_size_l4:
        moveq   #4,d1
        moveq   #$0F,d4
        bra.s   v10_size_len_ready
v10_size_l5:
        moveq   #5,d1
        moveq   #$07,d4
        bra.s   v10_size_len_ready
v10_size_l6:
        moveq   #6,d1
        moveq   #$03,d4
        bra.s   v10_size_len_ready
v10_size_l7:
        moveq   #7,d1
        moveq   #$01,d4
        bra.s   v10_size_len_ready
v10_size_l8:
        moveq   #8,d1
        moveq   #0,d4
v10_size_len_ready:
        move.l  a1,d5
        sub.l   a0,d5
        cmp.l   d1,d5
        bcs.w   v10_size_done

        ; Detect all-ones payload = EBML unknown size.
        move.l  d3,d5
        and.l   d4,d5
        cmp.l   d4,d5
        bne.s   v10_size_finite
        moveq   #1,d6
        moveq   #1,d7
v10_size_unknown_loop:
        cmp.l   d1,d7
        bcc.s   v10_size_unknown_yes
        moveq   #0,d5
        move.b  0(a0,d7.w),d5
        cmpi.b  #$FF,d5
        bne.s   v10_size_finite
        addq.l  #1,d7
        bra.s   v10_size_unknown_loop
v10_size_unknown_yes:
        move.l  #$FFFFFFFF,d0
        moveq   #0,d2
        bra.w   v10_size_done

v10_size_finite:
        ; 1..4-byte sizes fit directly in D0.
        cmpi.l  #4,d1
        bhi.s   v10_size_long
        move.l  d3,d0
        and.l   d4,d0
        moveq   #1,d7
v10_size_short_loop:
        cmp.l   d1,d7
        bcc.s   v10_size_ok
        lsl.l   #8,d0
        moveq   #0,d5
        move.b  0(a0,d7.w),d5
        or.l    d5,d0
        addq.l  #1,d7
        bra.s   v10_size_short_loop

v10_size_long:
        ; For 5..8 bytes accept only values whose leading payload bytes are 0.
        move.l  d1,d6
        subq.l  #4,d6                   ; number of leading payload bytes
        move.l  d3,d5
        and.l   d4,d5
        tst.l   d5
        bne.s   v10_size_too_big
        moveq   #1,d7
        subq.l  #1,d6
        beq.s   v10_size_last4
v10_size_high_zero_loop:
        moveq   #0,d5
        move.b  0(a0,d7.w),d5
        tst.b   d5
        bne.s   v10_size_too_big
        addq.l  #1,d7
        subq.l  #1,d6
        bne.s   v10_size_high_zero_loop
v10_size_last4:
        move.l  d1,d7
        subq.l  #4,d7
        moveq   #0,d0
        moveq   #0,d5
        move.b  0(a0,d7.w),d5
        or.l    d5,d0
        addq.l  #1,d7
        lsl.l   #8,d0
        moveq   #0,d5
        move.b  0(a0,d7.w),d5
        or.l    d5,d0
        addq.l  #1,d7
        lsl.l   #8,d0
        moveq   #0,d5
        move.b  0(a0,d7.w),d5
        or.l    d5,d0
        addq.l  #1,d7
        lsl.l   #8,d0
        moveq   #0,d5
        move.b  0(a0,d7.w),d5
        or.l    d5,d0
        bra.s   v10_size_ok
v10_size_too_big:
        moveq   #2,d2
        bra.s   v10_size_done
v10_size_ok:
        moveq   #0,d2
v10_size_done:
        rts

; A0=data, D0=byte length 1..4. Returns D0=big-endian unsigned value,
; D1=0 success/1 invalid.
v10_read_uint:
        movem.l d2-d4/a0,-(sp)
        move.l  d0,d4
        moveq   #1,d1
        tst.l   d4
        beq.s   v10_uint_done
        cmpi.l  #4,d4
        bhi.s   v10_uint_done
        moveq   #0,d0
        moveq   #0,d2
v10_uint_loop:
        lsl.l   #8,d0
        moveq   #0,d3
        move.b  (a0)+,d3
        or.l    d3,d0
        addq.l  #1,d2
        cmp.l   d4,d2
        bcs.s   v10_uint_loop
        moveq   #0,d1
v10_uint_done:
        movem.l (sp)+,d2-d4/a0
        rts

; Unsigned 32/32 divide for diagnostics. Input D0=dividend, D1=divisor.
; Output D0=quotient, D1=remainder. Divisor 0 returns quotient 0.
v10_udiv32:
        movem.l d2-d5,-(sp)
        move.l  d0,d2
        move.l  d1,d3
        clr.l   d0
        clr.l   d4
        tst.l   d3
        beq.s   v10_udiv_done
        moveq   #31,d5
v10_udiv_loop:
        add.l   d4,d4
        btst    d5,d2
        beq.s   v10_udiv_no_bit
        addq.l  #1,d4
v10_udiv_no_bit:
        cmp.l   d3,d4
        bcs.s   v10_udiv_less
        sub.l   d3,d4
        bset    d5,d0
v10_udiv_less:
        dbra    d5,v10_udiv_loop
v10_udiv_done:
        move.l  d4,d1
        movem.l (sp)+,d2-d5
        rts

; Compare current CodecID with V_MPEG4/ISO/AVC. D0=1 match else 0.
v10_codec_is_avc:
        movem.l d1-d3/a0-a1,-(sp)
        move.l  v10_cur_codec_len,d1
        cmpi.l  #15,d1
        bne.s   v10_codec_no
        move.l  v10_cur_codec_ptr,a0
        lea     v10_codec_avc,a1
        moveq   #14,d3
v10_codec_cmp_loop:
        move.b  (a0)+,d1
        cmp.b   (a1)+,d1
        bne.s   v10_codec_no
        dbra    d3,v10_codec_cmp_loop
        moveq   #1,d0
        bra.s   v10_codec_done
v10_codec_no:
        moveq   #0,d0
v10_codec_done:
        movem.l (sp)+,d1-d3/a0-a1
        rts

v10_track_begin:
        clr.l   v10_cur_track_num
        clr.l   v10_cur_track_type
        clr.l   v10_cur_codec_ptr
        clr.l   v10_cur_codec_len
        clr.l   v10_cur_codecpriv_ptr
        clr.l   v10_cur_codecpriv_len
        clr.l   v10_cur_default_dur
        clr.l   v10_cur_width
        clr.l   v10_cur_height
        clr.l   v10_cur_channels
        move.l  #1,v10_in_track
        rts

v10_track_finalize:
        movem.l d0-d7/a0-a3,-(sp)
        clr.l   v10_in_track
        addq.l  #1,v10_track_count

        lea     msg_v10_track,a1
        move.l  #msg_v10_track_end-msg_v10_track,d3
        jsr     print
        move.l  v10_cur_track_num,d0
        jsr     print_hex32
        lea     msg_v10_type,a1
        move.l  #msg_v10_type_end-msg_v10_type,d3
        jsr     print
        move.l  v10_cur_track_type,d0
        jsr     print_hex32
        lea     msg_v10_codec,a1
        move.l  #msg_v10_codec_end-msg_v10_codec,d3
        jsr     print
        move.l  v10_cur_codec_ptr,d0
        beq.s   v10_track_no_codec_text
        move.l  d0,a1
        move.l  v10_cur_codec_len,d3
        cmpi.l  #63,d3
        bls.s   v10_track_codec_len_ok
        moveq   #63,d3
v10_track_codec_len_ok:
        jsr     print
        bra.s   v10_track_codec_printed
v10_track_no_codec_text:
        lea     msg_v10_none,a1
        move.l  #msg_v10_none_end-msg_v10_none,d3
        jsr     print
v10_track_codec_printed:
        jsr     newline

        cmpi.l  #1,v10_cur_track_type
        bne.w   v10_track_not_video
        lea     msg_v10_video,a1
        move.l  #msg_v10_video_end-msg_v10_video,d3
        jsr     print
        move.l  v10_cur_width,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v10_cur_height,d0
        jsr     print_hex32
        lea     msg_v10_defdur,a1
        move.l  #msg_v10_defdur_end-msg_v10_defdur,d3
        jsr     print
        move.l  v10_cur_default_dur,d0
        jsr     print_hex32
        jsr     newline

        ; Select the first AVC video track.
        tst.l   v10_h264_found
        bne.w   v10_track_done
        jsr     v10_codec_is_avc
        tst.l   d0
        beq.w   v10_track_done
        move.l  #1,v10_h264_found
        move.l  v10_cur_track_num,d0
        move.l  d0,v10_video_track_num
        move.l  v10_cur_default_dur,d0
        move.l  d0,v10_video_default_dur
        move.l  v10_cur_width,d0
        move.l  d0,v10_video_width
        move.l  v10_cur_height,d0
        move.l  d0,v10_video_height
        move.l  v10_cur_codecpriv_ptr,d0
        move.l  d0,v10_video_codecpriv_ptr
        move.l  v10_cur_codecpriv_len,d0
        move.l  d0,v10_video_codecpriv_len
        lea     msg_v10_avc_selected,a1
        move.l  #msg_v10_avc_selected_end-msg_v10_avc_selected,d3
        jsr     print
        jsr     v10_parse_avcc
        bra.w   v10_track_done

v10_track_not_video:
        cmpi.l  #2,v10_cur_track_type
        bne.w   v10_track_done
        lea     msg_v10_audio,a1
        move.l  #msg_v10_audio_end-msg_v10_audio,d3
        jsr     print
        move.l  v10_cur_channels,d0
        jsr     print_hex32
        jsr     newline

        ; VPv20: remember the first Matroska A_AAC track and copy its
        ; CodecPrivate (AudioSpecificConfig) before the 2-MiB probe buffer
        ; is released.  Real AAC blocks are later wrapped as ADTS.
        tst.l   v19_aac_found
        bne.w   v10_track_done
        jsr     v19_codec_is_aac
        tst.l   d0
        beq.w   v10_track_done
        move.l  v10_cur_codecpriv_len,d0
        cmpi.l  #2,d0
        bcs.w   v10_track_done
        move.l  #16,d1
        cmp.l   d1,d0
        bls.s   v19_audio_priv_len_ok
        move.l  d1,d0
v19_audio_priv_len_ok:
        move.l  d0,v19_audio_codecpriv_len
        move.l  v10_cur_codecpriv_ptr,a0
        lea     v19_audio_codecpriv,a1
        move.l  d0,d1
v19_audio_priv_copy:
        move.b  (a0)+,(a1)+
        subq.l  #1,d1
        bne.s   v19_audio_priv_copy
        move.l  v10_cur_track_num,d0
        move.l  d0,v19_audio_track_num
        move.l  v10_cur_channels,d0
        move.l  d0,v19_audio_probe_channels
        move.l  #1,v19_aac_found
        lea     msg_v19_aac_selected,a1
        move.l  #msg_v19_aac_selected_end-msg_v19_aac_selected,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  v19_audio_track_num,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
v10_track_done:
        movem.l (sp)+,d0-d7/a0-a3
        rts

; Parse AVCDecoderConfigurationRecord (avcC) from selected Matroska CodecPrivate.
; Copies first SPS/PPS to h264_file_extradata as 00 00 00 01 NALs so the next
; demux/playback stage can reuse the established MMAL extradata format.
v10_parse_avcc:
        movem.l d0-d7/a0-a3,-(sp)
        move.l  v10_video_codecpriv_ptr,a0
        move.l  v10_video_codecpriv_len,d7
        cmpi.l  #7,d7
        bcs.w   v10_avcc_fail
        cmpi.b  #1,(a0)
        bne.w   v10_avcc_fail

        lea     msg_v10_avcc_profile,a1
        move.l  #msg_v10_avcc_profile_end-msg_v10_avcc_profile,d3
        jsr     print
        moveq   #0,d0
        move.b  1(a0),d0
        jsr     print_hex32
        lea     msg_v10_avcc_level,a1
        move.l  #msg_v10_avcc_level_end-msg_v10_avcc_level,d3
        jsr     print
        moveq   #0,d0
        move.b  3(a0),d0
        jsr     print_hex32
        jsr     newline

        moveq   #0,d0
        move.b  4(a0),d0
        and.l   #3,d0
        addq.l  #1,d0
        move.l  d0,v10_nal_length_size

        moveq   #0,d0
        move.b  5(a0),d0
        and.l   #$1F,d0
        beq.w   v10_avcc_fail
        move.l  d0,v10_avcc_sps_count

        lea     6(a0),a2
        move.l  a0,a3
        add.l   d7,a3
        move.l  a3,d0
        sub.l   a2,d0
        cmpi.l  #2,d0
        bcs.w   v10_avcc_fail
        moveq   #0,d5
        move.b  (a2)+,d5
        lsl.l   #8,d5
        moveq   #0,d6
        move.b  (a2)+,d6
        or.l    d6,d5                    ; SPS payload length
        tst.l   d5
        beq.w   v10_avcc_fail
        move.l  a3,d0
        sub.l   a2,d0
        cmp.l   d5,d0
        bcs.w   v10_avcc_fail

        ; Need 4-byte Annex-B prefix + SPS + at least PPS header/length/prefix.
        move.l  d5,d0
        add.l   #10,d0
        cmpi.l  #H264_CODEC_CONFIG_MAX,d0
        bhi.w   v10_avcc_too_large

        lea     h264_file_extradata,a1
        move.l  a1,h264_sps_ptr
        move.l  #$00000001,(a1)+
        move.l  d5,d0
        addq.l  #4,d0
        move.l  d0,h264_sps_len
        move.l  d5,d4
v10_avcc_copy_sps:
        move.b  (a2)+,(a1)+
        subq.l  #1,d4
        bne.s   v10_avcc_copy_sps

        ; Skip any additional SPS records; V10 only exports the first one.
        move.l  v10_avcc_sps_count,d4
        subq.l  #1,d4
        beq.s   v10_avcc_after_extra_sps
v10_avcc_skip_extra_sps:
        move.l  a3,d0
        sub.l   a2,d0
        cmpi.l  #2,d0
        bcs.w   v10_avcc_fail
        moveq   #0,d6
        move.b  (a2)+,d6
        lsl.l   #8,d6
        moveq   #0,d0
        move.b  (a2)+,d0
        or.l    d0,d6
        move.l  a3,d0
        sub.l   a2,d0
        cmp.l   d6,d0
        bcs.w   v10_avcc_fail
        adda.l  d6,a2
        subq.l  #1,d4
        bne.s   v10_avcc_skip_extra_sps
v10_avcc_after_extra_sps:

        cmpa.l  a3,a2
        bcc.w   v10_avcc_fail
        moveq   #0,d0
        move.b  (a2)+,d0                 ; numOfPPS
        tst.l   d0
        beq.w   v10_avcc_fail
        move.l  a3,d0
        sub.l   a2,d0
        cmpi.l  #2,d0
        bcs.w   v10_avcc_fail
        moveq   #0,d6
        move.b  (a2)+,d6
        lsl.l   #8,d6
        moveq   #0,d0
        move.b  (a2)+,d0
        or.l    d0,d6                    ; PPS payload length
        tst.l   d6
        beq.w   v10_avcc_fail
        move.l  a3,d0
        sub.l   a2,d0
        cmp.l   d6,d0
        bcs.w   v10_avcc_fail
        move.l  d5,d0
        add.l   d6,d0
        addq.l  #8,d0
        cmpi.l  #H264_CODEC_CONFIG_MAX,d0
        bhi.w   v10_avcc_too_large
        move.l  a1,h264_pps_ptr
        move.l  #$00000001,(a1)+
        move.l  d6,d0
        addq.l  #4,d0
        move.l  d0,h264_pps_len
        move.l  d6,d4
v10_avcc_copy_pps:
        move.b  (a2)+,(a1)+
        subq.l  #1,d4
        bne.s   v10_avcc_copy_pps

        move.l  h264_sps_len,d0
        add.l   h264_pps_len,d0
        move.l  d0,h264_codec_config_len
        move.l  #1,v10_avcc_ok

        lea     msg_v10_avcc_ok,a1
        move.l  #msg_v10_avcc_ok_end-msg_v10_avcc_ok,d3
        jsr     print
        move.l  v10_nal_length_size,d0
        jsr     print_hex32
        lea     msg_v10_avcc_sps,a1
        move.l  #msg_v10_avcc_sps_end-msg_v10_avcc_sps,d3
        jsr     print
        move.l  h264_sps_len,d0
        subq.l  #4,d0
        jsr     print_hex32
        lea     msg_v10_avcc_pps,a1
        move.l  #msg_v10_avcc_pps_end-msg_v10_avcc_pps,d3
        jsr     print
        move.l  h264_pps_len,d0
        subq.l  #4,d0
        jsr     print_hex32
        jsr     newline
        bra.s   v10_avcc_done

v10_avcc_too_large:
        lea     msg_v10_avcc_large,a1
        move.l  #msg_v10_avcc_large_end-msg_v10_avcc_large,d3
        jsr     print
        bra.s   v10_avcc_done
v10_avcc_fail:
        lea     msg_v10_avcc_fail,a1
        move.l  #msg_v10_avcc_fail_end-msg_v10_avcc_fail,d3
        jsr     print
v10_avcc_done:
        movem.l (sp)+,d0-d7/a0-a3
        rts

; A0=block payload, D0=payload bytes. Stores first timestamp for selected AVC track.
v10_parse_block:
        movem.l d0-d7/a0-a3,-(sp)
        tst.l   v10_first_pts_found
        bne.w   v10_block_done
        tst.l   v10_video_track_num
        beq.w   v10_block_done
        cmpi.l  #4,d0
        bcs.w   v10_block_done
        move.l  a0,a2
        move.l  a0,a1
        add.l   d0,a1
        move.l  a2,a0
        jsr     v10_ebml_read_size       ; TrackNumber uses same marker-stripped VINT value
        tst.l   d2
        bne.w   v10_block_done
        move.l  d0,d5
        cmp.l   v10_video_track_num,d5
        bne.w   v10_block_done
        adda.l  d1,a2
        move.l  a1,d0
        sub.l   a2,d0
        cmpi.l  #3,d0
        bcs.w   v10_block_done
        moveq   #0,d6
        move.b  (a2)+,d6
        lsl.w   #8,d6
        moveq   #0,d7
        move.b  (a2)+,d7
        or.w    d7,d6
        ext.l   d6                       ; signed relative cluster timecode
        move.l  d6,v10_first_rel_tc
        add.l   v10_cluster_timecode,d6
        move.l  d6,v10_first_pts_ticks
        move.l  #1,v10_first_pts_found
v10_block_done:
        movem.l (sp)+,d0-d7/a0-a3
        rts

; Recursive bounded EBML walker. A0=start, A1=end.
v10_scan_elements:
        movem.l d0-d7/a0-a6,-(sp)
        move.l  a1,a6                    ; stable scan-end; A1 is reused by print
v10_scan_loop:
        cmpa.l  a6,a0
        bcc.w   v10_scan_done
        move.l  a6,d0
        sub.l   a0,d0
        cmpi.l  #2,d0
        bcs.w   v10_scan_done

        move.l  a6,a1
        jsr     v10_ebml_read_id
        tst.l   d2
        bne.w   v10_scan_done
        ; V10P FIX: v10_ebml_read_size uses D3-D7 internally.  Preserve the
        ; element ID across that call; otherwise D5 no longer contains the ID
        ; and masters such as Tracks/TrackEntry are never recognized.
        move.l  d0,-(sp)                 ; preserve element ID
        adda.l  d1,a0
        move.l  a6,a1
        jsr     v10_ebml_read_size
        move.l  (sp)+,d5                 ; restore element ID
        tst.l   d2
        bne.w   v10_scan_done
        move.l  d0,d6                    ; payload size / FFFFFFFF unknown
        adda.l  d1,a0
        move.l  a0,a2                    ; payload start
        move.l  a6,a3                    ; default capped end
        cmpi.l  #$FFFFFFFF,d6
        beq.s   v10_scan_end_ready
        move.l  a2,d0
        add.l   d6,d0
        cmp.l   a6,d0
        bhi.s   v10_scan_end_ready
        move.l  d0,a3
v10_scan_end_ready:

        ; Master elements that contain other EBML elements.
        cmpi.l  #$1A45DFA3,d5            ; EBML
        beq.w   v10_scan_master
        cmpi.l  #$18538067,d5            ; Segment
        beq.w   v10_scan_master
        cmpi.l  #$114D9B74,d5            ; SeekHead
        beq.w   v10_scan_master
        cmpi.l  #$1549A966,d5            ; Info
        beq.w   v10_scan_master
        cmpi.l  #$1654AE6B,d5            ; Tracks
        beq.w   v10_scan_master
        cmpi.l  #$000000E0,d5            ; Video
        beq.w   v10_scan_master
        cmpi.l  #$000000E1,d5            ; Audio
        beq.w   v10_scan_master
        cmpi.l  #$000000A0,d5            ; BlockGroup
        beq.w   v10_scan_master
        cmpi.l  #$1F43B675,d5            ; Cluster
        beq.w   v10_scan_cluster
        cmpi.l  #$000000AE,d5            ; TrackEntry
        beq.w   v10_scan_trackentry

        ; DocType
        cmpi.l  #$00004282,d5
        bne.s   v10_scan_not_doctype
        lea     msg_v10_doctype,a1
        move.l  #msg_v10_doctype_end-msg_v10_doctype,d3
        jsr     print
        move.l  a2,a1
        move.l  a3,d3
        sub.l   a2,d3
        cmpi.l  #31,d3
        bls.s   v10_doctype_len_ok
        moveq   #31,d3
v10_doctype_len_ok:
        jsr     print
        jsr     newline
        bra.w   v10_scan_next
v10_scan_not_doctype:

        ; Info.TimecodeScale (default already 1,000,000 ns/tick).
        cmpi.l  #$002AD7B1,d5
        bne.s   v10_scan_not_scale
        move.l  a3,d0
        sub.l   a2,d0
        move.l  a2,a0
        jsr     v10_read_uint
        tst.l   d1
        bne.w   v10_scan_next
        move.l  d0,v10_timecode_scale
        bra.w   v10_scan_next
v10_scan_not_scale:

        ; Track fields.
        tst.l   v10_in_track
        beq.w   v10_scan_cluster_fields
        cmpi.l  #$000000D7,d5            ; TrackNumber
        bne.s   v10_track_field_type
        move.l  a3,d0
        sub.l   a2,d0
        move.l  a2,a0
        jsr     v10_read_uint
        tst.l   d1
        bne.w   v10_scan_next
        move.l  d0,v10_cur_track_num
        bra.w   v10_scan_next
v10_track_field_type:
        cmpi.l  #$00000083,d5            ; TrackType
        bne.s   v10_track_field_codec
        move.l  a3,d0
        sub.l   a2,d0
        move.l  a2,a0
        jsr     v10_read_uint
        tst.l   d1
        bne.w   v10_scan_next
        move.l  d0,v10_cur_track_type
        bra.w   v10_scan_next
v10_track_field_codec:
        cmpi.l  #$00000086,d5            ; CodecID
        bne.s   v10_track_field_private
        move.l  a2,v10_cur_codec_ptr
        move.l  a3,d0
        sub.l   a2,d0
        move.l  d0,v10_cur_codec_len
        bra.w   v10_scan_next
v10_track_field_private:
        cmpi.l  #$000063A2,d5            ; CodecPrivate
        bne.s   v10_track_field_duration
        move.l  a2,v10_cur_codecpriv_ptr
        move.l  a3,d0
        sub.l   a2,d0
        move.l  d0,v10_cur_codecpriv_len
        bra.w   v10_scan_next
v10_track_field_duration:
        cmpi.l  #$0023E383,d5            ; DefaultDuration
        bne.s   v10_track_field_width
        move.l  a3,d0
        sub.l   a2,d0
        move.l  a2,a0
        jsr     v10_read_uint
        tst.l   d1
        bne.w   v10_scan_next
        move.l  d0,v10_cur_default_dur
        bra.w   v10_scan_next
v10_track_field_width:
        cmpi.l  #$000000B0,d5            ; PixelWidth
        bne.s   v10_track_field_height
        move.l  a3,d0
        sub.l   a2,d0
        move.l  a2,a0
        jsr     v10_read_uint
        tst.l   d1
        bne.w   v10_scan_next
        move.l  d0,v10_cur_width
        bra.w   v10_scan_next
v10_track_field_height:
        cmpi.l  #$000000BA,d5            ; PixelHeight
        bne.s   v10_track_field_channels
        move.l  a3,d0
        sub.l   a2,d0
        move.l  a2,a0
        jsr     v10_read_uint
        tst.l   d1
        bne.w   v10_scan_next
        move.l  d0,v10_cur_height
        bra.w   v10_scan_next
v10_track_field_channels:
        cmpi.l  #$0000009F,d5            ; Channels
        bne.w   v10_scan_cluster_fields
        move.l  a3,d0
        sub.l   a2,d0
        move.l  a2,a0
        jsr     v10_read_uint
        tst.l   d1
        bne.w   v10_scan_next
        move.l  d0,v10_cur_channels
        bra.w   v10_scan_next

v10_scan_cluster_fields:
        cmpi.l  #$000000E7,d5            ; Cluster.Timecode
        bne.s   v10_scan_block_field
        move.l  a3,d0
        sub.l   a2,d0
        move.l  a2,a0
        jsr     v10_read_uint
        tst.l   d1
        bne.w   v10_scan_next
        move.l  d0,v10_cluster_timecode
        bra.w   v10_scan_next
v10_scan_block_field:
        cmpi.l  #$000000A3,d5            ; SimpleBlock
        beq.s   v10_scan_parse_block
        cmpi.l  #$000000A1,d5            ; Block inside BlockGroup
        bne.w   v10_scan_next
v10_scan_parse_block:
        move.l  a3,d0
        sub.l   a2,d0
        move.l  a2,a0
        jsr     v10_parse_block
        bra.w   v10_scan_next

v10_scan_trackentry:
        jsr     v10_track_begin
        move.l  a2,a0
        move.l  a3,a1
        jsr     v10_scan_elements
        jsr     v10_track_finalize
        bra.s   v10_scan_next

v10_scan_cluster:
        clr.l   v10_cluster_timecode
        move.l  a2,a0
        move.l  a3,a1
        jsr     v10_scan_elements
        bra.s   v10_scan_next

v10_scan_master:
        move.l  a2,a0
        move.l  a3,a1
        jsr     v10_scan_elements
v10_scan_next:
        move.l  a3,a0
        bra.w   v10_scan_loop
v10_scan_done:
        movem.l (sp)+,d0-d7/a0-a6
        rts

; VPv21T sparse hard-reset breadcrumb. A1=text, D3=len.
; Each call performs the already-proven logger transaction:
; screen -> Open/append -> Write -> Flush -> Close, then disables logging again.
vpv21n_trace:
        ; VPv120: sparse breadcrumbs are normal stdout too; AmigaDOS '>'
        ; captures them together with the rest of the console diagnostics.
        jsr     print
        rts

v10_mkv_probe:
        movem.l d0-d7/a0-a6,-(sp)
        clr.l   v10_mkv_buf_ptr
        clr.l   v10_mkv_handle
        clr.l   v10_mkv_read
        clr.l   v10_track_count
        clr.l   v19_aac_found
        clr.l   v19_audio_track_num
        clr.l   v19_audio_codecpriv_len
        clr.l   v19_audio_probe_channels
        clr.l   v19_audio_lacing_seen
        clr.l   v10_h264_found
        clr.l   v10_video_track_num
        clr.l   v10_video_codecpriv_ptr
        clr.l   v10_video_codecpriv_len
        clr.l   v10_video_default_dur
        clr.l   v10_video_width
        clr.l   v10_video_height
        clr.l   v10_nal_length_size
        clr.l   v10_avcc_ok
        clr.l   v10_first_pts_found
        clr.l   v10_first_pts_ticks
        clr.l   v10_first_rel_tc
        clr.l   v10_cluster_timecode
        clr.l   v10_in_track
        move.l  #1000000,v10_timecode_scale  ; Matroska default 1 ms = 1,000,000 ns

        lea     msg_v10_probe_start,a1
        move.l  #msg_v10_probe_start_end-msg_v10_probe_start,d3
        jsr     print
        lea     msg_vpv21n_p_alloc_before,a1
        move.l  #msg_vpv21n_p_alloc_before_end-msg_vpv21n_p_alloc_before,d3
        jsr     vpv21n_trace

        move.l  a4,a6
        move.l  #V10_MKV_PROBE_SIZE,d0
        move.l  #MEMF_FAST,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   v10_probe_alloc_fail
        move.l  d0,v10_mkv_buf_ptr
        lea     msg_vpv21n_p_alloc_after,a1
        move.l  #msg_vpv21n_p_alloc_after_end-msg_vpv21n_p_alloc_after,d3
        jsr     vpv21n_trace
        lea     msg_vpv21n_p_open_before,a1
        move.l  #msg_vpv21n_p_open_before_end-msg_vpv21n_p_open_before,d3
        jsr     vpv21n_trace

        move.l  a5,a6
        lea     t23_file_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   v10_probe_open_fail
        move.l  d0,v10_mkv_handle
        lea     msg_vpv21n_p_open_after,a1
        move.l  #msg_vpv21n_p_open_after_end-msg_vpv21n_p_open_after,d3
        jsr     vpv21n_trace
        lea     msg_vpv21n_p_read_before,a1
        move.l  #msg_vpv21n_p_read_before_end-msg_vpv21n_p_read_before,d3
        jsr     vpv21n_trace

        ; mkvr7fix USB: keep the proven 2-MiB probe buffer/parser, but do not
        ; ask DOS/filesystem/device for one giant 2-MiB transfer.  The live
        ; MKV demux already uses 64-KiB windows, so fill the same probe buffer
        ; with <=64-KiB Read() calls.  This also accepts a final short read/EOF.
        clr.l   d4                      ; total probe bytes read
        move.l  v10_mkv_buf_ptr,d5     ; current destination
        move.l  #V10_MKV_PROBE_SIZE,d6 ; bytes still wanted
v10_probe_read_64k_loop:
        tst.l   d6
        beq.s   v10_probe_read_64k_done
        move.l  d6,d3
        cmpi.l  #V10P_IO_SIZE,d3
        bls.s   v10_probe_read_64k_size_ok
        move.l  #V10P_IO_SIZE,d3
v10_probe_read_64k_size_ok:
        move.l  v10_mkv_handle,d1
        move.l  d5,d2
        move.l  a5,a6
        jsr     Read(a6)
        tst.l   d0
        bmi.s   v10_probe_read_64k_error
        beq.s   v10_probe_read_64k_done ; normal EOF
        add.l   d0,d4
        add.l   d0,d5
        sub.l   d0,d6
        bra.s   v10_probe_read_64k_loop
v10_probe_read_64k_error:
        clr.l   d4                      ; force normal probe failure path
v10_probe_read_64k_done:
        move.l  d4,v10_mkv_read
        lea     msg_vpv21n_p_read_after,a1
        move.l  #msg_vpv21n_p_read_after_end-msg_vpv21n_p_read_after,d3
        jsr     vpv21n_trace
        lea     msg_vpv21n_p_close_before,a1
        move.l  #msg_vpv21n_p_close_before_end-msg_vpv21n_p_close_before,d3
        jsr     vpv21n_trace

        move.l  v10_mkv_handle,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   v10_mkv_handle
        lea     msg_vpv21n_p_close_after,a1
        move.l  #msg_vpv21n_p_close_after_end-msg_vpv21n_p_close_after,d3
        jsr     vpv21n_trace

        lea     msg_v10_probe_read,a1
        move.l  #msg_v10_probe_read_end-msg_v10_probe_read,d3
        jsr     print
        move.l  v10_mkv_read,d0
        jsr     print_hex32
        jsr     newline

        move.l  v10_mkv_read,d0
        cmpi.l  #8,d0
        bcs.w   v10_probe_format_fail
        move.l  v10_mkv_buf_ptr,a0
        cmpi.l  #$1A45DFA3,(a0)
        bne.w   v10_probe_format_fail

        lea     msg_v10_ebml_ok,a1
        move.l  #msg_v10_ebml_ok_end-msg_v10_ebml_ok,d3
        jsr     print
        move.l  v10_mkv_buf_ptr,a0
        move.l  a0,a1
        add.l   v10_mkv_read,a1
        jsr     v10_scan_elements

        lea     msg_v10_summary,a1
        move.l  #msg_v10_summary_end-msg_v10_summary,d3
        jsr     print
        lea     msg_v10_tracks,a1
        move.l  #msg_v10_tracks_end-msg_v10_tracks,d3
        jsr     print
        move.l  v10_track_count,d0
        jsr     print_hex32
        jsr     newline

        tst.l   v10_h264_found
        beq.w   v10_probe_no_avc
        lea     msg_v10_video_track,a1
        move.l  #msg_v10_video_track_end-msg_v10_video_track,d3
        jsr     print
        move.l  v10_video_track_num,d0
        jsr     print_hex32
        lea     msg_v10_timescale,a1
        move.l  #msg_v10_timescale_end-msg_v10_timescale,d3
        jsr     print
        move.l  v10_timecode_scale,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_v10_video_geom,a1
        move.l  #msg_v10_video_geom_end-msg_v10_video_geom,d3
        jsr     print
        move.l  v10_video_width,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v10_video_height,d0
        jsr     print_hex32
        lea     msg_v10_video_dur,a1
        move.l  #msg_v10_video_dur_end-msg_v10_video_dur,d3
        jsr     print
        move.l  v10_video_default_dur,d0
        jsr     print_hex32
        jsr     newline

        move.l  v10_video_default_dur,d1
        beq.s   v10_probe_fps_unknown
        move.l  d1,d0
        lsr.l   #1,d0
        add.l   #1000000000,d0           ; round(1e9 / DefaultDuration)
        jsr     v10_udiv32
        lea     msg_v10_fps,a1
        move.l  #msg_v10_fps_end-msg_v10_fps,d3
        jsr     print
        jsr     print_hex32
        jsr     newline
        bra.s   v10_probe_fps_done
v10_probe_fps_unknown:
        lea     msg_v10_fps_unknown,a1
        move.l  #msg_v10_fps_unknown_end-msg_v10_fps_unknown,d3
        jsr     print
v10_probe_fps_done:

        tst.l   v10_first_pts_found
        beq.s   v10_probe_no_pts
        lea     msg_v10_pts,a1
        move.l  #msg_v10_pts_end-msg_v10_pts,d3
        jsr     print
        move.l  v10_first_pts_ticks,d0
        jsr     print_hex32
        lea     msg_v10_pts_rel,a1
        move.l  #msg_v10_pts_rel_end-msg_v10_pts_rel,d3
        jsr     print
        move.l  v10_first_rel_tc,d0
        jsr     print_hex32
        lea     msg_v10_pts_scale,a1
        move.l  #msg_v10_pts_scale_end-msg_v10_pts_scale,d3
        jsr     print
        move.l  v10_timecode_scale,d0
        jsr     print_hex32
        jsr     newline
        bra.s   v10_probe_success
v10_probe_no_pts:
        lea     msg_v10_no_pts,a1
        move.l  #msg_v10_no_pts_end-msg_v10_no_pts,d3
        jsr     print
        bra.s   v10_probe_success
v10_probe_no_avc:
        lea     msg_v10_no_avc,a1
        move.l  #msg_v10_no_avc_end-msg_v10_no_avc,d3
        jsr     print

v10_probe_success:
        lea     msg_v10_probe_done,a1
        move.l  #msg_v10_probe_done_end-msg_v10_probe_done,d3
        jsr     print
        bra.s   v10_probe_cleanup
v10_probe_format_fail:
        lea     msg_v10_bad_mkv,a1
        move.l  #msg_v10_bad_mkv_end-msg_v10_bad_mkv,d3
        jsr     print
        bra.s   v10_probe_cleanup
v10_probe_open_fail:
        lea     msg_v10_open_fail,a1
        move.l  #msg_v10_open_fail_end-msg_v10_open_fail,d3
        jsr     print
        bra.s   v10_probe_cleanup
v10_probe_alloc_fail:
        lea     msg_v10_alloc_fail,a1
        move.l  #msg_v10_alloc_fail_end-msg_v10_alloc_fail,d3
        jsr     print
        bra.s   v10_probe_exit

v10_probe_cleanup:
        move.l  v10_mkv_handle,d0
        beq.s   v10_probe_file_closed
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   v10_mkv_handle
v10_probe_file_closed:
        move.l  v10_mkv_buf_ptr,d0
        beq.s   v10_probe_exit
        move.l  d0,a1
        move.l  #V10_MKV_PROBE_SIZE,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   v10_mkv_buf_ptr
v10_probe_exit:
        movem.l (sp)+,d0-d7/a0-a6
        rts

        section data,data
