        even

        section bss,bss
v10_mkv_buf_ptr:          ds.l 1
v10_mkv_handle:           ds.l 1
v10_mkv_read:             ds.l 1
v10_track_count:          ds.l 1
v10_in_track:             ds.l 1
v10_cur_track_num:        ds.l 1
v10_cur_track_type:       ds.l 1
v10_cur_codec_ptr:        ds.l 1
v10_cur_codec_len:        ds.l 1
v10_cur_codecpriv_ptr:    ds.l 1
v10_cur_codecpriv_len:    ds.l 1
v10_cur_default_dur:      ds.l 1
v10_cur_width:            ds.l 1
v10_cur_height:           ds.l 1
v10_cur_channels:         ds.l 1
v10_h264_found:           ds.l 1
v10_video_track_num:      ds.l 1
v10_video_codecpriv_ptr:  ds.l 1
v10_video_codecpriv_len:  ds.l 1
v10_video_default_dur:    ds.l 1
v10_video_width:          ds.l 1
v10_video_height:         ds.l 1
v10_nal_length_size:      ds.l 1
v10_avcc_ok:              ds.l 1
v10_avcc_sps_count:       ds.l 1
v10_timecode_scale:       ds.l 1
v10_cluster_timecode:     ds.l 1
v10_first_pts_found:      ds.l 1
v10_first_pts_ticks:      ds.l 1
v10_first_rel_tc:         ds.l 1


; ====================================================================
; V10P - BOUNDED-MEMORY MATROSKA -> ANNEX-B LIVE DEMUX
; ====================================================================
; This path never allocates the movie size and never creates a temporary file.
; The source is consumed sequentially through one fixed 64-KiB Fast-RAM window.
; Only the selected V_MPEG4/ISO/AVC SimpleBlock/Block payload is converted.
; AVC NAL length prefixes can span input-window boundaries. V10P preserves each
; Matroska video block as one MMAL access unit: large encoded frames may span any
; number of <=256-KiB MMAL buffers using FRAME_START/FRAME_END. Video lacing remains
; intentionally rejected. Non-video blocks (including AAC) are skipped in-stream.
;
; File offsets/element sizes are kept in 32 bits. This comfortably covers the
; requested 1-GiB class and classic AmigaDOS Seek/Read usage; >2-GiB container
; edge cases are not the goal of this first hardware test.

        section code,code

; Reset/free only V10P's process-local 64-KiB source window. DOS file closing is
; deliberately left to the already-proven t23 close sites.
v10b_stream_reset:
        movem.l d0-d2/a0-a1/a6,-(sp)
        move.l  v10b_io_ptr,d0
        beq.s   v10b_reset_no_io
        move.l  d0,a1
        move.l  #V10P_IO_SIZE,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   v10b_io_ptr
v10b_reset_no_io:
        clr.l   v10b_io_len
        clr.l   v10b_io_pos
        clr.l   v10b_abs_pos
        clr.l   v10b_reader_eof
        clr.l   v10b_reader_error
        clr.l   v10b_stream_started
        clr.l   v10b_stream_done
        clr.l   v10b_block_remaining
        clr.l   v10b_nal_remaining
        clr.l   v10b_cluster_active
        clr.l   v10b_cluster_end
        clr.l   v10b_blockgroup_end
        clr.l   v10b_emit_config_pos
        clr.l   v10g_chunk_flags
        clr.l   v10g_frame_open
        clr.l   v10g_frame_fragment_no
        clr.l   v10g_split_frame_count
        movem.l (sp)+,d0-d2/a0-a1/a6
        rts

; Open the original MKV and allocate exactly one 64-KiB Fast-RAM input window.
; D0=0 success, 1 failure.
v10b_stream_open:
        movem.l d1-d7/a0-a2/a6,-(sp)
        tst.l   v10b_stream_started
        bne.w   v10b_open_ok
        clr.l   v10b_stream_error_stage
        clr.l   v10b_io_len
        clr.l   v10b_io_pos
        clr.l   v10b_abs_pos
        clr.l   v10b_reader_eof
        clr.l   v10b_reader_error
        clr.l   v10b_stream_done
        clr.l   v10b_block_remaining
        clr.l   v10b_nal_remaining
        clr.l   v10b_cluster_active
        clr.l   v10b_cluster_end
        clr.l   v10b_blockgroup_end
        clr.l   v10b_cluster_timecode_live
        ; V10P single-axis test: SPS/PPS are already committed as INPUT
        ; PORT_INFO_SET extradata.  Do NOT send the same Annex-B SPS/PPS again
        ; as a synthetic MMAL_BUFFER_FLAG_CONFIG input buffer.
        move.l  h264_codec_config_len,d0
        move.l  d0,v10b_emit_config_pos
        clr.l   v10g_chunk_flags
        clr.l   v10g_frame_open
        clr.l   v10g_frame_fragment_no
        clr.l   v10g_split_frame_count
        clr.l   v10b_video_block_count
        move.l  #2,v10b_nal_count          ; avcC-exported SPS + PPS are decoder config
        clr.l   v10b_last_pts_ticks
        clr.l   v10b_pts_valid
        clr.l   t23_total_read

        move.l  a4,a6
        move.l  #V10P_IO_SIZE,d0
        move.l  #MEMF_FAST,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   v10b_open_alloc_fail
        move.l  d0,v10b_io_ptr

        move.l  a5,a6
        lea     t23_file_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   v10b_open_file_fail
        move.l  d0,t23_file_handle
        move.l  #1,v10b_stream_started

        ; R5 playback reopen: position the DOS file directly at the selected
        ; IDR AVC payload and reconstruct the minimal live-cluster state that
        ; v10b_find_video_block needs after that first access unit completes.
        tst.l   v005r5_seek_valid
        beq.s   v005r5_stream_seek_done
        move.l  t23_file_handle,d1
        move.l  v005r5_seek_payload_pos,d2
        move.l  #OFFSET_BEGINNING,d3
        move.l  a5,a6
        jsr     Seek(a6)
        cmpi.l  #-1,d0
        bne.s   v005r5_stream_seek_ok
        ; Unlike the legacy Open() failure path a handle already exists here.
        move.l  t23_file_handle,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
        bra.w   v10b_open_file_fail
v005r5_stream_seek_ok:

        clr.l   v10b_io_len
        clr.l   v10b_io_pos
        move.l  v005r5_seek_payload_pos,v10b_abs_pos
        clr.l   v10b_reader_eof
        clr.l   v10b_reader_error
        clr.l   v10b_stream_done
        move.l  #1,v10b_cluster_active
        move.l  v005r5_seek_cluster_end,v10b_cluster_end
        move.l  v005r5_seek_blockgroup_end,v10b_blockgroup_end
        move.l  v005r5_seek_cluster_tc,v10b_cluster_timecode_live
        move.l  v005r5_seek_payload_len,v10b_block_remaining
        clr.l   v10b_nal_remaining
        move.l  v005r5_seek_pts_ticks,v10b_last_pts_ticks
        move.l  #1,v10b_pts_valid
        move.l  #1,v10b_video_block_count
        move.l  v005r5_seek_segment_end,v10b_segment_end
        move.l  #1,v005r5_seek_primed
        ; Effective stream origin after a real file seek.
        move.l  v005r5_seek_pts_ticks,v10_first_pts_ticks
        move.l  #1,v10_first_pts_found

v005r5_stream_seek_done:
        lea     msg_v10b_open_ok,a1
        move.l  #msg_v10b_open_ok_end-msg_v10b_open_ok,d3
        jsr     print
v10b_open_ok:
        moveq   #0,d0
        bra.s   v10b_open_done

v10b_open_file_fail:
        move.l  #$00000002,v10b_stream_error_stage
        jsr     v10b_stream_reset
        moveq   #1,d0
        bra.s   v10b_open_done
v10b_open_alloc_fail:
        move.l  #$00000001,v10b_stream_error_stage
        moveq   #1,d0
v10b_open_done:
        movem.l (sp)+,d1-d7/a0-a2/a6
        rts

; Refill the 64-KiB source window. D0=0 data, 2 clean source EOF, 1 error.
v10b_refill:
        movem.l d1-d3/a0/a6,-(sp)
        move.l  t23_file_handle,d1
        beq.s   v10b_refill_fail
        move.l  v10b_io_ptr,d2
        beq.s   v10b_refill_fail
        move.l  #V10P_IO_SIZE,d3
        move.l  a5,a6
        jsr     Read(a6)
        tst.l   d0
        bmi.s   v10b_refill_fail
        beq.s   v10b_refill_eof
        move.l  d0,v10b_io_len
        clr.l   v10b_io_pos
        moveq   #0,d0
        bra.s   v10b_refill_done
v10b_refill_eof:
        move.l  #1,v10b_reader_eof
        clr.l   v10b_io_len
        clr.l   v10b_io_pos
        moveq   #2,d0
        bra.s   v10b_refill_done
v10b_refill_fail:
        move.l  #1,v10b_reader_error
        move.l  #$00000003,v10b_stream_error_stage
        moveq   #1,d0
v10b_refill_done:
        movem.l (sp)+,d1-d3/a0/a6
        rts

; Get one source byte. D0=status (0/1/2), D1=byte when success.
v10b_get_byte:
        movem.l d2-d4/a0,-(sp)
v10b_get_byte_retry:
        move.l  v10b_io_pos,d2
        move.l  v10b_io_len,d3
        cmp.l   d3,d2
        bcs.s   v10b_get_byte_have
        jsr     v10b_refill
        tst.l   d0
        bne.s   v10b_get_byte_done
        bra.s   v10b_get_byte_retry
v10b_get_byte_have:
        move.l  v10b_io_ptr,a0
        adda.l  d2,a0
        moveq   #0,d1
        move.b  (a0),d1
        addq.l  #1,d2
        move.l  d2,v10b_io_pos
        addq.l  #1,v10b_abs_pos
        moveq   #0,d0
v10b_get_byte_done:
        movem.l (sp)+,d2-d4/a0
        rts

; Skip exactly D0 source bytes through the bounded reader. D0=0 success/1 fail.
v10b_skip_bytes:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  d0,d7
v10b_skip_loop:
        tst.l   d7
        beq.s   v10b_skip_ok
        move.l  v10b_io_len,d2
        move.l  v10b_io_pos,d1
        sub.l   d1,d2                    ; available bytes
        bne.s   v10b_skip_have
        jsr     v10b_refill
        tst.l   d0
        bne.s   v10b_skip_fail
        bra.s   v10b_skip_loop
v10b_skip_have:
        move.l  d7,d3
        cmp.l   d2,d3
        bls.s   v10b_skip_n_ready
        move.l  d2,d3
v10b_skip_n_ready:
        add.l   d3,v10b_io_pos
        add.l   d3,v10b_abs_pos
        sub.l   d3,d7
        bra.s   v10b_skip_loop
v10b_skip_ok:
        moveq   #0,d0
        bra.s   v10b_skip_done
v10b_skip_fail:
        move.l  #$00000004,v10b_stream_error_stage
        moveq   #1,d0
v10b_skip_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Copy exactly D0 source bytes into the current MMAL output chunk and advance
; both reader and output state. Caller guarantees D0 <= v10b_out_space.
v10b_copy_source_out:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,d7
v10b_copy_src_loop:
        tst.l   d7
        beq.w   v10b_copy_src_ok
        move.l  v10b_io_len,d2
        move.l  v10b_io_pos,d1
        sub.l   d1,d2
        bne.s   v10b_copy_src_have
        jsr     v10b_refill
        tst.l   d0
        bne.w   v10b_copy_src_fail
        bra.s   v10b_copy_src_loop
v10b_copy_src_have:
        move.l  d7,d5
        cmp.l   d2,d5
        bls.s   v10b_copy_src_n_ready
        move.l  d2,d5
v10b_copy_src_n_ready:
        move.l  v10b_io_ptr,a1
        adda.l  v10b_io_pos,a1
        move.l  v10b_out_ptr,a2

        move.l  d5,d6
        lsr.l   #2,d6
        beq.s   v10b_copy_src_bytes
        subq.l  #1,d6
v10b_copy_src_long_loop:
        move.l  (a1)+,(a2)+
        dbra    d6,v10b_copy_src_long_loop
v10b_copy_src_bytes:
        move.l  d5,d6
        andi.l  #3,d6
        beq.s   v10b_copy_src_update
        subq.l  #1,d6
v10b_copy_src_byte_loop:
        move.b  (a1)+,(a2)+
        dbra    d6,v10b_copy_src_byte_loop
v10b_copy_src_update:
        add.l   d5,v10b_io_pos
        add.l   d5,v10b_abs_pos
        add.l   d5,v10b_out_ptr
        add.l   d5,v10b_out_count
        sub.l   d5,v10b_out_space
        sub.l   d5,d7
        bra.w   v10b_copy_src_loop
v10b_copy_src_ok:
        moveq   #0,d0
        bra.s   v10b_copy_src_done
v10b_copy_src_fail:
        move.l  #$00000005,v10b_stream_error_stage
        moveq   #1,d0
v10b_copy_src_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Emit D0 bytes from A0 into the current output chunk. D0=0 success/1 fail.
v10b_emit_mem:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  d0,d7
        move.l  v10b_out_space,d1
        cmp.l   d7,d1
        bcs.s   v10b_emit_mem_fail
        move.l  v10b_out_ptr,a1
        move.l  d7,d6
        beq.s   v10b_emit_mem_ok
        subq.l  #1,d6
v10b_emit_mem_loop:
        move.b  (a0)+,(a1)+
        dbra    d6,v10b_emit_mem_loop
        add.l   d7,v10b_out_ptr
        add.l   d7,v10b_out_count
        sub.l   d7,v10b_out_space
v10b_emit_mem_ok:
        moveq   #0,d0
        bra.s   v10b_emit_mem_done
v10b_emit_mem_fail:
        move.l  #$00000006,v10b_stream_error_stage
        moveq   #1,d0
v10b_emit_mem_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Streaming EBML ID: D0=status, D1=ID (marker retained), D2=encoded bytes.
v10b_read_id:
        movem.l d3-d7/a0,-(sp)
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   v10b_read_id_done
        move.l  d1,d3
        moveq   #1,d4
        btst    #7,d3
        bne.s   v10b_id_len_ready
        moveq   #2,d4
        btst    #6,d3
        bne.s   v10b_id_len_ready
        moveq   #3,d4
        btst    #5,d3
        bne.s   v10b_id_len_ready
        moveq   #4,d4
        btst    #4,d3
        bne.s   v10b_id_len_ready
        move.l  #$00000007,v10b_stream_error_stage
        moveq   #1,d0
        bra.s   v10b_read_id_done
v10b_id_len_ready:
        move.l  d3,d5
        move.l  d4,d6
        subq.l  #1,d6
        beq.s   v10b_id_success
v10b_id_more:
        jsr     v10b_get_byte
        tst.l   d0
        beq.s   v10b_id_more_have
        move.l  #$00000008,v10b_stream_error_stage
        moveq   #1,d0
        bra.s   v10b_read_id_done
v10b_id_more_have:
        lsl.l   #8,d5
        or.l    d1,d5
        subq.l  #1,d6
        bne.s   v10b_id_more
v10b_id_success:
        move.l  d5,d1
        move.l  d4,d2
        moveq   #0,d0
v10b_read_id_done:
        movem.l (sp)+,d3-d7/a0
        rts

; Streaming EBML VINT size/value: D0=status, D1=value (FFFFFFFF=unknown), D2=len.
; Values larger than 32 bits are rejected unless their high bytes are zero.
v10b_read_size:
        movem.l d3-d7/a0-a3,-(sp)
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   v10b_size_done
        lea     v10b_vint_tmp,a2
        move.b  d1,(a2)
        move.l  d1,d3                    ; raw first byte
        move.l  #$00000080,d4            ; marker bit
        moveq   #1,d5                    ; encoded length
v10b_size_find_marker:
        move.l  d3,d6
        and.l   d4,d6
        bne.s   v10b_size_marker_found
        lsr.l   #1,d4
        addq.l  #1,d5
        cmpi.l  #9,d5
        bcs.s   v10b_size_find_marker
        move.l  #$00000009,v10b_stream_error_stage
        moveq   #1,d0
        bra.w   v10b_size_done
v10b_size_marker_found:
        move.l  d5,d7
        subq.l  #1,d7
        beq.s   v10b_size_all_read
        lea     1(a2),a3
v10b_size_read_more:
        jsr     v10b_get_byte
        tst.l   d0
        beq.s   v10b_size_store_more
        move.l  #$0000000A,v10b_stream_error_stage
        moveq   #1,d0
        bra.w   v10b_size_done
v10b_size_store_more:
        move.b  d1,(a3)+
        subq.l  #1,d7
        bne.s   v10b_size_read_more
v10b_size_all_read:
        ; Unknown-size test: first stripped value equals marker-1 and every
        ; following encoded byte is FF. This also handles 8-byte 01 FF..FF.
        move.l  d4,d6
        subq.l  #1,d6                    ; first-byte value mask
        moveq   #0,d3
        move.b  (a2),d3
        and.l   d6,d3                    ; first stripped value
        cmp.l   d6,d3
        bne.s   v10b_size_not_unknown
        move.l  d5,d7
        subq.l  #1,d7
        beq.s   v10b_size_unknown
        lea     1(a2),a3
v10b_size_unknown_loop:
        cmpi.b  #$FF,(a3)+
        bne.s   v10b_size_not_unknown
        subq.l  #1,d7
        bne.s   v10b_size_unknown_loop
v10b_size_unknown:
        move.l  #$FFFFFFFF,d1
        move.l  d5,d2
        moveq   #0,d0
        bra.w   v10b_size_done

v10b_size_not_unknown:
        cmpi.l  #4,d5
        bls.s   v10b_size_build_short
        ; For 5..8-byte VINTs, all bytes above the low 32 bits must be zero.
        tst.l   d3                       ; stripped first high byte/value bits
        bne.w   v10b_size_too_large
        move.l  d5,d7
        sub.l   #4,d7                    ; number of high encoded bytes
        subq.l  #1,d7                    ; first byte already checked
        ble.s   v10b_size_build_last4
        lea     1(a2),a3
v10b_size_high_zero_loop:
        tst.b   (a3)+
        bne.w   v10b_size_too_large
        subq.l  #1,d7
        bne.s   v10b_size_high_zero_loop
v10b_size_build_last4:
        move.l  d5,d7
        sub.l   #4,d7
        lea     (a2,d7.l),a3
        moveq   #0,d6
        moveq   #3,d7
v10b_size_last4_loop:
        lsl.l   #8,d6
        moveq   #0,d3
        move.b  (a3)+,d3
        or.l    d3,d6
        dbra    d7,v10b_size_last4_loop
        move.l  d6,d1
        move.l  d5,d2
        moveq   #0,d0
        bra.s   v10b_size_done

v10b_size_build_short:
        move.l  d3,d6
        move.l  d5,d7
        subq.l  #1,d7
        beq.s   v10b_size_short_done
        lea     1(a2),a3
v10b_size_short_loop:
        lsl.l   #8,d6
        moveq   #0,d3
        move.b  (a3)+,d3
        or.l    d3,d6
        subq.l  #1,d7
        bne.s   v10b_size_short_loop
v10b_size_short_done:
        move.l  d6,d1
        move.l  d5,d2
        moveq   #0,d0
        bra.s   v10b_size_done
v10b_size_too_large:
        move.l  #$0000000B,v10b_stream_error_stage
        moveq   #1,d0
v10b_size_done:
        movem.l (sp)+,d3-d7/a0-a3
        rts

; Read unsigned EBML integer payload of D0 bytes (up to 4 significant bytes;
; longer encodings are accepted only when their high bytes are zero).
; D0=status, D1=value.
v10b_read_uint:
        movem.l d2-d7,-(sp)
        move.l  d0,d7
        moveq   #0,d6
        tst.l   d7
        beq.s   v10b_uint_ok
        cmpi.l  #8,d7
        bhi.s   v10b_uint_fail
        move.l  d7,d5
        sub.l   #4,d5
        ble.s   v10b_uint_low_part
v10b_uint_high_loop:
        jsr     v10b_get_byte
        tst.l   d0
        bne.s   v10b_uint_fail
        tst.l   d1
        bne.s   v10b_uint_fail
        subq.l  #1,d5
        bne.s   v10b_uint_high_loop
v10b_uint_low_part:
        move.l  d7,d5
        cmpi.l  #4,d5
        bls.s   v10b_uint_low_count_ok
        moveq   #4,d5
v10b_uint_low_count_ok:
        tst.l   d5
        beq.s   v10b_uint_ok
v10b_uint_low_loop:
        jsr     v10b_get_byte
        tst.l   d0
        bne.s   v10b_uint_fail
        lsl.l   #8,d6
        or.l    d1,d6
        subq.l  #1,d5
        bne.s   v10b_uint_low_loop
v10b_uint_ok:
        move.l  d6,d1
        moveq   #0,d0
        bra.s   v10b_uint_done
v10b_uint_fail:
        move.l  #$0000000C,v10b_stream_error_stage
        moveq   #1,d0
v10b_uint_done:
        movem.l (sp)+,d2-d7
        rts

; Parse one SimpleBlock/Block payload of D0 bytes. Returns:
; D0=0 selected video block ready; D0=3 non-video block skipped; D0=1 failure.
v10b_begin_block:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  d0,d7                    ; complete element payload bytes
        cmpi.l  #4,d7
        bcs.w   v10b_block_fail

        jsr     v10b_read_size           ; TrackNumber VINT uses same stripped value
        tst.l   d0
        bne.w   v10b_block_fail
        move.l  d1,d6                    ; track number
        move.l  d2,d5                    ; VINT bytes consumed
        move.l  d5,d4
        addq.l  #3,d4
        cmp.l   d7,d4
        bhi.w   v10b_block_fail

        jsr     v10b_get_byte
        tst.l   d0
        bne.w   v10b_block_fail
        move.l  d1,d3
        lsl.w   #8,d3
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   v10b_block_fail
        or.w    d1,d3
        ext.l   d3                       ; signed block-relative timecode
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   v10b_block_fail
        move.l  d1,d2                    ; flags

        sub.l   d4,d7                    ; AVC/audio payload remaining after block hdr
        cmp.l   v10_video_track_num,d6
        beq.s   v10b_block_selected
        move.l  d7,d0
        jsr     v10b_skip_bytes
        tst.l   d0
        bne.s   v10b_block_fail
        moveq   #3,d0
        bra.w   v10b_block_done

v10b_block_selected:
        move.l  d2,d1
        andi.l  #$00000006,d1            ; Matroska lacing bits
        beq.s   v10b_block_unlaced
        move.l  #1,v10b_laced_video_seen
        move.l  d7,d0
        jsr     v10b_skip_bytes
        move.l  #$0000000D,v10b_stream_error_stage
        moveq   #1,d0
        bra.s   v10b_block_done
v10b_block_unlaced:
        tst.l   d7
        beq.s   v10b_block_fail
        move.l  d7,v10b_block_remaining
        move.l  d7,v10h_current_frame_payload
        clr.l   v10b_nal_remaining
        addq.l  #1,v10b_video_block_count
        move.l  v10b_cluster_timecode_live,d1
        add.l   d3,d1
        move.l  d1,v10b_last_pts_ticks
        move.l  #1,v10b_pts_valid
        moveq   #0,d0
        bra.s   v10b_block_done
v10b_block_fail:
        move.l  #$0000000E,v10b_stream_error_stage
        moveq   #1,d0
v10b_block_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; --------------------------------------------------------------------
; R5 compressed T: video seek.
;
; Scan Matroska/H.264 entirely on CPU/DOS before VCHIQ/MMAL exists.  Selected
; video Block payloads remain avcC length-prefixed here; inspect every NAL in
; each access unit and choose the first real IDR (nal_unit_type=5) whose PTS is
; >= requested T:.  No P/B frame is ever handed to the hardware decoder during
; this search.  Playback later DOS-Seek()s directly to the saved IDR payload.
; --------------------------------------------------------------------

; Consume the currently selected v10b_block_remaining AVC payload and return:
;   D0=0 no IDR, D0=1 contains IDR, D0=2 malformed/read failure.
v005r5_scan_current_block_idr:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  v10b_block_remaining,d7
        moveq   #0,d6                    ; found-IDR flag
v005r5_scan_nal_loop:
        tst.l   d7
        beq.s   v005r5_scan_nal_done
        move.l  v10_nal_length_size,d5
        cmpi.l  #1,d5
        bcs.s   v005r5_scan_nal_fail
        cmpi.l  #4,d5
        bhi.s   v005r5_scan_nal_fail
        cmp.l   d5,d7
        bcs.s   v005r5_scan_nal_fail

        moveq   #0,d4                    ; one AVC NAL payload length
        move.l  d5,d3
v005r5_scan_len_loop:
        jsr     v10b_get_byte
        tst.l   d0
        bne.s   v005r5_scan_nal_fail
        lsl.l   #8,d4
        or.l    d1,d4
        subq.l  #1,d7
        subq.l  #1,d3
        bne.s   v005r5_scan_len_loop
        tst.l   d4
        beq.s   v005r5_scan_nal_fail
        cmp.l   d7,d4
        bhi.s   v005r5_scan_nal_fail

        ; Read the actual NAL header, not an assumed byte-4 Annex-B position.
        jsr     v10b_get_byte
        tst.l   d0
        bne.s   v005r5_scan_nal_fail
        subq.l  #1,d7
        move.l  d1,d2
        andi.l  #$0000001F,d2
        cmpi.l  #5,d2
        bne.s   v005r5_scan_not_idr
        moveq   #1,d6
v005r5_scan_not_idr:
        subq.l  #1,d4
        beq.s   v005r5_scan_nal_loop
        move.l  d4,d0
        jsr     v10b_skip_bytes
        tst.l   d0
        bne.s   v005r5_scan_nal_fail
        sub.l   d4,d7
        bra.s   v005r5_scan_nal_loop

v005r5_scan_nal_done:
        clr.l   v10b_block_remaining
        clr.l   v10b_nal_remaining
        move.l  d6,d0
        bra.s   v005r5_scan_nal_exit
v005r5_scan_nal_fail:
        clr.l   v10b_block_remaining
        clr.l   v10b_nal_remaining
        moveq   #2,d0
v005r5_scan_nal_exit:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Resolve textual T: to the first H.264 IDR at/after the requested millisecond.
; D0=0 success/no T:, D0=1 failure.  Only 1-ms Matroska scale is enabled here;
; that is the same hardware-proven timing domain used by the A/V scheduler.
v005r5_prepare_video_seek:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   v005r5_seek_valid
        clr.l   v005r5_seek_primed
        clr.l   v005r5_seek_request_ticks
        clr.l   v005r5_seek_pts_ticks

        tst.l   v40j_start_time_valid
        beq.w   v005r5_seek_ok
        move.l  v40j_start_time_secs,d0
        tst.l   d0
        beq.w   v005r5_seek_ok
        tst.l   v10_video_track_num
        beq.w   v005r5_seek_fail
        tst.l   v10_avcc_ok
        beq.w   v005r5_seek_fail
        move.l  v10_timecode_scale,d1
        cmpi.l  #VPV43_TIMECODE_SCALE_MS,d1
        bne.w   v005r5_seek_fail

        cmpi.l  #65535,d0
        bls.s   v005r5_seek_secs_ok
        move.l  #65535,d0
v005r5_seek_secs_ok:
        mulu.w  #1000,d0
        move.l  d0,v005r5_seek_request_ticks

        ; Open the ordinary bounded video reader, but use it only as a parser.
        ; No call to v10b_next_annexb_chunk and no MMAL buffer is involved.
        jsr     v10b_stream_open
        tst.l   d0
        bne.w   v005r5_seek_fail_cleanup

v005r5_seek_scan_loop:
        jsr     v10b_find_video_block
        tst.l   d0
        beq.s   v005r5_seek_have_block
        cmpi.l  #2,d0
        beq.w   v005r5_seek_fail_cleanup
        bra.w   v005r5_seek_fail_cleanup

v005r5_seek_have_block:
        ; Snapshot payload/file/cluster state BEFORE consuming it for IDR scan.
        move.l  v10b_abs_pos,v005r5_scan_pos
        move.l  v10b_block_remaining,v005r5_scan_len
        move.l  v10b_last_pts_ticks,v005r5_scan_pts
        move.l  v10b_cluster_end,v005r5_scan_cluster_end
        move.l  v10b_blockgroup_end,v005r5_scan_blockgroup_end
        move.l  v10b_cluster_timecode_live,v005r5_scan_cluster_tc
        move.l  v10b_segment_end,v005r5_scan_segment_end

        jsr     v005r5_scan_current_block_idr
        cmpi.l  #2,d0
        beq.w   v005r5_seek_fail_cleanup
        cmpi.l  #1,d0
        bne.w   v005r5_seek_scan_loop

        move.l  v005r5_scan_pts,d1
        cmp.l   v005r5_seek_request_ticks,d1
        bcs.w   v005r5_seek_scan_loop

        ; First real IDR at/after T: is the new stream origin.
        move.l  #1,v005r5_seek_valid
        move.l  v005r5_scan_pts,v005r5_seek_pts_ticks
        move.l  v005r5_scan_pos,v005r5_seek_payload_pos
        move.l  v005r5_scan_len,v005r5_seek_payload_len
        move.l  v005r5_scan_cluster_end,v005r5_seek_cluster_end
        move.l  v005r5_scan_blockgroup_end,v005r5_seek_blockgroup_end
        move.l  v005r5_scan_cluster_tc,v005r5_seek_cluster_tc
        move.l  v005r5_scan_segment_end,v005r5_seek_segment_end

        lea     msg_v005r5_seek_ok,a1
        move.l  #msg_v005r5_seek_ok_end-msg_v005r5_seek_ok,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  v005r5_seek_request_ticks,d0
        jsr     print_hex32
        lea     msg_v005r5_seek_idr,a1
        move.l  #msg_v005r5_seek_idr_end-msg_v005r5_seek_idr,d3
        jsr     print_force
        move.l  v005r5_seek_pts_ticks,d0
        jsr     print_hex32
        lea     msg_v005r5_seek_off,a1
        move.l  #msg_v005r5_seek_off_end-msg_v005r5_seek_off,d3
        jsr     print_force
        move.l  v005r5_seek_payload_pos,d0
        jsr     print_hex32
        lea     msg_v005r5_seek_len,a1
        move.l  #msg_v005r5_seek_len_end-msg_v005r5_seek_len,d3
        jsr     print_force
        move.l  v005r5_seek_payload_len,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print

        ; Close/free parser state.  Saved R5 fields deliberately survive reset.
        move.l  t23_file_handle,d0
        beq.s   v005r5_seek_close_done
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
v005r5_seek_close_done:
        jsr     v10b_stream_reset
        moveq   #0,d0
        bra.s   v005r5_seek_done

v005r5_seek_fail_cleanup:
        move.l  t23_file_handle,d0
        beq.s   v005r5_seek_fail_reset
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
v005r5_seek_fail_reset:
        jsr     v10b_stream_reset
v005r5_seek_fail:
        clr.l   v005r5_seek_valid
        moveq   #1,d0
        bra.s   v005r5_seek_done
v005r5_seek_ok:
        moveq   #0,d0
v005r5_seek_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Find the next selected AVC block while walking the original Matroska file
; sequentially. D0=0 block ready, 2 clean file EOF, 1 malformed/unsupported.
v10b_find_video_block:
        movem.l d1-d7/a0-a3,-(sp)
v10b_find_loop:
        ; Close finite BlockGroup/Cluster scopes when their payload end is reached.
        move.l  v10b_blockgroup_end,d1
        beq.s   v10b_find_check_cluster
        cmpi.l  #$FFFFFFFF,d1
        beq.s   v10b_find_check_cluster
        move.l  v10b_abs_pos,d2
        cmp.l   d1,d2
        bcs.s   v10b_find_check_cluster
        clr.l   v10b_blockgroup_end
v10b_find_check_cluster:
        move.l  v10b_cluster_end,d1
        beq.s   v10b_find_header
        cmpi.l  #$FFFFFFFF,d1
        beq.s   v10b_find_header
        move.l  v10b_abs_pos,d2
        cmp.l   d1,d2
        bcs.s   v10b_find_header
        clr.l   v10b_cluster_active
        clr.l   v10b_cluster_end
        clr.l   v10b_blockgroup_end

v10b_find_header:
        jsr     v10b_read_id
        cmpi.l  #2,d0
        beq.w   v10b_find_eof
        tst.l   d0
        bne.w   v10b_find_fail
        move.l  d1,d5                    ; ID
        jsr     v10b_read_size
        tst.l   d0
        bne.w   v10b_find_fail
        move.l  d1,d6                    ; payload size / FFFFFFFF unknown

        move.l  #$FFFFFFFF,d7            ; payload end default for unknown size
        cmpi.l  #$FFFFFFFF,d6
        beq.s   v10b_find_end_ready
        move.l  v10b_abs_pos,d7
        add.l   d6,d7
        bcs.w   v10b_find_fail
v10b_find_end_ready:

        ; EBML header can be skipped wholesale; Segment and Cluster are masters
        ; we enter. Other metadata masters are skipped because V10F already parsed them.
        cmpi.l  #$1A45DFA3,d5            ; EBML
        beq.w   v10b_find_skip
        cmpi.l  #$18538067,d5            ; Segment
        beq.w   v10b_find_segment
        cmpi.l  #$1F43B675,d5            ; Cluster
        beq.w   v10b_find_cluster

        ; If a Segment-level master appears after an unknown-size Cluster, it
        ; implicitly ends that cluster for our flat streaming state machine.
        cmpi.l  #$114D9B74,d5            ; SeekHead
        beq.s   v10b_find_segment_meta
        cmpi.l  #$1549A966,d5            ; Info
        beq.s   v10b_find_segment_meta
        cmpi.l  #$1654AE6B,d5            ; Tracks
        beq.s   v10b_find_segment_meta
        cmpi.l  #$1C53BB6B,d5            ; Cues
        beq.s   v10b_find_segment_meta
        cmpi.l  #$1254C367,d5            ; Tags
        beq.s   v10b_find_segment_meta
        cmpi.l  #$1941A469,d5            ; Attachments
        beq.s   v10b_find_segment_meta
        cmpi.l  #$1043A770,d5            ; Chapters
        beq.s   v10b_find_segment_meta
        bra.s   v10b_find_cluster_children
v10b_find_segment_meta:
        move.l  v10b_cluster_end,d1
        cmpi.l  #$FFFFFFFF,d1
        bne.w   v10b_find_skip
        clr.l   v10b_cluster_active
        clr.l   v10b_cluster_end
        clr.l   v10b_blockgroup_end
        bra.w   v10b_find_skip

v10b_find_cluster_children:
        tst.l   v10b_cluster_active
        beq.w   v10b_find_skip
        cmpi.l  #$000000E7,d5            ; Cluster Timecode
        beq.w   v10b_find_timecode
        cmpi.l  #$000000A0,d5            ; BlockGroup master
        beq.w   v10b_find_blockgroup
        cmpi.l  #$000000A3,d5            ; SimpleBlock
        beq.w   v10b_find_block
        cmpi.l  #$000000A1,d5            ; Block within BlockGroup
        bne.w   v10b_find_skip
        tst.l   v10b_blockgroup_end
        beq.w   v10b_find_skip
        bra.w   v10b_find_block

v10b_find_segment:
        move.l  d7,v10b_segment_end
        bra.w   v10b_find_loop
v10b_find_cluster:
        move.l  #1,v10b_cluster_active
        move.l  d7,v10b_cluster_end
        clr.l   v10b_blockgroup_end
        clr.l   v10b_cluster_timecode_live
        bra.w   v10b_find_loop
v10b_find_blockgroup:
        move.l  d7,v10b_blockgroup_end
        bra.w   v10b_find_loop
v10b_find_timecode:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   v10b_find_fail
        move.l  d6,d0
        jsr     v10b_read_uint
        tst.l   d0
        bne.w   v10b_find_fail
        move.l  d1,v10b_cluster_timecode_live
        bra.w   v10b_find_loop
v10b_find_block:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   v10b_find_fail
        move.l  d6,d0
        jsr     v10b_begin_block
        tst.l   d0
        beq.s   v10b_find_found
        cmpi.l  #3,d0
        beq.w   v10b_find_loop
        bra.w   v10b_find_fail
v10b_find_skip:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   v10b_find_fail
        move.l  d6,d0
        jsr     v10b_skip_bytes
        tst.l   d0
        bne.w   v10b_find_fail
        bra.w   v10b_find_loop
v10b_find_found:
        moveq   #0,d0
        bra.s   v10b_find_done
v10b_find_eof:
        moveq   #2,d0
        bra.s   v10b_find_done
v10b_find_fail:
        tst.l   v10b_stream_error_stage
        bne.s   v10b_find_fail_stage_set
        move.l  #$0000000F,v10b_stream_error_stage
v10b_find_fail_stage_set:
        moveq   #1,d0
v10b_find_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Produce one <=256-KiB Annex-B fragment directly into bulk_data_ptr.
; D0=0 chunk ready, 2 clean end of selected MKV video, 1 failure.
;
; V10P difference: Matroska gives us access-unit boundaries.  Preserve those
; boundaries for MMAL.  A small access unit is one buffer with START|END; a large
; one is START|END; only access units above 256 KiB are split START/middle/END.  No fragment ever contains
; bytes from two different video blocks.  avcC-derived SPS/PPS stay exclusively in INPUT PORT_INFO_SET extradata.
; V10P deliberately emits no synthetic CONFIG input buffer before frame 0.
v10b_next_annexb_chunk:
        movem.l d1-d7/a0-a3,-(sp)
        jsr     v10b_stream_open
        tst.l   d0
        bne.w   v10b_chunk_fail
        tst.l   v10b_stream_done
        bne.w   v10b_chunk_eof

        move.l  bulk_data_ptr,d0
        move.l  d0,v10b_out_ptr
        clr.l   v10b_out_count
        move.l  #V10P_MKV_CHUNK,v10b_out_space
        clr.l   v10g_chunk_flags
        clr.l   v10h_chunk_fragment_no
        move.l  v10g_frame_open,d0
        beq.s   v10g_chunk_no_continuation
        addq.l  #1,v10g_frame_fragment_no
        move.l  v10g_frame_fragment_no,v10h_chunk_fragment_no
v10g_chunk_no_continuation:
        ; R5: when stream_open DOS-Seek()ed straight to an already-selected
        ; IDR payload, v10b_find_video_block is intentionally bypassed once.
        ; Mark that payload as a fresh access unit so MMAL sees START|END.
        tst.l   v005r5_seek_primed
        beq.s   v005r5_chunk_not_primed
        clr.l   v005r5_seek_primed
        move.l  #1,v10g_frame_open
        move.l  #1,v10g_frame_fragment_no
        move.l  #1,v10h_chunk_fragment_no
        move.l  #MMAL_BUFFER_FLAG_FRAME_START,v10g_chunk_flags
v005r5_chunk_not_primed:

        ; First MMAL input buffer is codec config only.  It is deliberately
        ; separate from frame 0 so FRAME_START really points at frame payload.
        move.l  h264_codec_config_len,d6
        move.l  v10b_emit_config_pos,d5
        cmp.l   d6,d5
        bcc.s   v10g_chunk_main
        sub.l   d5,d6
        move.l  #V10P_MKV_CHUNK,d7
        cmp.l   d7,d6
        bls.s   v10g_config_n_ready
        move.l  d7,d6
v10g_config_n_ready:
        lea     h264_file_extradata,a0
        adda.l  d5,a0
        move.l  d6,d0
        jsr     v10b_emit_mem
        tst.l   d0
        bne.w   v10b_chunk_fail
        add.l   d6,v10b_emit_config_pos
        move.l  #MMAL_BUFFER_FLAG_CONFIG,v10g_chunk_flags
        bra.w   v10b_chunk_ready

v10g_chunk_main:
        move.l  v10b_out_space,d7
        beq.w   v10b_chunk_ready

        ; Continue an AVC NAL payload that spans one or more MMAL fragments.
        move.l  v10b_nal_remaining,d6
        beq.s   v10g_chunk_need_nal_or_block
        move.l  d7,d5
        cmp.l   d6,d5
        bls.s   v10g_payload_n_ready
        move.l  d6,d5
v10g_payload_n_ready:
        move.l  d5,d0
        jsr     v10b_copy_source_out
        tst.l   d0
        bne.w   v10b_chunk_fail
        sub.l   d5,v10b_nal_remaining
        sub.l   d5,v10b_block_remaining

        ; End of this Matroska video block == end of this access unit.  Return
        ; immediately even if buffer space remains, so the next frame can never
        ; share this MMAL buffer.
        move.l  v10b_block_remaining,d0
        bne.w   v10g_chunk_main
        move.l  v10g_chunk_flags,d0
        or.l    #MMAL_BUFFER_FLAG_FRAME_END,d0
        move.l  d0,v10g_chunk_flags
        move.l  v10g_frame_fragment_no,d0
        cmpi.l  #1,d0
        bls.s   v10g_frame_not_split
        addq.l  #1,v10g_split_frame_count
v10g_frame_not_split:
        clr.l   v10g_frame_open
        clr.l   v10g_frame_fragment_no
        bra.w   v10b_chunk_ready

v10g_chunk_need_nal_or_block:
        move.l  v10b_block_remaining,d6
        beq.w   v10g_chunk_find_block

        ; Never split the synthetic 00 00 00 01 prefix across MMAL fragments.
        cmpi.l  #4,d7
        bcs.w   v10b_chunk_ready
        move.l  v10_nal_length_size,d5
        cmpi.l  #1,d5
        bcs.w   v10b_chunk_bad_avc
        cmpi.l  #4,d5
        bhi.w   v10b_chunk_bad_avc
        cmp.l   d5,d6
        bcs.w   v10b_chunk_bad_avc

        moveq   #0,d4                    ; AVC NAL payload length
        move.l  d5,d3
v10g_nal_len_loop:
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   v10b_chunk_fail
        lsl.l   #8,d4
        or.l    d1,d4
        subq.l  #1,d3
        bne.s   v10g_nal_len_loop
        sub.l   d5,v10b_block_remaining
        tst.l   d4
        beq.w   v10b_chunk_bad_avc
        move.l  v10b_block_remaining,d6
        cmp.l   d6,d4
        bhi.w   v10b_chunk_bad_avc
        move.l  d4,v10b_nal_remaining
        addq.l  #1,v10b_nal_count
        lea     v10b_startcode,a0
        moveq   #4,d0
        jsr     v10b_emit_mem
        tst.l   d0
        bne.w   v10b_chunk_fail
        bra.w   v10g_chunk_main

v10g_chunk_find_block:
        ; If a frame is already open, reaching block_remaining=0 would have
        ; returned above.  Therefore a successful find here always starts a new
        ; access unit and this MMAL fragment gets FRAME_START.
        jsr     v10b_find_video_block
        tst.l   d0
        beq.s   v10g_chunk_new_frame
        cmpi.l  #2,d0
        bne.w   v10b_chunk_fail
        move.l  #1,v10b_stream_done
        move.l  v10b_out_count,d1
        bne.w   v10b_chunk_ready
        bra.w   v10b_chunk_eof
v10g_chunk_new_frame:
        move.l  #1,v10g_frame_open
        move.l  #1,v10g_frame_fragment_no
        move.l  #1,v10h_chunk_fragment_no
        move.l  #MMAL_BUFFER_FLAG_FRAME_START,v10g_chunk_flags
        bra.w   v10g_chunk_main

v10b_chunk_bad_avc:
        move.l  #$00000010,v10b_stream_error_stage
v10b_chunk_fail:
        moveq   #1,d0
        bra.s   v10b_chunk_done
v10b_chunk_eof:
        moveq   #2,d0
        bra.s   v10b_chunk_done
v10b_chunk_ready:
        move.l  v10b_out_count,d1
        beq.s   v10b_chunk_eof

        move.l  d1,v10b_chunk_len
        moveq   #0,d0
v10b_chunk_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

        section data,data
v10b_startcode:
        dc.l $00000001
msg_v10p_unsupported:
        dc.b "FEHLER: Video wird nicht unterstuetzt.",10
msg_v10p_unsupported_end:

msg_v10b_stream_ready:
        dc.b "[V10P] MKV-Metadaten/avcC OK; starte bounded-memory Live-Demux direkt zum MMAL-H264-Input.",10
        dc.b "[V10P] Diagnose: erster MMAL ERRO wird mit Status + letztem MKV-Input-Kontext geloggt und stoppt sofort.",10
msg_v10b_stream_ready_end:
msg_v10b_prepare_fail:
        dc.b "[V10P] FEHLER: MKV enthaelt im Probe-Fenster keine nutzbare H264/AVC-Spur mit avcC.",10
msg_v10b_prepare_fail_end:
msg_v10b_open_ok:
        dc.b "[V10P] MKV-Live-Stream: 64-KiB Dateifenster, 256-KiB MMAL-Input; Frames <=256 KiB als EIN START|END-Buffer; kein doppelter CONFIG-Buffer.",10
msg_v10b_open_ok_end:
msg_v10b_stream_eof:
        dc.b "[V10P] MKV-Quelle bis EOF gestreamt; an MMAL gelieferte Annex-B-Bytes: 0x"
msg_v10b_stream_eof_end:
msg_v10b_stream_stats:
        dc.b "[V10P] Video-Bloecke=0x"
msg_v10b_stream_stats_end:
msg_v10b_stream_nals:
        dc.b "  Annex-B-NALs=0x"
msg_v10b_stream_nals_end:
msg_v10g_stream_split:
        dc.b "  >64KiB/mehrteilige Video-Frames=0x"
msg_v10g_stream_split_end:
msg_v10b_stream_fail:
        dc.b "[V10P] FEHLER im MKV-Live-Demux. Stage=0x"
msg_v10b_stream_fail_end:
msg_v10b_stream_pos:
        dc.b "  MKV-Position=0x"
msg_v10b_stream_pos_end:
        even

        section bss,bss
v10b_input_is_mkv:          ds.l 1
v10b_io_ptr:                ds.l 1
v10b_io_len:                ds.l 1
v10b_io_pos:                ds.l 1
v10b_abs_pos:               ds.l 1
v10b_reader_eof:            ds.l 1
v10b_reader_error:          ds.l 1
v10b_stream_started:        ds.l 1
v10b_stream_done:           ds.l 1
v10b_stream_error_stage:    ds.l 1
v10b_chunk_len:             ds.l 1
v10b_out_ptr:               ds.l 1
v10b_out_count:             ds.l 1
v10b_out_space:             ds.l 1
v10b_emit_config_pos:       ds.l 1
v10b_segment_end:           ds.l 1
v10b_cluster_active:        ds.l 1
v10b_cluster_end:           ds.l 1
v10b_blockgroup_end:        ds.l 1
v10b_cluster_timecode_live: ds.l 1
v10b_block_remaining:       ds.l 1
v10b_nal_remaining:         ds.l 1
v10b_video_block_count:     ds.l 1
v10b_nal_count:             ds.l 1
v10b_laced_video_seen:      ds.l 1
v10b_last_pts_ticks:        ds.l 1
v10b_pts_valid:             ds.l 1
v10g_chunk_flags:           ds.l 1
v10g_frame_open:            ds.l 1
v10g_frame_fragment_no:     ds.l 1
v10g_split_frame_count:     ds.l 1
v10b_vint_tmp:              ds.b 8
        even


; ====================================================================
; V12D - VIDECORE ISP DOWNSCALE EXPERIMENT
; Shared first/restart graph. Stable V12 remains the reference branch.
; ====================================================================
        section bss,bss
v12a_decoder_handle:       ds.l 1
v12a_decoder_output:       ds.l 1
v12a_isp_handle:           ds.l 1
v12a_isp_input:            ds.l 1
v12a_isp_output:           ds.l 1
; N79J: real ISP stage (decoder -> scheduler -> ISP -> renderer) state.
n79j_isp_handle:           ds.l 1
n79j_isp_input:            ds.l 1
n79j_isp_output:           ds.l 1
n79j_out_buf_num:          ds.l 1
n79j_out_buf_size:         ds.l 1
n79j_out_variant:          ds.l 1
n79j_out_w:                ds.l 1
n79j_out_h:                ds.l 1
n79j_out_crop_x:           ds.l 1
n79j_out_crop_y:           ds.l 1
n79j_out_crop_w:           ds.l 1
n79j_out_crop_h:           ds.l 1
n79j_out_fps_num:          ds.l 1
n79j_out_fps_den:          ds.l 1
n79j_out_par_num:          ds.l 1
n79j_out_par_den:          ds.l 1
n79j_out_colorspace:       ds.l 1
n79j_save_dec_handle:      ds.l 1
n79j_save_dec_output:      ds.l 1
v12a_dec_buf_num:          ds.l 1
v12a_dec_buf_size:         ds.l 1
v12a_dec_w:                ds.l 1
v12a_dec_h:                ds.l 1
v12a_dec_crop_x:           ds.l 1
v12a_dec_crop_y:           ds.l 1
v12a_dec_crop_w:           ds.l 1
v12a_dec_crop_h:           ds.l 1
v12a_dec_fps_num:          ds.l 1
v12a_dec_fps_den:          ds.l 1
v12a_dec_par_num:          ds.l 1
v12a_dec_par_den:          ds.l 1
v12a_dec_colorspace:       ds.l 1
v12c_dec_variant:         ds.l 1
v12c_local_set_active:    ds.l 1
v12a_local_get_active:    ds.l 1
v12a_target_w:             ds.l 1
v12a_target_h:             ds.l 1
v12a_target_aw:            ds.l 1
v12a_target_ah:            ds.l 1
v12a_create_size:          ds.l 1
v12a_create_status:        ds.l 1
v12a_create_hstatus:       ds.l 1
v12a_create_type:          ds.l 1
v12a_create_context_rx:    ds.l 1
v12a_connect_status:       ds.l 1
v12a_connect_header_status: ds.l 1   ; VPv128 MMAL header status separate from action status
v12a_connect_rx_size:      ds.l 1
v12a_connect_context:      ds.l 1    ; VPv127 unique context for PORT_ACTION CONNECT
v12a_req_status:           ds.l 1
v12a_req_rx_size:          ds.l 1
v12a_saved_input_handle:   ds.l 1
v12f_local_port:           ds.l 1    ; 0 first MMAL service, 1 restart service
v12f_local_bits:           ds.l 1    ; 0 or $00001000 in VCHIQ source field
hdmi_v40o_renderer_handle: ds.l 1
hdmi_v40o_drain_done:      ds.l 1
hdmi_v40o_displayregion_ok: ds.l 1
hdmi_v40o_param_status:     ds.l 1
hdmi_v40o_param_rx_size:    ds.l 1
hdmi_v40o_wb_fb_cpu:       ds.l 1
hdmi_v40o_wb_pitch:        ds.l 1
hdmi_v40o_wb_width:        ds.l 1
hdmi_v40o_wb_height:       ds.l 1
hdmi_v40o_wb_control:      ds.l 1
hdmi_v40o_wb_valid:        ds.l 1
hdmi_v40o_rtg_frames:      ds.l 1

        section code,code

; --------------------------------------------------------------------
; V12A - slot-safe synchronous RX helper.
; The V10P setup stayed inside MASTER slot 2. The extra ISP replies can
; cross the 4-KiB boundary, where VideoCore inserts a PADDING record and
; continues in MASTER_QUEUE[(rx_pos>>12)&63]. Keep the already proven
; TEST26C/TEST33 mapping and recycle semantics for these setup replies.
; --------------------------------------------------------------------
v12a_rx_advance_stride:
        movem.l d1-d3,-(sp)
        move.l  port_rx_pos,d1
        move.l  d1,d2
        add.l   d0,d2
        move.l  d2,port_rx_pos
        move.l  d1,d3
        and.l   #$fffff000,d3
        and.l   #$fffff000,d2
        cmp.l   d3,d2
        beq.s   v12a_rx_advance_ok
        move.l  d1,d0
        bsr     h31s_recycle_rx_slot
        tst.l   d0
        bne.s   v12a_rx_advance_fail
v12a_rx_advance_ok:
        moveq   #0,d0
        movem.l (sp)+,d1-d3
        rts
v12a_rx_advance_fail:
        moveq   #1,d0
        movem.l (sp)+,d1-d3
        rts

v12a_rx_consume_payload:
        add.l   #15,d0
        and.l   #$fffffff8,d0
        bra.w   v12a_rx_advance_stride

; Return A2 at the next non-PADDING MASTER record. D0=0 OK, 1 failure.
v12a_rx_map_data:
        movem.l d1-d4/a0-a1,-(sp)
v12a_rx_map_again:
        bsr     h26a_map_rx_current
        tst.l   d0
        bne.s   v12a_rx_map_fail
        move.l  a2,a0
        bsr     load_le32
        tst.l   d0
        bne.s   v12a_rx_map_ok
        ; PADDING must consume exactly the remainder of this 4-KiB slot.
        lea     4(a2),a0
        bsr     load_le32
        add.l   #15,d0
        and.l   #$fffffff8,d0
        move.l  d0,d4
        move.l  port_rx_pos,d1
        and.l   #$00000fff,d1
        move.l  #SLOT_SIZE,d2
        sub.l   d1,d2
        cmp.l   d2,d4
        bne.s   v12a_rx_map_fail
        move.l  d4,d0
        bsr     v12a_rx_advance_stride
        tst.l   d0
        bne.s   v12a_rx_map_fail
        bra.s   v12a_rx_map_again
v12a_rx_map_ok:
        moveq   #0,d0
        movem.l (sp)+,d1-d4/a0-a1
        rts
v12a_rx_map_fail:
        moveq   #1,d0
        movem.l (sp)+,d1-d4/a0-a1
        rts

; Create ril.isp on the already open local-0 MMAL service.
; Entry/exit shared slot RAM CPU-owned. D0=0 success, 1 failure.
v12a_create_isp:
        movem.l d1-d7/a0-a3,-(sp)
        ; request is 168-byte VCHIQ stride
        ; V12G restart: map absolute TX position through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_ispcreate_tx_legacy
        move.l  #168,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v12a_create_fail
        bra.s   v12g_ispcreate_tx_ready
v12g_ispcreate_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_ispcreate_tx_ready:

        move.l  a2,a0
        moveq   #41,d7
v12a_create_clear:
        clr.l   (a0)+
        dbra    d7,v12a_create_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #160,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_COMPONENT_CREATE,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$12A00001,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #$12A1A1A1,d0
        jsr     store_le32
        lea     36(a2),a0
        cmpi.l  #3,v41_display_style
        bne.s   v41b_create_name_isp
        lea     v41b_renderer_name,a1
        moveq   #16,d7               ; "ril.video_render" + NUL = 17 bytes
        bra.s   v12a_create_name
v41b_create_name_isp:
        lea     v12a_isp_name,a1
        moveq   #7,d7                ; "ril.isp" + terminating NUL = 8 bytes
v12a_create_name:
        move.b  (a1)+,(a0)+
        dbra    d7,v12a_create_name

        add.l   #168,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   v12a_create_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v12a_create_wait_setup:
        move.l  #POLL_COUNT,d7
v12a_create_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   v12a_create_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   v12a_create_wait
        jsr     dma_post_all
        bra.w   v12a_create_fail
v12a_create_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   v12a_create_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,d5
        and.l   #$ff000000,d5
        cmp.l   #VCHIQ_MSG_DATA,d5
        bne.w   v12a_create_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_size
        cmp.l   #44,d0
        bcs.w   v12a_create_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   v12a_create_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_type
        cmp.l   #MMAL_COMPONENT_CREATE,d0
        bne.w   v12a_create_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_context_rx
        cmp.l   #$12A00001,d0
        bne.w   v12a_create_fail_consume
        lea     24(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_hstatus
        tst.l   d0
        bne.w   v12a_create_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_status
        tst.l   d0
        bne.w   v12a_create_fail_consume
        lea     36(a2),a0
        jsr     load_le32
        move.l  d0,v12a_isp_handle
        tst.l   d0
        beq.w   v12a_create_fail_consume
        cmpi.l  #3,v41_display_style
        bne.s   v41b_create_handle_saved
        move.l  d0,hdmi_v40o_renderer_handle
v41b_create_handle_saved:

        move.l  v12a_create_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   v12a_create_fail
        lea     msg_v12a_isp_created,a1
        move.l  #msg_v12a_isp_created_end-msg_v12a_isp_created,d3
        jsr     print
        move.l  v12a_isp_handle,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d0
        bra.s   v12a_create_done
v12a_create_fail_consume:
        move.l  v12a_create_size,d0
        jsr     v12a_rx_consume_payload
v12a_create_fail:
        lea     msg_v12a_isp_create_fail,a1
        move.l  #msg_v12a_isp_create_fail_end-msg_v12a_isp_create_fail,d3
        jsr     print
        move.l  v12a_create_status,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0
v12a_create_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Connect decoder output -> ISP input using worker PORT_ACTION CONNECT.
v12a_connect_ports:
        movem.l d1-d7/a0-a3,-(sp)
        ; VPv127: CONNECT is a synchronous MMAL transaction.  Do not assume
        ; that the next RX record belongs to this request: the first tunnel
        ; may emit an asynchronous MMAL event before the second CONNECT reply.
        clr.l   v12a_connect_status
        clr.l   v12a_connect_header_status
        clr.l   v12a_connect_rx_size
        jsr     vpv30_alloc_context
        move.l  d0,v12a_connect_context
        ; V12G restart: map absolute TX position through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_connect_tx_legacy
        move.l  #112,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v12a_connect_fail
        bra.s   v12g_connect_tx_ready
v12g_connect_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_connect_tx_ready:
        move.l  a2,a0
        moveq   #27,d7
v12a_connect_clear:
        clr.l   (a0)+
        dbra    d7,v12a_connect_clear
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #100,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_ACTION,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  v12a_connect_context,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  v12a_decoder_handle,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  v12a_decoder_output,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  #MMAL_PORT_ACTION_CONNECT,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  v12a_isp_handle,d0
        jsr     store_le32
        lea     48(a2),a0
        move.l  v12a_isp_input,d0
        jsr     store_le32

        add.l   #112,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   v12a_connect_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v12a_connect_wait_setup:
        ; VPv127: wait for the exact PORT_ACTION + context pair.  The shared
        ; dispatcher consumes unrelated pre-stream control/event records and
        ; leaves the matching reply current and CPU-owned.
        move.l  #MMAL_PORT_ACTION,vpv30_expect_type
        move.l  v12a_connect_context,vpv30_expect_context
        jsr     vpv30_wait_matching
        tst.l   d0
        bne.w   v12a_connect_fail
v12a_connect_have:
        ; vpv30_wait_matching already mapped the exact matching RX record.
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,v12a_connect_rx_size
        cmp.l   #28,d0
        bcs.w   v12a_connect_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   v12a_connect_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.w   v12a_connect_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   v12a_connect_context,d0
        bne.w   v12a_connect_fail_consume
        lea     24(a2),a0
        jsr     load_le32
        move.l  d0,v12a_connect_header_status
        tst.l   d0
        bne.w   v12a_connect_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,v12a_connect_status
        tst.l   d0
        bne.w   v12a_connect_fail_consume
        move.l  v12a_connect_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   v12a_connect_fail
        lea     msg_v12a_connected,a1
        move.l  #msg_v12a_connected_end-msg_v12a_connected,d3
        jsr     print
        moveq   #0,d0
        bra.s   v12a_connect_done
v12a_connect_fail_consume:
        move.l  v12a_connect_rx_size,d0
        jsr     v12a_rx_consume_payload
v12a_connect_fail:
        lea     msg_v12a_connect_fail,a1
        move.l  #msg_v12a_connect_fail_end-msg_v12a_connect_fail,d3
        jsr     print
        move.l  v12a_connect_status,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_vpv128_connect_diag,a1
        move.l  #msg_vpv128_connect_diag_end-msg_vpv128_connect_diag,d3
        jsr     print
        move.l  v12a_decoder_handle,d0
        jsr     print_hex32
        lea     msg_vpv128_connect_diag_sep,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_decoder_output,d0
        jsr     print_hex32
        lea     msg_vpv128_connect_diag_sep,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_isp_handle,d0
        jsr     print_hex32
        lea     msg_vpv128_connect_diag_sep,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_isp_input,d0
        jsr     print_hex32
        lea     msg_vpv128_connect_diag_sep,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_connect_rx_size,d0
        jsr     print_hex32
        lea     msg_vpv128_connect_diag_sep,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_connect_header_status,d0
        jsr     print_hex32
        lea     msg_vpv128_connect_diag_sep,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_connect_status,d0
        jsr     print_hex32
        lea     msg_vpv128_connect_diag_sep,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_connect_context,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0
v12a_connect_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; HDMI_v41L HVS diagnostic + controlled restore.
; VideoCore.card itself writes the active HVS display-list word index at
; $F2400024. v05 captures that little-endian offset before video_render is
; created. Only after renderer teardown, MMAL service close and the proven
; 0.5 s service-close stabilization does v05 wait for a raster-frame wrap and
; write EXACTLY that saved value back. No display-list RAM is modified.
hdmi_v40o_log_hvs_all:
        movem.l d0-d3/a0-a1,-(sp)
        lea     msg_hdmi_v40o_hvs_all,a1
        move.l  #msg_hdmi_v40o_hvs_all_end-msg_hdmi_v40o_hvs_all,d3
        jsr     print
        move.l  #HDMI_V18_HVS_DLIST0_PTR,a0
        jsr     load_le32
        jsr     print_hex32
        lea     msg_hdmi_v40o_hvs_sep,a1
        move.l  #msg_hdmi_v40o_hvs_sep_end-msg_hdmi_v40o_hvs_sep,d3
        jsr     print
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        jsr     print_hex32
        lea     msg_hdmi_v40o_hvs_sep,a1
        move.l  #msg_hdmi_v40o_hvs_sep_end-msg_hdmi_v40o_hvs_sep,d3
        jsr     print
        move.l  #HDMI_V18_HVS_DLIST2_PTR,a0
        jsr     load_le32
        jsr     print_hex32
        jsr     newline
        movem.l (sp)+,d0-d3/a0-a1
        rts

hdmi_v40o_log_hvs_ptr:
        movem.l d0-d3/a0-a1,-(sp)
        lea     msg_hdmi_v40o_hvs_value,a1
        move.l  #msg_hdmi_v40o_hvs_value_end-msg_hdmi_v40o_hvs_value,d3
        jsr     print
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,hdmi_v40o_hvs_last
        jsr     print_hex32
        jsr     newline
        movem.l (sp)+,d0-d3/a0-a1
        rts

; HDMI_v41L: Dump 32 HVS DWORDs from active-list word offset D0. READ ONLY.
hdmi_v40o_dump_dlist_at:
        movem.l d0-d7/a0-a2,-(sp)
        move.l  d0,d6
        lea     msg_hdmi_v40o_dump_offset,a1
        move.l  #msg_hdmi_v40o_dump_offset_end-msg_hdmi_v40o_dump_offset,d3
        jsr     print
        move.l  d6,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d7
hdmi_v40o_dump_row:
        lea     msg_hdmi_v40o_dump_row,a1
        move.l  #msg_hdmi_v40o_dump_row_end-msg_hdmi_v40o_dump_row,d3
        jsr     print
        move.l  d7,d0
        jsr     print_hex32
        lea     msg_hdmi_v40o_dump_colon,a1
        move.l  #msg_hdmi_v40o_dump_colon_end-msg_hdmi_v40o_dump_colon,d3
        jsr     print
        moveq   #0,d5
hdmi_v40o_dump_word:
        move.l  #HDMI_V14_HVS_DLIST_BASE,a0
        move.l  d6,d0
        add.l   d7,d0
        add.l   d5,d0
        lsl.l   #2,d0
        adda.l  d0,a0
        jsr     load_le32
        jsr     print_hex32
        lea     msg_hdmi_v40o_space,a1
        moveq   #1,d3
        jsr     print
        addq.l  #1,d5
        cmpi.l  #4,d5
        bcs.s   hdmi_v40o_dump_word
        jsr     newline
        addq.l  #4,d7
        cmpi.l  #HDMI_V14_DUMP_WORDS,d7
        bcs.s   hdmi_v40o_dump_row
        movem.l (sp)+,d0-d7/a0-a2
        rts

; Capture up to two distinct non-Workbench active HVS list offsets in playback.
hdmi_v40o_probe_video_dlist:
        movem.l d0-d3/a0-a1,-(sp)
        move.l  hdmi_v40o_dump_count,d0
        cmpi.l  #2,d0
        bcc.s   hdmi_v40o_probe_done
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,d2
        cmp.l   hdmi_v40o_hvs_saved,d2
        beq.s   hdmi_v40o_probe_done
        tst.l   hdmi_v40o_dump_count
        bne.s   hdmi_v40o_probe_second
        move.l  d2,hdmi_v40o_dump_first_offset
        move.l  #1,hdmi_v40o_dump_count
        lea     msg_hdmi_v40o_dump_video1,a1
        move.l  #msg_hdmi_v40o_dump_video1_end-msg_hdmi_v40o_dump_video1,d3
        jsr     print
        move.l  d2,d0
        jsr     hdmi_v40o_dump_dlist_at
        bra.s   hdmi_v40o_probe_done
hdmi_v40o_probe_second:
        cmp.l   hdmi_v40o_dump_first_offset,d2
        beq.s   hdmi_v40o_probe_done
        move.l  d2,hdmi_v40o_dump_second_offset
        move.l  #2,hdmi_v40o_dump_count
        lea     msg_hdmi_v40o_dump_video2,a1
        move.l  #msg_hdmi_v40o_dump_video2_end-msg_hdmi_v40o_dump_video2,d3
        jsr     print
        move.l  d2,d0
        jsr     hdmi_v40o_dump_dlist_at
hdmi_v40o_probe_done:
        movem.l (sp)+,d0-d3/a0-a1
        rts



; --------------------------------------------------------------------
; HDMI_v41L LIVE HVS-VBLANK MERGE
;
; v13 proved that the exact original Workbench main plane + exact MMAL H264
; element + original WB tail/mouse form a correct HVS display list when MMAL
; is no longer changing the channel pointer. v15 performs the same composition
; live, but only once per real HVS raster wrap. After the wrap it waits briefly
; for ril.video_render to publish its new MMAL list, copies that stable H264
; element into the *inactive* shadow list, then switches the HVS channel to the
; completed shadow. Two independent shadow lists ($400/$460) alternate so the
; list currently scanned by HVS is never modified.
; --------------------------------------------------------------------

; D7 = source MMAL list index, D4 = destination shadow list index.
; Return D0 = 0 success, 1 invalid/transient source.
hdmi_v40o_build_live_merge:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d7,d5
        moveq   #0,d6
hdmi_v40o_live_find_h264:
        move.l  d5,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d3
        btst    #31,d3
        bne.w   hdmi_v40o_live_build_fail
        move.l  d3,d0
        andi.l  #$0000000f,d0
        cmpi.l  #HDMI_V14_HVS_FMT_H264,d0
        beq.s   hdmi_v40o_live_h264_found
        move.l  d3,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        beq.w   hdmi_v40o_live_build_fail
        add.l   d0,d5
        addq.l  #1,d6
        cmpi.l  #8,d6
        bcs.s   hdmi_v40o_live_find_h264
        bra.w   hdmi_v40o_live_build_fail

hdmi_v40o_live_h264_found:
        move.l  d3,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        move.l  d0,d6
        beq.w   hdmi_v40o_live_build_fail
        cmpi.l  #32,d6
        bhi.w   hdmi_v40o_live_build_fail

        ; Determine exact original WB main-plane length.
        move.l  hdmi_v40o_hvs_saved,d3
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        btst    #31,d2
        bne.w   hdmi_v40o_live_build_fail
        lsr.l   #8,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        andi.l  #$0000003f,d2
        beq.w   hdmi_v40o_live_build_fail
        cmpi.l  #32,d2
        bhi.w   hdmi_v40o_live_build_fail

        ; 1) exact original WB main plane.
        move.l  hdmi_v40o_hvs_saved,d3
        bsr     hdmi_v40o_static_copy_words

        ; 2) exact WB remainder (mouse etc.) BEFORE video.
        ; Hardware v13 showed that with WB -> H264 -> mouse, the cursor vanished
        ; inside the H264 rectangle. Putting the cursor element before H264 is
        ; the z-order experiment for v15: cursor must remain visible over video.
        move.l  hdmi_v40o_hvs_saved,d3
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        andi.l  #$0000003f,d2
        add.l   d2,d3
hdmi_v40o_live_copy_tail:
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        btst    #31,d2
        bne.s   hdmi_v40o_live_append_end
        move.l  d2,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        beq.w   hdmi_v40o_live_build_fail
        move.l  d0,d2
        bsr     hdmi_v40o_static_copy_words
        add.l   d2,d3
        bra.s   hdmi_v40o_live_copy_tail
hdmi_v40o_live_append_end:
        ; 3) append exact active MMAL H264 element LAST, then END.
        ; This reverses only mouse/video z-order relative to v14.
        move.l  d5,d3
        move.l  d6,d2
        bsr     hdmi_v40o_static_copy_words
        ; d1 still contains the original WB END marker.
        move.l  d4,d0
        bsr     hdmi_v40o_dlist_store_idx
        moveq   #0,d0
        bra.s   hdmi_v40o_live_build_out
hdmi_v40o_live_build_fail:
        moveq   #1,d0
hdmi_v40o_live_build_out:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Called very frequently from the existing passive pacing loops. It only does
; real work once when the HVS channel-1 line counter wraps.
hdmi_v40o_live_merge_poll:
        rts

; --------------------------------------------------------------------
; HDMI_v41L STATIC POST-EOS MERGE PROOF
;
; During live playback v15 performs NO HVS list or active-pointer writes.
; After input EOS + the established 0.5 s renderer drain, this routine takes
; the currently displayed final MMAL H264 element, copies it together with
; the *original* VideoCore.card Workbench main plane and WB tail (mouse/END)
; into an independent list at DWORD $400, activates that list once at HVS
; vblank, holds it for 3 seconds, then returns to the original final MMAL
; list before normal renderer cleanup.
;
; This deliberately freezes the final video frame.  The sole question is:
; can original WB + original H264 + original mouse coexist stably when no
; firmware frame-list writer is racing us?
; --------------------------------------------------------------------

; Copy D2 DWORDs from source index D3 to destination index D4.
hdmi_v40o_static_copy_words:
        movem.l d0-d3/a0,-(sp)
        tst.l   d2
        beq.s   hdmi_v40o_static_copy_done
hdmi_v40o_static_copy_loop:
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,-(sp)
        move.l  d4,d0
        move.l  (sp)+,d1
        bsr     hdmi_v40o_dlist_store_idx
        addq.l  #1,d3
        addq.l  #1,d4
        subq.l  #1,d2
        bne.s   hdmi_v40o_static_copy_loop
hdmi_v40o_static_copy_done:
        movem.l (sp)+,d0-d3/a0
        rts

; Wait for HVS channel-1 raster wrap. Read-only until caller writes pointer.
hdmi_v40o_wait_hvs_vblank:
        movem.l d0-d3/a0,-(sp)
        move.l  #HDMI_V14_HVS_DISPSTAT1,a0
        jsr     load_le32
        andi.l  #$00000fff,d0
        move.l  d0,d2
hdmi_v40o_hvs_vb_loop:
        move.l  #HDMI_V14_HVS_DISPSTAT1,a0
        jsr     load_le32
        andi.l  #$00000fff,d0
        cmp.l   d2,d0
        bcs.s   hdmi_v40o_hvs_vb_done
        move.l  d0,d2
        bra.s   hdmi_v40o_hvs_vb_loop
hdmi_v40o_hvs_vb_done:
        movem.l (sp)+,d0-d3/a0
        rts

hdmi_v40o_static_merge_test:
        movem.l d0-d7/a0-a3,-(sp)
        clr.l   hdmi_v40o_merge_count
        clr.l   hdmi_v40o_merge_retry

        ; Current final MMAL display list after EOS/drain.
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,d7
        move.l  d7,hdmi_v40o_merge_last_src
        cmp.l   hdmi_v40o_hvs_saved,d7
        beq.w   hdmi_v40o_static_fail
        cmpi.l  #$00000fff,d7
        bhi.w   hdmi_v40o_static_fail

        ; Find H264 element dynamically in final MMAL list.
        move.l  d7,d5
        moveq   #0,d6
hdmi_v40o_static_find_h264:
        move.l  d5,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d3
        btst    #31,d3
        bne.w   hdmi_v40o_static_fail
        move.l  d3,d0
        andi.l  #$0000000f,d0
        cmpi.l  #HDMI_V14_HVS_FMT_H264,d0
        beq.s   hdmi_v40o_static_h264_found
        move.l  d3,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        beq.w   hdmi_v40o_static_fail
        add.l   d0,d5
        addq.l  #1,d6
        cmpi.l  #8,d6
        bcs.s   hdmi_v40o_static_find_h264
        bra.w   hdmi_v40o_static_fail

hdmi_v40o_static_h264_found:
        move.l  d3,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        move.l  d0,d6                    ; H264 element DWORD count
        beq.w   hdmi_v40o_static_fail
        cmpi.l  #32,d6
        bhi.w   hdmi_v40o_static_fail

        ; Original Workbench main-plane size.
        move.l  hdmi_v40o_hvs_saved,d3
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        btst    #31,d2
        bne.w   hdmi_v40o_static_fail
        lsr.l   #8,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        andi.l  #$0000003f,d2
        beq.w   hdmi_v40o_static_fail
        cmpi.l  #32,d2
        bhi.w   hdmi_v40o_static_fail

        ; Destination = independent test list @ DWORD $400.
        move.l  #HDMI_V14_MERGE_DLIST,d4
        ; 1) exact original WB main plane.
        move.l  hdmi_v40o_hvs_saved,d3
        bsr     hdmi_v40o_static_copy_words

        ; 2) exact remainder of original WB list (mouse etc.) BEFORE H264.
        ; v13 hardware observation: old order WB -> H264 -> mouse put the
        ; cursor underneath video. v15 tests WB -> mouse -> H264.
        move.l  hdmi_v40o_hvs_saved,d3
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        andi.l  #$0000003f,d2
        add.l   d2,d3
hdmi_v40o_static_copy_wb_tail:
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        btst    #31,d2
        bne.s   hdmi_v40o_static_append_end
        move.l  d2,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        beq.w   hdmi_v40o_static_fail
        move.l  d0,d2
        move.l  d4,d0
        subi.l  #HDMI_V14_MERGE_DLIST,d0
        add.l   d2,d0
        cmpi.l  #HDMI_V14_MERGE_MAX_WORDS,d0
        bhi.w   hdmi_v40o_static_fail
        bsr     hdmi_v40o_static_copy_words
        add.l   d2,d3
        bra.s   hdmi_v40o_static_copy_wb_tail

hdmi_v40o_static_append_end:
        ; 3) append exact final MMAL H264 element LAST, then WB END marker.
        move.l  d5,d3
        move.l  d6,d2
        bsr     hdmi_v40o_static_copy_words
        ; d1 still contains WB END marker.
        move.l  d4,d0
        bsr     hdmi_v40o_dlist_store_idx

        lea     msg_hdmi_v40o_static_begin,a1
        move.l  #msg_hdmi_v40o_static_begin_end-msg_hdmi_v40o_static_begin,d3
        jsr     print
        move.l  d7,d0
        jsr     print_hex32
        lea     msg_hdmi_v40o_static_mid,a1
        move.l  #msg_hdmi_v40o_static_mid_end-msg_hdmi_v40o_static_mid,d3
        jsr     print
        move.l  d5,d0
        jsr     print_hex32
        jsr     newline

        ; Activate merged list ONCE after all video frames are drained.
        bsr     hdmi_v40o_wait_hvs_vblank
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        move.l  #HDMI_V14_MERGE_DLIST,d0
        jsr     store_le32
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        cmpi.l  #HDMI_V14_MERGE_DLIST,d0
        bne.w   hdmi_v40o_static_fail_restore
        move.l  #1,hdmi_v40o_merge_count

        lea     msg_hdmi_v40o_static_hold,a1
        move.l  #msg_hdmi_v40o_static_hold_end-msg_hdmi_v40o_static_hold,d3
        jsr     print

        ; 3 second observation window. No new decoder input is being fed.
        bsr     dma_pre_all
        move.l  a5,a6
        move.l  #150,d1
        jsr     Delay(a6)
        bsr     dma_post_all

        ; Did firmware leave our static list alone once frames had stopped?
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,d2
        lea     msg_hdmi_v40o_static_after,a1
        move.l  #msg_hdmi_v40o_static_after_end-msg_hdmi_v40o_static_after,d3
        jsr     print
        move.l  d2,d0
        jsr     print_hex32
        jsr     newline
        cmpi.l  #HDMI_V14_MERGE_DLIST,d2
        beq.s   hdmi_v40o_static_restore_source
        addq.l  #1,hdmi_v40o_merge_retry

hdmi_v40o_static_restore_source:
        ; Return to the final MMAL list before renderer teardown, preserving
        ; the already hardware-proven cleanup ordering.
        bsr     hdmi_v40o_wait_hvs_vblank
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        move.l  hdmi_v40o_merge_last_src,d0
        jsr     store_le32
        lea     msg_hdmi_v40o_static_restore,a1
        move.l  #msg_hdmi_v40o_static_restore_end-msg_hdmi_v40o_static_restore,d3
        jsr     print
        bra.s   hdmi_v40o_static_done

hdmi_v40o_static_fail_restore:
        addq.l  #1,hdmi_v40o_merge_retry
        ; Best effort restore to original final MMAL list.
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        move.l  hdmi_v40o_merge_last_src,d0
        jsr     store_le32
        bra.s   hdmi_v40o_static_fail_msg

hdmi_v40o_static_fail:
        addq.l  #1,hdmi_v40o_merge_retry
hdmi_v40o_static_fail_msg:
        lea     msg_hdmi_v40o_static_fail,a1
        move.l  #msg_hdmi_v40o_static_fail_end-msg_hdmi_v40o_static_fail,d3
        jsr     print
hdmi_v40o_static_done:
        movem.l (sp)+,d0-d7/a0-a3
        rts

; --------------------------------------------------------------------
; HDMI_v41L legacy v12 live-patch code retained but NOT CALLED in v15.
;
; v10 proved that EXPANDING MMAL's 8-DWORD background element into the
; 16-DWORD scaled Workbench element is unsafe: firmware continues rebuilding
; its H264 element at the original +8 position, so the two layouts overlap.
;
; v12 NEVER changes element offsets or list length.  It learns the two MMAL
; lists and, while one list is inactive, overwrites ONLY DWORDs +0..+7 with
; an 8-DWORD compact Workbench UNITY element.  The H264 element remains at
; MMAL's original +8 position and is never moved or copied.
;
; The current Workbench is scaled by VideoCore.card (1280x720 -> 1920x1080),
; which needs a 16-DWORD PPF element.  For this isolation test v12 converts
; it to a UNITY element using the same framebuffer address/pitch/pixel mode.
; Therefore Workbench is intentionally shown at its native source size at
; x=0,y=0.  If this is stable, later work can add clipping/scaling safely.
; --------------------------------------------------------------------

; D0 = dword index. D1 = host-order word loaded.
hdmi_v40o_dlist_load_idx:
        movem.l d0/a0,-(sp)
        move.l  #HDMI_V14_HVS_DLIST_BASE,a0
        lsl.l   #2,d0
        adda.l  d0,a0
        jsr     load_le32
        move.l  d0,d1
        movem.l (sp)+,d0/a0
        rts

; D0 = destination dword index, D1 = host-order word.
hdmi_v40o_dlist_store_idx:
        movem.l d0/a0,-(sp)
        move.l  #HDMI_V14_HVS_DLIST_BASE,a0
        lsl.l   #2,d0
        adda.l  d0,a0
        move.l  d1,d0
        jsr     store_le32
        movem.l (sp)+,d0/a0
        rts

; Build the Workbench fields that can be transplanted into MMAL's existing
; 8-DWORD UNITY background element WITHOUT changing its layout or length.
;
; v11 built a new element and therefore changed too many semantics at once.
; v12 preserves MMAL's own control/layout/scratch words and changes only:
;   CTL0 format + pixel-order bits
;   POS2 native source width/height
;   PTR0 framebuffer address
;   PITCH0 bytes/row
;
; hdmi_v40o_wb_bg_tmp layout used here:
;   +0 = WB format/order mask (CONTROL_FORMAT + CONTROL_PIXEL_ORDER)
;   +2 = WB native source POS2 width/height
;   +4 = WB framebuffer pointer
;   +6 = WB pitch
; Return D0=0 success, 1 unsupported.
hdmi_v40o_build_wb_bg:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  hdmi_v40o_hvs_saved,d7

        ; Validate saved VideoCore.card Workbench main element.
        move.l  d7,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d6
        btst    #30,d6
        beq.w   hdmi_v40o_wb_bg_fail
        move.l  d6,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        cmpi.l  #8,d0
        bcs.w   hdmi_v40o_wb_bg_fail
        cmpi.l  #32,d0
        bhi.w   hdmi_v40o_wb_bg_fail

        lea     hdmi_v40o_wb_bg_tmp,a2
        ; Clear temp area first (8 DWORDs).
        moveq   #0,d0
        moveq   #7,d1
hdmi_v40o_wb_tmp_clear:
        move.l  d0,(a2)+
        dbra    d1,hdmi_v40o_wb_tmp_clear
        lea     hdmi_v40o_wb_bg_tmp,a2

        ; Exact Workbench HVS pixel format + pixel order.
        move.l  d6,d1
        andi.l  #$0000600f,d1
        move.l  d1,(a2)

        ; Scaled WB source POS2 is saved WB +3. Keep only native H/W fields;
        ; alpha/scaler mode bits from the scaled element are not valid for
        ; MMAL's UNITY background slot.
        move.l  d7,d0
        addq.l  #3,d0
        bsr     hdmi_v40o_dlist_load_idx
        andi.l  #$0fff0fff,d1
        move.l  d1,8(a2)

        ; Workbench framebuffer bus pointer.
        move.l  d7,d0
        addq.l  #5,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,16(a2)

        ; Workbench pitch.
        move.l  d7,d0
        addq.l  #7,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,24(a2)

        moveq   #0,d0
        bra.s   hdmi_v40o_wb_bg_out
hdmi_v40o_wb_bg_fail:
        moveq   #1,d0
hdmi_v40o_wb_bg_out:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; D5 = inactive MMAL list start.
; Return D0: 1=patched, 0=already correct/no work, 2=transient/race.
hdmi_v40o_patch_inactive:
        movem.l d1-d7/a0-a3,-(sp)

        ; Never patch the list currently scanned by HVS.
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        cmp.l   d5,d0
        beq.w   hdmi_v40o_patch_retry

        ; Firmware H264 element must remain exactly at +8.
        move.l  d5,d0
        addq.l  #8,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        andi.l  #$0000000f,d2
        cmpi.l  #HDMI_V14_HVS_FMT_H264,d2
        bne.w   hdmi_v40o_patch_retry
        btst    #30,d1
        beq.w   hdmi_v40o_patch_retry

        ; MMAL first element must itself be VALID, exactly 8 DWORDs and UNITY.
        move.l  d5,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d6                    ; current MMAL CTL0
        btst    #30,d6
        beq.w   hdmi_v40o_patch_retry
        btst    #4,d6
        beq.w   hdmi_v40o_patch_retry
        move.l  d6,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        cmpi.l  #8,d0
        bne.w   hdmi_v40o_patch_retry

        bsr     hdmi_v40o_build_wb_bg
        tst.l   d0
        bne.w   hdmi_v40o_patch_retry
        lea     hdmi_v40o_wb_bg_tmp,a2

        ; Desired CTL0 = MMAL CTL0 with ONLY format/order replaced by WB.
        move.l  d6,d7
        andi.l  #$ffff9ff0,d7
        or.l    (a2),d7

        ; If all four stable fields are already ours, don't hammer firmware.
        move.l  d5,d0
        bsr     hdmi_v40o_dlist_load_idx
        cmp.l   d7,d1
        bne.s   hdmi_v40o_patch_needed
        move.l  d5,d0
        addq.l  #2,d0
        bsr     hdmi_v40o_dlist_load_idx
        cmp.l   8(a2),d1
        bne.s   hdmi_v40o_patch_needed
        move.l  d5,d0
        addq.l  #4,d0
        bsr     hdmi_v40o_dlist_load_idx
        cmp.l   16(a2),d1
        bne.s   hdmi_v40o_patch_needed
        move.l  d5,d0
        addq.l  #6,d0
        bsr     hdmi_v40o_dlist_load_idx
        cmp.l   24(a2),d1
        bne.s   hdmi_v40o_patch_needed
        moveq   #0,d0
        bra.w   hdmi_v40o_patch_out

hdmi_v40o_patch_needed:
        ; Final ownership check. Four DWORD stores only; scratch/context words
        ; and MMAL's eighth private word are deliberately untouched.
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        cmp.l   d5,d0
        beq.w   hdmi_v40o_patch_retry

        move.l  d7,d1
        move.l  d5,d0
        bsr     hdmi_v40o_dlist_store_idx
        move.l  8(a2),d1
        move.l  d5,d0
        addq.l  #2,d0
        bsr     hdmi_v40o_dlist_store_idx
        move.l  16(a2),d1
        move.l  d5,d0
        addq.l  #4,d0
        bsr     hdmi_v40o_dlist_store_idx
        move.l  24(a2),d1
        move.l  d5,d0
        addq.l  #6,d0
        bsr     hdmi_v40o_dlist_store_idx

        ; If firmware activated the list during those four stores, report a
        ; transient race; never touch the active-pointer register here.
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        cmp.l   d5,d0
        beq.s   hdmi_v40o_patch_retry

        move.l  d5,hdmi_v40o_last_patched
        moveq   #1,d0
        bra.s   hdmi_v40o_patch_out

hdmi_v40o_patch_retry:
        moveq   #2,d0
hdmi_v40o_patch_out:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Learn the two alternating MMAL lists. While one is active, patch only the
; other list's first eight background DWORDs. No element moves, no active
; pointer writes, no H264 data stores.
hdmi_v40o_merge_poll:
        movem.l d0-d7/a0-a3,-(sp)
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,d7
        cmp.l   hdmi_v40o_hvs_saved,d7
        beq.w   hdmi_v40o_merge_done
        cmpi.l  #$00000fff,d7
        bhi.w   hdmi_v40o_merge_bad

        ; Genuine MMAL list must have H264 exactly at +8 in v12.
        move.l  d7,d0
        addq.l  #8,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        andi.l  #$0000000f,d2
        cmpi.l  #HDMI_V14_HVS_FMT_H264,d2
        bne.w   hdmi_v40o_merge_done

        move.l  hdmi_v40o_slot_a,d0
        bne.s   hdmi_v40o_have_a
        move.l  d7,hdmi_v40o_slot_a
        bra.w   hdmi_v40o_merge_done
hdmi_v40o_have_a:
        cmp.l   d0,d7
        beq.s   hdmi_v40o_choose_inactive
        move.l  hdmi_v40o_slot_b,d1
        bne.s   hdmi_v40o_choose_inactive
        move.l  d7,hdmi_v40o_slot_b

hdmi_v40o_choose_inactive:
        move.l  hdmi_v40o_slot_b,d1
        beq.w   hdmi_v40o_merge_done
        move.l  hdmi_v40o_slot_a,d0
        cmp.l   d0,d7
        beq.s   hdmi_v40o_inactive_b
        cmp.l   d1,d7
        bne.w   hdmi_v40o_merge_done
        move.l  d0,d5
        bra.s   hdmi_v40o_do_patch
hdmi_v40o_inactive_b:
        move.l  d1,d5

hdmi_v40o_do_patch:
        bsr     hdmi_v40o_patch_inactive
        cmpi.l  #1,d0
        beq.s   hdmi_v40o_patch_counted
        cmpi.l  #2,d0
        bne.w   hdmi_v40o_maybe_report_slots
        addq.l  #1,hdmi_v40o_merge_retry
        cmpi.l  #1,hdmi_v40o_merge_retry
        bne.w   hdmi_v40o_maybe_report_slots
        lea     msg_hdmi_v40o_merge_fail,a1
        move.l  #msg_hdmi_v40o_merge_fail_end-msg_hdmi_v40o_merge_fail,d3
        jsr     print
        bra.w   hdmi_v40o_maybe_report_slots
hdmi_v40o_patch_counted:
        addq.l  #1,hdmi_v40o_merge_count
        move.l  d5,hdmi_v40o_merge_last_src

hdmi_v40o_maybe_report_slots:
        move.l  hdmi_v40o_slots_reported,d0
        bne.s   hdmi_v40o_merge_done
        move.l  hdmi_v40o_slot_a,d0
        beq.s   hdmi_v40o_merge_done
        move.l  hdmi_v40o_slot_b,d1
        beq.s   hdmi_v40o_merge_done
        move.l  #1,hdmi_v40o_slots_reported
        lea     msg_hdmi_v40o_merge_first,a1
        move.l  #msg_hdmi_v40o_merge_first_end-msg_hdmi_v40o_merge_first,d3
        jsr     print
        lea     msg_hdmi_v40o_merge_src,a1
        move.l  #msg_hdmi_v40o_merge_src_end-msg_hdmi_v40o_merge_src,d3
        jsr     print
        move.l  hdmi_v40o_slot_a,d0
        jsr     print_hex32
        lea     msg_hdmi_v40o_merge_rb,a1
        move.l  #msg_hdmi_v40o_merge_rb_end-msg_hdmi_v40o_merge_rb,d3
        jsr     print
        move.l  hdmi_v40o_slot_b,d0
        jsr     print_hex32
        jsr     newline
        bra.s   hdmi_v40o_merge_done

hdmi_v40o_merge_bad:
        addq.l  #1,hdmi_v40o_merge_retry
hdmi_v40o_merge_done:
        movem.l (sp)+,d0-d7/a0-a3
        rts

; Wait for one complete PAL raster wrap using read-only custom-chip polling.
; No Exec interrupt server and no Copper/bitplane/DMA state is touched.
hdmi_v40o_wait_vblank:
        movem.l d0-d2,-(sp)
        jsr     v04_sample_raster
        move.l  d0,d1
hdmi_v40o_wait_vblank_loop:
        jsr     v04_sample_raster
        cmp.l   d1,d0
        bcs.s   hdmi_v40o_wait_vblank_done
        move.l  d0,d1
        bra.s   hdmi_v40o_wait_vblank_loop
hdmi_v40o_wait_vblank_done:
        movem.l (sp)+,d0-d2
        rts

; Restore exactly the HVS display-list offset that was active before
; ril.video_render existed. The MMIO register is little-endian from the 68k
; view, so use the same byte-swap helper as the diagnostic read.
hdmi_v40o_restore_hvs_ptr:
        movem.l d1-d3/a0-a1,-(sp)
        ; MintVID: only the renderer graphs save the list (fullscreen).  The
        ; P96 window graph has no renderer, so nothing was saved and writing
        ; the cleared value put 0 in the HVS list pointer: black screen after
        ; every window stream, with the Amiga still running.
        tst.l   hdmi_v40o_hvs_saved
        bne.s   hdmi_v40o_restore_hvs_have
        moveq   #0,d0
        movem.l (sp)+,d1-d3/a0-a1
        rts
hdmi_v40o_restore_hvs_have:
        lea     msg_hdmi_v40o_hvs_restore_begin,a1
        move.l  #msg_hdmi_v40o_hvs_restore_begin_end-msg_hdmi_v40o_hvs_restore_begin,d3
        jsr     print
        move.l  hdmi_v40o_hvs_saved,d0
        jsr     print_hex32
        jsr     newline
        bsr     hdmi_v40o_wait_vblank
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        move.l  hdmi_v40o_hvs_saved,d0
        jsr     store_le32
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,hdmi_v40o_hvs_last
        lea     msg_hdmi_v40o_hvs_restore_readback,a1
        move.l  #msg_hdmi_v40o_hvs_restore_readback_end-msg_hdmi_v40o_hvs_restore_readback,d3
        jsr     print
        move.l  hdmi_v40o_hvs_last,d0
        jsr     print_hex32
        jsr     newline
        move.l  hdmi_v40o_hvs_last,d0
        movem.l (sp)+,d1-d3/a0-a1
        rts

; HDMI_v41L: MMAL video_render display-region control with HVS restore.
; MMAL_DISPLAYREGION_T uses fullscreen TRUE and the native P96/Workbench area.
; The renderer may take over the HVS list while video is visible; after full
; MMAL teardown HDMI_v41L restores the exact VideoCore.card/Workbench HVS offset
; captured before renderer creation. Visible alpha is 255 | MMAL_DISPLAY_ALPHA_FLAGS_DISCARD_LOWER_LAYERS (bit 29).
; This asks VideoCore to discard lower display layers behind cinema video.
;
; set bits: NUM | FULLSCREEN | DEST_RECT | LAYER | ALPHA = 0x50B
; layer: 10, visible alpha: 0x200000FF, display number explicitly selected.
; Returns D0=0 success, D0=1 failure. Shared memory CPU-owned on return.
hdmi_v40o_set_displayregion:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   hdmi_v40o_param_status
        clr.l   hdmi_v40o_param_rx_size
        clr.l   n80_dr_word

        ; Worker payload is 32-byte prefix before param + 84-byte displayregion
        ; = 116 bytes. With 8-byte VCHIQ header, reserve/alignment stride = 128.
        tst.l   v12f_local_port
        beq.s   hdmi_v40o_param_tx_legacy
        move.l  #128,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   n80_dr1
        bra.s   hdmi_v40o_param_tx_ready
hdmi_v40o_param_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
hdmi_v40o_param_tx_ready:
        move.l  a2,a0
        moveq   #31,d7
hdmi_v40o_param_clear:
        clr.l   (a0)+
        dbra    d7,hdmi_v40o_param_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #116,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_PARAMETER_SET,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$12D30001,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  v12a_isp_handle,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  v12a_isp_input,d0
        jsr     store_le32

        ; MMAL_DISPLAYREGION_T begins at worker param offset +40.
        lea     40(a2),a0
        move.l  #MMAL_PARAMETER_DISPLAYREGION,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #84,d0
        jsr     store_le32
        lea     48(a2),a0
        move.l  #HDMI_V14_DISPLAY_SET,d0
        jsr     store_le32
        ; +52 display_num = 1, explicitly selected by DISPLAY_SET_NUM.
        lea     52(a2),a0
        move.l  #HDMI_V18_DISPLAY_NUM,d0
        jsr     v91_display_num          ; v96.91: CM4 -> 2 (HDMI0)
        jsr     store_le32
        lea     56(a2),a0
        moveq   #1,d0                   ; renderer owns full HDMI display region
        jsr     store_le32
        ; +60 transform = 0. dest_rect = complete current P96/Workbench screen.
        lea     64(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     68(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     72(a2),a0
        move.l  hdmi_v40o_wb_width,d0
        jsr     store_le32
        lea     76(a2),a0
        move.l  hdmi_v40o_wb_height,d0
        jsr     store_le32
        lea     112(a2),a0
        move.l  #HDMI_V14_LAYER,d0
        jsr     store_le32
        ; +116 copyprotect = 0, left cleared.
        lea     120(a2),a0
        moveq   #0,d0
        tst.l   v41b_renderer_visible
        beq.s   v41b_displayregion_alpha_ready
        move.l  #HDMI_V41K_CINEMA_ALPHA,d0 ; 255 + DISCARD_LOWER_LAYERS when visible
v41b_displayregion_alpha_ready:
        jsr     store_le32

        add.l   #128,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   hdmi_v40o_param_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
hdmi_v40o_param_wait_setup:
        ; N80: the cleanup budget, not 100 polls.  The reply can be slow
        ; while the VideoCore reconfigures the display; POLLS= in the
        ; trace says how long it took.
        move.l  #V10_CLEANUP_POLL_COUNT,d7
hdmi_v40o_param_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   hdmi_v40o_param_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   hdmi_v40o_param_wait
        jsr     dma_post_all
        bra.w   n80_dr2

hdmi_v40o_param_have:
        move.l  #V10_CLEANUP_POLL_COUNT,d0
        sub.l   d7,d0
        lea     n80_pfx_dr_polls,a1
        jsr     n15_log_hex32
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   n80_dr3
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,hdmi_v40o_param_rx_size
        cmp.l   #28,d0
        bcs.w   n80_dr4
        lea     8(a2),a0
        jsr     load_le32
        move.l  d0,n80_dr_word
        cmp.l   #MMAL_MAGIC,d0
        bne.w   n80_dr5
        lea     12(a2),a0
        jsr     load_le32
        move.l  d0,n80_dr_word
        cmp.l   #MMAL_PORT_PARAMETER_SET,d0
        bne.w   n80_dr6
        lea     20(a2),a0
        jsr     load_le32
        move.l  d0,n80_dr_word
        cmp.l   #$12D30001,d0
        bne.w   n80_dr7
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,hdmi_v40o_param_status
        move.l  hdmi_v40o_param_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   n80_dr8
        move.l  hdmi_v40o_param_status,d0
        tst.l   d0
        bne.w   n80_dr9
        move.l  #1,hdmi_v40o_displayregion_ok
        lea     msg_hdmi_v40o_displayregion_ok,a1
        move.l  #msg_hdmi_v40o_displayregion_ok_end-msg_hdmi_v40o_displayregion_ok,d3
        jsr     print
        moveq   #0,d0
        bra.s   hdmi_v40o_param_done

; N80: say why DISPLAYREGION failed (1 tx reserve, 2 no reply, 3 rx map,
; 4 short reply, 5 bad magic, 6 not PARAMETER_SET reply, 7 wrong context,
; 8 consume failed, 9 VideoCore status != 0).  WORD = the mismatching
; reply field for 5..7.
n80_dr1:
        moveq   #1,d0
        bra.s   n80_dr_note
n80_dr2:
        moveq   #2,d0
        bra.s   n80_dr_note
n80_dr3:
        moveq   #3,d0
        bra.s   n80_dr_note
n80_dr4:
        moveq   #4,d0
        bra.s   n80_dr_note
n80_dr8:
        moveq   #8,d0
        bra.s   n80_dr_note
n80_dr9:
        moveq   #9,d0
n80_dr_note:
        bsr     n80_dr_log
        bra.s   hdmi_v40o_param_fail
n80_dr5:
        moveq   #5,d0
        bra.s   n80_dr_note_consume
n80_dr6:
        moveq   #6,d0
        bra.s   n80_dr_note_consume
n80_dr7:
        moveq   #7,d0
n80_dr_note_consume:
        bsr     n80_dr_log
hdmi_v40o_param_fail_consume:
        move.l  hdmi_v40o_param_rx_size,d0
        jsr     v12a_rx_consume_payload
hdmi_v40o_param_fail:
        clr.l   hdmi_v40o_displayregion_ok
        lea     msg_hdmi_v40o_displayregion_warn,a1
        move.l  #msg_hdmi_v40o_displayregion_warn_end-msg_hdmi_v40o_displayregion_warn,d3
        jsr     print
        move.l  hdmi_v40o_param_status,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0
hdmi_v40o_param_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

n80_dr_log:
        movem.l d0-d1/a0-a1,-(sp)
        lea     n80_pfx_dr_reason,a1
        jsr     n15_log_hex32
        move.l  hdmi_v40o_param_rx_size,d0
        lea     n80_pfx_dr_size,a1
        jsr     n15_log_hex32
        move.l  n80_dr_word,d0
        lea     n80_pfx_dr_word,a1
        jsr     n15_log_hex32
        move.l  hdmi_v40o_param_status,d0
        lea     n80_pfx_dr_status,a1
        jsr     n15_log_hex32
        movem.l (sp)+,d0-d1/a0-a1
        rts

; Apply buffer requirements to the connected ISP input. This mirrors
; mmal_vc_port_enable(): a connected output first sends
; MMAL_WORKER_PORT_ACTION_SET_REQUIREMENTS to the peer input, then enables
; the output. Current port_* globals must describe ISP INPUT 0.
v12a_set_isp_requirements:
        movem.l d1-d7/a0-a3,-(sp)
        ; 100-byte MMAL payload + 8-byte VCHIQ header -> 112-byte stride.
        ; V12G restart: map absolute TX position through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_req_tx_legacy
        move.l  #112,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v12a_req_fail
        bra.s   v12g_req_tx_ready
v12g_req_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_req_tx_ready:
        move.l  a2,a0
        moveq   #27,d7
v12a_req_clear:
        clr.l   (a0)+
        dbra    d7,v12a_req_clear
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32
        lea     4(a2),a0
        move.l  #100,d0
        bsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_ACTION,d0
        bsr     store_le32
        lea     20(a2),a0
        move.l  #$12A60001,d0
        bsr     store_le32
        lea     32(a2),a0
        move.l  v12a_isp_handle,d0
        bsr     store_le32
        lea     36(a2),a0
        move.l  v12a_isp_input,d0
        bsr     store_le32
        lea     40(a2),a0
        move.l  #MMAL_PORT_ACTION_SET_REQUIREMENTS,d0
        bsr     store_le32
        ; struct mmal_port starts at offset 44.
        lea     52(a2),a0
        move.l  #MMAL_PORT_INPUT,d0
        bsr     store_le32
        lea     60(a2),a0
        move.l  port_enabled,d0
        bsr     store_le32
        lea     68(a2),a0
        move.l  port_buf_num_min,d0
        bsr     store_le32
        lea     72(a2),a0
        move.l  port_buf_size_min,d0
        bsr     store_le32
        lea     76(a2),a0
        move.l  port_buf_align,d0
        bsr     store_le32
        lea     80(a2),a0
        move.l  port_buf_num_rec,d0
        bsr     store_le32
        lea     84(a2),a0
        move.l  port_buf_size_rec,d0
        bsr     store_le32
        lea     88(a2),a0
        move.l  port_buf_num,d0
        bsr     store_le32
        lea     92(a2),a0
        move.l  port_buf_size,d0
        bsr     store_le32
        lea     100(a2),a0
        move.l  #$12A60001,d0
        bsr     store_le32
        lea     104(a2),a0
        move.l  port_caps,d0
        bsr     store_le32

        add.l   #112,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,d6
        bsr     dma_pre_all
        tst.l   d6
        beq.s   v12a_req_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v12a_req_wait_setup:
        move.l  #POLL_COUNT,d7
v12a_req_wait:
        bsr     short_delay
        bsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   v12a_req_have
        bsr     dma_pre_all
        subq.l  #1,d7
        bne.s   v12a_req_wait
        bsr     dma_post_all
        bra.w   v12a_req_fail
v12a_req_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   v12a_req_fail
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,v12a_req_rx_size
        cmp.l   #28,d0
        bcs.w   v12a_req_fail
        lea     8(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   v12a_req_fail_consume
        lea     12(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.w   v12a_req_fail_consume
        lea     20(a2),a0
        bsr     load_le32
        cmp.l   #$12A60001,d0
        bne.w   v12a_req_fail_consume
        lea     24(a2),a0
        bsr     load_le32
        tst.l   d0
        bne.w   v12a_req_fail_consume
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,v12a_req_status
        move.l  v12a_req_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   v12a_req_fail
        move.l  v12a_req_status,d0
        tst.l   d0
        bne.w   v12a_req_fail
        lea     msg_v12a_requirements_ok,a1
        move.l  #msg_v12a_requirements_ok_end-msg_v12a_requirements_ok,d3
        bsr     print
        moveq   #0,d0
        bra.s   v12a_req_done
v12a_req_fail_consume:
        move.l  v12a_req_rx_size,d0
        jsr     v12a_rx_consume_payload
v12a_req_fail:
        lea     msg_v12a_requirements_fail,a1
        move.l  #msg_v12a_requirements_fail_end-msg_v12a_requirements_fail,d3
        bsr     print
        move.l  v12a_req_status,d0
        bsr     print_hex32
        bsr     newline
        moveq   #1,d0
v12a_req_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Main graph setup. Returns with decoder in component_handle and ISP output in
; output_port_handle/output_component_handle. Host output geometry is small.
; ====================================================================
; N79P full-path router.  Library C mode with a 128-aligned decoder width
; (N79Q: aligned width % 64 == 0) uses the original direct N79 graph (decoder -> scheduler -> renderer);
; every other case uses the N79K ISP graph below.
; ====================================================================
n79p_setup_graph_router:
        clr.l   n83_upscale
        tst.l   bvp_library_mode
        beq.s   n79p_router_k
        tst.l   n82_force_isp              ; ISP82 test switch
        bne.s   n79p_router_k
        cmpi.l  #3,v41_display_style
        bne.s   n79p_router_k
        ; N80: without HDMI audio every width takes the direct graph. The
        ; scheduler-free ISP graph does not come up on a PiStorm 600 (the
        ; VideoCore stops answering), so N83's ISP upscale is skipped too.
        tst.l   n80_no_hdmi_audio
        bne.w   n80_router_direct
        ; N83: films smaller than 1280x720 in either direction: the HVS
        ; would have to upscale by an odd factor and then draws green
        ; 1-pixel grid lines (tested 26./27.10.2026: lines at 1.88-2.4x,
        ; clean at 1.0/1.13/1.5/3.0, any graph).  Such films go through
        ; the ISP, which upscales them to fit 1920x1080; the HVS then
        ; only shows 1:1 or downscales, which is always clean.
        cmpi.l  #-1,n84_isp_out          ; N84 test: no N83 upscale
        beq.w   n83_router_size_ok
        ; v96.88: limits = 1280x720, but never more than the screen (HDMI
        ; 1280x1024: Coachman, green lines when 1920x1080 was shrunk again)
        jsr     o2_read_display_size
        move.l  o2_disp_w,d0
        cmpi.l  #1280,d0
        bls.s   n88_router_w
        move.l  #1280,d0
n88_router_w:
        cmp.l   v6_src_visible_w,d0
        bhi.s   n83_router_up            ; film narrower than the limit
        move.l  o2_disp_h,d0
        cmpi.l  #720,d0
        bls.s   n88_router_h
        move.l  #720,d0
n88_router_h:
        cmp.l   v6_src_visible_h,d0
        bls.w   n83_router_size_ok
n83_router_up:
        ; N84: films much wider than 16:9 (more than 2 %, e.g. cinema
        ; format) are not upscaled for now - old N79J/direct path as P96W31.
        ; (N83 upscaled 720x404 to 1920x1076; the renderer then stretched
        ; 1076 -> 1080 lines in the HVS = green stripes, 28.10.2026.)
        movem.l d1-d2,-(sp)
        move.l  v6_src_visible_w,d0
        mulu.w  #1080,d0                 ; W*1080
        move.l  v6_src_visible_h,d1
        mulu.w  #1920,d1                 ; H*1920
        move.l  d1,d2
        divu.w  #50,d2
        andi.l  #$FFFF,d2
        add.l   d2,d1                    ; H*1920 * 1.02
        cmp.l   d1,d0
        movem.l (sp)+,d1-d2              ; (movem keeps the flags)
        bhi.s   n84_router_wide
        move.l  #1,n83_upscale
        bra.s   n79p_router_k
n84_router_wide:
        move.l  a1,-(sp)
        lea     n84_msg_wide,a1
        jsr     n12_log
        move.l  (sp)+,a1
n83_router_size_ok:
        ; N79Q aligned64 fix: use the SPS-derived aligned width (valid here,
        ; unlike the late/zero v12a_dec_crop_w) and a 64-pixel rule.
        move.l  v6_src_aligned_w,d0
        andi.l  #63,d0
        bne.s   n79p_router_k
n80_router_direct:
        jsr     n79p_direct_setup_graph
        bra.s   o1_router_after
n79p_router_k:
        jsr     v12a_setup_isp_graph
o1_router_after:
        ; O1: OSD test layer once the film graph stands (cinema only)
        tst.l   d0
        bne.s   o1_router_done
        tst.l   o1_req
        beq.s   o1_router_done
        cmpi.l  #3,v41_display_style
        bne.s   o1_router_done
        jsr     o1_setup                 ; keeps D0, failure only logged
o1_router_done:
        rts

; N79P: unchanged N79 direct graph setup (copy, labels prefixed n79p_d_).
n79p_direct_setup_graph:
        movem.l d1-d7/a0-a3,-(sp)
        ; VPv126: every fresh MMAL graph/service receives a fresh scheduler.
        ; Never carry VideoCore component handles across a service restart.
        clr.l   vpv117_sched_handle
        clr.l   vpv117_sched_inputs
        clr.l   vpv117_sched_outputs
        clr.l   vpv117_sched_clocks
        clr.l   vpv117_sched_input0
        clr.l   vpv117_sched_output0
        clr.l   vpv117_sched_clock0
        clr.l   vpv126_data_graph_ok
        clr.l   vpv166_c_sched_feedahead
        clr.l   vpv179_mkv_c_fast_active
        clr.l   vpv179_mkv_c_fast_fallbacks
        clr.l   vpv179_mkv_video_pts_valid
        clr.l   vpv179_mkv_video_pts_lo
        clr.l   vpv179_mkv_video_pts_hi
        clr.l   vpv179_mkv_pts_attached
        clr.l   vpv126_sched_clock_armed
        clr.l   vpv126_sched_component_enabled
        clr.l   vpv128_sched_started_early
        clr.l   vpv126_scheduler_feed_aus
        clr.l   vpv129_audio_master_gate_uses
        clr.l   vpv129_audio_master_start_publishes
        clr.l   vpv129_audio_master_start_misses
        clr.l   vpv130_stop_transport_polls
        clr.l   vpv130_stop_transport_logged
        clr.l   vpv130_stop_bulk_done_logged
        ; VPv131: scheduler-output PTS vs actual P96 presentation wall-clock.
        clr.l   vpv131_schedwall_started
        clr.l   vpv131_schedwall_frames
        clr.l   vpv131_schedwall_invalid
        clr.l   vpv131_schedwall_nonmono
        clr.l   vpv131_schedwall_first_pts
        clr.l   vpv131_schedwall_last_pts
        clr.l   vpv131_schedwall_first_wall
        clr.l   vpv131_schedwall_last_wall
        clr.l   vpv131_schedwall_wall_elapsed
        clr.l   vpv131_schedwall_pts_elapsed
        clr.l   vpv131_schedwall_last_drift
        clr.l   vpv131_schedwall_min_drift
        clr.l   vpv131_schedwall_max_drift
        clr.l   vpv131_schedwall_step_min
        clr.l   vpv131_schedwall_step_max
        clr.l   vpv134_pts_immediate_snapshots
        clr.l   vpv134_pts_deferred_snapshots
        clr.l   vpv134_pts_deferred_restores
        clr.l   vpv134_pts_scratch_mismatches
        ; VPv136: video pipeline stage timing.
        clr.l   vpv136_header_wall_now
        clr.l   vpv136_deferred_depth_max
        clr.l   vpv136_stage_started
        clr.l   vpv136_stage_frames
        clr.l   vpv136_stage_invalid
        clr.l   vpv136_stage_first_pts
        clr.l   vpv136_stage_first_header_wall
        clr.l   vpv136_stage_last_header_wall
        clr.l   vpv136_stage_header_elapsed
        clr.l   vpv136_stage_pts_elapsed
        clr.l   vpv136_stage_header_drift
        clr.l   vpv136_stage_header_drift_min
        clr.l   vpv136_stage_header_drift_max
        clr.l   vpv136_stage_h2b_last
        clr.l   vpv136_stage_h2b_min
        clr.l   vpv136_stage_h2b_max
        clr.l   vpv136_stage_b2p_last
        clr.l   vpv136_stage_b2p_min
        clr.l   vpv136_stage_b2p_max
        clr.l   vpv126_saved_isp_handle
        clr.l   vpv126_saved_isp_input
        clr.l   vpv126_saved_dec_handle
        clr.l   vpv126_saved_dec_output
        move.l  #1,v12a_local_get_active
        move.l  component_handle,v12a_decoder_handle
        move.l  input_port_handle,v12a_saved_input_handle
        move.l  output_port_handle,v12a_decoder_output

        ; Snapshot decoder output, deliberately WITHOUT the old 640x480 DMA cap.
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   n80_pd1
        move.l  port_last_handle,d0
        cmp.l   v12a_decoder_output,d0
        bne.w   n80_pd2
        move.l  port_fmt_type,d0
        cmp.l   #MMAL_ES_VIDEO,d0
        bne.w   n80_pd3
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_I420,d0
        bne.w   n80_pd4
        ; N16: snapshot firmware decoder OUTPUT requirements before OPQV.
        move.l  port_fmt_encoding,d0
        lea     n15_pfx_out_pre_enc,a1
        jsr     n15_log_hex32
        move.l  port_buf_num_min,d0
        lea     n15_pfx_out_pre_min_num,a1
        jsr     n15_log_hex32
        move.l  port_buf_num_rec,d0
        lea     n15_pfx_out_pre_rec_num,a1
        jsr     n15_log_hex32
        move.l  port_buf_num,d0
        lea     n15_pfx_out_pre_cur_num,a1
        jsr     n15_log_hex32
        move.l  port_buf_size_min,d0
        lea     n15_pfx_out_pre_min_size,a1
        jsr     n15_log_hex32
        move.l  port_buf_size_rec,d0
        lea     n15_pfx_out_pre_rec_size,a1
        jsr     n15_log_hex32
        move.l  port_buf_size,d0
        lea     n15_pfx_out_pre_cur_size,a1
        jsr     n15_log_hex32

        move.l  port_buf_num,v12a_dec_buf_num
        move.l  port_buf_size,v12a_dec_buf_size
        move.l  port_video_width,v12a_dec_w
        move.l  port_video_height,v12a_dec_h
        move.l  port_crop_x,v12a_dec_crop_x
        move.l  port_crop_y,v12a_dec_crop_y
        move.l  port_crop_width,v12a_dec_crop_w
        move.l  port_crop_height,v12a_dec_crop_h
        move.l  port_fps_num,v12a_dec_fps_num
        move.l  port_fps_den,v12a_dec_fps_den
        move.l  port_par_num,v12a_dec_par_num
        move.l  port_par_den,v12a_dec_par_den
        move.l  port_color_space,v12a_dec_colorspace

        ; HDMI_v41L: no size is changed while a movie is running.  The user
        ; chooses the fixed ISP preset in the Intuition window BEFORE the ISP
        ; graph is created.  Until then no target geometry is committed.
        move.l  port_buf_size,output_buf_size_saved
        move.l  port_video_width,output_width_saved
        move.l  port_video_height,output_height_saved
        move.l  port_crop_x,output_crop_x_saved
        move.l  port_crop_y,output_crop_y_saved
        move.l  port_crop_width,output_crop_w_saved
        move.l  port_crop_height,output_crop_h_saved
        clr.l   v32_fixed_mode

        ; HDMI_v41L: capture the live VideoCore.card/P96 framebuffer before
        ; any video component can touch HVS. The renderer-free path writes
        ; only into this normal Amiga/RTG framebuffer.
        cmpi.l  #203,v40j_cli_mode
        bne.s   n79p_d_vpv98_c_before_capture_done
        lea     msg_vpv98_c_graph_enter,a1
        move.l  #msg_vpv98_c_graph_enter_end-msg_vpv98_c_graph_enter,d3
        jsr     vpv21n_trace
n79p_d_vpv98_c_before_capture_done:
        jsr     hdmi_v40o_capture_wb_fb
        tst.l   d0
        bne.w   n80_pd5
        cmpi.l  #203,v40j_cli_mode
        bne.s   n79p_d_vpv98_c_capture_ok_done
        lea     msg_vpv98_c_capture_ok,a1
        move.l  #msg_vpv98_c_capture_ok_end-msg_vpv98_c_capture_ok,d3
        jsr     vpv21n_trace
n79p_d_vpv98_c_capture_ok_done:

        ; V41L C: choose cinema window style before the very first OpenWindow,
        ; so direct cinema does not flash the small normal P96 window first.
        cmpi.l  #202,v40j_cli_mode
        beq.s   n79p_d_n79p96_preopen_fullfront_style
        cmpi.l  #203,v40j_cli_mode
        bne.s   n79p_d_v41l_preopen_normal_style
        move.l  #3,v41_display_style
        bra.s   n79p_d_v41l_preopen_style_ready
n79p_d_n79p96_preopen_fullfront_style:
        move.l  #2,v41_display_style
        bra.s   n79p_d_v41l_preopen_style_ready
n79p_d_v41l_preopen_normal_style:
        clr.l   v41_display_style
n79p_d_v41l_preopen_style_ready:
        ; N65 isolation: berryvp.library has no Intuition movie/event window.
        ; Workbench itself remains open.  video_render still receives the exact
        ; VPr8 DISPLAYREGION (Layer 10, Alpha 0x200000FF) later in graph setup.
        ; N79P96 diagnostic: unlike normal N79, library mode needs the real
        ; borderless Intuition/P96 surface.  Other library display modes keep
        ; the original no-window behaviour.
        tst.l   bvp_library_mode
        beq.s   n79p_d_n79p96_open_movie_window
        cmpi.l  #202,v40j_cli_mode
        bne.s   n79p_d_vpv98_c_window_ok_done
n79p_d_n79p96_open_movie_window:
        jsr     hdmi_v40o_open_window
        tst.l   d0
        bne.w   n80_pd6
        cmpi.l  #203,v40j_cli_mode
        bne.s   n79p_d_vpv98_c_window_ok_done
        lea     msg_vpv98_c_window_ok,a1
        move.l  #msg_vpv98_c_window_ok_end-msg_vpv98_c_window_ok,d3
        jsr     vpv21n_trace
n79p_d_vpv98_c_window_ok_done:

        ; V40: select the fixed VideoCore-ISP size now, before decoder OUTPUT
        ; is switched to OPQV and before ril.isp exists.  This is the core
        ; safety difference from v25/v30: the graph never changes mid-stream.
        jsr     v32_wait_initial_mode
        tst.l   d0
        bne.w   n80_pd7
        cmpi.l  #203,v40j_cli_mode
        bne.s   n79p_d_vpv98_c_selector_ok_done
        lea     msg_vpv98_c_selector_ok,a1
        move.l  #msg_vpv98_c_selector_ok_end-msg_vpv98_c_selector_ok,d3
        jsr     vpv21n_trace
n79p_d_vpv98_c_selector_ok_done:

        lea     msg_v12a_target,a1
        move.l  #msg_v12a_target_end-msg_v12a_target,d3
        jsr     print
        move.l  v12a_dec_crop_w,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_dec_crop_h,d0
        jsr     print_hex32
        lea     msg_v12a_arrow,a1
        move.l  #msg_v12a_arrow_end-msg_v12a_arrow,d3
        jsr     print
        move.l  v12a_target_w,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_target_h,d0
        jsr     print_hex32
        jsr     newline

        ; V12D: keep the full 1080p frame inside VideoCore.  The V12A
        ; I420 tunnel still described each connected buffer as a 0x2FD000-byte
        ; 1080p surface.  With only 32 MiB VC memory this can exhaust the
        ; firmware heap as soon as the decoder allocates its reference frames.
        ; The MMAL decoder supports OPQV output, and ril.isp supports OPQV input.
        ; Commit OPQV first, re-read its small buffer requirements, then commit
        ; the firmware MINIMUM header count before making the tunnel.
        move.l  v12a_decoder_handle,component_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   n80_pd8
        move.l  port_last_handle,d0
        cmp.l   v12a_decoder_output,d0
        bne.w   n80_pd9
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_OPAQUE,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_extra
        move.l  port_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   n79p_d_v12b_dec_opaque_first_num_ok
        moveq   #2,d0
n79p_d_v12b_dec_opaque_first_num_ok:
        move.l  d0,port_buf_num
        ; First format commit may still carry the old I420 buffer_size.  No
        ; buffers are allocated yet; the following GET reveals OPQV minima.
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   n80_pd10

        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   n80_pd11
        move.l  port_last_handle,d0
        cmp.l   v12a_decoder_output,d0
        bne.w   n80_pd12
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_OPAQUE,d0
        bne.w   n80_pd13

        ; V12D: use the decoder's MINIMUM opaque header count, not the
        ; recommended count.  This firmware reports min=3, recommended=10 at
        ; 1080p.  The official MMAL decoder example likewise uses buffer_num_min.
        ; Keeping ten OPQV surfaces is a prime ENOSPC suspect with only 32 MiB
        ; VideoCore memory.  Never go below the firmware-declared minimum.
        move.l  port_buf_num_min,d0
        cmpi.l  #2,d0
        bcc.s   n79p_d_v12b_dec_num_two_ok
        moveq   #2,d0
n79p_d_v12b_dec_num_two_ok:
        move.l  d0,port_buf_num

        move.l  port_buf_size_min,d0
        cmp.l   port_buf_size_rec,d0
        bcc.s   n79p_d_v12b_dec_size_rec_ok
