        clr.l   vpv131_schedwall_last_pts
        clr.l   vpv131_schedwall_first_wall
        clr.l   vpv131_schedwall_last_wall
        clr.l   vpv131_schedwall_wall_elapsed
        clr.l   vpv131_schedwall_pts_elapsed
        clr.l   vpv131_schedwall_last_drift
        clr.l   vpv131_schedwall_min_drift
        clr.l   vpv131_schedwall_max_drift
        clr.l   vpv131_schedwall_step_min
        clr.l   vpv131_schedwall_step_max
        clr.l   vpv134_pts_immediate_snapshots
        clr.l   vpv134_pts_deferred_snapshots
        clr.l   vpv134_pts_deferred_restores
        clr.l   vpv134_pts_scratch_mismatches
        ; VPv136: video pipeline stage timing.
        clr.l   vpv136_header_wall_now
        clr.l   vpv136_deferred_depth_max
        clr.l   vpv136_stage_started
        clr.l   vpv136_stage_frames
        clr.l   vpv136_stage_invalid
        clr.l   vpv136_stage_first_pts
        clr.l   vpv136_stage_first_header_wall
        clr.l   vpv136_stage_last_header_wall
        clr.l   vpv136_stage_header_elapsed
        clr.l   vpv136_stage_pts_elapsed
        clr.l   vpv136_stage_header_drift
        clr.l   vpv136_stage_header_drift_min
        clr.l   vpv136_stage_header_drift_max
        clr.l   vpv136_stage_h2b_last
        clr.l   vpv136_stage_h2b_min
        clr.l   vpv136_stage_h2b_max
        clr.l   vpv136_stage_b2p_last
        clr.l   vpv136_stage_b2p_min
        clr.l   vpv136_stage_b2p_max
        clr.l   vpv126_saved_isp_handle
        clr.l   vpv126_saved_isp_input
        clr.l   vpv126_saved_dec_handle
        clr.l   vpv126_saved_dec_output
        move.l  #1,v12a_local_get_active
        move.l  component_handle,v12a_decoder_handle
        move.l  input_port_handle,v12a_saved_input_handle
        move.l  output_port_handle,v12a_decoder_output

        ; Snapshot decoder output, deliberately WITHOUT the old 640x480 DMA cap.
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,d0
        cmp.l   v12a_decoder_output,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_type,d0
        cmp.l   #MMAL_ES_VIDEO,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_I420,d0
        bne.w   v12a_setup_fail
        ; N16: snapshot firmware decoder OUTPUT requirements before OPQV.
        move.l  port_fmt_encoding,d0
        lea     n15_pfx_out_pre_enc,a1
        jsr     n15_log_hex32
        move.l  port_buf_num_min,d0
        lea     n15_pfx_out_pre_min_num,a1
        jsr     n15_log_hex32
        move.l  port_buf_num_rec,d0
        lea     n15_pfx_out_pre_rec_num,a1
        jsr     n15_log_hex32
        move.l  port_buf_num,d0
        lea     n15_pfx_out_pre_cur_num,a1
        jsr     n15_log_hex32
        move.l  port_buf_size_min,d0
        lea     n15_pfx_out_pre_min_size,a1
        jsr     n15_log_hex32
        move.l  port_buf_size_rec,d0
        lea     n15_pfx_out_pre_rec_size,a1
        jsr     n15_log_hex32
        move.l  port_buf_size,d0
        lea     n15_pfx_out_pre_cur_size,a1
        jsr     n15_log_hex32

        move.l  port_buf_num,v12a_dec_buf_num
        move.l  port_buf_size,v12a_dec_buf_size
        move.l  port_video_width,v12a_dec_w
        move.l  port_video_height,v12a_dec_h
        move.l  port_crop_x,v12a_dec_crop_x
        move.l  port_crop_y,v12a_dec_crop_y
        move.l  port_crop_width,v12a_dec_crop_w
        move.l  port_crop_height,v12a_dec_crop_h
        move.l  port_fps_num,v12a_dec_fps_num
        move.l  port_fps_den,v12a_dec_fps_den
        move.l  port_par_num,v12a_dec_par_num
        move.l  port_par_den,v12a_dec_par_den
        move.l  port_color_space,v12a_dec_colorspace

        ; HDMI_v41L: no size is changed while a movie is running.  The user
        ; chooses the fixed ISP preset in the Intuition window BEFORE the ISP
        ; graph is created.  Until then no target geometry is committed.
        move.l  port_buf_size,output_buf_size_saved
        move.l  port_video_width,output_width_saved
        move.l  port_video_height,output_height_saved
        move.l  port_crop_x,output_crop_x_saved
        move.l  port_crop_y,output_crop_y_saved
        move.l  port_crop_width,output_crop_w_saved
        move.l  port_crop_height,output_crop_h_saved
        clr.l   v32_fixed_mode

        ; HDMI_v41L: capture the live VideoCore.card/P96 framebuffer before
        ; any video component can touch HVS. The renderer-free path writes
        ; only into this normal Amiga/RTG framebuffer.
        cmpi.l  #203,v40j_cli_mode
        bne.s   vpv98_c_before_capture_done
        lea     msg_vpv98_c_graph_enter,a1
        move.l  #msg_vpv98_c_graph_enter_end-msg_vpv98_c_graph_enter,d3
        jsr     vpv21n_trace
vpv98_c_before_capture_done:
        jsr     hdmi_v40o_capture_wb_fb
        tst.l   d0
        bne.w   v12a_setup_fail
        cmpi.l  #203,v40j_cli_mode
        bne.s   vpv98_c_capture_ok_done
        lea     msg_vpv98_c_capture_ok,a1
        move.l  #msg_vpv98_c_capture_ok_end-msg_vpv98_c_capture_ok,d3
        jsr     vpv21n_trace
vpv98_c_capture_ok_done:

        ; V41L C: choose cinema window style before the very first OpenWindow,
        ; so direct cinema does not flash the small normal P96 window first.
        cmpi.l  #202,v40j_cli_mode
        beq.s   n79p96_preopen_fullfront_style
        cmpi.l  #203,v40j_cli_mode
        bne.s   v41l_preopen_normal_style
        move.l  #3,v41_display_style
        bra.s   v41l_preopen_style_ready
n79p96_preopen_fullfront_style:
        move.l  #2,v41_display_style
        bra.s   v41l_preopen_style_ready
v41l_preopen_normal_style:
        clr.l   v41_display_style
v41l_preopen_style_ready:
        ; N65 isolation: berryvp.library has no Intuition movie/event window.
        ; Workbench itself remains open.  video_render still receives the exact
        ; VPr8 DISPLAYREGION (Layer 10, Alpha 0x200000FF) later in graph setup.
        ; N79P96 diagnostic: unlike normal N79, library mode needs the real
        ; borderless Intuition/P96 surface.  Other library display modes keep
        ; the original no-window behaviour.
        tst.l   bvp_library_mode
        beq.s   n79p96_open_movie_window
        tst.l   bvp_p96_mode
        beq.s   vpv98_c_window_ok_done
n79p96_open_movie_window:
        jsr     hdmi_v40o_open_window
        tst.l   d0
        bne.w   v12a_setup_fail
        cmpi.l  #203,v40j_cli_mode
        bne.s   vpv98_c_window_ok_done
        lea     msg_vpv98_c_window_ok,a1
        move.l  #msg_vpv98_c_window_ok_end-msg_vpv98_c_window_ok,d3
        jsr     vpv21n_trace
vpv98_c_window_ok_done:

        ; V40: select the fixed VideoCore-ISP size now, before decoder OUTPUT
        ; is switched to OPQV and before ril.isp exists.  This is the core
        ; safety difference from v25/v30: the graph never changes mid-stream.
        jsr     v32_wait_initial_mode
        tst.l   d0
        bne.w   v12a_setup_fail
        cmpi.l  #203,v40j_cli_mode
        bne.s   vpv98_c_selector_ok_done
        lea     msg_vpv98_c_selector_ok,a1
        move.l  #msg_vpv98_c_selector_ok_end-msg_vpv98_c_selector_ok,d3
        jsr     vpv21n_trace
vpv98_c_selector_ok_done:

        lea     msg_v12a_target,a1
        move.l  #msg_v12a_target_end-msg_v12a_target,d3
        jsr     print
        move.l  v12a_dec_crop_w,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_dec_crop_h,d0
        jsr     print_hex32
        lea     msg_v12a_arrow,a1
        move.l  #msg_v12a_arrow_end-msg_v12a_arrow,d3
        jsr     print
        move.l  v12a_target_w,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_target_h,d0
        jsr     print_hex32
        jsr     newline

        ; V12D: keep the full 1080p frame inside VideoCore.  The V12A
        ; I420 tunnel still described each connected buffer as a 0x2FD000-byte
        ; 1080p surface.  With only 32 MiB VC memory this can exhaust the
        ; firmware heap as soon as the decoder allocates its reference frames.
        ; The MMAL decoder supports OPQV output, and ril.isp supports OPQV input.
        ; Commit OPQV first, re-read its small buffer requirements, then commit
        ; the firmware MINIMUM header count before making the tunnel.
        move.l  v12a_decoder_handle,component_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,d0
        cmp.l   v12a_decoder_output,d0
        bne.w   v12a_setup_fail
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_OPAQUE,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_extra
        move.l  port_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   v12b_dec_opaque_first_num_ok
        moveq   #2,d0
v12b_dec_opaque_first_num_ok:
        move.l  d0,port_buf_num
        ; First format commit may still carry the old I420 buffer_size.  No
        ; buffers are allocated yet; the following GET reveals OPQV minima.
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v12a_setup_fail

        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,d0
        cmp.l   v12a_decoder_output,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_OPAQUE,d0
        bne.w   v12a_setup_fail

        ; V12D: use the decoder's MINIMUM opaque header count, not the
        ; recommended count.  This firmware reports min=3, recommended=10 at
        ; 1080p.  The official MMAL decoder example likewise uses buffer_num_min.
        ; Keeping ten OPQV surfaces is a prime ENOSPC suspect with only 32 MiB
        ; VideoCore memory.  Never go below the firmware-declared minimum.
        move.l  port_buf_num_min,d0
        cmpi.l  #2,d0
        bcc.s   v12b_dec_num_two_ok
        moveq   #2,d0
v12b_dec_num_two_ok:
        move.l  d0,port_buf_num

        move.l  port_buf_size_min,d0
        cmp.l   port_buf_size_rec,d0
        bcc.s   v12b_dec_size_rec_ok
        move.l  port_buf_size_rec,d0
v12b_dec_size_rec_ok:
        tst.l   d0
        bne.s   v12b_dec_size_nonzero
        move.l  #128,d0
v12b_dec_size_nonzero:
        move.l  d0,port_buf_size
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v12a_setup_fail

        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_OPAQUE,d0
        bne.w   v12a_setup_fail

        ; N16: exact lazy-allocation contract that is live when first AU arrives.
        move.l  port_fmt_encoding,d0
        lea     n15_pfx_out_opq_enc,a1
        jsr     n15_log_hex32
        move.l  port_fmt_variant,d0
        lea     n15_pfx_out_opq_var,a1
        jsr     n15_log_hex32
        move.l  port_buf_num_min,d0
        lea     n15_pfx_out_opq_min_num,a1
        jsr     n15_log_hex32
        move.l  port_buf_num_rec,d0
        lea     n15_pfx_out_opq_rec_num,a1
        jsr     n15_log_hex32
        move.l  port_buf_num,d0
        lea     n15_pfx_out_opq_cur_num,a1
        jsr     n15_log_hex32
        move.l  port_buf_size_min,d0
        lea     n15_pfx_out_opq_min_size,a1
        jsr     n15_log_hex32
        move.l  port_buf_size_rec,d0
        lea     n15_pfx_out_opq_rec_size,a1
        jsr     n15_log_hex32
        move.l  port_buf_size,d0
        lea     n15_pfx_out_opq_cur_size,a1
        jsr     n15_log_hex32

        ; V12D: OPQV carries the underlying pixel format in variant.
        ; Hardware returned I420 ($30323449) here; ISP input must receive
        ; the same variant instead of zero or it rejects PORT_INFO_SET/EINVAL.
        move.l  port_fmt_variant,v12c_dec_variant
        move.l  port_buf_num,v12a_dec_buf_num
        move.l  port_buf_size,v12a_dec_buf_size
        lea     msg_v12b_decoder_opaque,a1
        move.l  #msg_v12b_decoder_opaque_end-msg_v12b_decoder_opaque,d3
        jsr     print
        move.l  v12a_dec_buf_num,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_dec_buf_size,d0
        jsr     print_hex32
        jsr     newline

        ; N79J: in library C mode the first component is a REAL ril.isp;
        ; v12a_create_isp picks the component name from v41_display_style.
        tst.l   bvp_library_mode
        beq.s   n79j_create_normal
        cmpi.l  #3,v41_display_style
        bne.s   n79j_create_normal
        clr.l   v41_display_style
        bsr     v12a_create_isp
        move.l  #3,v41_display_style
        tst.l   d0
        bne.w   v12a_setup_fail
        bra.s   v41b_setup_continue_isp
n79j_create_normal:
        bsr     v12a_create_isp
        tst.l   d0
        bne.w   v12a_setup_fail
        cmpi.l  #3,v41_display_style
        bne.s   v41b_setup_continue_isp
        lea     msg_vpv98_c_renderer_created,a1
        move.l  #msg_vpv98_c_renderer_created_end-msg_vpv98_c_renderer_created,d3
        jsr     vpv21n_trace
        jsr     v41b_setup_renderer_after_create
        tst.l   d0
        bne.w   v12a_setup_fail
        lea     msg_vpv98_c_renderer_ready,a1
        move.l  #msg_vpv98_c_renderer_ready_end-msg_vpv98_c_renderer_ready,d3
        jsr     vpv21n_trace
        moveq   #0,d0
        bra.w   v12a_setup_done
v41b_setup_continue_isp:

        ; ISP INPUT 0 = decoder full-size OPQV (opaque VideoCore frame handle).
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,v12a_isp_input
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_OPAQUE,port_fmt_encoding
        move.l  v12c_dec_variant,port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v12a_dec_w,port_video_width
        move.l  v12a_dec_h,port_video_height
        move.l  v12a_dec_crop_x,port_crop_x
        move.l  v12a_dec_crop_y,port_crop_y
        move.l  v12a_dec_crop_w,port_crop_width
        move.l  v12a_dec_crop_h,port_crop_height
        move.l  v12a_dec_fps_num,port_fps_num
        move.l  v12a_dec_fps_den,port_fps_den
        move.l  v12a_dec_par_num,port_par_num
        move.l  v12a_dec_par_den,port_par_den
        move.l  v12a_dec_colorspace,port_color_space
        move.l  v12a_dec_buf_size,port_buf_size
        move.l  v12a_dec_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   v12a_in_num_ok
        moveq   #2,d0
v12a_in_num_ok:
        move.l  d0,port_buf_num
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_input,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_OPAQUE,d0
        bne.w   v12a_setup_fail

        ; HDMI_v41L: ISP OUTPUT 0 = small aspect-correct BGR24. VideoCore does YUV->RGB.
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,v12a_isp_output
        ; N79J: library C mode -> ISP OUTPUT 0 = I420 with the width rounded
        ; up to 128 and the height to 16; crop = full widened width (N79K), decoder height.
        tst.l   bvp_library_mode
        beq.w   n79j_out_bgr24
        cmpi.l  #3,v41_display_style
        bne.w   n79j_out_bgr24
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_I420,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        tst.l   n83_upscale
        beq.s   n83_out_native
        bsr     n83_calc_out             ; N83: ISP upscales to fit 1920x1080
        bra.s   n83_out_sized
n83_out_native:
        move.l  v12a_dec_crop_w,d0
        add.l   #127,d0
        and.l   #$FFFFFF80,d0
        move.l  d0,port_video_width
        move.l  v12a_dec_crop_h,d0
        add.l   #15,d0
        and.l   #$FFFFFFF0,d0
        move.l  d0,port_video_height
        clr.l   port_crop_x
        clr.l   port_crop_y
        move.l  port_video_width,port_crop_width ; N79K: full 128-aligned width visible
        move.l  v12a_dec_crop_h,port_crop_height
n83_out_sized:
        move.l  v12a_dec_fps_num,port_fps_num
        move.l  v12a_dec_fps_den,port_fps_den
        moveq   #1,d0
        move.l  d0,port_par_num
        move.l  d0,port_par_den
        move.l  v12a_dec_colorspace,port_color_space
        moveq   #3,d0
        move.l  d0,port_buf_num
        move.l  port_video_width,d0
        move.l  port_video_height,d1
        mulu.w  d1,d0
        move.l  d0,d1
        lsr.l   #1,d1
        add.l   d1,d0                    ; I420: width*height*3/2
        move.l  d0,port_buf_size
        bra.w   n79j_out_set
n79j_out_bgr24:
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_BGR24,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v12a_target_aw,port_video_width
        move.l  v12a_target_ah,port_video_height
        clr.l   port_crop_x
        clr.l   port_crop_y
        move.l  v12a_target_w,port_crop_width
        move.l  v12a_target_h,port_crop_height
        move.l  v12a_dec_fps_num,port_fps_num
        move.l  v12a_dec_fps_den,port_fps_den
        moveq   #1,d0
        move.l  d0,port_par_num
        move.l  d0,port_par_den
        move.l  v12a_dec_colorspace,port_color_space
        moveq   #2,d0
        move.l  d0,port_buf_num
        move.l  v12a_target_aw,d0
        move.l  v12a_target_ah,d1
        mulu.w  d1,d0
        move.l  d0,d1
        add.l   d0,d0
        add.l   d1,d0                    ; BGR24: 3 bytes/pixel
        move.l  d0,port_buf_size
n79j_out_set:
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_output,d0
        bne.w   v12a_setup_fail
        tst.l   bvp_library_mode
        beq.w   n79j_check_bgr24
        cmpi.l  #3,v41_display_style
        bne.w   n79j_check_bgr24
        cmpi.l  #MMAL_ENCODING_I420,port_fmt_encoding
        bne.w   v12a_setup_fail
        move.l  v12a_isp_handle,n79j_isp_handle
        move.l  v12a_isp_input,n79j_isp_input
        move.l  v12a_isp_output,n79j_isp_output
        move.l  port_buf_num,n79j_out_buf_num
        move.l  port_buf_size,n79j_out_buf_size
        move.l  port_fmt_variant,n79j_out_variant
        move.l  port_video_width,n79j_out_w
        move.l  port_video_height,n79j_out_h
        move.l  port_crop_x,n79j_out_crop_x
        move.l  port_crop_y,n79j_out_crop_y
        move.l  port_crop_width,n79j_out_crop_w
        move.l  port_crop_height,n79j_out_crop_h
        move.l  port_fps_num,n79j_out_fps_num
        move.l  port_fps_den,n79j_out_fps_den
        move.l  port_par_num,n79j_out_par_num
        move.l  port_par_den,n79j_out_par_den
        move.l  port_color_space,n79j_out_colorspace
        bsr     n79j_setup_sched_isp_renderer
        tst.l   d0
        bne.w   v12a_setup_fail
        moveq   #0,d0
        bra.w   v12a_setup_done
n79j_check_bgr24:
        cmpi.l  #MMAL_ENCODING_BGR24,port_fmt_encoding
        bne.w   v12a_setup_fail

        ; mkvr7 SAFE RESTORE:
        ; Matroska H264 input still uses the hardware-proven VPv102 framing and
        ; currently carries MMAL_TIME_UNKNOWN into MMAL.  A real video_scheduler
        ; data path must not be inserted until MKV PTS are attached to every
        ; VIDEO AU.  Keep the proven direct decoder OPQV -> ISP tunnel here.
        ;
        ; This deliberately restores VPv102 P96 playback semantics while
        ; retaining the later common-core fixes (async FAAD, cleanup/restart,
        ; and VPv174 nonblocking P96 layer handling).
        bsr     v12a_connect_ports
        tst.l   d0
        bne.w   v12a_setup_fail

        ; Apply peer input requirements before enabling connected decoder output.
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_input,d0
        bne.w   v12a_setup_fail
        bsr     v12a_set_isp_requirements
        tst.l   d0
        bne.w   v12a_setup_fail

        ; Enable decoder OUTPUT; connected ISP INPUT comes up through the tunnel.
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_decoder_output,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   vpv176_mkv_dec_out_num_ok
        moveq   #2,d0
vpv176_mkv_dec_out_num_ok:
        move.l  d0,port_buf_num
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   v12a_setup_fail

        ; Verify ISP INPUT was enabled by the direct VideoCore tunnel.
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        cmpi.l  #1,port_enabled
        bne.w   v12a_setup_fail

        ; Enable host-facing ISP output with exactly two small buffers.
        move.l  v12a_isp_output,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        moveq   #2,d0
        move.l  d0,port_buf_num
        move.l  d0,v10j_output_req_count
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_enabled,d0
        cmpi.l  #1,d0
        bne.w   v12a_setup_fail

        ; ISP is a real component and must be enabled too.
        jsr     component_enable_worker
        tst.l   d0
        bne.w   v12a_setup_fail

        ; Save only the SMALL ISP output for existing host/HAM6 code.
        move.l  v12a_isp_handle,output_component_handle
        move.l  v12a_isp_output,output_port_handle
        move.l  port_buf_size,output_buf_size_saved
        move.l  port_video_width,output_width_saved
        move.l  port_video_height,output_height_saved
        move.l  port_crop_x,output_crop_x_saved
        move.l  port_crop_y,output_crop_y_saved
        move.l  port_crop_width,output_crop_w_saved
        move.l  port_crop_height,output_crop_h_saved
        move.l  output_width_saved,d0
        move.l  output_height_saved,d1
        mulu.w  d1,d0
        move.l  d0,d1
        add.l   d0,d0
        add.l   d1,d0                    ; BGR24: aligned width*height*3
        move.l  d0,output_frame_bytes_expected
        cmp.l   output_buf_size_saved,d0
        bhi.w   v12a_setup_fail

        ; V40: the chosen size is now final for this playback.  Resize the
        ; Intuition window exactly once to surround the fixed ISP crop.
        jsr     v32f_resize_window_fixed

        ; Restore decoder as the input-side component for H264/EOS messages.
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle

        lea     msg_v12a_graph_ok,a1
        move.l  #msg_v12a_graph_ok_end-msg_v12a_graph_ok,d3
        jsr     print
        move.l  output_width_saved,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  output_height_saved,d0
        jsr     print_hex32
        lea     msg_crop,a1
        move.l  #msg_crop_end-msg_crop,d3
        jsr     print
        move.l  output_crop_w_saved,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  output_crop_h_saved,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d0
        bra.s   v12a_setup_done
v12a_setup_fail:
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        lea     msg_v12a_graph_fail,a1
        move.l  #msg_v12a_graph_fail_end-msg_v12a_graph_fail,d3
        jsr     print
        moveq   #1,d0
v12a_setup_done:
        clr.l   v12a_local_get_active
        movem.l (sp)+,d1-d7/a0-a3
        rts

; ====================================================================
; N83 - ISP output size for small films: fit W x H (decoder crop) into
; 1920x1080 keeping the aspect.  Width = multiple of 128 (whole width
; visible, as N79K), height even, buffer height aligned to 16.
; Sets port_video_width/height and port_crop_*.  68000 code (mulu.w/divu.w;
; all values <= 2048, quotients <= 1920).
; ====================================================================
n83_calc_out:
        movem.l d0-d6,-(sp)
        move.l  n84_isp_out,d0           ; N84 test: fixed output size
        beq.s   n84_calc_auto
        move.l  d0,d4
        swap    d4
        andi.l  #$FFFF,d4                ; W
        move.l  d0,d1
        andi.l  #$FFFF,d1                ; H
        bra     n83_calc_store
n84_calc_auto:
        ; v96.88: the box is the real screen (o2_read_display_size, called
        ; by the router), at most 1920x1080.  Before: always 1920x1080, and
        ; on a 1280x1024 monitor the HVS then shrank it = green/black lines.
        move.l  o2_disp_w,d5             ; box W
        move.l  o2_disp_h,d6             ; box H
        cmpi.l  #1920,d5
        bhi.s   n88_box_hd
        cmpi.l  #1080,d6
        bls.s   n88_box_ok
n88_box_hd:
        move.l  #1920,d5
        move.l  #1080,d6
n88_box_ok:
        move.l  v12a_dec_crop_w,d2       ; W
        move.l  v12a_dec_crop_h,d3       ; H
        tst.l   d2
        beq.w   n83_calc_full
        tst.l   d3
        beq.w   n83_calc_full
        move.l  d2,d0
        mulu.w  d6,d0                    ; W*boxH
        move.l  d3,d1
        mulu.w  d5,d1                    ; H*boxW
        cmp.l   d1,d0
        bcs.s   n83_calc_tall
        ; v96.88: film wider than the screen by more than 2 % (16:9 film on
        ; a 5:4 / 4:3 screen): full screen width, height = H*boxW/W (even)
        move.l  d1,d4
        divu.w  #50,d4
        andi.l  #$FFFF,d4
        add.l   d1,d4                    ; H*boxW * 1.02
        cmp.l   d4,d0
        bls.s   n88_calc_box
        move.l  d1,d0
        add.l   d2,d0                    ; + W (round to nearest even)
        move.l  d2,d1
        add.l   d1,d1                    ; 2W
        divu.w  d1,d0
        andi.l  #$FFFF,d0
        add.l   d0,d0
        move.l  d0,d1                    ; height
        move.l  d5,d4                    ; width = box W
        bra.s   n83_calc_round
n88_calc_box:
        ; N84: 16:9 or up to 2 % wider (the router sends wider films the old
        ; way): exactly 1920x1080.  N83 used H*1920/W (720x404 -> 1076 lines)
        ; and the renderer then stretched it to 1080 lines in the HVS, which
        ; draws green stripes.  The ISP stretches by <= 2 % instead (clean,
        ; looks the same as before - the renderer filled the screen anyway).
        move.l  d5,d4                    ; v96.88: exactly the box
        move.l  d6,d1
        bra.s   n83_calc_round
n83_calc_tall:
        ; narrower: height = box H, width = W*boxH/H
        divu.w  d3,d0
        andi.l  #$FFFF,d0
        move.l  d0,d4
        move.l  d6,d1
n83_calc_round:
        add.l   #64,d4                   ; nearest multiple of 128
        andi.l  #$FFFFFF80,d4
        cmpi.l  #128,d4
        bcc.s   n83_calc_wmin
        move.l  #128,d4
n83_calc_wmin:
        cmp.l   d5,d4                    ; v96.88: not wider than the box
        bls.s   n83_calc_wmax
        move.l  d5,d4
        andi.l  #$FFFFFF80,d4
n83_calc_wmax:
        andi.l  #$FFFFFFFE,d1            ; even height
        cmpi.l  #16,d1
        bcc.s   n83_calc_hmin
        moveq   #16,d1
n83_calc_hmin:
        bra.s   n83_calc_store
n83_calc_full:
        move.l  d5,d4                    ; v96.88: the box
        move.l  d6,d1
        bra.w   n83_calc_round
n83_calc_store:
        move.l  d4,port_video_width
        move.l  d4,port_crop_width
        move.l  d1,port_crop_height
        move.l  d1,d0
        add.l   #15,d0
        andi.l  #$FFFFFFF0,d0
        move.l  d0,port_video_height
        clr.l   port_crop_x
        clr.l   port_crop_y
        lea     n83_msg_upscale,a1
        jsr     n12_log
        move.l  d4,d0
        lea     n83_pfx_w,a1
        jsr     n15_log_hex32
        move.l  port_crop_height,d0
        lea     n83_pfx_h,a1
        jsr     n15_log_hex32
        movem.l (sp)+,d0-d6
        rts

; ====================================================================
; O1 - OSD feasibility test (28.10.2026): a second ril.video_render on a
; layer above the film shows one RGBA picture (from mrberry, BVP_CTRL_OSD)
; for the whole film.  Built once at graph setup, before any frame is sent,
; so no extra traffic while the film plays.  Cinema (style 3) only.
; Request block (big endian, owned by mrberry until CloseStream):
;   +0 'OSD1'  +4 width (mult. of 32)  +8 height (mult. of 16)
;   +12 alpha mode (0 = 255, 1 = 255 + MIX)  +16 RGBA data pointer
;   +20 dest x (-1 = centred)  +24 dest y (-1 = near the bottom)
; The host copy of the picture is freed as soon as BULK_TX_DONE arrived
; (the VideoCore keeps its own copy).  A returned O1 buffer is ignored by
; h19_buffer_to_host (context O1_BUFFER_CONTEXT).
; ====================================================================
O1_LAYER            equ 11              ; above the film (HDMI_V14_LAYER 10)
O1_BUFFER_CONTEXT   equ $05D10001
O1_PARAM_CONTEXT    equ $05D30001
O1_DATA_MAX         equ $00100000       ; O3: 1 MiB RGBA max (e.g. 1280x128)
O1_PL_OFFSET        equ $00100000       ; pagelist after the data
O1_ALLOC_SIZE       equ $00102000       ; data + pagelist page + alignment
O1_MAGIC            equ $4F534431       ; 'OSD1'

o1_setup:
        movem.l d0-d7/a0-a6,-(sp)
        clr.l   o1_stage
        clr.l   o1_ok
        lea     o1_msg_begin,a1
        jsr     n12_log
        clr.l   o2_hide_move
        move.l  o1_req,a0
        cmpi.l  #O1_MAGIC,(a0)
        beq.s   o1_magic_ok
        cmpi.l  #O2_MAGIC,(a0)
        bne.w   o1_fail
        move.l  28(a0),o2_hide_move       ; O2: 0 = hide by alpha, 1 = move away
o1_magic_ok:
        jsr     o2_read_display_size
        move.l  #1,o1_stage
        move.l  4(a0),d0
        move.l  d0,o1_w
        move.l  8(a0),d1
        move.l  d1,o1_h
        beq.w   o1_fail
        tst.l   d0
        beq.w   o1_fail
        move.l  d0,d2
        andi.l  #31,d2
        bne.w   o1_fail
        move.l  d1,d2
        andi.l  #15,d2
        bne.w   o1_fail
        mulu.w  d1,d0                     ; w*h (both < 65536)
        lsl.l   #2,d0                     ; RGBA
        cmp.l   #O1_DATA_MAX,d0
        bhi.w   o1_fail
        move.l  d0,o1_bytes
        move.l  #255,o1_alpha
        tst.l   12(a0)
        beq.s   o1_alpha_set
        move.l  #$800000FF,o1_alpha       ; MMAL_DISPLAY_ALPHA_FLAGS_MIX | 255
o1_alpha_set:
        ; destination: centred, 1/12 of the screen above the bottom
        move.l  20(a0),d0
        cmpi.l  #-1,d0
        bne.s   o1_dx_ok
        move.l  o2_disp_w,d0              ; O2: TV picture, not the Workbench
        sub.l   o1_w,d0
        bpl.s   o1_dx_pos
        moveq   #0,d0
o1_dx_pos:
        lsr.l   #1,d0
o1_dx_ok:
        move.l  d0,o1_dest_x
        move.l  24(a0),d0
        cmpi.l  #-1,d0
        bne.s   o1_dy_ok
        move.l  o2_disp_h,d0              ; O2: TV picture, not the Workbench
        move.l  d0,d1
        divu.w  #12,d1
        andi.l  #$FFFF,d1
        sub.l   o1_h,d0
        sub.l   d1,d0
        bpl.s   o1_dy_ok
        moveq   #0,d0
o1_dy_ok:
        move.l  d0,o1_dest_y
        move.l  o1_dest_x,o2_show_x
        move.l  o1_dest_y,o2_show_y
        move.l  o1_alpha,o2_show_alpha
        move.l  #1,o2_shown

        ; ---- DMA-safe host copy (4 KiB aligned, below the VC alias limit)
        move.l  #2,o1_stage
        move.l  4.w,a6
        move.l  #O1_ALLOC_SIZE,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        move.l  d0,o1_alloc
        beq.w   o1_fail
        add.l   #$00000fff,d0
        and.l   #$fffff000,d0
        move.l  d0,o1_buf
        move.l  d0,d1
        add.l   #O1_ALLOC_SIZE-$1000,d1
        cmp.l   #$3f000000,d1
        bcc.w   o1_fail
        move.l  o1_req,a0
        move.l  16(a0),a0                 ; source RGBA
        move.l  o1_buf,a1
        move.l  o1_bytes,d0
        lsr.l   #2,d0
        subq.l  #1,d0
o1_copy:
        move.l  (a0)+,(a1)+
        subq.l  #1,d0
        bpl.s   o1_copy
        ; pagelist: length, type WRITE, one contiguous run
        move.l  o1_buf,a0
        add.l   #O1_PL_OFFSET,a0
        move.l  a0,o1_pagelist
        move.l  o1_bytes,d0
        jsr     store_le32
        move.l  o1_pagelist,a0
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  o1_bytes,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        move.l  o1_buf,d1
        or.l    #$c0000000,d1
        or.l    d0,d1
        lea     8(a0),a0
        move.l  d1,d0
        jsr     v94_pl_store             ; v96.94: CM4 = 36-bit pagelist
        ; push picture + pagelist out of the CPU cache
        move.l  4.w,a6
        move.l  #O1_ALLOC_SIZE-$1000,o1_dma_len
        move.l  o1_buf,a0
        lea     o1_dma_len,a1
        moveq   #0,d0
        jsr     CachePreDMA(a6)
        move.l  #O1_ALLOC_SIZE-$1000,o1_dma_len
        move.l  o1_buf,a0
        lea     o1_dma_len,a1
        moveq   #0,d0
        jsr     CachePostDMA(a6)

        ; errors in the MMAL helpers return here instead of close_prog
        move.l  #1,v12a_local_get_active
        move.l  #1,v12c_local_set_active

        ; ---- second ril.video_render (style 3 selects that name)
        move.l  #3,o1_stage
        move.l  v12a_isp_handle,o1_save_handle
        jsr     v12a_create_isp
        move.l  v12a_isp_handle,o1_handle
        move.l  o1_save_handle,v12a_isp_handle
        tst.l   d0
        bne.w   o1_fail_mmal

        ; ---- INPUT 0 = RGBA w x h, one buffer
        move.l  #4,o1_stage
        move.l  o1_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   o1_fail_mmal
        move.l  port_last_handle,o1_input
        move.l  o1_input,input_port_handle
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_RGBA,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  o1_w,port_video_width
        move.l  o1_h,port_video_height
        clr.l   port_crop_x
        clr.l   port_crop_y
        move.l  o1_w,port_crop_width
        move.l  o1_h,port_crop_height
        clr.l   port_fps_num
        move.l  #1,port_fps_den
        move.l  #1,port_par_num
        move.l  #1,port_par_den
        clr.l   port_color_space
        move.l  port_buf_num_min,d0
        cmpi.l  #2,d0                     ; O3: 2, old one held while new one shows
        bcc.s   o1_num_ok
        moveq   #2,d0
o1_num_ok:
        move.l  d0,port_buf_num
        move.l  o1_bytes,d0
        cmp.l   port_buf_size_min,d0
        bcc.s   o1_size_ok
        move.l  port_buf_size_min,d0
o1_size_ok:
        move.l  d0,port_buf_size
        move.l  #5,o1_stage
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        move.l  #1,v12c_local_set_active
        tst.l   d0
        bne.w   o1_fail_mmal
        move.l  #6,o1_stage
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   o1_fail_mmal
        move.l  port_last_handle,d0
        cmp.l   o1_input,d0
        bne.w   o1_fail_mmal
        cmpi.l  #MMAL_ENCODING_RGBA,port_fmt_encoding
        bne.w   o1_fail_mmal
        move.l  port_buf_size,o1_port_size

        ; ---- layer, place and alpha
        move.l  #7,o1_stage
        jsr     o1_set_displayregion
        tst.l   d0
        bne.w   o1_fail_mmal

        ; ---- enable INPUT 0 (local-0 / local-1 helper as for audio_render)
        move.l  #8,o1_stage
        move.l  o1_handle,component_handle
        move.l  o1_input,input_port_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   o1_fail_mmal
        tst.l   v12f_local_port
        bne.s   o1_enable_second
        jsr     port_enable_current
        bra.s   o1_enable_done
o1_enable_second:
        move.l  o1_input,d0
        move.l  #MMAL_PORT_INPUT,d1
        jsr     v9f_port_enable
o1_enable_done:
        tst.l   d0
        bne.w   o1_fail_mmal
        move.l  #9,o1_stage
        move.l  o1_handle,component_handle
        jsr     component_enable_worker
        tst.l   d0
        bne.w   o1_fail_mmal

        ; ---- the picture
        move.l  #10,o1_stage
        jsr     o1_send_buffer
        tst.l   d0
        bne.w   o1_fail_mmal
        move.l  #11,o1_stage
        jsr     o1_wait_bulk
        tst.l   d0
        bne.w   o1_fail_mmal
        move.l  #1,o1_ok
        lea     o1_msg_ok,a1
        jsr     n12_log
        bra.s   o1_end
o1_fail_mmal:
o1_fail:
        lea     o1_msg_fail,a1
        jsr     n12_log
o1_end:
        clr.l   v12a_local_get_active
        clr.l   v12c_local_set_active
        ; the graph state the stream continues with (as n79j_setup_*)
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        move.l  o1_stage,d0
        lea     o1_pfx_stage,a1
        jsr     n15_log_hex32
        move.l  o1_port_size,d0
        lea     o1_pfx_size,a1
        jsr     n15_log_hex32
        move.l  o1_dest_x,d0
        lea     o1_pfx_x,a1
        jsr     n15_log_hex32
        move.l  o1_dest_y,d0
        lea     o1_pfx_y,a1
        jsr     n15_log_hex32
        move.l  o2_dispctrl,d0           ; O2: TV picture size
        lea     o2_pfx_dispctrl,a1
        jsr     n15_log_hex32
        move.l  o2_disp_w,d0
        lea     o2_pfx_dw,a1
        jsr     n15_log_hex32
        move.l  o2_disp_h,d0
        lea     o2_pfx_dh,a1
        jsr     n15_log_hex32
        move.l  o1_dr_status,d0          ; O1b: display region reply
        lea     o1_pfx_drst,a1
        jsr     n15_log_hex32
        move.l  o1_dr_ctx,d0
        lea     o1_pfx_drctx,a1
        jsr     n15_log_hex32
        move.l  o1_bulk_result,d0
        lea     o1_pfx_bulk,a1
        jsr     n15_log_hex32
        ; O3: keep the DMA buffer for new pictures while the OSD works;
        ; o2_close frees it.  After a failure free it now.
        tst.l   o1_ok
        bne.s   o1_no_free
        move.l  o1_alloc,d0
        beq.s   o1_no_free
        move.l  d0,a1
        move.l  #O1_ALLOC_SIZE,d0
        move.l  4.w,a6
        jsr     FreeMem(a6)
        clr.l   o1_alloc
o1_no_free:
        movem.l (sp)+,d0-d7/a0-a6
        rts


; ------------------------------------------------------------
; O2: fill one 128-byte PARAMETER_SET DISPLAYREGION record at A2 for the OSD
; renderer from o1_dest_x/y, o1_w/h, o1_alpha; context o1_df_ctx.
; ------------------------------------------------------------
o1_dr_fill:
        movem.l d0-d1/d7/a0,-(sp)
        move.l  a2,a0
        moveq   #31,d7
o1_df_clear:
        clr.l   (a0)+
        dbra    d7,o1_df_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #116,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_PARAMETER_SET,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  o1_df_ctx,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  o1_handle,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  o1_input,d0
        jsr     store_le32

        ; MMAL_DISPLAYREGION_T begins at worker param offset +40.
        lea     40(a2),a0
        move.l  #MMAL_PARAMETER_DISPLAYREGION,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #84,d0
        jsr     store_le32
        lea     48(a2),a0
        move.l  #HDMI_V14_DISPLAY_SET,d0
        jsr     store_le32
        ; +52 display_num = 1, explicitly selected by DISPLAY_SET_NUM.
        lea     52(a2),a0
        move.l  #HDMI_V18_DISPLAY_NUM,d0
        jsr     v91_display_num          ; v96.91: CM4 -> 2 (HDMI0)
        jsr     store_le32
        lea     56(a2),a0
        moveq   #0,d0                   ; O1: not fullscreen, own dest_rect
        jsr     store_le32
        ; +60 transform = 0. dest_rect = complete current P96/Workbench screen.
        lea     64(a2),a0
        move.l  o1_dest_x,d0
        jsr     store_le32
        lea     68(a2),a0
        move.l  o1_dest_y,d0
        jsr     store_le32
        lea     72(a2),a0
        move.l  o1_w,d0
        jsr     store_le32
        lea     76(a2),a0
        move.l  o1_h,d0
        jsr     store_le32
        lea     112(a2),a0
        move.l  #O1_LAYER,d0
        jsr     store_le32
        ; +116 copyprotect = 0, left cleared.
        lea     120(a2),a0
        move.l  o1_alpha,d0              ; O1: 255 (+ MIX flag in mode 1)
        jsr     store_le32

        movem.l (sp)+,d0-d1/d7/a0
        rts

; ====================================================================
; O2 (28.10.2026): OSD on/off while the film plays, OSD placed on the TV
; picture.  o2_apply runs at the start of SendVideo (library owns the
; queues), sends PARAMETER_SET DISPLAYREGION without waiting (as the
; window clock queries); the reply goes through h19_mmal_data -> o2_reply.
; Hide: o2_hide_move 0 = alpha MIX|0 (layer stays), 1 = moved below the
; screen bottom.
; ====================================================================
O2_MAGIC            equ $4F534432       ; 'OSD2'
O2_PARAM_CONTEXT    equ $05D50001
O2_HVS_DISPCTRL1    equ $F2400050       ; channel 1 (DISPLIST1 $F2400024)

o2_read_display_size:
        movem.l d0-d1/a0,-(sp)
        ; v96.89: Pi 4 / CM4: HVS5 DISPCTRL has another bit layout; ask the
        ; firmware for the physical display size (tag $00040003, as the
        ; VideoCore.card does) instead.
        tst.l   v89_vc6
        beq.s   v89_rds_pi3
        movem.l d2,-(sp)
        move.l  #$00040003,d0
        jsr     v89_query_tag
        tst.l   d0
        bne.s   v89_rds_fail
        move.l  d2,d0                     ; height (d1 = width)
        movem.l (sp)+,d2                  ; movem keeps the flags/values
        move.l  d1,o2_dispctrl            ; (width, for the trace)
        bra.s   v89_rds_check
v89_rds_fail:
        movem.l (sp)+,d2
        bra.s   o2_rds_default
v89_rds_pi3:
        move.l  #O2_HVS_DISPCTRL1,a0
        jsr     load_le32
        move.l  d0,o2_dispctrl
        move.l  d0,d1
        lsr.l   #8,d1
        lsr.l   #4,d1
        andi.l  #$00000fff,d1             ; width  bits 23..12
        andi.l  #$00000fff,d0             ; height bits 11..0
v89_rds_check:
        cmpi.l  #640,d1
        bcs.s   o2_rds_default
        cmpi.l  #4096,d1
        bhi.s   o2_rds_default
        cmpi.l  #400,d0
        bcs.s   o2_rds_default
        cmpi.l  #2304,d0
        bhi.s   o2_rds_default
        move.l  d1,o2_disp_w
        move.l  d0,o2_disp_h
        bra.s   o2_rds_done
o2_rds_default:
        move.l  #1920,o2_disp_w
        move.l  #1080,o2_disp_h
o2_rds_done:
        movem.l (sp)+,d0-d1/a0
        rts

o2_apply:
        movem.l d0-d7/a0-a6,-(sp)
        clr.l   o2_req
        tst.l   o1_ok
        beq.w   o2_ap_done
        tst.l   v10h_error_seen
        bne.w   o2_ap_done
        tst.l   o2_reply_pending
        beq.s   o2_ap_go
        move.l  #1,o2_req                 ; one at a time: try next frame
        bra.w   o2_ap_done
o2_ap_go:
        move.l  o2_want,d0
        cmp.l   o2_shown,d0
        beq.w   o2_ap_done                ; already so
        move.l  o2_show_x,o1_dest_x
        move.l  o2_show_y,o1_dest_y
        move.l  o2_show_alpha,o1_alpha
        tst.l   d0
        bne.s   o2_ap_values
        tst.l   o2_hide_move
        bne.s   o2_ap_move
        move.l  #$80000000,o1_alpha       ; MIX with 0: fully transparent
        bra.s   o2_ap_values
o2_ap_move:
        move.l  o2_disp_h,d1
        add.l   #16,d1
        move.l  d1,o1_dest_y              ; below the bottom edge
o2_ap_values:
        jsr     bvp_engine_env
        jsr     dma_post_all
        move.l  #128,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.s   o2_ap_fail
        move.l  #O2_PARAM_CONTEXT,o1_df_ctx
        jsr     o1_dr_fill
        add.l   #128,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  o2_want,o2_shown
        move.l  #1,o2_reply_pending
        addq.l  #1,o2_sends
        jsr     p96w12_kick               ; flush + doorbell (DMA-owned)
        jsr     dma_post_all
        bra.s   o2_ap_done
o2_ap_fail:
        addq.l  #1,o2_fails
o2_ap_done:
        movem.l (sp)+,d0-d7/a0-a6
        rts

; From h19_mmal_data with A2 = message: PARAMETER_SET reply.  Ours is
; counted; every SET reply is consumed as before O2.
o2_reply:
        movem.l d0,-(sp)
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   #O2_PARAM_CONTEXT,d0
        bne.s   o2_rp_out
        clr.l   o2_reply_pending
        addq.l  #1,o2_replies
        move.l  bulk_rx_size,d0
        cmpi.l  #28,d0
        bcs.s   o2_rp_out
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,o2_last_status
        tst.l   d0
        beq.s   o2_rp_out
        addq.l  #1,o2_bad_status
o2_rp_out:
        movem.l (sp)+,d0
        jmp     h19_consume

; CloseStream: let an outstanding OSD reply arrive before the synchronous
; teardown, then log.  The OSD renderer itself goes with the service close.
o2_close:
        movem.l d0-d7/a0-a6,-(sp)
        jsr     bvp_engine_env
        clr.l   s1_enabled
        tst.l   o1_ok
        beq.w   o2_cl_reset
        tst.l   v10h_error_seen
        bne.s   o2_cl_log
        tst.l   p96w_wait_timeouts
        bne.s   o2_cl_log
        move.l  #400,d7
o2_cl_loop:
        tst.l   o2_reply_pending
        bne.s   o2_cl_busy
        tst.l   s1_pending
        beq.s   o2_cl_log
o2_cl_busy:
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     60(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bls.s   o2_cl_wait
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.s   o2_cl_log
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,bulk_rx_size
        jsr     v9g_h19_dispatch
        jsr     dma_post_all
        bra.s   o2_cl_next
o2_cl_wait:
        jsr     short_delay
o2_cl_next:
        subq.l  #1,d7
        bne.s   o2_cl_loop
o2_cl_log:
        move.l  o2_requests,d0
        lea     o2_pfx_req,a1
        jsr     n15_log_hex32
        move.l  o2_sends,d0
        lea     o2_pfx_sends,a1
        jsr     n15_log_hex32
        move.l  o2_replies,d0
        lea     o2_pfx_replies,a1
        jsr     n15_log_hex32
        move.l  o2_bad_status,d0
        lea     o2_pfx_bad,a1
        jsr     n15_log_hex32
        move.l  o2_last_status,d0
        lea     o2_pfx_last,a1
        jsr     n15_log_hex32
        move.l  o2_fails,d0
        lea     o2_pfx_fails,a1
        jsr     n15_log_hex32
        move.l  o2_reply_pending,d0
        lea     o2_pfx_pend,a1
        jsr     n15_log_hex32
        move.l  o3_requests,d0
        lea     o3_pfx_req,a1
        jsr     n15_log_hex32
        move.l  o3_sent,d0
        lea     o3_pfx_sent,a1
        jsr     n15_log_hex32
        move.l  o3_done,d0
        lea     o3_pfx_done,a1
        jsr     n15_log_hex32
        move.l  o3_defers,d0
        lea     o3_pfx_defers,a1
        jsr     n15_log_hex32
        move.l  o3_bad,d0
        lea     o3_pfx_bad,a1
        jsr     n15_log_hex32
        move.l  o3_dead,d0
        lea     o3_pfx_dead,a1
        jsr     n15_log_hex32
        move.l  o3_max_us,d0
        lea     o3_pfx_max,a1
        jsr     n15_log_hex32
        move.l  o3_total_us,d0
        lea     o3_pfx_total,a1
        jsr     n15_log_hex32
        move.l  s1_block+16,d0
        lea     s1_pfx_q,a1
        jsr     n15_log_hex32
        move.l  s1_block,d0
        lea     s1_pfx_r,a1
        jsr     n15_log_hex32
        move.l  s1_block+20,d0
        lea     s1_pfx_f,a1
        jsr     n15_log_hex32
        move.l  s1_rtt_max,d0
        lea     s1_pfx_rtt,a1
        jsr     n15_log_hex32
o2_cl_reset:
        clr.l   o1_ok
        clr.l   o2_req
        clr.l   o2_want
        clr.l   o2_shown
        clr.l   o2_reply_pending
        clr.l   o2_requests
        clr.l   o2_sends
        clr.l   o2_replies
        clr.l   o2_bad_status
        clr.l   o2_last_status
        clr.l   o2_fails
        clr.l   o3_req
        clr.l   o3_bulk_pending
        clr.l   o3_requests
        clr.l   o3_sent
        clr.l   o3_done
        clr.l   o3_defers
        clr.l   o3_bad
        clr.l   o3_dead
        clr.l   o3_max_us
        clr.l   o3_total_us
        clr.l   s1_pending
        clr.l   s1_started
        clr.l   s1_rtt_max
        lea     s1_block,a0
        moveq   #5,d0
o2_cl_s1clr:
        clr.l   (a0)+
        dbra    d0,o2_cl_s1clr
        move.l  o1_alloc,d0               ; O3: DMA picture buffer
        beq.s   o2_cl_nofree
        move.l  d0,a1
        move.l  #O1_ALLOC_SIZE,d0
        move.l  4.w,a6
        jsr     FreeMem(a6)
        clr.l   o1_alloc
o2_cl_nofree:
        movem.l (sp)+,d0-d7/a0-a6
        rts

; ====================================================================
; O3 (28.10.2026): new OSD picture while the film plays.  From the start
; of SendVideo: only when no other BULK_TX is outstanding (BULK_TX is
; serialized on the shared service, h19_input_bulk_done relies on that).
; BUFFER_FROM_HOST + BULK_TX as at setup, then wait for our BULK_TX_DONE
; while every other message goes through the normal dispatcher.  The
; buffer the renderer gives back (BUFFER_TO_HOST, O1 context) is ignored
; by h19_buffer_to_host.  A timeout ends O3 for this film (o3_dead).
; ====================================================================
o3_apply:
        movem.l d0-d7/a0-a6,-(sp)
        tst.l   o1_ok
        beq.w   o3_ap_clear
        tst.l   o3_dead
        bne.w   o3_ap_clear
        tst.l   v10h_error_seen
        bne.w   o3_ap_clear
        tst.l   eos_sent
        bne.w   o3_ap_clear
        tst.l   input_bulk_pending
        bne.w   o3_ap_defer
        tst.l   vpv39_audio_bulk_pending
        bne.w   o3_ap_defer
        clr.l   o3_req
        jsr     bvp_engine_env
        jsr     vpv98_read_sys_us
        move.l  d0,o3_t0
        jsr     dma_post_all
        move.l  #1,o3_bulk_pending
        jsr     o1_send_buffer            ; ends DMA-owned, doorbell rung
        tst.l   d0
        bne.w   o3_ap_fail
        addq.l  #1,o3_sent
        move.l  #$00040000,d7
o3_ap_loop:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     60(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bls.s   o3_ap_check
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.s   o3_ap_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,bulk_rx_size
        jsr     v9g_h19_dispatch
        tst.l   v10h_error_seen
        bne.s   o3_ap_fail
o3_ap_check:
        tst.l   o3_bulk_pending
        beq.s   o3_ap_ok
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   o3_ap_loop
        jsr     dma_post_all
o3_ap_fail:
        move.l  #1,o3_dead
        clr.l   o3_bulk_pending
        bra.s   o3_ap_done
o3_ap_ok:
        jsr     vpv98_read_sys_us
        sub.l   o3_t0,d0
        add.l   d0,o3_total_us
        cmp.l   o3_max_us,d0
        bls.s   o3_ap_done
        move.l  d0,o3_max_us
        bra.s   o3_ap_done
o3_ap_defer:
        addq.l  #1,o3_defers              ; o3_req stays: next SendVideo
        bra.s   o3_ap_done
o3_ap_clear:
        clr.l   o3_req
o3_ap_done:
        movem.l (sp)+,d0-d7/a0-a6
        rts

; From h19_input_bulk_done, D0 = bulk_actual, while o3_bulk_pending.
o3_bulk_done:
        clr.l   o3_bulk_pending
        addq.l  #1,o3_done
        cmp.l   o1_bytes,d0
        beq.s   o3_bd_ok
        addq.l  #1,o3_bad
o3_bd_ok:
        jmp     h19_consume


; ====================================================================
; S1 (28.10.2026): Pi clock for subtitles (see BVP_CTL_OsdClock).
; ====================================================================
S1_CLK_CTX          equ $05D70000
S1_PERIOD_US        equ 1000000
S1_TIMEOUT_US       equ 500000

s1_clk_maybe:
        movem.l d0-d7/a0-a6,-(sp)
        tst.l   bvp_p96_mode              ; cinema only
        bne.w   s1_cm_done
        tst.l   v10h_error_seen
        bne.w   s1_cm_done
        tst.l   n73_first_pcm_published
        beq.w   s1_cm_done
        tst.l   n73_clock_armed
        beq.w   s1_cm_done
        tst.l   vpv116_clock_handle
        beq.w   s1_cm_done
        jsr     vpv98_read_sys_us
        move.l  d0,d2
        tst.l   s1_pending
        beq.s   s1_cm_free
        sub.l   s1_req_sys,d0
        cmpi.l  #S1_TIMEOUT_US,d0
        bcs.w   s1_cm_done
        clr.l   s1_pending                ; lost: try again later
        addq.l  #1,s1_block+20
        bra.w   s1_cm_done
s1_cm_free:
        tst.l   s1_started
        beq.s   s1_cm_go
        sub.l   s1_next_sys,d0
        bmi.w   s1_cm_done
s1_cm_go:
        move.l  #1,s1_started
        move.l  d2,d0
        add.l   #S1_PERIOD_US,d0
        move.l  d0,s1_next_sys
        jsr     bvp_engine_env
        jsr     dma_post_all
        move.l  #48,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   s1_cm_fail
        move.l  a2,a0
        moveq   #11,d7
s1_cm_clear:
        clr.l   (a0)+
        dbra    d7,s1_cm_clear
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        moveq   #40,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_PARAMETER_GET,d0
        jsr     store_le32
        addq.l  #1,s1_seq
        move.l  s1_seq,d0
        andi.l  #$0000ffff,d0
        ori.l   #S1_CLK_CTX,d0
        move.l  d0,s1_ctx
        lea     20(a2),a0
        jsr     store_le32
        lea     32(a2),a0
        move.l  vpv116_clock_handle,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv117_clock_port0,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  #MMAL_PARAMETER_CLOCK_TIME,d0
        jsr     store_le32
        lea     44(a2),a0
        moveq   #16,d0
        jsr     store_le32
        add.l   #48,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        jsr     vpv98_read_sys_us
        move.l  d0,s1_req_sys
        move.l  #1,s1_pending
        addq.l  #1,s1_block+16
        jsr     p96w12_kick              ; flush + doorbell (DMA-owned)
        jsr     dma_post_all
        bra.s   s1_cm_done
s1_cm_fail:
        addq.l  #1,s1_block+20
s1_cm_done:
        movem.l (sp)+,d0-d7/a0-a6
        rts

; From h19_mmal_data (PARAMETER_GET reply) while s1_pending.
s1_clk_reply:
        movem.l d1-d3,-(sp)
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   s1_ctx,d0
        bne.s   s1_cr_other
        clr.l   s1_pending
        jsr     vpv98_read_sys_us
        move.l  d0,d3
        sub.l   s1_req_sys,d0             ; round trip
        cmp.l   s1_rtt_max,d0
        bls.s   s1_cr_rtt
        move.l  d0,s1_rtt_max
s1_cr_rtt:
        lsr.l   #1,d0
        add.l   s1_req_sys,d0
        move.l  d0,d3                     ; sample = middle of the round trip
        move.l  bulk_rx_size,d0
        cmpi.l  #44,d0
        bcs.s   s1_cr_fail
        lea     32(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.s   s1_cr_fail
        lea     48(a2),a0
        jsr     load_le32
        move.l  d0,d1                     ; media time hi
        bmi.s   s1_cr_fail                ; unknown / negative
        lea     44(a2),a0
        jsr     load_le32
        move.l  d1,s1_block+4
        move.l  d0,s1_block+8
        move.l  d3,s1_block+12
        addq.l  #1,s1_block               ; last: the block is complete
        bra.s   s1_cr_out
s1_cr_fail:
        addq.l  #1,s1_block+20
s1_cr_out:
        movem.l (sp)+,d1-d3
        jmp     h19_consume
s1_cr_other:
        movem.l (sp)+,d1-d3
        jmp     p96w_clk_reply            ; not ours (window clock)

; ------------------------------------------------------------
; O1: BUFFER_FROM_HOST (picture) + BULK_TX, as vpv01_send_tone_block.
; ------------------------------------------------------------
o1_send_buffer:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  #320,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   o1_send_fail
        move.l  a2,a0
        moveq   #79,d7
o1_send_clear:
        clr.l   (a0)+
        dbra    d7,o1_send_clear
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #292,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_BUFFER_FROM_HOST,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #O1_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  o1_handle,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  o1_input,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #O1_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     76(a2),a0
        move.l  o1_buf,d0
        jsr     store_le32
        lea     80(a2),a0
        move.l  o1_port_size,d0
        jsr     store_le32
        lea     84(a2),a0
        move.l  o1_bytes,d0
        jsr     store_le32
        lea     92(a2),a0
        move.l  #MMAL_BUFFER_FLAG_FRAME_END,d0
        jsr     store_le32
        lea     96(a2),a0                 ; PTS/DTS unknown: show at once
        moveq   #0,d0
        jsr     store_le32
        lea     100(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32
        lea     104(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     108(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32
        lea     304(a2),a3
        move.l  a3,a0
        move.l  #VCHIQ_MSG_BULK_TX,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #8,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  o1_pagelist,d0
        or.l    #$c0000000,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  o1_bytes,d0
        jsr     store_le32
        add.l   #320,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   o1_send_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
o1_send_no_bell:
        moveq   #0,d0
        bra.s   o1_send_done
o1_send_fail:
        moveq   #1,d0
o1_send_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; ------------------------------------------------------------
; O1: wait for BULK_TX_DONE of the picture (the renderer keeps the buffer,
; so no BUFFER_TO_HOST is expected).  Other traffic is consumed; at graph
; setup nothing else is in flight.  Returns CPU-owned shared RAM.
; ------------------------------------------------------------
o1_wait_bulk:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  #V10_CLEANUP_POLL_COUNT,d7
o1_wait_loop:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   o1_wait_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   o1_wait_loop
        jsr     dma_post_all
        bra.w   o1_wait_fail
o1_wait_have:
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   o1_wait_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,o1_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,o1_rx_size
        addq.l  #1,o1_rx_count
        move.l  o1_rx_msgid,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.s   o1_wait_consume
        move.l  o1_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_BULK_TX_DONE,d0
        bne.s   o1_wait_consume
        move.l  o1_rx_size,d0
        cmp.l   #4,d0
        bcs.s   o1_wait_consume
        lea     8(a2),a0
        jsr     load_le32
        move.l  d0,o1_bulk_result
        cmp.l   o1_bytes,d0
        bne.s   o1_wait_consume
        move.l  o1_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.s   o1_wait_fail
        moveq   #0,d0
        bra.s   o1_wait_done
o1_wait_consume:
        move.l  o1_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.s   o1_wait_fail
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   o1_wait_loop
        jsr     dma_post_all
o1_wait_fail:
        moveq   #1,d0
o1_wait_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; O1: display region of the OSD renderer (copy of hdmi_v40o_set_displayregion)
o1_set_displayregion:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   o1_dr_status
        clr.l   o1_dr_rx_size
        clr.l   o1_dr_type
        clr.l   o1_dr_ctx

        ; Worker payload is 32-byte prefix before param + 84-byte displayregion
        ; = 116 bytes. With 8-byte VCHIQ header, reserve/alignment stride = 128.
        tst.l   v12f_local_port
        beq.s   o1_dr_tx_legacy
        move.l  #128,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   o1_dr_fail
        bra.s   o1_dr_tx_ready
o1_dr_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
o1_dr_tx_ready:
        move.l  #O1_PARAM_CONTEXT,o1_df_ctx
        jsr     o1_dr_fill
        add.l   #128,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   o1_dr_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
o1_dr_wait_setup:
        move.l  #POLL_COUNT,d7
o1_dr_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   o1_dr_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   o1_dr_wait
        jsr     dma_post_all
        bra.w   o1_dr_fail

o1_dr_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   o1_dr_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,o1_dr_rx_size
        cmp.l   #28,d0
        bcs.w   o1_dr_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   o1_dr_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        move.l  d0,o1_dr_type            ; O1 diagnostics
        cmp.l   #MMAL_PORT_PARAMETER_SET,d0
        bne.w   o1_dr_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        move.l  d0,o1_dr_ctx
        cmp.l   #O1_PARAM_CONTEXT,d0     ; O1b: was still $12D30001
        bne.w   o1_dr_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,o1_dr_status
        move.l  o1_dr_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   o1_dr_fail
        move.l  o1_dr_status,d0
        tst.l   d0
        bne.w   o1_dr_fail
        move.l  #1,o1_dr_ok
        moveq   #0,d0
        bra.s   o1_dr_done

o1_dr_fail_consume:
        move.l  o1_dr_rx_size,d0
        jsr     v12a_rx_consume_payload
o1_dr_fail:
        clr.l   o1_dr_ok
        moveq   #1,d0
o1_dr_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; ====================================================================
; N79J - decoder -> video_scheduler -> ISP(I420, 128-aligned) -> renderer
; Entry: the real ISP is configured (n79j_* holds its output format).
; ====================================================================
n79j_setup_sched_isp_renderer:
        movem.l d1-d7/a0-a3,-(sp)
        ; Preserve the exact Workbench HVS list before video_render owns it.
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,hdmi_v40o_hvs_saved
        ; N80: without HDMI audio (no ConfigAudio) the Audio-Master clock
        ; never runs, and a scheduler in the chain would hold every frame.
        ; Tunnel decoder -> ISP directly; n66_service_pending_video then
        ; paces AUs with the host frame grid because the graph is not
        ; marked scheduler-ready.  The tunnel is built after the
        ; renderer's DISPLAYREGION: with decoder -> ISP already in place
        ; the VideoCore never answered that request (PiStorm 600).
        clr.l   n80_direct_mode
        tst.l   n80_no_hdmi_audio
        bne.s   n80_n79j_direct
        ; Proven N79 graph helper: decoder -> scheduler -> ISP.
        jsr     vpv126_setup_scheduler_data_graph
        tst.l   d0
        bne.w   n80_j1
        move.l  #1,n73_scheduler_graph_ready
        move.l  #1,vpv166_c_sched_feedahead
        bra.s   n80_n79j_graph_ready
n80_n79j_direct:
        move.l  #1,n80_direct_mode
n80_n79j_graph_ready:
        move.l  v12a_isp_handle,n79j_isp_handle
        move.l  v12a_isp_input,n79j_isp_input
        move.l  v12a_isp_output,n79j_isp_output
        ; Create the video_render component (style 3 selects it).
        move.l  #3,v41_display_style
        bsr     v12a_create_isp
        tst.l   d0
        bne.w   n80_j3
        ; Renderer INPUT 0 = the ISP I420 surface.
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   n80_j4
        move.l  port_last_handle,v12a_isp_input
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_I420,port_fmt_encoding
        move.l  n79j_out_variant,port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  n79j_out_w,port_video_width
        move.l  n79j_out_h,port_video_height
        move.l  n79j_out_crop_x,port_crop_x
        move.l  n79j_out_crop_y,port_crop_y
        move.l  n79j_out_crop_w,port_crop_width
        move.l  n79j_out_crop_h,port_crop_height
        move.l  n79j_out_fps_num,port_fps_num
        move.l  n79j_out_fps_den,port_fps_den
        move.l  n79j_out_par_num,port_par_num
        move.l  n79j_out_par_den,port_par_den
        move.l  n79j_out_colorspace,port_color_space
        move.l  n79j_out_buf_size,port_buf_size
        move.l  n79j_out_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   n79j_rin_num_ok
        moveq   #2,d0
n79j_rin_num_ok:
        move.l  d0,port_buf_num
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   n80_j5
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   n80_j6
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_input,d0
        bne.w   n80_j7
        cmpi.l  #MMAL_ENCODING_I420,port_fmt_encoding
        bne.w   n80_j8
        ; Renderer visible, display region as for the direct C path.
        clr.l   v41b_renderer_reveal_pending
        move.l  #1,v41b_renderer_visible
        bsr     hdmi_v40o_set_displayregion
        tst.l   d0
        bne.w   n80_j9
        ; N80 direct mode: now tunnel decoder -> ISP.  The helper works on
        ; v12a_isp_*, which hold the renderer here, so swap the ISP in.
        tst.l   n80_direct_mode
        beq.s   n80_n79j_after_dr
        move.l  v12a_isp_handle,n80_rend_handle
        move.l  v12a_isp_input,n80_rend_input
        move.l  n79j_isp_handle,v12a_isp_handle
        move.l  n79j_isp_input,v12a_isp_input
        jsr     n80_setup_direct_isp_graph
        move.l  n80_rend_handle,v12a_isp_handle
        move.l  n80_rend_input,v12a_isp_input
        tst.l   d0
        bne.w   n80_j2
n80_n79j_after_dr:
        ; ISP.output -> renderer.input through the proven connector.
        move.l  v12a_decoder_handle,n79j_save_dec_handle
        move.l  v12a_decoder_output,n79j_save_dec_output
        move.l  n79j_isp_handle,v12a_decoder_handle
        move.l  n79j_isp_output,v12a_decoder_output
        bsr     v12a_connect_ports
        move.l  n79j_save_dec_handle,v12a_decoder_handle
        move.l  n79j_save_dec_output,v12a_decoder_output
        tst.l   d0
        bne.w   n80_j10
        ; Renderer peer requirements before ISP output is enabled.
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   n80_j11
        bsr     v12a_set_isp_requirements
        tst.l   d0
        bne.w   n80_j12
        ; Enable ISP OUTPUT; connected renderer input comes up with it.
        move.l  n79j_isp_handle,component_handle
        move.l  n79j_isp_output,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   n80_j13
        move.l  port_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   n79j_iout_num_ok
        moveq   #2,d0
n79j_iout_num_ok:
        move.l  d0,port_buf_num
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   n80_j14
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   n80_j15
        cmpi.l  #1,port_enabled
        bne.w   n80_j16
        ; Enable renderer, then the ISP component.
        jsr     component_enable_worker
        tst.l   d0
        bne.s   n80_j17
        move.l  n79j_isp_handle,component_handle
        jsr     component_enable_worker
        tst.l   d0
        bne.s   n80_j18
        ; No host-facing output buffers on this path.
        clr.l   output_component_handle
        clr.l   output_port_handle
        clr.l   output_buf_size_saved
        clr.l   output_width_saved
        clr.l   output_height_saved
        clr.l   output_crop_x_saved
        clr.l   output_crop_y_saved
        clr.l   output_crop_w_saved
        clr.l   output_crop_h_saved
        clr.l   output_frame_bytes_expected
        clr.l   v10j_output_req_count
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        lea     n79j_msg_graph_ready,a1
        jsr     n12_log
        moveq   #0,d0
        bra.s   n79j_done
n80_j1:
        move.l  d0,n80_n79j_d0
        move.l  #1,n80_n79j_step
        bra.w   n79j_fail
n80_j2:
        move.l  d0,n80_n79j_d0
        move.l  #2,n80_n79j_step
        bra.w   n79j_fail
n80_j3:
        move.l  d0,n80_n79j_d0
        move.l  #3,n80_n79j_step
        bra.w   n79j_fail
n80_j4:
        move.l  d0,n80_n79j_d0
        move.l  #4,n80_n79j_step
        bra.w   n79j_fail
n80_j5:
        move.l  d0,n80_n79j_d0
        move.l  #5,n80_n79j_step
        bra.w   n79j_fail
n80_j6:
        move.l  d0,n80_n79j_d0
        move.l  #6,n80_n79j_step
        bra.w   n79j_fail
n80_j7:
        move.l  d0,n80_n79j_d0
        move.l  #7,n80_n79j_step
        bra.w   n79j_fail
n80_j8:
        move.l  d0,n80_n79j_d0
        move.l  #8,n80_n79j_step
        bra.w   n79j_fail
n80_j9:
        move.l  d0,n80_n79j_d0
        move.l  #9,n80_n79j_step
        bra.w   n79j_fail
n80_j10:
        move.l  d0,n80_n79j_d0
        move.l  #10,n80_n79j_step
        bra.w   n79j_fail
n80_j11:
        move.l  d0,n80_n79j_d0
        move.l  #11,n80_n79j_step
        bra.w   n79j_fail
n80_j12:
        move.l  d0,n80_n79j_d0
        move.l  #12,n80_n79j_step
        bra.w   n79j_fail
n80_j13:
        move.l  d0,n80_n79j_d0
        move.l  #13,n80_n79j_step
        bra.w   n79j_fail
n80_j14:
        move.l  d0,n80_n79j_d0
        move.l  #14,n80_n79j_step
        bra.w   n79j_fail
n80_j15:
        move.l  d0,n80_n79j_d0
        move.l  #15,n80_n79j_step
        bra.w   n79j_fail
n80_j16:
        move.l  d0,n80_n79j_d0
        move.l  #16,n80_n79j_step
        bra.w   n79j_fail
n80_j17:
        move.l  d0,n80_n79j_d0
        move.l  #17,n80_n79j_step
        bra.w   n79j_fail
n80_j18:
        move.l  d0,n80_n79j_d0
        move.l  #18,n80_n79j_step
        bra.w   n79j_fail
n79j_fail:
        tst.l   n79j_save_dec_handle
        beq.s   n79j_fail_no_dec
        move.l  n79j_save_dec_handle,v12a_decoder_handle
        move.l  n79j_save_dec_output,v12a_decoder_output
n79j_fail_no_dec:
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        lea     n79j_msg_graph_fail,a1
        jsr     n12_log
        move.l  n80_n79j_step,d0
        lea     n80_pfx_j_step,a1
        jsr     n15_log_hex32
        move.l  n80_n79j_d0,d0
        lea     n80_pfx_j_d0,a1
        jsr     n15_log_hex32
        clr.l   n80_n79j_step
        moveq   #1,d0
n79j_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts



; ====================================================================
; mkvr7 - generic 64-bit Matroska tick -> microsecond conversion
; ====================================================================
        section code,code
; VPv170: exact unsigned (ticks * 1,000,000 + carried_remainder) / timescale.
; IN : D0=ticks (u32), D1=timescale (1..0x7fffffff), D2=carried numerator remainder
; OUT: D1:D0=quotient microseconds (hi:lo), D2=new remainder, D3=0 success/1 failure.
vpv170_ticks_to_us64_rem:
        movem.l d4-d7,-(sp)
        move.l  d1,d7
        move.l  d2,d6
        moveq   #1,d3
        tst.l   d7
        beq.w   vpv170_tu64_fail
        btst    #31,d7
        bne.w   vpv170_tu64_fail

        clr.l   d4                     ; product high
        clr.l   d5                     ; product low
        clr.l   d3                     ; shifted multiplicand high
        move.l  #1000000,d1
        moveq   #31,d2
vpv170_tu64_mul_loop:
        btst    #0,d1
        beq.s   vpv170_tu64_mul_noadd
        add.l   d0,d5
        addx.l  d3,d4
vpv170_tu64_mul_noadd:
        add.l   d0,d0
        addx.l  d3,d3
        lsr.l   #1,d1
        dbra    d2,vpv170_tu64_mul_loop

        add.l   d6,d5                  ; rational carry from previous step
        bcc.s   vpv170_tu64_num_ready
        addq.l  #1,d4
vpv170_tu64_num_ready:
        move.l  d4,d0                  ; quotient high = product_high / divisor
        move.l  d7,d1
        jsr     v10_udiv32
        move.l  d0,d4
        move.l  d1,d6                  ; remainder seeds low-word division

        clr.l   d0                     ; quotient low
        moveq   #31,d2
vpv170_tu64_div_loop:
        add.l   d6,d6
        btst    d2,d5
        beq.s   vpv170_tu64_div_nobit
        addq.l  #1,d6
vpv170_tu64_div_nobit:
        cmp.l   d7,d6
        bcs.s   vpv170_tu64_div_less
        sub.l   d7,d6
        bset    d2,d0
vpv170_tu64_div_less:
        dbra    d2,vpv170_tu64_div_loop

        move.l  d4,d1
        move.l  d6,d2
        moveq   #0,d3
        bra.s   vpv170_tu64_done
vpv170_tu64_fail:
        clr.l   d0
        clr.l   d1
        clr.l   d2
        moveq   #1,d3
vpv170_tu64_done:
        movem.l (sp)+,d4-d7
        rts

vpv170_ticks_to_us64:
        clr.l   d2
        bra.w   vpv170_ticks_to_us64_rem


