        section code,code

v32f_calc_mode_dims:
        jmp     v40j_calc_mode_dims
v32f_calc_mode_dims_legacy:
        movem.l d1-d7,-(sp)
        move.l  d0,d7
        cmpi.l  #1,d7
        beq.s   v32f_calc_small
        cmpi.l  #2,d7
        beq.s   v32f_calc_medium
        bra.w   v32f_calc_fail
v32f_calc_small:
        move.l  #192,d4
        move.l  #108,d5
        bra.s   v32f_calc_box_ready
v32f_calc_medium:
        move.l  #320,d4
        move.l  #180,d5
v32f_calc_box_ready:
        move.l  v12a_dec_crop_w,d1
        move.l  v12a_dec_crop_h,d2
        tst.l   d1
        beq.w   v32f_calc_fail
        tst.l   d2
        beq.w   v32f_calc_fail

        move.l  d4,d0
        mulu.w  d2,d0
        divu.w  d1,d0
        andi.l  #$0000ffff,d0
        cmp.l   d5,d0
        bhi.s   v32f_calc_fit_height
        move.l  d4,d3
        move.l  d0,d6
        bra.s   v32f_calc_even
v32f_calc_fit_height:
        move.l  d5,d6
        move.l  d5,d0
        mulu.w  d1,d0
        divu.w  d2,d0
        andi.l  #$0000ffff,d0
        move.l  d0,d3
v32f_calc_even:
        andi.l  #$fffffffe,d3
        andi.l  #$fffffffe,d6
        cmpi.l  #2,d3
        bcs.w   v32f_calc_fail
        cmpi.l  #2,d6
        bcs.w   v32f_calc_fail
        move.l  d3,v32_calc_w
        move.l  d6,v32_calc_h
        move.l  d3,d0
        add.l   #31,d0
        andi.l  #$ffffffe0,d0
        move.l  d0,v32_calc_aw
        move.l  d6,d0
        add.l   #15,d0
        andi.l  #$fffffff0,d0
        move.l  d0,v32_calc_ah
        moveq   #0,d0
        bra.s   v32f_calc_done
v32f_calc_fail:
        moveq   #1,d0
v32f_calc_done:
        movem.l (sp)+,d1-d7
        rts

; D0=mode (1/2). Queue a fixed mode change.
v32f_request_mode:
        movem.l d1-d4,-(sp)
        move.l  d0,d4
        cmp.l   v32_fixed_mode,d4
        beq.w   v32f_request_done
        cmp.l   v32_pending_mode,d4
        beq.w   v32f_request_done
        move.l  d4,d0
        jsr     v32f_calc_mode_dims
        tst.l   d0
        bne.w   v32f_request_done
        move.l  d4,v32_pending_mode
        move.l  v32_calc_w,v32_resize_pending_w
        move.l  v32_calc_h,v32_resize_pending_h
        move.l  v32_calc_aw,v32_resize_pending_aw
        move.l  v32_calc_ah,v32_resize_pending_ah
        ; V40 phase 1: do NOT hold output buffers yet.  First stop publishing
        ; new decoder input and let every already-submitted INPUT buffer return.
        ; Only then does v40_resize_service set v32_resize_pending=1, which is
        ; the existing callback-side signal to hold the two ISP output buffers.
        clr.l   v32_resize_pending
        clr.l   v32_resize_held
        clr.l   v40_resize_wait_count
        move.l  #1,v40_resize_state
        addq.l  #1,v32_switch_requests
        lea     msg_v32f_switch_request,a1
        move.l  #msg_v32f_switch_request_end-msg_v32f_switch_request,d3
        jsr     print
        move.l  d4,d0
        jsr     print_hex32
        lea     msg_v32f_switch_target,a1
        move.l  #msg_v32f_switch_target_end-msg_v32f_switch_target,d3
        jsr     print
        move.l  v32_resize_pending_w,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v32_resize_pending_h,d0
        jsr     print_hex32
        jsr     newline
v32f_request_done:
        movem.l (sp)+,d1-d4
        rts

; Resize Intuition window to surround active fixed video size.
v32f_resize_window_fixed:
        movem.l d0-d4/a0/a6,-(sp)
        cmpi.l  #2,v41_display_style
        bcc.w   v32f_resize_window_done
        move.l  hdmi_v40o_window_ptr,a0
        cmpa.l  #0,a0
        beq.w   v32f_resize_window_done
        move.l  hdmi_v40o_intuition_base,a6
        cmpa.l  #0,a6
        beq.w   v32f_resize_window_done

        move.l  output_crop_w_saved,d2
        moveq   #0,d3
        move.b  WIN_BorderLeft(a0),d3
        add.l   d3,d2
        moveq   #0,d3
        move.b  WIN_BorderRight(a0),d3
        add.l   d3,d2
        clr.l   d3
        move.w  WIN_Width(a0),d3
        sub.l   d3,d2

        move.l  output_crop_h_saved,d3
        moveq   #0,d4
        move.b  WIN_BorderTop(a0),d4
        add.l   d4,d3
        moveq   #0,d4
        move.b  WIN_BorderBottom(a0),d4
        add.l   d4,d3
        clr.l   d4
        move.w  WIN_Height(a0),d4
        sub.l   d4,d3

        move.l  d2,d0
        move.l  d3,d1
        jsr     IntuiSizeWindow(a6)
v32f_resize_window_done:
        movem.l (sp)+,d0-d4/a0/a6
        rts

; Tear down only the old ISP branch. Decoder/input remain alive.
v32f_teardown_isp:
        movem.l d1-d3,-(sp)
        move.l  v12a_isp_handle,d0
        tst.l   d0
        beq.w   v32f_teardown_fail

        move.l  v12a_isp_handle,component_handle
        move.l  v12a_isp_output,d0
        move.l  #MMAL_PORT_OUTPUT,d1
        jsr     v9_disable_port
        tst.l   d0
        bne.w   v32f_teardown_fail

        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_decoder_output,d0
        move.l  #MMAL_PORT_OUTPUT,d1
        jsr     v9_disable_port
        tst.l   d0
        bne.w   v32f_teardown_fail

        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_decoder_output,v9_worker_port
        move.l  #MMAL_PORT_OUTPUT,v9_worker_port_type
        move.l  #MMAL_PORT_ACTION,v9_worker_type
        move.l  #MMAL_PORT_ACTION_DISCONNECT,v9_worker_action
        move.l  #1,v9_worker_is_port
        jsr     v9_worker_sync
        tst.l   d0
        bne.w   v32f_teardown_fail

        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_COMPONENT_DISABLE,d0
        jsr     v9_component_cmd
        tst.l   d0
        bne.w   v32f_teardown_fail
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_COMPONENT_DESTROY,d0
        jsr     v9_component_cmd
        tst.l   d0
        bne.w   v32f_teardown_fail

        clr.l   v12a_isp_handle
        clr.l   v12a_isp_input
        clr.l   v12a_isp_output
        clr.l   output_component_handle
        clr.l   output_port_handle
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        moveq   #0,d0
        bra.s   v32f_teardown_done
v32f_teardown_fail:
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        moveq   #1,d0
v32f_teardown_done:
        movem.l (sp)+,d1-d3
        rts

; Build a fresh ISP branch for the pending fixed geometry.
v32f_build_fresh_isp:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  v32_resize_pending_w,v12a_target_w
        move.l  v32_resize_pending_h,v12a_target_h
        move.l  v32_resize_pending_aw,v12a_target_aw
        move.l  v32_resize_pending_ah,v12a_target_ah

        jsr     v12a_create_isp
        tst.l   d0
        bne.w   v32f_build_fail

        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,v12a_isp_input
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_OPAQUE,port_fmt_encoding
        move.l  v12c_dec_variant,port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v12a_dec_w,port_video_width
        move.l  v12a_dec_h,port_video_height
        move.l  v12a_dec_crop_x,port_crop_x
        move.l  v12a_dec_crop_y,port_crop_y
        move.l  v12a_dec_crop_w,port_crop_width
        move.l  v12a_dec_crop_h,port_crop_height
        move.l  v12a_dec_fps_num,port_fps_num
        move.l  v12a_dec_fps_den,port_fps_den
        move.l  v12a_dec_par_num,port_par_num
        move.l  v12a_dec_par_den,port_par_den
        move.l  v12a_dec_colorspace,port_color_space
        move.l  v12a_dec_buf_size,port_buf_size
        move.l  v12a_dec_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   v32f_build_in_num_ok
        moveq   #2,d0
v32f_build_in_num_ok:
        move.l  d0,port_buf_num
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v32f_build_fail
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_input,d0
        bne.w   v32f_build_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_OPAQUE,d0
        bne.w   v32f_build_fail

        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,v12a_isp_output
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_BGR24,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v12a_target_aw,port_video_width
        move.l  v12a_target_ah,port_video_height
        clr.l   port_crop_x
        clr.l   port_crop_y
        move.l  v12a_target_w,port_crop_width
        move.l  v12a_target_h,port_crop_height
        move.l  v12a_dec_fps_num,port_fps_num
        move.l  v12a_dec_fps_den,port_fps_den
        moveq   #1,d0
        move.l  d0,port_par_num
        move.l  d0,port_par_den
        move.l  v12a_dec_colorspace,port_color_space
        moveq   #2,d0
        move.l  d0,port_buf_num
        move.l  v12a_target_aw,d0
        move.l  v12a_target_ah,d1
        mulu.w  d1,d0
        move.l  d0,d1
        add.l   d0,d0
        add.l   d1,d0                    ; BGR24: 3 bytes/pixel
        cmp.l   #OUTPUT_MAX_DMA,d0
        bhi.w   v32f_build_fail
        move.l  d0,port_buf_size
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v32f_build_fail
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_output,d0
        bne.w   v32f_build_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_BGR24,d0
        bne.w   v32f_build_fail

        jsr     v12a_connect_ports
        tst.l   d0
        bne.w   v32f_build_fail
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_input,d0
        bne.w   v32f_build_fail
        jsr     v12a_set_isp_requirements
        tst.l   d0
        bne.w   v32f_build_fail

        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_decoder_output,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   v32f_build_dec_num_ok
        moveq   #2,d0
v32f_build_dec_num_ok:
        move.l  d0,port_buf_num
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   v32f_build_fail

        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        cmpi.l  #1,port_enabled
        bne.w   v32f_build_fail

        move.l  v12a_isp_output,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        moveq   #2,d0
        move.l  d0,port_buf_num
        move.l  d0,v10j_output_req_count
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   v32f_build_fail
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        cmpi.l  #1,port_enabled
        bne.w   v32f_build_fail

        jsr     component_enable_worker
        tst.l   d0
        bne.w   v32f_build_fail

        move.l  v12a_isp_handle,output_component_handle
        move.l  v12a_isp_output,output_port_handle
        move.l  port_buf_size,output_buf_size_saved
        move.l  port_video_width,output_width_saved
        move.l  port_video_height,output_height_saved
        move.l  port_crop_x,output_crop_x_saved
        move.l  port_crop_y,output_crop_y_saved
        move.l  port_crop_width,output_crop_w_saved
        move.l  port_crop_height,output_crop_h_saved
        move.l  output_width_saved,d0
        move.l  output_height_saved,d1
        mulu.w  d1,d0
        move.l  d0,d1
        add.l   d0,d0
        add.l   d1,d0                    ; BGR24: aligned width*height*3
        move.l  d0,output_frame_bytes_expected
        cmp.l   output_buf_size_saved,d0
        bhi.w   v32f_build_fail

        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        moveq   #0,d0
        bra.s   v32f_build_done
v32f_build_fail:
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        moveq   #1,d0
v32f_build_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Apply pending mode once both old host output buffers are back.
v32f_try_switch_apply:
        movem.l d1-d3,-(sp)
        moveq   #0,d3
        tst.l   v32_resize_pending
        beq.w   v32f_try_done
        tst.l   output_bulk_queued
        bne.w   v32f_try_done
        tst.l   output_deferred_count
        bne.w   v32f_try_done
        tst.l   output_empty_requeue_pending
        bne.w   v32f_try_done
        jsr     v10j_count_output_dma_active
        tst.l   d0
        bne.w   v32f_try_done

        lea     msg_v32f_switch_begin,a1
        move.l  #msg_v32f_switch_begin_end-msg_v32f_switch_begin,d3
        jsr     print
        move.l  v32_pending_mode,d0
        jsr     print_hex32
        jsr     newline

        jsr     v32f_teardown_isp
        tst.l   d0
        bne.w   v32f_try_fail
        jsr     v32f_build_fresh_isp
        tst.l   d0
        bne.w   v32f_try_fail

        moveq   #0,d0
        jsr     h61_queue_output_idx
        tst.l   d0
        bne.w   v32f_try_fail
        moveq   #1,d0
        jsr     h61_queue_output_idx
        tst.l   d0
        bne.w   v32f_try_fail

        move.l  v32_pending_mode,d0
        move.l  d0,v32_fixed_mode
        clr.l   v32_pending_mode
        clr.l   v32_resize_pending
        addq.l  #1,v32_resize_applied
        jsr     v32f_resize_window_fixed

        lea     msg_v32f_switch_ok,a1
        move.l  #msg_v32f_switch_ok_end-msg_v32f_switch_ok,d3
        jsr     print
        move.l  v32_fixed_mode,d0
        jsr     print_hex32
        lea     msg_v32f_switch_target,a1
        move.l  #msg_v32f_switch_target_end-msg_v32f_switch_target,d3
        jsr     print
        move.l  output_crop_w_saved,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  output_crop_h_saved,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d3
        bra.s   v32f_try_done
v32f_try_fail:
        addq.l  #1,v32_resize_fail
        clr.l   v32_resize_pending
        clr.l   v32_pending_mode
        lea     msg_v32f_switch_fail,a1
        move.l  #msg_v32f_switch_fail_end-msg_v32f_switch_fail,d3
        jsr     print
        moveq   #1,d3
v32f_try_done:
        move.l  d3,d0
        movem.l (sp)+,d1-d3
        rts

        section data,data
msg_v32f_switch_request:
        dc.b "[HDMI_v41L] Feste Groesse angefordert, Modus=0x"
msg_v32f_switch_request_end:
msg_v32f_switch_target:
        dc.b "  Ziel=0x"
msg_v32f_switch_target_end:
msg_v32f_switch_begin:
        dc.b "[HDMI_v41L] ISP-Umschaltung startet; Decoder bleibt bestehen. Modus=0x"
msg_v32f_switch_begin_end:
msg_v32f_switch_ok:
        dc.b "[HDMI_v41L] ISP komplett neu aufgebaut; Wiedergabe laeuft weiter. Modus=0x"
msg_v32f_switch_ok_end:
msg_v32f_switch_fail:
        dc.b "[HDMI_v41L] FEHLER beim kontrollierten ISP-Neuaufbau; Stream wird abgebrochen.",10
msg_v32f_switch_fail_end:
        even


; ====================================================================
; HDMI_v41L RESTART / RESUME EXTENSION
; ====================================================================
        even
        section code,code

; D0=requested fixed mode 1/2. Save mode + current completed decoder output
; frame to T:, then request the existing controlled EOS path.
; D0=0 armed, 1 ignored/error.
v32r_request_restart:
        movem.l d1-d7/a0-a2/a6,-(sp)
        move.l  d0,d7
        cmpi.l  #10,d7
        beq.s   v32r_request_mode_ok
        cmpi.l  #25,d7
        beq.s   v32r_request_mode_ok
        cmpi.l  #50,d7
        beq.s   v32r_request_mode_ok
        cmpi.l  #75,d7
        beq.s   v32r_request_mode_ok
        cmpi.l  #100,d7
        beq.s   v32r_request_mode_ok
        cmpi.l  #110,d7
        beq.s   v32r_request_mode_ok
        cmpi.l  #120,d7
        beq.s   v32r_request_mode_ok
        cmpi.l  #201,d7
        beq.s   v32r_request_mode_ok
        cmpi.l  #202,d7
        beq.s   v32r_request_mode_ok
        cmpi.l  #203,d7
        bne.w   v32r_request_fail
v32r_request_mode_ok:
        move.l  d7,v32r_state_mode
        move.l  output_frame_total,d0
        move.l  d0,v32r_state_frame
        bsr     v32r_write_state
        tst.l   d0
        bne.w   v32r_request_fail
        move.l  #1,v32r_restart_armed
        move.l  #1,v15_stop_requested

        lea     msg_v32r_request,a1
        move.l  #msg_v32r_request_end-msg_v32r_request,d3
        jsr     print
        move.l  v32r_state_mode,d0
        jsr     print_hex32
        lea     msg_v32r_state_frame,a1
        move.l  #msg_v32r_state_frame_end-msg_v32r_state_frame,d3
        jsr     print
        move.l  v32r_state_frame,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d0
        bra.s   v32r_request_done
v32r_request_fail:
        lea     msg_v32r_write_fail,a1
        move.l  #msg_v32r_write_fail_end-msg_v32r_write_fail,d3
        jsr     print
        moveq   #1,d0
v32r_request_done:
        movem.l (sp)+,d1-d7/a0-a2/a6
        rts

; Binary state layout, 12 bytes big-endian/68k native:
;   +0 magic 'V40R' (legacy state signature retained), +4 mode, +8 completed decoder-output frame count.
v32r_write_state:
        movem.l d1-d4/a0-a1/a6,-(sp)
        lea     v32r_state_buf,a0
        move.l  #$56333252,(a0)          ; 'V40R'
        move.l  v32r_state_mode,4(a0)
        move.l  v32r_state_frame,8(a0)
        move.l  a5,a6
        lea     v32r_state_name,a0
        move.l  a0,d1
        move.l  #MODE_NEWFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.s   v32r_write_fail
        move.l  d0,v32r_state_handle
        move.l  d0,d1
        lea     v32r_state_buf,a0
        move.l  a0,d2
        moveq   #12,d3
        jsr     Write(a6)
        move.l  d0,v32r_state_io
        move.l  v32r_state_handle,d1
        jsr     Close(a6)
        clr.l   v32r_state_handle
        cmpi.l  #12,v32r_state_io
        bne.s   v32r_write_fail
        moveq   #0,d0
        bra.s   v32r_write_done
v32r_write_fail:
        move.l  v32r_state_handle,d0
        beq.s   v32r_write_fail_closed
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   v32r_state_handle
v32r_write_fail_closed:
        moveq   #1,d0
v32r_write_done:
        movem.l (sp)+,d1-d4/a0-a1/a6
        rts

; Load and validate T: state. D0=0 valid, 1 absent/bad.
v32r_load_state:
        movem.l d1-d4/a0-a1/a6,-(sp)
        clr.l   v32r_state_handle
        move.l  a5,a6
        lea     v32r_state_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   v32r_load_fail
        move.l  d0,v32r_state_handle
        move.l  d0,d1
        lea     v32r_state_buf,a0
        move.l  a0,d2
        moveq   #12,d3
        jsr     Read(a6)
        move.l  d0,v32r_state_io
        move.l  v32r_state_handle,d1
        jsr     Close(a6)
        clr.l   v32r_state_handle
        cmpi.l  #12,v32r_state_io
        bne.s   v32r_load_fail
        lea     v32r_state_buf,a0
        cmpi.l  #$56333252,(a0)
        bne.s   v32r_load_fail
        move.l  4(a0),d0
        ; V40O A/B: accept every supported fixed CLI mode so key 1 can rebuild
        ; the second run at exactly the same size as the first run.
        cmpi.l  #10,d0
        beq.s   v32r_load_mode_ok
        cmpi.l  #25,d0
        beq.s   v32r_load_mode_ok
        cmpi.l  #50,d0
        beq.s   v32r_load_mode_ok
        cmpi.l  #75,d0
        beq.s   v32r_load_mode_ok
        cmpi.l  #100,d0
        beq.s   v32r_load_mode_ok
        cmpi.l  #110,d0
        beq.s   v32r_load_mode_ok
        cmpi.l  #120,d0
        beq.s   v32r_load_mode_ok
        cmpi.l  #201,d0
        beq.s   v32r_load_mode_ok
        cmpi.l  #202,d0
        beq.s   v32r_load_mode_ok
        cmpi.l  #203,d0
        bne.s   v32r_load_fail
v32r_load_mode_ok:
        move.l  d0,v32r_state_mode
        move.l  8(a0),v32r_state_frame
        moveq   #0,d0
        bra.s   v32r_load_done
v32r_load_fail:
        move.l  v32r_state_handle,d0
        beq.s   v32r_load_fail_closed
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   v32r_state_handle
v32r_load_fail_closed:
        moveq   #1,d0
v32r_load_done:
        movem.l (sp)+,d1-d4/a0-a1/a6
        rts

v32r_delete_state:
        movem.l d1/a0/a6,-(sp)
        move.l  a5,a6
        lea     v32r_state_name,a0
        move.l  a0,d1
        jsr     DosDeleteFile(a6)
        movem.l (sp)+,d1/a0/a6
        rts

        section data,data
v32r_state_name:
        dc.b "T:hdmi_v41.state",0
        even
msg_v32r_request:
        dc.b "[mkvr7][RESTART] sauberer Neustart angefordert; T:hdmi_v41.state gespeichert; Modus=0x"
msg_v32r_request_end:
msg_v32r_state_frame:
        dc.b "  Decoderframe=0x"
msg_v32r_state_frame_end:
msg_v32r_write_fail:
        dc.b "[HDMI_v41L] FEHLER: Restart-State konnte nicht nach T: geschrieben werden; Wiedergabe bleibt unveraendert.",10
msg_v32r_write_fail_end:
msg_v32r_state_loaded:
        dc.b "[mkvr7][RESTART] State gelesen; neuer Startmodus=0x"
msg_v32r_state_loaded_end:
msg_v32r_state_bad:
        dc.b "[HDMI_v41L] Restart-State fehlt/ungueltig; falle auf normale Vorwahl 1/2 zurueck.",10
msg_v32r_state_bad_end:
        even

        section bss,bss
v32r_root_cli_len:       ds.l 1
v32r_root_cli_ptr:       ds.l 1
v32r_restart_cycle:      ds.l 1
v32r_restart_armed:      ds.l 1
v32r_restart_count:      ds.l 1
v32r_fastforward:        ds.l 1
v32r_resume_target:      ds.l 1
v32r_resume_reached:     ds.l 1
v32r_state_mode:         ds.l 1
v32r_state_frame:        ds.l 1
v32r_state_handle:       ds.l 1
v32r_state_io:           ds.l 1
v32r_state_buf:          ds.b 12
        even

        section code,code

; --------------------------------------------------------------------
; HDMI_v41L live fixed-size ISP OUTPUT switching.
;
; State 0: idle.
; State 1: stop feeding NEW H264 input, but keep ISP output buffers recycling
;          normally. Wait until every already-submitted decoder INPUT buffer
;          and input BULK transfer has returned. This prevents decoder-input
;          BUFFER_TO_HOST callbacks from racing a synchronous MMAL worker call.
; State 2: set v32_resize_pending=1 so the existing output callback path stops
;          requeueing returned ISP buffers. Wait until BOTH output slots are
;          back at the host and there is no BULK_RX/deferred/DMA ownership.
;          Then DISABLE -> PORT_INFO_SET -> ENABLE only ril.isp OUTPUT 0 and
;          re-prime the same preallocated slots with the NEW buffer size.
;
; Decoder OUTPUT -> ISP INPUT OPQV tunnel is never disabled/rebuilt.
; No AllocMem/FreeMem occurs during a size switch.
; --------------------------------------------------------------------
v40_resize_service:
        movem.l d1-d4,-(sp)

        move.l  v40_resize_state,d0
        beq.w   v40_resize_service_done

        ; A real user stop or natural EOF wins over a pending resize.
        tst.l   v15_stop_requested
        bne.w   v40_resize_cancel
        tst.l   input_eof_seen
        bne.w   v40_resize_cancel
        tst.l   eos_sent
        bne.w   v40_resize_cancel

        cmpi.l  #1,d0
        beq.w   v40_resize_phase1
        cmpi.l  #2,d0
        beq.w   v40_resize_phase2
        bra.w   v40_resize_cancel

v40_resize_phase1:
        ; New input feeding is already blocked by h25_check_input_recycle.
        ; Wait until no host->decoder DMA/BULK/input ownership remains.
        addq.l  #1,v40_resize_wait_count
        cmpi.l  #5000,v40_resize_wait_count
        bcc.w   v40_resize_phase1_timeout
        tst.l   input_bulk_pending
        bne.w   v40_resize_service_done
        tst.l   bulk_dma_active
        bne.w   v40_resize_service_done
        tst.l   input_in_use_count
        bne.w   v40_resize_service_done

        ; Now begin output quiesce. Returned output buffers are held by the
        ; already-existing v32_resize_pending checks in the callback path.
        clr.l   v32_resize_held
        clr.l   v40_resize_wait_count
        move.l  #1,v32_resize_pending
        move.l  #2,v40_resize_state
        addq.l  #1,v40_resize_input_drained
        lea     msg_v40_phase2,a1
        move.l  #msg_v40_phase2_end-msg_v40_phase2,d3
        jsr     print
        bra.w   v40_resize_service_done

v40_resize_phase2:
        ; Do not touch MMAL until every old output transfer/header/slot is back.
        addq.l  #1,v40_resize_wait_count
        cmpi.l  #5000,v40_resize_wait_count
        bcc.w   v40_resize_fail
        tst.l   output_bulk_queued
        bne.w   v40_resize_service_done
        tst.l   output_deferred_count
        bne.w   v40_resize_service_done
        tst.l   output_empty_requeue_pending
        bne.w   v40_resize_service_done
        tst.l   output_pagelist_dma_active
        bne.w   v40_resize_service_done
        ; mkvr7: do not enter synchronous graph surgery while PCM owns
        ; the globally serialized VCHIQ BULK transport.  Return to h19 so the
        ; pending BULK_TX_DONE is consumed first; the next poll retries here.
        tst.l   vpv39_audio_bulk_pending
        bne.w   v40_resize_service_done

        ; mkvr7: all NEW audio publishes are blocked while resize_state
        ; is non-zero. Reap completed slots now and wait until audio_render owns
        ; no PCM input buffers at all.  v003 entered synchronous MMAL control
        ; traffic with one renderer-owned audio slot still live; its asynchronous
        ; BUFFER_TO_HOST could race the context waiter and the second scheduler
        ; PORT_INFO_GET timed out.
        jsr     vpv47_audio_service
        tst.l   vpv47_inflight
        bne.w   v40_resize_service_done

        jsr     v10j_count_output_dma_active
        tst.l   d0
        bne.w   v40_resize_service_done

        ; mkvr7: v32_resize_held is diagnostic only.  A slot may already
        ; be host-owned when phase 2 begins and therefore never "return" after
        ; v32_resize_pending is asserted.  Requiring held==requested can then
        ; deadlock forever with one perfectly safe host-owned slot.  The real
        ; ownership proof is the set above: no queued/deferred/empty BULK_RX,
        ; no pagelist DMA, no per-slot output DMA and no audio BULK/inflight.

        lea     msg_v40_apply,a1
        move.l  #msg_v40_apply_end-msg_v40_apply,d3
        jsr     print
        move.l  v32_pending_mode,d0
        jsr     print_hex32
        lea     msg_v40_target,a1
        move.l  #msg_v40_target_end-msg_v40_target,d3
        jsr     print
        move.l  v32_resize_pending_w,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v32_resize_pending_h,d0
        jsr     print_hex32
        jsr     newline

        ; mkvr7: mode 203 changes graph topology instead of merely
        ; resizing ISP output. At this point both decoder INPUT ownership and
        ; both host P96 OUTPUT buffers are fully quiescent, so it is safe to
        ; replace decoder->ISP with decoder->scheduler->video_render without
        ; restarting the movie/decoder.
        cmpi.l  #203,v32_pending_mode
        bne.s   v41_live_c_not_apply
        jsr     v41_live_switch_to_c_apply
        tst.l   d0
        bne.w   v40_resize_fail
        move.l  #203,v32_fixed_mode
        clr.l   v32_pending_mode
        clr.l   v40_resize_state
        clr.l   v32_resize_pending
        clr.l   v32_resize_held
        clr.l   v40_resize_wait_count
        clr.l   v41_live_c_switch_pending
        addq.l  #1,v40_resize_success
        move.l  #1,v40_resume_feed_pending
        lea     msg_v41_live_c_ok,a1
        move.l  #msg_v41_live_c_ok_end-msg_v41_live_c_ok,d3
        jsr     print
        bra.w   v40_resize_service_done
v41_live_c_not_apply:

        ; Existing v25-era routine already has the important corrected order:
        ; PORT disable/set/get/enable -> publish NEW output_buf_size_saved ->
        ; only then h61_queue_output_idx. Thus CachePreDMA and MMAL capacity
        ; use the new size, not the old one.
        jsr     hdmi_v40o_reconfigure_isp
        tst.l   d0
        bne.w   v40_resize_fail

        move.l  v32_pending_mode,d0
        move.l  d0,v32_fixed_mode
        clr.l   v32_pending_mode
        clr.l   v40_resize_state
        clr.l   v32_resize_held
        clr.l   v40_resize_wait_count
        addq.l  #1,v40_resize_success
        move.l  #1,v40_resume_feed_pending
        jsr     v32f_resize_window_fixed

        lea     msg_v40_ok,a1
        move.l  #msg_v40_ok_end-msg_v40_ok,d3
        jsr     print
        move.l  v32_fixed_mode,d0
        jsr     print_hex32
        lea     msg_v40_target,a1
        move.l  #msg_v40_target_end-msg_v40_target,d3
        jsr     print
        move.l  output_crop_w_saved,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  output_crop_h_saved,d0
        jsr     print_hex32
        jsr     newline
        bra.w   v40_resize_service_done

v40_resize_phase1_timeout:
        ; Safe fallback: phase 2 has not started, ISP output buffers were still
        ; recycling normally and no MMAL port transaction has happened.
        addq.l  #1,v40_resize_phase1_timeouts
        clr.l   v40_resize_state
        clr.l   v40_resume_feed_pending
        clr.l   v41_live_c_switch_pending
        clr.l   v32_pending_mode
        clr.l   v32_resize_pending
        clr.l   v32_resize_held
        clr.l   v40_resize_wait_count
        lea     msg_v40_phase1_timeout,a1
        move.l  #msg_v40_phase1_timeout_end-msg_v40_phase1_timeout,d3
        jsr     print
        bra.w   v40_resize_service_done

v40_resize_fail:
        addq.l  #1,v40_resize_errors
        clr.l   v40_resize_state
        clr.l   v40_resume_feed_pending
        clr.l   v41_live_c_switch_pending
        clr.l   v32_pending_mode
        clr.l   v32_resize_pending
        clr.l   v40_resize_wait_count
        ; A failed live port transaction is not safe to continue blindly.
        ; Route through the already-proven controlled EOS/cleanup path.
        move.l  #1,v15_stop_requested
        move.l  #1,input_eof_seen
        lea     msg_v40_fail,a1
        move.l  #msg_v40_fail_end-msg_v40_fail,d3
        jsr     print
        bra.s   v40_resize_service_done

v40_resize_cancel:
        ; If stop/EOF arrives during phase 2, some ISP output buffers may
        ; already be host-owned and intentionally held. Re-offer exactly those
        ; inactive slots before leaving resize mode, so the proven EOS drain
        ; is not starved. A still-active slot will be requeued normally when
        ; its callback/BULK_RX completes because v32_resize_pending is cleared.
        move.l  v40_resize_state,d0
        cmpi.l  #2,d0
        bne.s   v40_resize_cancel_clear
        clr.l   v32_resize_pending
        moveq   #0,d1
v40_resize_cancel_requeue_loop:
        cmp.l   v10j_output_req_count,d1
        bcc.s   v40_resize_cancel_clear
        move.l  d1,d2
        lsl.l   #2,d2
        lea     output_dma_active_slots,a0
        tst.l   0(a0,d2.l)
        bne.s   v40_resize_cancel_next
        move.l  d1,d0
        jsr     h61_queue_output_idx
v40_resize_cancel_next:
        addq.l  #1,d1
        bra.s   v40_resize_cancel_requeue_loop
v40_resize_cancel_clear:
        clr.l   v40_resize_state
        clr.l   v40_resume_feed_pending
        clr.l   v41_live_c_switch_pending
        clr.l   v32_pending_mode
        clr.l   v32_resize_pending
        clr.l   v32_resize_held
        clr.l   v40_resize_wait_count
v40_resize_service_done:
        movem.l (sp)+,d1-d4
        rts

        section data,data
msg_v40_phase2:
        dc.b "[HDMI_v41L] Resize Phase 1 OK: Decoder-Inputs komplett zurueck; sammle jetzt ISP-Outputpuffer ein.",10
msg_v40_phase2_end:
msg_v40_apply:
        dc.b "[HDMI_v41L] LIVE ISP-OUTPUT Umschaltung startet. Modus=0x"
msg_v40_apply_end:
msg_v40_target:
        dc.b "  Ziel=0x"
msg_v40_target_end:
msg_v40_ok:
        dc.b "[HDMI_v41L] LIVE ISP-OUTPUT Umschaltung OK. Modus=0x"
msg_v40_ok_end:
msg_v40_phase1_timeout:
        dc.b "[HDMI_v41L] Resize verworfen: Decoder-Input wurde nicht vollstaendig ruhig; alte Groesse laeuft sicher weiter.",10
msg_v40_phase1_timeout_end:
msg_v40_fail:
        dc.b "[HDMI_v41L] FEHLER/Timeout bei LIVE ISP-OUTPUT Umschaltung; kontrollierter EOS/Cleanup wird erzwungen.",10
msg_v40_fail_end:
msg_v40a_reconfig_fail_stage:
        dc.b "[HDMI_v41L] Reconfigure-Abbruch in Stufe=0x"
msg_v40a_reconfig_fail_stage_end:
msg_v40a_reconfig_fail_d0:
        dc.b "  D0=0x"
msg_v40a_reconfig_fail_d0_end:
        even

        section bss,bss
v40_resize_state:         ds.l 1
v40_resize_input_drained: ds.l 1
v40_resize_success:       ds.l 1
v40_resize_errors:        ds.l 1
v40_resize_wait_count:    ds.l 1
v40_resize_phase1_timeouts: ds.l 1
v40_resume_feed_pending:   ds.l 1
v40a_reconfig_stage:       ds.l 1
v40a_reconfig_last_d0:     ds.l 1
v40c_blit_fail_reason:     ds.l 1
v40c_window_wait_skips:    ds.l 1
        even

        section code,code


; V40B diagnostic reconfigure routine moved to source end to keep the proven
; core/helper branch layout stable.
hdmi_v40o_reconfigure_isp_diag:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   v40a_reconfig_stage
        move.l  #1,v40a_reconfig_stage
        move.l  v12a_isp_handle,component_handle
        move.l  v12a_isp_output,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get

        move.l  #2,v40a_reconfig_stage
        move.l  v12a_isp_output,d0
        move.l  #MMAL_PORT_OUTPUT,d1
        bsr     v9_disable_port
        tst.l   d0
        bne.w   hdmi_v40o_diag_fail

        move.l  #3,v40a_reconfig_stage
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_BGR24,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v32_resize_pending_aw,port_video_width
        move.l  v32_resize_pending_ah,port_video_height
        clr.l   port_crop_x
        clr.l   port_crop_y
        move.l  v32_resize_pending_w,port_crop_width
        move.l  v32_resize_pending_h,port_crop_height
        move.l  v12a_dec_fps_num,port_fps_num
        move.l  v12a_dec_fps_den,port_fps_den
        moveq   #1,d0
        move.l  d0,port_par_num
        move.l  d0,port_par_den
        move.l  v12a_dec_colorspace,port_color_space
        moveq   #2,d0
        move.l  d0,port_buf_num
        move.l  v32_resize_pending_aw,d0
        move.l  v32_resize_pending_ah,d1
        mulu.w  d1,d0
        move.l  d0,d1
        add.l   d0,d0
        add.l   d1,d0                    ; BGR24: 3 bytes/pixel
        cmp.l   #OUTPUT_MAX_DMA,d0
        bhi.w   hdmi_v40o_diag_fail
        move.l  d0,port_buf_size
        move.l  #4,v40a_reconfig_stage
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   hdmi_v40o_diag_fail

        move.l  #5,v40a_reconfig_stage
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_BGR24,d0
        bne.w   hdmi_v40o_diag_fail

        move.l  #6,v40a_reconfig_stage
        move.l  v12a_isp_output,output_port_handle
        moveq   #2,d0
        move.l  d0,port_buf_num
        move.l  d0,v10j_output_req_count
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   hdmi_v40o_diag_fail
        move.l  #7,v40a_reconfig_stage
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        cmpi.l  #1,port_enabled
        bne.w   hdmi_v40o_diag_fail

        move.l  #8,v40a_reconfig_stage
        move.l  port_buf_size,output_buf_size_saved
        move.l  port_video_width,output_width_saved
        move.l  port_video_height,output_height_saved
        move.l  port_crop_x,output_crop_x_saved
        move.l  port_crop_y,output_crop_y_saved
        move.l  port_crop_width,output_crop_w_saved
        move.l  port_crop_height,output_crop_h_saved
        move.l  output_width_saved,d0
        move.l  output_height_saved,d1
        mulu.w  d1,d0
        move.l  d0,d1
        add.l   d0,d0
        add.l   d1,d0                    ; BGR24: aligned width*height*3
        move.l  d0,output_frame_bytes_expected
        cmp.l   output_buf_size_saved,d0
        bhi.w   hdmi_v40o_diag_fail

        move.l  #9,v40a_reconfig_stage
        moveq   #0,d0
        jsr     h61_queue_output_idx
        tst.l   d0
        bne.w   hdmi_v40o_diag_fail
        move.l  #10,v40a_reconfig_stage
        moveq   #1,d0
        jsr     h61_queue_output_idx
        tst.l   d0
        bne.w   hdmi_v40o_diag_fail

        addq.l  #1,v32_resize_applied
        clr.l   v32_resize_pending
        clr.l   v32_resize_stable
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        clr.l   v40a_reconfig_stage
        moveq   #0,d0
        bra.s   hdmi_v40o_diag_done
hdmi_v40o_diag_fail:
        move.l  d0,v40a_reconfig_last_d0
        lea     msg_v40a_reconfig_fail_stage,a1
        move.l  #msg_v40a_reconfig_fail_stage_end-msg_v40a_reconfig_fail_stage,d3
        jsr     print
        move.l  v40a_reconfig_stage,d0
        jsr     print_hex32
        lea     msg_v40a_reconfig_fail_d0,a1
        move.l  #msg_v40a_reconfig_fail_d0_end-msg_v40a_reconfig_fail_d0,d3
        jsr     print
        move.l  v40a_reconfig_last_d0,d0
        jsr     print_hex32
        jsr     newline
        move.l  #1,v32_resize_fail
        clr.l   v32_resize_pending
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        moveq   #1,d0
hdmi_v40o_diag_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts




; ====================================================================
; HDMI_v41L P96 blit diagnostics (appended to preserve core branch layout)
; reason: 1=P96 lib,2=data ptr,3=window,4=RPort,5=cropW,6=cropH,
;         7=clientW transient,8=clientH transient. 7/8 are normally skipped.
; ====================================================================
        even
        section code,code
v40c_report_blit_failure:
        movem.l d0-d4/a0-a1,-(sp)
        lea     msg_v40c_blit_fail,a1
        move.l  #msg_v40c_blit_fail_end-msg_v40c_blit_fail,d3
        jsr     print
        move.l  v40c_blit_fail_reason,d0
        jsr     print_hex32
        lea     msg_v40c_blit_crop,a1
        move.l  #msg_v40c_blit_crop_end-msg_v40c_blit_crop,d3
        jsr     print
        move.l  output_crop_w_saved,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  output_crop_h_saved,d0
        jsr     print_hex32
        move.l  hdmi_v40o_window_ptr,a0
        cmpa.l  #0,a0
        beq.s   v40c_report_no_window
        lea     msg_v40c_blit_window,a1
        move.l  #msg_v40c_blit_window_end-msg_v40c_blit_window,d3
        jsr     print
        clr.l   d0
        move.w  WIN_Width(a0),d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        clr.l   d0
        move.w  WIN_Height(a0),d0
        jsr     print_hex32
v40c_report_no_window:
        jsr     newline
        movem.l (sp)+,d0-d4/a0-a1
        rts

        section data,data
msg_v40c_blit_fail:
        dc.b "[HDMI_v41L] P96-Blitfehler Grund=0x"
msg_v40c_blit_fail_end:
msg_v40c_blit_crop:
        dc.b "  Video=0x"
msg_v40c_blit_crop_end:
msg_v40c_blit_window:
        dc.b "  Fenster=0x"
msg_v40c_blit_window_end:
        even


; ====================================================================
; HDMI_v41L CLI geometry + one-way fullscreen control
; Modes: 10/25/50/75/100 = source percent, 110=gfit, 120=gfull.
; ====================================================================
        even
        section code,code

; Parse optional second CLI token after the filename. Missing -> g25.
; Return D0=0 OK, D0=1 invalid. Result in v40j_cli_mode.
v40j_parse_size_arg:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  #25,v40j_cli_mode
        move.l  h264rgb_cli_ptr,a0
        move.l  h264rgb_cli_len,d7
        tst.l   d7
        beq.w   v40j_parse_size_ok
; skip leading whitespace
v40j_ps_skip0:
        tst.l   d7
        beq.w   v40j_parse_size_ok
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.s   v40j_ps_skip0_one
        cmpi.b  #9,d0
        bne.s   v40j_ps_first
v40j_ps_skip0_one:
        addq.l  #1,a0
        subq.l  #1,d7
        bra.s   v40j_ps_skip0
; skip first argument, honoring quotes
v40j_ps_first:
        moveq   #0,d6
        cmpi.b  #$22,d0
        bne.s   v40j_ps_first_loop
        moveq   #1,d6
        addq.l  #1,a0
        subq.l  #1,d7
v40j_ps_first_loop:
        tst.l   d7
        beq.w   v40j_parse_size_ok
        move.b  (a0)+,d0
        subq.l  #1,d7
        tst.b   d6
        beq.s   v40j_ps_first_plain
        cmpi.b  #$22,d0
        beq.s   v40j_ps_after_first
        bra.s   v40j_ps_first_loop
v40j_ps_first_plain:
        cmpi.b  #$20,d0
        beq.s   v40j_ps_after_first
        cmpi.b  #9,d0
        beq.s   v40j_ps_after_first
        cmpi.b  #10,d0
        beq.w   v40j_parse_size_ok
        cmpi.b  #13,d0
        beq.w   v40j_parse_size_ok
        bra.s   v40j_ps_first_loop
v40j_ps_after_first:
; skip whitespace before optional token
v40j_ps_skip1:
        tst.l   d7
        beq.w   v40j_parse_size_ok
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.s   v40j_ps_skip1_one
        cmpi.b  #9,d0
        bne.s   v40j_ps_token
v40j_ps_skip1_one:
        addq.l  #1,a0
        subq.l  #1,d7
        bra.s   v40j_ps_skip1
v40j_ps_token:
        lea     v40j_size_token,a1
        moveq   #0,d5
v40j_ps_copy:
        tst.l   d7
        beq.s   v40j_ps_copy_done
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.s   v40j_ps_copy_done
        cmpi.b  #9,d0
        beq.s   v40j_ps_copy_done
        cmpi.b  #10,d0
        beq.s   v40j_ps_copy_done
        cmpi.b  #13,d0
        beq.s   v40j_ps_copy_done
        cmpi.l  #4,d5                     ; v005: 4 statt 3, erlaubt "w:75"/"w:c"
        bcc.w   v40j_ps_overflow
        ; fold A-Z to lowercase, so C and c are both accepted.
        cmpi.b  #'A',d0
        bcs.s   v40j_ps_store
        cmpi.b  #'Z',d0
        bhi.s   v40j_ps_store
        ori.b   #$20,d0
v40j_ps_store:
        move.b  d0,(a1)+
        addq.l  #1,a0
        subq.l  #1,d7
        addq.l  #1,d5
        bra.s   v40j_ps_copy
v40j_ps_overflow:
        ; Token laenger als 4 Zeichen. v40j_size_token enthaelt zu diesem
        ; Zeitpunkt bereits die ersten 4 (schon klein geschriebenen)
        ; Zeichen. Beginnt es mit "t:", ist es (vermutlich) ein zu langes
        ; T:-Token an der Groessen-Position -> kein Fehler, Standardgroesse
        ; bleibt aktiv. Sonst wie bisher: ungueltige Groesse.
        lea     v40j_size_token,a1
        cmpi.b  #'t',(a1)
        bne.s   mkvr7_ps_overflow_not_time
        cmpi.b  #':',1(a1)
        beq.w   v40j_parse_size_ok
mkvr7_ps_overflow_not_time:
        ; VPr8: "resume" is six letters, so the legacy four-byte size-token
        ; scratch overflows after "resu". Treat that prefix as a non-size token;
        ; vpr8_parse_resume_arg validates the complete token independently.
        cmpi.b  #'r',(a1)
        bne.s   vpr8_ps_overflow_not_resume
        cmpi.b  #'e',1(a1)
        bne.s   vpr8_ps_overflow_not_resume
        cmpi.b  #'s',2(a1)
        bne.s   vpr8_ps_overflow_not_resume
        cmpi.b  #'u',3(a1)
        bne.s   vpr8_ps_overflow_not_resume
        ; At overflow A0 points at character 5 and D7 counts the remainder.
        ; Accept only exact "resume" followed by token end/whitespace.
        cmpi.l  #2,d7
        bcs.w   v40j_parse_size_fail
        move.b  (a0),d0
        ori.b   #$20,d0
        cmpi.b  #'m',d0
        bne.w   v40j_parse_size_fail
        move.b  1(a0),d0
        ori.b   #$20,d0
        cmpi.b  #'e',d0
        bne.w   v40j_parse_size_fail
        cmpi.l  #2,d7
        beq.w   v40j_parse_size_ok
        move.b  2(a0),d0
        cmpi.b  #$20,d0
        beq.w   v40j_parse_size_ok
        cmpi.b  #9,d0
        beq.w   v40j_parse_size_ok
        cmpi.b  #10,d0
        beq.w   v40j_parse_size_ok
        cmpi.b  #13,d0
        beq.w   v40j_parse_size_ok
        bra.w   v40j_parse_size_fail
vpr8_ps_overflow_not_resume:
        ; mkvr7: log:<filename> may be the first optional token. The dedicated
        ; scanner handles it and v005r4_parse_w_anywhere still finds W: later.
        cmpi.b  #'l',(a1)
        bne.w   v40j_parse_size_fail
        cmpi.b  #'o',1(a1)
        bne.w   v40j_parse_size_fail
        cmpi.b  #'g',2(a1)
        bne.w   v40j_parse_size_fail
        cmpi.b  #':',3(a1)
        bne.w   v40j_parse_size_fail
        bra.w   v40j_parse_size_ok

v40j_ps_copy_done:
        clr.b   (a1)
        lea     v40j_size_token,a0

        ; v005: optionales "W:"/"w:"-Praefix vor dem Groessen-Token. Die
        ; Gross/Klein-Faltung ist im Kopierloop schon passiert, daher reicht
        ; hier der Test auf Kleinbuchstabe 'w'. "75" und "w:75" landen damit
        ; auf demselben Vergleichspfad; die alte Schreibweise ohne "w:" bleibt
        ; unveraendert gueltig.
        cmpi.b  #'w',(a0)
        bne.s   v40j_ps_no_wprefix
        cmpi.b  #':',1(a0)
        bne.s   v40j_ps_no_wprefix
        addq.l  #2,a0
v40j_ps_no_wprefix:

        ; v005: an dieser Position darf auch ein T:-Token stehen (wenn kein
        ; Groessen-Token angegeben wurde). Kein Fehler, Standardgroesse (g25)
        ; bleibt aktiv; v40j_parse_time_arg wertet T: unabhaengig davon aus.
        cmpi.b  #'t',(a0)
        bne.s   v40j_ps_not_time
        cmpi.b  #':',1(a0)
        beq.w   v40j_parse_size_ok
v40j_ps_not_time:
        ; mkvr7: exact "log" at the first optional position keeps default 25.
        cmpi.b  #'l',(a0)
        bne.s   mkvr7_ps_not_log
        cmpi.b  #'o',1(a0)
        bne.s   mkvr7_ps_not_log
        cmpi.b  #'g',2(a0)
        bne.s   mkvr7_ps_not_log
        tst.b   3(a0)
        beq.w   v40j_parse_size_ok
mkvr7_ps_not_log:
        ; VPr8: exact "R" at the first optional position is a no-op here.
        ; The dedicated scanner loads the .t file later in the same CLI pass.
        cmpi.b  #'r',(a0)
        bne.s   vpr8_ps_not_r
        tst.b   1(a0)
        beq.w   v40j_parse_size_ok
vpr8_ps_not_r:

        ; V41L: only 10 / 25 / 50 / 75 / C remain.
        cmpi.b  #'c',(a0)
        bne.s   v41l_ps_not_c
        tst.b   1(a0)
        bne.w   v40j_parse_size_fail
        move.l  #203,v40j_cli_mode       ; direct VideoCore/HVS cinema
        move.l  #1,vpr8_cli_w_explicit
        bra.w   v40j_parse_size_ok
v41l_ps_not_c:
        cmpi.b  #'1',(a0)
        bne.s   v41l_ps_not_10
        cmpi.b  #'0',1(a0)
        bne.w   v40j_parse_size_fail
        tst.b   2(a0)
        bne.w   v40j_parse_size_fail
        move.l  #10,v40j_cli_mode
        move.l  #1,vpr8_cli_w_explicit
        bra.w   v40j_parse_size_ok
v41l_ps_not_10:
        cmpi.b  #'2',(a0)
        bne.s   v41l_ps_not_25
        cmpi.b  #'5',1(a0)
        bne.w   v40j_parse_size_fail
        tst.b   2(a0)
        bne.w   v40j_parse_size_fail
        move.l  #25,v40j_cli_mode
        move.l  #1,vpr8_cli_w_explicit
        bra.w   v40j_parse_size_ok
v41l_ps_not_25:
        cmpi.b  #'5',(a0)
        bne.s   v41l_ps_not_50
        cmpi.b  #'0',1(a0)
        bne.w   v40j_parse_size_fail
        tst.b   2(a0)
        bne.w   v40j_parse_size_fail
        move.l  #50,v40j_cli_mode
        move.l  #1,vpr8_cli_w_explicit
        bra.w   v40j_parse_size_ok
v41l_ps_not_50:
        cmpi.b  #'7',(a0)
        bne.w   v40j_parse_size_fail
        cmpi.b  #'5',1(a0)
        bne.w   v40j_parse_size_fail
        tst.b   2(a0)
        bne.w   v40j_parse_size_fail
        move.l  #75,v40j_cli_mode
        move.l  #1,vpr8_cli_w_explicit
v40j_parse_size_ok:
        moveq   #0,d0
        bra.s   v40j_parse_size_done
v40j_parse_size_fail:
        moveq   #1,d0
v40j_parse_size_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; ====================================================================
; mkvr7: find an explicit W: token anywhere after the filename.
; D0=0 OK/no W:, D0=1 malformed W: token.
; ====================================================================
v005r4_parse_w_anywhere:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  h264rgb_cli_ptr,a0
        move.l  h264rgb_cli_len,d7
        tst.l   d7
        beq.w   v005r4_pw_ok

v005r4_pw_skip0:
        tst.l   d7
        beq.w   v005r4_pw_ok
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.s   v005r4_pw_skip0_one
        cmpi.b  #9,d0
        bne.s   v005r4_pw_file
v005r4_pw_skip0_one:
        addq.l  #1,a0
        subq.l  #1,d7
        bra.s   v005r4_pw_skip0

v005r4_pw_file:
        moveq   #0,d6
        cmpi.b  #$22,d0
        bne.s   v005r4_pw_file_loop
        moveq   #1,d6
        addq.l  #1,a0
        subq.l  #1,d7
v005r4_pw_file_loop:
        tst.l   d7
        beq.w   v005r4_pw_ok
        move.b  (a0)+,d0
        subq.l  #1,d7
        tst.b   d6
        beq.s   v005r4_pw_file_plain
        cmpi.b  #$22,d0
        beq.s   v005r4_pw_next
        bra.s   v005r4_pw_file_loop
v005r4_pw_file_plain:
        cmpi.b  #$20,d0
        beq.s   v005r4_pw_next
        cmpi.b  #9,d0
        beq.s   v005r4_pw_next
        cmpi.b  #10,d0
        beq.w   v005r4_pw_ok
        cmpi.b  #13,d0
        beq.w   v005r4_pw_ok
        bra.s   v005r4_pw_file_loop

v005r4_pw_next:
        tst.l   d7
        beq.w   v005r4_pw_ok
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.s   v005r4_pw_ws
        cmpi.b  #9,d0
        bne.s   v005r4_pw_token
v005r4_pw_ws:
        addq.l  #1,a0
        subq.l  #1,d7
        bra.s   v005r4_pw_next

v005r4_pw_token:
        move.b  (a0),d0
        cmpi.b  #'A',d0
        bcs.s   v005r4_pw_folded
        cmpi.b  #'Z',d0
        bhi.s   v005r4_pw_folded
        ori.b   #$20,d0
v005r4_pw_folded:
        cmpi.b  #'w',d0
        bne.w   v005r4_pw_skip_token
        cmpi.l  #2,d7
        bcs.w   v005r4_pw_fail
        cmpi.b  #':',1(a0)
        bne.w   v005r4_pw_skip_token
        addq.l  #2,a0
        subq.l  #2,d7

        tst.l   d7
        beq.w   v005r4_pw_fail
        move.b  (a0),d0
        cmpi.b  #'A',d0
        bcs.s   v005r4_pw_value_folded
        cmpi.b  #'Z',d0
        bhi.s   v005r4_pw_value_folded
        ori.b   #$20,d0
v005r4_pw_value_folded:
        cmpi.b  #'c',d0
        bne.s   v005r4_pw_num
        addq.l  #1,a0
        subq.l  #1,d7
        move.l  #203,v40j_cli_mode
        move.l  #1,vpr8_cli_w_explicit
        bra.s   v005r4_pw_require_end

v005r4_pw_num:
        lea     v40j_size_token,a1
        moveq   #0,d5
v005r4_pw_num_copy:
        tst.l   d7
        beq.s   v005r4_pw_num_done
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.s   v005r4_pw_num_done
        cmpi.b  #9,d0
        beq.s   v005r4_pw_num_done
        cmpi.b  #10,d0
        beq.s   v005r4_pw_num_done
        cmpi.b  #13,d0
        beq.s   v005r4_pw_num_done
        cmpi.l  #2,d5
        bcc.w   v005r4_pw_fail
        move.b  d0,(a1)+
        addq.l  #1,a0
        subq.l  #1,d7
        addq.l  #1,d5
        bra.s   v005r4_pw_num_copy
v005r4_pw_num_done:
        clr.b   (a1)
        lea     v40j_size_token,a1
        cmpi.b  #'1',(a1)
        bne.s   v005r4_pw_not10
        cmpi.b  #'0',1(a1)
        bne.w   v005r4_pw_fail
        tst.b   2(a1)
        bne.w   v005r4_pw_fail
        move.l  #10,v40j_cli_mode
        move.l  #1,vpr8_cli_w_explicit
        bra.s   v005r4_pw_require_end
v005r4_pw_not10:
        cmpi.b  #'2',(a1)
        bne.s   v005r4_pw_not25
        cmpi.b  #'5',1(a1)
        bne.w   v005r4_pw_fail
        tst.b   2(a1)
        bne.w   v005r4_pw_fail
        move.l  #25,v40j_cli_mode
        move.l  #1,vpr8_cli_w_explicit
        bra.s   v005r4_pw_require_end
v005r4_pw_not25:
        cmpi.b  #'5',(a1)
        bne.s   v005r4_pw_not50
        cmpi.b  #'0',1(a1)
        bne.w   v005r4_pw_fail
        tst.b   2(a1)
        bne.w   v005r4_pw_fail
        move.l  #50,v40j_cli_mode
        move.l  #1,vpr8_cli_w_explicit
        bra.s   v005r4_pw_require_end
v005r4_pw_not50:
        cmpi.b  #'7',(a1)
        bne.w   v005r4_pw_fail
        cmpi.b  #'5',1(a1)
        bne.w   v005r4_pw_fail
        tst.b   2(a1)
        bne.w   v005r4_pw_fail
        move.l  #75,v40j_cli_mode
        move.l  #1,vpr8_cli_w_explicit

v005r4_pw_require_end:
        tst.l   d7
        beq.w   v005r4_pw_ok
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.w   v005r4_pw_next
        cmpi.b  #9,d0
        beq.w   v005r4_pw_next
        cmpi.b  #10,d0
        beq.w   v005r4_pw_ok
        cmpi.b  #13,d0
        beq.w   v005r4_pw_ok
        bra.w   v005r4_pw_fail

v005r4_pw_skip_token:
        tst.l   d7
        beq.w   v005r4_pw_ok
        move.b  (a0)+,d0
        subq.l  #1,d7
        cmpi.b  #$20,d0
        beq.w   v005r4_pw_next
        cmpi.b  #9,d0
        beq.w   v005r4_pw_next
        cmpi.b  #10,d0
        beq.w   v005r4_pw_ok
        cmpi.b  #13,d0
        beq.w   v005r4_pw_ok
        bra.s   v005r4_pw_skip_token

v005r4_pw_ok:
        moveq   #0,d0
        bra.s   v005r4_pw_done
v005r4_pw_fail:
        moveq   #1,d0
v005r4_pw_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; ====================================================================
; v005: T:-Startzeit-Token, unabhaengig von seiner Position nach dem
; Dateinamen (kann vor oder nach dem Groessen-Token stehen).
; Format nach "t:" (Gross/Klein egal): MM | MM:SS | HH:MM:SS.
; Ergebnis: v40j_start_time_valid/v40j_start_time_secs.
; Kein T:-Token gefunden -> valid bleibt 0, D0=0 (kein Fehler).
; T:-Token vorhanden, aber unlesbar -> D0=1.
; D0=0 OK, D0=1 invalid.
; ====================================================================
v40j_parse_time_arg:
        movem.l d1-d7/a0-a2,-(sp)
        clr.l   v40j_start_time_valid
        clr.l   v40j_start_time_secs
        move.l  h264rgb_cli_ptr,a0
        move.l  h264rgb_cli_len,d7
        tst.l   d7
        beq.w   v40j_pt_ok

; -- Whitespace vor Token 1 (Dateiname) ueberspringen --
v40j_pt_skip_file_ws:
        tst.l   d7
        beq.w   v40j_pt_ok
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.s   v40j_pt_skip_file_ws_one
        cmpi.b  #9,d0
        bne.s   v40j_pt_file_tok
v40j_pt_skip_file_ws_one:
        addq.l  #1,a0
        subq.l  #1,d7
        bra.s   v40j_pt_skip_file_ws

; -- Token 1 (Dateiname) ueberspringen, Anfuehrungszeichen beachten --
v40j_pt_file_tok:
        moveq   #0,d6
        cmpi.b  #$22,d0
        bne.s   v40j_pt_file_loop
        moveq   #1,d6
        addq.l  #1,a0
        subq.l  #1,d7
v40j_pt_file_loop:
        tst.l   d7
        beq.w   v40j_pt_ok
        move.b  (a0)+,d0
        subq.l  #1,d7
        tst.b   d6
        beq.s   v40j_pt_file_plain
        cmpi.b  #$22,d0
        beq.s   v40j_pt_next_token
        bra.s   v40j_pt_file_loop
v40j_pt_file_plain:
        cmpi.b  #$20,d0
        beq.s   v40j_pt_next_token
        cmpi.b  #9,d0
        beq.s   v40j_pt_next_token
        cmpi.b  #10,d0
        beq.w   v40j_pt_ok
        cmpi.b  #13,d0
        beq.w   v40j_pt_ok
        bra.s   v40j_pt_file_loop

; -- Ab hier: jedes weitere Leerzeichen-getrennte Token pruefen. --
; Ist es (klein geschrieben) "t:...", wird der Rest als Zeit geparst.
; Sonst wird das ganze Token uebersprungen und das naechste geprueft.
v40j_pt_next_token:
        tst.l   d7
        beq.w   v40j_pt_ok
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.s   v40j_pt_skip_ws_again
        cmpi.b  #9,d0
        bne.s   v40j_pt_tok_start
v40j_pt_skip_ws_again:
        addq.l  #1,a0
        subq.l  #1,d7
        bra.s   v40j_pt_next_token

v40j_pt_tok_start:
        moveq   #0,d6
        cmpi.b  #$22,d0
        bne.s   v40j_pt_check_prefix
        moveq   #1,d6
        addq.l  #1,a0
        subq.l  #1,d7

v40j_pt_check_prefix:
        ; Erstes Zeichen des Tokens auf 't'/'T' pruefen, ohne den Lesezeiger
        ; schon zu verbrauchen (Quote wurde ggf. schon uebersprungen).
        tst.l   d7
        beq.w   v40j_pt_ok
        move.b  (a0),d0
        cmpi.b  #'A',d0
        bcs.s   v40j_pt_c1
        cmpi.b  #'Z',d0
        bhi.s   v40j_pt_c1
        ori.b   #$20,d0
v40j_pt_c1:
        cmpi.b  #'t',d0
        bne.w   v40j_pt_skip_token
        move.l  a0,a1
        move.l  d7,d5
        cmpi.l  #1,d5
        beq.w   v40j_pt_skip_token
        move.b  1(a1),d0
        cmpi.b  #':',d0
        bne.w   v40j_pt_skip_token

        ; Treffer: "t:" gefunden. a0/d7 hinter "t:" weiterstellen und den
        ; Rest des Tokens als Zeitwert einlesen.
        addq.l  #2,a0
        subq.l  #2,d7
        bra.w   v40j_pt_parse_time

; -- kein T:-Token: das ganze aktuelle Token ueberspringen, weitersuchen --
v40j_pt_skip_token:
        tst.l   d7
        beq.w   v40j_pt_ok
        move.b  (a0)+,d0
        subq.l  #1,d7
        tst.b   d6
        beq.s   v40j_pt_skip_token_plain
        cmpi.b  #$22,d0
        beq.w   v40j_pt_next_token
        bra.s   v40j_pt_skip_token
v40j_pt_skip_token_plain:
        cmpi.b  #$20,d0
        beq.w   v40j_pt_next_token
        cmpi.b  #9,d0
        beq.w   v40j_pt_next_token
        cmpi.b  #10,d0
        beq.w   v40j_pt_ok
        cmpi.b  #13,d0
        beq.w   v40j_pt_ok
        bra.s   v40j_pt_skip_token

; -- Zeitwert nach "t:" einlesen: bis zu 3 Dezimalgruppen, getrennt durch ':' --
; MM  ->  1 Gruppe            (Minuten)
; MM:SS -> 2 Gruppen          (Minuten:Sekunden)
; HH:MM:SS -> 3 Gruppen       (Stunden:Minuten:Sekunden)
v40j_pt_parse_time:
        lea     v40j_time_groups,a2
        clr.l   (a2)
        clr.l   4(a2)
        clr.l   8(a2)
        moveq   #0,d4                    ; Anzahl bereits abgeschlossener Gruppen (0/1/2)
        moveq   #0,d5                    ; laufender Akkumulator der aktuellen Gruppe

v40j_pt_time_loop:
        tst.l   d7
        beq.s   v40j_pt_time_close
        move.b  (a0),d0
        cmpi.b  #$20,d0
        beq.s   v40j_pt_time_close
        cmpi.b  #9,d0
        beq.s   v40j_pt_time_close
        cmpi.b  #10,d0
        beq.s   v40j_pt_time_close
        cmpi.b  #13,d0
        beq.s   v40j_pt_time_close
        cmpi.b  #$22,d0
        beq.s   v40j_pt_time_close
        addq.l  #1,a0
        subq.l  #1,d7
        cmpi.b  #':',d0
        bne.s   v40j_pt_time_isdigit

        ; Doppelpunkt: aktuelle Gruppe ablegen, naechste Gruppe beginnen.
        ; Mehr als 2 Doppelpunkte (also mehr als 3 Gruppen) ist ungueltig.
        cmpi.l  #2,d4
        bcc.w   v40j_pt_time_fail
        move.l  d4,d1
        lsl.l   #2,d1
        move.l  d5,0(a2,d1.l)
        moveq   #0,d5
        addq.l  #1,d4
        bra.s   v40j_pt_time_loop

v40j_pt_time_isdigit:
        cmpi.b  #'0',d0
        bcs.w   v40j_pt_time_fail
        cmpi.b  #'9',d0
        bhi.w   v40j_pt_time_fail
        sub.b   #'0',d0
        and.l   #$000000FF,d0
        mulu.w  #10,d5
        add.l   d0,d5
        ; Jede Gruppe (Stunden/Minuten/Sekunden) auf <=999 begrenzen. Das
        ; reicht fuer jede realistische Laufzeit und haelt alle folgenden
        ; mulu.w-Schritte sicher innerhalb des 16-Bit-Quelloperanden.
        cmpi.l  #999,d5
        bls.s   v40j_pt_time_loop
        bra.w   v40j_pt_time_fail

v40j_pt_time_close:
        move.l  d4,d1
        lsl.l   #2,d1
        move.l  d5,0(a2,d1.l)

        ; Gesamtsekunden aus den (d4+1) Gruppen berechnen.
        move.l  (a2),d1
        tst.l   d4
        beq.s   v40j_pt_time_minutes_only
        cmpi.l  #1,d4
        beq.s   v40j_pt_time_min_sec
        ; 3 Gruppen: Stunden:Minuten:Sekunden
        mulu.w  #60,d1
        add.l   4(a2),d1
        mulu.w  #60,d1
        add.l   8(a2),d1
        bra.s   v40j_pt_time_have_secs
v40j_pt_time_min_sec:
        ; 2 Gruppen: Minuten:Sekunden
        mulu.w  #60,d1
        add.l   4(a2),d1
        bra.s   v40j_pt_time_have_secs
v40j_pt_time_minutes_only:
        ; 1 Gruppe: nur Minuten
        mulu.w  #60,d1
v40j_pt_time_have_secs:
        move.l  d1,v40j_start_time_secs
        move.l  #1,v40j_start_time_valid
        bra.w   v40j_pt_ok

v40j_pt_time_fail:
        clr.l   v40j_start_time_valid
        clr.l   v40j_start_time_secs
        moveq   #1,d0
        bra.s   v40j_pt_done

v40j_pt_ok:
        moveq   #0,d0
v40j_pt_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; ====================================================================
; v005: T:-Sekunden (v40j_start_time_secs) in eine Ziel-Videoblockzahl
; umrechnen, sobald die Container/SPS-FPS (v7_fps_num/v7_fps_den) bekannt
; sind. Ergebnis in v40j_start_time_blocks; bleibt 0, wenn keine gueltige
; T:-Zeit vorliegt oder die FPS (noch) unbekannt sind.
; Nur 16x16->32-Bit MULU/DIVU (reines 68000): fps wird zuerst auf eine
; ganze Zahl gerundet, danach ein einzelnes mulu.w mit den (auf 65535
; begrenzten) Sekunden. Ein paar Frames Abweichung sind fuer ein "ab
; ungefaehr hier abspielen" voellig ausreichend.
; ====================================================================
v40j_apply_start_time:
        movem.l d0-d4,-(sp)
        clr.l   v40j_start_time_blocks
        clr.l   v40j_time_target_ticks
        clr.l   v40j_time_target_us_lo
        clr.l   v40j_time_target_us_hi
        clr.l   v40j_time_target_input_count
        clr.l   v40j_time_target_input_valid
        clr.l   v40j_time_video_start_ticks
        clr.l   v40j_time_latest_video_ticks
        clr.l   v40j_time_latest_video_valid

        tst.l   v40j_start_time_valid
        beq.w   v40j_ast_done
        move.l  v40j_start_time_secs,d0
        tst.l   d0
        beq.w   v40j_ast_done

        ; R5 uses the same 1-ms Matroska PTS domain already proven by the
        ; player A/V scheduler.  When the early compressed scan found an IDR,
        ; that IDR PTS is the common media epoch.  Audio may begin a few ms
        ; later at its first AAC block, but no decoder fast-forward is needed.
        move.l  v10_timecode_scale,d4
        cmpi.l  #VPV43_TIMECODE_SCALE_MS,d4
        bne.w   v40j_ast_done

        tst.l   v005r5_seek_valid
        beq.s   v005r5_ast_no_preseek
        move.l  v005r5_seek_pts_ticks,d0
        bra.s   v005r4_ast_target_ready

v005r5_ast_no_preseek:
        cmpi.l  #65535,d0
        bls.s   v005r4_ast_secs_ok
        move.l  #65535,d0
v005r4_ast_secs_ok:
        mulu.w  #1000,d0                  ; fallback requested milliseconds
v005r4_ast_target_ready:
        move.l  d0,v40j_time_target_ticks
        move.l  d0,v40j_time_video_start_ticks

        ; MMAL buffer PTS is in microseconds. Convert 1-ms ticks to us exactly.
        move.l  #1000,d1
        jsr     vpv170_ticks_to_us64
        tst.l   d3
        bne.s   v005r4_ast_clear
        move.l  d0,v40j_time_target_us_lo
        move.l  d1,v40j_time_target_us_hi

        lea     msg_v005r4_time_target,a1
        move.l  #msg_v005r4_time_target_end-msg_v005r4_time_target,d3
        jsr     print
        move.l  v40j_time_target_ticks,d0
        jsr     print_hex32
        lea     msg_v005r4_time_target_us,a1
        move.l  #msg_v005r4_time_target_us_end-msg_v005r4_time_target_us,d3
        jsr     print
        move.l  v40j_time_target_us_hi,d0
        jsr     print_hex32
        move.l  v40j_time_target_us_lo,d0
        jsr     print_hex32
        jsr     newline
        bra.s   v40j_ast_done

v005r4_ast_clear:
        clr.l   v40j_time_target_ticks
        clr.l   v40j_time_target_us_lo
        clr.l   v40j_time_target_us_hi
v40j_ast_done:
        movem.l (sp)+,d0-d4
        rts



; R4 helper: unsigned MMAL microseconds D1:D0 -> 32-bit milliseconds D0.
; Movie-scale values keep the high 32-bit word <1000; quotient then fits u32.
; D1=0 success, D1=1 unsupported/overflow.
v005r4_us64_to_ms32:
        movem.l d2-d4,-(sp)
        move.l  d1,d2
        cmpi.l  #1000,d2
        bcc.s   v005r4_u64ms_fail
        clr.l   d3
        moveq   #31,d4
v005r4_u64ms_loop:
        add.l   d2,d2
        btst    d4,d0
        beq.s   v005r4_u64ms_no_bit
        addq.l  #1,d2
v005r4_u64ms_no_bit:
        cmpi.l  #1000,d2
        bcs.s   v005r4_u64ms_less
        subi.l  #1000,d2
        bset    d4,d3
v005r4_u64ms_less:
        dbra    d4,v005r4_u64ms_loop
        move.l  d3,d0
        moveq   #0,d1
        bra.s   v005r4_u64ms_done
v005r4_u64ms_fail:
        clr.l   d0
        moveq   #1,d1
v005r4_u64ms_done:
        movem.l (sp)+,d2-d4
        rts


; D0=mode. Results v32_calc_w/h/aw/ah. D0=0 OK, 1 invalid.
v40j_calc_mode_dims:
        movem.l d1-d7/a0,-(sp)
        clr.l   v41e_host_safe_cap
        move.l  d0,d7
        move.l  v12a_dec_crop_w,d1
        move.l  v12a_dec_crop_h,d2
        tst.l   d1
        beq.w   v40j_calc_fail
        tst.l   d2
        beq.w   v40j_calc_fail
        cmpi.l  #100,d7
        bls.s   v40j_calc_percent
        cmpi.l  #110,d7
        beq.w   v40j_calc_full
        cmpi.l  #120,d7
        beq.w   v40j_calc_full
        cmpi.l  #201,d7
        beq.w   v40j_calc_full
        cmpi.l  #202,d7
        beq.w   v40j_calc_full
        cmpi.l  #203,d7
        beq.w   v40j_calc_full
        bra.w   v40j_calc_fail
v40j_calc_percent:
        cmpi.l  #10,d7
        beq.s   v40j_calc_pct_ok
        cmpi.l  #25,d7
        beq.s   v40j_calc_pct_ok
        cmpi.l  #50,d7
        beq.s   v40j_calc_pct_ok
        cmpi.l  #75,d7
        beq.s   v40j_calc_pct_ok
        cmpi.l  #100,d7
        bne.w   v40j_calc_fail
v40j_calc_pct_ok:
        ; V41: gXX means XX percent of current WB/P96 area, preserving
        ; source aspect and NEVER enlarging above decoded source size.
        move.l  hdmi_v40o_wb_width,d4
        move.l  d4,d0
        mulu.w  d7,d0
        divu.w  #100,d0
        andi.l  #$0000ffff,d0
        move.l  d0,d4
        move.l  hdmi_v40o_wb_height,d5
        move.l  d5,d0
        mulu.w  d7,d0
        divu.w  #100,d0
        andi.l  #$0000ffff,d0
        move.l  d0,d5
        cmp.l   d4,d1
        bhi.s   v40j_calc_box_fit
        cmp.l   d5,d2
        bhi.s   v40j_calc_box_fit
        move.l  d1,d3
        move.l  d2,d6
        bra.w   v40j_calc_finish
v40j_calc_fit:
        ; gfit never enlarges above source size.
        jsr     v40j_get_full_box
        tst.l   d0
        bne.w   v40j_calc_fail
        cmp.l   d4,d1
        bhi.s   v40j_calc_box_fit
        cmp.l   d5,d2
        bhi.s   v40j_calc_box_fit
        move.l  d1,d3
        move.l  d2,d6
        bra.s   v40j_calc_finish
v40j_calc_full:
        ; N79P96 diagnostic: mode 202 is the explicit full-screen P96 test.
        ; Fit 736x416 to the complete Workbench box even when this is an
        ; upscale.  This keeps HVS video_render out of the path completely.
        jsr     v40j_get_full_box
        tst.l   d0
        bne.w   v40j_calc_fail
        cmpi.l  #202,d7
        beq.w   v40j_calc_box_fit
        ; Original VPr8 safety rule for all other full modes: downscale only.
        cmp.l   d4,d1
        bhi.s   v40j_calc_box_fit
        cmp.l   d5,d2
        bhi.s   v40j_calc_box_fit
        move.l  d1,d3
        move.l  d2,d6
        bra.s   v40j_calc_finish
v40j_calc_box_fit:
        ; Fit source aspect into D4 x D5.
        move.l  d4,d0
        mulu.w  d2,d0
        divu.w  d1,d0
        andi.l  #$0000ffff,d0
        cmp.l   d5,d0
        bhi.s   v40j_calc_fit_height
        move.l  d4,d3
        move.l  d0,d6
        bra.s   v40j_calc_finish
v40j_calc_fit_height:
        move.l  d5,d6
        move.l  d5,d0
        mulu.w  d1,d0
        divu.w  d2,d0
        andi.l  #$0000ffff,d0
        move.l  d0,d3
v40j_calc_finish:
        ; HDMI_v41L: host-facing modes 1/2 are deliberately capped to the
        ; hardware-proven 640x360 BGRA class. 1920x1080 -> 1280x720 created
        ; 0x00384000-byte buffers and stalled before usable output. Mode 3 is
        ; pure VideoCore/HVS and is not capped here.
        ; N79P96: mode 202 deliberately bypasses the historical 640x360
        ; host-facing cap so the ISP can produce the full borderless window.
        cmpi.l  #202,d7
        beq.s   v41e_host_cap_done
        cmpi.l  #201,d7
        bne.s   v41e_host_cap_done
v41e_host_cap_check:
        cmpi.l  #640,d3
        bhi.s   v41e_host_cap_apply
        cmpi.l  #360,d6
        bls.s   v41e_host_cap_done
v41e_host_cap_apply:
        move.l  #1,v41e_host_safe_cap
        move.l  #640,d4
        move.l  #360,d5
        ; Fit the decoded source aspect into 640x360.
        move.l  d4,d0
        mulu.w  d2,d0
        divu.w  d1,d0
        andi.l  #$0000ffff,d0
        cmp.l   d5,d0
        bhi.s   v41e_host_cap_height
        move.l  d4,d3
        move.l  d0,d6
        bra.s   v41e_host_cap_done
v41e_host_cap_height:
        move.l  d5,d6
        move.l  d5,d0
        mulu.w  d1,d0
        divu.w  d2,d0
        andi.l  #$0000ffff,d0
        move.l  d0,d3
v41e_host_cap_done:
        andi.l  #$fffffffe,d3
        andi.l  #$fffffffe,d6
        cmpi.l  #2,d3
        bcs.s   v40j_calc_fail
        cmpi.l  #2,d6
        bcs.s   v40j_calc_fail
        move.l  d3,v32_calc_w
        move.l  d6,v32_calc_h
        move.l  d3,d0
        add.l   #31,d0
        andi.l  #$ffffffe0,d0
        move.l  d0,v32_calc_aw
        move.l  d6,d0
        add.l   #15,d0
        andi.l  #$fffffff0,d0
        move.l  d0,v32_calc_ah
        ; VPv102 C-FIX: mode 203 never allocates a host BGRA/I420 output.
        ; Do not apply the host OUTPUT_MAX_DMA limit to the pure VideoCore/HVS path.
        cmpi.l  #203,d7
        beq.s   vpv98_c_dims_ok
        move.l  v32_calc_aw,d0
        move.l  v32_calc_ah,d4
        mulu.w  d4,d0
        lsl.l   #2,d0
        cmp.l   #OUTPUT_MAX_DMA,d0
        bhi.s   v40j_calc_fail
vpv98_c_dims_ok:
        moveq   #0,d0
        bra.s   v40j_calc_done
v40j_calc_fail:
        moveq   #1,d0
v40j_calc_done:
        movem.l (sp)+,d1-d7/a0
        rts

; Fullscreen client box = Workbench native area minus this window's borders.
; Return D4=box width, D5=box height, D0=0 OK.
v40j_get_full_box:
        movem.l d1-d3/a0,-(sp)
        move.l  hdmi_v40o_wb_width,d4
        move.l  hdmi_v40o_wb_height,d5
        cmpi.l  #64,d4
        bcs.s   v40j_full_box_fail
        cmpi.l  #36,d5
        bcs.s   v40j_full_box_fail
        moveq   #0,d0
        bra.s   v40j_full_box_done
v40j_full_box_fail:
        moveq   #1,d0
v40j_full_box_done:
        movem.l (sp)+,d1-d3/a0
        rts

; Called instead of old pre-start keyboard selector.
v40j_initial_cli_selector:
        clr.l   v32r_fastforward
        clr.l   v32r_resume_target
        clr.l   v32r_resume_reached
        ; mkvr7: T: is a true media-PTS target. Keep
        ; v32r_resume_target exclusively for the legacy state-file restart.
        tst.l   v40j_start_time_valid
        beq.s   v40j_no_start_time_ff
        move.l  v40j_time_target_ticks,d0
        tst.l   d0
        beq.s   v40j_no_start_time_ff
        move.l  #1,v40j_time_seek_active

        ; R5: a valid compressed IDR seek has already moved the file to the
        ; requested epoch.  Do NOT decode 1 minute invisibly again.  Publish
        ; resume_reached immediately so the ordinary PTS/audio gate can start
        ; on the first real output frame.
        tst.l   v005r5_seek_valid
        beq.s   v005r5_selector_legacy_ff
        move.l  #1,v32r_resume_reached
        bra.s   v40j_no_start_time_ff
v005r5_selector_legacy_ff:
        move.l  #1,v32r_fastforward
v40j_no_start_time_ff:
        clr.l   v40j_full_switched
        clr.l   v41_switch_done
        clr.l   v41_live_c_switch_pending
        move.l  v40j_cli_mode,d7
        ; C was already opened borderless/full-area before this selector.
        ; Keep display_style=3 and start video_render directly, with no restart.
        cmpi.l  #202,d7
        beq.s   n79p96_initial_fullfront_ready
        cmpi.l  #203,d7
        beq.s   v41l_initial_cinema_ready
        clr.l   v41_display_style
        bra.s   v41l_initial_style_ready
n79p96_initial_fullfront_ready:
        move.l  #2,v41_display_style
        bra.s   v41l_initial_style_ready
v41l_initial_cinema_ready:
        move.l  #3,v41_display_style
        lea     msg_vpv98_c_cli_enter,a1
        move.l  #msg_vpv98_c_cli_enter_end-msg_vpv98_c_cli_enter,d3
        jsr     vpv21n_trace
        jsr     hdmi_v41l_fill_cinema_black
v41l_initial_style_ready:
        move.l  d7,d0
        jsr     v40j_calc_mode_dims
        tst.l   d0
        beq.s   v40j_initial_calc_ok3
        jmp     v32_wait_mode_abort
v40j_initial_calc_ok3:
        move.l  d7,v32_fixed_mode
        move.l  v32_calc_w,v12a_target_w
        move.l  v32_calc_h,v12a_target_h
        move.l  v32_calc_aw,v12a_target_aw
        move.l  v32_calc_ah,v12a_target_ah
        lea     msg_v40j_start_mode,a1
        move.l  #msg_v40j_start_mode_end-msg_v40j_start_mode,d3
        jsr     print
        move.l  d7,d0
        jsr     print_hex32
        lea     msg_v40j_start_target,a1
        move.l  #msg_v40j_start_target_end-msg_v40j_start_target,d3
        jsr     print
        move.l  v12a_target_w,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_target_h,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d0
        jmp     v32_wait_mode_done

; V40O key 1: controlled restart into gfull. gfull is capped at source
; size, so this is never an ISP upscale beyond the decoded source.
v40j_request_full_once:
        movem.l d1-d4,-(sp)
        tst.l   v40j_full_switched
        bne.s   v40o_full_req_done
        move.l  #120,d0
        jsr     v40j_calc_mode_dims
        tst.l   d0
        bne.s   v40o_full_req_done
        ; Do not restart if target dimensions already equal current dimensions.
        move.l  v32_calc_w,d1
        cmp.l   v12a_target_w,d1
        bne.s   v40o_full_req_go
        move.l  v32_calc_h,d1
        cmp.l   v12a_target_h,d1
        beq.s   v40o_full_mark_done
v40o_full_req_go:
        move.l  #1,v40j_full_switched
        move.l  #120,d0
        jsr     v32r_request_restart
        bra.s   v40o_full_req_done
v40o_full_mark_done:
        move.l  #1,v40j_full_switched
v40o_full_req_done:
        movem.l (sp)+,d1-d4
        rts


; ====================================================================
; HDMI_v41L three-way one-shot display menu
; 201 = g100 normal window, 202 = V40R full-front borderless,
; 203 = direct VideoCore video_render -> HVS fullscreen (borderless event catcher).
; ====================================================================
v41_request_menu_once:
        movem.l d1-d4/a1,-(sp)
        tst.l   v41_switch_done
        bne.w   v41_request_menu_done
        cmpi.l  #203,d0
        bne.w   v41_request_menu_done
        ; mkvr7: C is now a true in-process graph switch.  Do NOT
        ; arm the old full process restart/resume path: once the modern
        ; video_scheduler owns MKV PTS that path can only catch up in real
        ; time and leaves the display black for the already-played duration.
        ; Instead reuse the proven two-phase live resize quiesce: stop NEW
        ; H264 input, drain all decoder inputs, then collect both host P96
        ; output buffers before touching the MMAL graph.
        move.l  d0,d4
        move.l  d4,d0
        jsr     v40j_calc_mode_dims
        tst.l   d0
        bne.w   v41_request_menu_done
        move.l  d4,v32_pending_mode
        move.l  v32_calc_w,v32_resize_pending_w
        move.l  v32_calc_h,v32_resize_pending_h
        move.l  v32_calc_aw,v32_resize_pending_aw
        move.l  v32_calc_ah,v32_resize_pending_ah
        clr.l   v32_resize_pending
        clr.l   v32_resize_held
        clr.l   v40_resize_wait_count
        move.l  #1,v41_live_c_switch_pending
        move.l  #1,v40_resize_state
        move.l  #1,v41_switch_done
        lea     msg_v41_live_c_request,a1
        move.l  #msg_v41_live_c_request_end-msg_v41_live_c_request,d3
        jsr     print
v41_request_menu_done:
        movem.l (sp)+,d1-d4/a1
        rts

; --------------------------------------------------------------------
; mkvr7 live P96 -> C graph switch.
; Preconditions are supplied by v40_resize_service phase 2:
;   * no decoder INPUT/BULK ownership remains
;   * both old P96 ISP output slots are host-owned and no BULK_RX is active
; Keep decoder, parser, audio renderer, central clock and current stream
; position alive. Only replace the downstream video graph.
; D0=0 success, D0=1 failure.
; --------------------------------------------------------------------
v41_live_switch_to_c_apply:
        movem.l d1-d7/a0-a3/a6,-(sp)
        lea     msg_v41_live_c_begin,a1
        move.l  #msg_v41_live_c_begin_end-msg_v41_live_c_begin,d3
        jsr     print

        ; Remove the old host-facing ISP branch while decoder state remains.
        jsr     v32f_teardown_isp
        tst.l   d0
        bne.w   v41_live_c_apply_fail

        ; Reopen only the Intuition event surface as borderless cinema.
        ; No stream restart/state file/fast-forward is involved.
        move.l  #203,d0
        jsr     v41_prepare_restart_style
        tst.l   d0
        bne.w   v41_live_c_apply_fail
        clr.l   v32r_fastforward
        clr.l   v32r_resume_target
        clr.l   v32r_resume_reached
        clr.l   v41b_renderer_reveal_pending
        move.l  #1,v41b_renderer_visible

        ; Preserve already-calculated fullscreen target for diagnostics/common
        ; graph globals, then create ril.video_render instead of ril.isp.
        move.l  v32_resize_pending_w,v12a_target_w
        move.l  v32_resize_pending_h,v12a_target_h
        move.l  v32_resize_pending_aw,v12a_target_aw
        move.l  v32_resize_pending_ah,v12a_target_ah
        jsr     v12a_create_isp
        tst.l   d0
        bne.w   v41_live_c_apply_fail

        ; mkvr7: this helper contains nested PORT_INFO_GET calls. Mark
        ; them as local graph transactions exactly like v12a_setup_isp_graph,
        ; so any timeout returns here instead of fatally unwinding into close_prog
        ; with this live-switch MOVEM frame still on the stack.
        move.l  #1,v12a_local_get_active
        jsr     v41b_setup_renderer_after_create
        clr.l   v12a_local_get_active
        tst.l   d0
        bne.w   v41_live_c_apply_fail

        ; Start C timing from 'now'. The scheduler/audio master already exists
        ; and retains its running clock; these are only host pacing diagnostics.
        clr.l   v04_clock_started
        clr.l   v04_clock_accum
        clr.l   v04_clock_target
        clr.l   v04_clock_counter
        clr.l   v41e_hr_started
        clr.l   v41e_hr_target
        clr.l   v41e_hr_accum
        clr.l   vpv98_timer_base_us
        clr.l   vpv98_timer_last_elapsed_us
        clr.l   vpv98_timer_target_us

        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        moveq   #0,d0
        bra.s   v41_live_c_apply_done
v41_live_c_apply_fail:
        clr.l   v12a_local_get_active
        lea     msg_v41_live_c_fail,a1
        move.l  #msg_v41_live_c_fail_end-msg_v41_live_c_fail,d3
        jsr     print
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        moveq   #1,d0
v41_live_c_apply_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; D0 = special restart mode. Set style and reopen the Intuition surface before
; the fixed ISP graph is created. Return D0=0 success.
v41_prepare_restart_style:
        movem.l d1-d3/a0/a6,-(sp)
        move.l  d0,d3
        cmpi.l  #202,d3
        beq.s   v41_style_fullfront
        cmpi.l  #203,d3
        beq.s   v41_style_direct
        move.l  #1,v41_display_style
        bra.s   v41_style_reopen
v41_style_fullfront:
        move.l  #2,v41_display_style
        bra.s   v41_style_reopen
v41_style_direct:
        move.l  #3,v41_display_style
v41_style_reopen:
        move.l  hdmi_v40o_window_ptr,a0
        cmpa.l  #0,a0
        beq.s   v41_style_open
        move.l  hdmi_v40o_intuition_base,a6
        cmpa.l  #0,a6
        beq.s   v41_style_fail
        jsr     IntuiCloseWindow(a6)
        clr.l   hdmi_v40o_window_ptr
v41_style_open:
        jsr     hdmi_v40o_open_window
        tst.l   d0
        bne.s   v41_style_fail
        cmpi.l  #3,v41_display_style
        bne.s   v41i_style_no_black
        jsr     hdmi_v41l_fill_cinema_black
v41i_style_no_black:
        moveq   #0,d0
        bra.s   v41_style_done
v41_style_fail:
        moveq   #1,d0
v41_style_done:
        movem.l (sp)+,d1-d3/a0/a6
        rts

; Patch the shared NewWindow definition immediately before OpenWindow.
v41_patch_newwindow_style:
        movem.l d0-d2/a0,-(sp)
        lea     hdmi_v40o_newwindow,a0
        cmpi.l  #2,v41_display_style
        bcc.s   v41_patch_borderless
        ; normal movable window
        move.w  #80,(a0)
        move.w  #60,2(a0)
        move.w  #216,4(a0)
        move.w  #144,6(a0)
        move.l  #IDCMP_CLOSEWINDOW|IDCMP_RAWKEY|IDCMP_VANILLAKEY,10(a0)
        move.l  #WFLG_DRAGBAR|WFLG_CLOSEGADGET|WFLG_ACTIVATE,14(a0)
        move.l  #hdmi_v40o_window_title,26(a0)
        move.w  #80,38(a0)
        move.w  #60,40(a0)
        move.w  #2047,42(a0)
        move.w  #1200,44(a0)
        bra.s   v41_patch_done
v41_patch_borderless:
        clr.w   (a0)
        clr.w   2(a0)
        move.l  hdmi_v40o_wb_width,d0
        move.w  d0,4(a0)
        move.l  hdmi_v40o_wb_height,d0
        move.w  d0,6(a0)
        move.l  #IDCMP_RAWKEY|IDCMP_VANILLAKEY,10(a0)
        move.l  #WFLG_BORDERLESS|WFLG_ACTIVATE,14(a0)
        clr.l   26(a0)
        move.w  #1,38(a0)
        move.w  #1,40(a0)
        move.w  #32767,42(a0)
        move.w  #32767,44(a0)
v41_patch_done:
        movem.l (sp)+,d0-d2/a0
        rts

; V41I cinema backdrop: fill the full borderless mode-3 window with
; OPAQUE black. The P96 screen is TrueAlpha on the target machine; color 0
; would be transparent black and expose the Emu68 background below it.
hdmi_v41l_fill_cinema_black:
        movem.l d0-d4/a0-a1/a6,-(sp)
        cmpi.l  #3,v41_display_style
        bne.s   v41i_black_done
        move.l  hdmi_v40o_window_ptr,a0
        cmpa.l  #0,a0
        beq.s   v41i_black_done
        move.l  hdmi_v40o_p96_base,a6
        cmpa.l  #0,a6
        beq.s   v41i_black_done
        move.l  WIN_RPort(a0),a1
        cmpa.l  #0,a1
        beq.s   v41i_black_done
        moveq   #0,d0
        moveq   #0,d1
        clr.l   d2
        move.w  WIN_Width(a0),d2
        subq.l  #1,d2
        clr.l   d3
        move.w  WIN_Height(a0),d3
        subq.l  #1,d3
        move.l  #$FF000000,d4          ; TrueAlpha: opaque RGB black
        jsr     P96RectFill(a6)
v41i_black_done:
        movem.l (sp)+,d0-d4/a0-a1/a6
        rts

; Mode 3: bypass p96WritePixelArray/RastPort and copy the already ISP-scaled
; BGRA frame straight into the active VideoCore.card/P96 framebuffer plane.
; The borderless front window remains only as a key-event catcher.
v41_direct_fb_blit:
        ; V41A: D0 is the function return value.  V41 accidentally saved and
        ; restored D0 here, so a successful direct copy could return an old
        ; non-zero D0 and the caller aborted with P96-Blitfehler Grund=0.
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   v40c_blit_fail_reason
        move.l  output_data_ptr,a0
        cmpa.l  #0,a0
        bne.s   v41_direct_have_data
        move.l  #$31,v40c_blit_fail_reason
        bra.w   v41_direct_fail
v41_direct_have_data:
        move.l  hdmi_v40o_wb_fb_cpu,a1
        cmpa.l  #0,a1
        bne.s   v41_direct_have_fb
        move.l  #$32,v40c_blit_fail_reason
        bra.w   v41_direct_fail
v41_direct_have_fb:
        move.l  output_crop_w_saved,d7
        move.l  output_crop_h_saved,d6
        tst.l   d7
        bne.s   v41_direct_have_w
        move.l  #$33,v40c_blit_fail_reason
        bra.w   v41_direct_fail
v41_direct_have_w:
        tst.l   d6
        bne.s   v41_direct_have_h
        move.l  #$34,v40c_blit_fail_reason
        bra.w   v41_direct_fail
v41_direct_have_h:
        ; source aligned stride
        move.l  output_width_saved,d4
        lsl.l   #2,d4
        move.l  output_crop_x_saved,d0
        lsl.l   #2,d0
        adda.l  d0,a0
        move.l  output_crop_y_saved,d0
        mulu.w  d4,d0
        adda.l  d0,a0
        ; center inside WB framebuffer
        move.l  hdmi_v40o_wb_width,d0
        sub.l   d7,d0
        bcc.s   v41_direct_width_ok
        move.l  #$35,v40c_blit_fail_reason
        bra.w   v41_direct_fail
v41_direct_width_ok:
        lsr.l   #1,d0
        lsl.l   #2,d0
        adda.l  d0,a1
        move.l  hdmi_v40o_wb_height,d0
        sub.l   d6,d0
        bcc.s   v41_direct_height_ok
        move.l  #$36,v40c_blit_fail_reason
        bra.w   v41_direct_fail
v41_direct_height_ok:
        lsr.l   #1,d0
        mulu.w  hdmi_v40o_wb_pitch,d0
        adda.l  d0,a1
        move.l  d7,d5
        lsl.l   #2,d5                 ; visible row bytes
        move.l  d4,d2
        sub.l   d5,d2                 ; source row skip
        move.l  hdmi_v40o_wb_pitch,d3
        sub.l   d5,d3                 ; destination row skip
        subq.l  #1,d6
v41_direct_row:
        move.l  d7,d1
        subq.l  #1,d1
v41_direct_pixel:
        move.l  (a0)+,(a1)+
        dbra    d1,v41_direct_pixel
        adda.l  d2,a0
        adda.l  d3,a1
        dbra    d6,v41_direct_row
        addq.l  #1,hdmi_v40o_rtg_frames
        moveq   #0,d0
        bra.s   v41_direct_done
v41_direct_fail:
        moveq   #1,d0
v41_direct_done:
        ; Do not restore D0: it carries the success/error result.
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

        section data,data
msg_v40j_bad_size:
        dc.b "[HDMI_v41L] FEHLER: Unbekannter Startparameter. Erlaubt: 10 25 50 75 C.",10
msg_v40j_bad_size_end:
msg_v40j_bad_time:
        dc.b "[mkvr7] FEHLER: Ungueltiges T:-Token. Erlaubt: T:MM, T:MM:SS, T:HH:MM:SS.",10
msg_v40j_bad_time_end:
msg_v005r4_time_target:
        dc.b "[mkvr7][T-PTS] effective common target ticks(ms)=0x"
msg_v005r4_time_target_end:
msg_v005r4_time_target_us:
        dc.b " MMAL-us hi:lo=0x"
msg_v005r4_time_target_us_end:
msg_v40j_start_mode:
        dc.b "[HDMI_v41L] CLI-Startmodus=0x"
msg_v40j_start_mode_end:
msg_v40j_start_target:
        dc.b "  ISP-Ziel=0x"
msg_v40j_start_target_end:
msg_v40j_key0_stop:
        dc.b "[HDMI_v41L] Taste Esc: sauberer Stop angefordert; Decoder-EOS/Cleanup folgt.",10
msg_v40j_key0_stop_end:
msg_vpx_pause_on:
        dc.b "[mkvr7][PAUSE] Leertaste: Wiedergabe angehalten (Leertaste = weiter).",10
msg_vpx_pause_on_end:
msg_vpx_pause_off:
        dc.b "[mkvr7][PAUSE] Leertaste: Wiedergabe laeuft weiter.",10
msg_vpx_pause_off_end:
msg_v40j_full_ignored:
        dc.b "[HDMI_v41L] Taste 1: gfull ist nicht groesser als die aktuelle Ausgabe; kein unsicherer Rueckwechsel wird ausgefuehrt.",10
msg_v40j_full_ignored_end:
        even

        section bss,bss
v40j_cli_mode:       ds.l 1
v40j_full_switched:  ds.l 1
v41_switch_done:     ds.l 1
v41_display_style:   ds.l 1
v40j_size_token:     ds.b 8
; v005: T:-Startzeit. secs/valid werden von v40j_parse_time_arg gefuellt;
; blocks (Ziel-Videoblockzahl) von v40j_apply_start_time, sobald die Container-
; FPS bekannt sind (nach v7_setup_timing).
v40j_start_time_valid:  ds.l 1
v40j_start_time_secs:   ds.l 1
v40j_start_time_blocks: ds.l 1       ; legacy field; R5 T: does not use it
v40j_time_target_ticks: ds.l 1       ; common A/V target, Matroska 1-ms ticks
v40j_time_target_us_lo: ds.l 1       ; same target in MMAL microseconds
v40j_time_target_us_hi: ds.l 1
v40j_time_seek_active:  ds.l 1       ; distinguishes T: from frame-count restart
v40j_time_target_input_count: ds.l 1 ; PTS-derived P96 fallback count
v40j_time_target_input_valid: ds.l 1
v40j_time_video_start_ticks: ds.l 1  ; visible post-T: media base for audio gate
v40j_time_latest_video_ticks: ds.l 1 ; exact displayed P96 PTS after T:
v40j_time_latest_video_valid: ds.l 1

; R5 compressed video seek state.  The early Matroska scan stores the first
; real H.264 IDR at/after T:.  Playback later reopens the file and DOS-Seek()s
; directly to the already-parsed AVC payload of that block.
v005r5_seek_valid:          ds.l 1
v005r5_seek_primed:         ds.l 1
v005r5_seek_request_ticks:  ds.l 1
v005r5_seek_pts_ticks:      ds.l 1
v005r5_seek_payload_pos:    ds.l 1
v005r5_seek_payload_len:    ds.l 1
v005r5_seek_cluster_end:    ds.l 1
v005r5_seek_blockgroup_end: ds.l 1
v005r5_seek_cluster_tc:     ds.l 1
v005r5_seek_segment_end:    ds.l 1
v005r5_scan_pos:            ds.l 1
v005r5_scan_len:            ds.l 1
v005r5_scan_pts:            ds.l 1
v005r5_scan_cluster_end:    ds.l 1
v005r5_scan_blockgroup_end: ds.l 1
v005r5_scan_cluster_tc:     ds.l 1
v005r5_scan_segment_end:    ds.l 1

v40j_time_groups:       ds.l 3
        even


; ====================================================================
; HDMI_v41L MODE 3 - DIRECT VIDEOCORE -> VIDEO_RENDER -> HVS
; ====================================================================
        even
        section code,code

; Called after v12a_create_isp has actually created ril.video_render when
; v41_display_style==3. v12a_isp_handle is deliberately reused as the peer
; component handle so the proven CONNECT/SET_REQUIREMENTS helpers can be used.
; No renderer output port and no host BGRA buffers exist in this mode.
v41b_setup_renderer_after_create:
        movem.l d1-d7/a0-a3,-(sp)

        ; Preserve the exact Workbench HVS list before video_render can own it.
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,hdmi_v40o_hvs_saved
        lea     msg_v41b_hvs_saved,a1
        move.l  #msg_v41b_hvs_saved_end-msg_v41b_hvs_saved,d3
        jsr     print
        move.l  hdmi_v40o_hvs_saved,d0
        jsr     print_hex32
        jsr     newline

        ; Renderer INPUT 0 receives the decoder's full OPQV surface.
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        lea     msg_vpv98_c_renderer_get,a1
        move.l  #msg_vpv98_c_renderer_get_end-msg_vpv98_c_renderer_get,d3
        jsr     vpv21n_trace
        jsr     port_info_get
        tst.l   d0
        bne.w   v41b_renderer_setup_fail
        move.l  port_last_handle,v12a_isp_input
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_OPAQUE,port_fmt_encoding
        move.l  v12c_dec_variant,port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v12a_dec_w,port_video_width
        move.l  v12a_dec_h,port_video_height
        move.l  v12a_dec_crop_x,port_crop_x
        move.l  v12a_dec_crop_y,port_crop_y
        move.l  v12a_dec_crop_w,port_crop_width
        move.l  v12a_dec_crop_h,port_crop_height
        move.l  v12a_dec_fps_num,port_fps_num
        move.l  v12a_dec_fps_den,port_fps_den
        move.l  v12a_dec_par_num,port_par_num
        move.l  v12a_dec_par_den,port_par_den
        move.l  v12a_dec_colorspace,port_color_space
        move.l  v12a_dec_buf_size,port_buf_size
        move.l  v12a_dec_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   v41b_renderer_num_ok
        moveq   #2,d0
v41b_renderer_num_ok:
        move.l  d0,port_buf_num
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v41b_renderer_setup_fail

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_input,d0
        bne.w   v41b_renderer_setup_fail
        cmpi.l  #MMAL_ENCODING_OPAQUE,port_fmt_encoding
        bne.w   v41b_renderer_setup_fail

        ; Hide the renderer while internal restart catch-up is active.
        clr.l   v41b_renderer_reveal_pending
        move.l  #1,v41b_renderer_visible
        tst.l   v32r_fastforward
        beq.s   v41b_renderer_visibility_ready
        clr.l   v41b_renderer_visible
v41b_renderer_visibility_ready:
        lea     msg_vpv98_c_displayregion,a1
        move.l  #msg_vpv98_c_displayregion_end-msg_vpv98_c_displayregion,d3
        jsr     vpv21n_trace
        jsr     hdmi_v40o_set_displayregion
        tst.l   d0
        bne.w   v41b_renderer_setup_fail

        ; N79 library path: unlike N24, use the CURRENT hardware-proven VPr8
        ; C graph construction.  The MintVID bridge supplies MMAL-usec PTS on
        ; every FRAME_START, so the old Matroska-private v10b_* gate is not
        ; applicable here.  Build decoder -> video_scheduler -> video_render
        ; now; the Audio-Master clock is armed later, only after the first real
        ; PCM block has been published (N79 prime-2 startup).
        tst.l   bvp_library_mode
        beq.s   n80_c_standalone
        ; N80 (MintVID): the scheduler only shows a frame once the
        ; Audio-Master clock runs, and only ConfigAudio arms that clock.  A
        ; stream without HDMI audio (mrberry --no-audio, or --paula where the
        ; Amiga plays the sound) never calls ConfigAudio, so its first AU was
        ; deferred forever.  Such streams take the direct decoder -> renderer
        ; tunnel instead; n66_service_pending_video then paces them with the
        ; host frame grid (n70_*), as standalone C mode does for MP4 input.
        ; The caller says so in OpenStream (BVP_OPENF_NO_HDMI_AUDIO): the
        ; graph is built before ConfigAudio, so n73_clock_armed is always 0
        ; here and cannot tell the two cases apart.
        tst.l   n80_no_hdmi_audio
        beq.w   n73_library_scheduler_enable
        lea     n80_msg_direct_no_audio,a1
        jsr     n12_log
        bra.w   vpv166_c_direct_legacy
n80_c_standalone:

        ; R5: normal C keeps decoder -> scheduler -> renderer.  A successful
        ; compressed IDR seek is already positioned at the target, therefore
        ; C+T uses the SAME normal scheduler path as C without T:.  Only the
        ; fallback legacy hidden-fast-forward path uses direct renderer input.
        tst.l   v40j_time_seek_active
        beq.s   v005r5_c_time_ready
        tst.l   v005r5_seek_valid
        beq.s   vpv166_c_direct_legacy
v005r5_c_time_ready:
        tst.l   v10b_input_is_mkv
        beq.s   vpv166_c_direct_legacy
        move.l  v10_timecode_scale,d0
        cmpi.l  #VPV43_TIMECODE_SCALE_MS,d0
        bne.s   vpv179_c_fast_fallback
        tst.l   v10_first_pts_found
        beq.s   vpv179_c_fast_fallback

n73_library_scheduler_enable:
        jsr     vpv126_setup_scheduler_data_graph
        tst.l   d0
        bne.w   v41b_renderer_setup_fail
        move.l  #1,n73_scheduler_graph_ready
        move.l  #1,vpv166_c_sched_feedahead
        lea     n73_msg_sched_graph_ready,a1
        jsr     n12_log
        bra.w   vpv166_c_renderer_input_ready

vpv179_c_scheduler_enable:
        jsr     vpv126_setup_scheduler_data_graph
        tst.l   d0
        bne.w   v41b_renderer_setup_fail
        move.l  #1,vpv166_c_sched_feedahead
        move.l  #1,vpv179_mkv_c_fast_active
        lea     msg_vpv179_mkv_c_fast_ok,a1
        move.l  #msg_vpv179_mkv_c_fast_ok_end-msg_vpv179_mkv_c_fast_ok,d3
        jsr     print_force
vpv179_c_fast_msg_common:
        lea     msg_vpv166_c_feedahead_ok,a1
        move.l  #msg_vpv166_c_feedahead_ok_end-msg_vpv166_c_feedahead_ok,d3
        jsr     print_force
        bra.w   vpv166_c_renderer_input_ready

vpv179_c_fast_fallback:
        addq.l  #1,vpv179_mkv_c_fast_fallbacks
        lea     msg_vpv179_mkv_c_fast_fallback,a1
        move.l  #msg_vpv179_mkv_c_fast_fallback_end-msg_vpv179_mkv_c_fast_fallback,d3
        jsr     print_force

vpv166_c_direct_legacy:
        ; Legacy direct decoder OPQV output -> video_render input tunnel.
        lea     msg_vpv98_c_connect,a1
        move.l  #msg_vpv98_c_connect_end-msg_vpv98_c_connect,d3
        jsr     vpv21n_trace
        jsr     v12a_connect_ports
        tst.l   d0
        bne.w   v41b_renderer_setup_fail

        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_input,d0
        bne.w   v41b_renderer_setup_fail
        jsr     v12a_set_isp_requirements
        tst.l   d0
        bne.w   v41b_renderer_setup_fail

        ; Enabling the connected decoder OUTPUT enables renderer INPUT.
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_decoder_output,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   v41b_renderer_dec_num_ok
        moveq   #2,d0
v41b_renderer_dec_num_ok:
        move.l  d0,port_buf_num
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   v41b_renderer_setup_fail

        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        cmpi.l  #1,port_enabled
        bne.w   v41b_renderer_setup_fail

vpv166_c_renderer_input_ready:
        ; Renderer component itself must run, but exposes no host output buffer.
        jsr     component_enable_worker
        tst.l   d0
        bne.w   v41b_renderer_setup_fail

        clr.l   output_component_handle
        clr.l   output_port_handle
        clr.l   output_buf_size_saved
        clr.l   output_width_saved
        clr.l   output_height_saved
        clr.l   output_crop_w_saved
        clr.l   output_crop_h_saved
        clr.l   output_frame_bytes_expected
        clr.l   v10j_output_req_count

        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        lea     msg_v41b_renderer_ok,a1
        move.l  #msg_v41b_renderer_ok_end-msg_v41b_renderer_ok,d3
        jsr     print
        lea     msg_v41e_hr_timing,a1
        move.l  #msg_v41e_hr_timing_end-msg_v41e_hr_timing,d3
        jsr     print
        moveq   #0,d0
        bra.s   v41b_renderer_setup_done

v41b_renderer_setup_fail:
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        lea     msg_v41b_renderer_fail,a1
        move.l  #msg_v41b_renderer_fail_end-msg_v41b_renderer_fail,d3
        jsr     print
        moveq   #1,d0
v41b_renderer_setup_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

 ; While renderer alpha is zero, count already-consumed source units.
; MKV uses the existing video-block counter. Once the saved restart position
; is reached, reveal the HVS renderer and resume real-time playback.
v41b_renderer_maybe_show:
        movem.l d0-d3/a1,-(sp)

        ; If the target was already reached on an earlier pass, remain paused
        ; and wait until the normal dispatcher has returned every outstanding
        ; input buffer and completed the serialized BULK_TX.
        tst.l   v41b_renderer_reveal_pending
        bne.s   v41b_renderer_reveal_wait_quiet

        tst.l   v32r_fastforward
        beq.w   v41b_renderer_show_done

        ; R5 T: direct-C catch-up uses the exact PTS of the last submitted AU.
        tst.l   v40j_time_seek_active
        beq.s   v005r4_c_legacy_target
        tst.l   v10b_pts_valid
        beq.w   v41b_renderer_show_done
        move.l  v10b_last_pts_ticks,d0
        cmp.l   v40j_time_target_ticks,d0
        bcs.w   v41b_renderer_show_done
        bra.s   v41b_renderer_target_reached

v005r4_c_legacy_target:
        move.l  v32r_resume_target,d1
        tst.l   d1
        beq.s   v41b_renderer_target_reached
v41b_renderer_check_mkv:
        tst.l   v10b_input_is_mkv
        beq.s   v41b_renderer_raw_count
        move.l  v10b_video_block_count,d0
        bra.s   v41b_renderer_count_ready
v41b_renderer_raw_count:
        move.l  input_bulk_total,d0
v41b_renderer_count_ready:
        cmp.l   d1,d0
        bcs.w   v41b_renderer_show_done

v41b_renderer_target_reached:
        move.l  #1,v41b_renderer_reveal_pending

v41b_renderer_reveal_wait_quiet:
        ; Do not issue a synchronous MMAL_PORT_PARAMETER_SET while a stream
        ; callback can still be at the head of the VCHIQ RX queue.  These three
        ; counters are cleared only by the normal h19 dispatcher.
        tst.l   input_bulk_pending
        bne.w   v41b_renderer_show_done
        tst.l   bulk_dma_active
        bne.w   v41b_renderer_show_done
        tst.l   input_in_use_count
        bne.w   v41b_renderer_show_done

        clr.l   v32r_fastforward
        move.l  #1,v32r_resume_reached
        ; Hidden direct-C catch-up incremented v04_paced_frames while invisible.
        ; Start the visible epoch at one target frame; the first PCM block can
        ; therefore enter on this same common media PTS.
        tst.l   v40j_time_seek_active
        beq.s   v005r4_c_reveal_counter_done
        move.l  #1,v04_paced_frames
        clr.l   v41e_hr_started
        clr.l   v41e_hr_target
        clr.l   v41e_hr_accum
        clr.l   vpv98_timer_base_us
        clr.l   vpv98_timer_last_elapsed_us
        clr.l   vpv98_timer_target_us
v005r4_c_reveal_counter_done:
        move.l  #1,v41b_renderer_visible
        ; V41I: reassert opaque black after the hidden pre-roll, immediately
        ; before revealing video_render. TrueAlpha needs alpha=$FF, not $00.
        jsr     hdmi_v41l_fill_cinema_black
        jsr     hdmi_v40o_set_displayregion
        tst.l   d0
        bne.s   v41b_renderer_show_fail
        clr.l   v41b_renderer_reveal_pending
        lea     msg_v41b_renderer_visible,a1
        move.l  #msg_v41b_renderer_visible_end-msg_v41b_renderer_visible,d3
        jsr     print
        bra.w   v41b_renderer_show_done
v41b_renderer_show_fail:
        clr.l   v41b_renderer_reveal_pending
        move.l  #1,v15_stop_requested
        lea     msg_v41b_renderer_show_fail,a1
        move.l  #msg_v41b_renderer_show_fail_end-msg_v41b_renderer_show_fail,d3
        jsr     print
v41b_renderer_show_done:
        movem.l (sp)+,d0-d3/a1
        rts

