; ====================================================================
; VPv06 - SAFE FREEMEM FIX AUF BASIS DES HARDWARE-BESTAETIGTEN VPv05
; Base: HDMI_v41L VCHIQ/MMAL transport. No movie parser, no H264 decoder.
;
; Goal for real hardware:
;   VPv06 -> unveraenderter VPv05-Audiopfad + sichere Exec-Speicherfreigabe
;
; PCM: 48 kHz, stereo, signed 16-bit little-endian.
; One 0.25-s buffer = 12000 stereo frames = 48000 bytes, sent 8 times.
; Total nominal tone duration: 2.0 seconds.
; ====================================================================
VPV01_AUDIO_RATE       equ 48000
VPV01_AUDIO_CHANNELS   equ 2
VPV01_AUDIO_BITS       equ 16
VPV01_AUDIO_BLOCKALIGN equ 4
VPV01_AUDIO_BITRATE    equ 1536000
VPV01_TONE_FRAMES      equ 12000
VPV01_TONE_BYTES       equ 48000
VPV01_TONE_REPEATS     equ 8
VPV01_TONE_PHASE_MOD   equ 1200       ; 48000/440 = 1200/11
VPV01_TONE_PHASE_STEP  equ 11
VPV01_TONE_HALF        equ 600
VPV01_BUFFER_CONTEXT   equ $A0300001

        section bss,bss
