        section code,code

; VPv06 ignores CLI arguments. Enter the same VCHIQ attach/init decision used
; by HDMI_v41L, but without touching file/container/video state.
vpv01_bootstrap:
        clr.l   v15_stop_requested
        clr.l   vpx_pause_active
        clr.l   vpx_pause_total_us
        clr.l   vpx_pause_count
        clr.l   vpx_pause_stamp_valid
        clr.l   vpx_resume_kick
        clr.l   v9m_ham_lut_ptr
        clr.l   v9m_edge_lut_ptr
        clr.l   v9m_state_lut_ptr
        clr.l   vpv01_audio_handle
        clr.l   vpv01_audio_input
        clr.l   vpv01_audio_control
        clr.l   vpv01_component_enabled
        clr.l   vpv01_test_status
        jmp     vpv01_vchiq_entry

; First-start GET_VERSION returns here with shared slot RAM CPU-owned.
vpv01_first_mmal_ready:
        jsr     vpv01_audio_test
        jmp     v9d_attach_exit

; Orchestrate one complete renderer/tone/cleanup pass.
vpv01_audio_test:
        jmp     vpv19_audio_test

vpv01_audio_test_v06_legacy:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv01_test_status
        clr.l   vpv01_component_enabled
        clr.l   vpv01_audio_handle
        clr.l   vpv01_audio_input
        clr.l   vpv01_audio_control

        lea     msg_vpv01_mmal_ready,a1
        move.l  #msg_vpv01_mmal_ready_end-msg_vpv01_mmal_ready,d3
        jsr     print_force

        jsr     vpv01_create_audio_render
        tst.l   d0
        bne.w   vpv01_test_fail

        jsr     vpv01_configure_audio_render
        tst.l   d0
        bne.w   vpv01_test_fail

        jsr     vpv01_prepare_tone
        tst.l   d0
        bne.w   vpv01_test_fail

        lea     msg_vpv01_tone_begin,a1
        move.l  #msg_vpv01_tone_begin_end-msg_vpv01_tone_begin,d3
        jsr     print_force

        moveq   #VPV01_TONE_REPEATS-1,d7
vpv01_tone_repeat_loop:
        jsr     vpv01_send_tone_block
        tst.l   d0
        bne.w   vpv01_test_fail
        jsr     vpv01_wait_tone_block
        tst.l   d0
        bne.w   vpv01_test_fail
        dbra    d7,vpv01_tone_repeat_loop

        ; Let the HDMI renderer drain the last internally queued samples.
        jsr     dma_pre_all
        move.l  a5,a6
        move.l  #10,d1
        jsr     Delay(a6)
        jsr     dma_post_all

        lea     msg_vpv01_tone_ok,a1
        move.l  #msg_vpv01_tone_ok_end-msg_vpv01_tone_ok,d3
        jsr     print_force
        bra.w   vpv01_test_cleanup

vpv01_test_fail:
        move.l  #1,vpv01_test_status
        lea     msg_vpv01_fail,a1
        move.l  #msg_vpv01_fail_end-msg_vpv01_fail,d3
        jsr     print_force

vpv01_test_cleanup:
        jsr     vpv01_cleanup
        move.l  vpv01_test_status,d0
        tst.l   d0
        bne.w   vpv01_test_done
        lea     msg_vpv01_done,a1
        move.l  #msg_vpv01_done_end-msg_vpv01_done,d3
        jsr     print_force
vpv01_test_done:
        move.l  vpv01_test_status,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; ------------------------------------------------------------
; Create ril.audio_render over whichever MMAL local service is active.
; ------------------------------------------------------------
vpv01_create_audio_render:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv01_create_status
        clr.l   vpv01_create_size
        clr.l   vpv01_param_status      ; VPv06: CREATE fail-stage (reuse, no new BSS)
        clr.l   vpv01_last_rx_msgid     ; VPv06: header status (reuse, no new BSS)

        tst.l   v12f_local_port
        beq.w   vpv01_create_tx_legacy
        move.l  #168,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        beq.w   vpv01_create_tx_ready
        move.l  #1,vpv01_param_status
        bra.w   vpv01_create_fail
vpv01_create_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
vpv01_create_tx_ready:
        move.l  a2,a0
        moveq   #41,d7
vpv01_create_clear:
        clr.l   (a0)+
        dbra    d7,vpv01_create_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #160,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_COMPONENT_CREATE,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$A0100001,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #$A011A1A1,d0
        jsr     store_le32
        lea     36(a2),a0
        lea     vpv01_audio_render_name,a1
        moveq   #16,d7               ; 16 chars + NUL = 17 bytes
vpv01_create_name:
        move.b  (a1)+,(a0)+
        dbra    d7,vpv01_create_name

        add.l   #168,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.w   vpv01_create_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv01_create_wait_setup:
        move.l  #V10_CLEANUP_POLL_COUNT,d7
vpv01_create_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.w   vpv01_create_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv01_create_wait
        jsr     dma_post_all
        move.l  #2,vpv01_param_status
        bra.w   vpv01_create_fail
vpv01_create_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        beq.w   vpv04_create_rx_mapped
        move.l  #3,vpv01_param_status
        bra.w   vpv01_create_fail
vpv04_create_rx_mapped:
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_create_size
        cmp.l   #44,d0
        bcc.w   vpv04_create_size_ok
        move.l  #4,vpv01_param_status
        bra.w   vpv01_create_fail
vpv04_create_size_ok:
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        beq.w   vpv04_create_magic_ok
        move.l  #5,vpv01_param_status
        bra.w   vpv01_create_fail_consume
vpv04_create_magic_ok:
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_COMPONENT_CREATE,d0
        beq.w   vpv04_create_type_ok
        move.l  #6,vpv01_param_status
        bra.w   vpv01_create_fail_consume
vpv04_create_type_ok:
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   #$A0100001,d0
        beq.w   vpv04_create_context_ok
        move.l  #7,vpv01_param_status
        bra.w   vpv01_create_fail_consume
vpv04_create_context_ok:
        lea     24(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_last_rx_msgid
        tst.l   d0
        beq.w   vpv04_create_hstatus_ok
        move.l  #8,vpv01_param_status
        bra.w   vpv01_create_fail_consume
vpv04_create_hstatus_ok:
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_create_status
        tst.l   d0
        beq.w   vpv04_create_worker_ok
        move.l  #9,vpv01_param_status
        bra.w   vpv01_create_fail_consume
vpv04_create_worker_ok:
        lea     36(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_audio_handle
        tst.l   d0
        bne.w   vpv04_create_handle_ok
        move.l  #10,vpv01_param_status
        bra.w   vpv01_create_fail_consume
vpv04_create_handle_ok:
        ; VPv116: COMPONENT_CREATE reply also contains input/output/clock counts.
        lea     40(a2),a0
        jsr     load_le32
        move.l  d0,vpv116_audio_inputs
        lea     44(a2),a0
        jsr     load_le32
        move.l  d0,vpv116_audio_outputs
        lea     48(a2),a0
        jsr     load_le32
        move.l  d0,vpv116_audio_clocks
        move.l  vpv01_create_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        beq.w   vpv04_create_consume_ok
        move.l  #11,vpv01_param_status
        bra.w   vpv01_create_fail
vpv04_create_consume_ok:
        ; VPv116: keep the proven audio_render CREATE -> CONFIG sequence intact.
        ; The clock probe is deliberately deferred until audio_render is fully
        ; configured, enabled and its initial PCM prefix has been queued.
        lea     msg_vpv116_audio_ports,a1
        move.l  #msg_vpv116_audio_ports_end-msg_vpv116_audio_ports,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv116_audio_inputs,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv116_audio_outputs,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv116_audio_clocks,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print

        lea     msg_vpv01_create_ok,a1
        move.l  #msg_vpv01_create_ok_end-msg_vpv01_create_ok,d3
        jsr     print_force
        moveq   #0,d0
        bra.w   vpv01_create_done
vpv01_create_fail_consume:
        move.l  vpv01_create_size,d0
        jsr     v12a_rx_consume_payload
vpv01_create_fail:
        lea     msg_vpv01_create_fail,a1
        move.l  #msg_vpv01_create_fail_end-msg_vpv01_create_fail,d3
        jsr     print_force

        ; VPv06: minimal safe diagnostics. No alias retry, no alternate CREATE.
        lea     msg_vpv04_diag_stage,a1
        move.l  #msg_vpv04_diag_stage_end-msg_vpv04_diag_stage,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv01_param_status,d0
        jsr     print_hex32
        clr.l   v41l_force_print
        lea     msg_vpv04_diag_worker,a1
        move.l  #msg_vpv04_diag_worker_end-msg_vpv04_diag_worker,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv01_create_status,d0
        jsr     print_hex32
        clr.l   v41l_force_print
        lea     msg_vpv04_diag_header,a1
        move.l  #msg_vpv04_diag_header_end-msg_vpv04_diag_header,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv01_last_rx_msgid,d0
        jsr     print_hex32
        clr.l   v41l_force_print
        move.l  #1,v41l_force_print
        jsr     newline
        clr.l   v41l_force_print
        moveq   #1,d0
vpv01_create_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; ------------------------------------------------------------
; VPv116 diagnostic: create MMAL component "clock" on the current service.
; Component creation itself remains side-effect free. VPv124 later resolves,
; connects and enables CLOCK0 only after the graph probe has completed. Normal
; MMAL service CLOSE still owns final component destruction.
; ------------------------------------------------------------
vpv116_probe_clock_component:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv116_clock_probe_ok
        clr.l   vpv116_clock_handle
        clr.l   vpv116_clock_inputs
        clr.l   vpv116_clock_outputs
        clr.l   vpv116_clock_clocks

        tst.l   v12f_local_port
        beq.s   vpv116_clock_tx_legacy
        move.l  #168,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv116_clock_fail
        bra.s   vpv116_clock_tx_ready
vpv116_clock_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
vpv116_clock_tx_ready:
        move.l  a2,a0
        moveq   #41,d7
vpv116_clock_clear:
        clr.l   (a0)+
        dbra    d7,vpv116_clock_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #160,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_COMPONENT_CREATE,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$A115C10C,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #$A115C10D,d0
        jsr     store_le32
        lea     36(a2),a0
        lea     vpv116_clock_name,a1
        moveq   #5,d7                    ; "clock" + NUL
vpv116_clock_name_copy:
        move.b  (a1)+,(a0)+
        dbra    d7,vpv116_clock_name_copy

        add.l   #168,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   vpv116_clock_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv116_clock_wait_setup:
        move.l  #V10_CLEANUP_POLL_COUNT,d7
vpv116_clock_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   vpv116_clock_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   vpv116_clock_wait
        jsr     dma_post_all
        bra.w   vpv116_clock_fail
vpv116_clock_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   vpv116_clock_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,d5
        cmp.l   #44,d0
        bcs.s   vpv116_clock_consume_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.s   vpv116_clock_consume_fail
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_COMPONENT_CREATE,d0
        bne.s   vpv116_clock_consume_fail
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   #$A115C10C,d0
        bne.s   vpv116_clock_consume_fail
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.s   vpv116_clock_consume_fail
        lea     32(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.s   vpv116_clock_consume_fail
        lea     36(a2),a0
        jsr     load_le32
        move.l  d0,vpv116_clock_handle
        tst.l   d0
        beq.s   vpv116_clock_consume_fail
        lea     40(a2),a0
        jsr     load_le32
        move.l  d0,vpv116_clock_inputs
        lea     44(a2),a0
        jsr     load_le32
        move.l  d0,vpv116_clock_outputs
        lea     48(a2),a0
        jsr     load_le32
        move.l  d0,vpv116_clock_clocks
        move.l  d5,d0
        jsr     v12a_rx_consume_payload
        move.l  #1,vpv116_clock_probe_ok

        lea     msg_vpv116_clock_ok,a1
        move.l  #msg_vpv116_clock_ok_end-msg_vpv116_clock_ok,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv116_clock_handle,d0
        jsr     print_hex32
        lea     msg_vpv116_ports,a1
        move.l  #msg_vpv116_ports_end-msg_vpv116_ports,d3
        jsr     print_force
        move.l  vpv116_clock_inputs,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv116_clock_outputs,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv116_clock_clocks,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print

        ; VPv117: resolve actual clock/audio clock endpoints and create/query
        ; video_scheduler.  No PORT_ACTION CONNECT is issued in this build.
        jsr     vpv117_probe_clock_ports_scheduler
        bra.s   vpv116_clock_done
vpv116_clock_consume_fail:
        move.l  d5,d0
        jsr     v12a_rx_consume_payload
vpv116_clock_fail:
        lea     msg_vpv116_clock_fail,a1
        move.l  #msg_vpv116_clock_fail_end-msg_vpv116_clock_fail,d3
        jsr     print_force
vpv116_clock_done:
        ; restore audio component globals expected by the caller
        move.l  vpv01_audio_handle,component_handle
        movem.l (sp)+,d1-d7/a0-a3
        moveq   #0,d0                    ; diagnostic failure is non-fatal
        rts

; ------------------------------------------------------------
; VPv117 graph probe.
; Resolve two independent clock source ports, audio_render CLOCK0, then
; create/query MMAL scheduler INPUT0/OUTPUT0/CLOCK0.  Still no tunnel.
; ------------------------------------------------------------
vpv117_probe_clock_ports_scheduler:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv117_graph_probe_ok
        clr.l   vpv117_clock_port0
        clr.l   vpv117_clock_port1
        clr.l   vpv117_clock_port2
        clr.l   vpv117_clock_port3
        clr.l   vpv117_clock_port4
        clr.l   vpv117_audio_clock_port
        ; VPv126: scheduler was created and inserted into the video data graph
        ; during ISP setup.  Preserve its handle and data-port handles here.
        clr.l   vpv117_sched_clock0

        move.l  vpv116_clock_handle,component_handle
        move.l  #MMAL_PORT_CLOCK,port_query_type

        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv117_graph_probe_fail
        move.l  port_last_handle,vpv117_clock_port0

        move.l  #1,port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv117_graph_probe_fail
        move.l  port_last_handle,vpv117_clock_port1

        move.l  #2,port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv117_graph_probe_fail
        move.l  port_last_handle,vpv117_clock_port2

        move.l  #3,port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv117_graph_probe_fail
        move.l  port_last_handle,vpv117_clock_port3

        move.l  #4,port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv117_graph_probe_fail
        move.l  port_last_handle,vpv117_clock_port4

        tst.l   n81_free_mode             ; CLK81: no audio_render
        bne.s   n81_skip_audio_clock_port
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_CLOCK,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv117_graph_probe_fail
        move.l  port_last_handle,vpv117_audio_clock_port
n81_skip_audio_clock_port:

        tst.l   vpv117_sched_handle
        bne.s   vpv126_sched_already_created
        jsr     vpv117_create_scheduler_component
        tst.l   d0
        bne.w   vpv117_graph_probe_fail
vpv126_sched_already_created:
        move.l  vpv117_sched_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv117_graph_probe_fail
        move.l  port_last_handle,vpv117_sched_input0

        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv117_graph_probe_fail
        move.l  port_last_handle,vpv117_sched_output0

        move.l  #MMAL_PORT_CLOCK,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv117_graph_probe_fail
        move.l  port_last_handle,vpv117_sched_clock0

        move.l  #1,vpv117_graph_probe_ok
        lea     msg_vpv117_graph_ok,a1
        move.l  #msg_vpv117_graph_ok_end-msg_vpv117_graph_ok,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv117_clock_port0,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv117_clock_port1,d0
        jsr     print_hex32
        lea     msg_vpv117_arrow,a1
        move.l  #msg_vpv117_arrow_end-msg_vpv117_arrow,d3
        jsr     print_force
        move.l  vpv117_audio_clock_port,d0
        jsr     print_hex32
        lea     msg_vpv117_sched_ports,a1
        move.l  #msg_vpv117_sched_ports_end-msg_vpv117_sched_ports,d3
        jsr     print_force
        move.l  vpv117_sched_input0,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv117_sched_output0,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv117_sched_clock0,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print

        ; VPv121: first real MMAL clock connection.  Keep the proven P96
        ; video path and old A/V scheduler intact; only connect clock port 0
        ; to ril.audio_render CLOCK0 and verify the worker acknowledgement.
        tst.l   n81_free_mode             ; CLK81: free-running clock
        bne.w   n81_probe_free_tail
        jsr     vpv121_connect_clock_to_audio
        ; VPv122: prove the second clock fanout leg as a separate isolated
        ; worker CONNECT.  Scheduler still carries no video data in this build.
        jsr     vpv122_connect_clock_to_scheduler
        ; VPv124: now turn the proven clock0->audio tunnel into a real
        ; audio timing-reference path.  This is deliberately armed only
        ; after both CONNECT replies are consumed, while no video input
        ; buffer is in flight, so synchronous MMAL control remains safe.
        jsr     vpv124_arm_audio_master_clock
        ; VPv126: activate the clock fanout leg used by the scheduler and
        ; start the scheduler component only after audio master is armed.
        jsr     vpv126_activate_scheduler_clock
        jsr     vpv126_enable_scheduler_component
        bra.s   vpv117_graph_probe_done
n81_probe_free_tail:
        ; CLK81: clock1 -> scheduler only, no audio_render.  The clock is
        ; started by n81_free_clock_start (REFERENCE + ACTIVE, scale 1.0).
        jsr     vpv122_connect_clock_to_scheduler
        jsr     vpv126_activate_scheduler_clock
        jsr     n81_free_clock_start
        jsr     vpv126_enable_scheduler_component
        bra.s   vpv117_graph_probe_done

vpv117_graph_probe_fail:
        lea     msg_vpv117_graph_fail,a1
        move.l  #msg_vpv117_graph_fail_end-msg_vpv117_graph_fail,d3
        jsr     print_force
vpv117_graph_probe_done:
        move.l  vpv01_audio_handle,component_handle
        movem.l (sp)+,d1-d7/a0-a3
        moveq   #0,d0
        rts

; ------------------------------------------------------------
; VPv121 first real clock tunnel probe.
; Connect clock CLOCK0 -> ril.audio_render CLOCK0 with the same
; MMAL_WORKER_PORT_ACTION_CONNECT protocol already proven for decoder->ISP.
; No clock state, clock enable, scheduler tunnel or pacing change yet.
; Playback remains governed by the VPv114/VPv120 P96 path.
; ------------------------------------------------------------
vpv121_connect_clock_to_audio:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv121_audio_clock_tunnel_ok
        clr.l   vpv121_audio_clock_rx_size
        clr.l   vpv121_audio_clock_status

        ; Both endpoints were resolved successfully immediately before this.
        tst.l   vpv116_clock_handle
        beq.w   vpv121_clock_audio_fail
        tst.l   vpv117_clock_port0
        beq.w   vpv121_clock_audio_fail
        tst.l   vpv01_audio_handle
        beq.w   vpv121_clock_audio_fail
        tst.l   vpv117_audio_clock_port
        beq.w   vpv121_clock_audio_fail

        ; Reserve one 112-byte worker record, slot-safe on both local-0/1.
        move.l  #112,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv121_clock_audio_fail

        move.l  a2,a0
        moveq   #27,d7
vpv121_clock_audio_clear:
        clr.l   (a0)+
        dbra    d7,vpv121_clock_audio_clear

        ; VCHIQ DATA header.
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #100,d0
        jsr     store_le32

        ; MMAL worker header.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_ACTION,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$A121C001,d0
        jsr     store_le32

        ; PORT_ACTION CONNECT payload: clock CLOCK0 -> audio_render CLOCK0.
        lea     32(a2),a0
        move.l  vpv116_clock_handle,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv117_clock_port0,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  #MMAL_PORT_ACTION_CONNECT,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  vpv01_audio_handle,d0
        jsr     store_le32
        lea     48(a2),a0
        move.l  vpv117_audio_clock_port,d0
        jsr     store_le32

        add.l   #112,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   vpv121_clock_audio_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2

vpv121_clock_audio_wait_setup:
        move.l  #POLL_COUNT,d7
vpv121_clock_audio_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   vpv121_clock_audio_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   vpv121_clock_audio_wait
        jsr     dma_post_all
        bra.w   vpv121_clock_audio_fail

vpv121_clock_audio_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   vpv121_clock_audio_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv121_audio_clock_rx_size
        move.l  d0,d5
        cmp.l   #28,d0
        bcs.w   vpv121_clock_audio_fail_consume
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   vpv121_clock_audio_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.w   vpv121_clock_audio_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   #$A121C001,d0
        bne.w   vpv121_clock_audio_fail_consume
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   vpv121_clock_audio_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,vpv121_audio_clock_status
        tst.l   d0
        bne.w   vpv121_clock_audio_fail_consume

        move.l  d5,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv121_clock_audio_fail
        move.l  #1,vpv121_audio_clock_tunnel_ok

        lea     msg_vpv121_clock_audio_ok,a1
        move.l  #msg_vpv121_clock_audio_ok_end-msg_vpv121_clock_audio_ok,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv116_clock_handle,d0
        jsr     print_hex32
        lea     msg_vpv121_colon,a1
        move.l  #msg_vpv121_colon_end-msg_vpv121_colon,d3
        jsr     print_force
        move.l  vpv117_clock_port0,d0
        jsr     print_hex32
        lea     msg_vpv117_arrow,a1
        move.l  #msg_vpv117_arrow_end-msg_vpv117_arrow,d3
        jsr     print_force
        move.l  vpv01_audio_handle,d0
        jsr     print_hex32
        lea     msg_vpv121_colon,a1
        move.l  #msg_vpv121_colon_end-msg_vpv121_colon,d3
        jsr     print_force
        move.l  vpv117_audio_clock_port,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        bra.s   vpv121_clock_audio_done

vpv121_clock_audio_fail_consume:
        move.l  d5,d0
        jsr     v12a_rx_consume_payload
vpv121_clock_audio_fail:
        lea     msg_vpv121_clock_audio_fail,a1
        move.l  #msg_vpv121_clock_audio_fail_end-msg_vpv121_clock_audio_fail,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv121_audio_clock_rx_size,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv121_audio_clock_status,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
vpv121_clock_audio_done:
        movem.l (sp)+,d1-d7/a0-a3
        moveq   #0,d0                    ; probe remains non-fatal
        rts

; ------------------------------------------------------------
; VPv122 second real clock tunnel probe.
; Connect clock CLOCK1 -> scheduler CLOCK0.  The scheduler component is still
; not inserted into the video data path; this build proves only that one clock
; component can fan out to audio_render and scheduler simultaneously.
; ------------------------------------------------------------
vpv122_connect_clock_to_scheduler:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv122_sched_clock_tunnel_ok
        clr.l   vpv122_sched_clock_rx_size
        clr.l   vpv122_sched_clock_status

        tst.l   vpv116_clock_handle
        beq.w   vpv122_clock_sched_fail
        tst.l   vpv117_clock_port1
        beq.w   vpv122_clock_sched_fail
        tst.l   vpv117_sched_handle
        beq.w   vpv122_clock_sched_fail
        tst.l   vpv117_sched_clock0
        beq.w   vpv122_clock_sched_fail

        move.l  #112,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv122_clock_sched_fail

        move.l  a2,a0
        moveq   #27,d7
vpv122_clock_sched_clear:
        clr.l   (a0)+
        dbra    d7,vpv122_clock_sched_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #100,d0
        jsr     store_le32

        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_ACTION,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$A122C002,d0
        jsr     store_le32

        ; clock CLOCK1 -> scheduler CLOCK0
        lea     32(a2),a0
        move.l  vpv116_clock_handle,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv117_clock_port1,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  #MMAL_PORT_ACTION_CONNECT,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  vpv117_sched_handle,d0
        jsr     store_le32
        lea     48(a2),a0
        move.l  vpv117_sched_clock0,d0
        jsr     store_le32

        add.l   #112,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   vpv122_clock_sched_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2

vpv122_clock_sched_wait_setup:
        move.l  #POLL_COUNT,d7
vpv122_clock_sched_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   vpv122_clock_sched_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   vpv122_clock_sched_wait
        jsr     dma_post_all
        bra.w   vpv122_clock_sched_fail

vpv122_clock_sched_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   vpv122_clock_sched_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv122_sched_clock_rx_size
        move.l  d0,d5
        cmp.l   #28,d0
        bcs.w   vpv122_clock_sched_fail_consume
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   vpv122_clock_sched_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.w   vpv122_clock_sched_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   #$A122C002,d0
        bne.w   vpv122_clock_sched_fail_consume
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   vpv122_clock_sched_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,vpv122_sched_clock_status
        tst.l   d0
        bne.w   vpv122_clock_sched_fail_consume

        move.l  d5,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv122_clock_sched_fail
        move.l  #1,vpv122_sched_clock_tunnel_ok

        lea     msg_vpv122_clock_sched_ok,a1
        move.l  #msg_vpv122_clock_sched_ok_end-msg_vpv122_clock_sched_ok,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv116_clock_handle,d0
        jsr     print_hex32
        lea     msg_vpv121_colon,a1
        move.l  #msg_vpv121_colon_end-msg_vpv121_colon,d3
        jsr     print_force
        move.l  vpv117_clock_port1,d0
        jsr     print_hex32
        lea     msg_vpv117_arrow,a1
        move.l  #msg_vpv117_arrow_end-msg_vpv117_arrow,d3
        jsr     print_force
        move.l  vpv117_sched_handle,d0
        jsr     print_hex32
        lea     msg_vpv121_colon,a1
        move.l  #msg_vpv121_colon_end-msg_vpv121_colon,d3
        jsr     print_force
