; ------------------------------------------------------------
; VPv124 real audio-master clock arming.
;
; Preconditions:
;   * clock CLOCK0 -> ril.audio_render CLOCK0 tunnel is proven (VPv121)
;   * no H264 input is in flight yet
;   * the initial PCM prefix has already returned, so worker RX is quiescent
;
; Steps:
;   1) audio_render CLOCK0: MMAL_PARAMETER_CLOCK_ENABLE_BUFFER_INFO = TRUE
;      so renderer input timing is forwarded through the connected clock port.
;   2) enable central clock CLOCK0 using a fresh PORT_INFO_GET snapshot.
;   3) enable the central "clock" component.
;   4) read CLOCK0 back and require enabled=1.
;
; The scheduler clock tunnel remains a graph probe only in VPv124; video input
; still carries MMAL_TIME_UNKNOWN, therefore putting scheduler into the video
; data path would be premature.  P96 video pacing remains unchanged here.
; ------------------------------------------------------------
vpv124_arm_audio_master_clock:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv124_audio_master_armed
        clr.l   vpv124_buffer_info_set_ok
        clr.l   vpv124_clock_port_enable_ok
        clr.l   vpv124_clock_component_enable_ok

        move.l  component_handle,vpv124_saved_component
        move.l  input_port_handle,vpv124_saved_input
        move.l  port_query_type,vpv124_saved_qtype
        move.l  port_query_index,vpv124_saved_qidx

        tst.l   vpv121_audio_clock_tunnel_ok
        beq.w   vpv124_audio_master_fail
        tst.l   vpv116_clock_handle
        beq.w   vpv124_audio_master_fail
        tst.l   vpv117_clock_port0
        beq.w   vpv124_audio_master_fail
        tst.l   vpv01_audio_handle
        beq.w   vpv124_audio_master_fail
        tst.l   vpv117_audio_clock_port
        beq.w   vpv124_audio_master_fail

        ; Ask audio_render's clock port to report timing information for the
        ; actually consumed PCM buffers.  The central clock component receives
        ; those events through the already-connected CLOCK0 tunnel.
        move.l  vpv01_audio_handle,d0
        move.l  vpv117_audio_clock_port,d1
        move.l  #MMAL_PARAMETER_CLOCK_ENABLE_BUFFER_INFO,d2
        moveq   #1,d3
        jsr     vpv124_set_clock_bool
        tst.l   d0
        bne.w   vpv124_audio_master_fail
        move.l  #1,vpv124_buffer_info_set_ok
        lea     msg_vpv124_buffer_info_ok,a1
        move.l  #msg_vpv124_buffer_info_ok_end-msg_vpv124_buffer_info_ok,d3
        jsr     print_force

        ; Get an exact VideoCore snapshot of the source clock port before the
        ; official PORT_ACTION ENABLE, because the worker action carries the
        ; complete mmal_port snapshot.
        move.l  vpv116_clock_handle,component_handle
        move.l  #MMAL_PORT_CLOCK,port_query_type
        clr.l   port_query_index
        move.l  #1,v12a_local_get_active
        jsr     port_info_get
        clr.l   v12a_local_get_active
        tst.l   d0
        bne.w   vpv124_audio_master_fail

        move.l  vpv117_clock_port0,v9_worker_port
        move.l  #MMAL_PORT_CLOCK,v9_worker_port_type
        move.l  #MMAL_PORT_ACTION,v9_worker_type
        move.l  #MMAL_PORT_ACTION_ENABLE,v9_worker_action
        move.l  #1,v9_worker_is_port
        ; v9_worker_sync obtains the local VCHIQ service bits from the high
        ; portion of port_query_index.  Clock index itself is zero.
        move.l  v12f_local_bits,port_query_index
        jsr     v9_worker_sync
        tst.l   d0
        bne.w   vpv124_audio_master_fail
        move.l  #1,vpv124_clock_port_enable_ok
        lea     msg_vpv124_clock_port_enable_ok,a1
        move.l  #msg_vpv124_clock_port_enable_ok_end-msg_vpv124_clock_port_enable_ok,d3
        jsr     print_force

        ; Enable the central clock component.  Its action thread can now accept
        ; MMAL_CLOCK_EVENT_INPUT_BUFFER_INFO events from audio_render and use
        ; them to establish/adjust media time.
        move.l  vpv116_clock_handle,component_handle
        move.l  v12f_local_bits,port_query_index
        move.l  #MMAL_COMPONENT_ENABLE,d0
        jsr     v9_component_cmd
        tst.l   d0
        bne.w   vpv124_audio_master_fail
        move.l  #1,vpv124_clock_component_enable_ok
        lea     msg_vpv124_clock_component_enable_ok,a1
        move.l  #msg_vpv124_clock_component_enable_ok_end-msg_vpv124_clock_component_enable_ok,d3
        jsr     print_force

        ; Read source CLOCK0 back through the official worker port query.  This
        ; proves the port-side enable, not merely the PORT_ACTION reply.
        move.l  vpv116_clock_handle,component_handle
        move.l  #MMAL_PORT_CLOCK,port_query_type
        clr.l   port_query_index
        move.l  #1,v12a_local_get_active
        jsr     port_info_get
        clr.l   v12a_local_get_active
        tst.l   d0
        bne.w   vpv124_audio_master_fail
        cmpi.l  #1,port_enabled
        bne.w   vpv124_audio_master_fail

        move.l  #1,vpv124_audio_master_armed
        lea     msg_vpv124_audio_master_ok,a1
        move.l  #msg_vpv124_audio_master_ok_end-msg_vpv124_audio_master_ok,d3
        jsr     print_force
        bra.s   vpv124_audio_master_restore

vpv124_audio_master_fail:
        lea     msg_vpv124_audio_master_fail,a1
        move.l  #msg_vpv124_audio_master_fail_end-msg_vpv124_audio_master_fail,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv124_buffer_info_set_ok,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv124_clock_port_enable_ok,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv124_clock_component_enable_ok,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print

vpv124_audio_master_restore:
        move.l  vpv124_saved_component,component_handle
        move.l  vpv124_saved_input,input_port_handle
        move.l  vpv124_saved_qtype,port_query_type
        move.l  vpv124_saved_qidx,port_query_index
        movem.l (sp)+,d1-d7/a0-a3
        moveq   #0,d0                    ; isolation step remains non-fatal
        rts

; ------------------------------------------------------------
; VPv124 generic MMAL clock BOOLEAN parameter SET.
; D0 = component handle, D1 = port handle, D2 = parameter id, D3 = value.
; MMAL_PARAMETER_BOOLEAN_T is 12 bytes (8-byte header + 32-bit enable).
; Worker payload = 32 + 12 = 44, VCHIQ record stride = 56.
; ------------------------------------------------------------
vpv124_set_clock_bool:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,vpv124_param_component
        move.l  d1,vpv124_param_port
        move.l  d2,vpv124_param_id
        move.l  d3,vpv124_param_value
        clr.l   vpv124_param_size
        clr.l   vpv124_param_status

        move.l  #56,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv124_param_fail
        move.l  a2,a0
        moveq   #13,d7
vpv124_param_clear:
        clr.l   (a0)+
        dbra    d7,vpv124_param_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #44,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_PARAMETER_SET,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$A124B001,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  vpv124_param_component,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv124_param_port,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  vpv124_param_id,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #12,d0
        jsr     store_le32
        lea     48(a2),a0
        move.l  vpv124_param_value,d0
        jsr     store_le32

        add.l   #56,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   vpv124_param_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2

vpv124_param_wait_setup:
        move.l  #V10_CLEANUP_POLL_COUNT,d7
vpv124_param_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   vpv124_param_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   vpv124_param_wait
        jsr     dma_post_all
        bra.w   vpv124_param_fail

vpv124_param_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   vpv124_param_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv124_param_size
        move.l  d0,d5
        cmp.l   #28,d0
        bcs.w   vpv124_param_fail_consume
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   vpv124_param_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_PORT_PARAMETER_SET,d0
        bne.w   vpv124_param_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   #$A124B001,d0
        bne.w   vpv124_param_fail_consume
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   vpv124_param_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,vpv124_param_status
        move.l  d5,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv124_param_fail
        tst.l   vpv124_param_status
        bne.w   vpv124_param_fail
        moveq   #0,d0
        bra.s   vpv124_param_done

vpv124_param_fail_consume:
        move.l  d5,d0
        jsr     v12a_rx_consume_payload
vpv124_param_fail:
        moveq   #1,d0
vpv124_param_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; ------------------------------------------------------------
; Create MMAL component "scheduler" on the active worker service.
; Diagnostic only: no enable and no PORT_ACTION CONNECT.
; ------------------------------------------------------------
vpv117_create_scheduler_component:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv117_sched_handle
        clr.l   vpv117_sched_inputs
        clr.l   vpv117_sched_outputs
        clr.l   vpv117_sched_clocks
        clr.l   vpv119_sched_stage
        clr.l   vpv119_sched_rx_size
        clr.l   vpv119_sched_magic
        clr.l   vpv119_sched_type
        clr.l   vpv119_sched_context
        clr.l   vpv119_sched_hdr_status
        clr.l   vpv119_sched_create_status
        clr.l   vpv119_sched_reply_handle
        clr.l   vpv119_sched_reply_inputs
        clr.l   vpv119_sched_reply_outputs
        clr.l   vpv119_sched_reply_clocks

        tst.l   v12f_local_port
        beq.s   vpv119_sched_tx_legacy
        move.l  #1,vpv119_sched_stage
        move.l  #168,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv119_sched_fail
        bra.s   vpv119_sched_tx_ready
vpv119_sched_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
vpv119_sched_tx_ready:
        move.l  a2,a0
        moveq   #41,d7
vpv119_sched_clear:
        clr.l   (a0)+
        dbra    d7,vpv119_sched_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #160,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_COMPONENT_CREATE,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$A1195C10,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #$A1195C11,d0
        jsr     store_le32
        lea     36(a2),a0
        lea     vpv117_sched_name,a1
        moveq   #15,d7
vpv119_sched_name_copy:
        move.b  (a1)+,(a0)+
        dbra    d7,vpv119_sched_name_copy

        add.l   #168,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   vpv119_sched_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv119_sched_wait_setup:
        move.l  #2,vpv119_sched_stage
        move.l  #V10_CLEANUP_POLL_COUNT,d7
vpv119_sched_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   vpv119_sched_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   vpv119_sched_wait
        jsr     dma_post_all
        bra.w   vpv119_sched_fail

vpv119_sched_have:
        move.l  #3,vpv119_sched_stage
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   vpv119_sched_fail

        ; Snapshot every field before validating it so hardware tells us
        ; exactly why this component is rejected.
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv119_sched_rx_size
        move.l  d0,d5

        lea     8(a2),a0
        jsr     load_le32
        move.l  d0,vpv119_sched_magic
        lea     12(a2),a0
        jsr     load_le32
        move.l  d0,vpv119_sched_type
        lea     20(a2),a0
        jsr     load_le32
        move.l  d0,vpv119_sched_context
        lea     24(a2),a0
        jsr     load_le32
        move.l  d0,vpv119_sched_hdr_status
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,vpv119_sched_create_status
        lea     36(a2),a0
        jsr     load_le32
        move.l  d0,vpv119_sched_reply_handle
        lea     40(a2),a0
        jsr     load_le32
        move.l  d0,vpv119_sched_reply_inputs
        lea     44(a2),a0
        jsr     load_le32
        move.l  d0,vpv119_sched_reply_outputs
        lea     48(a2),a0
        jsr     load_le32
        move.l  d0,vpv119_sched_reply_clocks

        ; VPv120: v12a_rx_map_data returns the MMAL payload length in d5.
        ; COMPONENT_CREATE reply is 44 bytes (0x2C) of MMAL payload; the
        ; preceding 8-byte VCHIQ header is not part of d5.  VPv119 compared
        ; against 52 and therefore rejected a completely valid reply.
        cmp.l   #44,d5
        bcs.s   vpv119_sched_bad_short
        move.l  vpv119_sched_magic,d0
        cmp.l   #MMAL_MAGIC,d0
        bne.s   vpv119_sched_bad_magic
        move.l  vpv119_sched_type,d0
        cmp.l   #MMAL_COMPONENT_CREATE,d0
        bne.s   vpv119_sched_bad_type
        move.l  vpv119_sched_context,d0
        cmp.l   #$A1195C10,d0
        bne.s   vpv119_sched_bad_context
        tst.l   vpv119_sched_hdr_status
        bne.s   vpv119_sched_bad_header
        tst.l   vpv119_sched_create_status
        bne.s   vpv119_sched_bad_create
        tst.l   vpv119_sched_reply_handle
        beq.s   vpv119_sched_bad_handle

        move.l  vpv119_sched_reply_handle,vpv117_sched_handle
        move.l  vpv119_sched_reply_inputs,vpv117_sched_inputs
        move.l  vpv119_sched_reply_outputs,vpv117_sched_outputs
        move.l  vpv119_sched_reply_clocks,vpv117_sched_clocks
        clr.l   vpv119_sched_stage
        move.l  d5,d0
        jsr     v12a_rx_consume_payload

        lea     msg_vpv117_sched_ok,a1
        move.l  #msg_vpv117_sched_ok_end-msg_vpv117_sched_ok,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv117_sched_handle,d0
        jsr     print_hex32
        lea     msg_vpv116_ports,a1
        move.l  #msg_vpv116_ports_end-msg_vpv116_ports,d3
        jsr     print_force
        move.l  vpv117_sched_inputs,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv117_sched_outputs,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv117_sched_clocks,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        moveq   #0,d0
        bra.w   vpv119_sched_done

vpv119_sched_bad_short:
        move.l  #4,vpv119_sched_stage
        bra.s   vpv119_sched_consume_fail
vpv119_sched_bad_magic:
        move.l  #5,vpv119_sched_stage
        bra.s   vpv119_sched_consume_fail
vpv119_sched_bad_type:
        move.l  #6,vpv119_sched_stage
        bra.s   vpv119_sched_consume_fail
vpv119_sched_bad_context:
        move.l  #7,vpv119_sched_stage
        bra.s   vpv119_sched_consume_fail
vpv119_sched_bad_header:
        move.l  #8,vpv119_sched_stage
        bra.s   vpv119_sched_consume_fail
vpv119_sched_bad_create:
        move.l  #9,vpv119_sched_stage
        bra.s   vpv119_sched_consume_fail
vpv119_sched_bad_handle:
        move.l  #10,vpv119_sched_stage
vpv119_sched_consume_fail:
        move.l  d5,d0
        jsr     v12a_rx_consume_payload

vpv119_sched_fail:
        lea     msg_vpv119_sched_diag,a1
        move.l  #msg_vpv119_sched_diag_end-msg_vpv119_sched_diag,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv119_sched_stage,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv119_sched_rx_size,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv119_sched_magic,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv119_sched_type,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv119_sched_context,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv119_sched_hdr_status,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv119_sched_create_status,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv119_sched_reply_handle,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv119_sched_reply_inputs,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv119_sched_reply_outputs,d0
        jsr     print_hex32
        lea     msg_vpv116_slash,a1
        move.l  #msg_vpv116_slash_end-msg_vpv116_slash,d3
        jsr     print_force
        move.l  vpv119_sched_reply_clocks,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print

        lea     msg_vpv117_sched_fail,a1
        move.l  #msg_vpv117_sched_fail_end-msg_vpv117_sched_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv119_sched_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; ------------------------------------------------------------
; Configure audio_render INPUT0 as signed PCM LE, stereo, 48 kHz, 16 bit.
; Also resolve the real input/control port handles from VideoCore.
; ------------------------------------------------------------
vpv01_configure_audio_render:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  vpv01_audio_handle,component_handle

        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv01_config_fail
        move.l  port_last_handle,vpv01_audio_control

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv01_config_fail
        move.l  port_last_handle,vpv01_audio_input
        move.l  vpv01_audio_input,input_port_handle

        move.l  #MMAL_ES_AUDIO,port_fmt_type
        move.l  #MMAL_ENCODING_PCM_SIGNED_LE,port_fmt_encoding
        clr.l   port_fmt_variant
        move.l  #VPV01_AUDIO_BITRATE,port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra

        ; mmal_audio_format union occupies the same first four 32-bit slots
        ; that the legacy decoder helper names video_width/height/crop_x/crop_y.
        move.l  #VPV01_AUDIO_CHANNELS,port_video_width
        move.l  #VPV01_AUDIO_RATE,port_video_height
        move.l  #VPV01_AUDIO_BITS,port_crop_x
        move.l  #VPV01_AUDIO_BLOCKALIGN,port_crop_y
        clr.l   port_crop_width
        clr.l   port_crop_height
        clr.l   port_fps_num
        clr.l   port_fps_den
        clr.l   port_par_num
        clr.l   port_par_den
        clr.l   port_color_space

        move.l  port_buf_num_min,d0
        tst.l   d0
        bne.w   vpv01_buf_num_ok
        moveq   #1,d0
vpv01_buf_num_ok:
        move.l  d0,port_buf_num
        move.l  #$00010000,d0
        cmp.l   port_buf_size_min,d0
        bcc.w   vpv01_buf_size_min_ok
        move.l  port_buf_size_min,d0
vpv01_buf_size_min_ok:
        cmp.l   #INPUT_DATA_SIZE,d0
        bhi.w   vpv01_config_fail
        move.l  d0,port_buf_size

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_set_input
        tst.l   d0
        bne.w   vpv01_config_fail

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv01_config_fail
        move.l  port_last_handle,d0
        cmp.l   vpv01_audio_input,d0
        bne.w   vpv01_config_fail
        cmpi.l  #MMAL_ES_AUDIO,port_fmt_type
        bne.w   vpv01_config_fail
        cmpi.l  #MMAL_ENCODING_PCM_SIGNED_LE,port_fmt_encoding
        bne.w   vpv01_config_fail
        cmpi.l  #VPV01_AUDIO_CHANNELS,port_video_width
        bne.w   vpv01_config_fail
        cmpi.l  #VPV01_AUDIO_RATE,port_video_height
        bne.w   vpv01_config_fail
        cmpi.l  #VPV01_AUDIO_BITS,port_crop_x
        bne.w   vpv01_config_fail
        move.l  port_buf_size,d0
        cmpi.l  #VPV01_TONE_BYTES,d0
        bcs.w   vpv01_config_fail
        cmpi.l  #INPUT_DATA_SIZE,d0
        bhi.w   vpv01_config_fail

        ; Set HDMI output destination. First try INPUT0 (matching the original
        ; audio sketch); if firmware rejects it, retry on CONTROL0.
        move.l  vpv01_audio_input,d0
        jsr     vpv01_set_hdmi_destination
        tst.l   d0
        beq.w   vpv01_dest_ok
        move.l  vpv01_audio_control,d0
        jsr     vpv01_set_hdmi_destination
        tst.l   d0
        bne.w   vpv01_config_fail
vpv01_dest_ok:

        ; Enable host-fed INPUT0. Local-0 uses the original proven helper;
        ; attached local-1 uses the slot-safe second-service helper.
        move.l  vpv01_audio_handle,component_handle
        move.l  vpv01_audio_input,input_port_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv01_config_fail
        tst.l   v12f_local_port
        bne.w   vpv01_enable_input_second
        jsr     port_enable_current
        bra.w   vpv01_enable_input_done
vpv01_enable_input_second:
        move.l  vpv01_audio_input,d0
        move.l  #MMAL_PORT_INPUT,d1
        jsr     v9f_port_enable
vpv01_enable_input_done:
        tst.l   d0
        bne.w   vpv01_config_fail

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv01_config_fail
        cmpi.l  #1,port_enabled
        bne.w   vpv01_config_fail

        move.l  vpv01_audio_handle,component_handle
        jsr     component_enable_worker
        tst.l   d0
        bne.w   vpv01_config_fail
        move.l  #1,vpv01_component_enabled

        lea     msg_vpv01_config_ok,a1
        move.l  #msg_vpv01_config_ok_end-msg_vpv01_config_ok,d3
        jsr     print_force
        moveq   #0,d0
        bra.w   vpv01_config_done
vpv01_config_fail:
        lea     msg_vpv01_config_fail,a1
        move.l  #msg_vpv01_config_fail_end-msg_vpv01_config_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv01_config_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; ------------------------------------------------------------
; MMAL_PARAMETER_AUDIO_DESTINATION = "hdmi".
; D0 = target port handle. CPU-owned shared RAM on entry/exit.
; Parameter header size = 8 + 5 bytes = 13. Worker payload = 32 + 13 = 45.
; ------------------------------------------------------------
vpv01_set_hdmi_destination:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,vpv01_param_port
        clr.l   vpv01_param_status
        clr.l   vpv01_param_size

        move.l  #56,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv01_param_fail
        move.l  a2,a0
        moveq   #13,d7
vpv01_param_clear:
        clr.l   (a0)+
        dbra    d7,vpv01_param_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #45,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_PARAMETER_SET,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$A0200001,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  vpv01_audio_handle,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv01_param_port,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  #MMAL_PARAMETER_AUDIO_DESTINATION,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #13,d0
        jsr     store_le32
        lea     48(a2),a0
        lea     vpv01_audio_dest_hdmi,a1
        moveq   #4,d7
vpv01_param_copy:
        move.b  (a1)+,(a0)+
        dbra    d7,vpv01_param_copy

        add.l   #56,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.w   vpv01_param_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv01_param_wait_setup:
        move.l  #V10_CLEANUP_POLL_COUNT,d7
vpv01_param_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.w   vpv01_param_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv01_param_wait
        jsr     dma_post_all
        bra.w   vpv01_param_fail
vpv01_param_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   vpv01_param_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_param_size
        cmp.l   #28,d0
        bcs.w   vpv01_param_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   vpv01_param_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_PORT_PARAMETER_SET,d0
        bne.w   vpv01_param_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   #$A0200001,d0
        bne.w   vpv01_param_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_param_status
        move.l  vpv01_param_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv01_param_fail
        tst.l   vpv01_param_status
        bne.w   vpv01_param_fail
        moveq   #0,d0
        bra.w   vpv01_param_done
vpv01_param_fail_consume:
        move.l  vpv01_param_size,d0
        jsr     v12a_rx_consume_payload
vpv01_param_fail:
        moveq   #1,d0
vpv01_param_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; ------------------------------------------------------------
; Allocate one aligned DMA input area and generate exactly 0.25 s of
; 440-Hz stereo square wave. Samples are written little-endian bytewise.
; ------------------------------------------------------------
vpv01_prepare_tone:
        movem.l d1-d7/a0-a2/a6,-(sp)
        move.l  a4,a6
        move.l  #BULK_ALLOC_SIZE,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   vpv01_prepare_fail
        move.l  d0,bulk_alloc
        add.l   #$00000fff,d0
        and.l   #$fffff000,d0
        move.l  d0,bulk_pool_base
        cmp.l   #$3f000000,d0
        bcc.w   vpv01_prepare_fail_free
        move.l  d0,d1
        add.l   #INPUT_DMA_SPAN-1,d1
        cmp.l   #$3f000000,d1
        bcc.w   vpv01_prepare_fail_free

        move.l  bulk_pool_base,d0
        move.l  d0,bulk_data_ptr
        move.l  d0,d1
        or.l    #$c0000000,d1
        move.l  d1,bulk_data_bus
        move.l  d0,d2
        add.l   #INPUT_PAGELIST_OFFSET,d2
        move.l  d2,bulk_pagelist_ptr
        move.l  d2,d1
        or.l    #$c0000000,d1
        move.l  d1,bulk_pagelist_bus

        move.l  bulk_data_ptr,a0
        moveq   #0,d6                 ; phase 0..1199
        move.l  #VPV01_TONE_FRAMES-1,d7
vpv01_tone_gen_loop:
        cmpi.l  #VPV01_TONE_HALF,d6
        bcc.w   vpv01_tone_negative
        ; +0x1800, little endian, L + R
        clr.b   (a0)+
        move.b  #$18,(a0)+
        clr.b   (a0)+
        move.b  #$18,(a0)+
        bra.w   vpv01_tone_phase
vpv01_tone_negative:
        ; -0x1800 = 0xE800, little endian, L + R
        clr.b   (a0)+
        move.b  #$E8,(a0)+
        clr.b   (a0)+
        move.b  #$E8,(a0)+
vpv01_tone_phase:
        addi.l  #VPV01_TONE_PHASE_STEP,d6
        cmpi.l  #VPV01_TONE_PHASE_MOD,d6
        bcs.w   vpv01_tone_phase_ok
        subi.l  #VPV01_TONE_PHASE_MOD,d6
vpv01_tone_phase_ok:
        dbra    d7,vpv01_tone_gen_loop

        ; VCHIQ pagelist: length, type WRITE, one compressed contiguous run.
        move.l  bulk_pagelist_ptr,a0
        move.l  #VPV01_TONE_BYTES,d0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  #VPV01_TONE_BYTES,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        move.l  bulk_data_bus,d1
        or.l    d0,d1
        lea     8(a0),a0
        move.l  d1,d0
        jsr     v94_pl_store             ; v96.94: CM4 = 36-bit pagelist

        lea     msg_vpv01_pcm_ready,a1
        move.l  #msg_vpv01_pcm_ready_end-msg_vpv01_pcm_ready,d3
        jsr     print_force
        moveq   #0,d0
        bra.w   vpv01_prepare_done
vpv01_prepare_fail_free:
        lea     bulk_alloc,a0
        move.l  #BULK_ALLOC_SIZE,d0
        jsr     vpv06_free_var_safe
vpv01_prepare_fail:
        lea     msg_vpv01_pcm_fail,a1
        move.l  #msg_vpv01_pcm_fail_end-msg_vpv01_pcm_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv01_prepare_done:
        movem.l (sp)+,d1-d7/a0-a2/a6
        rts

; ------------------------------------------------------------
; Publish one MMAL input header plus one VCHIQ BULK_TX for the PCM block.
; Returns with shared VCHIQ RAM DMA-owned on success.
; ------------------------------------------------------------
vpv01_send_tone_block:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv01_bulk_done
        clr.l   vpv01_buffer_returned

        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        cmp.l   bulk_data_ptr,d0
        bne.w   vpv01_send_fail_nomap
        move.l  vpv01_audio_dma_len,d1
        cmp.l   #BULK_DMA_SIZE,d1
        bcs.w   vpv01_send_fail_post
        move.l  #1,vpv01_audio_dma_active

        move.l  #320,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv01_send_fail_post
        move.l  a2,a0
        moveq   #79,d7
vpv01_send_clear:
        clr.l   (a0)+
        dbra    d7,vpv01_send_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #292,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_BUFFER_FROM_HOST,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #VPV01_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv01_audio_handle,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  vpv01_audio_input,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #VPV01_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     76(a2),a0
        move.l  bulk_data_ptr,d0
        jsr     store_le32
        lea     80(a2),a0
        move.l  port_buf_size,d0
        jsr     store_le32
        lea     84(a2),a0
        move.l  #VPV01_TONE_BYTES,d0
        jsr     store_le32
        ; flags at +92 remain zero. PTS/DTS = MMAL_TIME_UNKNOWN.
        lea     96(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     100(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32
        lea     104(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     108(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32

        lea     304(a2),a3
        move.l  a3,a0
        move.l  #VCHIQ_MSG_BULK_TX,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #8,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  bulk_pagelist_bus,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  #VPV01_TONE_BYTES,d0
        jsr     store_le32

        add.l   #320,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.w   vpv01_send_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv01_send_no_bell:
        moveq   #0,d0
        bra.w   vpv01_send_done
vpv01_send_fail_post:
        tst.l   vpv01_audio_dma_active
        beq.w   vpv01_send_fail_nomap
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
vpv01_send_fail_nomap:
        lea     msg_vpv01_send_fail,a1
        move.l  #msg_vpv01_send_fail_end-msg_vpv01_send_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv01_send_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; ------------------------------------------------------------
; Wait until both BULK_TX_DONE and BUFFER_TO_HOST for our PCM context arrived.
; Success returns with shared VCHIQ RAM CPU-owned and audio DMA mapping closed.
; ------------------------------------------------------------
vpv01_wait_tone_block:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  #V10_CLEANUP_POLL_COUNT,d7
vpv01_wait_loop:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.w   vpv01_wait_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv01_wait_loop
        jsr     dma_post_all
        bra.w   vpv01_wait_fail

vpv01_wait_have:
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   vpv01_wait_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,vpv01_last_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_last_rx_size

        ; Ignore traffic not addressed to this local MMAL service.
        move.l  vpv01_last_rx_msgid,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   vpv01_wait_consume_continue
        move.l  vpv01_last_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   vpv01_wait_consume_continue

        move.l  vpv01_last_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_BULK_TX_DONE,d0
        beq.w   vpv01_wait_bulk_done
        cmp.l   #VCHIQ_MSG_DATA,d0
        beq.w   vpv01_wait_data
        bra.w   vpv01_wait_consume_continue

vpv01_wait_bulk_done:
        move.l  vpv01_last_rx_size,d0
        cmp.l   #4,d0
        bcs.w   vpv01_wait_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #VPV01_TONE_BYTES,d0
        bne.w   vpv01_wait_fail
        move.l  #1,vpv01_bulk_done
        tst.l   vpv01_audio_dma_active
        beq.w   vpv01_wait_consume_check
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
        bra.w   vpv01_wait_consume_check

vpv01_wait_data:
        move.l  vpv01_last_rx_size,d0
        cmp.l   #44,d0
        bcs.w   vpv01_wait_consume_continue
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   vpv01_wait_consume_continue
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_BUFFER_TO_HOST,d0
        bne.w   vpv01_wait_consume_continue
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   vpv01_wait_fail
        lea     40(a2),a0
        jsr     load_le32
        cmp.l   vpv01_audio_input,d0
        bne.w   vpv01_wait_consume_continue
        lea     44(a2),a0
        jsr     load_le32
        cmp.l   #VPV01_BUFFER_CONTEXT,d0
        bne.w   vpv01_wait_consume_continue
        move.l  #1,vpv01_buffer_returned

vpv01_wait_consume_check:
        move.l  vpv01_last_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv01_wait_fail
        tst.l   vpv01_bulk_done
        beq.w   vpv01_wait_more
        tst.l   vpv01_buffer_returned
        bne.w   vpv01_wait_success
vpv01_wait_more:
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv01_wait_loop
        jsr     dma_post_all
        bra.w   vpv01_wait_fail

vpv01_wait_consume_continue:
        move.l  vpv01_last_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv01_wait_fail
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv01_wait_loop
        jsr     dma_post_all
        bra.w   vpv01_wait_fail

vpv01_wait_success:
        moveq   #0,d0
        bra.w   vpv01_wait_done
vpv01_wait_fail:
        tst.l   vpv01_audio_dma_active
        beq.w   vpv01_wait_fail_print
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
vpv01_wait_fail_print:
        lea     msg_vpv01_wait_fail,a1
        move.l  #msg_vpv01_wait_fail_end-msg_vpv01_wait_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv01_wait_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; ------------------------------------------------------------
; VPv06: A0-safe variable-backed Exec FreeMem helper.
; D0 = allocation size, A0 = address of variable containing exact AllocMem base.
;
; The inherited v9_free_var performs FreeMem() and then clears (a0) without
; preserving A0 across the library call. Exec scratch registers may be changed
; by the call. VPv06 saves the variable address explicitly on the stack before
; FreeMem and restores it before clearing the variable.
; ------------------------------------------------------------
vpv06_free_var_safe:
        movem.l d1/a1/a6,-(sp)
        move.l  (a0),a1
        cmpa.l  #0,a1
        beq.s   vpv06_free_var_done
        move.l  d0,d1
        move.l  a0,-(sp)
        move.l  a4,a6
        jsr     FreeMem(a6)
        move.l  (sp)+,a0
        clr.l   (a0)
vpv06_free_var_done:
        movem.l (sp)+,d1/a1/a6
        rts

; ------------------------------------------------------------
; Service-owned teardown. Persistent global VCHIQ slot block remains until
; reboot, exactly as in HDMI_v41L. Stream DMA is freed only after input return.
; ------------------------------------------------------------
vpv01_cleanup:
        movem.l d0-d7/a0-a2/a6,-(sp)
        clr.l   vpv01_cleanup_status

        ; VPv06: keep the hardware-proven VPv05 MMAL/audio path unchanged.
        ; Restore only the two process-local frees using vpv06_free_var_safe.
        ; Persistent slot_alloc remains untouched until reboot as in HDMI_v41L.

        tst.l   vpv01_audio_dma_active
        beq.w   vpv05_cleanup_no_dma
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
vpv05_cleanup_no_dma:

        lea     msg_vpv05_cleanup_disable,a1
        move.l  #msg_vpv05_cleanup_disable_end-msg_vpv05_cleanup_disable,d3
        jsr     print_force

        ; v9 worker/close helpers use port_query_index as shifted local bits.
        move.l  v12f_local_bits,port_query_index
        move.l  vpv01_audio_handle,component_handle
        tst.l   component_handle
        beq.w   vpv05_cleanup_close_service
        tst.l   vpv01_component_enabled
        beq.w   vpv05_cleanup_close_service
        move.l  #MMAL_COMPONENT_DISABLE,d0
        jsr     v9_component_cmd
        tst.l   d0
        beq.w   vpv05_cleanup_close_service
        move.l  #1,vpv01_cleanup_status

vpv05_cleanup_close_service:
        lea     msg_vpv05_cleanup_service,a1
        move.l  #msg_vpv05_cleanup_service_end-msg_vpv05_cleanup_service,d3
        jsr     print_force

        tst.l   mmal_remote_port
        beq.w   vpv05_cleanup_after_close
        jsr     v9_close_service
        tst.l   d0
        beq.w   vpv05_cleanup_after_close
        move.l  #1,vpv01_cleanup_status
vpv05_cleanup_after_close:
        ; Let VideoCore finish service-owned component deletion.
        jsr     dma_pre_all
        move.l  a5,a6
        move.l  #25,d1
        jsr     Delay(a6)
        jsr     dma_post_all

        ; VPv06: reclaim the exact process-local AllocMem bases only.
        lea     msg_vpv06_free_bulk,a1
        move.l  #msg_vpv06_free_bulk_end-msg_vpv06_free_bulk,d3
        jsr     print_force
        lea     bulk_alloc,a0
        move.l  #BULK_ALLOC_SIZE,d0
        jsr     vpv06_free_var_safe

        lea     msg_vpv06_free_prop,a1
        move.l  #msg_vpv06_free_prop_end-msg_vpv06_free_prop,d3
        jsr     print_force
        lea     prop_alloc,a0
        move.l  #$200,d0
        jsr     vpv06_free_var_safe

        lea     msg_vpv06_free_ok,a1
        move.l  #msg_vpv06_free_ok_end-msg_vpv06_free_ok,d3
        jsr     print_force

        clr.l   vpv01_audio_handle
        clr.l   vpv01_audio_input
        clr.l   vpv01_audio_control
        clr.l   component_handle
        clr.l   input_port_handle
        clr.l   mmal_remote_port
        clr.l   vpv01_component_enabled

        tst.l   vpv01_cleanup_status
        beq.w   vpv05_cleanup_status_ok
        move.l  #1,vpv01_test_status
        lea     msg_vpv01_cleanup_fail,a1
        move.l  #msg_vpv01_cleanup_fail_end-msg_vpv01_cleanup_fail,d3
        jsr     print_force
vpv05_cleanup_status_ok:
        ; Persistent VCHIQ RAM must be left in DMA ownership between CLI runs.
        jsr     dma_pre_all
        movem.l (sp)+,d0-d7/a0-a2/a6
        rts

        section data,data
vpv01_audio_render_name:
        dc.b "ril.audio_render",0
        even
vpv116_clock_name:
