; ====================================================================
; VPv18 - SOFTWARE AAC -> HARDWARE HDMI AUDIO
;
; The VideoCore audio_decode experiment is intentionally abandoned here.
; VPv20 inherits the hardware-confirmed VPv06 ril.audio_render PCM path and
; loads MintAMP's external aac.decoder through AmigaDOS LoadSeg().
;
; Decoder module ABI (MintAMP Decoder Module ABI v2):
;   LoadSeg("aac.decoder") -> entry at BADDR(seg)+4 -> DecoderOps*
;   open(read,seek,user,info) -> opaque handle
;   decode(handle, short*, maxSamplesPerChan) -> signed 16-bit native m68k PCM
;
; m68k is big-endian while VPv06's proven MMAL renderer is configured for
; signed little-endian PCM. Therefore every decoded 16-bit sample is byte
; swapped in-place before the VCHIQ/MMAL BULK_TX.
; ====================================================================

DECODER_MODULE_MAGIC     equ $44454300
DECODER_MODULE_VERSION   equ 2
DECOPS_INFO               equ 0
DECOPS_OPEN               equ 4
DECOPS_DECODE             equ 8
DECOPS_SEEK               equ 12
DECOPS_CLOSE              equ 16
DECINFO_MAGIC             equ 0
DECINFO_VERSION           equ 4
DECSTREAM_RATE            equ 0
DECSTREAM_CHANNELS        equ 4
DECSTREAM_BITS            equ 6
DECSTREAM_TOTAL           equ 8
VPV18_MAX_SAMPLES_CH      equ 12000

        section bss,bss
vpv18_seg:                 ds.l 1
vpv18_ops:                 ds.l 1
vpv18_dec_handle:          ds.l 1
vpv18_stream_cur:          ds.l 1
vpv18_pcm_bytes:           ds.l 1
vpv18_pcm_samples:         ds.l 1
vpv18_pcm_blocks:          ds.l 1
vpv18_total_samples:       ds.l 1
vpv18_status:              ds.l 1
vpv18_stream_info:         ds.b 12
        even

        section code,code

vpv18_audio_test:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv01_test_status
        clr.l   vpv18_status
        clr.l   vpv18_seg
        clr.l   vpv18_ops
        clr.l   vpv18_dec_handle
        clr.l   vpv18_pcm_bytes
        clr.l   vpv18_pcm_samples
        clr.l   vpv18_pcm_blocks
        clr.l   vpv18_total_samples

        lea     msg_vpv18_load,a1
        move.l  #msg_vpv18_load_end-msg_vpv18_load,d3
        jsr     print_force
        jsr     vpv18_load_module
        tst.l   d0
        bne.w   vpv18_test_fail

        jsr     vpv18_open_module
        tst.l   d0
        bne.w   vpv18_test_fail

        ; This embedded test asset is known to be AAC-LC, 48 kHz stereo.
        ; Refuse a surprise format so the VPv06 renderer stays unchanged.
        cmpi.l  #VPV01_AUDIO_RATE,vpv18_stream_info+DECSTREAM_RATE
        bne.w   vpv18_bad_format
        cmpi.w  #VPV01_AUDIO_CHANNELS,vpv18_stream_info+DECSTREAM_CHANNELS
        bne.w   vpv18_bad_format
        cmpi.w  #16,vpv18_stream_info+DECSTREAM_BITS
        bne.w   vpv18_bad_format

        lea     msg_vpv18_info,a1
        move.l  #msg_vpv18_info_end-msg_vpv18_info,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv18_stream_info+DECSTREAM_RATE,d0
        jsr     print_hex32
        lea     msg_vpv18_info_ch,a1
        move.l  #msg_vpv18_info_ch_end-msg_vpv18_info_ch,d3
        jsr     print_force
        moveq   #0,d0
        move.w  vpv18_stream_info+DECSTREAM_CHANNELS,d0
        jsr     print_hex32
        lea     msg_vpv18_info_bits,a1
        move.l  #msg_vpv18_info_bits_end-msg_vpv18_info_bits,d3
        jsr     print_force
        moveq   #0,d0
        move.w  vpv18_stream_info+DECSTREAM_BITS,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print

        lea     msg_vpv01_mmal_ready,a1
        move.l  #msg_vpv01_mmal_ready_end-msg_vpv01_mmal_ready,d3
        jsr     print_force
        jsr     vpv01_create_audio_render
        tst.l   d0
        bne.w   vpv18_test_fail
        jsr     vpv01_configure_audio_render
        tst.l   d0
        bne.w   vpv18_test_fail

        ; Reuse VPv06's proven aligned DMA allocation. The synthetic square
        ; wave it writes is never sent: each block is overwritten by decode().
        jsr     vpv01_prepare_tone
        tst.l   d0
        bne.w   vpv18_test_fail

        lea     msg_vpv18_play,a1
        move.l  #msg_vpv18_play_end-msg_vpv18_play,d3
        jsr     print_force

vpv18_decode_loop:
        jsr     vpv18_decode_block
        tst.l   d0
        bmi.w   vpv18_decode_error
        beq.w   vpv18_decode_eof

        move.l  d0,vpv18_pcm_samples
        add.l   d0,vpv18_total_samples
        move.l  d0,d1
        lsl.l   #2,d1                 ; stereo * 16 bit = 4 bytes/sample-frame
        move.l  d1,vpv18_pcm_bytes
        cmpi.l  #VPV01_TONE_BYTES,d1
        bhi.w   vpv18_decode_error

        jsr     vpv18_swap_pcm16
        jsr     vpv18_make_pagelist
        tst.l   d0
        bne.w   vpv18_decode_error
        jsr     vpv18_send_pcm_block
        tst.l   d0
        bne.w   vpv18_decode_error
        jsr     vpv18_wait_pcm_block
        tst.l   d0
        bne.w   vpv18_decode_error
        addq.l  #1,vpv18_pcm_blocks
        bra.w   vpv18_decode_loop

vpv18_decode_eof:
        ; Let audio_render drain its internal queue before tearing it down.
        jsr     dma_pre_all
        move.l  a5,a6
        move.l  #20,d1
        jsr     Delay(a6)
        jsr     dma_post_all

        lea     msg_vpv18_success,a1
        move.l  #msg_vpv18_success_end-msg_vpv18_success,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv18_pcm_blocks,d0
        jsr     print_hex32
        lea     msg_vpv18_success_samples,a1
        move.l  #msg_vpv18_success_samples_end-msg_vpv18_success_samples,d3
        jsr     print_force
        move.l  vpv18_total_samples,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        bra.w   vpv18_cleanup

vpv18_bad_format:
        lea     msg_vpv18_badfmt,a1
        move.l  #msg_vpv18_badfmt_end-msg_vpv18_badfmt,d3
        jsr     print_force
        bra.w   vpv18_test_fail

vpv18_decode_error:
        lea     msg_vpv18_decode_fail,a1
        move.l  #msg_vpv18_decode_fail_end-msg_vpv18_decode_fail,d3
        jsr     print_force
vpv18_test_fail:
        move.l  #1,vpv18_status
        move.l  #1,vpv01_test_status

vpv18_cleanup:
        jsr     vpv18_close_module
        jsr     vpv01_cleanup
        tst.l   vpv01_test_status
        beq.s   vpv18_cleanup_mmal_ok
        move.l  #1,vpv18_status
vpv18_cleanup_mmal_ok:
        tst.l   vpv18_status
        bne.s   vpv18_done
        lea     msg_vpv18_done,a1
        move.l  #msg_vpv18_done_end-msg_vpv18_done,d3
        jsr     print_force
vpv18_done:
        move.l  vpv18_status,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Load the MintAMP decoder. First try the same drawer as VPv18, then the
; original MintAMP "decoders/" layout as a fallback.
vpv18_load_module:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  a5,a6
        ; VPv36: first try decoder next to the executable, independent of CWD.
        lea     vpv18_decoder_name_progdir,a0
        move.l  a0,d1
        jsr     LoadSeg(a6)
        tst.l   d0
        bne.s   vpv18_load_have_seg
        ; Backward-compatible fallbacks: current drawer, then decoders/.
        lea     vpv18_decoder_name,a0
        move.l  a0,d1
        jsr     LoadSeg(a6)
        tst.l   d0
        bne.s   vpv18_load_have_seg
        lea     vpv18_decoder_name_alt,a0
        move.l  a0,d1
        jsr     LoadSeg(a6)
        tst.l   d0
        beq.w   vpv18_load_fail
vpv18_load_have_seg:
        move.l  d0,vpv18_seg
        lsl.l   #2,d0                 ; BADDR(BPTR)
        addq.l  #4,d0                 ; documented DecoderModuleEntry address
        move.l  d0,a0
        jsr     (a0)
        move.l  d0,vpv18_ops
        beq.w   vpv18_load_fail_unload
        move.l  d0,a0
        move.l  DECOPS_INFO(a0),a1
        cmpa.l  #0,a1
        beq.w   vpv18_load_fail_unload
        cmpi.l  #DECODER_MODULE_MAGIC,DECINFO_MAGIC(a1)
        bne.w   vpv18_load_fail_unload
        moveq   #0,d0
        move.w  DECINFO_VERSION(a1),d0
        cmpi.l  #DECODER_MODULE_VERSION,d0
        bhi.w   vpv18_load_fail_unload
        tst.l   DECOPS_OPEN(a0)
        beq.w   vpv18_load_fail_unload
        tst.l   DECOPS_DECODE(a0)
        beq.w   vpv18_load_fail_unload
        tst.l   DECOPS_CLOSE(a0)
        beq.w   vpv18_load_fail_unload
        lea     msg_vpv18_load_ok,a1
        move.l  #msg_vpv18_load_ok_end-msg_vpv18_load_ok,d3
        jsr     print_force
        moveq   #0,d0
        bra.s   vpv18_load_done
vpv18_load_fail_unload:
        clr.l   vpv18_ops
        move.l  vpv18_seg,d1
        beq.s   vpv18_load_fail
        move.l  a5,a6
        jsr     UnLoadSeg(a6)
        clr.l   vpv18_seg
vpv18_load_fail:
        lea     msg_vpv18_load_fail,a1
        move.l  #msg_vpv18_load_fail_end-msg_vpv18_load_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv18_load_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Call DecoderOps.open(readCb, seekCb, userData, &streamInfo) using m68k cdecl.
vpv18_open_module:
        movem.l d2-d7/a2-a6,-(sp)
        lea     vpv18_test_aac,a0
        move.l  a0,vpv18_stream_cur
        lea     vpv18_stream_info,a0
        moveq   #2,d0
vpv18_open_clear:
        clr.l   (a0)+
        dbra    d0,vpv18_open_clear
        move.l  vpv18_ops,a0
        move.l  DECOPS_OPEN(a0),a0
        pea     vpv18_stream_info
        clr.l   -(sp)                  ; userData = NULL
        pea     vpv18_seek_cb
        pea     vpv18_read_cb
        jsr     (a0)
        lea     16(sp),sp
        move.l  d0,vpv18_dec_handle
        beq.s   vpv18_open_fail
        lea     msg_vpv18_open_ok,a1
        move.l  #msg_vpv18_open_ok_end-msg_vpv18_open_ok,d3
        jsr     print_force
        moveq   #0,d0
        bra.s   vpv18_open_done
vpv18_open_fail:
        lea     msg_vpv18_open_fail,a1
        move.l  #msg_vpv18_open_fail_end-msg_vpv18_open_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv18_open_done:
        movem.l (sp)+,d2-d7/a2-a6
        rts

; Decode up to 12000 sample frames/channel directly into the proven DMA area.
; Return D0 = samples/channel, 0 EOF, negative error.
vpv18_decode_block:
        movem.l d2-d7/a2-a6,-(sp)
        move.l  vpv18_ops,a0
        move.l  DECOPS_DECODE(a0),a0
        move.l  #VPV18_MAX_SAMPLES_CH,-(sp)
        move.l  bulk_data_ptr,-(sp)
        move.l  vpv18_dec_handle,-(sp)
        jsr     (a0)
        lea     12(sp),sp
        movem.l (sp)+,d2-d7/a2-a6
        rts

; Native m68k short PCM is big-endian. Swap every 16-bit sample to LE.
vpv18_swap_pcm16:
        movem.l d0-d2/a0,-(sp)
        move.l  vpv18_pcm_bytes,d1
        lsr.l   #1,d1
        beq.s   vpv18_swap_done
        move.l  bulk_data_ptr,a0
vpv18_swap_loop:
        moveq   #0,d0
        move.w  (a0),d0
        rol.w   #8,d0
        move.w  d0,(a0)+
        subq.l  #1,d1
        bne.s   vpv18_swap_loop
vpv18_swap_done:
        movem.l (sp)+,d0-d2/a0
        rts

; Rewrite the VCHIQ pagelist for the actual decoded PCM byte count.
vpv18_make_pagelist:
        movem.l d1-d2/a0,-(sp)
        move.l  vpv18_pcm_bytes,d0
        beq.s   vpv18_pagelist_fail
        cmpi.l  #VPV01_TONE_BYTES,d0
        bhi.s   vpv18_pagelist_fail
        move.l  bulk_pagelist_ptr,a0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  vpv18_pcm_bytes,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        move.l  bulk_data_bus,d1
        or.l    d0,d1
        lea     8(a0),a0
        move.l  d1,d0
        jsr     v94_pl_store             ; v96.94: CM4 = 36-bit pagelist
        moveq   #0,d0
        bra.s   vpv18_pagelist_done
vpv18_pagelist_fail:
        moveq   #1,d0
vpv18_pagelist_done:
        movem.l (sp)+,d1-d2/a0
        rts

; DecoderReadCb(void *user, unsigned char *buf, unsigned long maxBytes)
; cdecl stack: 4(sp)=user, 8(sp)=buf, 12(sp)=maxBytes.
vpv18_read_cb:
        move.l  12(sp),d0
        move.l  #vpv18_test_aac_end,d1
        sub.l   vpv18_stream_cur,d1
        cmp.l   d1,d0
        bls.s   vpv18_read_count_ok
        move.l  d1,d0
vpv18_read_count_ok:
        tst.l   d0
        beq.s   vpv18_read_done
        move.l  d0,d1
        move.l  vpv18_stream_cur,a1
        move.l  8(sp),a0
vpv18_read_loop:
        move.b  (a1)+,(a0)+
        subq.l  #1,d1
        bne.s   vpv18_read_loop
        move.l  a1,vpv18_stream_cur
vpv18_read_done:
        rts

; DecoderSeekCb(void *user, long offset, int whence), 0/1/2=set/cur/end.
vpv18_seek_cb:
        move.l  12(sp),d1
        cmpi.l  #0,d1
        beq.s   vpv18_seek_set
        cmpi.l  #1,d1
        beq.s   vpv18_seek_cur
        cmpi.l  #2,d1
        beq.s   vpv18_seek_end
        bra.s   vpv18_seek_fail
vpv18_seek_set:
        lea     vpv18_test_aac,a0
        bra.s   vpv18_seek_add
vpv18_seek_cur:
        move.l  vpv18_stream_cur,a0
        bra.s   vpv18_seek_add
vpv18_seek_end:
        lea     vpv18_test_aac_end,a0
vpv18_seek_add:
        adda.l  8(sp),a0
        move.l  a0,d0
        move.l  #vpv18_test_aac,d1
        cmp.l   d1,d0
        bcs.s   vpv18_seek_fail
        move.l  #vpv18_test_aac_end,d1
        cmp.l   d1,d0
        bhi.s   vpv18_seek_fail
        move.l  a0,vpv18_stream_cur
        moveq   #0,d0
        rts
vpv18_seek_fail:
        moveq   #-1,d0
        rts

; Close decoder state first, then unload the hunk after no module code is active.
vpv18_close_module:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  vpv18_dec_handle,d0
        beq.s   vpv18_close_unload
        move.l  vpv18_ops,a0
        move.l  DECOPS_CLOSE(a0),a0
        move.l  vpv18_dec_handle,-(sp)
        jsr     (a0)
        addq.l  #4,sp
        clr.l   vpv18_dec_handle
        lea     msg_vpv18_close_ok,a1
        move.l  #msg_vpv18_close_ok_end-msg_vpv18_close_ok,d3
        jsr     print_force
vpv18_close_unload:
        clr.l   vpv18_ops
        move.l  vpv18_seg,d1
        beq.s   vpv18_close_done
        move.l  a5,a6
        jsr     UnLoadSeg(a6)
        clr.l   vpv18_seg
        lea     msg_vpv18_unload_ok,a1
        move.l  #msg_vpv18_unload_ok_end-msg_vpv18_unload_ok,d3
        jsr     print_force
vpv18_close_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


vpv18_send_pcm_block:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv01_bulk_done
        clr.l   vpv01_buffer_returned

        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        cmp.l   bulk_data_ptr,d0
        bne.w   vpv18_send_fail_nomap
        move.l  vpv01_audio_dma_len,d1
        cmp.l   #BULK_DMA_SIZE,d1
        bcs.w   vpv18_send_fail_post
        move.l  #1,vpv01_audio_dma_active

        move.l  #320,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv18_send_fail_post
        move.l  a2,a0
        moveq   #79,d7
vpv18_send_clear:
        clr.l   (a0)+
        dbra    d7,vpv18_send_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #292,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_BUFFER_FROM_HOST,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #VPV01_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv01_audio_handle,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  vpv01_audio_input,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #VPV01_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     76(a2),a0
        move.l  bulk_data_ptr,d0
        jsr     store_le32
        lea     80(a2),a0
        move.l  port_buf_size,d0
        jsr     store_le32
        lea     84(a2),a0
        move.l  vpv18_pcm_bytes,d0
        jsr     store_le32
        ; flags at +92 remain zero. PTS/DTS = MMAL_TIME_UNKNOWN.
        lea     96(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     100(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32
        lea     104(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     108(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32

        lea     304(a2),a3
        move.l  a3,a0
        move.l  #VCHIQ_MSG_BULK_TX,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #8,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  bulk_pagelist_bus,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  vpv18_pcm_bytes,d0
        jsr     store_le32

        add.l   #320,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.w   vpv18_send_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv18_send_no_bell:
        moveq   #0,d0
        bra.w   vpv18_send_done
vpv18_send_fail_post:
        tst.l   vpv01_audio_dma_active
        beq.w   vpv18_send_fail_nomap
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
vpv18_send_fail_nomap:
        lea     msg_vpv01_send_fail,a1
        move.l  #msg_vpv01_send_fail_end-msg_vpv01_send_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv18_send_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


vpv18_wait_pcm_block:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  #V10_CLEANUP_POLL_COUNT,d7
vpv18_wait_loop:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.w   vpv18_wait_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv18_wait_loop
        jsr     dma_post_all
        bra.w   vpv18_wait_fail

vpv18_wait_have:
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   vpv18_wait_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,vpv01_last_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_last_rx_size

        ; Ignore traffic not addressed to this local MMAL service.
        move.l  vpv01_last_rx_msgid,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   vpv18_wait_consume_continue
        move.l  vpv01_last_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   vpv18_wait_consume_continue

        move.l  vpv01_last_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_BULK_TX_DONE,d0
        beq.w   vpv18_wait_bulk_done
        cmp.l   #VCHIQ_MSG_DATA,d0
        beq.w   vpv18_wait_data
        bra.w   vpv18_wait_consume_continue

vpv18_wait_bulk_done:
        move.l  vpv01_last_rx_size,d0
        cmp.l   #4,d0
        bcs.w   vpv18_wait_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   vpv18_pcm_bytes,d0
        bne.w   vpv18_wait_fail
        move.l  #1,vpv01_bulk_done
        tst.l   vpv01_audio_dma_active
        beq.w   vpv18_wait_consume_check
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
        bra.w   vpv18_wait_consume_check

vpv18_wait_data:
        move.l  vpv01_last_rx_size,d0
        cmp.l   #44,d0
        bcs.w   vpv18_wait_consume_continue
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   vpv18_wait_consume_continue
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_BUFFER_TO_HOST,d0
        bne.w   vpv18_wait_consume_continue
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   vpv18_wait_fail
        lea     40(a2),a0
        jsr     load_le32
        cmp.l   vpv01_audio_input,d0
        bne.w   vpv18_wait_consume_continue
        lea     44(a2),a0
        jsr     load_le32
        cmp.l   #VPV01_BUFFER_CONTEXT,d0
        bne.w   vpv18_wait_consume_continue
        move.l  #1,vpv01_buffer_returned

vpv18_wait_consume_check:
        move.l  vpv01_last_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv18_wait_fail
        tst.l   vpv01_bulk_done
        beq.w   vpv18_wait_more
        tst.l   vpv01_buffer_returned
        bne.w   vpv18_wait_success
vpv18_wait_more:
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv18_wait_loop
        jsr     dma_post_all
        bra.w   vpv18_wait_fail

vpv18_wait_consume_continue:
        move.l  vpv01_last_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv18_wait_fail
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv18_wait_loop
        jsr     dma_post_all
        bra.w   vpv18_wait_fail

vpv18_wait_success:
        moveq   #0,d0
        bra.w   vpv18_wait_done
vpv18_wait_fail:
        tst.l   vpv01_audio_dma_active
        beq.w   vpv18_wait_fail_print
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
vpv18_wait_fail_print:
        lea     msg_vpv01_wait_fail,a1
        move.l  #msg_vpv01_wait_fail_end-msg_vpv01_wait_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv18_wait_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts



; ====================================================================
; VPv20 - REAL MATROSKA AAC LONG PREFIX -> MINTAMP/HELIX -> PCM -> RPi HDMI
;
; This is deliberately the next bounded integration step, not yet A/V mixing:
;   VPv20 <film.mkv>
;     1) parse the existing V41L Matroska Tracks metadata,
;     2) select first A_AAC track,
;     3) extract up to 4096 real unlaced AAC access units from the MKV,
;     4) synthesize ADTS headers from CodecPrivate/AudioSpecificConfig,
;     5) decode with MintAMP aac.decoder,
;     6) send resulting PCM through the hardware-confirmed VPv06 renderer.
;
; The purpose is to prove REAL container AAC before merging it into the live
; H.264 playback loop. VPv181 extends the active rolling MKV reader with
; Xiph/fixed/EBML AAC lacing while keeping the same bounded ADTS/FAAD path.
; ====================================================================

VPV19_AAC_BUF_SIZE      equ $00020000      ; VPv47: 128 KiB rolling ADTS window (movie length independent)
VPV19_TARGET_FRAMES     equ 4096              ; legacy prefix extractor only; VPv47 active path does not use this cap
VPV43_AUDIO_IO_SIZE     equ $00010000          ; independent 64 KiB MKV audio reader window
VPV43_ADTS_FILL_FRAMES  equ 128                ; refill granularity, bounded by 128 KiB ADTS window
VPV43_SYNC_SAMPLES_CH   equ 16384              ; VPv47: ~341-372 ms PCM blocks, fills one 64-KiB stereo/16-bit MMAL buffer
VPV43_TIMECODE_SCALE_MS equ 1000000             ; first PTS scheduler supports Matroska default 1 ms ticks
VPV44_ADTS_TOPUP_THRESHOLD equ $00004000         ; 16 KiB: top up outside Helix callback

        section bss,bss
v19_aac_found:              ds.l 1
v19_audio_track_num:        ds.l 1
v19_audio_codecpriv_len:    ds.l 1
v19_audio_probe_channels:   ds.l 1
v19_audio_codecpriv:        ds.b 16
v19_aac_buf_ptr:            ds.l 1
v19_aac_buf_len:            ds.l 1
v19_aac_buf_cur:            ds.l 1
v19_aac_frame_count:        ds.l 1
v19_audio_payload_len:      ds.l 1
v19_audio_lacing_seen:      ds.l 1
v19_adts_profile:           ds.l 1
v19_adts_freqidx:           ds.l 1
v19_adts_channels:          ds.l 1
v19_pcm_channels:           ds.l 1
v19_pcm_rate:               ds.l 1
v19_pcm_bits:               ds.l 1
v19_pcm_blockalign:         ds.l 1
v19_pcm_bitrate:            ds.l 1
v19_test_status:            ds.l 1
        even

        section code,code

; Exact CodecID comparison against Matroska "A_AAC".
v19_codec_is_aac:
        movem.l d1-d3/a0-a1,-(sp)
        move.l  v10_cur_codec_len,d1
        cmpi.l  #5,d1
        bne.s   v19_codec_aac_no
        move.l  v10_cur_codec_ptr,a0
        lea     v19_codec_aac,a1
        moveq   #4,d3
v19_codec_aac_cmp:
        move.b  (a0)+,d1
        cmp.b   (a1)+,d1
        bne.s   v19_codec_aac_no
        dbra    d3,v19_codec_aac_cmp
        moveq   #1,d0
        bra.s   v19_codec_aac_done
v19_codec_aac_no:
        moveq   #0,d0
v19_codec_aac_done:
        movem.l (sp)+,d1-d3/a0-a1
        rts

; We arrive here after DOS/Output are open but before the VCHIQ bootstrap.
; Parse one filename, probe Tracks, and convert a bounded real AAC prefix to
; an in-memory ADTS stream.  Only then enter the proven VPv06 MMAL startup.
vpv19_cli_entry:
        jsr     h264rgb_parse_arg
        tst.l   d0
        beq.s   vpv19_cli_have_arg
        ; berryVP 9.2: usage must be visible even though normal playback defaults
        ; to quiet mode.  DOS and Output() are already open at this point.
        move.l  #1,mkvr7_log_mode
        lea     msg_v19_usage,a1
        move.l  #msg_v19_usage_end-msg_v19_usage,d3
        jsr     print_force
        bra.w   vpv19_cli_fail_exit
vpv19_cli_have_arg:
        ; VPr9/berryVP: exact '?' is a side-effect-free help request.
        ; It exits before MKV probing, AAC setup, VCHIQ or MMAL initialization.
        cmpi.b  #$3F,t23_file_name
        bne.s   berryvp_cli_not_help
        tst.b   t23_file_name+1
        bne.s   berryvp_cli_not_help
        ; berryVP 9.2: '?' is an explicit UI request, so force this one
        ; message to the Shell instead of letting quiet mode suppress it.
        move.l  #1,mkvr7_log_mode
        lea     msg_usage,a1
        move.l  #msg_usage_end-msg_usage,d3
        jsr     print_force
        bra.w   vpv19_cli_fail_exit
berryvp_cli_not_help:
        ; berryVP 9.2: resolve R/resume BEFORE the early T:/IDR/AAC path.
        ; R must be semantically identical to typing the stored T:/W: values
        ; on the CLI.  VPr8 loaded the .t only later in h264rgb_arg_ok, after
        ; this early AAC/IDR preparation had already happened; that made R use
        ; old hidden video fast-forward while AAC still started at 0:00.
        ; Load the bookmark now.  The later shared parser runs again only to
        ; resolve final W:/CLI precedence; vpr8_resume_loaded prevents reread.
        jsr     vpr8_parse_resume_arg
        tst.l   vpr8_resume_requested
        beq.s   berryvp92_early_resume_ready
        jsr     vpr8_load_resume_file
        tst.l   d0
        beq.s   berryvp92_early_resume_ready
        cmpi.l  #1,d0
        bne.s   berryvp92_early_resume_bad_file
        lea     msg_vpr8_resume_missing,a1
        move.l  #msg_vpr8_resume_missing_end-msg_vpr8_resume_missing,d3
        jsr     vpr8_print_resume_error_path
        bra.w   vpv19_cli_fail_exit
berryvp92_early_resume_bad_file:
        lea     msg_vpr8_resume_invalid,a1
        move.l  #msg_vpr8_resume_invalid_end-msg_vpr8_resume_invalid,d3
        jsr     vpr8_print_resume_error_path
        bra.w   vpv19_cli_fail_exit
berryvp92_early_resume_ready:

        ; Parse an explicit CLI T: first.  If no T: was supplied, install the
        ; already-loaded resume time as the effective early T: BEFORE the
        ; independent AAC reader, compressed H264 IDR scan and FAAD priming.
        ; An explicit CLI T: therefore still has priority over the .t value.
        jsr     v40j_parse_time_arg
        tst.l   d0
        beq.s   berryvp92_early_time_parsed
        lea     msg_v40j_bad_time,a1
        move.l  #msg_v40j_bad_time_end-msg_v40j_bad_time,d3
        jsr     print_force
        lea     msg_usage,a1
        move.l  #msg_usage_end-msg_usage,d3
        jsr     print_force
        bra.w   vpv19_cli_fail_exit
berryvp92_early_time_parsed:
        tst.l   v40j_start_time_valid
        bne.s   vpv005r3_early_time_ok
        tst.l   vpr8_resume_requested
        beq.s   vpv005r3_early_time_ok
        tst.l   vpr8_resume_loaded
        beq.s   vpv005r3_early_time_ok
        move.l  vpr8_resume_time_secs,v40j_start_time_secs
        move.l  #1,v40j_start_time_valid
vpv005r3_early_time_ok:
        ; mkvr7 is Matroska-only. Keep the hardware-proven
        ; VPv102 EBML/Tracks/Cluster path intact.
        jsr     v10_is_mkv
        tst.l   d0
        bne.w   vpv19_cli_is_mkv
        lea     msg_v19_need_mkv,a1
        move.l  #msg_v19_need_mkv_end-msg_v19_need_mkv,d3
        jsr     print_force
        bra.w   vpv19_cli_fail_exit

; VPv102 MKV path re-enabled inside the later shared playback core.
; Container parsing and Matroska AAC extraction remain on the proven routines.
vpv19_cli_is_mkv:
        lea     msg_v19_probe,a1
        move.l  #msg_v19_probe_end-msg_v19_probe,d3
        jsr     print_force
        jsr     v10_mkv_probe

        ; R5 T: resolve the requested start time to a real H.264 IDR BEFORE
        ; VCHIQ/MMAL and before AAC priming.  This is a compressed Matroska
        ; scan only: no decoder/output graph exists and no hidden video frames
        ; are rendered.  The first IDR at/after T: becomes the effective start.
        jsr     v005r5_prepare_video_seek
        tst.l   d0
        beq.s   v005r5_video_seek_ready
        lea     msg_v005r5_seek_fail,a1
        move.l  #msg_v005r5_seek_fail_end-msg_v005r5_seek_fail,d3
        jsr     print_force
        bra.w   vpv19_cli_fail_exit
v005r5_video_seek_ready:
        tst.l   v19_aac_found
        beq.w   vpv19_cli_no_aac
        tst.l   v19_audio_track_num
        beq.w   vpv19_cli_no_aac
        cmpi.l  #2,v19_audio_codecpriv_len
        bcs.w   vpv19_cli_no_aac
        jsr     vpv19_parse_asc
        tst.l   d0
        bne.w   vpv19_cli_bad_asc
        ; VPv47: open a second bounded Matroska reader for AAC.  It remains
        ; independent of the existing 64-KiB H264 reader and refills a small
        ; rolling ADTS window on demand. There is no movie-duration frame cap.
        jsr     vpv43_audio_stream_prepare
        tst.l   d0
        bne.w   vpv19_cli_extract_fail
        lea     msg_vpv43_stream_ready,a1
        move.l  #msg_vpv43_stream_ready_end-msg_vpv43_stream_ready,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  v19_aac_frame_count,d0
        jsr     print_hex32
        lea     msg_v19_extract_bytes,a1
        move.l  #msg_v19_extract_bytes_end-msg_v19_extract_bytes,d3
        jsr     print_force
        move.l  v19_aac_buf_len,d0
        jsr     print_hex32
        lea     msg_vpv43_first_audio_pts,a1
        move.l  #msg_vpv43_first_audio_pts_end-msg_vpv43_first_audio_pts,d3
        jsr     print_force
        move.l  vpv43_first_audio_pts_ticks,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print

        ; VPv21T: decode exactly one real AAC PCM block into a small
        ; Fast-RAM DMA area before VideoCore playback starts.
        ; This keeps Helix/68k work out of the first simultaneous A/V test.
        jsr     vpv21_predecode_pcm
        tst.l   d0
        bne.w   vpv19_cli_extract_fail
        lea     msg_vpv21n_after_predecode,a1
        move.l  #msg_vpv21n_after_predecode_end-msg_vpv21n_after_predecode,d3
        jsr     vpv21n_trace

        ; VPv21T isolation: RETAIN the correctly allocated PCM block during the
        ; complete HDMI_v41L video run.  VPv21S proved the corrected FreeMem ABI.
        ; This test repeats P/Q with the FreeMem fix, but still creates NO audio_render.
        lea     msg_vpv21t_pcm_retained_before_video,a1
        move.l  #msg_vpv21t_pcm_retained_before_video_end-msg_vpv21t_pcm_retained_before_video,d3
        jsr     vpv21n_trace

        ; Continue into the unchanged HDMI_v41L H264/MKV preparation path.
        ; h264rgb_parse_arg already filled t23_file_name, so enter after it.
        jmp     h264rgb_arg_ok

vpv19_cli_no_aac:
        lea     msg_v19_no_aac,a1
        move.l  #msg_v19_no_aac_end-msg_v19_no_aac,d3
        jsr     print_force
        bra.s   vpv19_cli_fail_exit
vpv19_cli_bad_asc:
        lea     msg_v19_bad_asc,a1
        move.l  #msg_v19_bad_asc_end-msg_v19_bad_asc,d3
        jsr     print_force
        bra.s   vpv19_cli_fail_exit
vpv19_cli_extract_fail:
        lea     msg_v19_extract_fail,a1
        move.l  #msg_v19_extract_fail_end-msg_v19_extract_fail,d3
        jsr     print_force
        jsr     vpv19_free_aac_buffer
vpv19_cli_fail_exit:
        ; h264rgb_main saved these registers on entry. No VCHIQ state exists yet.
        move.l  t23_file_handle,d0
        beq.s   vpv19_cli_no_open_file
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
vpv19_cli_no_open_file:
        jsr     v10b_stream_reset
        jsr     mkvr7_close_log
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

; Parse the first two bytes of MPEG-4 AudioSpecificConfig. v19 intentionally
; accepts AAC-LC only (audioObjectType=2), with an explicit sampling-frequency
; index and mono/stereo channelConfiguration.
vpv19_parse_asc:
        movem.l d1-d4/a0,-(sp)
        lea     v19_audio_codecpriv,a0
        moveq   #0,d1
        move.b  (a0),d1
        moveq   #0,d2
        move.b  1(a0),d2
        move.l  d1,d0
        lsr.l   #3,d0
        andi.l  #$1f,d0
        cmpi.l  #2,d0                  ; AAC-LC only in this first real MKV test
        bne.s   vpv19_asc_fail
        subq.l  #1,d0                  ; ADTS profile = objectType - 1
        move.l  d0,v19_adts_profile
        move.l  d1,d0
        andi.l  #7,d0
        lsl.l   #1,d0
        move.l  d2,d3
        lsr.l   #7,d3
        andi.l  #1,d3
        or.l    d3,d0
        cmpi.l  #12,d0
        bhi.s   vpv19_asc_fail
        move.l  d0,v19_adts_freqidx
        move.l  d2,d0
        lsr.l   #3,d0
        andi.l  #$0f,d0
        cmpi.l  #1,d0
        bcs.s   vpv19_asc_fail
        cmpi.l  #2,d0
        bhi.s   vpv19_asc_fail
        move.l  d0,v19_adts_channels
        moveq   #0,d0
        bra.s   vpv19_asc_done
vpv19_asc_fail:
        moveq   #1,d0
vpv19_asc_done:
        movem.l (sp)+,d1-d4/a0
        rts

; Find and extract up to 4096 actual AAC access units from the original MKV.
; Output is a contiguous ADTS stream in Fast RAM.
vpv19_extract_aac_prefix:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   v19_aac_buf_ptr
        clr.l   v19_aac_buf_len
        clr.l   v19_aac_buf_cur
        clr.l   v19_aac_frame_count
        clr.l   v19_audio_lacing_seen
        clr.l   v10b_segment_end

        move.l  a4,a6
        move.l  #VPV19_AAC_BUF_SIZE,d0
        move.l  #MEMF_FAST,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   vpv19_extract_fail
        move.l  d0,v19_aac_buf_ptr
        move.l  d0,v19_aac_buf_cur

        jsr     v10b_stream_open
        tst.l   d0
        bne.w   vpv19_extract_fail_close
vpv19_extract_loop:
        move.l  v19_aac_frame_count,d0
        cmpi.l  #VPV19_TARGET_FRAMES,d0
        bcc.w   vpv19_extract_success
        jsr     vpv19_find_audio_block
        tst.l   d0
        beq.s   vpv19_extract_have_block
        cmpi.l  #2,d0
        beq.w   vpv19_extract_eof
        bra.w   vpv19_extract_fail_close
vpv19_extract_have_block:
        move.l  v19_audio_payload_len,d0
        addq.l  #7,d0
        move.l  v19_aac_buf_len,d1
        add.l   d0,d1
        cmpi.l  #VPV19_AAC_BUF_SIZE,d1
        bhi.w   vpv19_extract_success
        move.l  v19_audio_payload_len,d0
        jsr     vpv19_append_adts_header
        tst.l   d0
        bne.w   vpv19_extract_fail_close
        move.l  v19_audio_payload_len,d0
        jsr     vpv19_copy_audio_payload
        tst.l   d0
        bne.w   vpv19_extract_fail_close
        addq.l  #1,v19_aac_frame_count
        bra.w   vpv19_extract_loop
vpv19_extract_eof:
        tst.l   v19_aac_frame_count
        bne.s   vpv19_extract_eof_have
        tst.l   v19_audio_lacing_seen
        beq.w   vpv19_extract_fail_close
        lea     msg_v19_lacing,a1
        move.l  #msg_v19_lacing_end-msg_v19_lacing,d3
        jsr     print_force
        bra.w   vpv19_extract_fail_close
vpv19_extract_eof_have:
vpv19_extract_success:
        moveq   #0,d7
        bra.s   vpv19_extract_close
vpv19_extract_fail_close:
        moveq   #1,d7
vpv19_extract_close:
        move.l  t23_file_handle,d0
        beq.s   vpv19_extract_closed
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
vpv19_extract_closed:
        jsr     v10b_stream_reset
        tst.l   d7
        beq.s   vpv19_extract_ok
vpv19_extract_fail:
        jsr     vpv19_free_aac_buffer
        moveq   #1,d0
        bra.s   vpv19_extract_done
vpv19_extract_ok:
        moveq   #0,d0
vpv19_extract_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Parse one Block/SimpleBlock payload. D0 contains payload bytes on entry.
; D0=0 selected, unlaced AAC block ready with reader at raw AAC payload;
; D0=3 other/laced block skipped; D0=1 malformed.
vpv19_begin_audio_block:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  d0,d7
        cmpi.l  #4,d7
        bcs.w   vpv19_audio_block_fail
        jsr     v10b_read_size
        tst.l   d0
        bne.w   vpv19_audio_block_fail
        move.l  d1,d6                  ; track number
        move.l  d2,d5                  ; track VINT bytes
        move.l  d5,d4
        addq.l  #3,d4                  ; timecode(2)+flags(1)
        cmp.l   d7,d4
        bhi.w   vpv19_audio_block_fail
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   vpv19_audio_block_fail
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   vpv19_audio_block_fail
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   vpv19_audio_block_fail
        move.l  d1,d2                  ; flags
        sub.l   d4,d7
        cmp.l   v19_audio_track_num,d6
        beq.s   vpv19_audio_selected
        move.l  d7,d0
        jsr     v10b_skip_bytes
        tst.l   d0
        bne.s   vpv19_audio_block_fail
        moveq   #3,d0
        bra.s   vpv19_audio_block_done
vpv19_audio_selected:
        move.l  d2,d1
        andi.l  #$00000006,d1
        beq.s   vpv19_audio_unlaced
        move.l  #1,v19_audio_lacing_seen
        move.l  d7,d0
        jsr     v10b_skip_bytes
        tst.l   d0
        bne.s   vpv19_audio_block_fail
        moveq   #3,d0
        bra.s   vpv19_audio_block_done
vpv19_audio_unlaced:
        tst.l   d7
        beq.s   vpv19_audio_block_fail
        move.l  d7,v19_audio_payload_len
        moveq   #0,d0
        bra.s   vpv19_audio_block_done
vpv19_audio_block_fail:
        moveq   #1,d0
vpv19_audio_block_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Sequential Matroska walker modelled after v10b_find_video_block, but dispatches
; only the selected AAC track and leaves its payload unread for the caller.
vpv19_find_audio_block:
        movem.l d1-d7/a0-a3,-(sp)
vpv19_find_loop:
        move.l  v10b_blockgroup_end,d1
        beq.s   vpv19_find_check_cluster
        cmpi.l  #$FFFFFFFF,d1
        beq.s   vpv19_find_check_cluster
        move.l  v10b_abs_pos,d2
        cmp.l   d1,d2
        bcs.s   vpv19_find_check_cluster
        clr.l   v10b_blockgroup_end
vpv19_find_check_cluster:
        move.l  v10b_cluster_end,d1
        beq.s   vpv19_find_header
        cmpi.l  #$FFFFFFFF,d1
        beq.s   vpv19_find_header
        move.l  v10b_abs_pos,d2
        cmp.l   d1,d2
        bcs.s   vpv19_find_header
        clr.l   v10b_cluster_active
        clr.l   v10b_cluster_end
        clr.l   v10b_blockgroup_end
vpv19_find_header:
        jsr     v10b_read_id
        cmpi.l  #2,d0
        beq.w   vpv19_find_eof
        tst.l   d0
        bne.w   vpv19_find_fail
        move.l  d1,d5
        jsr     v10b_read_size
        tst.l   d0
        bne.w   vpv19_find_fail
        move.l  d1,d6
        move.l  #$FFFFFFFF,d7
        cmpi.l  #$FFFFFFFF,d6
        beq.s   vpv19_find_end_ready
        move.l  v10b_abs_pos,d7
        add.l   d6,d7
        bcs.w   vpv19_find_fail
vpv19_find_end_ready:
        cmpi.l  #$1A45DFA3,d5
        beq.w   vpv19_find_skip
        cmpi.l  #$18538067,d5
        beq.w   vpv19_find_segment
        cmpi.l  #$1F43B675,d5
        beq.w   vpv19_find_cluster
        cmpi.l  #$114D9B74,d5
        beq.s   vpv19_find_segment_meta
        cmpi.l  #$1549A966,d5
        beq.s   vpv19_find_segment_meta
        cmpi.l  #$1654AE6B,d5
        beq.s   vpv19_find_segment_meta
        cmpi.l  #$1C53BB6B,d5
        beq.s   vpv19_find_segment_meta
        cmpi.l  #$1254C367,d5
        beq.s   vpv19_find_segment_meta
        cmpi.l  #$1941A469,d5
        beq.s   vpv19_find_segment_meta
        cmpi.l  #$1043A770,d5
        beq.s   vpv19_find_segment_meta
        bra.s   vpv19_find_cluster_children
vpv19_find_segment_meta:
        move.l  v10b_cluster_end,d1
        cmpi.l  #$FFFFFFFF,d1
        bne.w   vpv19_find_skip
        clr.l   v10b_cluster_active
        clr.l   v10b_cluster_end
        clr.l   v10b_blockgroup_end
        bra.w   vpv19_find_skip
vpv19_find_cluster_children:
        tst.l   v10b_cluster_active
        beq.w   vpv19_find_skip
        cmpi.l  #$000000E7,d5
        beq.w   vpv19_find_timecode
        cmpi.l  #$000000A0,d5
        beq.w   vpv19_find_blockgroup
        cmpi.l  #$000000A3,d5
        beq.w   vpv19_find_block
        cmpi.l  #$000000A1,d5
        bne.w   vpv19_find_skip
        tst.l   v10b_blockgroup_end
        beq.w   vpv19_find_skip
        bra.w   vpv19_find_block
vpv19_find_segment:
        move.l  d7,v10b_segment_end
        bra.w   vpv19_find_loop
vpv19_find_cluster:
        move.l  #1,v10b_cluster_active
        move.l  d7,v10b_cluster_end
        clr.l   v10b_blockgroup_end
        clr.l   v10b_cluster_timecode_live
        bra.w   vpv19_find_loop
vpv19_find_blockgroup:
        move.l  d7,v10b_blockgroup_end
        bra.w   vpv19_find_loop
vpv19_find_timecode:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   vpv19_find_fail
        move.l  d6,d0
        jsr     v10b_read_uint
        tst.l   d0
        bne.w   vpv19_find_fail
        move.l  d1,v10b_cluster_timecode_live
        bra.w   vpv19_find_loop
vpv19_find_block:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   vpv19_find_fail
        move.l  d6,d0
        jsr     vpv19_begin_audio_block
        tst.l   d0
        beq.s   vpv19_find_found
        cmpi.l  #3,d0
        beq.w   vpv19_find_loop
        bra.w   vpv19_find_fail
vpv19_find_skip:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   vpv19_find_fail
        move.l  d6,d0
        jsr     v10b_skip_bytes
        tst.l   d0
        bne.w   vpv19_find_fail
        bra.w   vpv19_find_loop
vpv19_find_found:
        moveq   #0,d0
        bra.s   vpv19_find_done
vpv19_find_eof:
        moveq   #2,d0
        bra.s   vpv19_find_done
vpv19_find_fail:
        moveq   #1,d0
vpv19_find_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; D0 = raw AAC payload bytes. Append a seven-byte MPEG-4 ADTS header.
vpv19_append_adts_header:
        movem.l d1-d7/a0,-(sp)
        move.l  d0,d7
        addq.l  #7,d7                  ; full ADTS frame length
        cmpi.l  #$1fff,d7
        bhi.w   vpv19_adts_fail
        move.l  v19_aac_buf_cur,a0
        move.b  #$ff,(a0)+
        move.b  #$f1,(a0)+             ; MPEG-4, layer 0, protection_absent
        move.l  v19_adts_profile,d1
        lsl.l   #6,d1
        move.l  v19_adts_freqidx,d2
        lsl.l   #2,d2
        or.l    d2,d1
        move.l  v19_adts_channels,d2
        lsr.l   #2,d2
        or.l    d2,d1
        move.b  d1,(a0)+
        move.l  v19_adts_channels,d1
        andi.l  #3,d1
        lsl.l   #6,d1
        move.l  d7,d2
        lsr.l   #8,d2
        lsr.l   #3,d2
        andi.l  #3,d2
        or.l    d2,d1
        move.b  d1,(a0)+
        move.l  d7,d1
        lsr.l   #3,d1
        move.b  d1,(a0)+
        move.l  d7,d1
        andi.l  #7,d1
        lsl.l   #5,d1
        ori.l   #$1f,d1
        move.b  d1,(a0)+
        move.b  #$fc,(a0)+             ; VBR fullness + 1 raw_data_block
        move.l  a0,v19_aac_buf_cur
        addq.l  #7,v19_aac_buf_len
        moveq   #0,d0
        bra.s   vpv19_adts_done
vpv19_adts_fail:
        moveq   #1,d0
vpv19_adts_done:
        movem.l (sp)+,d1-d7/a0
        rts

; D0 = bytes. Copy selected raw AAC payload from the bounded MKV reader into
; the ADTS output buffer.
vpv19_copy_audio_payload:
        movem.l d1-d7/a0,-(sp)
        move.l  d0,d7
        move.l  v19_aac_buf_cur,a0
vpv19_copy_audio_loop:
        tst.l   d7
        beq.s   vpv19_copy_audio_ok
        jsr     v10b_get_byte
        tst.l   d0
        bne.s   vpv19_copy_audio_fail
        move.b  d1,(a0)+
        addq.l  #1,v19_aac_buf_len
        subq.l  #1,d7
        bra.s   vpv19_copy_audio_loop
vpv19_copy_audio_ok:
        move.l  a0,v19_aac_buf_cur
        moveq   #0,d0
        bra.s   vpv19_copy_audio_done
vpv19_copy_audio_fail:
        moveq   #1,d0
vpv19_copy_audio_done:
        movem.l (sp)+,d1-d7/a0
        rts

vpv19_free_aac_buffer:
        movem.l d0-d2/a1/a6,-(sp)
        ; VPv47 may own an independent live MKV audio reader as well.
        tst.l   vpv43_streaming_audio
        beq.s   vpv19_free_no_stream
        jsr     vpv43_audio_stream_cleanup
vpv19_free_no_stream:
        move.l  v19_aac_buf_ptr,d0
        beq.s   vpv19_free_aac_done
        move.l  d0,a1
        move.l  #VPV19_AAC_BUF_SIZE,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   v19_aac_buf_ptr
        clr.l   v19_aac_buf_len
        clr.l   v19_aac_buf_cur
vpv19_free_aac_done:
        movem.l (sp)+,d0-d2/a1/a6
        rts

; Open MintAMP's AAC decoder on the real ADTS buffer generated from the MKV.
vpv19_open_module:
        movem.l d2-d7/a2-a6,-(sp)
        move.l  v19_aac_buf_ptr,d0
        move.l  d0,vpv18_stream_cur
        lea     vpv18_stream_info,a0
        moveq   #2,d0
vpv19_open_clear:
        clr.l   (a0)+
        dbra    d0,vpv19_open_clear
        move.l  vpv18_ops,a0
        move.l  DECOPS_OPEN(a0),a0
        pea     vpv18_stream_info
        clr.l   -(sp)
        pea     vpv19_seek_cb
        pea     vpv19_read_cb
        jsr     (a0)
        lea     16(sp),sp
        move.l  d0,vpv18_dec_handle
        beq.s   vpv19_open_fail
        lea     msg_v19_open_ok,a1
        move.l  #msg_v19_open_ok_end-msg_v19_open_ok,d3
        jsr     print_force
        moveq   #0,d0
        bra.s   vpv19_open_done
vpv19_open_fail:
        lea     msg_v19_open_fail,a1
        move.l  #msg_v19_open_fail_end-msg_v19_open_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv19_open_done:
        movem.l (sp)+,d2-d7/a2-a6
        rts


; ====================================================================
; VPv47 - rolling AAC/ADTS source reader + container PTS capture
; ====================================================================
; This reader is deliberately independent from V10P's video reader.  It opens
; the same MKV a second time, owns a separate 64-KiB source window, and keeps
; only a 128-KiB rolling ADTS window for Helix.  Movie duration therefore no
; longer determines audio memory use.

; Close the independent audio file and reset parser state, but keep allocations.
vpv43_audio_reader_close:
        movem.l d0-d2/a0-a1/a6,-(sp)
        move.l  vpv43_a_file_handle,d0
        beq.s   vpv43_arc_no_file
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   vpv43_a_file_handle
vpv43_arc_no_file:
        clr.l   vpv43_a_io_len
        clr.l   vpv43_a_io_pos
        clr.l   vpv43_a_abs_pos
        clr.l   vpv43_a_reader_eof
        clr.l   vpv43_a_reader_error
        clr.l   vpv43_a_segment_end
        clr.l   vpv43_a_cluster_active
        clr.l   vpv43_a_cluster_end
        clr.l   vpv43_a_blockgroup_end
        clr.l   vpv43_a_cluster_timecode
        clr.l   vpv43_a_payload_len
        clr.l   vpv43_a_current_pts_ticks
        clr.l   vpv181_lace_total
        clr.l   vpv181_lace_index
        clr.l   vpv181_lace_base_pts
        movem.l (sp)+,d0-d2/a0-a1/a6
        rts

; Reopen the same MKV from byte zero for the independent audio walker.
vpv43_audio_reader_reopen:
        movem.l d1-d3/a0/a6,-(sp)
        jsr     vpv43_audio_reader_close
        move.l  a5,a6
        lea     t23_file_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.s   vpv43_arr_fail
        move.l  d0,vpv43_a_file_handle
vpv43_arr_ready:
        moveq   #0,d0
        bra.s   vpv43_arr_done
vpv43_arr_fail_close:
        move.l  vpv43_a_file_handle,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   vpv43_a_file_handle
vpv43_arr_fail:
        moveq   #1,d0
vpv43_arr_done:
        movem.l (sp)+,d1-d3/a0/a6
        rts

; Refill independent 64-KiB source window. D0=0 data, 2 EOF, 1 error.
vpv43_a_refill:
        movem.l d1-d3/a0/a6,-(sp)
        move.l  vpv43_a_file_handle,d1
        beq.s   vpv43_a_refill_fail
        move.l  vpv43_a_io_ptr,d2
        beq.s   vpv43_a_refill_fail
        move.l  #VPV43_AUDIO_IO_SIZE,d3
        move.l  a5,a6
        jsr     Read(a6)
        tst.l   d0
        bmi.s   vpv43_a_refill_fail
        beq.s   vpv43_a_refill_eof
        move.l  d0,vpv43_a_io_len
        clr.l   vpv43_a_io_pos
        moveq   #0,d0
        bra.s   vpv43_a_refill_done
vpv43_a_refill_eof:
        move.l  #1,vpv43_a_reader_eof
        clr.l   vpv43_a_io_len
        clr.l   vpv43_a_io_pos
        moveq   #2,d0
        bra.s   vpv43_a_refill_done
vpv43_a_refill_fail:
        move.l  #1,vpv43_a_reader_error
        moveq   #1,d0
vpv43_a_refill_done:
        movem.l (sp)+,d1-d3/a0/a6
        rts

; D0=status, D1=byte.
vpv43_a_get_byte:
        movem.l d2-d4/a0,-(sp)
vpv43_a_get_retry:
        move.l  vpv43_a_io_pos,d2
        move.l  vpv43_a_io_len,d3
        cmp.l   d3,d2
        bcs.s   vpv43_a_get_have
        jsr     vpv43_a_refill
        tst.l   d0
        bne.s   vpv43_a_get_done
        bra.s   vpv43_a_get_retry
vpv43_a_get_have:
        move.l  vpv43_a_io_ptr,a0
        adda.l  d2,a0
        moveq   #0,d1
        move.b  (a0),d1
        addq.l  #1,d2
        move.l  d2,vpv43_a_io_pos
        addq.l  #1,vpv43_a_abs_pos
        moveq   #0,d0
vpv43_a_get_done:
        movem.l (sp)+,d2-d4/a0
        rts

; Skip D0 bytes. D0=0 success, 1 failure.
vpv43_a_skip_bytes:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  d0,d7
vpv43_a_skip_loop:
        tst.l   d7
        beq.s   vpv43_a_skip_ok
        move.l  vpv43_a_io_len,d2
        move.l  vpv43_a_io_pos,d1
        sub.l   d1,d2
        bne.s   vpv43_a_skip_have
        jsr     vpv43_a_refill
        tst.l   d0
        bne.s   vpv43_a_skip_fail
        bra.s   vpv43_a_skip_loop
vpv43_a_skip_have:
        move.l  d7,d3
        cmp.l   d2,d3
        bls.s   vpv43_a_skip_n_ready
        move.l  d2,d3
vpv43_a_skip_n_ready:
        add.l   d3,vpv43_a_io_pos
        add.l   d3,vpv43_a_abs_pos
        sub.l   d3,d7
        bra.s   vpv43_a_skip_loop
vpv43_a_skip_ok:
        moveq   #0,d0
        bra.s   vpv43_a_skip_done
vpv43_a_skip_fail:
        moveq   #1,d0
vpv43_a_skip_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; EBML ID: D0=status, D1=ID, D2=encoded bytes.
vpv43_a_read_id:
        movem.l d3-d7/a0,-(sp)
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv43_a_read_id_done
        move.l  d1,d3
        moveq   #1,d4
        btst    #7,d3
        bne.s   vpv43_a_id_len_ready
        moveq   #2,d4
        btst    #6,d3
        bne.s   vpv43_a_id_len_ready
        moveq   #3,d4
        btst    #5,d3
        bne.s   vpv43_a_id_len_ready
        moveq   #4,d4
        btst    #4,d3
        bne.s   vpv43_a_id_len_ready
        moveq   #1,d0
        bra.s   vpv43_a_read_id_done
vpv43_a_id_len_ready:
        move.l  d3,d5
        move.l  d4,d6
        subq.l  #1,d6
        beq.s   vpv43_a_id_success
vpv43_a_id_more:
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.s   vpv43_a_read_id_fail
        lsl.l   #8,d5
        or.l    d1,d5
        subq.l  #1,d6
        bne.s   vpv43_a_id_more
vpv43_a_id_success:
        move.l  d5,d1
        move.l  d4,d2
        moveq   #0,d0
        bra.s   vpv43_a_read_id_done
vpv43_a_read_id_fail:
        moveq   #1,d0
vpv43_a_read_id_done:
        movem.l (sp)+,d3-d7/a0
        rts

; EBML size/VINT. D0=status, D1=value (FFFFFFFF unknown), D2=len.
vpv43_a_read_size:
        movem.l d3-d7/a0-a3,-(sp)
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv43_a_size_done
        lea     vpv43_a_vint_tmp,a2
        move.b  d1,(a2)
        move.l  d1,d3
        move.l  #$00000080,d4
        moveq   #1,d5
vpv43_a_size_find_marker:
        move.l  d3,d6
        and.l   d4,d6
        bne.s   vpv43_a_size_marker_found
        lsr.l   #1,d4
        addq.l  #1,d5
        cmpi.l  #9,d5
        bcs.s   vpv43_a_size_find_marker
        moveq   #1,d0
        bra.w   vpv43_a_size_done
vpv43_a_size_marker_found:
        move.l  d5,d7
        subq.l  #1,d7
        beq.s   vpv43_a_size_all_read
        lea     1(a2),a3
vpv43_a_size_read_more:
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv43_a_size_fail
        move.b  d1,(a3)+
        subq.l  #1,d7
        bne.s   vpv43_a_size_read_more
vpv43_a_size_all_read:
        move.l  d4,d6
        subq.l  #1,d6
        moveq   #0,d3
        move.b  (a2),d3
        and.l   d6,d3
        cmp.l   d6,d3
        bne.s   vpv43_a_size_not_unknown
        move.l  d5,d7
        subq.l  #1,d7
        beq.s   vpv43_a_size_unknown
        lea     1(a2),a3
vpv43_a_size_unknown_loop:
        cmpi.b  #$FF,(a3)+
        bne.s   vpv43_a_size_not_unknown
        subq.l  #1,d7
        bne.s   vpv43_a_size_unknown_loop
vpv43_a_size_unknown:
        move.l  #$FFFFFFFF,d1
        move.l  d5,d2
        moveq   #0,d0
        bra.w   vpv43_a_size_done
vpv43_a_size_not_unknown:
        cmpi.l  #4,d5
        bls.s   vpv43_a_size_build_short
        tst.l   d3
        bne.w   vpv43_a_size_fail
        move.l  d5,d7
        sub.l   #4,d7
        subq.l  #1,d7
        ble.s   vpv43_a_size_build_last4
        lea     1(a2),a3
vpv43_a_size_high_zero_loop:
        tst.b   (a3)+
        bne.w   vpv43_a_size_fail
        subq.l  #1,d7
        bne.s   vpv43_a_size_high_zero_loop
vpv43_a_size_build_last4:
        move.l  d5,d7
        sub.l   #4,d7
        lea     (a2,d7.l),a3
        moveq   #0,d6
        moveq   #3,d7
vpv43_a_size_last4_loop:
        lsl.l   #8,d6
        moveq   #0,d3
        move.b  (a3)+,d3
        or.l    d3,d6
        dbra    d7,vpv43_a_size_last4_loop
        move.l  d6,d1
        move.l  d5,d2
        moveq   #0,d0
        bra.s   vpv43_a_size_done
vpv43_a_size_build_short:
        move.l  d3,d6
        move.l  d5,d7
        subq.l  #1,d7
        beq.s   vpv43_a_size_short_done
        lea     1(a2),a3
vpv43_a_size_short_loop:
        lsl.l   #8,d6
        moveq   #0,d3
        move.b  (a3)+,d3
        or.l    d3,d6
        subq.l  #1,d7
        bne.s   vpv43_a_size_short_loop
vpv43_a_size_short_done:
        move.l  d6,d1
        move.l  d5,d2
        moveq   #0,d0
        bra.s   vpv43_a_size_done
vpv43_a_size_fail:
        moveq   #1,d0
vpv43_a_size_done:
        movem.l (sp)+,d3-d7/a0-a3
        rts

; Unsigned EBML integer payload, <=32 significant bits.
vpv43_a_read_uint:
        movem.l d2-d7,-(sp)
        move.l  d0,d7
        moveq   #0,d6
        tst.l   d7
        beq.s   vpv43_a_uint_ok
        cmpi.l  #8,d7
        bhi.s   vpv43_a_uint_fail
        move.l  d7,d5
        sub.l   #4,d5
        ble.s   vpv43_a_uint_low_part
vpv43_a_uint_high_loop:
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.s   vpv43_a_uint_fail
        tst.l   d1
        bne.s   vpv43_a_uint_fail
        subq.l  #1,d5
        bne.s   vpv43_a_uint_high_loop
vpv43_a_uint_low_part:
        move.l  d7,d5
        cmpi.l  #4,d5
        bls.s   vpv43_a_uint_low_count_ok
        moveq   #4,d5
vpv43_a_uint_low_count_ok:
        tst.l   d5
        beq.s   vpv43_a_uint_ok
vpv43_a_uint_low_loop:
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.s   vpv43_a_uint_fail
        lsl.l   #8,d6
        or.l    d1,d6
        subq.l  #1,d5
        bne.s   vpv43_a_uint_low_loop
vpv43_a_uint_ok:
        move.l  d6,d1
        moveq   #0,d0
        bra.s   vpv43_a_uint_done
vpv43_a_uint_fail:
        moveq   #1,d0
vpv43_a_uint_done:
        movem.l (sp)+,d2-d7
        rts

; mkvr7: read one Matroska lace VINT, marker bit stripped.
; OUT D0=0 success / 1 fail, D1=value, D2=encoded length (1..4).
vpv181_lace_read_vint:
        movem.l d3-d7,-(sp)
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv181_lrv_fail
        move.l  d1,d3
        moveq   #1,d2
        move.l  #$00000080,d4
vpv181_lrv_find:
        move.l  d3,d5
        and.l   d4,d5
        bne.s   vpv181_lrv_marker
        lsr.l   #1,d4
        addq.l  #1,d2
        cmpi.l  #5,d2
        bcs.s   vpv181_lrv_find
        bra.w   vpv181_lrv_fail
vpv181_lrv_marker:
        move.l  d4,d5
        subq.l  #1,d5
        and.l   d5,d3
        move.l  d2,d6
        subq.l  #1,d6
        beq.s   vpv181_lrv_ok
vpv181_lrv_more:
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.s   vpv181_lrv_fail
        lsl.l   #8,d3
        or.l    d1,d3
        subq.l  #1,d6
        bne.s   vpv181_lrv_more
vpv181_lrv_ok:
        move.l  d3,d1
        moveq   #0,d0
        bra.s   vpv181_lrv_done
vpv181_lrv_fail:
        clr.l   d1
        clr.l   d2
        moveq   #1,d0
vpv181_lrv_done:
        movem.l (sp)+,d3-d7
        rts

; Parse selected AAC lacing header.
; IN : D0=bytes after Block flags, D1=(flags & $06)
; OUT: D0=0 success, stream positioned at first AAC payload.
;      vpv43_a_payload_len = first AAC frame size.
vpv181_parse_audio_lacing:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,d7                  ; bytes still inside Block
        move.l  d1,d6                  ; lacing type bits
        tst.l   d7
        beq.w   vpv181_lace_fail

        ; one byte = frame_count - 1
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv181_lace_fail
        subq.l  #1,d7
        move.l  d1,d5
        addq.l  #1,d5                  ; 1..256
        beq.w   vpv181_lace_fail
        cmpi.l  #256,d5
        bhi.w   vpv181_lace_fail

        lea     vpv181_lace_sizes,a2
        clr.l   d4                     ; sum of explicit sizes

        cmpi.l  #$00000002,d6
        beq.w   vpv181_lace_xiph
        cmpi.l  #$00000004,d6
        beq.w   vpv181_lace_fixed
        cmpi.l  #$00000006,d6
        beq.w   vpv181_lace_ebml
        bra.w   vpv181_lace_fail

; Xiph lacing: N-1 sizes, each encoded as 255-byte runs + final remainder.
vpv181_lace_xiph:
        addq.l  #1,vpv181_lace_xiph_blocks
        move.l  d5,d3
        subq.l  #1,d3
        beq.w   vpv181_lace_store_last
vpv181_lace_xiph_frame:
        clr.l   d2
vpv181_lace_xiph_size:
        tst.l   d7
        beq.w   vpv181_lace_fail
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv181_lace_fail
        subq.l  #1,d7
        add.l   d1,d2
        bcs.w   vpv181_lace_fail
        cmpi.l  #255,d1
        beq.s   vpv181_lace_xiph_size
        tst.l   d2
        beq.w   vpv181_lace_fail
        move.l  d2,(a2)+
        add.l   d2,d4
        bcs.w   vpv181_lace_fail
        subq.l  #1,d3
        bne.s   vpv181_lace_xiph_frame
        bra.w   vpv181_lace_store_last

; Fixed lacing: remaining data divides evenly by frame count.
vpv181_lace_fixed:
        addq.l  #1,vpv181_lace_fixed_blocks
        move.l  d7,d0
        move.l  d5,d1
        jsr     v10_udiv32
        tst.l   d1                     ; remainder must be zero
        bne.w   vpv181_lace_fail
        tst.l   d0
        beq.w   vpv181_lace_fail
        move.l  d5,d3
vpv181_lace_fixed_loop:
        move.l  d0,(a2)+
        subq.l  #1,d3
        bne.s   vpv181_lace_fixed_loop
        bra.w   vpv181_lace_ready

; EBML lacing:
;   size0 = unsigned VINT
;   size1..size(N-2) = previous size + signed VINT delta
;   last = bytes remaining after header - sum(previous sizes)
vpv181_lace_ebml:
        addq.l  #1,vpv181_lace_ebml_blocks
        cmpi.l  #1,d5
        beq.w   vpv181_lace_store_last

        jsr     vpv181_lace_read_vint
        tst.l   d0
        bne.w   vpv181_lace_fail
        cmp.l   d2,d7
        bcs.w   vpv181_lace_fail
        sub.l   d2,d7
        move.l  d1,d6                  ; previous frame size
        tst.l   d6
        beq.w   vpv181_lace_fail
        move.l  d6,(a2)+
        move.l  d6,d4

        move.l  d5,d3
        subq.l  #2,d3
        beq.w   vpv181_lace_store_last

vpv181_lace_ebml_delta:
        jsr     vpv181_lace_read_vint
        tst.l   d0
        bne.w   vpv181_lace_fail
        cmp.l   d2,d7
        bcs.w   vpv181_lace_fail
        sub.l   d2,d7

        ; signed EBML-lace bias = 2^(7*n-1)-1
        cmpi.l  #1,d2
        bne.s   vpv181_lace_bias2
        subi.l  #63,d1
        bra.s   vpv181_lace_delta_apply
vpv181_lace_bias2:
        cmpi.l  #2,d2
        bne.s   vpv181_lace_bias3
        subi.l  #8191,d1
        bra.s   vpv181_lace_delta_apply
vpv181_lace_bias3:
        cmpi.l  #3,d2
        bne.s   vpv181_lace_bias4
        subi.l  #1048575,d1
        bra.s   vpv181_lace_delta_apply
vpv181_lace_bias4:
        cmpi.l  #4,d2
        bne.w   vpv181_lace_fail
        subi.l  #134217727,d1

vpv181_lace_delta_apply:
        move.l  d6,d0
        add.l   d1,d0
        tst.l   d0
        ble.w   vpv181_lace_fail
        move.l  d0,d6
        move.l  d6,(a2)+
        add.l   d6,d4
        bcs.w   vpv181_lace_fail
        subq.l  #1,d3
        bne.w   vpv181_lace_ebml_delta

vpv181_lace_store_last:
        cmp.l   d4,d7
        bcs.w   vpv181_lace_fail
        sub.l   d4,d7
        tst.l   d7
        beq.w   vpv181_lace_fail
        move.l  d7,(a2)+

vpv181_lace_ready:
        move.l  d5,vpv181_lace_total
        clr.l   vpv181_lace_index
        addq.l  #1,vpv181_lace_blocks
        add.l   d5,vpv181_lace_frames

        lea     vpv181_lace_sizes,a0
        move.l  (a0),d0
        tst.l   d0
        beq.s   vpv181_lace_fail
        move.l  d0,vpv43_a_payload_len
        moveq   #0,d0
        bra.s   vpv181_lace_done

vpv181_lace_fail:
        clr.l   vpv181_lace_total
        clr.l   vpv181_lace_index
        addq.l  #1,vpv181_lace_errors
        moveq   #1,d0
vpv181_lace_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Parse one Block/SimpleBlock.  Selected AAC payload is left unread.
vpv43_a_begin_audio_block:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  d0,d7
        cmpi.l  #4,d7
        bcs.w   vpv43_a_block_fail
        jsr     vpv43_a_read_size
        tst.l   d0
        bne.w   vpv43_a_block_fail
        move.l  d1,d6
        move.l  d2,d5
        move.l  d5,d4
        addq.l  #3,d4
        cmp.l   d7,d4
        bhi.w   vpv43_a_block_fail

        ; signed 16-bit block-relative timecode
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv43_a_block_fail
        move.l  d1,d3
        lsl.w   #8,d3
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv43_a_block_fail
        or.w    d1,d3
        ext.l   d3
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv43_a_block_fail
        move.l  d1,d2
        sub.l   d4,d7

        cmp.l   v19_audio_track_num,d6
        beq.s   vpv43_a_block_selected
        move.l  d7,d0
        jsr     vpv43_a_skip_bytes
        tst.l   d0
        bne.s   vpv43_a_block_fail
        moveq   #3,d0
        bra.s   vpv43_a_block_done
vpv43_a_block_selected:
        ; Save Block PTS before parsing lacing. For the rolling AAC path only
        ; the first source PTS seeds the exact decoded-sample timeline; later
        ; AAC time advances from decoded sample counts, just like VPv180.
        move.l  vpv43_a_cluster_timecode,d1
        add.l   d3,d1
        move.l  d1,vpv43_a_current_pts_ticks
        move.l  d1,vpv181_lace_base_pts

        move.l  d2,d1
        andi.l  #$00000006,d1
        beq.s   vpv43_a_block_unlaced

        ; VPv181: Xiph, fixed-size and EBML lacing are supported here.
        move.l  #1,v19_audio_lacing_seen
        move.l  d7,d0
        jsr     vpv181_parse_audio_lacing
        tst.l   d0
        bne.s   vpv43_a_block_fail
        moveq   #0,d0
        bra.s   vpv43_a_block_done

vpv43_a_block_unlaced:
        tst.l   d7
        beq.s   vpv43_a_block_fail
        move.l  d7,vpv43_a_payload_len
        moveq   #0,d0
        bra.s   vpv43_a_block_done
vpv43_a_block_fail:
        moveq   #1,d0
vpv43_a_block_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Find next selected AAC block in the independent Matroska stream.
; D0=0 found, 2 EOF, 1 malformed/unsupported.
vpv43_a_find_audio_block:
vpv43_a_find_mkv:
        movem.l d1-d7/a0-a3,-(sp)

        ; If the previous Matroska block was laced, the stream is already
        ; positioned at the next concatenated AAC access unit. Return its
        ; stored size directly instead of reading a new EBML element header.
        move.l  vpv181_lace_total,d1
        beq.s   vpv43_a_find_loop
        move.l  vpv181_lace_index,d2
        cmp.l   d1,d2
        bcc.s   vpv181_lace_pending_clear
        move.l  d2,d3
        lsl.l   #2,d3
        lea     vpv181_lace_sizes,a0
        move.l  0(a0,d3.l),d0
        tst.l   d0
        beq.w   vpv43_a_find_fail
        move.l  d0,vpv43_a_payload_len
        move.l  vpv181_lace_base_pts,vpv43_a_current_pts_ticks
        moveq   #0,d0
        bra.w   vpv43_a_find_done
vpv181_lace_pending_clear:
        clr.l   vpv181_lace_total
        clr.l   vpv181_lace_index

vpv43_a_find_loop:
        move.l  vpv43_a_blockgroup_end,d1
        beq.s   vpv43_a_find_check_cluster
        cmpi.l  #$FFFFFFFF,d1
        beq.s   vpv43_a_find_check_cluster
        move.l  vpv43_a_abs_pos,d2
        cmp.l   d1,d2
        bcs.s   vpv43_a_find_check_cluster
        clr.l   vpv43_a_blockgroup_end
vpv43_a_find_check_cluster:
        move.l  vpv43_a_cluster_end,d1
        beq.s   vpv43_a_find_header
        cmpi.l  #$FFFFFFFF,d1
        beq.s   vpv43_a_find_header
        move.l  vpv43_a_abs_pos,d2
        cmp.l   d1,d2
        bcs.s   vpv43_a_find_header
        clr.l   vpv43_a_cluster_active
        clr.l   vpv43_a_cluster_end
        clr.l   vpv43_a_blockgroup_end
vpv43_a_find_header:
        jsr     vpv43_a_read_id
        cmpi.l  #2,d0
        beq.w   vpv43_a_find_eof
        tst.l   d0
        bne.w   vpv43_a_find_fail
        move.l  d1,d5
        jsr     vpv43_a_read_size
        tst.l   d0
        bne.w   vpv43_a_find_fail
        move.l  d1,d6
        move.l  #$FFFFFFFF,d7
        cmpi.l  #$FFFFFFFF,d6
        beq.s   vpv43_a_find_end_ready
        move.l  vpv43_a_abs_pos,d7
        add.l   d6,d7
        bcs.w   vpv43_a_find_fail
vpv43_a_find_end_ready:
        cmpi.l  #$1A45DFA3,d5
        beq.w   vpv43_a_find_skip
        cmpi.l  #$18538067,d5
        beq.w   vpv43_a_find_segment
        cmpi.l  #$1F43B675,d5
        beq.w   vpv43_a_find_cluster
        cmpi.l  #$114D9B74,d5
        beq.s   vpv43_a_find_segment_meta
        cmpi.l  #$1549A966,d5
        beq.s   vpv43_a_find_segment_meta
        cmpi.l  #$1654AE6B,d5
        beq.s   vpv43_a_find_segment_meta
        cmpi.l  #$1C53BB6B,d5
        beq.s   vpv43_a_find_segment_meta
        cmpi.l  #$1254C367,d5
        beq.s   vpv43_a_find_segment_meta
        cmpi.l  #$1941A469,d5
        beq.s   vpv43_a_find_segment_meta
        cmpi.l  #$1043A770,d5
        beq.s   vpv43_a_find_segment_meta
        bra.s   vpv43_a_find_cluster_children
vpv43_a_find_segment_meta:
        move.l  vpv43_a_cluster_end,d1
        cmpi.l  #$FFFFFFFF,d1
        bne.w   vpv43_a_find_skip
        clr.l   vpv43_a_cluster_active
        clr.l   vpv43_a_cluster_end
        clr.l   vpv43_a_blockgroup_end
        bra.w   vpv43_a_find_skip
vpv43_a_find_cluster_children:
        tst.l   vpv43_a_cluster_active
        beq.w   vpv43_a_find_skip
        cmpi.l  #$000000E7,d5
        beq.w   vpv43_a_find_timecode
        cmpi.l  #$000000A0,d5
        beq.w   vpv43_a_find_blockgroup
        cmpi.l  #$000000A3,d5
        beq.w   vpv43_a_find_block
        cmpi.l  #$000000A1,d5
        bne.w   vpv43_a_find_skip
        tst.l   vpv43_a_blockgroup_end
        beq.w   vpv43_a_find_skip
        bra.w   vpv43_a_find_block
vpv43_a_find_segment:
        move.l  d7,vpv43_a_segment_end
        bra.w   vpv43_a_find_loop
vpv43_a_find_cluster:
        move.l  #1,vpv43_a_cluster_active
        move.l  d7,vpv43_a_cluster_end
        clr.l   vpv43_a_blockgroup_end
        clr.l   vpv43_a_cluster_timecode
        bra.w   vpv43_a_find_loop
vpv43_a_find_blockgroup:
        move.l  d7,vpv43_a_blockgroup_end
        bra.w   vpv43_a_find_loop
vpv43_a_find_timecode:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   vpv43_a_find_fail
        move.l  d6,d0
        jsr     vpv43_a_read_uint
        tst.l   d0
        bne.w   vpv43_a_find_fail
        move.l  d1,vpv43_a_cluster_timecode
        bra.w   vpv43_a_find_loop
vpv43_a_find_block:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   vpv43_a_find_fail
        move.l  d6,d0
        jsr     vpv43_a_begin_audio_block
        tst.l   d0
        beq.s   vpv43_a_find_found
        cmpi.l  #3,d0
        beq.w   vpv43_a_find_loop
        bra.w   vpv43_a_find_fail
vpv43_a_find_skip:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   vpv43_a_find_fail
        move.l  d6,d0
        jsr     vpv43_a_skip_bytes
        tst.l   d0
        bne.w   vpv43_a_find_fail
        bra.w   vpv43_a_find_loop
vpv43_a_find_found:
        moveq   #0,d0
        bra.s   vpv43_a_find_done
vpv43_a_find_eof:
        moveq   #2,d0
        bra.s   vpv43_a_find_done
vpv43_a_find_fail:
        moveq   #1,d0
vpv43_a_find_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; mkvr7: skip one already-selected AAC payload without copying it
; into the ADTS buffer. This mirrors the lacing-index ownership update performed
; by vpv43_a_copy_payload, so the next find returns the next lace frame/block.
; D0=0 OK, 1 fail.
vpv005r3_audio_skip_selected:
        movem.l d1-d3,-(sp)
        move.l  vpv43_a_payload_len,d0
        tst.l   d0
        beq.s   vpv005r3_audio_skip_fail
        jsr     vpv43_a_skip_bytes
        tst.l   d0
        bne.s   vpv005r3_audio_skip_fail

        move.l  vpv181_lace_total,d1
        beq.s   vpv005r3_audio_skip_ok
        move.l  vpv181_lace_index,d2
        addq.l  #1,d2
        move.l  d2,vpv181_lace_index
        cmp.l   d1,d2
        bcs.s   vpv005r3_audio_skip_ok
        clr.l   vpv181_lace_total
        clr.l   vpv181_lace_index
vpv005r3_audio_skip_ok:
        moveq   #0,d0
        bra.s   vpv005r3_audio_skip_done
vpv005r3_audio_skip_fail:
        moveq   #1,d0
vpv005r3_audio_skip_done:
        movem.l (sp)+,d1-d3
        rts

; mkvr7: compressed AAC start-time seek for the independent Matroska
; audio reader. T: is in seconds; Matroska timing in this player is the proven
; 1-ms tick domain. Stop on the first selected AAC Block with PTS >= target and
; leave that payload unread for vpv43_fill_adts_buffer.
; D0=0 OK/no T:, 1 malformed/target past usable audio.
vpv005r3_audio_seek_start_time:
        movem.l d1-d7/a0-a2,-(sp)
        clr.l   vpv005r3_audio_seek_pending
        clr.l   vpv005r3_audio_seek_target
        clr.l   vpv005r3_audio_seek_found
        clr.l   vpv005r3_audio_seek_skipped

        tst.l   v40j_start_time_valid
        beq.w   vpv005r3_audio_seek_ok

        ; R5: align audio to the actual video IDR selected by the compressed
        ; pre-scan, not merely to the textual T: value.  This guarantees that
        ; video never starts later than already-queued audio.
        tst.l   v005r5_seek_valid
        beq.s   v005r5_audio_target_from_text
        move.l  v005r5_seek_pts_ticks,d0
        bra.s   v005r5_audio_target_ready

v005r5_audio_target_from_text:
        move.l  v40j_start_time_secs,d0
        tst.l   d0
        beq.w   vpv005r3_audio_seek_ok
        cmpi.l  #65535,d0
        bls.s   vpv005r3_audio_seek_secs_ok
        move.l  #65535,d0
vpv005r3_audio_seek_secs_ok:
        mulu.w  #1000,d0
v005r5_audio_target_ready:
        move.l  d0,vpv005r3_audio_seek_target

vpv005r3_audio_seek_loop:
        jsr     vpv43_a_find_audio_block
        tst.l   d0
        beq.s   vpv005r3_audio_seek_have
        bra.s   vpv005r3_audio_seek_fail

vpv005r3_audio_seek_have:
        move.l  vpv43_a_current_pts_ticks,d1
        cmp.l   vpv005r3_audio_seek_target,d1
        bcc.s   vpv005r3_audio_seek_found_block

        jsr     vpv005r3_audio_skip_selected
        tst.l   d0
        bne.s   vpv005r3_audio_seek_fail
        addq.l  #1,vpv005r3_audio_seek_skipped
        bra.w   vpv005r3_audio_seek_loop

vpv005r3_audio_seek_found_block:
        move.l  d1,vpv005r3_audio_seek_found
        move.l  #1,vpv005r3_audio_seek_pending

        lea     msg_vpv005r3_audio_seek,a1
        move.l  #msg_vpv005r3_audio_seek_end-msg_vpv005r3_audio_seek,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv005r3_audio_seek_target,d0
        jsr     print_hex32
        lea     msg_vpv005r3_audio_seek_found,a1
        move.l  #msg_vpv005r3_audio_seek_found_end-msg_vpv005r3_audio_seek_found,d3
        jsr     print_force
        move.l  vpv005r3_audio_seek_found,d0
        jsr     print_hex32
        lea     msg_vpv005r3_audio_seek_skipped,a1
        move.l  #msg_vpv005r3_audio_seek_skipped_end-msg_vpv005r3_audio_seek_skipped,d3
        jsr     print_force
        move.l  vpv005r3_audio_seek_skipped,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print

vpv005r3_audio_seek_ok:
        moveq   #0,d0
        bra.s   vpv005r3_audio_seek_done
vpv005r3_audio_seek_fail:
        moveq   #1,d0
vpv005r3_audio_seek_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Copy current selected AAC payload into v19 rolling ADTS buffer.
vpv43_a_copy_payload:
vpv43_a_copy_mkv:
        movem.l d1-d7/a0,-(sp)
        move.l  d0,d7
        move.l  v19_aac_buf_cur,a0
vpv43_a_copy_loop:
        tst.l   d7
        beq.s   vpv43_a_copy_ok
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.s   vpv43_a_copy_fail
        move.b  d1,(a0)+
        addq.l  #1,v19_aac_buf_len
        subq.l  #1,d7
        bra.s   vpv43_a_copy_loop
vpv43_a_copy_ok:
        move.l  a0,v19_aac_buf_cur

        ; One complete laced AAC access unit has now been consumed.
        move.l  vpv181_lace_total,d1
        beq.s   vpv181_lace_copy_done
        move.l  vpv181_lace_index,d2
        addq.l  #1,d2
        move.l  d2,vpv181_lace_index
        cmp.l   d1,d2
        bcs.s   vpv181_lace_copy_done
        clr.l   vpv181_lace_total
        clr.l   vpv181_lace_index
vpv181_lace_copy_done:
        moveq   #0,d0
        bra.s   vpv43_a_copy_done
vpv43_a_copy_fail:
        moveq   #1,d0
vpv43_a_copy_done:
        movem.l (sp)+,d1-d7/a0
        rts

; Fill one rolling ADTS window. D0=0 bytes available, 2 true AAC EOF, 1 fail.
vpv43_fill_adts_buffer:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   v19_aac_buf_len
        move.l  v19_aac_buf_ptr,d0
        beq.w   vpv43_fill_fail
        move.l  d0,v19_aac_buf_cur
        move.l  d0,vpv18_stream_cur
        clr.l   v19_aac_frame_count
        moveq   #0,d7
vpv43_fill_loop:
        ; Leave room for the largest legal ADTS frame before parsing another
        ; block so a selected payload is never stranded half-consumed.
        move.l  v19_aac_buf_len,d0
        cmpi.l  #VPV19_AAC_BUF_SIZE-$00002010,d0
        bcc.w   vpv43_fill_have
        cmpi.l  #VPV43_ADTS_FILL_FRAMES,d7
        bcc.w   vpv43_fill_have

        ; mkvr7: the T: compressed-audio seek stops with the first
        ; wanted AAC payload already selected and intentionally unread.
        tst.l   vpv005r3_audio_seek_pending
        beq.s   vpv005r3_fill_find_normal
        clr.l   vpv005r3_audio_seek_pending
        moveq   #0,d0
        bra.s   vpv43_fill_found
vpv005r3_fill_find_normal:
        jsr     vpv43_a_find_audio_block
        tst.l   d0
        beq.s   vpv43_fill_found
        cmpi.l  #2,d0
        beq.s   vpv43_fill_eof
        bra.w   vpv43_fill_fail
vpv43_fill_found:
        tst.l   vpv43_first_audio_pts_found
        bne.s   vpv43_fill_pts_known
        move.l  vpv43_a_current_pts_ticks,d0
        move.l  d0,vpv43_first_audio_pts_ticks
        move.l  #1,vpv43_first_audio_pts_found
vpv43_fill_pts_known:
        move.l  vpv43_a_payload_len,d0
        addq.l  #7,d0
        move.l  v19_aac_buf_len,d1
        add.l   d0,d1
        cmpi.l  #VPV19_AAC_BUF_SIZE,d1
        bhi.w   vpv43_fill_fail
        move.l  vpv43_a_payload_len,d0
        jsr     vpv19_append_adts_header
        tst.l   d0
        bne.w   vpv43_fill_fail
        move.l  vpv43_a_payload_len,d0
        jsr     vpv43_a_copy_payload
        tst.l   d0
        bne.w   vpv43_fill_fail
        addq.l  #1,d7
        addq.l  #1,v19_aac_frame_count
        addq.l  #1,vpv43_a_total_frames
        bra.w   vpv43_fill_loop
vpv43_fill_eof:
        move.l  #1,vpv43_a_source_eof
        tst.l   v19_aac_buf_len
        bne.s   vpv43_fill_have
        moveq   #2,d0
        bra.s   vpv43_fill_done
vpv43_fill_have:
        tst.l   v19_aac_buf_len
        beq.s   vpv43_fill_fail
        move.l  v19_aac_buf_ptr,vpv18_stream_cur
        moveq   #0,d0
        bra.s   vpv43_fill_done
vpv43_fill_fail:
        move.l  #1,vpv43_a_reader_error
        moveq   #1,d0
vpv43_fill_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Allocate bounded streaming state, open independent reader, fill first ADTS window.
vpv43_audio_stream_prepare:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv43_streaming_audio
        clr.l   vpv43_a_source_eof
        clr.l   vpv43_a_total_frames
        clr.l   vpv43_first_audio_pts_found
        clr.l   vpv43_first_audio_pts_ticks
        clr.l   vpv170_first_audio_pts_hi
        clr.l   vpv43_audio_next_pts_ticks
        clr.l   vpv170_audio_next_pts_hi
        clr.l   vpv43_audio_pts_remainder
        clr.l   vpv43_last_sent_samples
        clr.l   vpv43_video_frame_ticks
        clr.l   vpv43_display_pts_ticks
        clr.l   vpv43_last_output_frames
        clr.l   vpv43_sync_waits
        clr.l   vpv43_sync_started
        clr.l   vpv43_pts_mode
        clr.l   vpv45_topup_count
        clr.l   vpv45_prefetch_ready
        clr.l   vpv45_prefetch_bytes
        clr.l   vpv45_prefetch_samples
        clr.l   vpv45_prefetch_count
        clr.l   vpv45_prefetch_miss_count
        clr.l   vpv45_prefetch_first_logged
        clr.l   v19_audio_lacing_seen
        clr.l   vpv181_lace_total
        clr.l   vpv181_lace_index
        clr.l   vpv181_lace_base_pts
        clr.l   vpv181_lace_blocks
        clr.l   vpv181_lace_frames
        clr.l   vpv181_lace_xiph_blocks
        clr.l   vpv181_lace_fixed_blocks
        clr.l   vpv181_lace_ebml_blocks
        clr.l   vpv181_lace_errors
        clr.l   vpv005r3_audio_seek_pending
        clr.l   vpv005r3_audio_seek_target
        clr.l   vpv005r3_audio_seek_found
        clr.l   vpv005r3_audio_seek_skipped

        move.l  a4,a6
        move.l  #VPV19_AAC_BUF_SIZE,d0
        move.l  #MEMF_FAST,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   vpv43_prepare_fail
        move.l  d0,v19_aac_buf_ptr
        move.l  d0,v19_aac_buf_cur

        move.l  #VPV43_AUDIO_IO_SIZE,d0
        move.l  #MEMF_FAST,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   vpv43_prepare_fail_cleanup
        move.l  d0,vpv43_a_io_ptr

        jsr     vpv43_audio_reader_reopen
        tst.l   d0
        bne.w   vpv43_prepare_fail_cleanup

        ; mkvr7: for T: starts, advance the independent AAC Matroska
        ; reader in COMPRESSED form to the first audio Block at/after target.
        ; The selected payload is left unread and consumed by the normal ADTS
        ; filler below. This avoids playing audio from 0:00 while video performs
        ; its current hidden fast-forward.
        jsr     vpv005r3_audio_seek_start_time
        tst.l   d0
        bne.w   vpv43_prepare_fail_cleanup

        move.l  #1,vpv43_streaming_audio
        jsr     vpv43_fill_adts_buffer
        tst.l   d0
        bne.w   vpv43_prepare_fail_cleanup
        tst.l   vpv43_first_audio_pts_found
        beq.w   vpv43_prepare_fail_cleanup
        move.l  vpv43_first_audio_pts_ticks,d0
        move.l  d0,vpv43_audio_next_pts_ticks

vpv103_prepare_mkv_pts:

        ; Build the video display timeline from container metadata.  The current
        ; audio duration accumulator is exact for the Matroska default 1-ms tick
        ; scale; non-default scales still stream but fall back to ungated audio.
        move.l  v10_timecode_scale,d0
        cmpi.l  #VPV43_TIMECODE_SCALE_MS,d0
        bne.s   vpv43_prepare_no_pts_mode
        tst.l   v10_first_pts_found
        beq.s   vpv43_prepare_no_pts_mode
        move.l  v10_video_default_dur,d0
        beq.s   vpv43_prepare_no_pts_mode
        move.l  v10_timecode_scale,d1
        jsr     v10_udiv32
        tst.l   d0
        beq.s   vpv43_prepare_no_pts_mode
        move.l  d0,vpv43_video_frame_ticks
        move.l  #1,vpv43_pts_mode
vpv43_prepare_no_pts_mode:
        moveq   #0,d0
        bra.s   vpv43_prepare_done
vpv43_prepare_fail_cleanup:
        jsr     vpv43_audio_stream_cleanup
vpv43_prepare_fail:
        moveq   #1,d0
vpv43_prepare_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Full independent streaming cleanup. Safe to call repeatedly.
vpv43_audio_stream_cleanup:
        movem.l d0-d2/a0-a1/a6,-(sp)
        jsr     vpv43_audio_reader_close
        move.l  vpv43_a_io_ptr,d0
        beq.s   vpv43_cleanup_no_io
        move.l  d0,a1
        move.l  #VPV43_AUDIO_IO_SIZE,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   vpv43_a_io_ptr
vpv43_cleanup_no_io:
        clr.l   vpv43_streaming_audio
        movem.l (sp)+,d0-d2/a0-a1/a6
        rts


; VPv47: top up the rolling ADTS source OUTSIDE the Helix callback.
; VPv43 performed DOS Read()/Matroska parsing recursively from vpv19_read_cb
; while DECOPS_DECODE was active.  Real hardware crashed in that new path.
; The callback is memory-only again; unread ADTS is compacted here and more
; complete AAC blocks are appended before the next decoder call.
; D0=0 OK (including source EOF with buffered bytes), D0=1 parser/I/O failure.
vpv45_topup_adts_buffer:
        movem.l d1-d7/a0-a3,-(sp)
        tst.l   vpv43_streaming_audio
        beq.w   vpv45_topup_ok

        move.l  v19_aac_buf_ptr,d6
        beq.w   vpv45_topup_fail
        move.l  d6,d5
        add.l   v19_aac_buf_len,d5
        move.l  vpv18_stream_cur,d4
        cmp.l   d6,d4
        bcs.w   vpv45_topup_fail
        cmp.l   d5,d4
        bhi.w   vpv45_topup_fail
        sub.l   d4,d5

        cmpi.l  #VPV44_ADTS_TOPUP_THRESHOLD,d5
        bcc.w   vpv45_topup_ok
        tst.l   vpv43_a_source_eof
        bne.w   vpv45_topup_ok

        move.l  d4,a1
        move.l  d6,a0
        move.l  d5,d3
        beq.s   vpv45_compact_done
        cmp.l   a0,a1
        beq.s   vpv45_compact_done
vpv45_compact_loop:
        move.b  (a1)+,(a0)+
        subq.l  #1,d3
        bne.s   vpv45_compact_loop
vpv45_compact_done:
        move.l  d5,v19_aac_buf_len
        move.l  v19_aac_buf_ptr,d0
        move.l  d0,vpv18_stream_cur
        add.l   d5,d0
        move.l  d0,v19_aac_buf_cur
        clr.l   v19_aac_frame_count
        moveq   #0,d7

vpv45_topup_loop:
        move.l  v19_aac_buf_len,d0
        cmpi.l  #VPV19_AAC_BUF_SIZE-$00002010,d0
        bcc.s   vpv45_topup_have
        cmpi.l  #VPV43_ADTS_FILL_FRAMES,d7
        bcc.s   vpv45_topup_have
        jsr     vpv43_a_find_audio_block
        tst.l   d0
        beq.s   vpv45_topup_found
        cmpi.l  #2,d0
        beq.s   vpv45_topup_eof
        bra.w   vpv45_topup_fail

vpv45_topup_found:
        move.l  vpv43_a_payload_len,d0
        addq.l  #7,d0
        move.l  v19_aac_buf_len,d1
        add.l   d0,d1
        cmpi.l  #VPV19_AAC_BUF_SIZE,d1
        bhi.w   vpv45_topup_fail
        move.l  vpv43_a_payload_len,d0
        jsr     vpv19_append_adts_header
        tst.l   d0
        bne.w   vpv45_topup_fail
        move.l  vpv43_a_payload_len,d0
        jsr     vpv43_a_copy_payload
        tst.l   d0
        bne.w   vpv45_topup_fail
        addq.l  #1,d7
        addq.l  #1,v19_aac_frame_count
        addq.l  #1,vpv43_a_total_frames
        bra.w   vpv45_topup_loop

vpv45_topup_eof:
        move.l  #1,vpv43_a_source_eof
vpv45_topup_have:
        addq.l  #1,vpv45_topup_count
        cmpi.l  #1,vpv45_topup_count
        bne.s   vpv45_topup_ok
        lea     msg_vpv45_topup_ok,a1
        move.l  #msg_vpv45_topup_ok_end-msg_vpv45_topup_ok,d3
        jsr     vpv21n_trace
vpv45_topup_ok:
        moveq   #0,d0
        bra.s   vpv45_topup_done
vpv45_topup_fail:
        move.l  #1,vpv43_a_reader_error
        lea     msg_vpv45_topup_fail,a1
        move.l  #msg_vpv45_topup_fail_end-msg_vpv45_topup_fail,d3
        jsr     vpv21n_trace
        moveq   #1,d0
vpv45_topup_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Decoder callbacks over ADTS. VPv47 can refill this window indefinitely.
vpv19_read_cb:
        move.l  12(sp),d0              ; requested byte count
        move.l  8(sp),a0               ; destination
        tst.l   vpv43_streaming_audio
        beq.w   vpv19_read_legacy

        movem.l d2-d7/a2-a3,-(sp)
        move.l  d0,d7
        move.l  a0,a3
        moveq   #0,d6                  ; bytes returned this call
vpv43_read_loop:
        tst.l   d7
        beq.w   vpv43_read_done
        move.l  v19_aac_buf_ptr,d1
        add.l   v19_aac_buf_len,d1
        move.l  vpv18_stream_cur,d2
        sub.l   d2,d1                  ; available bytes
        bne.s   vpv43_read_have

        ; VPv47: callback is memory-only. Never call DOS/Matroska parsing
        ; recursively from inside Helix DECOPS_DECODE. The outer scheduler
        ; tops this buffer up before each decode call.
        bra.w   vpv43_read_done

vpv43_read_have:
        move.l  d7,d5
        cmp.l   d1,d5
        bls.s   vpv43_read_n_ready
        move.l  d1,d5
vpv43_read_n_ready:
        move.l  vpv18_stream_cur,a1
        move.l  d5,d4
        beq.s   vpv43_read_after_copy
vpv43_read_copy:
        move.b  (a1)+,(a3)+
        subq.l  #1,d4
        bne.s   vpv43_read_copy
vpv43_read_after_copy:
        move.l  a1,vpv18_stream_cur
        sub.l   d5,d7
        add.l   d5,d6
        bra.w   vpv43_read_loop
vpv43_read_done:
        move.l  d6,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

vpv19_read_legacy:
        move.l  v19_aac_buf_ptr,d1
        add.l   v19_aac_buf_len,d1
        sub.l   vpv18_stream_cur,d1
        cmp.l   d1,d0
        bls.s   vpv19_read_count_ok
        move.l  d1,d0
vpv19_read_count_ok:
        tst.l   d0
        beq.s   vpv19_read_done
        move.l  d0,d1
        move.l  vpv18_stream_cur,a1
        move.l  8(sp),a0
vpv19_read_loop:
        move.b  (a1)+,(a0)+
        subq.l  #1,d1
        bne.s   vpv19_read_loop
        move.l  a1,vpv18_stream_cur
vpv19_read_done:
        rts

vpv19_seek_cb:
        move.l  12(sp),d1              ; origin
        tst.l   vpv43_streaming_audio
        beq.w   vpv19_seek_legacy

        ; Streaming AAC is intentionally forward-only. Helix may rewind to byte
        ; zero while opening; support exactly that operation plus CUR+0.
        cmpi.l  #0,d1
        beq.s   vpv43_seek_set
        cmpi.l  #1,d1
        beq.s   vpv43_seek_cur
        bra.w   vpv19_seek_fail
vpv43_seek_set:
        tst.l   8(sp)
        bne.w   vpv19_seek_fail
        movem.l d2-d7/a0-a3/a6,-(sp)
        clr.l   vpv43_a_source_eof
        clr.l   vpv43_a_total_frames
        clr.l   vpv43_first_audio_pts_found
        clr.l   vpv43_first_audio_pts_ticks
        jsr     vpv43_audio_reader_reopen
        tst.l   d0
        bne.s   vpv43_seek_set_fail
        jsr     vpv43_fill_adts_buffer
        tst.l   d0
        bne.s   vpv43_seek_set_fail
        moveq   #0,d0
        bra.s   vpv43_seek_set_done
vpv43_seek_set_fail:
        moveq   #-1,d0
vpv43_seek_set_done:
        movem.l (sp)+,d2-d7/a0-a3/a6
        rts
vpv43_seek_cur:
        tst.l   8(sp)
        bne.w   vpv19_seek_fail
        moveq   #0,d0
        rts

vpv19_seek_legacy:
        cmpi.l  #0,d1
        beq.s   vpv19_seek_set
        cmpi.l  #1,d1
        beq.s   vpv19_seek_cur
        cmpi.l  #2,d1
        beq.s   vpv19_seek_end
        bra.s   vpv19_seek_fail
vpv19_seek_set:
        move.l  v19_aac_buf_ptr,a0
        bra.s   vpv19_seek_add
vpv19_seek_cur:
        move.l  vpv18_stream_cur,a0
        bra.s   vpv19_seek_add
vpv19_seek_end:
        move.l  v19_aac_buf_ptr,a0
        adda.l  v19_aac_buf_len,a0
vpv19_seek_add:
        adda.l  8(sp),a0
        move.l  a0,d0
        move.l  v19_aac_buf_ptr,d1
        cmp.l   d1,d0
        bcs.s   vpv19_seek_fail
        add.l   v19_aac_buf_len,d1
        cmp.l   d1,d0
        bhi.s   vpv19_seek_fail
        move.l  a0,vpv18_stream_cur
        moveq   #0,d0
        rts
vpv19_seek_fail:
        moveq   #-1,d0
        rts

; Configure ril.audio_render to the actual PCM format returned by Helix.
; v19 supports mono/stereo 16-bit and uses the decoder's real sample rate.
vpv19_configure_audio_render:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  vpv18_stream_info+DECSTREAM_RATE,d0
        move.l  d0,v19_pcm_rate
        moveq   #0,d0
        move.w  vpv18_stream_info+DECSTREAM_CHANNELS,d0
        move.l  d0,v19_pcm_channels
        moveq   #0,d0
        move.w  vpv18_stream_info+DECSTREAM_BITS,d0
        move.l  d0,v19_pcm_bits
        cmpi.l  #16,d0
        bne.w   vpv19_config_fail
        move.l  v19_pcm_channels,d0
        cmpi.l  #1,d0
        bcs.w   vpv19_config_fail
        cmpi.l  #2,d0
        bhi.w   vpv19_config_fail
        add.l   d0,d0
        move.l  d0,v19_pcm_blockalign
        move.l  v19_pcm_channels,d1
        lsl.l   #4,d1                  ; channels * 16 bits/sample
        move.l  v19_pcm_rate,d0
        mulu.w  d1,d0                  ; <= 96 kHz * 32 = 3.072 Mbit/s
        move.l  d0,v19_pcm_bitrate

        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv19_config_fail
        move.l  port_last_handle,vpv01_audio_control
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv19_config_fail
        move.l  port_last_handle,vpv01_audio_input
        move.l  vpv01_audio_input,input_port_handle

        move.l  #MMAL_ES_AUDIO,port_fmt_type
        move.l  #MMAL_ENCODING_PCM_SIGNED_LE,port_fmt_encoding
        clr.l   port_fmt_variant
        move.l  v19_pcm_bitrate,d0
        move.l  d0,port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v19_pcm_channels,d0
        move.l  d0,port_video_width
        move.l  v19_pcm_rate,d0
        move.l  d0,port_video_height
        move.l  v19_pcm_bits,d0
        move.l  d0,port_crop_x
        move.l  v19_pcm_blockalign,d0
        move.l  d0,port_crop_y
        clr.l   port_crop_width
        clr.l   port_crop_height
        clr.l   port_fps_num
        clr.l   port_fps_den
        clr.l   port_par_num
        clr.l   port_par_den
        clr.l   port_color_space

        move.l  port_buf_num_min,d0
        tst.l   d0
        bne.s   vpv19_cfg_num_ok
        moveq   #1,d0
vpv19_cfg_num_ok:
        ; VPv47: renderer must accept at least two queued PCM buffers so the
        ; next block can already be resident while the current one is playing.
        cmpi.l  #2,d0
        bcc.s   vpv47_cfg_num_ok
        moveq   #2,d0
vpv47_cfg_num_ok:
        move.l  d0,port_buf_num
        ; VPv58: VPv49 decoded batches stay 64 KiB internally, but audio_render
        ; sees 64-KiB chunks. Keep the proven two renderer slots; together they
        ; can queue two complete 64-KiB FAAD batches (~743 ms at 44.1-kHz stereo)
        ; ahead without touching the video loop.
        move.l  #VPV53_AUDIO_CHUNK_BYTES,d0
vpv21_cfg_have_size:
        cmp.l   port_buf_size_min,d0
        bcc.s   vpv19_cfg_size_ok
        move.l  port_buf_size_min,d0
vpv19_cfg_size_ok:
        cmp.l   #VPV21_PCM_MAX_BYTES,d0
        bhi.w   vpv19_config_fail
        move.l  d0,port_buf_size

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_set_input
        tst.l   d0
        bne.w   vpv19_config_fail
        move.l  vpv01_audio_input,d0
        jsr     vpv01_set_hdmi_destination
        tst.l   d0
        beq.s   vpv19_dest_ok
        move.l  vpv01_audio_control,d0
        jsr     vpv01_set_hdmi_destination
        tst.l   d0
        bne.w   vpv19_config_fail
vpv19_dest_ok:
        move.l  vpv01_audio_handle,component_handle
        move.l  vpv01_audio_input,input_port_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv19_config_fail
        tst.l   v12f_local_port
        bne.s   vpv19_enable_second
        jsr     port_enable_current
        bra.s   vpv19_enable_done
vpv19_enable_second:
        move.l  vpv01_audio_input,d0
        move.l  #MMAL_PORT_INPUT,d1
        jsr     v9f_port_enable
vpv19_enable_done:
        tst.l   d0
        bne.w   vpv19_config_fail
        move.l  vpv01_audio_handle,component_handle
        jsr     component_enable_worker
        tst.l   d0
        bne.w   vpv19_config_fail
        move.l  #1,vpv01_component_enabled
        lea     msg_v19_render_ok,a1
        move.l  #msg_v19_render_ok_end-msg_v19_render_ok,d3
        jsr     print_force
        moveq   #0,d0
        bra.s   vpv19_config_done
vpv19_config_fail:
        lea     msg_v19_render_fail,a1
        move.l  #msg_v19_render_fail_end-msg_v19_render_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv19_config_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

vpv19_audio_test:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   v19_test_status
        clr.l   vpv01_test_status
        clr.l   vpv18_seg
        clr.l   vpv18_ops
        clr.l   vpv18_dec_handle
        clr.l   vpv18_pcm_blocks
        clr.l   vpv18_total_samples

        lea     msg_v19_header,a1
        move.l  #msg_v19_header_end-msg_v19_header,d3
        jsr     print_force
        jsr     vpv18_load_module
        tst.l   d0
        bne.w   vpv19_test_fail
        jsr     vpv19_open_module
        tst.l   d0
        bne.w   vpv19_test_fail

        lea     msg_v19_dec_fmt,a1
        move.l  #msg_v19_dec_fmt_end-msg_v19_dec_fmt,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv18_stream_info+DECSTREAM_RATE,d0
        jsr     print_hex32
        lea     msg_vpv18_info_ch,a1
        move.l  #msg_vpv18_info_ch_end-msg_vpv18_info_ch,d3
        jsr     print_force
        moveq   #0,d0
        move.w  vpv18_stream_info+DECSTREAM_CHANNELS,d0
        jsr     print_hex32
        lea     msg_vpv18_info_bits,a1
        move.l  #msg_vpv18_info_bits_end-msg_vpv18_info_bits,d3
        jsr     print_force
        moveq   #0,d0
        move.w  vpv18_stream_info+DECSTREAM_BITS,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print

        lea     msg_vpv01_mmal_ready,a1
        move.l  #msg_vpv01_mmal_ready_end-msg_vpv01_mmal_ready,d3
        jsr     print_force
        jsr     vpv01_create_audio_render
        tst.l   d0
        bne.w   vpv19_test_fail
        jsr     vpv19_configure_audio_render
        tst.l   d0
        bne.w   vpv19_test_fail
        jsr     vpv01_prepare_tone
        tst.l   d0
        bne.w   vpv19_test_fail

        lea     msg_v19_play,a1
        move.l  #msg_v19_play_end-msg_v19_play,d3
        jsr     print_force
vpv19_decode_loop:
        jsr     vpv18_decode_block
        tst.l   d0
        bmi.w   vpv19_decode_error
        beq.w   vpv19_decode_eof
        move.l  d0,vpv18_pcm_samples
        add.l   d0,vpv18_total_samples
        move.l  d0,d1
        move.l  v19_pcm_channels,d2
        mulu.w  d2,d1
        lsl.l   #1,d1
        move.l  d1,vpv18_pcm_bytes
        cmpi.l  #VPV01_TONE_BYTES,d1
        bhi.w   vpv19_decode_error
        jsr     vpv18_swap_pcm16
        jsr     vpv18_make_pagelist
        tst.l   d0
        bne.w   vpv19_decode_error
        jsr     vpv18_send_pcm_block
        tst.l   d0
        bne.w   vpv19_decode_error
        jsr     vpv18_wait_pcm_block
        tst.l   d0
        bne.w   vpv19_decode_error
        addq.l  #1,vpv18_pcm_blocks
        bra.w   vpv19_decode_loop
vpv19_decode_eof:
        jsr     dma_pre_all
        move.l  a5,a6
        move.l  #20,d1
        jsr     Delay(a6)
        jsr     dma_post_all
        lea     msg_v19_success,a1
        move.l  #msg_v19_success_end-msg_v19_success,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv18_pcm_blocks,d0
        jsr     print_hex32
        lea     msg_vpv18_success_samples,a1
        move.l  #msg_vpv18_success_samples_end-msg_vpv18_success_samples,d3
        jsr     print_force
        move.l  vpv18_total_samples,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        bra.s   vpv19_cleanup
vpv19_decode_error:
        lea     msg_v19_decode_fail,a1
        move.l  #msg_v19_decode_fail_end-msg_v19_decode_fail,d3
        jsr     print_force
vpv19_test_fail:
        move.l  #1,v19_test_status
        move.l  #1,vpv01_test_status
vpv19_cleanup:
        jsr     vpv18_close_module
        jsr     vpv01_cleanup
        jsr     vpv19_free_aac_buffer
        tst.l   vpv01_test_status
        beq.s   vpv19_cleanup_ok
        move.l  #1,v19_test_status
vpv19_cleanup_ok:
        tst.l   v19_test_status
        bne.s   vpv19_done
        lea     msg_v19_done,a1
        move.l  #msg_v19_done_end-msg_v19_done,d3
        jsr     print_force
vpv19_done:
        move.l  v19_test_status,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


; ====================================================================
; VPv36 - AUDIO INPUT0 PORT_INFO_SET ISOLATION ON BOTH START PATHS
;
; Stage strategy:
;   1) keep the VPv21T/VPv21U proven AAC predecode + retained PCM path,
;   2) build/enable the hardware-proven HDMI_v41L H264/ISP graph,
;   3) create ril.audio_render on the already-open MMAL service (VPv21U proven),
;   4) query ONLY audio_render CONTROL port 0 via MMAL_PORT_INFO_GET,
;   5) restore the live video globals and run the complete video to EOS.
;
; No audio INPUT query, no PORT_INFO_SET, no audio enable and no PCM transfer.
; Purpose: isolate the first synchronous audio port transaction from all later
; audio configuration work.
; ====================================================================
VPV21_PCM_MAX_BYTES    equ $00010000      ; VPv47: full proven 64-KiB audio_render input buffer
VPV21_PCM_PAGE_OFS     equ $00040000      ; same geometry as proven V41L input slot
VPV21_PCM_DMA_SPAN     equ $00041000      ; same proven 256-KiB data + pagelist span
VPV21_PCM_ALLOC_SIZE   equ $00085000      ; VPv47: two 0x42000-aligned audio DMA slots + alignment slack
VPV47_AUDIO_SLOTS        equ 2
VPV47_AUDIO_CONTEXT_BASE equ $A0300100
; VPv66: keep VPv58 video/VCHIQ scheduling intact, but send each complete 64-KiB
; FAAD batch as one 64-KiB (~372 ms @44.1k stereo) renderer buffer. VPv66
; uses two slots = two full ~743-ms FAAD batches queued ahead against video stalls.
VPV53_AUDIO_CHUNK_BYTES  equ $00010000
VPV38_PCM_BLOCKS       equ 1
VPV38_PCM_STORE_BYTES   equ $00010000      ; VPv47: one full 64-KiB priming/prefetch PCM block

; VPv48 - BerryFAAD03 / BerryCore CPU1 bridge.
; The external module is the BerryFAAD03 FAAD2 2.11.2 build.
VPV48_FAAD_MODULE_SIZE equ $00022109      ; 139529 bytes (BerryFAAD03 variable-rate)
VPV48_FAAD_INPUT_SIZE  equ $00020000      ; 128 KiB aligned staging input
VPV48_FAAD_OUT_SIZE    equ $00011000      ; 256-byte metadata + 64 KiB PCM + guard
VPV48_FAAD_WORK_SIZE   equ $00040000      ; 256 KiB persistent FAAD work/heap/stack
VPV48_FAAD_MAIL_SIZE   equ 128
VPV48_FAAD_MOD_ALLOC   equ VPV48_FAAD_MODULE_SIZE+$1000
VPV48_FAAD_IN_ALLOC    equ VPV48_FAAD_INPUT_SIZE+$1000
VPV48_FAAD_OUT_ALLOC   equ VPV48_FAAD_OUT_SIZE+$1000
VPV48_FAAD_WORK_ALLOC  equ VPV48_FAAD_WORK_SIZE+$1000
VPV48_FAAD_MAIL_ALLOC  equ $00002000
VPV48_SCAN_LOW         equ $08000000
VPV48_SCAN_HIGH        equ $10000000
VPV48_MAGIC0           equ $42393942
VPV48_MAGIC1           equ $59393959
VPV48_CMD_LOAD_MODULE  equ 3
VPV48_CMD_CALL_MODULE  equ 4
VPV48_CMD_UNLOAD_MODULE equ 5
VPV48_MODULE_TYPE_CODEC equ 2
VPV48_FAAD_OUT_MARKER  equ $46414431      ; 'FAD1'
VPV48_FAAD_BATCH_STATUS equ 4
VPV48_MAIL_MAX_TICKS   equ 500
VPV56_MAIL_FAST_POLLS  equ 512        ; immediate cache-coherent polls before 1 OS-tick fallback
VPV56_MAIL_SPIN        equ 255        ; short CPU-side wait between PreDMA/PostDMA

