        section code,code

; Prime one bounded PCM block before MMAL startup. VPv47 keeps Helix open and
; refills compressed AAC through a rolling 128-KiB ADTS window during playback.
vpv21_predecode_pcm:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv21_pcm_total_bytes
        clr.l   vpv21_pcm_total_samples
        clr.l   vpv21_audio_returned
        clr.l   vpv21_audio_dma_active
        clr.l   vpv38_pcm_block_count
        clr.l   vpv38_pcm_store_total
        clr.l   vpv41_decoder_live
        clr.l   vpv41_audio_eof
        clr.l   vpv41_live_decode_blocks
        clr.l   vpv48_batch_count
        lea     vpv38_pcm_block_sizes,a0
        moveq   #VPV38_PCM_BLOCKS-1,d0
vpv48_clear_sizes:
        clr.l   (a0)+
        dbra    d0,vpv48_clear_sizes

        ; Keep VPv47's proven pair of 64-KiB MMAL audio DMA slots unchanged.
        move.l  a4,a6
        move.l  #VPV21_PCM_ALLOC_SIZE,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   vpv21_predecode_fail
        move.l  d0,vpv21_pcm_alloc
        add.l   #$00000fff,d0
        and.l   #$fffff000,d0
        move.l  d0,vpv21_pcm_ptr
        move.l  d0,vpv21_pcm_write_ptr
        cmp.l   #$3f000000,d0
        bcc.w   vpv21_predecode_fail_free
        move.l  d0,d1
        add.l   #VPV21_PCM_DMA_SPAN-1,d1
        cmp.l   #$3f000000,d1
        bcc.w   vpv21_predecode_fail_free
        move.l  d0,d1
        or.l    #$c0000000,d1
        move.l  d1,vpv21_pcm_bus
        move.l  d0,d1
        add.l   #VPV21_PCM_PAGE_OFS,d1
        move.l  d1,vpv21_pcm_pagelist_ptr
        or.l    #$c0000000,d1
        move.l  d1,vpv21_pcm_pagelist_bus

        move.l  vpv21_pcm_ptr,d1
        add.l   #$00042000,d1
        move.l  d1,vpv47_pcm1_ptr
        move.l  d1,d2
        or.l    #$c0000000,d2
        move.l  d2,vpv47_pcm1_bus
        add.l   #VPV21_PCM_PAGE_OFS,d1
        move.l  d1,vpv47_pcm1_pagelist_ptr
        or.l    #$c0000000,d1
        move.l  d1,vpv47_pcm1_pagelist_bus

        ; VPv48: install and initialize the BerryFAAD03
        ; module on CPU1. The Matroska/ADTS rolling reader remains VPv47 code.
        jsr     vpv48_faad_prepare
        tst.l   d0
        bne.w   vpv21_predecode_fail_decoder

        move.l  v19_aac_buf_ptr,d0
        move.l  d0,vpv18_stream_cur
        jsr     vpv48_faad_decode_batch_store
        tst.l   d0
        bne.w   vpv21_predecode_fail_decoder

        move.l  vpv48_last_pcm_bytes,d0
        tst.l   d0
        beq.w   vpv21_predecode_fail_decoder
        move.l  d0,vpv38_pcm_store_total
        move.l  d0,vpv21_pcm_total_bytes
        lea     vpv38_pcm_block_sizes,a0
        move.l  d0,(a0)
        move.l  #1,vpv38_pcm_block_count
        move.l  vpv48_last_samples_ch,d0
        move.l  d0,vpv21_pcm_total_samples

        ; BerryFAAD03 keeps the proven AAC-LC stereo/PCM16 format, but the
        ; samplerate now comes from FAAD2/ADTS instead of being forced to 48 kHz.
        tst.l   v19_pcm_rate
        beq.w   vpv21_predecode_fail_decoder
        move.l  #2,v19_pcm_channels
        move.l  #16,v19_pcm_bits
        move.l  #4,v19_pcm_blockalign
        move.l  v19_pcm_rate,d0
        lsl.l   #5,d0                  ; stereo PCM16 bitrate = samplerate * 32
        move.l  d0,v19_pcm_bitrate

        move.l  vpv43_first_audio_pts_ticks,d0
        move.l  d0,vpv43_audio_next_pts_ticks
        move.l  vpv170_first_audio_pts_hi,d0
        move.l  d0,vpv170_audio_next_pts_hi
        clr.l   vpv43_audio_pts_remainder
        move.l  v19_pcm_rate,d0
        tst.l   d0
        bne.s   vpv48_predecode_pts_ready
        clr.l   vpv43_pts_mode
vpv48_predecode_pts_ready:

        move.l  #1,vpv41_decoder_live
        move.l  #1,vpv41_live_decode_blocks

        lea     msg_vpv48_predecode_ok,a1
        move.l  #msg_vpv48_predecode_ok_end-msg_vpv48_predecode_ok,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv48_last_pcm_bytes,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv48_last_consumed,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        moveq   #0,d0
        bra.s   vpv21_predecode_done

vpv21_predecode_fail_decoder:
        lea     msg_vpv49_faad_call_fail,a1
        move.l  #msg_vpv49_faad_call_fail_end-msg_vpv49_faad_call_fail,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv48_last_mail_status,d0
        jsr     print_hex32
        lea     msg_vpv49_faad_freqidx,a1
        move.l  #msg_vpv49_faad_freqidx_end-msg_vpv49_faad_freqidx,d3
        jsr     print_force
        move.l  v19_adts_freqidx,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        jsr     vpv48_faad_cleanup
        jsr     vpv19_free_aac_buffer
vpv21_predecode_fail_free:
        jsr     vpv21_free_pcm
vpv21_predecode_fail:
        lea     msg_vpv21_predecode_fail,a1
        move.l  #msg_vpv21_predecode_fail_end-msg_vpv21_predecode_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv21_predecode_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; VPv47: copy the single staged priming PCM block into the proven DMA slot and rebuild
; its one-run VCHIQ pagelist. D0=block index, returns D0=0/1.
vpv38_load_pcm_block:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,d7
        cmp.l   vpv38_pcm_block_count,d7
        bcc.w   vpv38_load_fail

        ; Find block source by summing prior variable block sizes.
        lea     vpv38_pcm_store,a1
        lea     vpv38_pcm_block_sizes,a2
        moveq   #0,d6
vpv38_load_offset_loop:
        cmp.l   d7,d6
        bcc.s   vpv38_load_have_src
        move.l  (a2)+,d1
        adda.l  d1,a1
        addq.l  #1,d6
        bra.s   vpv38_load_offset_loop
vpv38_load_have_src:
        ; A2 currently points to this block's size entry when d7>0; recompute
        ; directly to keep the zero-index case simple and explicit.
        move.l  d7,d0
        lsl.l   #2,d0
        lea     vpv38_pcm_block_sizes,a2
        adda.l  d0,a2
        move.l  (a2),d5
        tst.l   d5
        beq.s   vpv38_load_fail
        cmpi.l  #VPV21_PCM_MAX_BYTES,d5
        bhi.s   vpv38_load_fail
        move.l  d5,vpv21_pcm_total_bytes

        ; Copy exact PCM bytes into the already-proven aligned DMA slot.
        move.l  vpv21_pcm_ptr,a0
        move.l  d5,d1
vpv38_copy_loop:
        move.b  (a1)+,(a0)+
        subq.l  #1,d1
        bne.s   vpv38_copy_loop

        ; Rebuild compressed contiguous-run pagelist for this exact block size.
        move.l  vpv21_pcm_pagelist_ptr,a0
        move.l  d5,d0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  d5,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        and.l   #$00000fff,d0
        move.l  vpv21_pcm_bus,d1
        and.l   #$fffff000,d1
        or.l    d0,d1
        lea     8(a0),a0
        move.l  d1,d0
        jsr     v94_pl_store             ; v96.94: CM4 = 36-bit pagelist
        moveq   #0,d0
        bra.s   vpv38_load_done
vpv38_load_fail:
        moveq   #1,d0
vpv38_load_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; VPv47: decode ONE additional AAC block live into the proven aligned PCM DMA
; slot. Helix reads through VPv47's rolling ADTS callback; refills come from an
; independent 64-KiB MKV reader and do not disturb the H264 file state.
; Return D0: 0=PCM ready, 1=AAC EOF, 2=fail.
vpv41_decode_live_pcm:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv41_decoder_live
        beq.w   vpv41_live_eof_return
        move.l  vpv18_ops,d0
        beq.w   vpv41_live_fail
        move.l  vpv18_dec_handle,d0
        beq.w   vpv41_live_fail

        ; VPv47: all file I/O and EBML parsing happens outside Helix.
        jsr     vpv45_topup_adts_buffer
        tst.l   d0
        bne.w   vpv41_live_fail

        move.l  vpv18_ops,a0
        move.l  DECOPS_DECODE(a0),a0
        move.l  #VPV43_SYNC_SAMPLES_CH,-(sp)
        move.l  vpv21_pcm_ptr,-(sp)
        move.l  vpv18_dec_handle,-(sp)
        jsr     (a0)
        lea     12(sp),sp
        tst.l   d0
        bmi.w   vpv41_live_fail
        beq.w   vpv41_live_eof

        move.l  d0,d5                  ; samples/channel
        move.l  d5,d1
        move.l  v19_pcm_channels,d6
        cmpi.l  #1,d6
        bcs.w   vpv41_live_fail
        cmpi.l  #2,d6
        bhi.w   vpv41_live_fail
        mulu.w  d6,d1
        lsl.l   #1,d1                  ; signed 16-bit PCM bytes
        tst.l   d1
        beq.w   vpv41_live_fail
        cmpi.l  #VPV21_PCM_MAX_BYTES,d1
        bhi.w   vpv41_live_fail
        move.l  d1,vpv21_pcm_total_bytes
        add.l   d5,vpv21_pcm_total_samples

        ; Native m68k decoder output is BE; MMAL PCM_SIGNED_LE requires LE.
        move.l  d1,d2
        lsr.l   #1,d2
        move.l  vpv21_pcm_ptr,a0
vpv41_live_swap_loop:
        moveq   #0,d0
        move.w  (a0),d0
        rol.w   #8,d0
        move.w  d0,(a0)+
        subq.l  #1,d2
        bne.s   vpv41_live_swap_loop

        ; Rebuild the compact contiguous VCHIQ pagelist for this exact block.
        move.l  vpv21_pcm_pagelist_ptr,a0
        move.l  d1,d0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  d1,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        and.l   #$00000fff,d0
        move.l  vpv21_pcm_bus,d3
        and.l   #$fffff000,d3
        or.l    d0,d3
        lea     8(a0),a0
        move.l  d3,d0
        jsr     v94_pl_store             ; v96.94: CM4 = 36-bit pagelist
        addq.l  #1,vpv41_live_decode_blocks
        moveq   #0,d0
        bra.w   vpv41_live_done

vpv41_live_eof:
        clr.l   vpv41_decoder_live
        move.l  #1,vpv41_audio_eof
        jsr     vpv18_close_module
        jsr     vpv19_free_aac_buffer
vpv41_live_eof_return:
        moveq   #1,d0
        bra.s   vpv41_live_done

vpv41_live_fail:
        clr.l   vpv41_decoder_live
        move.l  #1,vpv41_audio_eof
        jsr     vpv18_close_module
        jsr     vpv19_free_aac_buffer
        moveq   #2,d0
vpv41_live_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


; VPv47: decode ONE future AAC block into CPU-side vpv38_pcm_store while the
; previous PCM DMA buffer is still owned by VideoCore. No MMAL/VCHIQ transfer
; happens here. Return D0: 0=prefetch ready/already ready, 1=AAC EOF, 2=fail.
vpv45_prefetch_live_pcm:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv45_prefetch_ready
        bne.w   vpv45_prefetch_ok
        tst.l   vpv41_decoder_live
        beq.w   vpv45_prefetch_eof_return
        tst.l   vpv48_faad_ready
        beq.w   vpv45_prefetch_fail

        jsr     vpv48_faad_decode_batch_store
        cmpi.l  #1,d0
        beq.w   vpv45_prefetch_eof
        tst.l   d0
        bne.w   vpv45_prefetch_fail

        move.l  vpv48_last_pcm_bytes,d1
        tst.l   d1
        beq.w   vpv45_prefetch_fail
        cmpi.l  #VPV38_PCM_STORE_BYTES,d1
        bhi.w   vpv45_prefetch_fail
        move.l  d1,vpv45_prefetch_bytes
        move.l  vpv48_last_samples_ch,d5
        tst.l   d5
        beq.w   vpv45_prefetch_fail
        move.l  d5,vpv45_prefetch_samples
        add.l   d5,vpv21_pcm_total_samples

        move.l  #1,vpv45_prefetch_ready
        addq.l  #1,vpv45_prefetch_count
        addq.l  #1,vpv41_live_decode_blocks
        tst.l   vpv45_prefetch_first_logged
        bne.s   vpv45_prefetch_ok
        move.l  #1,vpv45_prefetch_first_logged
        lea     msg_vpv48_prefetch_ok,a1
        move.l  #msg_vpv48_prefetch_ok_end-msg_vpv48_prefetch_ok,d3
        jsr     vpv21n_trace
vpv45_prefetch_ok:
        moveq   #0,d0
        bra.s   vpv45_prefetch_done

vpv45_prefetch_eof:
        clr.l   vpv41_decoder_live
        move.l  #1,vpv41_audio_eof
        jsr     vpv48_faad_cleanup
        jsr     vpv19_free_aac_buffer
vpv45_prefetch_eof_return:
        moveq   #1,d0
        bra.s   vpv45_prefetch_done

vpv45_prefetch_fail:
        clr.l   vpv41_decoder_live
        move.l  #1,vpv41_audio_eof
        jsr     vpv48_faad_cleanup
        jsr     vpv19_free_aac_buffer
        moveq   #2,d0
vpv45_prefetch_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Copy the already-decoded future PCM block into the proven aligned DMA slot
; and rebuild the one-run pagelist. Return D0=0/1.
vpv45_load_prefetch_pcm:
        movem.l d1-d7/a0-a3,-(sp)
        tst.l   vpv45_prefetch_ready
        beq.w   vpv45_load_prefetch_fail
        move.l  vpv45_prefetch_bytes,d5
        tst.l   d5
        beq.w   vpv45_load_prefetch_fail
        cmpi.l  #VPV21_PCM_MAX_BYTES,d5
        bhi.w   vpv45_load_prefetch_fail
        move.l  d5,vpv21_pcm_total_bytes
        lea     vpv38_pcm_store,a1
        move.l  vpv21_pcm_ptr,a0
        move.l  d5,d1
vpv45_load_prefetch_copy:
        move.b  (a1)+,(a0)+
        subq.l  #1,d1
        bne.s   vpv45_load_prefetch_copy

        move.l  vpv21_pcm_pagelist_ptr,a0
        move.l  d5,d0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  d5,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        and.l   #$00000fff,d0
        move.l  vpv21_pcm_bus,d1
        and.l   #$fffff000,d1
        or.l    d0,d1
        lea     8(a0),a0
        move.l  d1,d0
        jsr     v94_pl_store             ; v96.94: CM4 = 36-bit pagelist
        clr.l   vpv45_prefetch_ready
        clr.l   vpv45_prefetch_bytes
        clr.l   vpv45_prefetch_samples
        moveq   #0,d0
        bra.s   vpv45_load_prefetch_done
vpv45_load_prefetch_fail:
        moveq   #1,d0
vpv45_load_prefetch_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; --------------------------------------------------------------------
; VPv135 - passive audio_renderer PTS vs wall-clock proof.
; Called from the existing audio BUFFER_TO_HOST callback. D1 = slot 0/1.
; No MMAL GET, no synchronous worker request and no transport state change.
; --------------------------------------------------------------------
vpv135_measure_audio_return:
        movem.l d0-d7/a0-a1,-(sp)
        cmpi.l  #2,vpv43_pts_mode
        bne.w   vpv135_audio_measure_done
        addq.l  #1,vpv135_audio_returns

        move.l  buffer_pts_hi,d5
        tst.l   d5
        bmi.s   vpv135_audio_pts_invalid
        move.l  buffer_pts_lo,d6

        ; Verify that the callback carries the exact 64-bit submitted PTS.
        move.l  d1,d0
        lsl.l   #2,d0
        lea     vpv135_slot_pts_hi,a0
        adda.l  d0,a0
        cmp.l   (a0),d5
        bne.s   vpv135_audio_callback_mismatch_seen
        lea     vpv135_slot_pts_lo,a0
        adda.l  d0,a0
        cmp.l   (a0),d6
        beq.s   vpv135_audio_callback_match
vpv135_audio_pts_invalid:
        addq.l  #1,vpv135_audio_invalid
        bra.w   vpv135_audio_measure_done
vpv135_audio_callback_mismatch_seen:
        addq.l  #1,vpv135_audio_callback_mismatch
vpv135_audio_callback_match:

        bsr     vpv98_read_sys_us
        move.l  d0,d7
        tst.l   vpv135_audio_started
        bne.s   vpv135_audio_measure_next
        move.l  #1,vpv135_audio_started
        move.l  d6,vpv135_audio_first_pts
        move.l  d6,vpv135_audio_last_pts
        move.l  d5,vpv170_audio_first_return_hi
        move.l  d5,vpv170_audio_last_pts_hi
        move.l  d7,vpv135_audio_first_wall
        move.l  d7,vpv135_audio_last_wall
        clr.l   vpv135_audio_wall_elapsed
        clr.l   vpv135_audio_pts_elapsed
        clr.l   vpv135_audio_last_drift
        clr.l   vpv135_audio_min_drift
        clr.l   vpv135_audio_max_drift
        bra.s   vpv135_audio_measure_done

vpv135_audio_measure_next:
        move.l  vpv170_audio_last_pts_hi,d4
        cmp.l   d4,d5
        bhi.s   vpv135_audio_monotonic
        bcs.s   vpv170_audio_nonmono_seen
        move.l  vpv135_audio_last_pts,d4
        cmp.l   d4,d6
        bcc.s   vpv135_audio_monotonic
vpv170_audio_nonmono_seen:
        addq.l  #1,vpv135_audio_nonmono
vpv135_audio_monotonic:
        move.l  d6,vpv135_audio_last_pts
        move.l  d5,vpv170_audio_last_pts_hi
        move.l  d7,vpv135_audio_last_wall
        move.l  d7,d3
        sub.l   vpv135_audio_first_wall,d3
        move.l  d3,vpv135_audio_wall_elapsed
        move.l  d6,d4
        sub.l   vpv135_audio_first_pts,d4
        move.l  d4,vpv135_audio_pts_elapsed
        sub.l   d4,d3
        move.l  d3,vpv135_audio_last_drift
        move.l  vpv135_audio_min_drift,d2
        cmp.l   d2,d3
        bge.s   vpv135_audio_min_ok
        move.l  d3,vpv135_audio_min_drift
vpv135_audio_min_ok:
        move.l  vpv135_audio_max_drift,d2
        cmp.l   d2,d3
        ble.s   vpv135_audio_measure_done
        move.l  d3,vpv135_audio_max_drift
vpv135_audio_measure_done:
        movem.l (sp)+,d0-d7/a0-a1
        rts

; --------------------------------------------------------------------
; VPv131 - passive scheduler/P96 timing proof.
;
; Called only after a frame has been successfully written to the P96 window.
; VPv134: output_current_pts_hi/lo belongs to the exact payload just blitted.
; Later BUFFER_TO_HOST callbacks cannot overwrite this frame-owned snapshot.
; We compare that propagated presentation PTS with the Pi 1-MHz system timer
; relative to the first displayed frame.  No worker call, no clock parameter
; query and no transport ownership change occurs here.
;
; For a correctly audio-mastered scheduler:
;   wall_elapsed ~= pts_elapsed
; and drift should remain bounded rather than growing over time.
; --------------------------------------------------------------------
vpv131_measure_display_timing:
        movem.l d0-d7/a0-a1,-(sp)
        addq.l  #1,vpv131_schedwall_frames

        ; VPv134 proof of the old ownership bug: the shared scratch header may
        ; already describe a later callback while output_current_pts_* still
        ; belongs to the payload that has just reached P96.
        move.l  buffer_pts_hi,d0
        cmp.l   output_current_pts_hi,d0
        bne.s   vpv134_schedwall_scratch_mismatch
        move.l  buffer_pts_lo,d0
        cmp.l   output_current_pts_lo,d0
        beq.s   vpv134_schedwall_scratch_checked
vpv134_schedwall_scratch_mismatch:
        addq.l  #1,vpv134_pts_scratch_mismatches
vpv134_schedwall_scratch_checked:

        ; Legacy P96 wall-clock proof remains a compact low-32 diagnostic.
        ; C/video_render playback itself uses the full 64-bit MMAL timestamp.
        tst.l   output_current_pts_hi
        beq.s   vpv131_schedwall_pts_ok
        addq.l  #1,vpv131_schedwall_invalid
        bra.w   vpv131_schedwall_done

vpv131_schedwall_pts_ok:
        bsr     vpv98_read_sys_us
        move.l  d0,d7                    ; current free-running wall-us
        move.l  output_current_pts_lo,d6 ; displayed payload scheduler PTS-us

        ; VPv136: split the video delay into header->BULK_RX and
        ; BULK_RX->finished-P96 stages, using this same display wall sample.
        bsr     vpv136_measure_video_stages

        tst.l   vpv131_schedwall_started
        bne.s   vpv131_schedwall_next
        move.l  #1,vpv131_schedwall_started
        move.l  d6,vpv131_schedwall_first_pts
        move.l  d6,vpv131_schedwall_last_pts
        move.l  d7,vpv131_schedwall_first_wall
        move.l  d7,vpv131_schedwall_last_wall
        clr.l   vpv131_schedwall_wall_elapsed
        clr.l   vpv131_schedwall_pts_elapsed
        clr.l   vpv131_schedwall_last_drift
        clr.l   vpv131_schedwall_min_drift
        clr.l   vpv131_schedwall_max_drift
        bra.w   vpv131_schedwall_done

vpv131_schedwall_next:
        ; Presentation PTS from video_scheduler must be monotonic.  Track the
        ; normal per-frame step as an additional B-frame/reorder proof.
        move.l  vpv131_schedwall_last_pts,d5
        cmp.l   d5,d6
        bcs.s   vpv131_schedwall_nonmono_seen
        move.l  d6,d4
        sub.l   d5,d4                    ; d4 = current PTS step
        move.l  vpv131_schedwall_step_min,d3
        bne.s   vpv131_schedwall_step_min_have
        move.l  d4,vpv131_schedwall_step_min
        bra.s   vpv131_schedwall_step_max_check
vpv131_schedwall_step_min_have:
        cmp.l   d3,d4
        bcc.s   vpv131_schedwall_step_max_check
        move.l  d4,vpv131_schedwall_step_min
vpv131_schedwall_step_max_check:
        cmp.l   vpv131_schedwall_step_max,d4
        bls.s   vpv131_schedwall_after_step
        move.l  d4,vpv131_schedwall_step_max
        bra.s   vpv131_schedwall_after_step

vpv131_schedwall_nonmono_seen:
        addq.l  #1,vpv131_schedwall_nonmono

vpv131_schedwall_after_step:
        move.l  d6,vpv131_schedwall_last_pts
        move.l  d7,vpv131_schedwall_last_wall

        move.l  d7,d3
        sub.l   vpv131_schedwall_first_wall,d3
        move.l  d3,vpv131_schedwall_wall_elapsed
        move.l  d6,d4
        sub.l   vpv131_schedwall_first_pts,d4
        move.l  d4,vpv131_schedwall_pts_elapsed
        sub.l   d4,d3                    ; signed drift = wall - PTS
        move.l  d3,vpv131_schedwall_last_drift

        ; Signed min/max drift.  Values print in two's-complement hex; the
        ; next analysis can convert them directly to signed microseconds.
        move.l  vpv131_schedwall_min_drift,d2
        cmp.l   d2,d3
        bge.s   vpv131_schedwall_min_ok
        move.l  d3,vpv131_schedwall_min_drift
vpv131_schedwall_min_ok:
        move.l  vpv131_schedwall_max_drift,d2
        cmp.l   d2,d3
        ble.s   vpv131_schedwall_done
        move.l  d3,vpv131_schedwall_max_drift

vpv131_schedwall_done:
        movem.l (sp)+,d0-d7/a0-a1
        rts

; --------------------------------------------------------------------
; VPv136 - passive video stage latency proof.
;
; Entry from vpv131_measure_display_timing:
;   D6 = exact displayed frame PTS in microseconds
;   D7 = wall time immediately after successful P96 blit
; Frame-owned snapshots:
;   output_current_header_wall   = ISP BUFFER_TO_HOST arrival
;   output_current_bulkdone_wall = BULK_RX completion
;
; No MMAL/VCHIQ command is emitted.  The measurement separates:
;   A) PTS progression vs ISP header arrival progression
;   B) header -> BULK_RX_DONE latency
;   C) BULK_RX_DONE -> completed P96 blit latency
; --------------------------------------------------------------------
vpv136_measure_video_stages:
        movem.l d0-d7/a0-a1,-(sp)
        addq.l  #1,vpv136_stage_frames

        tst.l   output_current_pts_hi
        bne.w   vpv136_stage_invalid_seen
        move.l  output_current_header_wall,d5
        tst.l   d5
        beq.w   vpv136_stage_invalid_seen
        move.l  output_current_bulkdone_wall,d4
        tst.l   d4
        beq.w   vpv136_stage_invalid_seen

        ; Per-frame stage latencies.  Unsigned subtraction naturally tolerates
        ; one 32-bit system-timer wrap, although normal tests are far shorter.
        move.l  d4,d2
        sub.l   d5,d2                    ; header -> BULK_RX_DONE
        move.l  d7,d3
        sub.l   d4,d3                    ; BULK_RX_DONE -> P96 complete

        tst.l   vpv136_stage_started
        bne.s   vpv136_stage_next

        move.l  #1,vpv136_stage_started
        move.l  d6,vpv136_stage_first_pts
        move.l  d5,vpv136_stage_first_header_wall
        move.l  d5,vpv136_stage_last_header_wall
        clr.l   vpv136_stage_header_elapsed
        clr.l   vpv136_stage_pts_elapsed
        clr.l   vpv136_stage_header_drift
        clr.l   vpv136_stage_header_drift_min
        clr.l   vpv136_stage_header_drift_max

        move.l  d2,vpv136_stage_h2b_last
        move.l  d2,vpv136_stage_h2b_min
        move.l  d2,vpv136_stage_h2b_max
        move.l  d3,vpv136_stage_b2p_last
        move.l  d3,vpv136_stage_b2p_min
        move.l  d3,vpv136_stage_b2p_max
        bra.w   vpv136_stage_done

vpv136_stage_next:
        move.l  d5,vpv136_stage_last_header_wall
        move.l  d5,d0
        sub.l   vpv136_stage_first_header_wall,d0
        move.l  d0,vpv136_stage_header_elapsed

        move.l  d6,d1
        sub.l   vpv136_stage_first_pts,d1
        move.l  d1,vpv136_stage_pts_elapsed

        sub.l   d1,d0                    ; signed: header wall progression - PTS
        move.l  d0,vpv136_stage_header_drift
        move.l  vpv136_stage_header_drift_min,d1
        cmp.l   d1,d0
        bge.s   vpv136_stage_hdr_min_ok
        move.l  d0,vpv136_stage_header_drift_min
vpv136_stage_hdr_min_ok:
        move.l  vpv136_stage_header_drift_max,d1
        cmp.l   d1,d0
        ble.s   vpv136_stage_h2b
        move.l  d0,vpv136_stage_header_drift_max

vpv136_stage_h2b:
        move.l  d2,vpv136_stage_h2b_last
        move.l  vpv136_stage_h2b_min,d0
        cmp.l   d0,d2
        bcc.s   vpv136_stage_h2b_min_ok
        move.l  d2,vpv136_stage_h2b_min
vpv136_stage_h2b_min_ok:
        cmp.l   vpv136_stage_h2b_max,d2
        bls.s   vpv136_stage_b2p
        move.l  d2,vpv136_stage_h2b_max

vpv136_stage_b2p:
        move.l  d3,vpv136_stage_b2p_last
        move.l  vpv136_stage_b2p_min,d0
        cmp.l   d0,d3
        bcc.s   vpv136_stage_b2p_min_ok
        move.l  d3,vpv136_stage_b2p_min
vpv136_stage_b2p_min_ok:
        cmp.l   vpv136_stage_b2p_max,d3
        bls.s   vpv136_stage_done
        move.l  d3,vpv136_stage_b2p_max
        bra.s   vpv136_stage_done

vpv136_stage_invalid_seen:
        addq.l  #1,vpv136_stage_invalid

vpv136_stage_done:
        movem.l (sp)+,d0-d7/a0-a1
        rts

; VPv47 cleanup is idempotent and is also used when video is stopped before
; AAC EOF. It must run before the PCM DMA allocation is freed.
