; ====================================================================
; VPv48 - BerryCore / BerryFAAD03 bridge
; ====================================================================
; The mailbox/service ABI is the hardware-confirmed BerryFAAD03 ABI.  The
; external module remains resident for the whole A/V run; compressed AAC is
; staged into an aligned 128-KiB buffer, while output/work follow the same
; CachePreDMA/PostDMA discipline used by berrytestFAAD02.

; D0=allocation bytes. Returns D0=raw allocation, D1=4-KiB-aligned pointer;
; D0=0 on failure. Allocation size is preserved exactly for later FreeMem.
vpv48_alloc_aligned:
        movem.l d2-d3/a1/a6,-(sp)
        move.l  d0,d3
        move.l  4.w,a6
        move.l  #MEMF_PUBLICFASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.s   vpv48_aa_done
        move.l  d0,d2
        move.l  d0,d1
        add.l   #$00000fff,d1
        and.l   #$fffff000,d1
        cmpi.l  #VPV48_SCAN_LOW,d1
        bcs.s   vpv48_aa_bad
        cmpi.l  #VPV48_SCAN_HIGH,d1
        bcc.s   vpv48_aa_bad
        move.l  d2,d0
        bra.s   vpv48_aa_done
vpv48_aa_bad:
        move.l  d2,a1
        move.l  d3,d0
        jsr     FreeMem(a6)
        moveq   #0,d0
vpv48_aa_done:
        movem.l (sp)+,d2-d3/a1/a6
        rts

vpv48_check_phys:
        cmpi.l  #VPV48_SCAN_LOW,d0
        bcs.s   vpv48_phys_bad
        cmpi.l  #VPV48_SCAN_HIGH,d0
        bcc.s   vpv48_phys_bad
        moveq   #0,d0
        rts
vpv48_phys_bad:
        moveq   #1,d0
        rts

vpv48_setup_mail:
        movem.l d1-d4/a0-a1/a6,-(sp)
        move.l  vpv48_mail_ptr,a0
        move.l  #VPV48_MAGIC0,(a0)
        move.l  #VPV48_MAGIC1,4(a0)
        moveq   #0,d1
        lea     8(a0),a1
        moveq   #29,d2
vpv48_sm_clear:
        move.l  d1,(a1)+
        dbra    d2,vpv48_sm_clear
        move.l  #VPV48_FAAD_MAIL_SIZE,vpv48_dma_mail_len
        move.l  vpv48_mail_ptr,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  d0,d4
        move.l  vpv48_mail_ptr,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        jsr     CachePostDMA(a6)
        move.l  vpv48_mail_ptr,d0
        cmp.l   d4,d0
        beq.s   vpv48_sm_ok
        moveq   #1,d0
        bra.s   vpv48_sm_done
vpv48_sm_ok:
        moveq   #0,d0
vpv48_sm_done:
        movem.l (sp)+,d1-d4/a0-a1/a6
        rts

; --------------------------------------------------------------------
; VPv158 - nonblocking BerryCore mailbox request for live FAAD batches.
;
; The synchronous vpv48_send_request remains untouched for module LOAD/INIT,
; UNLOAD and the pre-video priming decode.  Live CALL_MODULE(param0=3) uses
; this split begin/poll pair so CPU1 can work while the 68k dispatcher keeps
; servicing VideoCore/VCHIQ.  Exactly one request may be outstanding.
; --------------------------------------------------------------------
; D0=BerryCore command. Returns D0=0 launched, D0=1 busy/fail.
vpv158_send_request_begin:
        movem.l d4-d7/a0-a3/a6,-(sp)
        tst.l   vpv158_mail_pending
        bne.w   vpv158_srb_fail
        move.l  vpv48_mail_ptr,a3
        addq.l  #1,vpv48_sequence
        move.l  vpv48_sequence,12(a3)
        move.l  d0,16(a3)
        clr.l   20(a3)
        move.l  vpv48_req_in_phys,24(a3)
        move.l  vpv48_req_in_len,28(a3)
        move.l  vpv48_req_out_phys,32(a3)
        move.l  vpv48_req_out_len,36(a3)
        move.l  vpv48_req_param0,40(a3)
        move.l  vpv48_req_param1,44(a3)
        move.l  vpv48_req_work_phys,48(a3)
        move.l  vpv48_req_work_len,52(a3)
        clr.l   56(a3)
        clr.l   60(a3)
        clr.l   64(a3)
        move.l  #$ffffffff,68(a3)
        move.l  #$ffffffff,vpv48_last_mail_status
        clr.l   72(a3)
        clr.l   76(a3)
        clr.b   9(a3)
        clr.b   10(a3)
        clr.b   11(a3)
        move.b  #$a5,8(a3)

        ; Exact same cache-coherent publication sequence as the proven
        ; synchronous path, but return immediately instead of waiting.
        move.l  #VPV48_FAAD_MAIL_SIZE,vpv48_dma_mail_len
        move.l  a3,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  a3,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        jsr     CachePostDMA(a6)
        move.l  #1,vpv158_mail_pending
        moveq   #0,d0
        bra.s   vpv158_srb_done
vpv158_srb_fail:
        moveq   #1,d0
vpv158_srb_done:
        movem.l (sp)+,d4-d7/a0-a3/a6
        rts

; Poll one bounded coherent mailbox window.  No DOS Delay() here.
; Returns D0=0 pending, D0=1 completed OK (D1/D2/D3 results), D0=2 bad.
vpv158_send_request_poll:
        movem.l d4-d7/a0-a3/a6,-(sp)
        tst.l   vpv158_mail_pending
        bne.s   vpv158_srp_have_pending
        moveq   #2,d0
        bra.w   vpv158_srp_done
vpv158_srp_have_pending:
        move.l  vpv48_mail_ptr,a3
        move.l  #VPV48_FAAD_MAIL_SIZE,vpv48_dma_mail_len
        move.l  a3,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #0,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.w  #VPV56_MAIL_SPIN,d4
vpv158_srp_spin:
        dbf     d4,vpv158_srp_spin
        move.l  a3,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #0,d0
        move.l  4.w,a6
        jsr     CachePostDMA(a6)

        cmpi.b  #$5a,9(a3)
        bne.s   vpv158_srp_notyet
        move.l  vpv48_sequence,d5
        cmp.l   76(a3),d5
        bne.s   vpv158_srp_notyet
        move.l  68(a3),vpv48_last_mail_status
        cmpi.b  #1,10(a3)
        bne.s   vpv158_srp_bad
        cmpi.b  #20,11(a3)
        bne.s   vpv158_srp_bad
        tst.l   68(a3)
        bne.s   vpv158_srp_bad
        move.l  56(a3),d1
        move.l  60(a3),d2
        move.l  64(a3),d3
        clr.l   vpv158_mail_pending
        addq.l  #1,vpv56_mail_fast_replies
        moveq   #1,d0
        bra.s   vpv158_srp_done
vpv158_srp_notyet:
        addq.l  #1,vpv158_async_pending_polls
        moveq   #0,d0
        bra.s   vpv158_srp_done
vpv158_srp_bad:
        clr.l   vpv158_mail_pending
        moveq   #2,d0
vpv158_srp_done:
        movem.l (sp)+,d4-d7/a0-a3/a6
        rts

; D0=BerryCore command. Returns D0=0 and D1/D2/D3=result0/1/2.
vpv48_send_request:
        movem.l d4-d7/a0-a3/a6,-(sp)
        move.l  vpv48_mail_ptr,a3
        addq.l  #1,vpv48_sequence
        move.l  vpv48_sequence,12(a3)
        move.l  d0,16(a3)
        clr.l   20(a3)
        move.l  vpv48_req_in_phys,24(a3)
        move.l  vpv48_req_in_len,28(a3)
        move.l  vpv48_req_out_phys,32(a3)
        move.l  vpv48_req_out_len,36(a3)
        move.l  vpv48_req_param0,40(a3)
        move.l  vpv48_req_param1,44(a3)
        move.l  vpv48_req_work_phys,48(a3)
        move.l  vpv48_req_work_len,52(a3)
        clr.l   56(a3)
        clr.l   60(a3)
        clr.l   64(a3)
        move.l  #$ffffffff,68(a3)
        move.l  #$ffffffff,vpv48_last_mail_status
        clr.l   72(a3)
        clr.l   76(a3)
        clr.b   9(a3)
        clr.b   10(a3)
        clr.b   11(a3)
        move.b  #$a5,8(a3)

        move.l  #VPV48_FAAD_MAIL_SIZE,vpv48_dma_mail_len
        move.l  a3,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  a3,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        jsr     CachePostDMA(a6)

        ; VPv58: the old loop always called DOS Delay(1) before the FIRST
        ; mailbox inspection.  That quantized every FAAD batch to at least
        ; one OS tick.  Poll coherently first with a very short bounded spin;
        ; only fall back to Delay(1) if CPU1 really has not answered yet.
        moveq   #0,d7                  ; number of slow 1-tick fallbacks
        move.l  #VPV56_MAIL_FAST_POLLS,d6
vpv48_sr_poll:
        move.l  #VPV48_FAAD_MAIL_SIZE,vpv48_dma_mail_len
        move.l  a3,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #0,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.w  #VPV56_MAIL_SPIN,d4
vpv56_sr_spin:
        dbf     d4,vpv56_sr_spin
        move.l  a3,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #0,d0
        move.l  4.w,a6
        jsr     CachePostDMA(a6)
        cmpi.b  #$5a,9(a3)
        bne.s   vpv48_sr_notyet
        move.l  vpv48_sequence,d5
        cmp.l   76(a3),d5
        bne.s   vpv48_sr_notyet
        move.l  68(a3),vpv48_last_mail_status
        cmpi.b  #1,10(a3)
        bne.s   vpv48_sr_bad
        cmpi.b  #20,11(a3)
        bne.s   vpv48_sr_bad
        tst.l   68(a3)
        bne.s   vpv48_sr_bad
        tst.l   d7
        bne.s   vpv56_sr_reply_counted
        addq.l  #1,vpv56_mail_fast_replies
vpv56_sr_reply_counted:
        move.l  56(a3),d1
        move.l  60(a3),d2
        move.l  64(a3),d3
        moveq   #0,d0
        bra.s   vpv48_sr_done
vpv48_sr_notyet:
        subq.l  #1,d6
        bne.w   vpv48_sr_poll

        ; Rare slow path: preserve the old scheduler-friendly yield and the
        ; old 500-tick timeout, but only AFTER hundreds of immediate polls.
        addq.l  #1,vpv56_mail_slow_fallbacks
        move.l  a5,a6
        moveq   #1,d1
        jsr     Delay(a6)
        addq.l  #1,d7
        cmpi.l  #VPV48_MAIL_MAX_TICKS,d7
        bcc.s   vpv48_sr_timeout
        move.l  #VPV56_MAIL_FAST_POLLS,d6
        bra.w   vpv48_sr_poll
vpv48_sr_timeout:
        moveq   #1,d0
        bra.s   vpv48_sr_done
vpv48_sr_bad:
        moveq   #2,d0
vpv48_sr_done:
        movem.l (sp)+,d4-d7/a0-a3/a6
        rts

vpv48_map_output_work:
        movem.l d1-d2/a0-a1/a6,-(sp)
        move.l  #VPV48_FAAD_OUT_SIZE,vpv48_dma_output_len
        move.l  vpv48_output_ptr,a0
        lea     vpv48_dma_output_len,a1
        moveq   #0,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  d0,vpv48_output_phys
        move.b  #1,vpv48_output_dma_active
        cmpi.l  #VPV48_FAAD_OUT_SIZE,vpv48_dma_output_len
        bne.s   vpv48_mow_bad
        jsr     vpv48_check_phys
        tst.l   d0
        bne.s   vpv48_mow_bad

        move.l  #VPV48_FAAD_WORK_SIZE,vpv48_dma_work_len
        move.l  vpv48_work_ptr,a0
        lea     vpv48_dma_work_len,a1
        moveq   #0,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  d0,vpv48_work_phys
        move.b  #1,vpv48_work_dma_active
        cmpi.l  #VPV48_FAAD_WORK_SIZE,vpv48_dma_work_len
        bne.s   vpv48_mow_bad
        jsr     vpv48_check_phys
        tst.l   d0
        bne.s   vpv48_mow_bad
        moveq   #0,d0
        bra.s   vpv48_mow_done
vpv48_mow_bad:
        moveq   #1,d0
vpv48_mow_done:
        movem.l (sp)+,d1-d2/a0-a1/a6
        rts

vpv48_close_output_work:
        movem.l d0/a0-a1/a6,-(sp)
        move.l  4.w,a6
        tst.b   vpv48_output_dma_active
        beq.s   vpv48_cow_no_out
        move.l  vpv48_output_ptr,a0
        lea     vpv48_dma_output_len,a1
        moveq   #0,d0
        jsr     CachePostDMA(a6)
        clr.b   vpv48_output_dma_active
vpv48_cow_no_out:
        tst.b   vpv48_work_dma_active
        beq.s   vpv48_cow_done
        move.l  vpv48_work_ptr,a0
        lea     vpv48_dma_work_len,a1
        moveq   #0,d0
        jsr     CachePostDMA(a6)
        clr.b   vpv48_work_dma_active
vpv48_cow_done:
        movem.l (sp)+,d0/a0-a1/a6
        rts

; D0=input byte count in aligned vpv48_input_ptr.
vpv48_map_input:
        movem.l d1/a0-a1/a6,-(sp)
        move.l  d0,vpv48_dma_input_len
        move.l  vpv48_input_ptr,a0
        lea     vpv48_dma_input_len,a1
        moveq   #DMA_ReadFromRAM,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  d0,vpv48_input_phys
        move.b  #1,vpv48_input_dma_active
        jsr     vpv48_check_phys
        movem.l (sp)+,d1/a0-a1/a6
        rts

vpv48_close_input:
        movem.l d0/a0-a1/a6,-(sp)
        tst.b   vpv48_input_dma_active
        beq.s   vpv48_ci_done
        move.l  vpv48_input_ptr,a0
        lea     vpv48_dma_input_len,a1
        moveq   #DMA_ReadFromRAM,d0
        move.l  4.w,a6
        jsr     CachePostDMA(a6)
        clr.b   vpv48_input_dma_active
vpv48_ci_done:
        movem.l (sp)+,d0/a0-a1/a6
        rts

vpv48_release_mail:
        movem.l d0/a0-a1/a6,-(sp)
        move.l  vpv48_mail_ptr,a0
        move.l  a0,d0
        beq.s   vpv48_rm_done
        clr.l   (a0)
        clr.l   4(a0)
        clr.l   8(a0)
        move.l  #VPV48_FAAD_MAIL_SIZE,vpv48_dma_mail_len
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  vpv48_mail_ptr,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        jsr     CachePostDMA(a6)
vpv48_rm_done:
        movem.l (sp)+,d0/a0-a1/a6
        rts

; Allocate/load/map the external BerryFAAD03 module, publish the BerryCore
; mailbox, LOAD_MODULE it and run FAAD INIT. D0=0/1.
vpv48_faad_prepare:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv48_faad_ready
        bne.w   vpv48_fp_ok
        clr.l   vpv48_faad_module_loaded
        clr.l   vpv48_sequence
        clr.b   vpv48_module_dma_active
        clr.b   vpv48_input_dma_active
        clr.b   vpv48_output_dma_active
        clr.b   vpv48_work_dma_active

        move.l  #VPV48_FAAD_MAIL_ALLOC,d0
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   vpv48_fp_fail
        move.l  d0,vpv48_mail_raw
        move.l  d1,vpv48_mail_ptr
        move.l  #VPV48_FAAD_MOD_ALLOC,d0
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   vpv48_fp_fail
        move.l  d0,vpv48_module_raw
        move.l  d1,vpv48_module_ptr
        move.l  #VPV48_FAAD_IN_ALLOC,d0
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   vpv48_fp_fail
        move.l  d0,vpv48_input_raw
        move.l  d1,vpv48_input_ptr
        move.l  #VPV48_FAAD_OUT_ALLOC,d0
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   vpv48_fp_fail
        move.l  d0,vpv48_output_raw
        move.l  d1,vpv48_output_ptr
        move.l  #VPV48_FAAD_WORK_ALLOC,d0
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   vpv48_fp_fail
        move.l  d0,vpv48_work_raw
        move.l  d1,vpv48_work_ptr

        ; Read external raw AArch64 module.
        move.l  a5,a6
        lea     vpv48_faad_modulename_progdir,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        bne.s   vpv48_fp_have_module_file
        lea     vpv48_faad_modulename,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   vpv48_fp_fail
vpv48_fp_have_module_file:
        move.l  d0,vpv48_module_file
        move.l  d0,d1
        move.l  vpv48_module_ptr,d2
        move.l  #VPV48_FAAD_MODULE_SIZE,d3
        jsr     Read(a6)
        move.l  d0,d7
        move.l  vpv48_module_file,d1
        jsr     Close(a6)
        clr.l   vpv48_module_file
        cmpi.l  #VPV48_FAAD_MODULE_SIZE,d7
        bne.w   vpv48_fp_fail

        ; Publish module for CPU1.
        move.l  #VPV48_FAAD_MODULE_SIZE,vpv48_dma_module_len
        move.l  vpv48_module_ptr,a0
        lea     vpv48_dma_module_len,a1
        moveq   #DMA_ReadFromRAM,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  d0,vpv48_module_phys
        move.b  #1,vpv48_module_dma_active
        cmpi.l  #VPV48_FAAD_MODULE_SIZE,vpv48_dma_module_len
        bne.w   vpv48_fp_fail
        jsr     vpv48_check_phys
        tst.l   d0
        bne.w   vpv48_fp_fail

        jsr     vpv48_map_output_work
        tst.l   d0
        bne.w   vpv48_fp_fail
        jsr     vpv48_setup_mail
        tst.l   d0
        bne.w   vpv48_fp_fail

        ; LOAD_MODULE.
        move.l  vpv48_module_phys,vpv48_req_in_phys
        move.l  #VPV48_FAAD_MODULE_SIZE,vpv48_req_in_len
        clr.l   vpv48_req_out_phys
        clr.l   vpv48_req_out_len
        clr.l   vpv48_req_param0
        clr.l   vpv48_req_param1
        clr.l   vpv48_req_work_phys
        clr.l   vpv48_req_work_len
        moveq   #VPV48_CMD_LOAD_MODULE,d0
        jsr     vpv48_send_request
        tst.l   d0
        bne.w   vpv48_fp_fail
        cmpi.l  #VPV48_MODULE_TYPE_CODEC,d1
        bne.w   vpv48_fp_fail
        cmpi.l  #VPV48_FAAD_MODULE_SIZE,d2
        bne.w   vpv48_fp_fail
        move.l  #1,vpv48_faad_module_loaded

        ; CALL_MODULE param0=0 -> FAAD decoder INIT + persistent arena bind.
        clr.l   vpv48_req_in_phys
        clr.l   vpv48_req_in_len
        move.l  vpv48_output_phys,vpv48_req_out_phys
        move.l  #VPV48_FAAD_OUT_SIZE,vpv48_req_out_len
        clr.l   vpv48_req_param0
        clr.l   vpv48_req_param1
        move.l  vpv48_work_phys,vpv48_req_work_phys
        move.l  #VPV48_FAAD_WORK_SIZE,vpv48_req_work_len
        moveq   #VPV48_CMD_CALL_MODULE,d0
        jsr     vpv48_send_request
        tst.l   d0
        bne.w   vpv48_fp_fail
        cmpi.l  #1,d1
        bne.w   vpv48_fp_fail

        move.l  #1,vpv48_faad_ready
        lea     msg_vpv48_faad_ready,a1
        move.l  #msg_vpv48_faad_ready_end-msg_vpv48_faad_ready,d3
        jsr     print_force
vpv48_fp_ok:
        moveq   #0,d0
        bra.s   vpv48_fp_done
vpv48_fp_fail:
        lea     msg_vpv48_faad_fail,a1
        move.l  #msg_vpv48_faad_fail_end-msg_vpv48_faad_fail,d3
        jsr     print_force
        jsr     vpv48_faad_cleanup
        moveq   #1,d0
vpv48_fp_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Decode one BerryFAAD03 streaming batch from the unread VPv47 ADTS window.
; PCM is copied to vpv38_pcm_store and converted BE->LE for MMAL audio_render.
; D0=0 PCM ready, 1 clean AAC EOF, 2 failure.
vpv48_faad_decode_batch_store:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv48_last_consumed
        clr.l   vpv48_last_pcm_bytes
        clr.l   vpv48_last_samples_ch
        clr.l   vpv48_last_frames
        tst.l   vpv48_faad_ready
        beq.w   vpv48_fdb_fail

        ; Existing VPv47 parser compacts/refills the source before CPU1 runs.
        jsr     vpv45_topup_adts_buffer
        tst.l   d0
        bne.w   vpv48_fdb_fail

        move.l  v19_aac_buf_ptr,d6
        move.l  d6,d5
        add.l   v19_aac_buf_len,d5
        move.l  vpv18_stream_cur,d4
        cmp.l   d6,d4
        bcs.w   vpv48_fdb_fail
        cmp.l   d5,d4
        bhi.w   vpv48_fdb_fail
        sub.l   d4,d5                  ; D5 unread bytes
        bne.s   vpv48_fdb_have_input
        tst.l   vpv43_a_source_eof
        bne.w   vpv48_fdb_eof
        bra.w   vpv48_fdb_fail
vpv48_fdb_have_input:
        cmpi.l  #VPV48_FAAD_INPUT_SIZE,d5
        bls.s   vpv48_fdb_size_ok
        move.l  #VPV48_FAAD_INPUT_SIZE,d5
vpv48_fdb_size_ok:

        ; Stage compressed input into the exact aligned geometry proven by
        ; berrytestFAAD02. No CPU1 DMA phase touches VPv47's rolling buffer.
        move.l  d4,a1
        move.l  vpv48_input_ptr,a0
        move.l  d5,d3                  ; exact byte count remains in D5
        move.l  d3,d2
        lsr.l   #2,d2                  ; copy bulk as 32-bit longwords
        beq.s   vpv48_fdb_ci_tail
vpv48_fdb_ci_long:
        move.l  (a1)+,(a0)+
        subq.l  #1,d2
        bne.s   vpv48_fdb_ci_long
vpv48_fdb_ci_tail:
        and.l   #3,d3                  ; 0..3 bytes left
        beq.s   vpv48_fdb_copy_input_done
vpv48_fdb_ci_byte:
        move.b  (a1)+,(a0)+
        subq.l  #1,d3
        bne.s   vpv48_fdb_ci_byte
vpv48_fdb_copy_input_done:

        move.l  d5,d0
        jsr     vpv48_map_input
        tst.l   d0
        bne.w   vpv48_fdb_fail

        move.l  vpv48_input_phys,vpv48_req_in_phys
        move.l  d5,vpv48_req_in_len
        move.l  vpv48_output_phys,vpv48_req_out_phys
        move.l  #VPV48_FAAD_OUT_SIZE,vpv48_req_out_len
        move.l  #3,vpv48_req_param0
        clr.l   vpv48_req_param1
        move.l  vpv48_work_phys,vpv48_req_work_phys
        move.l  #VPV48_FAAD_WORK_SIZE,vpv48_req_work_len
        moveq   #VPV48_CMD_CALL_MODULE,d0
        jsr     vpv48_send_request
        move.l  d0,d7
        jsr     vpv48_close_input
        jsr     vpv48_close_output_work
        tst.l   d7
        bne.w   vpv48_fdb_reopen_fail

        move.l  vpv48_output_ptr,a0
        cmpi.l  #VPV48_FAAD_OUT_MARKER,0(a0)
        bne.w   vpv48_fdb_reopen_fail
        cmpi.l  #VPV48_FAAD_BATCH_STATUS,4(a0)
        bne.w   vpv48_fdb_reopen_fail
        move.l  8(a0),d0              ; actual FAAD2 samplerate from ADTS/ASC
        tst.l   d0
        beq.w   vpv48_fdb_reopen_fail
        cmpi.l  #192000,d0
        bhi.w   vpv48_fdb_reopen_fail
        move.l  d0,v19_pcm_rate
        cmpi.l  #2,12(a0)
        bne.w   vpv48_fdb_reopen_fail
        tst.l   24(a0)                 ; FAAD error
        bne.w   vpv48_fdb_reopen_fail

        move.l  16(a0),d4              ; bytes consumed from staged chunk
        tst.l   d4
        beq.w   vpv48_fdb_reopen_fail
        cmp.l   d5,d4
        bhi.w   vpv48_fdb_reopen_fail
        move.l  d4,vpv48_last_consumed
        move.l  28(a0),vpv48_last_frame_index
        move.l  68(a0),vpv48_last_frames
        move.l  76(a0),d6              ; exact PCM bytes
        move.l  d6,vpv48_last_pcm_bytes
        cmpi.l  #VPV38_PCM_STORE_BYTES,d6
        bhi.w   vpv48_fdb_reopen_fail
        move.l  20(a0),d2              ; total interleaved sample values
        btst    #0,d2
        bne.w   vpv48_fdb_reopen_fail
        lsr.l   #1,d2                  ; stereo -> samples/channel
        move.l  d2,vpv48_last_samples_ch

        ; Advance the old VPv47 stream cursor by exactly FAAD's consumed bytes.
        move.l  vpv18_stream_cur,d1
        add.l   d4,d1
        move.l  d1,vpv18_stream_cur

        tst.l   d6
        beq.s   vpv48_fdb_no_pcm
        move.l  20(a0),d1
        lsl.l   #1,d1
        cmp.l   d6,d1
        bne.w   vpv48_fdb_reopen_fail

        ; CPU1/AArch64-BE PCM16 -> VideoCore MMAL PCM_SIGNED_LE.
        lea     256(a0),a1
        lea     vpv38_pcm_store,a2
        move.l  d6,d3
        lsr.l   #1,d3
vpv48_fdb_pcm_loop:
        move.w  (a1)+,d0
        ror.w   #8,d0                  ; AArch64-BE PCM16 -> MMAL little-endian
        move.w  d0,(a2)+
        subq.l  #1,d3
        bne.s   vpv48_fdb_pcm_loop

        addq.l  #1,vpv48_batch_count
        jsr     vpv48_map_output_work
        tst.l   d0
        bne.w   vpv48_fdb_fail
        moveq   #0,d0
        bra.s   vpv48_fdb_done

vpv48_fdb_no_pcm:
        ; FAAD has a one-frame filterbank priming delay. Normally the first
        ; batch already contains many frames, but handle a short first chunk.
        jsr     vpv48_map_output_work
        tst.l   d0
        bne.w   vpv48_fdb_fail
        move.l  v19_aac_buf_ptr,d1
        add.l   v19_aac_buf_len,d1
        cmp.l   vpv18_stream_cur,d1
        bhi.w   vpv48_faad_decode_batch_store_retry
        tst.l   vpv43_a_source_eof
        bne.s   vpv48_fdb_eof
        bra.w   vpv48_fdb_fail
vpv48_faad_decode_batch_store_retry:
        ; Re-enter through a small tail path instead of recursion.
        movem.l (sp)+,d1-d7/a0-a3/a6
        bra.w   vpv48_faad_decode_batch_store

vpv48_fdb_reopen_fail:
        jsr     vpv48_map_output_work
        ; fall through to failure regardless of reopen result
vpv48_fdb_fail:
        moveq   #2,d0
        bra.s   vpv48_fdb_done
vpv48_fdb_eof:
        moveq   #1,d0
vpv48_fdb_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; --------------------------------------------------------------------
; VPv158 - asynchronous live BerryFAAD03 batch.
;
; Launch performs only source top-up/staging/cache publication and then returns.
; CPU1 decode itself runs concurrently with the normal 68k A/V dispatcher.
; Poll finalizes the exact same output metadata/PCM conversion as the proven
; synchronous vpv48_faad_decode_batch_store path.
; --------------------------------------------------------------------
; Returns D0=0 launched/already pending, 1 clean AAC EOF, 2 failure.
vpv158_faad_async_launch:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv158_faad_pending
        bne.w   vpv158_fal_ok
        tst.l   vpv48_faad_ready
        beq.w   vpv158_fal_fail
        tst.b   vpv48_output_dma_active
        beq.w   vpv158_fal_fail
        tst.b   vpv48_work_dma_active
        beq.w   vpv158_fal_fail

        clr.l   vpv48_last_consumed
        clr.l   vpv48_last_pcm_bytes
        clr.l   vpv48_last_samples_ch
        clr.l   vpv48_last_frames

        ; Keep the proven VPv47 audio rolling-reader/top-up unchanged.
        jsr     vpv45_topup_adts_buffer
        tst.l   d0
        bne.w   vpv158_fal_fail

        move.l  v19_aac_buf_ptr,d6
        move.l  d6,d5
        add.l   v19_aac_buf_len,d5
        move.l  vpv18_stream_cur,d4
        cmp.l   d6,d4
        bcs.w   vpv158_fal_fail
        cmp.l   d5,d4
        bhi.w   vpv158_fal_fail
        sub.l   d4,d5
        bne.s   vpv158_fal_have_input
        tst.l   vpv43_a_source_eof
        bne.w   vpv158_fal_eof
        bra.w   vpv158_fal_fail
vpv158_fal_have_input:
        cmpi.l  #VPV48_FAAD_INPUT_SIZE,d5
        bls.s   vpv158_fal_size_ok
        move.l  #VPV48_FAAD_INPUT_SIZE,d5
vpv158_fal_size_ok:

        ; Stage compressed bytes exactly as the synchronous path does.
        move.l  d4,a1
        move.l  vpv48_input_ptr,a0
        move.l  d5,d3
        move.l  d3,d2
        lsr.l   #2,d2
        beq.s   vpv158_fal_ci_tail
vpv158_fal_ci_long:
        move.l  (a1)+,(a0)+
        subq.l  #1,d2
        bne.s   vpv158_fal_ci_long
vpv158_fal_ci_tail:
        and.l   #3,d3
        beq.s   vpv158_fal_copy_done
vpv158_fal_ci_byte:
        move.b  (a1)+,(a0)+
        subq.l  #1,d3
        bne.s   vpv158_fal_ci_byte
vpv158_fal_copy_done:

        move.l  d5,d0
        jsr     vpv48_map_input
        tst.l   d0
        bne.w   vpv158_fal_fail

        move.l  vpv48_input_phys,vpv48_req_in_phys
        move.l  d5,vpv48_req_in_len
        move.l  vpv48_output_phys,vpv48_req_out_phys
        move.l  #VPV48_FAAD_OUT_SIZE,vpv48_req_out_len
        move.l  #3,vpv48_req_param0
        clr.l   vpv48_req_param1
        move.l  vpv48_work_phys,vpv48_req_work_phys
        move.l  #VPV48_FAAD_WORK_SIZE,vpv48_req_work_len
        move.l  d5,vpv158_async_input_len
        bsr     vpv98_read_sys_us
        move.l  d0,vpv158_async_start_us
        moveq   #VPV48_CMD_CALL_MODULE,d0
        jsr     vpv158_send_request_begin
        tst.l   d0
        bne.s   vpv158_fal_publish_fail
        move.l  #1,vpv158_faad_pending
        addq.l  #1,vpv158_async_launches
vpv158_fal_ok:
        moveq   #0,d0
        bra.s   vpv158_fal_done
vpv158_fal_publish_fail:
        jsr     vpv48_close_input
vpv158_fal_fail:
        addq.l  #1,vpv158_async_failures
        moveq   #2,d0
        bra.s   vpv158_fal_done
vpv158_fal_eof:
        clr.l   vpv41_decoder_live
        move.l  #1,vpv41_audio_eof
        jsr     vpv48_faad_cleanup
        jsr     vpv19_free_aac_buffer
        moveq   #1,d0
vpv158_fal_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Poll the outstanding CPU1 batch once. Never Delay().
; D0=0 pending/no PCM yet, 1 PCM prefetch ready, 2 failure, 3 clean EOF.
vpv158_faad_async_poll:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv158_faad_pending
        bne.s   vpv158_fap_have_pending
        moveq   #0,d0
        bra.w   vpv158_fap_done
vpv158_fap_have_pending:
        jsr     vpv158_send_request_poll
        tst.l   d0
        beq.w   vpv158_fap_pending
        cmpi.l  #1,d0
        bne.w   vpv158_fap_fail_reply

        clr.l   vpv158_faad_pending
        addq.l  #1,vpv158_async_completions
        jsr     vpv48_close_input
        jsr     vpv48_close_output_work

        ; Wall latency from request publication until the coherent reply.
        bsr     vpv98_read_sys_us
        sub.l   vpv158_async_start_us,d0
        addq.l  #1,vpv157_audio_decode_calls
        add.l   d0,vpv157_audio_decode_total_us
        cmp.l   vpv157_audio_decode_max_us,d0
        bls.s   vpv158_fap_no_max
        move.l  d0,vpv157_audio_decode_max_us
vpv158_fap_no_max:
        cmpi.l  #20000,d0
        bls.s   vpv158_fap_no_20ms
        addq.l  #1,vpv157_audio_decode_gt20ms
vpv158_fap_no_20ms:
        move.l  v41e_hr_step_num,d1
        tst.l   d1
        beq.s   vpv158_fap_time_done
        cmp.l   d1,d0
        bls.s   vpv158_fap_time_done
        addq.l  #1,vpv157_audio_decode_gtframe
vpv158_fap_time_done:

        ; Validate BerryFAAD03 output exactly like the proven synchronous path.
        move.l  vpv48_output_ptr,a0
        cmpi.l  #VPV48_FAAD_OUT_MARKER,0(a0)
        bne.w   vpv158_fap_reopen_fail
        cmpi.l  #VPV48_FAAD_BATCH_STATUS,4(a0)
        bne.w   vpv158_fap_reopen_fail
        move.l  8(a0),d0
        tst.l   d0
        beq.w   vpv158_fap_reopen_fail
        cmpi.l  #192000,d0
        bhi.w   vpv158_fap_reopen_fail
        move.l  d0,v19_pcm_rate
        cmpi.l  #2,12(a0)
        bne.w   vpv158_fap_reopen_fail
        tst.l   24(a0)
        bne.w   vpv158_fap_reopen_fail

        move.l  16(a0),d4
        tst.l   d4
        beq.w   vpv158_fap_reopen_fail
        move.l  vpv158_async_input_len,d5
        cmp.l   d5,d4
        bhi.w   vpv158_fap_reopen_fail
        move.l  d4,vpv48_last_consumed
        move.l  28(a0),vpv48_last_frame_index
        move.l  68(a0),vpv48_last_frames
        move.l  76(a0),d6
        move.l  d6,vpv48_last_pcm_bytes
        cmpi.l  #VPV38_PCM_STORE_BYTES,d6
        bhi.w   vpv158_fap_reopen_fail
        move.l  20(a0),d2
        btst    #0,d2
        bne.w   vpv158_fap_reopen_fail
        lsr.l   #1,d2
        move.l  d2,vpv48_last_samples_ch

        ; Only now advance the audio cursor. While CPU1 was working, the
        ; staged input and rolling source cursor remained stable.
        move.l  vpv18_stream_cur,d1
        add.l   d4,d1
        move.l  d1,vpv18_stream_cur

        tst.l   d6
        beq.w   vpv158_fap_no_pcm
        move.l  20(a0),d1
        lsl.l   #1,d1
        cmp.l   d6,d1
        bne.w   vpv158_fap_reopen_fail

        lea     256(a0),a1
        lea     vpv38_pcm_store,a2
        move.l  d6,d3
        lsr.l   #1,d3
vpv158_fap_pcm_loop:
        move.w  (a1)+,d0
        ror.w   #8,d0
        move.w  d0,(a2)+
        subq.l  #1,d3
        bne.s   vpv158_fap_pcm_loop

        addq.l  #1,vpv48_batch_count
        jsr     vpv48_map_output_work
        tst.l   d0
        bne.w   vpv158_fap_fail

        ; Publish the completed CPU-only PCM block to the unchanged VPv47
        ; prefetch interface. No MMAL/VCHIQ transfer is performed here.
        move.l  vpv48_last_pcm_bytes,d1
        move.l  d1,vpv45_prefetch_bytes
        move.l  vpv48_last_samples_ch,d5
        move.l  d5,vpv45_prefetch_samples
        add.l   d5,vpv21_pcm_total_samples
        move.l  #1,vpv45_prefetch_ready
        addq.l  #1,vpv45_prefetch_count
        addq.l  #1,vpv41_live_decode_blocks
        tst.l   vpv45_prefetch_first_logged
        bne.s   vpv158_fap_ready
        move.l  #1,vpv45_prefetch_first_logged
        lea     msg_vpv48_prefetch_ok,a1
        move.l  #msg_vpv48_prefetch_ok_end-msg_vpv48_prefetch_ok,d3
        jsr     vpv21n_trace
vpv158_fap_ready:
        moveq   #1,d0
        bra.w   vpv158_fap_done

vpv158_fap_no_pcm:
        ; The live stream is already past FAAD's startup priming, so this is
        ; rare. Restore DMA publication and allow a later safe-window launch
        ; to process the next compressed bytes without blocking video.
        jsr     vpv48_map_output_work
        tst.l   d0
        bne.s   vpv158_fap_fail
        move.l  v19_aac_buf_ptr,d1
        add.l   v19_aac_buf_len,d1
        cmp.l   vpv18_stream_cur,d1
        bhi.s   vpv158_fap_no_pcm_more
        tst.l   vpv43_a_source_eof
        bne.s   vpv158_fap_eof
vpv158_fap_no_pcm_more:
        moveq   #0,d0
        bra.s   vpv158_fap_done

vpv158_fap_eof:
        clr.l   vpv41_decoder_live
        move.l  #1,vpv41_audio_eof
        jsr     vpv48_faad_cleanup
        jsr     vpv19_free_aac_buffer
        moveq   #3,d0
        bra.s   vpv158_fap_done

vpv158_fap_reopen_fail:
        jsr     vpv48_map_output_work
vpv158_fap_fail:
        addq.l  #1,vpv158_async_failures
        moveq   #2,d0
        bra.s   vpv158_fap_done
vpv158_fap_fail_reply:
        clr.l   vpv158_faad_pending
        jsr     vpv48_close_input
        jsr     vpv48_close_output_work
        addq.l  #1,vpv158_async_failures
        moveq   #2,d0
        bra.s   vpv158_fap_done
vpv158_fap_pending:
        moveq   #0,d0
vpv158_fap_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Emergency only: audio has no renderer-owned reserve left. Wait for an
; already-launched CPU1 batch so audio cannot underrun. Normal VPv158 runs
; should keep this at zero; every wait tick is counted explicitly.
; Returns D0=0 PCM ready/EOF handled, D0=1 failure.
vpv158_faad_async_force_wait:
        movem.l d1-d7/a0-a3/a6,-(sp)
        addq.l  #1,vpv158_async_forced_waits
        move.l  #VPV48_MAIL_MAX_TICKS,d7
vpv158_fafw_loop:
        jsr     vpv158_faad_async_poll
        cmpi.l  #1,d0
        beq.s   vpv158_fafw_ok
        cmpi.l  #2,d0
        beq.s   vpv158_fafw_fail
        cmpi.l  #3,d0
        beq.s   vpv158_fafw_ok
        tst.l   vpv158_faad_pending
        bne.s   vpv158_fafw_delay
        tst.l   vpv41_decoder_live
        beq.s   vpv158_fafw_ok
        jsr     vpv158_faad_async_launch
        cmpi.l  #2,d0
        beq.s   vpv158_fafw_fail
        cmpi.l  #1,d0
        beq.s   vpv158_fafw_ok
vpv158_fafw_delay:
        move.l  a5,a6
        moveq   #1,d1
        jsr     Delay(a6)
        addq.l  #1,vpv158_async_forced_wait_ticks
        subq.l  #1,d7
        bne.w   vpv158_fafw_loop
vpv158_fafw_fail:
        moveq   #1,d0
        bra.s   vpv158_fafw_done
vpv158_fafw_ok:
        moveq   #0,d0
vpv158_fafw_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Cleanup drain: if Ctrl-C/EOS arrives while CPU1 owns the live decode buffers,
; wait for that one request before UNLOAD/free. This happens outside live video
; scheduling and preserves the existing DMA ownership guarantee.
vpv158_faad_async_cleanup_drain:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv158_faad_pending
        beq.s   vpv158_facd_done
        move.l  #VPV48_MAIL_MAX_TICKS,d7
vpv158_facd_loop:
        jsr     vpv158_send_request_poll
        cmpi.l  #1,d0
        beq.s   vpv158_facd_reply
        cmpi.l  #2,d0
        beq.s   vpv158_facd_reply
        move.l  a5,a6
        moveq   #1,d1
        jsr     Delay(a6)
        subq.l  #1,d7
        bne.s   vpv158_facd_loop
        ; Never free buffers still potentially owned by CPU1.  A 500-tick
        ; timeout is treated as a safe leak/abort rather than a DMA use-after-free.
        addq.l  #1,vpv158_async_failures
        bra.s   vpv158_facd_done
vpv158_facd_reply:
        clr.l   vpv158_faad_pending
        clr.l   vpv158_mail_pending
        jsr     vpv48_close_input
        jsr     vpv48_close_output_work
vpv158_facd_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Idempotent FAAD/BerryCore cleanup. The Matroska audio reader/buffer remains
; owned by vpv19_free_aac_buffer and is deliberately not freed here.
vpv48_faad_cleanup:
        movem.l d0-d7/a0-a3/a6,-(sp)
        jsr     vpv158_faad_async_cleanup_drain
        tst.l   vpv158_faad_pending
        bne.w   vpv48_fc_pending_abort
        clr.l   vpv48_faad_ready
        jsr     vpv48_close_input
        tst.l   vpv48_faad_module_loaded
        beq.s   vpv48_fc_no_unload
        clr.l   vpv48_req_in_phys
        clr.l   vpv48_req_in_len
        clr.l   vpv48_req_out_phys
        clr.l   vpv48_req_out_len
        clr.l   vpv48_req_param0
        clr.l   vpv48_req_param1
        clr.l   vpv48_req_work_phys
        clr.l   vpv48_req_work_len
        moveq   #VPV48_CMD_UNLOAD_MODULE,d0
        jsr     vpv48_send_request
        clr.l   vpv48_faad_module_loaded
vpv48_fc_no_unload:
        jsr     vpv48_close_output_work
        jsr     vpv48_release_mail

        move.l  4.w,a6
        tst.b   vpv48_module_dma_active
        beq.s   vpv48_fc_no_moddma
        move.l  vpv48_module_ptr,a0
        lea     vpv48_dma_module_len,a1
        moveq   #DMA_ReadFromRAM,d0
        jsr     CachePostDMA(a6)
        clr.b   vpv48_module_dma_active
vpv48_fc_no_moddma:

        move.l  vpv48_work_raw,d0
        beq.s   vpv48_fc_no_work
        move.l  d0,a1
        move.l  #VPV48_FAAD_WORK_ALLOC,d0
        jsr     FreeMem(a6)
        clr.l   vpv48_work_raw
        clr.l   vpv48_work_ptr
vpv48_fc_no_work:
        move.l  vpv48_output_raw,d0
        beq.s   vpv48_fc_no_out
        move.l  d0,a1
        move.l  #VPV48_FAAD_OUT_ALLOC,d0
        jsr     FreeMem(a6)
        clr.l   vpv48_output_raw
        clr.l   vpv48_output_ptr
vpv48_fc_no_out:
        move.l  vpv48_input_raw,d0
        beq.s   vpv48_fc_no_in
        move.l  d0,a1
        move.l  #VPV48_FAAD_IN_ALLOC,d0
        jsr     FreeMem(a6)
        clr.l   vpv48_input_raw
        clr.l   vpv48_input_ptr
vpv48_fc_no_in:
        move.l  vpv48_module_raw,d0
        beq.s   vpv48_fc_no_mod
        move.l  d0,a1
        move.l  #VPV48_FAAD_MOD_ALLOC,d0
        jsr     FreeMem(a6)
        clr.l   vpv48_module_raw
        clr.l   vpv48_module_ptr
vpv48_fc_no_mod:
        move.l  vpv48_mail_raw,d0
        beq.s   vpv48_fc_no_mail
        move.l  d0,a1
        move.l  #VPV48_FAAD_MAIL_ALLOC,d0
        jsr     FreeMem(a6)
        clr.l   vpv48_mail_raw
        clr.l   vpv48_mail_ptr
vpv48_fc_no_mail:
        clr.l   vpv48_module_phys
        clr.l   vpv48_input_phys
        clr.l   vpv48_output_phys
        clr.l   vpv48_work_phys
        bra.s   vpv48_fc_done
vpv48_fc_pending_abort:
        ; CPU1 did not return inside the very large cleanup timeout. Preserve
        ; every shared buffer and module mapping rather than freeing live DMA.
        addq.l  #1,vpv158_async_failures
vpv48_fc_done:
        movem.l (sp)+,d0-d7/a0-a3/a6
        rts

; Create/configure audio_render while the video decoder/ISP path is still
; quiescent. This isolates the synchronous audio PORT_INFO_SET from active
; video-graph traffic. The audio component remains enabled but receives no
; buffer until the video graph has been built and the decoder component enabled.
vpv21_prepare_audio_early:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv21_audio_prepared

        move.l  component_handle,vpv21_saved_component
        move.l  input_port_handle,vpv21_saved_input
        move.l  port_query_index,vpv21_saved_port_qidx
        move.l  port_buf_size,vpv21_saved_port_buf_size

        lea     msg_vpv21_prepare_begin,a1
        move.l  #msg_vpv21_prepare_begin_end-msg_vpv21_prepare_begin,d3
        jsr     print_force
        jsr     vpv01_create_audio_render
        tst.l   d0
        bne.s   vpv21_prepare_restore_fail
        jsr     vpv19_configure_audio_render
        tst.l   d0
        bne.s   vpv21_prepare_restore_fail

        move.l  port_buf_size,vpv21_audio_port_buf_size
        move.l  #1,vpv21_audio_prepared
        lea     msg_vpv21_prepare_ok,a1
        move.l  #msg_vpv21_prepare_ok_end-msg_vpv21_prepare_ok,d3
        jsr     print_force
        moveq   #0,d7
        bra.s   vpv21_prepare_restore
vpv21_prepare_restore_fail:
        moveq   #1,d7
vpv21_prepare_restore:
        move.l  vpv21_saved_component,component_handle
        move.l  vpv21_saved_input,input_port_handle
        move.l  vpv21_saved_port_qidx,port_query_index
        move.l  vpv21_saved_port_buf_size,port_buf_size
        move.l  d7,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Queue the already-configured short PCM block only after the video graph and
; decoder component are active. No PORT_INFO_SET or COMPONENT_CREATE occurs here.
vpv21_queue_audio_prefix:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv38_pcm_block_count
        beq.w   vpv39_arm_fail
        tst.l   vpv21_audio_prepared
        beq.w   vpv39_arm_fail

        clr.l   vpv39_audio_next_block
        clr.l   vpv39_audio_bulk_pending
        clr.l   vpv39_audio_blocks_done
        clr.l   vpv39_audio_all_done
        clr.l   vpv39_audio_failed
        clr.l   vpv01_bulk_done
        clr.l   vpv21_audio_returned
        clr.l   vpv21_audio_dma_active
        clr.l   vpv43_sync_started
        clr.l   vpv43_last_output_frames
        clr.l   vpv43_sync_waits
        clr.l   vpv45_prefetch_ready
        clr.l   vpv45_prefetch_bytes
        clr.l   vpv45_prefetch_samples
        clr.l   vpv47_tx_slot
        clr.l   vpv47_inflight
        clr.l   vpv47_audio_lead_ticks
        clr.l   vpv47_double_first_logged
        clr.l   vpv66_audio_returns
        ; VPv135 passive audio renderer PTS/wall-clock proof.
        clr.l   vpv135_audio_started
        clr.l   vpv135_audio_returns
        clr.l   vpv135_audio_invalid
        clr.l   vpv135_audio_nonmono
        clr.l   vpv135_audio_callback_mismatch
        clr.l   vpv135_audio_first_pts
        clr.l   vpv135_audio_last_pts
        clr.l   vpv170_audio_first_return_hi
        clr.l   vpv170_audio_last_pts_hi
        clr.l   vpv135_audio_first_wall
        clr.l   vpv135_audio_last_wall
        clr.l   vpv135_audio_wall_elapsed
        clr.l   vpv135_audio_pts_elapsed
        clr.l   vpv135_audio_last_drift
        clr.l   vpv135_audio_min_drift
        clr.l   vpv135_audio_max_drift
        clr.l   vpv135_slot_pts_lo
        clr.l   vpv135_slot_pts_lo+4
        clr.l   vpv135_slot_pts_hi
        clr.l   vpv135_slot_pts_hi+4
        clr.l   vpv66_refill_wait_active
        clr.l   vpv66_refill_start_vblank
        clr.l   vpv66_refill_count
        clr.l   vpv66_refill_max_vblanks
        clr.l   vpv66_block_video_bulk
        clr.l   vpv66_block_audio_bulk
        clr.l   vpv66_block_pts_gate
        clr.l   vpv66_return_while_video_bulk
        clr.l   vpv66_empty_events
        clr.l   vpv66_empty_latched
        clr.l   vpv70_rr_turn
        clr.l   vpv70_rr_audio_wins
        clr.l   vpv70_rr_video_wins
        clr.l   vpv70_rr_audio_fallbacks
        clr.l   vpv70_rr_video_fallbacks
        clr.l   vpv72_idle_due_kicks
        clr.l   vpv72_idle_wait_polls
        clr.l   vpv72_idle_audio_publishes
        clr.l   vpv156_c_lead_entries
        clr.l   vpv157_audio_decode_safe_launches
        clr.l   vpv157_audio_decode_deferred
        clr.l   vpv157_audio_decode_forced
        clr.l   vpv157_audio_decode_calls
        clr.l   vpv157_audio_decode_total_us
        clr.l   vpv157_audio_decode_max_us
        clr.l   vpv157_audio_decode_gt20ms
        clr.l   vpv157_audio_decode_gtframe
        clr.l   vpv158_mail_pending
        clr.l   vpv158_faad_pending
        clr.l   vpv158_async_input_len
        clr.l   vpv158_async_start_us
        clr.l   vpv158_async_launches
        clr.l   vpv158_async_completions
        clr.l   vpv158_async_pending_polls
        clr.l   vpv158_async_forced_waits
        clr.l   vpv158_async_forced_wait_ticks
        clr.l   vpv158_async_failures
        clr.l   vpv75_refill_lead_uses
        clr.l   vpv76_pair_window
        clr.l   vpv76_pair_opens
        clr.l   vpv76_pair_publishes
        clr.l   vpv76_pair_misses
        clr.l   vpv76_safe_stop_eos
        clr.l   vpv78_pair_gate_bypass_uses
        clr.l   vpv78_pair_last_video
        clr.l   vpv78_pair_startup_skips
        clr.l   vpv78_pair_cooldown_skips
        clr.l   vpv78_stop_audio_wait_polls
        clr.l   vpv81_key_stop_pending
        clr.l   vpv169_sync_stop_pending
        clr.l   vpv169_sync_stop_target_pts
        clr.l   vpv170_sync_stop_target_pts_hi
        clr.l   vpv169_sync_stop_start_us
        clr.l   vpv169_video_submitted_max_pts
        clr.l   vpv170_video_submitted_max_pts_hi
        clr.l   vpv169_sync_stop_wait_polls
        clr.l   vpv169_sync_stop_timeouts
        clr.l   vpv83_poll_seq
        clr.l   vpv83_video_bulk_seq
        clr.l   vpv83_refill_poll_start
        clr.l   vpv83_refill_video_seq_start
        clr.l   vpv83_refill_poll_total
        clr.l   vpv83_refill_poll_max
        clr.l   vpv83_refill_after_video_done
        clr.l   vpv83_refill_video_delta_max
        clr.l   vpv83_postvideo_ticket
        clr.l   vpv83_postvideo_tickets
        clr.l   vpv83_postvideo_publishes
        clr.l   vpv83_postvideo_misses
        clr.l   vpv84_prevideo_checks
        clr.l   vpv84_prevideo_publishes
        clr.l   vpv84_prevideo_no_publish
        clr.l   vpv85_prevideo_window
        clr.l   vpv85_prevideo_gate_bypass_uses
        clr.l   vpv99_c_pts_clock_uses
        lea     vpv47_slot_len,a0
        moveq   #((VPV47_AUDIO_SLOTS*6)-1),d0
vpv47_clear_slot_state:
        clr.l   (a0)+
        dbra    d0,vpv47_clear_slot_state
        clr.l   vpv53_stage_offset
        move.l  vpv38_pcm_store_total,d0
        move.l  d0,vpv53_stage_total
        clr.l   vpv53_chunk_count
        clr.l   vpv53_batch_adopts
        move.l  #1,vpv39_audio_armed

        lea     msg_vpv21_queue_begin,a1
        move.l  #msg_vpv21_queue_begin_end-msg_vpv21_queue_begin,d3
        jsr     print_force
        lea     msg_vpv43_sync_values,a1
        move.l  #msg_vpv43_sync_values_end-msg_vpv43_sync_values,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  v10_first_pts_ticks,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv43_first_audio_pts_ticks,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv43_video_frame_ticks,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv43_pts_mode,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        moveq   #0,d0
        bra.s   vpv39_arm_done
vpv39_arm_fail:
        clr.l   vpv39_audio_armed
        move.l  #1,vpv39_audio_failed
        lea     msg_vpv21_queue_fail,a1
        move.l  #msg_vpv21_queue_fail_end-msg_vpv21_queue_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv39_arm_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


; Advance the next audio media PTS by the exact decoded sample count of the
; buffer that just completed.  With 1-ms Matroska ticks this is:
;   delta_ticks = (samples * 1000 + remainder) / sample_rate
; The remainder is carried forever, so a two-hour movie does not accumulate
; integer-rounding drift from this scheduler.
vpv43_advance_audio_pts:
        movem.l d0-d4,-(sp)
        tst.l   vpv43_pts_mode
        beq.s   vpv43_advance_done
vpv43_advance_mkv:
        move.l  vpv43_last_sent_samples,d0
        beq.s   vpv43_advance_done
        mulu.w  #1000,d0
        add.l   vpv43_audio_pts_remainder,d0
        move.l  v19_pcm_rate,d1
        tst.l   d1
        beq.s   vpv43_advance_disable
        jsr     v10_udiv32
        add.l   d0,vpv43_audio_next_pts_ticks
        move.l  d1,vpv43_audio_pts_remainder
        bra.s   vpv43_advance_done
vpv43_advance_disable:
        clr.l   vpv43_pts_mode
vpv43_advance_done:
        movem.l (sp)+,d0-d4
        rts

; Update a displayed-video media timeline and decide whether the next PCM block
; is due.  Unlike VPv42, audio is no longer sent simply because VCHIQ is idle.
; The first audio block waits until the first decoded frame has actually reached
; the P96 output.  Thereafter the timeline advances from container PTS base +
; DefaultDuration ticks.  Return D0=0 send allowed, D0=1 wait.
vpv43_audio_pts_gate:
        movem.l d1-d7,-(sp)
        tst.l   vpv43_pts_mode
        beq.w   vpv43_gate_allow
        ; VPv102: legacy single-buffer gate remains exactly on the proven
        ; host-output clock. The active VPv47 double-buffer service below owns
        ; the dedicated C-mode HVS clock; do not widen the experiment here.
        move.l  output_frame_total,d6
        tst.l   d6
        beq.w   vpv43_gate_wait

        tst.l   vpv43_sync_started
        bne.s   vpv43_gate_update
        move.l  v10_first_pts_ticks,d0
        move.l  d0,vpv43_display_pts_ticks
        clr.l   vpv43_last_output_frames
        move.l  #1,vpv43_sync_started

vpv43_gate_update:
        move.l  vpv43_last_output_frames,d5
vpv43_gate_update_loop:
        cmp.l   d6,d5
        bcc.s   vpv43_gate_compare
        tst.l   d5
        beq.s   vpv43_gate_first_frame
        move.l  vpv43_video_frame_ticks,d0
        add.l   d0,vpv43_display_pts_ticks
vpv43_gate_first_frame:
        addq.l  #1,d5
        bra.s   vpv43_gate_update_loop
vpv43_gate_compare:
        move.l  d5,vpv43_last_output_frames
        move.l  vpv43_audio_next_pts_ticks,d0
        move.l  vpv43_display_pts_ticks,d1
        cmp.l   d1,d0
        bhi.s   vpv43_gate_wait
vpv43_gate_allow:
        moveq   #0,d0
        bra.s   vpv43_gate_done
vpv43_gate_wait:
        addq.l  #1,vpv43_sync_waits
        moveq   #1,d0
vpv43_gate_done:
        movem.l (sp)+,d1-d7
        rts


; VPv47 live A/V scheduler. Called only while shared VCHIQ RAM is CPU-owned.
; It never waits synchronously: video/MMAL callbacks continue through h19_poll.
; D0=1 means an AUDIO BULK_TX was just published, so the caller must not
; publish a video BULK_TX in the same cycle. D0=0 means video may continue.
; VPv47 true double-buffer audio scheduler. VCHIQ BULK_TX remains globally
; serialized, but two independent PCM DMA/MMAL buffers are allowed to remain
; renderer-owned. Once BULK_TX for slot N completes, slot N+1 can be queued
; without waiting for BUFFER_TO_HOST of N. This removes the renderer-empty gap.
;
; D0=1 only when an AUDIO BULK_TX was published in this call.
vpv47_audio_service:
        movem.l d1-d7/a0-a3/a6,-(sp)
        moveq   #0,d7
        tst.l   vpv39_audio_armed
        beq.w   vpv47_service_done
        tst.l   vpv39_audio_failed
        bne.w   vpv47_service_done

        ; Reclaim any slot whose BULK and exact MMAL return are both complete.
        moveq   #0,d6
vpv47_reap_loop:
        cmpi.l  #VPV47_AUDIO_SLOTS,d6
        bcc.w   vpv47_reap_done
        move.l  d6,d5
        lsl.l   #2,d5
        lea     vpv47_slot_state,a0
        adda.l  d5,a0
        tst.l   (a0)
        beq.s   vpv47_reap_next
        lea     vpv47_slot_bulk_done,a1
        adda.l  d5,a1
        tst.l   (a1)
        beq.s   vpv47_reap_next
        lea     vpv47_slot_returned,a1
        adda.l  d5,a1
        tst.l   (a1)
        beq.s   vpv47_reap_next

        ; CachePostDMA exact slot span only after both ownership signals.
        tst.l   d6
        bne.s   vpv47_reap_slot1
        move.l  vpv21_pcm_ptr,a0
        bra.s   vpv47_reap_have_ptr
vpv47_reap_slot1:
        move.l  vpv47_pcm1_ptr,a0
vpv47_reap_have_ptr:
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)

        move.l  d6,d5
        lsl.l   #2,d5
        lea     vpv47_slot_state,a0
        adda.l  d5,a0
        clr.l   (a0)
        lea     vpv47_slot_bulk_done,a0
        adda.l  d5,a0
        clr.l   (a0)
        lea     vpv47_slot_returned,a0
        adda.l  d5,a0
        clr.l   (a0)
        lea     vpv47_slot_dma_active,a0
        adda.l  d5,a0
        clr.l   (a0)
        subq.l  #1,vpv47_inflight
        addq.l  #1,vpv39_audio_blocks_done
vpv47_reap_next:
        addq.l  #1,d6
        bra.w   vpv47_reap_loop
vpv47_reap_done:
        ; VPv66 diagnostic only: count transitions to zero renderer-owned slots.
        tst.l   vpv39_audio_armed
        beq.s   vpv66_reap_diag_done
        tst.l   vpv41_audio_eof
        bne.s   vpv66_reap_diag_done
        tst.l   v15_stop_requested
        bne.s   vpv66_reap_diag_done
        tst.l   vpv47_inflight
        bne.s   vpv66_reap_nonempty
        tst.l   vpv66_audio_returns
        beq.s   vpv66_reap_diag_done
        tst.l   vpv66_empty_latched
        bne.s   vpv66_reap_diag_done
        move.l  #1,vpv66_empty_latched
        addq.l  #1,vpv66_empty_events
        bra.s   vpv66_reap_diag_done
vpv66_reap_nonempty:
        clr.l   vpv66_empty_latched
vpv66_reap_diag_done:
        ; VPv102: during a requested stop the audio service is truly
        ; housekeeping-only. Reaping above is allowed, but do not launch a
        ; new CPU1 FAAD prefetch/decode after the stop latch is set.
        tst.l   v15_stop_requested
        bne.w   vpv47_service_done

        ; SPACE-PAUSE: reaping above stays active, but no new PCM is decoded
        ; or published while paused.
        tst.l   vpx_pause_active
        bne.w   vpv47_service_done

        ; mkvr7 LIVE-C QUIET WINDOW: while a display graph switch is
        ; active, this service may REAP already returned renderer slots above,
        ; but it must never prefetch/decode/publish a fresh PCM buffer.  The
        ; resize service explicitly calls us until vpv47_inflight reaches zero.
        ; This creates a callback-quiet MMAL control window before GET/SET/CONNECT.
        tst.l   v40_resize_state
        bne.w   vpv47_service_done

        ; mkvr7 T:/restart rule: the AAC reader/FAAD priming already
        ; starts at the requested media position. While video is still doing
        ; its hidden catch-up, do NOT submit that target PCM to audio_render.
        ; This keeps HDMI silent instead of playing from 0:00 / running ahead
        ; in wall-clock time. As soon as video clears v32r_fastforward, the
        ; unchanged scheduler publishes the already-prepared target PCM.
        tst.l   v32r_fastforward
        bne.w   vpv47_service_done

        ; VPv158: first harvest an outstanding CPU1 decode without waiting.
        ; A completed batch is published through the unchanged vpv45_prefetch_*
        ; interface; a not-yet-complete batch costs only one bounded mailbox poll.
        tst.l   vpv158_faad_pending
        beq.s   vpv158_no_async_poll
        bsr     vpv158_faad_async_poll
        cmpi.l  #2,d0
        beq.w   vpv47_service_fail
vpv158_no_async_poll:

        ; Prefetch may overwrite vpv38_pcm_store ONLY after the current staged
        ; batch has been copied into DMA slots.  Start CPU1 only in the proven
        ; >=30-ms safe window, but do not wait for it here.
        move.l  vpv53_stage_offset,d0
        cmp.l   vpv53_stage_total,d0
        bcs.s   vpv47_prefetch_done
        tst.l   vpv45_prefetch_ready
        bne.s   vpv47_prefetch_done
        tst.l   vpv41_decoder_live
        beq.s   vpv47_prefetch_done
        tst.l   vpv158_faad_pending
        bne.s   vpv47_prefetch_done
        bsr     vpv157_audio_decode_safe_now
        tst.l   d0
        beq.s   vpv157_audio_decode_defer
        addq.l  #1,vpv157_audio_decode_safe_launches
        bsr     vpv158_faad_async_launch
        cmpi.l  #2,d0
        beq.w   vpv47_service_fail
        bra.s   vpv47_prefetch_done
vpv157_audio_decode_defer:
        addq.l  #1,vpv157_audio_decode_deferred
vpv47_prefetch_done:

        ; Completion is only final after AAC EOF, all staged PCM bytes were
        ; copied to DMA slots, and both renderer slots have returned.
        tst.l   vpv41_decoder_live
        bne.s   vpv47_maybe_send
        tst.l   vpv41_audio_eof
        beq.s   vpv47_maybe_send
        tst.l   vpv45_prefetch_ready
        bne.s   vpv47_maybe_send
        move.l  vpv53_stage_offset,d0
        cmp.l   vpv53_stage_total,d0
        bcs.s   vpv47_maybe_send
        tst.l   vpv47_inflight
        bne.s   vpv47_maybe_send
        tst.l   vpv39_audio_bulk_pending
        bne.s   vpv47_maybe_send
        move.l  #1,vpv39_audio_all_done
        clr.l   vpv39_audio_armed
        lea     msg_vpv39_live_done,a1
        move.l  #msg_vpv39_live_done_end-msg_vpv39_live_done,d3
        jsr     vpv21n_trace
        bra.w   vpv47_service_done

vpv47_maybe_send:
        tst.l   v15_stop_requested
        bne.w   vpv47_service_done
        tst.l   input_eof_seen
        beq.s   vpv168_audio_video_eof_ok
        ; VPv168: in TRUE C feed-ahead, VIDEO input EOF is allowed to precede
        ; AAC EOF.  Keep publishing PCM; PTS and Audio-Masterclock are unchanged.
        tst.l   vpv166_c_sched_feedahead
        beq.w   vpv47_service_done
vpv168_audio_video_eof_ok:
        tst.l   input_bulk_pending
        beq.s   vpv66_no_video_bulk_block
        tst.l   vpv66_refill_wait_active
        beq.w   vpv47_service_done
        addq.l  #1,vpv66_block_video_bulk
        bra.w   vpv47_service_done
vpv66_no_video_bulk_block:
        tst.l   vpv39_audio_bulk_pending
        beq.s   vpv66_no_audio_bulk_block
        tst.l   vpv66_refill_wait_active
        beq.w   vpv47_service_done
        addq.l  #1,vpv66_block_audio_bulk
        bra.w   vpv47_service_done
vpv66_no_audio_bulk_block:

        ; Find a free DMA/MMAL audio slot.
        moveq   #-1,d6
        tst.l   vpv47_slot_state
        beq.s   vpv47_free_slot0
        tst.l   vpv47_slot_state+4
        bne.w   vpv47_service_done
        moveq   #1,d6
        bra.s   vpv47_have_free_slot
vpv47_free_slot0:
        moveq   #0,d6
vpv47_have_free_slot:

        ; PTS gate. First buffer starts exactly on the visible-video timeline.
        ; Once one buffer is resident, allow the next buffer up to one current
        ; PCM-block duration early so audio_render can keep a continuous queue.
        jsr     vpv47_audio_pts_gate
        tst.l   d0
        beq.s   vpv66_pts_gate_allowed
        tst.l   vpv66_refill_wait_active
        beq.w   vpv47_service_done
        addq.l  #1,vpv66_block_pts_gate
        bra.w   vpv47_service_done
vpv66_pts_gate_allowed:

        ; VPv66: the current 64-KiB FAAD batch is consumed as one 64-KiB chunk.
        ; If it is exhausted, atomically adopt the already-prefetched next batch
        ; (or decode it now as a measurable fallback) before loading a slot.
        move.l  vpv53_stage_offset,d0
        cmp.l   vpv53_stage_total,d0
        bcs.s   vpv53_have_stage_pcm
        tst.l   vpv45_prefetch_ready
        bne.s   vpv53_adopt_prefetch
        tst.l   vpv41_decoder_live
        beq.w   vpv47_service_done

        ; VPv158: never synchronously wait for CPU1 while at least one old
        ; 64-KiB renderer buffer still protects audio.  If no request is in
        ; flight, launch one (subject to the same 30-ms safe window) and return
        ; to the dispatcher.  Only true zero-inflight starvation may force a
        ; blocking emergency wait.
        tst.l   vpv158_faad_pending
        bne.s   vpv158_forced_have_request
        bsr     vpv157_audio_decode_safe_now
        tst.l   d0
        beq.s   vpv158_forced_not_safe
        addq.l  #1,vpv157_audio_decode_safe_launches
        bsr     vpv158_faad_async_launch
        cmpi.l  #2,d0
        beq.w   vpv47_service_fail
        bra.s   vpv158_forced_have_request
vpv158_forced_not_safe:
        addq.l  #1,vpv157_audio_decode_deferred
        tst.l   vpv47_inflight
        bne.w   vpv47_service_done
        ; No renderer-owned reserve remains: launch now despite the video
        ; window, then use the explicit emergency wait below.
        bsr     vpv158_faad_async_launch
        cmpi.l  #2,d0
        beq.w   vpv47_service_fail
vpv158_forced_have_request:
        tst.l   vpv45_prefetch_ready
        bne.s   vpv53_adopt_prefetch
        tst.l   vpv47_inflight
        bne.w   vpv47_service_done
        addq.l  #1,vpv45_prefetch_miss_count
        addq.l  #1,vpv157_audio_decode_forced
        bsr     vpv158_faad_async_force_wait
        tst.l   d0
        bne.w   vpv47_service_fail
        tst.l   vpv45_prefetch_ready
        beq.w   vpv47_service_done
vpv53_adopt_prefetch:
        move.l  vpv45_prefetch_bytes,d0
        tst.l   d0
        beq.w   vpv47_service_fail
        move.l  d0,vpv53_stage_total
        clr.l   vpv53_stage_offset
        clr.l   vpv45_prefetch_ready
        clr.l   vpv45_prefetch_bytes
        clr.l   vpv45_prefetch_samples
        addq.l  #1,vpv53_batch_adopts
vpv53_have_stage_pcm:
        move.l  d6,d0
        jsr     vpv53_load_chunk_to_slot
        tst.l   d0
        bne.w   vpv47_service_fail
vpv47_source_ready:

        move.l  d6,d0
        jsr     vpv47_send_audio_slot
        tst.l   d0
        bne.w   vpv47_service_fail
        ; VPv66 diagnostic only: renderer-return -> next publish latency in VBlank ticks.
        tst.l   vpv66_refill_wait_active
        beq.s   vpv66_refill_diag_done
        move.l  t31s_vblank_counter,d0
        sub.l   vpv66_refill_start_vblank,d0
        addq.l  #1,vpv66_refill_count
        cmp.l   vpv66_refill_max_vblanks,d0
        bls.s   vpv66_refill_no_new_max
        move.l  d0,vpv66_refill_max_vblanks
vpv66_refill_no_new_max:
        ; VPv83 measurement only: tight poll passes and completed VIDEO BULKs
        ; between renderer return and the next Audio submit.
        move.l  vpv83_poll_seq,d1
        sub.l   vpv83_refill_poll_start,d1
        add.l   d1,vpv83_refill_poll_total
        cmp.l   vpv83_refill_poll_max,d1
        bls.s   vpv83_poll_max_done
        move.l  d1,vpv83_refill_poll_max
vpv83_poll_max_done:
        move.l  vpv83_video_bulk_seq,d2
        sub.l   vpv83_refill_video_seq_start,d2
        tst.l   d2
        beq.s   vpv83_video_delta_done
        addq.l  #1,vpv83_refill_after_video_done
        cmp.l   vpv83_refill_video_delta_max,d2
        bls.s   vpv83_video_delta_done
        move.l  d2,vpv83_refill_video_delta_max
vpv83_video_delta_done:
        clr.l   vpv66_refill_wait_active
vpv66_refill_diag_done:
        clr.l   vpv66_empty_latched
        addq.l  #1,vpv39_audio_next_block
        addq.l  #1,vpv53_chunk_count
        addq.l  #1,vpv47_inflight

        ; Advance the media PTS at publish time, not return time: slot N+1 can
        ; now be queued while slot N remains renderer-owned.
        move.l  d6,d5
        lsl.l   #2,d5
        lea     vpv47_slot_samples,a0
        adda.l  d5,a0
        move.l  (a0),vpv43_last_sent_samples
        jsr     vpv47_set_lead_from_samples
        jsr     vpv43_advance_audio_pts

        ; One breadcrumb when the renderer first holds two distinct buffers.
        cmpi.l  #2,vpv47_inflight
        bcs.s   vpv47_no_double_log
        tst.l   vpv47_double_first_logged
        bne.s   vpv47_no_double_log
        move.l  #1,vpv47_double_first_logged
        lea     msg_vpv47_double_ok,a1
        move.l  #msg_vpv47_double_ok_end-msg_vpv47_double_ok,d3
        jsr     vpv21n_trace
vpv47_no_double_log:
        moveq   #1,d7
        bra.s   vpv47_service_done

vpv47_service_fail:
        move.l  #1,vpv39_audio_failed
        clr.l   vpv39_audio_armed
        lea     msg_vpv39_live_fail,a1
        move.l  #msg_vpv39_live_fail_end-msg_vpv39_live_fail,d3
        jsr     vpv21n_trace
vpv47_service_done:
        move.l  d7,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Same visible-video PTS clock as VPv43, but when one audio buffer is already
; queued allow the NEXT PTS one block-duration ahead. This is bounded lead, not
; free-running audio; it exists solely to keep audio_render non-empty.
vpv47_audio_pts_gate:
        movem.l d1-d7,-(sp)
        ; VPv102: preventive Slot-2 bypass.  This can exist only during the
        ; one PREVIDEO guard call.  Exactly one older renderer-owned slot
        ; must still exist, therefore total Audio occupancy remains capped
        ; by the existing two 64-KiB slots.  No loop and no free-run.
        tst.l   vpv85_prevideo_window
        beq.s   vpv85_gate_check_pair
        cmpi.l  #1,vpv47_inflight
        bne.s   vpv85_gate_check_pair
        addq.l  #1,vpv85_prevideo_gate_bypass_uses
        bra.w   vpv47_gate_allow
vpv85_gate_check_pair:
        ; VPv83: bounded Slot-2 bypass only in the exact pair window.
        ; Exactly one older slot must still be renderer-owned, so audio can
        ; never exceed the existing two 64-KiB MMAL buffers.
        cmpi.l  #2,vpv76_pair_window
        bne.s   vpv78_gate_normal
        cmpi.l  #1,vpv47_inflight
        bne.s   vpv78_gate_normal
        addq.l  #1,vpv78_pair_gate_bypass_uses
        bra.w   vpv47_gate_allow
vpv78_gate_normal:
        ; mkvr7 FAST-C START:
        ; VPv174's scheduler/audio-master rule also applies to MKV fast C.
        ; The old MKV direct-C gate waits for v04_paced_frames, but fast C
        ; intentionally bypasses that host pacer. Waiting there deadlocks:
        ; video_scheduler waits for Audio-Master, while audio waits for a
        ; paced video frame that can never occur.
        ;
        ; When MKV fast-C and the scheduler data graph are active, audio is
        ; the master: publish PCM immediately.
        ; The existing two 64-KiB renderer slots remain the hard bounded lead.
        tst.l   vpv179_mkv_c_fast_active
        beq.s   vpv180_mkv_fast_gate_not_active
        tst.l   vpv126_data_graph_ok
        beq.s   vpv180_mkv_fast_gate_not_active
        addq.l  #1,vpv129_audio_master_gate_uses
        moveq   #0,d0
        bra.w   vpv47_gate_done
vpv180_mkv_fast_gate_not_active:
        tst.l   vpv43_pts_mode
        beq.w   vpv47_gate_allow
        ; VPv102 C-AUDIO FIX: direct video_render/HVS mode deliberately owns
        ; no P96/host output pool, therefore output_frame_total can never start
        ; the audio PTS clock.  Use v04_paced_frames only in mode 3; this is the
        ; native-fps FRAME_START counter advanced by the 1-MHz v41e_hr_pace_new_frame.
        ; 25/50/75 continue to use the hardware-proven P96 output counter.
        cmpi.l  #3,v41_display_style
        bne.s   vpv99_v47_host_clock
        move.l  v04_paced_frames,d6
        addq.l  #1,vpv99_c_pts_clock_uses
        bra.s   vpv99_v47_clock_ready
vpv99_v47_host_clock:
        move.l  output_frame_total,d6
vpv99_v47_clock_ready:
        tst.l   d6
        beq.w   vpv47_gate_wait
        tst.l   vpv43_sync_started
        beq.s   v005r4_gate_need_start

        ; R5 T:/P96: after startup, follow the exact propagated video PTS.
        tst.l   v40j_time_seek_active
        beq.s   vpv47_gate_update
        cmpi.l  #3,v41_display_style
        beq.s   vpv47_gate_update
        tst.l   v40j_time_latest_video_valid
        beq.s   vpv47_gate_update
        move.l  v40j_time_latest_video_ticks,vpv43_display_pts_ticks
        move.l  d6,vpv43_last_output_frames
        bra.s   vpv47_gate_compare

v005r4_gate_need_start:
        ; R5 T: all hidden frames belong to the discarded pre-roll epoch.
        ; Begin A/V gating directly at the common target and mark the current
        ; visible frame counter as already accounted for.
        tst.l   v40j_time_seek_active
        beq.s   v005r4_gate_normal_base
        tst.l   v32r_resume_reached
        beq.w   vpv47_gate_wait
        move.l  v40j_time_video_start_ticks,vpv43_display_pts_ticks
        move.l  d6,vpv43_last_output_frames
        move.l  #1,vpv43_sync_started
        bra.s   vpv47_gate_compare

v005r4_gate_normal_base:
        move.l  v10_first_pts_ticks,vpv43_display_pts_ticks
        clr.l   vpv43_last_output_frames
        move.l  #1,vpv43_sync_started
vpv47_gate_update:
        move.l  vpv43_last_output_frames,d5
vpv47_gate_loop:
        cmp.l   d6,d5
        bcc.s   vpv47_gate_compare
        tst.l   d5
        beq.s   vpv47_gate_first
        move.l  vpv43_video_frame_ticks,d0
        add.l   d0,vpv43_display_pts_ticks
vpv47_gate_first:
        addq.l  #1,d5
        bra.s   vpv47_gate_loop
vpv47_gate_compare:
        move.l  d5,vpv43_last_output_frames
        move.l  vpv43_display_pts_ticks,d1
        ; VPv83: VPv74 proved that the old lead window never fired because
        ; every renderer return was reaped down to inflight=0 before the next
        ; refill attempt.  A real pending renderer-return refill is therefore
        ; allowed to use the SAME bounded one-block lead as an already-inflight
        ; second slot.  Startup/first-buffer still has no lead and remains tied
        ; to the visible video PTS.  This changes timing only, not arbitration.
        move.l  d1,d3                  ; visible-video PTS without lead
        tst.l   vpv47_inflight
        bne.s   vpv75_gate_apply_lead
        tst.l   vpv66_refill_wait_active
        beq.s   vpv47_gate_no_lead
vpv75_gate_apply_lead:
        add.l   vpv47_audio_lead_ticks,d1
        move.l  vpv43_audio_next_pts_ticks,d2
        cmp.l   d3,d2
        bls.s   vpv47_gate_no_lead     ; lead was not actually needed
        cmp.l   d1,d2
        bhi.s   vpv47_gate_wait
        tst.l   vpv66_refill_wait_active
        beq.s   vpv47_gate_no_lead
        addq.l  #1,vpv75_refill_lead_uses
vpv47_gate_no_lead:
        move.l  vpv43_audio_next_pts_ticks,d0
        cmp.l   d1,d0
        bhi.s   vpv47_gate_wait
vpv47_gate_allow:
        moveq   #0,d0
        bra.s   vpv47_gate_done
vpv47_gate_wait:
        addq.l  #1,vpv43_sync_waits
        moveq   #1,d0
vpv47_gate_done:
        movem.l (sp)+,d1-d7
        rts

; Compute one-buffer lead in 1-ms Matroska ticks without touching the carried
; PTS remainder used by the exact long-term clock.
vpv47_set_lead_from_samples:
        movem.l d0-d3,-(sp)
        move.l  vpv43_last_sent_samples,d0
vpv103_lead_mkv:
        move.l  vpv43_last_sent_samples,d0
        mulu.w  #1000,d0
        move.l  v19_pcm_rate,d1
        tst.l   d1
        beq.s   vpv47_lead_zero
        jsr     v10_udiv32
        move.l  d0,vpv47_audio_lead_ticks
        bra.s   vpv47_lead_done
vpv47_lead_zero:
        clr.l   vpv47_audio_lead_ticks
vpv47_lead_done:
        movem.l (sp)+,d0-d3
        rts

; VPv66: D0=slot. Copy the next <=64-KiB chunk from the current FAAD batch
; in vpv38_pcm_store into one of the two proven DMA slots.  Advance the staging
; cursor only after the copy and pagelist are complete.  Return D0=0/1.
vpv53_load_chunk_to_slot:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,d7
        cmpi.l  #VPV47_AUDIO_SLOTS,d7
        bcc.w   vpv53_load_fail
        move.l  vpv53_stage_total,d4
        move.l  vpv53_stage_offset,d3
        cmp.l   d4,d3
        bcc.w   vpv53_load_fail
        sub.l   d3,d4                  ; remaining bytes
        move.l  #VPV53_AUDIO_CHUNK_BYTES,d5
        cmp.l   d5,d4
        bcc.s   vpv53_chunk_len_ok
        move.l  d4,d5
vpv53_chunk_len_ok:
        tst.l   d5
        beq.w   vpv53_load_fail
        ; PCM16 stereo chunks must end on the decoder block-alignment.
        move.l  v19_pcm_blockalign,d2
        tst.l   d2
        beq.w   vpv53_load_fail
        move.l  d5,d0
        move.l  d2,d1
        jsr     v10_udiv32
        tst.l   d1                     ; remainder must be zero
        bne.w   vpv53_load_fail
        move.l  d0,d6                  ; samples/channel in this chunk

        lea     vpv38_pcm_store,a1
        adda.l  d3,a1
        tst.l   d7
        bne.s   vpv53_load_slot1
        move.l  vpv21_pcm_ptr,a0
        move.l  vpv21_pcm_bus,d3
        move.l  vpv21_pcm_pagelist_ptr,a2
        bra.s   vpv53_load_have_slot
vpv53_load_slot1:
        move.l  vpv47_pcm1_ptr,a0
        move.l  vpv47_pcm1_bus,d3
        move.l  vpv47_pcm1_pagelist_ptr,a2
vpv53_load_have_slot:
        move.l  d5,d1
vpv53_load_copy:
        move.b  (a1)+,(a0)+
        subq.l  #1,d1
        bne.s   vpv53_load_copy

        move.l  a2,a0
        move.l  d5,d0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  d5,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        and.l   #$00000fff,d0
        and.l   #$fffff000,d3
        or.l    d0,d3
        lea     8(a0),a0
        move.l  d3,d0
        jsr     v94_pl_store             ; v96.94: CM4 = 36-bit pagelist

        move.l  d7,d0
        lsl.l   #2,d0
        lea     vpv47_slot_len,a0
        adda.l  d0,a0
        move.l  d5,(a0)
        lea     vpv47_slot_samples,a0
        adda.l  d0,a0
        move.l  d6,(a0)
        add.l   d5,vpv53_stage_offset
        moveq   #0,d0
        bra.s   vpv53_load_done
vpv53_load_fail:
        moveq   #1,d0
vpv53_load_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; D0=slot. Copy the priming PCM into that slot, rebuild its pagelist and record
; exact length/sample count.
vpv47_load_priming_to_slot:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,d7
        cmpi.l  #VPV47_AUDIO_SLOTS,d7
        bcc.w   vpv47_load_fail
        lea     vpv38_pcm_block_sizes,a2
        move.l  (a2),d5
        tst.l   d5
        beq.w   vpv47_load_fail
        lea     vpv38_pcm_store,a1
        bra.s   vpv47_load_common

; D0=slot. Consume the one CPU-side prefetched PCM block into that DMA slot.
vpv47_load_prefetch_to_slot:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,d7
        cmpi.l  #VPV47_AUDIO_SLOTS,d7
        bcc.w   vpv47_load_fail
        tst.l   vpv45_prefetch_ready
        beq.w   vpv47_load_fail
        move.l  vpv45_prefetch_bytes,d5
        tst.l   d5
        beq.w   vpv47_load_fail
        lea     vpv38_pcm_store,a1

vpv47_load_common:
        cmpi.l  #VPV21_PCM_MAX_BYTES,d5
        bhi.w   vpv47_load_fail
        tst.l   d7
        bne.s   vpv47_load_slot1
        move.l  vpv21_pcm_ptr,a0
        move.l  vpv21_pcm_bus,d3
        move.l  vpv21_pcm_pagelist_ptr,a2
        bra.s   vpv47_load_have_slot
vpv47_load_slot1:
        move.l  vpv47_pcm1_ptr,a0
        move.l  vpv47_pcm1_bus,d3
        move.l  vpv47_pcm1_pagelist_ptr,a2
vpv47_load_have_slot:
        move.l  d5,d1
        tst.l   m1_mute                   ; v96.87: muted -> silence
        bne.s   m1_load_zero
vpv47_load_copy:
        move.b  (a1)+,(a0)+
        subq.l  #1,d1
        bne.s   vpv47_load_copy
        bra.s   m1_load_done
m1_load_zero:
        clr.b   (a0)+
        subq.l  #1,d1
        bne.s   m1_load_zero
m1_load_done:

        move.l  a2,a0
        move.l  d5,d0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  d5,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        and.l   #$00000fff,d0
        and.l   #$fffff000,d3
        or.l    d0,d3
        lea     8(a0),a0
        move.l  d3,d0
        jsr     v94_pl_store             ; v96.94: CM4 = 36-bit pagelist

        move.l  d7,d0
        lsl.l   #2,d0
        lea     vpv47_slot_len,a0
        adda.l  d0,a0
        move.l  d5,(a0)
        move.l  d5,d1
        move.l  v19_pcm_blockalign,d2
        tst.l   d2
        beq.s   vpv47_load_fail
        move.l  d1,d0
        move.l  d2,d1
        jsr     v10_udiv32
        move.l  d7,d1
        lsl.l   #2,d1
        lea     vpv47_slot_samples,a0
        adda.l  d1,a0
        move.l  d0,(a0)

        ; Prefetch source is consumed after successful copy. Priming source is
        ; left intact but will only be selected while next_block==0.
        move.l  vpv39_audio_next_block,d0
        cmp.l   vpv38_pcm_block_count,d0
        bcs.s   vpv47_load_ok
        clr.l   vpv45_prefetch_ready
        clr.l   vpv45_prefetch_bytes
        clr.l   vpv45_prefetch_samples
vpv47_load_ok:
        moveq   #0,d0
        bra.s   vpv47_load_done
vpv47_load_fail:
        moveq   #1,d0
vpv47_load_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; D0=slot. Publish one independent MMAL audio buffer + serialized VCHIQ BULK_TX.
vpv47_send_audio_slot:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  d0,d7
        cmpi.l  #VPV47_AUDIO_SLOTS,d7
        bcc.w   vpv47_send_fail
        move.l  d7,d6
        lsl.l   #2,d6
        lea     vpv47_slot_len,a0
        adda.l  d6,a0
        move.l  (a0),d5
        tst.l   d5
        beq.w   vpv47_send_fail

        tst.l   d7
        bne.s   vpv47_send_slot1
        move.l  vpv21_pcm_ptr,a3
        move.l  vpv21_pcm_pagelist_bus,d4
        bra.s   vpv47_send_have_ptr
vpv47_send_slot1:
        move.l  vpv47_pcm1_ptr,a3
        move.l  vpv47_pcm1_pagelist_bus,d4
vpv47_send_have_ptr:
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  a3,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        cmp.l   a3,d0
        bne.w   vpv47_send_fail
        move.l  d7,d0
        lsl.l   #2,d0
        lea     vpv47_slot_dma_active,a0
        adda.l  d0,a0
        move.l  #1,(a0)

        move.l  #320,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv47_send_fail
        move.l  a2,a0
        moveq   #79,d3
vpv47_send_clear:
        clr.l   (a0)+
        dbra    d3,vpv47_send_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #292,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_BUFFER_FROM_HOST,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #VPV47_AUDIO_CONTEXT_BASE,d0
        add.l   d7,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv01_audio_handle,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  vpv01_audio_input,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #VPV47_AUDIO_CONTEXT_BASE,d0
        add.l   d7,d0
        jsr     store_le32
        lea     76(a2),a0
        move.l  a3,d0
        jsr     store_le32
        lea     80(a2),a0
        move.l  vpv21_audio_port_buf_size,d0
        jsr     store_le32
        lea     84(a2),a0
        move.l  d5,d0
        jsr     store_le32
        ; mkvr7: MMAL timestamps are ALWAYS microseconds.
        ; The legacy MKV scheduler/gate intentionally keeps its internal
        ; timeline in 1-ms Matroska ticks (vpv43_pts_mode=1), but older MKV
        ; builds copied those millisecond tick values directly into the MMAL
        ; PTS/DTS fields.  audio_render therefore saw e.g. 371 us instead of
        ; 371000 us between 64-KiB PCM chunks and drained its queue almost
        ; immediately, producing the audible chopped/stuttering playback.
        ; Convert only at the MMAL publication boundary; all proven MKV gate,
        ; demux and exact rational sample-count accumulation stay unchanged.
        move.l  vpv43_audio_next_pts_ticks,d2 ; default/native low word
        move.l  vpv170_audio_next_pts_hi,d3   ; default/native high word
        cmpi.l  #1,vpv43_pts_mode
        bne.s   vpv177_audio_submit_pts_ready
        move.l  vpv43_audio_next_pts_ticks,d0 ; milliseconds
        move.l  #1000,d1                      ; ticks per second
        jsr     vpv170_ticks_to_us64          ; D1:D0 = microseconds
        tst.l   d3
        bne.w   vpv47_send_fail
        move.l  d0,d2
        move.l  d1,d3
vpv177_audio_submit_pts_ready:

        ; Bind the exact MMAL-submitted PTS to the renderer slot.
        ; FAST13: exact same 10-byte diagnostic hook footprint as FAST12.
        bsr.w   fast13_h0_trampoline
        nop
        nop
        nop
        adda.l  d0,a0
        move.l  d2,(a0)
        lea     vpv135_slot_pts_hi,a0
        adda.l  d0,a0
        move.l  d3,(a0)

        lea     96(a2),a0
        move.l  d2,d0
        jsr     store_le32
        lea     100(a2),a0
        move.l  d3,d0
        jsr     store_le32
        ; PCM decode order equals presentation order, so DTS equals PTS.
        lea     104(a2),a0
        move.l  d2,d0
        jsr     store_le32
        lea     108(a2),a0
        move.l  d3,d0
        jsr     store_le32

        lea     304(a2),a0
        move.l  #VCHIQ_MSG_BULK_TX,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     308(a2),a0
        move.l  #8,d0
        jsr     store_le32
        lea     312(a2),a0
        move.l  d4,d0
        jsr     store_le32
        lea     316(a2),a0
        move.l  d5,d0
        jsr     store_le32

        add.l   #320,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d3
        jsr     dma_pre_all
        tst.l   d3
        beq.s   vpv47_send_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv47_send_no_bell:
        move.l  d7,vpv47_tx_slot
        move.l  #1,vpv39_audio_bulk_pending
        move.l  d7,d0
        lsl.l   #2,d0
        lea     vpv47_slot_state,a0
        adda.l  d0,a0
        move.l  #1,(a0)
        lea     vpv47_slot_bulk_done,a0
        adda.l  d0,a0
        clr.l   (a0)
        lea     vpv47_slot_returned,a0
        adda.l  d0,a0
        clr.l   (a0)
        moveq   #0,d0
        bra.s   vpv47_send_done
vpv47_send_fail:
        ; If CachePreDMA succeeded but TX reservation/publication failed,
        ; return CPU ownership before leaving the slot reusable.
        move.l  d7,d0
        cmpi.l  #VPV47_AUDIO_SLOTS,d0
        bcc.s   vpv47_send_fail_done
        lsl.l   #2,d0
        lea     vpv47_slot_dma_active,a0
        adda.l  d0,a0
        tst.l   (a0)
        beq.s   vpv47_send_fail_done
        tst.l   d7
        bne.s   vpv47_send_fail_slot1
        move.l  vpv21_pcm_ptr,a0
        bra.s   vpv47_send_fail_have_ptr
vpv47_send_fail_slot1:
        move.l  vpv47_pcm1_ptr,a0
vpv47_send_fail_have_ptr:
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        move.l  d7,d0
        lsl.l   #2,d0
        lea     vpv47_slot_dma_active,a0
        adda.l  d0,a0
        clr.l   (a0)
vpv47_send_fail_done:
        moveq   #1,d0
vpv47_send_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

msg_vpv47_double_ok:
        dc.b "[mkvr7][AUDIO-DOUBLE] TRUE DOUBLE: two independent 64KiB MMAL audio chunks simultaneously renderer-owned",10
msg_vpv47_double_ok_end:
msg_vpv81_port0_readback:
        dc.b "[mkvr7][AUDIO-PORT0] first-start VideoCore buffer_num/size = 0x"
msg_vpv81_port0_readback_end:
msg_vpv81_port1_readback:
        dc.b "[mkvr7][AUDIO-PORT1] second-start VideoCore buffer_num/size = 0x"
msg_vpv81_port1_readback_end:
        even

; Retain VPv46 single-buffer service below as diagnostic/reference, but it is
; no longer called by the H264 streaming dispatcher in VPv47.
vpv39_audio_service:
        movem.l d1-d7/a0-a3/a6,-(sp)
        moveq   #0,d7
        tst.l   vpv39_audio_armed
        beq.w   vpv39_service_done
        tst.l   vpv39_audio_failed
        bne.w   vpv39_service_done

        ; VPv47: while VideoCore is playing the current DMA block, prepare the
        ; NEXT AAC block in ordinary Fast RAM. This is the key anti-underrun
        ; change: file I/O + Helix decode no longer sit in the renderer gap.
        tst.l   vpv21_audio_dma_active
        beq.s   vpv45_no_prefetch_window
        tst.l   vpv45_prefetch_ready
        bne.s   vpv45_no_prefetch_window
        tst.l   vpv41_decoder_live
        beq.s   vpv45_no_prefetch_window
        jsr     vpv45_prefetch_live_pcm
        cmpi.l  #2,d0
        beq.w   vpv41_service_decode_fail
vpv45_no_prefetch_window:

        ; If the current PCM buffer has BOTH transport completion and the exact
        ; audio BUFFER_TO_HOST callback, ownership is fully back on the 68k.
        tst.l   vpv21_audio_dma_active
        beq.w   vpv39_service_maybe_send
        tst.l   vpv01_bulk_done
        beq.w   vpv39_service_done
        tst.l   vpv21_audio_returned
        beq.w   vpv39_service_done

        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  vpv21_pcm_ptr,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv21_audio_dma_active
        clr.l   vpv01_bulk_done
        clr.l   vpv21_audio_returned
        addq.l  #1,vpv39_audio_blocks_done
        addq.l  #1,vpv39_audio_next_block
        jsr     vpv43_advance_audio_pts

        move.l  vpv39_audio_next_block,d0
        cmp.l   vpv38_pcm_block_count,d0
        bcs.s   vpv39_service_maybe_send
        ; VPv47 continues past the single priming block by decoding the next
        ; AAC block on demand. Completion is only declared after Helix EOF.
        tst.l   vpv41_decoder_live
        bne.s   vpv39_service_maybe_send
        tst.l   vpv41_audio_eof
        beq.s   vpv39_service_maybe_send
        move.l  #1,vpv39_audio_all_done
        clr.l   vpv39_audio_armed
        lea     msg_vpv39_live_done,a1
        move.l  #msg_vpv39_live_done_end-msg_vpv39_live_done,d3
        jsr     vpv21n_trace
        bra.w   vpv39_service_done

vpv39_service_maybe_send:
        ; Never start a new audio buffer once a user stop/EOF is in progress.
        ; Any already-published audio buffer is still allowed to return above.
        tst.l   v15_stop_requested
        bne.w   vpv39_service_done
        tst.l   input_eof_seen
        bne.w   vpv39_service_done

        ; One VCHIQ BULK_TX at a time globally. Video can keep owning MMAL
        ; input buffers, but its current BULK transport must be idle here.
        tst.l   input_bulk_pending
        bne.w   vpv39_service_done
        tst.l   vpv39_audio_bulk_pending
        bne.w   vpv39_service_done
        tst.l   vpv21_audio_dma_active
        bne.w   vpv39_service_done

        ; VPv47: transport-idle is no longer sufficient.  Only publish PCM
        ; when its media PTS is due against the displayed-video timeline.
        jsr     vpv43_audio_pts_gate
        tst.l   d0
        bne.w   vpv39_service_done

        move.l  vpv39_audio_next_block,d0
        cmp.l   vpv38_pcm_block_count,d0
        bcs.s   vpv41_have_pcm_source

        ; Normal VPv47 path: next PCM was decoded while the previous block was
        ; playing. If we missed that window, decode here as a measurable fallback.
        tst.l   vpv45_prefetch_ready
        bne.s   vpv45_have_prefetched_pcm
        tst.l   vpv41_decoder_live
        beq.s   vpv45_no_decoder_for_prefetch
        addq.l  #1,vpv45_prefetch_miss_count
        jsr     vpv45_prefetch_live_pcm
        tst.l   d0
        beq.s   vpv45_have_prefetched_pcm
        cmpi.l  #1,d0
        bne.w   vpv41_service_decode_fail
vpv45_no_decoder_for_prefetch:
        ; Clean AAC EOF: no more PCM to send.
        move.l  #1,vpv39_audio_all_done
        clr.l   vpv39_audio_armed
        lea     msg_vpv39_live_done,a1
        move.l  #msg_vpv39_live_done_end-msg_vpv39_live_done,d3
        jsr     vpv21n_trace
        bra.w   vpv39_service_done
vpv45_have_prefetched_pcm:
        moveq   #1,d6                  ; source = CPU-side prefetched PCM
        bra.s   vpv45_expose_audio_globals
vpv41_have_pcm_source:
        moveq   #0,d6                  ; source = initial staged priming PCM

vpv45_expose_audio_globals:
        ; Save all live VIDEO globals. The proven audio constructor still uses
        ; these generic slots internally, so expose audio only for this publish.
        move.l  component_handle,vpv36_queue_saved_component
        move.l  input_port_handle,vpv36_queue_saved_input
        move.l  port_query_index,vpv36_queue_saved_qidx
        move.l  port_buf_size,vpv36_queue_saved_buf_size

        move.l  vpv01_audio_handle,component_handle
        move.l  vpv01_audio_input,input_port_handle
        move.l  vpv21_audio_port_buf_size,port_buf_size

        tst.l   d6
        beq.s   vpv45_load_priming_pcm
        jsr     vpv45_load_prefetch_pcm
        tst.l   d0
        bne.s   vpv39_service_send_fail
        bra.s   vpv41_pcm_is_in_dma
vpv45_load_priming_pcm:
        move.l  vpv39_audio_next_block,d0
        jsr     vpv38_load_pcm_block
        tst.l   d0
        bne.s   vpv39_service_send_fail
vpv41_pcm_is_in_dma:
        ; Remember exact samples/channel represented by this PCM buffer so the
        ; next audio PTS can advance with carried rational remainder.
        move.l  vpv21_pcm_total_bytes,d0
        move.l  v19_pcm_blockalign,d1
        tst.l   d1
        beq.w   vpv39_service_send_fail
        jsr     v10_udiv32
        move.l  d0,vpv43_last_sent_samples
        jsr     vpv21_send_full_pcm
        tst.l   d0
        bne.s   vpv39_service_send_fail
        move.l  #1,vpv39_audio_bulk_pending
        moveq   #1,d7
        bra.s   vpv39_service_restore

vpv41_service_decode_fail:
        move.l  #1,vpv39_audio_failed
        clr.l   vpv39_audio_armed
        lea     msg_vpv39_live_fail,a1
        move.l  #msg_vpv39_live_fail_end-msg_vpv39_live_fail,d3
        jsr     vpv21n_trace
        bra.w   vpv39_service_done

vpv39_service_send_fail:
        move.l  #1,vpv39_audio_failed
        clr.l   vpv39_audio_armed
        lea     msg_vpv39_live_fail,a1
        move.l  #msg_vpv39_live_fail_end-msg_vpv39_live_fail,d3
        jsr     vpv21n_trace
vpv39_service_restore:
        move.l  vpv36_queue_saved_component,component_handle
        move.l  vpv36_queue_saved_input,input_port_handle
        move.l  vpv36_queue_saved_qidx,port_query_index
        move.l  vpv36_queue_saved_buf_size,port_buf_size
vpv39_service_done:
        move.l  d7,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Publish the one bounded short PCM MMAL input buffer plus VCHIQ BULK_TX.
vpv21_send_full_pcm:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv01_bulk_done
        clr.l   vpv21_audio_returned

        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  vpv21_pcm_ptr,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        cmp.l   vpv21_pcm_ptr,d0
        bne.w   vpv21_send_fail
        move.l  vpv21_audio_dma_len,d1
        cmp.l   #VPV21_PCM_DMA_SPAN,d1
        bcs.w   vpv21_send_fail_post
        move.l  #1,vpv21_audio_dma_active

        move.l  #320,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv21_send_fail_post
        move.l  a2,a0
        moveq   #79,d7
vpv21_send_clear:
        clr.l   (a0)+
        dbra    d7,vpv21_send_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #292,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_BUFFER_FROM_HOST,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #VPV01_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv01_audio_handle,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  vpv01_audio_input,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #VPV01_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     76(a2),a0
        move.l  vpv21_pcm_ptr,d0
        jsr     store_le32
        lea     80(a2),a0
        move.l  port_buf_size,d0
        jsr     store_le32
        lea     84(a2),a0
        move.l  vpv21_pcm_total_bytes,d0
        jsr     store_le32
        lea     96(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     100(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32
        lea     104(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     108(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32

        lea     304(a2),a3
        move.l  a3,a0
        move.l  #VCHIQ_MSG_BULK_TX,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #8,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  vpv21_pcm_pagelist_bus,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  vpv21_pcm_total_bytes,d0
        jsr     store_le32

        add.l   #320,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   vpv21_send_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv21_send_no_bell:
        moveq   #0,d0
        bra.s   vpv21_send_done
vpv21_send_fail_post:
        tst.l   vpv21_audio_dma_active
        beq.s   vpv21_send_fail
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  vpv21_pcm_ptr,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv21_audio_dma_active
vpv21_send_fail:
        moveq   #1,d0
vpv21_send_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; VPv36: wait until BOTH the PCM BULK transfer and the matching
; audio BUFFER_TO_HOST callback have completed. VPv34 started H264 after
; BULK_TX_DONE alone and left the audio input header outstanding.
; Success returns CPU-owned with no audio buffer still in flight.
vpv21_wait_bulk_only:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  #V10_CLEANUP_POLL_COUNT,d7
vpv21_wait_bulk_loop:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   vpv21_wait_bulk_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv21_wait_bulk_loop
        jsr     dma_post_all
        bra.w   vpv21_wait_bulk_fail
vpv21_wait_bulk_have:
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   vpv21_wait_bulk_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,d5
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,d6

        ; Same local/remote MMAL service?
        move.l  d5,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   vpv21_wait_bulk_consume
        move.l  d5,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   vpv21_wait_bulk_consume

        move.l  d5,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_BULK_TX_DONE,d0
        beq.s   vpv21_wait_got_bulk
        cmp.l   #VCHIQ_MSG_DATA,d0
        beq.s   vpv21_wait_check_data
        bra.w   vpv21_wait_bulk_consume

vpv21_wait_got_bulk:
        cmpi.l  #4,d6
        bcs.w   vpv21_wait_bulk_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   vpv21_pcm_total_bytes,d0
        bne.w   vpv21_wait_bulk_fail
        move.l  #1,vpv01_bulk_done
        bra.s   vpv21_wait_bulk_consume

vpv21_wait_check_data:
        ; VPv36: do NOT start H264 until audio_render has returned the exact
        ; PCM input buffer as well.  VPv34 waited only for BULK_TX_DONE and
        ; left this MMAL callback outstanding while video streaming started.
        cmpi.l  #48,d6
        bcs.s   vpv21_wait_bulk_consume
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.s   vpv21_wait_bulk_consume
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_BUFFER_TO_HOST,d0
        bne.s   vpv21_wait_bulk_consume
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   vpv21_wait_bulk_fail
        lea     40(a2),a0
        jsr     load_le32
        cmp.l   vpv01_audio_input,d0
        bne.s   vpv21_wait_bulk_consume
        lea     44(a2),a0
        jsr     load_le32
        cmp.l   #VPV01_BUFFER_CONTEXT,d0
        bne.s   vpv21_wait_bulk_consume
        move.l  #1,vpv21_audio_returned

vpv21_wait_bulk_consume:
        move.l  d6,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv21_wait_bulk_fail
        tst.l   vpv01_bulk_done
        beq.s   vpv21_wait_bulk_more
        tst.l   vpv21_audio_returned
        bne.s   vpv21_wait_bulk_success
vpv21_wait_bulk_more:
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv21_wait_bulk_loop
        jsr     dma_post_all
        bra.s   vpv21_wait_bulk_fail
vpv21_wait_bulk_success:
        tst.l   vpv21_audio_dma_active
        beq.s   vpv21_wait_bulk_success_done
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  vpv21_pcm_ptr,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv21_audio_dma_active
vpv21_wait_bulk_success_done:
        lea     msg_vpv35_audio_return_ok,a1
        move.l  #msg_vpv35_audio_return_ok_end-msg_vpv35_audio_return_ok,d3
        jsr     vpv21n_trace
        moveq   #0,d0
        bra.s   vpv21_wait_bulk_done
vpv21_wait_bulk_fail:
        tst.l   vpv21_audio_dma_active
        beq.s   vpv21_wait_bulk_fail_done
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  vpv21_pcm_ptr,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv21_audio_dma_active
vpv21_wait_bulk_fail_done:
        lea     msg_vpv21_queue_fail,a1
        move.l  #msg_vpv21_queue_fail_end-msg_vpv21_queue_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv21_wait_bulk_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; VPv102: VPv36 audio_render setup; nested GET errors unwind locally, and C/local-0 skips only the post-ENABLE verification GET.
; VPv36: complete audio_render setup AFTER the already-proven PCM PORT_INFO_SET,
; but BEFORE any video input buffers are queued.  Entry has audio globals active.
; Adds only: HDMI destination, INPUT enable, component enable.  No PCM transfer.
; D0=0 success, 1 failure.
vpv35_finish_audio_enable:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv21_audio_prepared

        lea     msg_vpv35_dest_begin,a1
        move.l  #msg_vpv35_dest_begin_end-msg_vpv35_dest_begin,d3
        jsr     vpv21n_trace
        move.l  vpv01_audio_input,d0
        jsr     vpv01_set_hdmi_destination
        tst.l   d0
        beq.s   vpv35_dest_ok
        move.l  vpv01_audio_control,d0
        jsr     vpv01_set_hdmi_destination
        tst.l   d0
        bne.w   vpv35_finish_fail
vpv35_dest_ok:
        lea     msg_vpv35_dest_ok,a1
        move.l  #msg_vpv35_dest_ok_end-msg_vpv35_dest_ok,d3
        jsr     vpv21n_trace

        ; Refresh INPUT0 snapshot after SET before enabling it.
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        ; VPv102: this GET is nested inside vpv35_finish_audio_enable.  Mark it
        ; as a returnable GET so a transport timeout unwinds only port_info_get
        ; and returns D0=1 here instead of jumping across our MOVEM frame into
        ; close_prog (the VPv100 SP-difference diagnosis).
        move.l  #1,v12a_local_get_active
        jsr     port_info_get
        clr.l   v12a_local_get_active
        tst.l   d0
        bne.w   vpv35_finish_fail
        move.l  port_last_handle,vpv01_audio_input
        move.l  vpv01_audio_input,input_port_handle

        lea     msg_vpv35_port_enable_begin,a1
        move.l  #msg_vpv35_port_enable_begin_end-msg_vpv35_port_enable_begin,d3
        jsr     vpv21n_trace
        tst.l   v12f_local_port
        bne.s   vpv35_enable_local1
        jsr     port_enable_current
        bra.s   vpv35_enable_done
vpv35_enable_local1:
        move.l  vpv01_audio_input,d0
        move.l  #MMAL_PORT_INPUT,d1
        jsr     v9f_port_enable
vpv35_enable_done:
        tst.l   d0
        bne.w   vpv35_finish_fail

        ; Verify INPUT0 really reports enabled=1.
        ; VPv102 C/local-0 exception: VPv100 proved PORT_ACTION ENABLE itself
        ; returned SUCCESS, then the immediately following diagnostic GET timed
        ; out before any PCM/video traffic.  The GET is not required to enable
        ; the port.  In direct C mode on the first MMAL service trust the
        ; successful PORT_ACTION reply and avoid injecting this extra sync MMAL
        ; request into the freshly-built video_render graph.  P96 modes and the
        ; local-1/second-start path retain the historical readback unchanged.
        cmpi.l  #3,v41_display_style
        bne.s   vpv102_audio_enable_do_readback
        tst.l   v12f_local_port
        bne.s   vpv102_audio_enable_do_readback
        move.l  #1,port_enabled
        lea     msg_vpv102_c_enable_ack,a1
        move.l  #msg_vpv102_c_enable_ack_end-msg_vpv102_c_enable_ack,d3
        jsr     vpv21n_trace
        bra.s   vpv102_audio_enable_verified
vpv102_audio_enable_do_readback:
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        ; As above, this is a nested GET and must return to this routine on
        ; failure instead of performing the legacy fatal stack unwind.
        move.l  #1,v12a_local_get_active
        jsr     port_info_get
        clr.l   v12a_local_get_active
        tst.l   d0
        bne.w   vpv35_finish_fail
        cmpi.l  #1,port_enabled
        bne.w   vpv35_finish_fail
vpv102_audio_enable_verified:
        lea     msg_vpv35_port_enable_ok,a1
        move.l  #msg_vpv35_port_enable_ok_end-msg_vpv35_port_enable_ok,d3
        jsr     vpv21n_trace

        lea     msg_vpv35_component_enable_begin,a1
        move.l  #msg_vpv35_component_enable_begin_end-msg_vpv35_component_enable_begin,d3
        jsr     vpv21n_trace
        move.l  vpv01_audio_handle,component_handle
        tst.l   v12f_local_port
        bne.s   vpv35_comp_enable_local1
        jsr     component_enable_worker
        bra.s   vpv35_comp_enable_done
vpv35_comp_enable_local1:
        jsr     v9f_component_enable
vpv35_comp_enable_done:
        tst.l   d0
        bne.s   vpv35_finish_fail
        move.l  #1,vpv01_component_enabled
        move.l  port_buf_size,vpv21_audio_port_buf_size
        move.l  #1,vpv21_audio_prepared
        lea     msg_vpv35_component_enable_ok,a1
        move.l  #msg_vpv35_component_enable_ok_end-msg_vpv35_component_enable_ok,d3
        jsr     vpv21n_trace
        moveq   #0,d0
        bra.s   vpv35_finish_done
vpv35_finish_fail:
        clr.l   vpv21_audio_prepared
        lea     msg_vpv35_finish_fail,a1
        move.l  #msg_vpv35_finish_fail_end-msg_vpv35_finish_fail,d3
        jsr     vpv21n_trace
        moveq   #1,d0
vpv35_finish_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; VPv102 controlled-stop helper. Call ONLY after v9_cleanup_all has
; returned from MMAL service-close handling. It never touches VCHIQ shared RAM.
; It merely ends any remaining CachePreDMA ownership on the two independent
; 64-KiB PCM slots before FreeMem. Safe as a no-op on natural EOF.
vpv93_postclose_reclaim_audio_dma:
        movem.l d1-d3/a0-a1/a6,-(sp)
        ; Hard safety gate: only a confirmed closed MMAL service releases the
        ; renderer's ownership. On cleanup failure leave PCM allocated and
        ; return D0=1 so close_prog deliberately skips FreeMem.
        tst.l   mmal_remote_port
        bne.w   vpv93_postclose_reclaim_unsafe
        moveq   #0,d3
vpv93_postclose_reclaim_loop:
        cmpi.l  #VPV47_AUDIO_SLOTS,d3
        bcc.s   vpv93_postclose_reclaim_done
        move.l  d3,d0
        lsl.l   #2,d0
        lea     vpv47_slot_dma_active,a0
        adda.l  d0,a0
        tst.l   (a0)
        beq.s   vpv93_postclose_reclaim_clear
        tst.l   d3
        bne.s   vpv93_postclose_slot1
        move.l  vpv21_pcm_ptr,a0
        bra.s   vpv93_postclose_have_ptr
vpv93_postclose_slot1:
        move.l  vpv47_pcm1_ptr,a0
vpv93_postclose_have_ptr:
        cmpa.l  #0,a0
        beq.s   vpv93_postclose_reclaim_clear
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
vpv93_postclose_reclaim_clear:
        move.l  d3,d0
        lsl.l   #2,d0
        lea     vpv47_slot_dma_active,a0
        adda.l  d0,a0
        clr.l   (a0)
        lea     vpv47_slot_state,a0
        adda.l  d0,a0
        clr.l   (a0)
        lea     vpv47_slot_bulk_done,a0
        adda.l  d0,a0
        clr.l   (a0)
        lea     vpv47_slot_returned,a0
        adda.l  d0,a0
        clr.l   (a0)
        addq.l  #1,d3
        bra.s   vpv93_postclose_reclaim_loop
vpv93_postclose_reclaim_done:
        clr.l   vpv47_inflight
        clr.l   vpv39_audio_bulk_pending
        clr.l   vpv21_audio_dma_active
        clr.l   vpv39_audio_armed
        clr.l   vpv01_component_enabled
        clr.l   vpv01_audio_handle
        clr.l   vpv01_audio_input
        clr.l   vpv01_audio_control
        moveq   #0,d0
        bra.s   vpv93_postclose_reclaim_exit
vpv93_postclose_reclaim_unsafe:
        moveq   #1,d0
vpv93_postclose_reclaim_exit:
        movem.l (sp)+,d1-d3/a0-a1/a6
        rts

vpv21_free_pcm:
        movem.l d0-d1/a0-a1/a6,-(sp)
        move.l  vpv21_pcm_alloc,d0
        beq.s   vpv21_free_done
        move.l  d0,a1
        ; VPv21T FIX: Exec FreeMem() expects byteSize in D0, not D1.
        ; Previous VPv21 code left the allocation address in D0, causing
        ; Exec to free an absurd pointer-sized byte count and corrupt MemLists.
        move.l  #VPV21_PCM_ALLOC_SIZE,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   vpv21_pcm_alloc
        clr.l   vpv21_pcm_ptr
        clr.l   vpv21_pcm_bus
        clr.l   vpv21_pcm_pagelist_ptr
        clr.l   vpv21_pcm_pagelist_bus
        clr.l   vpv47_pcm1_ptr
        clr.l   vpv47_pcm1_bus
        clr.l   vpv47_pcm1_pagelist_ptr
        clr.l   vpv47_pcm1_pagelist_bus
        clr.l   vpv21_pcm_total_bytes
        clr.l   vpv21_pcm_total_samples
vpv21_free_done:
        movem.l (sp)+,d0-d1/a0-a1/a6
        rts

