; ====================================================================
; mkvr7 - real VideoCore scheduler data path
; decoder OPQV -> scheduler OPQV -> ISP BGRA/P96
; ====================================================================
; N80 - decoder.output -> ISP.input without a video_scheduler, for streams
; that have no Audio-Master clock (no HDMI audio).  Same steps as
; vpv126_setup_scheduler_data_graph minus the scheduler: connect, set the
; ISP input peer requirements, enable decoder OUTPUT (which brings the
; tunnelled ISP INPUT up), verify.  D0=0 ok, D0=1 failure.
n80_setup_direct_isp_graph:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv126_data_graph_ok
        jsr     v12a_connect_ports
        tst.l   d0
        bne.w   n80_dg_f1
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   n80_dg_f2
        jsr     v12a_set_isp_requirements
        tst.l   d0
        bne.w   n80_dg_f3
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_decoder_output,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   n80_dg_f4
        move.l  port_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   n80_dg_num_ok
        moveq   #2,d0
n80_dg_num_ok:
        move.l  d0,port_buf_num
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   n80_dg_f5
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   n80_dg_f6
        cmpi.l  #1,port_enabled
        bne.w   n80_dg_f7
        move.l  #1,vpv126_data_graph_ok
        lea     n80_msg_direct_no_audio,a1
        jsr     n12_log
        moveq   #0,d0
        bra.s   n80_dg_done
n80_dg_f1:
        move.l  d0,n80_dg_d0
        moveq   #1,d0
        bra.s   n80_dg_fail
n80_dg_f2:
        move.l  d0,n80_dg_d0
        moveq   #2,d0
        bra.s   n80_dg_fail
n80_dg_f3:
        move.l  d0,n80_dg_d0
        moveq   #3,d0
        bra.s   n80_dg_fail
n80_dg_f4:
        move.l  d0,n80_dg_d0
        moveq   #4,d0
        bra.s   n80_dg_fail
n80_dg_f5:
        move.l  d0,n80_dg_d0
        move.l  n80_en_why,d0
        lea     n80_pfx_en_why,a1
        jsr     n15_log_hex32
        move.l  out_enable_rx_size,d0
        lea     n80_pfx_en_rx,a1
        jsr     n15_log_hex32
        move.l  out_enable_status,d0
        lea     n80_pfx_en_st,a1
        jsr     n15_log_hex32
        move.l  vpv30_skipped,d0
        lea     n80_pfx_skipped,a1
        jsr     n15_log_hex32
        move.l  vpv30_async_skipped,d0
        lea     n80_pfx_async,a1
        jsr     n15_log_hex32
        moveq   #5,d0
        bra.w   n80_dg_fail
n80_dg_f6:
        move.l  d0,n80_dg_d0
        moveq   #6,d0
        bra.s   n80_dg_fail
n80_dg_f7:
        move.l  d0,n80_dg_d0
        moveq   #7,d0
        bra.s   n80_dg_fail
n80_dg_fail:
        ; N80: which step (1 connect, 2/4/6 port get, 3 ISP requirements,
        ; 5 decoder output enable, 7 ISP input not enabled), its D0, and
        ; the CONNECT reply fields.
        lea     n80_pfx_dg_step,a1
        jsr     n15_log_hex32
        move.l  n80_dg_d0,d0
        lea     n80_pfx_dg_d0,a1
        jsr     n15_log_hex32
        move.l  v12a_connect_rx_size,d0
        lea     n80_pfx_dg_crx,a1
        jsr     n15_log_hex32
        move.l  v12a_connect_header_status,d0
        lea     n80_pfx_dg_chdr,a1
        jsr     n15_log_hex32
        move.l  v12a_connect_status,d0
        lea     n80_pfx_dg_cst,a1
        jsr     n15_log_hex32
        lea     n80_msg_direct_fail,a1
        jsr     n12_log
        moveq   #1,d0
n80_dg_done:
        move.l  v12a_isp_handle,component_handle
        movem.l (sp)+,d1-d7/a0-a3
        rts

vpv126_setup_scheduler_data_graph:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv126_data_graph_ok

        ; Create one scheduler early enough for the two VIDEO tunnels.
        tst.l   vpv117_sched_handle
        bne.s   vpv126_graph_have_sched
        jsr     vpv117_create_scheduler_component
        tst.l   d0
        bne.w   vpv126_graph_fail
vpv126_graph_have_sched:

        ; Scheduler INPUT0: exact decoder OPQV geometry/variant.
        move.l  vpv117_sched_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv126_graph_fail
        move.l  port_last_handle,vpv117_sched_input0
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_OPAQUE,port_fmt_encoding
        move.l  v12c_dec_variant,port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v12a_dec_w,port_video_width
        move.l  v12a_dec_h,port_video_height
        move.l  v12a_dec_crop_x,port_crop_x
        move.l  v12a_dec_crop_y,port_crop_y
        move.l  v12a_dec_crop_w,port_crop_width
        move.l  v12a_dec_crop_h,port_crop_height
        move.l  v12a_dec_fps_num,port_fps_num
        move.l  v12a_dec_fps_den,port_fps_den
        move.l  v12a_dec_par_num,port_par_num
        move.l  v12a_dec_par_den,port_par_den
        move.l  v12a_dec_colorspace,port_color_space
        move.l  v12a_dec_buf_size,port_buf_size
        move.l  v12a_dec_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   vpv126_sched_in_num_ok
        moveq   #2,d0
vpv126_sched_in_num_ok:
        move.l  d0,port_buf_num
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   vpv126_graph_fail
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv126_graph_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_OPAQUE,d0
        bne.w   vpv126_graph_fail
        move.l  port_fmt_variant,d0
        cmp.l   v12c_dec_variant,d0
        bne.w   vpv126_graph_fail

        ; Scheduler OUTPUT0: same opaque surface description.
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv126_graph_fail
        move.l  port_last_handle,vpv117_sched_output0
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_OPAQUE,port_fmt_encoding
        move.l  v12c_dec_variant,port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v12a_dec_w,port_video_width
        move.l  v12a_dec_h,port_video_height
        move.l  v12a_dec_crop_x,port_crop_x
        move.l  v12a_dec_crop_y,port_crop_y
        move.l  v12a_dec_crop_w,port_crop_width
        move.l  v12a_dec_crop_h,port_crop_height
        move.l  v12a_dec_fps_num,port_fps_num
        move.l  v12a_dec_fps_den,port_fps_den
        move.l  v12a_dec_par_num,port_par_num
        move.l  v12a_dec_par_den,port_par_den
        move.l  v12a_dec_colorspace,port_color_space
        move.l  v12a_dec_buf_size,port_buf_size
        move.l  v12a_dec_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   vpv126_sched_out_num_ok
        moveq   #2,d0
vpv126_sched_out_num_ok:
        move.l  d0,port_buf_num
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   vpv126_graph_fail
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv126_graph_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_OPAQUE,d0
        bne.w   vpv126_graph_fail

        ; CONNECT #1: decoder.output -> scheduler.input.
        move.l  v12a_isp_handle,vpv126_saved_isp_handle
        move.l  v12a_isp_input,vpv126_saved_isp_input
        move.l  vpv117_sched_handle,v12a_isp_handle
        move.l  vpv117_sched_input0,v12a_isp_input
        jsr     v12a_connect_ports
        move.l  vpv126_saved_isp_handle,v12a_isp_handle
        move.l  vpv126_saved_isp_input,v12a_isp_input
        tst.l   d0
        bne.w   vpv126_graph_fail
        lea     msg_vpv127_connect1_ok,a1
        move.l  #msg_vpv127_connect1_ok_end-msg_vpv127_connect1_ok,d3
        jsr     print_force

        ; VPv128: Broadcom hello_video establishes decoder->scheduler,
        ; starts video_scheduler, and only then builds the downstream tunnel.
        ; mkvr7 live-switch note: in 10/25/50/75 playback the scheduler
        ; component is already enabled by the audio-master clock setup although
        ; its VIDEO ports are unused. Do not COMPONENT_ENABLE it a second time.
        tst.l   vpv126_sched_component_enabled
        bne.s   vpv126_sched_already_running_data
        clr.l   vpv128_sched_started_early
        move.l  vpv117_sched_handle,component_handle
        jsr     component_enable_worker
        tst.l   d0
        bne.w   vpv126_graph_fail
        move.l  #1,vpv128_sched_started_early
        bra.s   vpv126_sched_started_data_ready
vpv126_sched_already_running_data:
        move.l  #1,vpv128_sched_started_early
vpv126_sched_started_data_ready:
        lea     msg_vpv128_sched_early_ok,a1
        move.l  #msg_vpv128_sched_early_ok_end-msg_vpv128_sched_early_ok,d3
        jsr     print_force

        ; CONNECT #2: scheduler.output -> ISP.input.
        move.l  v12a_decoder_handle,vpv126_saved_dec_handle
        move.l  v12a_decoder_output,vpv126_saved_dec_output
        move.l  vpv117_sched_handle,v12a_decoder_handle
        move.l  vpv117_sched_output0,v12a_decoder_output
        jsr     v12a_connect_ports
        move.l  vpv126_saved_dec_handle,v12a_decoder_handle
        move.l  vpv126_saved_dec_output,v12a_decoder_output
        tst.l   d0
        bne.w   vpv126_graph_fail
        lea     msg_vpv127_connect2_ok,a1
        move.l  #msg_vpv127_connect2_ok_end-msg_vpv127_connect2_ok,d3
        jsr     print_force

        ; Peer requirements for scheduler INPUT0 before decoder OUTPUT enable.
        move.l  vpv117_sched_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv126_graph_fail
        move.l  v12a_isp_handle,vpv126_saved_isp_handle
        move.l  v12a_isp_input,vpv126_saved_isp_input
        move.l  vpv117_sched_handle,v12a_isp_handle
        move.l  vpv117_sched_input0,v12a_isp_input
        jsr     v12a_set_isp_requirements
        move.l  vpv126_saved_isp_handle,v12a_isp_handle
        move.l  vpv126_saved_isp_input,v12a_isp_input
        tst.l   d0
        bne.w   vpv126_graph_fail

        ; Peer requirements for ISP INPUT0 before scheduler OUTPUT enable.
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv126_graph_fail
        jsr     v12a_set_isp_requirements
        tst.l   d0
        bne.w   vpv126_graph_fail

        ; Enable decoder OUTPUT. Its connected scheduler INPUT comes up too.
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_decoder_output,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv126_graph_fail
        move.l  port_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   vpv126_dec_out_num_ok
        moveq   #2,d0
vpv126_dec_out_num_ok:
        move.l  d0,port_buf_num
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   vpv126_graph_fail

        ; Verify scheduler INPUT0 is enabled by tunnel ownership.
        move.l  vpv117_sched_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv126_graph_fail
        cmpi.l  #1,port_enabled
        bne.w   vpv126_graph_fail

        ; Enable scheduler OUTPUT0. Its connected ISP INPUT0 comes up too.
        move.l  vpv117_sched_handle,component_handle
        move.l  vpv117_sched_output0,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv126_graph_fail
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   vpv126_graph_fail

        ; Verify ISP INPUT0 is now enabled.
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv126_graph_fail
        cmpi.l  #1,port_enabled
        bne.w   vpv126_graph_fail

        move.l  #1,vpv126_data_graph_ok
        lea     msg_vpv126_data_graph_ok,a1
        move.l  #msg_vpv126_data_graph_ok_end-msg_vpv126_data_graph_ok,d3
        jsr     print_force
        moveq   #0,d0
        bra.s   vpv126_graph_done

vpv126_graph_fail:
        ; Always restore the established graph globals before returning.
        tst.l   vpv126_saved_isp_handle
        beq.s   vpv126_graph_no_isp_restore
        move.l  vpv126_saved_isp_handle,v12a_isp_handle
        move.l  vpv126_saved_isp_input,v12a_isp_input
vpv126_graph_no_isp_restore:
        tst.l   vpv126_saved_dec_handle
        beq.s   vpv126_graph_no_dec_restore
        move.l  vpv126_saved_dec_handle,v12a_decoder_handle
        move.l  vpv126_saved_dec_output,v12a_decoder_output
vpv126_graph_no_dec_restore:
        lea     msg_vpv126_data_graph_fail,a1
        move.l  #msg_vpv126_data_graph_fail_end-msg_vpv126_data_graph_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv126_graph_done:
        move.l  v12a_isp_handle,component_handle
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Enable a MMAL CLOCK port described by current port_* globals.
; component_handle + input_port_handle select the endpoint;
; vpv126_clock_enable_index is the clock-port index embedded in mmal_port.
vpv126_enable_clock_current:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv126_clock_enable_status
        move.l  #112,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv126_clock_enable_fail
        move.l  a2,a0
        moveq   #27,d7
vpv126_clk_en_clear:
        clr.l   (a0)+
        dbra    d7,vpv126_clk_en_clear
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #100,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_ACTION,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$A126C10C,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  component_handle,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  input_port_handle,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  #MMAL_PORT_ACTION_ENABLE,d0
        jsr     store_le32
        lea     52(a2),a0
        move.l  #MMAL_PORT_CLOCK,d0
        jsr     store_le32
        lea     56(a2),a0
        move.l  vpv126_clock_enable_index,d0
        jsr     store_le32
        lea     60(a2),a0
        move.l  port_enabled,d0
        jsr     store_le32
        lea     68(a2),a0
        move.l  port_buf_num_min,d0
        jsr     store_le32
        lea     72(a2),a0
        move.l  port_buf_size_min,d0
        jsr     store_le32
        lea     76(a2),a0
        move.l  port_buf_align,d0
        jsr     store_le32
        lea     80(a2),a0
        move.l  port_buf_num_rec,d0
        jsr     store_le32
        lea     84(a2),a0
        move.l  port_buf_size_rec,d0
        jsr     store_le32
        lea     88(a2),a0
        move.l  port_buf_num,d0
        jsr     store_le32
        lea     92(a2),a0
        move.l  port_buf_size,d0
        jsr     store_le32
        lea     100(a2),a0
        move.l  #$A126C10C,d0
        jsr     store_le32
        lea     104(a2),a0
        move.l  port_caps,d0
        jsr     store_le32

        add.l   #112,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   vpv126_clk_en_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv126_clk_en_wait_setup:
        move.l  #POLL_COUNT,d7
vpv126_clk_en_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   vpv126_clk_en_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   vpv126_clk_en_wait
        jsr     dma_post_all
        bra.w   vpv126_clock_enable_fail
vpv126_clk_en_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   vpv126_clock_enable_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,d5
        cmpi.l  #28,d0
        bcs.s   vpv126_clk_en_fail_consume
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.s   vpv126_clk_en_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.s   vpv126_clk_en_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   #$A126C10C,d0
        bne.s   vpv126_clk_en_fail_consume
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.s   vpv126_clk_en_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,vpv126_clock_enable_status
        tst.l   d0
        bne.s   vpv126_clk_en_fail_consume
        move.l  d5,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.s   vpv126_clock_enable_fail
        moveq   #0,d0
        bra.s   vpv126_clock_enable_done
vpv126_clk_en_fail_consume:
        move.l  d5,d0
        jsr     v12a_rx_consume_payload
vpv126_clock_enable_fail:
        moveq   #1,d0
vpv126_clock_enable_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Clock1 is the fanout leg already CONNECTed to scheduler CLOCK0 by VPv122.
; Enable the source clock port, verify the peer, and explicitly enable the
; peer only when firmware did not auto-enable it through the connection.
vpv126_activate_scheduler_clock:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv126_sched_clock_armed

        move.l  vpv116_clock_handle,component_handle
        move.l  #MMAL_PORT_CLOCK,port_query_type
        move.l  #1,port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv126_sched_clock_fail
        move.l  port_last_handle,input_port_handle
        move.l  #1,vpv126_clock_enable_index
        tst.l   port_enabled
        bne.s   vpv126_clock1_enabled
        jsr     vpv126_enable_clock_current
        tst.l   d0
        bne.w   vpv126_sched_clock_fail
vpv126_clock1_enabled:

        move.l  vpv117_sched_handle,component_handle
        move.l  #MMAL_PORT_CLOCK,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv126_sched_clock_fail
        move.l  port_last_handle,vpv117_sched_clock0
        move.l  port_last_handle,input_port_handle
        clr.l   vpv126_clock_enable_index
        tst.l   port_enabled
        bne.s   vpv126_sched_clock_peer_enabled
        jsr     vpv126_enable_clock_current
        tst.l   d0
        bne.w   vpv126_sched_clock_fail
        move.l  vpv117_sched_handle,component_handle
        move.l  #MMAL_PORT_CLOCK,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv126_sched_clock_fail
vpv126_sched_clock_peer_enabled:
        cmpi.l  #1,port_enabled
        bne.w   vpv126_sched_clock_fail
        move.l  #1,vpv126_sched_clock_armed
        lea     msg_vpv126_sched_clock_ok,a1
        move.l  #msg_vpv126_sched_clock_ok_end-msg_vpv126_sched_clock_ok,d3
        jsr     print_force
        bra.s   vpv126_sched_clock_done
vpv126_sched_clock_fail:
        lea     msg_vpv126_sched_clock_fail,a1
        move.l  #msg_vpv126_sched_clock_fail_end-msg_vpv126_sched_clock_fail,d3
        jsr     print_force
vpv126_sched_clock_done:
        move.l  vpv01_audio_handle,component_handle
        movem.l (sp)+,d1-d7/a0-a3
        moveq   #0,d0
        rts

vpv126_enable_scheduler_component:
        movem.l d1-d3/a0-a1,-(sp)
        clr.l   vpv126_sched_component_enabled
        tst.l   vpv126_sched_clock_armed
        beq.s   vpv126_sched_comp_fail
        tst.l   vpv128_sched_started_early
        bne.s   vpv128_sched_comp_already_started
        move.l  vpv117_sched_handle,component_handle
        jsr     component_enable_worker
        tst.l   d0
        bne.s   vpv126_sched_comp_fail
vpv128_sched_comp_already_started:
        move.l  #1,vpv126_sched_component_enabled
        lea     msg_vpv126_sched_component_ok,a1
        move.l  #msg_vpv126_sched_component_ok_end-msg_vpv126_sched_component_ok,d3
        jsr     print_force
        bra.s   vpv126_sched_comp_done
vpv126_sched_comp_fail:
        lea     msg_vpv126_sched_component_fail,a1
        move.l  #msg_vpv126_sched_component_fail_end-msg_vpv126_sched_component_fail,d3
        jsr     print_force
vpv126_sched_comp_done:
        move.l  vpv01_audio_handle,component_handle
        movem.l (sp)+,d1-d3/a0-a1
        moveq   #0,d0
        rts

