; ====================================================================
; mkvr7fix - TRUE-C parked scheduler queue watchdog
;
; Called only from h19_no_msg while VCHIQ RAM is CPU-owned.
; Return D0=1: this idle pass was handled; caller goes directly to h19_poll.
; Return D0=0: use the pre-existing legacy watchdog path.
;
; Key point: input send/return totals are the VIDEO progress source. Audio
; activity does not reset the video stall timer.  A bounded C queue therefore
; gets a real 5-second wall-clock window instead of 100/800 tight host polls.
; ====================================================================
        section code,code
mkvr7_c_sched_wait_service:
        movem.l d1-d3,-(sp)

        ; Detect real H264 progress without touching the hot callback sites.
        move.l  input_bulk_total,d1
        cmp.l   mkvr7_cwait_last_sent,d1
        bne.s   mkvr7_cwait_progress
        move.l  input_return_total,d2
        cmp.l   mkvr7_cwait_last_return,d2
        beq.s   mkvr7_cwait_progress_checked
mkvr7_cwait_progress:
        move.l  input_bulk_total,mkvr7_cwait_last_sent
        move.l  input_return_total,mkvr7_cwait_last_return
        clr.l   mkvr7_cwait_active
        clr.l   mkvr7_cwait_expired_logged
mkvr7_cwait_progress_checked:

        ; Only the TRUE-C, non-EOF, transport-idle, queued-video state belongs
        ; to this wall-clock guard. Everything else keeps R7's exact behavior.
        tst.l   vpv166_c_sched_feedahead
        beq.w   mkvr7_cwait_not_owned
        tst.l   input_eof_seen
        bne.w   mkvr7_cwait_not_owned
        tst.l   eos_sent
        bne.w   mkvr7_cwait_not_owned
        tst.l   input_bulk_pending
        bne.w   mkvr7_cwait_not_owned
        tst.l   vpv39_audio_bulk_pending
        bne.w   mkvr7_cwait_not_owned
        tst.l   input_in_use_count
        beq.w   mkvr7_cwait_not_owned

        ; Keep Audio eligible exactly as in the central dispatcher. If it
        ; publishes, its existing convention already leaves ownership ready
        ; for h19_poll. Audio progress deliberately does NOT reset video time.
        jsr     vpv47_audio_service
        tst.l   d0
        bne.s   mkvr7_cwait_handled_no_pre

        jsr     vpv98_read_sys_us
        tst.l   mkvr7_cwait_active
        bne.s   mkvr7_cwait_have_start
        move.l  #1,mkvr7_cwait_active
        move.l  d0,mkvr7_cwait_start_us
        addq.l  #1,mkvr7_cwait_entries
        bra.s   mkvr7_cwait_handled_pre

mkvr7_cwait_have_start:
        sub.l   mkvr7_cwait_start_us,d0
        cmpi.l  #MKVR7_C_SCHED_STALL_US,d0
        bcc.s   mkvr7_cwait_expired

mkvr7_cwait_handled_pre:
        jsr     vpv183_reload_stream_poll_budget
        jsr     dma_pre_all
mkvr7_cwait_handled_no_pre:
        moveq   #1,d0
        movem.l (sp)+,d1-d3
        rts

mkvr7_cwait_expired:
        tst.l   mkvr7_cwait_expired_logged
        bne.s   mkvr7_cwait_expired_done
        move.l  #1,mkvr7_cwait_expired_logged
        addq.l  #1,mkvr7_cwait_timeouts
        lea     msg_mkvr7_cwait_expired,a1
        move.l  #msg_mkvr7_cwait_expired_end-msg_mkvr7_cwait_expired,d3
        jsr     print
mkvr7_cwait_expired_done:
        ; After a genuine 5s wall-clock stall hand control back to the old
        ; watchdog. It will then produce the established detailed timeout dump.
        moveq   #0,d0
        movem.l (sp)+,d1-d3
        rts

mkvr7_cwait_not_owned:
        clr.l   mkvr7_cwait_active
        clr.l   mkvr7_cwait_expired_logged
        moveq   #0,d0
        movem.l (sp)+,d1-d3
        rts

