; ====================================================================
; Stage 4H - PURE VIDEO ISOLATION / Caffeine regression
; No audio implementation, no HVS fallback, no Intuition change.
; Only protects inherited standalone fatal exits while berryvp.library owns
; the call stack.
; ====================================================================
        section code,code
BVP4H_VchiqEntryWrapper:
        lea     4(sp),a0
        move.l  a0,bvp4h_abort_sp
        clr.l   bvp4h_abort_reason
        jmp     vpv01_vchiq_entry

BVP4H_CloseProgGate:
        tst.l   bvp_library_mode
        beq.s   BVP4H_CloseProgLegacy
        move.l  #1,bvp4h_abort_reason
        move.l  bvp4h_abort_sp,sp
        move.l  bvp_libbase_global,a6
        jmp     bvp_bi_backend_fail
BVP4H_CloseProgLegacy:
        lea     msg_vpv21p_close_enter,a1
        jmp     BVP4H_CloseProgAfterGate

BVP4H_AttachExitGate:
        tst.l   bvp_library_mode
        beq.s   BVP4H_AttachExitLegacy
        move.l  #2,bvp4h_abort_reason
        move.l  bvp4h_abort_sp,sp
        move.l  bvp_libbase_global,a6
        jmp     bvp_bi_backend_fail
BVP4H_AttachExitLegacy:
        jsr     hdmi_v40o_close_window
        jmp     BVP4H_AttachExitAfterGate

        section bss,bss
bvp4h_abort_sp:       ds.l 1
bvp4h_abort_reason:   ds.l 1
        even
        cnop    0,4
ac307_decoder_kind:
        ds.l    1                       ; 0=AAC/FAAD, 1=AC3/liba52, 2=E-AC3/FFmpeg fixed

BVPL_Stage4KEnd:

; ---------------------------------------------------------------------------
; N10D crash-persistent close-stamp trace. No Write/Flush. Each marker file is
; created and immediately closed, matching the hardware-proven N2/N3 method.
; A1 = zero-terminated filename. Uses DOSBase already opened by Stage4K backend.
; ---------------------------------------------------------------------------
        section code,code
n10d_stamp:
        movem.l d0-d3/a0-a1/a6,-(sp)
        move.l  bvp_dos_base,a6
        cmpa.l  #0,a6
        beq.s   n10d_stamp_done
        move.l  a1,d1
        move.l  #MODE_NEWFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.s   n10d_stamp_done
        move.l  d0,d1
        jsr     Close(a6)
n10d_stamp_done:
        movem.l (sp)+,d0-d3/a0-a1/a6
        rts

; ---------------------------------------------------------------------------
; N65 quiet crash-persistent sequential log. A1 = zero-terminated entry text.
; Only startup, errors and final summary are appended to N65_TRACE.TXT; DOS Flush + Close are
; executed before returning.  The live A/V success path performs no DOS logging,
; so playback throughput is not throttled by Open/Seek/Write/Flush/Close per packet.
; ---------------------------------------------------------------------------
n12_log:
        movem.l d0-d7/a0-a6,-(sp)
        move.l  bvp_dos_base,a6
        cmpa.l  #0,a6
        beq.s   n12_log_done
        move.l  a1,a2
        move.l  a1,a0
        moveq   #0,d5
n12_len_loop:
        tst.b   (a0)+
        beq.s   n12_len_done
        addq.l  #1,d5
        bra.s   n12_len_loop
n12_len_done:
        lea     n12_trace_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        bne.s   n12_have_file
        lea     n12_trace_name,a0
        move.l  a0,d1
        move.l  #MODE_NEWFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.s   n12_log_done
n12_have_file:
        move.l  d0,d4
        ; Seek(handle, 0, OFFSET_END=1) before every append.
        move.l  d4,d1
        moveq   #0,d2
        moveq   #1,d3
        jsr     Seek(a6)
        ; Write the entry text. A1 is scratch across DOS calls; A2 retains
        ; the original caller string pointer saved before Open/Seek.
        move.l  d4,d1
        move.l  a2,d2
        move.l  d5,d3
        jsr     Write(a6)
        ; Append LF.
        move.l  d4,d1
        lea     n12_trace_lf,a0
        move.l  a0,d2
        moveq   #1,d3
        jsr     Write(a6)
        ; Commit this entry before returning to the A/V path.
        move.l  d4,d1
        jsr     Flush(a6)
        move.l  d4,d1
        jsr     Close(a6)
n12_log_done:
        movem.l (sp)+,d0-d7/a0-a6
        rts

; N65 persistent numeric logger. Entry: A1=zero-terminated prefix, D0=value.
; Builds "<prefix>0xXXXXXXXX" in a private buffer and then uses n12_log,
; so every numeric fact is independently Open/Seek/Write/Flush/Close committed.
n15_log_hex32:
        movem.l d0-d7/a0-a3,-(sp)
        move.l  d0,d7
        lea     n15_hexbuf,a2
        move.l  a1,a0
n15_hex_copy_prefix:
        move.b  (a0)+,d0
        beq.s   n15_hex_prefix_done
        move.b  d0,(a2)+
        bra.s   n15_hex_copy_prefix
n15_hex_prefix_done:
        move.b  #'0',(a2)+
        move.b  #'x',(a2)+
        ; Fill eight digits right-to-left so only a legal 68000 #4 shift is used.
        lea     7(a2),a3
        moveq   #7,d6
n15_hex_digit_loop:
        move.l  d7,d0
        andi.l  #$0F,d0
        cmpi.b  #9,d0
        bls.s   n15_hex_digit_num
        addi.b  #'A'-10,d0
        bra.s   n15_hex_digit_store
n15_hex_digit_num:
        addi.b  #'0',d0
n15_hex_digit_store:
        move.b  d0,(a3)
        subq.l  #1,a3
        lsr.l   #4,d7
        dbra    d6,n15_hex_digit_loop
        adda.l  #8,a2
        clr.b   (a2)
        lea     n15_hexbuf,a1
        jsr     n12_log
        movem.l (sp)+,d0-d7/a0-a3
        rts

        cnop    0,4

; ============================================================================
; AC307A - AC3 source integration on exact reconstructed N79Q
; Existing N79Q FAAD/AAC code remains in place. AC3 gets a separate loader.
; ============================================================================
ac307_prepare_dispatch:
        move.l  ac307_decoder_kind,d0
        beq.s   ac308_prepare_aac
        cmpi.l  #1,d0
        beq.s   ac307_prepare_ac3
        jmp     ac308_eac3_prepare
ac308_prepare_aac:
        jmp     vpv48_faad_prepare       ; exact N79Q vpv48_faad_prepare
ac307_prepare_ac3:
        jmp     ac307_ac3_prepare

; Load/init the hardware-confirmed AC305 berry_ac3.module using the same
; BerryCore mailbox and buffer geometry already proven by N79Q/FAAD.
; D0=0 success, D0=1 failure.
ac307_ac3_prepare:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv48_faad_ready       ; vpv48_faad_ready
        bne.w   ac307_ap_ok

        clr.l   vpv48_faad_module_loaded       ; module_loaded
        clr.l   vpv48_sequence       ; sequence
        clr.b   vpv48_module_dma_active       ; module_dma_active
        clr.b   vpv48_input_dma_active       ; input_dma_active
        clr.b   vpv48_output_dma_active       ; output_dma_active
        clr.b   vpv48_work_dma_active       ; work_dma_active

        move.l  #$00002000,d0              ; mail alloc
        jsr     vpv48_alloc_aligned       ; vpv48_alloc_aligned
        tst.l   d0
        beq.w   ac307_ap_fail
        move.l  d0,vpv48_mail_raw
        move.l  d1,vpv48_mail_ptr

        move.l  #$00023109,d0              ; existing module allocation (143625)
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   ac307_ap_fail
        move.l  d0,vpv48_module_raw
        move.l  d1,vpv48_module_ptr

        move.l  #$00021000,d0              ; input alloc
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   ac307_ap_fail
        move.l  d0,vpv48_input_raw
        move.l  d1,vpv48_input_ptr

        move.l  #$00012000,d0              ; output alloc
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   ac307_ap_fail
        move.l  d0,vpv48_output_raw
        move.l  d1,vpv48_output_ptr

        move.l  #$00041000,d0              ; work alloc
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   ac307_ap_fail
        move.l  d0,vpv48_work_raw
        move.l  d1,vpv48_work_ptr

        ; DOS Open/Read/Close. a5 is the DOS base established by bvp_engine_env.
        move.l  a5,a6
        lea     ac307_ac3_modulename_progdir,a0
        move.l  a0,d1
        move.l  #1005,d2                   ; MODE_OLDFILE
        jsr     -30(a6)                    ; Open()
        tst.l   d0
        bne.s   ac307_ap_have_file
        lea     ac307_ac3_modulename,a0
        move.l  a0,d1
        move.l  #1005,d2
        jsr     -30(a6)
        tst.l   d0
        beq.w   ac307_ap_fail
ac307_ap_have_file:
        move.l  d0,vpv48_module_file    ; module_file
        move.l  d0,d1
        move.l  vpv48_module_ptr,d2    ; module_ptr
        move.l  #$00008360,d3              ; exact AC305 module size 33632
        jsr     -42(a6)                    ; Read()
        move.l  d0,d7
        move.l  vpv48_module_file,d1
        jsr     -36(a6)                    ; Close()
        clr.l   vpv48_module_file
        cmpi.l  #$00008360,d7
        bne.w   ac307_ap_fail

        ; Publish module to CPU1.
        move.l  #$00008360,vpv48_dma_module_len ; dma_module_len
        move.l  vpv48_module_ptr,a0
        lea     vpv48_dma_module_len,a1
        moveq   #8,d0                      ; DMA_ReadFromRAM
        move.l  4.w,a6
        jsr     -762(a6)                   ; CachePreDMA
        move.l  d0,vpv48_module_phys    ; module_phys
        move.b  #1,vpv48_module_dma_active
        cmpi.l  #$00008360,vpv48_dma_module_len
        bne.w   ac307_ap_fail
        jsr     vpv48_check_phys       ; vpv48_check_phys
        tst.l   d0
        bne.w   ac307_ap_fail

        jsr     vpv48_map_output_work       ; map output/work
        tst.l   d0
        bne.w   ac307_ap_fail
        jsr     vpv48_setup_mail       ; setup mailbox
        tst.l   d0
        bne.w   ac307_ap_fail

        ; LOAD_MODULE
        move.l  vpv48_module_phys,vpv48_req_in_phys
        move.l  #$00008360,vpv48_req_in_len
        clr.l   vpv48_req_out_phys
        clr.l   vpv48_req_out_len
        clr.l   vpv48_req_param0
        clr.l   vpv48_req_param1
        clr.l   vpv48_req_work_phys
        clr.l   vpv48_req_work_len
        moveq   #3,d0                      ; LOAD_MODULE
        jsr     vpv48_send_request       ; vpv48_send_request
        tst.l   d0
        bne.w   ac307_ap_fail
        cmpi.l  #2,d1                      ; codec module
        bne.w   ac307_ap_fail
        cmpi.l  #$00008360,d2
        bne.w   ac307_ap_fail
        move.l  #1,vpv48_faad_module_loaded

        ; CALL_MODULE param0=0 -> AC3 decoder persistent init.
        clr.l   vpv48_req_in_phys
        clr.l   vpv48_req_in_len
        move.l  vpv48_output_phys,vpv48_req_out_phys
        move.l  #$00011000,vpv48_req_out_len
        clr.l   vpv48_req_param0
        clr.l   vpv48_req_param1
        move.l  vpv48_work_phys,vpv48_req_work_phys
        move.l  #$00040000,vpv48_req_work_len
        moveq   #4,d0                      ; CALL_MODULE
        jsr     vpv48_send_request
        tst.l   d0
        bne.w   ac307_ap_fail
        cmpi.l  #1,d1                      ; module returns ret.a=1
        bne.w   ac307_ap_fail

        move.l  #1,vpv48_faad_ready
ac307_ap_ok:
        moveq   #0,d0
        bra.s   ac307_ap_done
ac307_ap_fail:
        jsr     vpv48_faad_cleanup       ; existing generic cleanup
        moveq   #1,d0
ac307_ap_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; AC308N2: load/init compact E-AC3 module; downmix layout is armed only at first decode, not during ConfigAudio/init.
; It exports the same AC305-style streaming result block as the AC3 module,
; so the proven AC307 batch->PCM->MMAL path below is shared unchanged.
ac308_eac3_prepare:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv48_faad_ready       ; decoder ready
        bne.w   ac308_ep_ok

        clr.l   vpv48_faad_module_loaded       ; module_loaded
        clr.l   vpv48_sequence       ; sequence
        clr.b   vpv48_module_dma_active       ; module_dma_active
        clr.b   vpv48_input_dma_active       ; input_dma_active
        clr.b   vpv48_output_dma_active       ; output_dma_active
        clr.b   vpv48_work_dma_active       ; work_dma_active

        move.l  #$00002000,d0              ; mail alloc
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   ac308_ep_fail
        move.l  d0,vpv48_mail_raw
        move.l  d1,vpv48_mail_ptr

        move.l  #$00023109,d0              ; module allocation, same proven geometry
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   ac308_ep_fail
        move.l  d0,vpv48_module_raw
        move.l  d1,vpv48_module_ptr

        move.l  #$00021000,d0              ; input alloc
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   ac308_ep_fail
        move.l  d0,vpv48_input_raw
        move.l  d1,vpv48_input_ptr

        move.l  #$00012000,d0              ; output alloc
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   ac308_ep_fail
        move.l  d0,vpv48_output_raw
        move.l  d1,vpv48_output_ptr

        move.l  #$00041000,d0              ; physical work buffer; E302F proved stable
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   ac308_ep_fail
        move.l  d0,vpv48_work_raw
        move.l  d1,vpv48_work_ptr

        move.l  a5,a6
        lea     ac308_eac3_modulename_progdir,a0
        move.l  a0,d1
        move.l  #1005,d2
        jsr     -30(a6)
        tst.l   d0
        bne.s   ac308_ep_have_file
        lea     ac308_eac3_modulename,a0
        move.l  a0,d1
        move.l  #1005,d2
        jsr     -30(a6)
        tst.l   d0
        beq.w   ac308_ep_fail
ac308_ep_have_file:
        move.l  d0,vpv48_module_file
        move.l  d0,d1
        move.l  vpv48_module_ptr,d2
        move.l  #$0001C3CC,d3              ; AC308N2 compact berry_eac3.module exact build size
        jsr     -42(a6)
        move.l  d0,d7
        move.l  vpv48_module_file,d1
        jsr     -36(a6)
        clr.l   vpv48_module_file
        cmpi.l  #$0001C3CC,d7
        bne.w   ac308_ep_fail

        move.l  #$0001C3CC,vpv48_dma_module_len
        move.l  vpv48_module_ptr,a0
        lea     vpv48_dma_module_len,a1
        moveq   #8,d0
        move.l  4.w,a6
        jsr     -762(a6)                   ; CachePreDMA
        move.l  d0,vpv48_module_phys
        move.b  #1,vpv48_module_dma_active
        cmpi.l  #$0001C3CC,vpv48_dma_module_len
        bne.w   ac308_ep_fail
        jsr     vpv48_check_phys
        tst.l   d0
        bne.w   ac308_ep_fail

        jsr     vpv48_map_output_work       ; map output/work
        tst.l   d0
        bne.w   ac308_ep_fail
        jsr     vpv48_setup_mail       ; setup mailbox
        tst.l   d0
        bne.w   ac308_ep_fail

        move.l  vpv48_module_phys,vpv48_req_in_phys
        move.l  #$0001C3CC,vpv48_req_in_len
        clr.l   vpv48_req_out_phys
        clr.l   vpv48_req_out_len
        clr.l   vpv48_req_param0
        clr.l   vpv48_req_param1
        clr.l   vpv48_req_work_phys
        clr.l   vpv48_req_work_len
        moveq   #3,d0                      ; LOAD_MODULE
        jsr     vpv48_send_request
        tst.l   d0
        bne.w   ac308_ep_fail
        cmpi.l  #2,d1
        bne.w   ac308_ep_fail
        cmpi.l  #$0001C3CC,d2
        bne.w   ac308_ep_fail
        move.l  #1,vpv48_faad_module_loaded

        ; E302F compatibility entry param0=0 performs all seven init stages.
        clr.l   vpv48_req_in_phys
        clr.l   vpv48_req_in_len
        move.l  vpv48_output_phys,vpv48_req_out_phys
        move.l  #$00011000,vpv48_req_out_len
        clr.l   vpv48_req_param0
        clr.l   vpv48_req_param1
        move.l  vpv48_work_phys,vpv48_req_work_phys
        move.l  #$00040000,vpv48_req_work_len
        moveq   #4,d0
        jsr     vpv48_send_request
        tst.l   d0
        bne.w   ac308_ep_fail
        cmpi.l  #1,d1
        bne.w   ac308_ep_fail

        move.l  #1,vpv48_faad_ready
ac308_ep_ok:
        moveq   #0,d0
        bra.s   ac308_ep_done
ac308_ep_fail:
        jsr     vpv48_faad_cleanup
        moveq   #1,d0
ac308_ep_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

        even

; FAST13 HUNK0-local trampoline. Kept at the end of HUNK0 so no existing
; HUNK0 instruction address changes. Diagnostic-only jump into HUNK4.
fast13_h0_trampoline:
        jmp     fast13_submit_trace_hook
        even

        section n10d_trace_data,data
