; ===========================================================================
; Stage 4N10D - PRISTINE STAGE4K VIDEO + PROVEN VPr/VPv AUDIO-RENDER INIT
; plus close-stamp trace only
; ---------------------------------------------------------------------------
; The complete Stage4K video body above is pristine except for four public
; vector pointers.  SendVideo itself is the exact Stage4K implementation.
; Audio is added in a separate hunk after BVPL_ModuleEnd.
; ===========================================================================
        section bvp_n9_audio_code,code

BVP_GetVersionN9:
        move.l  #$00030050,d0           ; N80: 3.80 (P35 reports 3.28)
        rts

; N16 VIDEO-ONLY CONTROL.  Keep the N13 video backend bit-for-bit in source
; and make the public AAC vectors acknowledge packets without creating
; ril.audio_render, loading BerryFAAD03 or issuing any audio VCHIQ traffic.
; This isolates the first-video MMAL_ENOSPC from all audio resource usage.
BVP_ConfigAudioN14:
        move.l  a6,bvp_libbase_global
        cmp.l   #BVP_STATE_OPEN,BVP_STATE(a6)
        beq.s   N16_CA_StateOK
        cmp.l   #BVP_STATE_PAUSED,BVP_STATE(a6)
        beq.s   N16_CA_StateOK
        moveq   #BVPERR_BADSTATE,d0
        bra.s   N16_CA_Done
N16_CA_StateOK:
        cmp.l   #BVP_CODEC_AAC,d0
        bne.s   N16_CA_Unsup
        tst.l   d1
        beq.s   N16_CA_Bad
        cmpi.l  #2,d2
        bne.s   N16_CA_Unsup
        tst.l   d3
        beq.s   N16_CA_Bad
        move.l  d0,BVP_AUDIO_CODEC(a6)
        move.l  d1,BVP_AUDIO_RATE(a6)
        move.l  d2,BVP_AUDIO_CHANNELS(a6)
        move.l  d3,BVP_AUDIO_TIMESCALE(a6)
        clr.l   BVP_AUDIO_ATTEMPTS(a6)
        clr.l   n9_audio_ready
        ori.l   #BVP_CFG_AUDIO,BVP_CONFIG_FLAGS(a6)
        lea     n14_msg_audio_bypass_cfg,a1
        jsr     n12_log
        moveq   #BVP_OK,d0
        bra.s   N16_CA_Done
N16_CA_Unsup:
        moveq   #BVPERR_UNSUPPORTED,d0
        bra.s   N16_CA_Done
N16_CA_Bad:
        moveq   #BVPERR_BADPARAM,d0
N16_CA_Done:
        move.l  d0,BVP_LAST_ERROR(a6)
        rts

; A0=data, D0=len, D1/D2=PTS, D3 flags.  Intentional no-op.
BVP_SendAudioN14:
        cmp.l   #BVP_STATE_OPEN,BVP_STATE(a6)
        beq.s   N16_SA_StateOK
        cmp.l   #BVP_STATE_PAUSED,BVP_STATE(a6)
        beq.s   N16_SA_StateOK
        moveq   #BVPERR_BADSTATE,d0
        bra.s   N16_SA_Done
N16_SA_StateOK:
        move.l  BVP_CONFIG_FLAGS(a6),d0
        btst    #1,d0
        beq.s   N16_SA_BadState
        move.l  a0,d0
        beq.s   N16_SA_BadParam
        tst.l   d0
        ; A0 nonzero above; restore packet length from caller D0 is no longer
        ; available after the pointer test, so packet length validation is
        ; intentionally omitted in this diagnostic no-op vector.
        addq.l  #1,BVP_AUDIO_ATTEMPTS(a6)
        moveq   #BVP_OK,d0
        bra.s   N16_SA_Done
N16_SA_BadState:
        moveq   #BVPERR_BADSTATE,d0
        bra.s   N16_SA_Done
N16_SA_BadParam:
        moveq   #BVPERR_BADPARAM,d0
N16_SA_Done:
        move.l  d0,BVP_LAST_ERROR(a6)
        rts

BVP_CloseStreamN9:
        move.l  a6,bvp_libbase_global
        movem.l d1-d7/a0-a5,-(sp)
        jsr     p96w_clk_close            ; P96W32: before the teardown
        jsr     o2_close                  ; O2: wait for an OSD reply, log
        clr.l   p96w20_fast               ; P96W20: normal pause for teardown
        lea     n11_name_close_in,a1
        jsr     n12_log
        jsr     p96w_clk_log

        ; P96W40: after a 6-s transfer timeout the VideoCore no longer answers.
        ; Every further wait below (final AU, TX close, audio flush, CPU1 audio)
        ; would only time out again or spin (W39: 3 x 6 s, then hung in the
        ; audio teardown).  Skip straight to the summary and forced cleanup.
        tst.l   p96w_wait_timeouts
        bne.w   N65_CS_AudioTransportDone

        ; N69: publish the final library-owned compressed AU before video EOS.
        ; The force loop keeps deferred PCM service alive while waiting for its
        ; absolute native-frame deadline.
        jsr     bvp_engine_env
        tst.l   n66_video_pending
        beq.s   N69_CS_VideoPendingDone
        addq.l  #1,n66_video_forced_waits
        jsr     n66_force_pending_video
        tst.l   d0
        beq.s   N69_CS_VideoPendingDone
        moveq   #BVPERR_BACKEND,d7
        bra.s   N69_CS_VideoPendingDone
N69_CS_VideoPendingDone:
        jsr     p96w8_close_tx

        ; N30: flush the final partial VPr8-style AAC batch before video EOS.
        ; Then only the serialized BULK transport must be idle; renderer-owned
        ; PCM slots may remain outstanding until the ordinary MMAL close.
        tst.l   n9_audio_ready
        beq.s   N65_CS_AudioTransportDone
        jsr     bvp_engine_env
        tst.l   n30_batch_frames
        beq.s   N65_CS_NoPartialBatch
        bsr     n30_flush_audio_batch
N65_CS_NoPartialBatch:
        jsr     p96w_async_finish
        tst.l   n65_audio_pending
        beq.s   N65_CS_NoDeferredPCM
        addq.l  #1,n65_audio_forced_waits
        jsr     n65_force_pending_audio
N65_CS_NoDeferredPCM:
        bsr     n29_wait_audio_transport_idle
N65_CS_AudioTransportDone:

        ; Final summary is outside the live path.
        move.l  bvp_libbase_global,a0
        move.l  BVP_AUDIO_ATTEMPTS(a0),d0
        lea     n19_pfx_final_audio_attempts,a1
        jsr     n15_log_hex32
        move.l  n11_audio_returns,d0
        lea     n19_pfx_final_audio_returns,a1
        jsr     n15_log_hex32
        move.l  bvp_libbase_global,a0
        move.l  BVP_VIDEO_ATTEMPTS(a0),d0
        lea     n19_pfx_final_video_attempts,a1
        jsr     n15_log_hex32
        move.l  input_return_total,d0
        lea     n19_pfx_final_video_returns,a1
        jsr     n15_log_hex32
        move.l  vpv139_input_inuse_peak,d0
        lea     n21_pfx_input_peak,a1
        jsr     n15_log_hex32
        move.l  vpv140_input_pool_exhausted,d0
        lea     n21_pfx_pool_exhausted,a1
        jsr     n15_log_hex32
        move.l  bvp_n21_feed_retries,d0
        lea     n21_pfx_feed_retries,a1
        jsr     n15_log_hex32
        move.l  n29_audio_inflight_peak,d0
        lea     n29_pfx_audio_peak,a1
        jsr     n15_log_hex32
        move.l  n29_audio_slot_waits,d0
        lea     n29_pfx_audio_slot_waits,a1
        jsr     n15_log_hex32
        move.l  vpv47_inflight,d0
        lea     n29_pfx_audio_inflight_close,a1
        jsr     n15_log_hex32
        move.l  n30_total_aac_frames,d0
        lea     n30_pfx_aac_frames,a1
        jsr     n15_log_hex32
        move.l  n30_decode_batches,d0
        lea     n30_pfx_decode_batches,a1
        jsr     n15_log_hex32
        move.l  n30_pcm_submits,d0
        lea     n30_pfx_pcm_submits,a1
        jsr     n15_log_hex32
        move.l  n30_partial_consumes,d0
        lea     n30_pfx_partial_consumes,a1
        jsr     n15_log_hex32
        move.l  n30_pcm_max,d0
        lea     n30_pfx_pcm_max,a1
        jsr     n15_log_hex32
        move.l  n65_audio_deferred_blocks,d0
        lea     n65_pfx_deferred_blocks,a1
        jsr     n15_log_hex32
        move.l  n65_audio_service_calls,d0
        lea     n65_pfx_service_calls,a1
        jsr     n15_log_hex32
        move.l  n65_audio_service_publishes,d0
