        jsr     n15_log_hex32
        move.l  n65_audio_pending,d0
        lea     n65_pfx_pending_close,a1
        jsr     n15_log_hex32
        move.l  n66_video_enqueued,d0
        lea     n66_pfx_video_enqueued,a1
        jsr     n15_log_hex32
        move.l  n66_video_service_calls,d0
        lea     n66_pfx_video_service_calls,a1
        jsr     n15_log_hex32
        move.l  n66_video_service_submits,d0
        lea     n66_pfx_video_service_submits,a1
        jsr     n15_log_hex32
        move.l  n66_video_service_defers,d0
