        jsr     n15_log_hex32
        move.l  n66_video_service_failures,d0
        lea     n66_pfx_video_service_failures,a1
        jsr     n15_log_hex32
        move.l  n66_video_pending,d0
        lea     n66_pfx_video_pending_close,a1
        jsr     n15_log_hex32
        move.l  n69_dispatch_entries,d0
        lea     n69_pfx_dispatch_entries,a1
        jsr     n15_log_hex32
        move.l  n69_dispatch_loops,d0
        lea     n69_pfx_dispatch_loops,a1
        jsr     n15_log_hex32
