        move.l  n63_video_pacer_calls,d0
        lea     n63_pfx_video_pacer_calls,a1
        jsr     n15_log_hex32
        move.l  n63_video_pacer_total_us,d0
        lea     n63_pfx_video_pacer_total,a1
        jsr     n15_log_hex32
        move.l  n63_video_pacer_max_us,d0
        lea     n63_pfx_video_pacer_max,a1
