        lea     n63_pfx_video_bulk_max,a1
        jsr     n15_log_hex32

        ; n12_log needs the still-open DOS base.  Emit the normal tail marker
        ; before BVP_CloseStream closes DOS/MMAL/VCHIQ.
        lea     n11_name_close_tail,a1
        jsr     n12_log

        movem.l (sp)+,d1-d7/a0-a5
        move.l  bvp_libbase_global,a6

        ; Let the ordinary BerryVP close path send video EOS and close MMAL/VCHIQ
        ; while any final renderer-owned PCM buffer is still valid. Preserve its
        ; public return code on the stack across the post-close cleanup.
        jsr     BVP_CloseStream
        move.l  d0,-(sp)

        ; MMAL is now closed. Reclaim cache ownership and free CPU1/PCM state.
        movem.l d1-d7/a0-a5,-(sp)
        jsr     bvp_engine_env
        tst.l   n9_audio_ready
        beq.s   N65_CS_AudioFreeDone
        bsr     n29_audio_post_after_service_close
        jsr     vpv48_faad_cleanup
