        clr.l   vpv39_audio_bulk_pending
        clr.l   vpv39_audio_armed
        clr.l   n65_audio_pending
        movem.l (sp)+,d1-d7/a0-a5
        move.l  (sp)+,d0
        move.l  bvp_libbase_global,a6
        rts

