        section bvp_n9_audio_code,code

; D0=codec, D1=rate, D2=channels, D3=timescale.
BVP_ConfigAudioN9:
        move.l  a6,bvp_libbase_global
        movem.l d4-d7/a0-a5,-(sp)
        cmp.l   #BVP_STATE_OPEN,BVP_STATE(a6)
        beq.s   N9_CA_StateOK
        cmp.l   #BVP_STATE_PAUSED,BVP_STATE(a6)
        beq.s   N9_CA_StateOK
        moveq   #BVPERR_BADSTATE,d0
        bra.w   N9_CA_Done
N9_CA_StateOK:
        cmp.l   #BVP_CODEC_AAC,d0
        bne.w   N9_CA_Unsup
        cmpi.l  #8000,d1
        bcs.w   N9_CA_Bad
        cmpi.l  #192000,d1
        bhi.w   N9_CA_Bad
        cmpi.l  #2,d2
        bne.w   N9_CA_Unsup
        tst.l   d3
        beq.w   N9_CA_Bad
        tst.l   bvp_backend_ready
        beq.w   N9_CA_NoBackend

        clr.l   BVP_AUDIO_ATTEMPTS(a6)
        clr.l   n11_audio_returns
        clr.l   BVP_LAST_APTS_HI(a6)
        clr.l   BVP_LAST_APTS_LO(a6)
        clr.l   BVP_LAST_AUDIO_LEN(a6)
        clr.l   n9_audio_ready
        clr.l   n9_audio_pending_ptr
        clr.l   n9_audio_pending_len
        clr.l   n9_saved_port_buf_size
        clr.l   vpv39_audio_bulk_pending
        clr.l   n65_audio_pending
        clr.l   n65_audio_pending_bytes
        clr.l   n65_audio_pending_samples
        clr.l   n65_audio_pending_pts_lo
        clr.l   n65_audio_pending_pts_hi
        clr.l   n65_audio_deferred_blocks
        clr.l   n65_audio_service_calls
        clr.l   n65_audio_service_publishes
        clr.l   n65_audio_service_defers
        clr.l   n65_audio_deferred_polls
        clr.l   n65_audio_forced_waits
        clr.l   n65_audio_service_failures
        clr.l   n73_clock_armed
        clr.l   n73_first_pcm_published
        clr.l   n73_prime_flushes
        clr.l   n73_clock_arm_attempts
        clr.l   n73_clock_arm_failures
        clr.l   vpv116_clock_probe_done
        move.l  d0,BVP_AUDIO_CODEC(a6)
        move.l  d1,BVP_AUDIO_RATE(a6)
        move.l  d2,BVP_AUDIO_CHANNELS(a6)
        move.l  d3,BVP_AUDIO_TIMESCALE(a6)

        jsr     bvp_engine_env
        lea     n10d_name_06,a1
        jsr     n12_log
        lea     n9_msg_ca_begin,a1
        move.l  #n9_msg_ca_begin_end-n9_msg_ca_begin,d3
        jsr     print_force

        ; BerryFAAD03 production format.  Mirror the VPr/VPv PCM globals before
        ; touching audio_render; this is the format consumed by the proven
        ; first-start INPUT0 configuration block.
        move.l  bvp_libbase_global,a0
        move.l  BVP_AUDIO_RATE(a0),d0
        move.l  d0,v19_pcm_rate
        move.l  d0,vpv18_stream_info+DECSTREAM_RATE
        move.l  #2,v19_pcm_channels
        move.w  #2,vpv18_stream_info+DECSTREAM_CHANNELS
        move.l  #16,v19_pcm_bits
        move.w  #16,vpv18_stream_info+DECSTREAM_BITS
        move.l  #4,v19_pcm_blockalign
        lsl.l   #5,d0
        move.l  d0,v19_pcm_bitrate

        bsr     n9_audio_alloc_pcm
        tst.l   d0
        bne.w   N9_CA_Backend
        jsr     ac307_prepare_dispatch
        tst.l   d0
        bne.w   N9_CA_BackendFree

        ; Do NOT use vpv21_prepare_audio_early here.  That helper was not the
        ; hardware-proven first-start A/V configuration path.  N9 reproduces
        ; the VPr/VPv CONTROL0/INPUT0/SET/readback/finish sequence directly.
        bsr     n9_config_audio_render_proven
        tst.l   d0
        bne.w   N9_CA_BackendFaad

        ; N30: initialize two independent renderer-owned PCM slots only.
        ; No video_scheduler, no central MMAL clock, no graph topology change.
        bsr     n29_audio_pipeline_init
        tst.l   d0
        bne.w   N9_CA_BackendFaad

        ; N79: exact VPr8 ordering correction versus N73.
        ; Build/arm the central Audio-Master clock while NO PCM/H264 buffer is
        ; in flight.  The real VPr8 path arms clock+scheduler first; only the
        ; central dispatcher publishes the first PCM afterwards.
        addq.l  #1,n73_clock_arm_attempts
        move.l  #1,vpv116_clock_probe_done
        jsr     vpv116_probe_clock_component
        tst.l   vpv117_graph_probe_ok
        beq.s   n74_ca_clock_fail
        tst.l   vpv121_audio_clock_tunnel_ok
        beq.s   n74_ca_clock_fail
        tst.l   vpv122_sched_clock_tunnel_ok
        beq.s   n74_ca_clock_fail
        tst.l   vpv124_audio_master_armed
        beq.s   n74_ca_clock_fail
        tst.l   vpv126_sched_clock_armed
        beq.s   n74_ca_clock_fail
        tst.l   vpv126_sched_component_enabled
        beq.s   n74_ca_clock_fail
        move.l  #1,n73_clock_armed
        lea     n73_msg_clock_armed,a1
        jsr     n12_log
        bra.s   n74_ca_clock_ready
n74_ca_clock_fail:
        addq.l  #1,n73_clock_arm_failures
        lea     n73_msg_clock_fail,a1
        jsr     n12_log
        bra.w   N9_CA_BackendFaad
n74_ca_clock_ready:

        move.l  #1,n9_audio_ready
        move.l  bvp_libbase_global,a6
        ori.l   #BVP_CFG_AUDIO,BVP_CONFIG_FLAGS(a6)
        lea     n10d_name_07,a1
        jsr     n12_log
        lea     n11_name_ready,a1
        jsr     n12_log
        lea     n19_msg_quiet_live,a1
        jsr     n12_log
        lea     n9_msg_ca_ready,a1
        move.l  #n9_msg_ca_ready_end-n9_msg_ca_ready,d3
        jsr     print_force
        moveq   #BVP_OK,d0
        bra.s   N9_CA_Done
N9_CA_BackendFaad:
        jsr     vpv48_faad_cleanup
N9_CA_BackendFree:
        jsr     vpv21_free_pcm
N9_CA_Backend:
        moveq   #BVPERR_BACKEND,d0
        bra.s   N9_CA_Done
N9_CA_NoBackend:
        moveq   #BVPERR_NOBACKEND,d0
        bra.s   N9_CA_Done
N9_CA_Unsup:
        moveq   #BVPERR_UNSUPPORTED,d0
        bra.s   N9_CA_Done
N9_CA_Bad:
        moveq   #BVPERR_BADPARAM,d0
N9_CA_Done:
        move.l  bvp_libbase_global,a6
        move.l  d0,BVP_LAST_ERROR(a6)
        movem.l (sp)+,d4-d7/a0-a5
        rts

; Exact operational sequence of the hardware-proven VPr/VPv first-start
; audio_render setup, adapted only so it can be called after Stage4K CONFIG has
; built the quiescent video graph.  No audio buffer is submitted here.
n9_config_audio_render_proven:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv21_audio_prepared
        move.l  component_handle,n9_saved_component
        move.l  input_port_handle,n9_saved_input
        move.l  port_query_type,n9_saved_qtype
        move.l  port_query_index,n9_saved_qidx
        move.l  port_buf_size,n9_saved_bufsize

        jsr     vpv01_create_audio_render
        tst.l   d0
        bne.w   n9_car_fail

        ; CONTROL0 GET.
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        move.l  #1,v12a_local_get_active
        jsr     port_info_get
        clr.l   v12a_local_get_active
        tst.l   d0
        bne.w   n9_car_fail
        move.l  port_last_handle,vpv01_audio_control

        ; INPUT0 GET.
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        move.l  #1,v12a_local_get_active
        jsr     port_info_get
        clr.l   v12a_local_get_active
        tst.l   d0
        bne.w   n9_car_fail
        move.l  port_last_handle,vpv01_audio_input
        move.l  vpv01_audio_input,input_port_handle

        ; Proven PCM INPUT0 PORT_INFO_SET: stereo signed LE PCM, two renderer
        ; buffers, 64 KiB input size unless firmware minimum is larger.
        move.l  #MMAL_ES_AUDIO,port_fmt_type
        move.l  #MMAL_ENCODING_PCM_SIGNED_LE,port_fmt_encoding
        clr.l   port_fmt_variant
        move.l  v19_pcm_bitrate,d0
        move.l  d0,port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v19_pcm_channels,d0
        move.l  d0,port_video_width
        move.l  v19_pcm_rate,d0
        move.l  d0,port_video_height
        move.l  v19_pcm_bits,d0
        move.l  d0,port_crop_x
        move.l  v19_pcm_blockalign,d0
        move.l  d0,port_crop_y
        clr.l   port_crop_width
        clr.l   port_crop_height
        clr.l   port_fps_num
        clr.l   port_fps_den
        clr.l   port_par_num
        clr.l   port_par_den
        clr.l   port_color_space
        moveq   #2,d0
        move.l  d0,port_buf_num
        move.l  #$00010000,d0
        cmp.l   port_buf_size_min,d0
        bcc.s   n9_car_size_ok
        move.l  port_buf_size_min,d0
n9_car_size_ok:
        cmp.l   #INPUT_DATA_SIZE,d0
        bhi.w   n9_car_fail
        move.l  d0,port_buf_size
        clr.l   vpv30_skipped
        clr.l   vpv30_async_skipped
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   n9_car_fail

        ; Proven readback before destination/enable/component-enable.
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        move.l  #1,v12a_local_get_active
        jsr     port_info_get
        clr.l   v12a_local_get_active
        tst.l   d0
        bne.w   n9_car_fail

        jsr     vpv35_finish_audio_enable
        tst.l   d0
        bne.s   n9_car_fail
        move.l  port_buf_size,vpv21_audio_port_buf_size
        moveq   #0,d7
        bra.s   n9_car_restore
n9_car_fail:
        clr.l   vpv21_audio_prepared
        moveq   #1,d7
n9_car_restore:
        clr.l   v12a_local_get_active
        clr.l   v12c_local_set_active
        move.l  n9_saved_component,component_handle
        move.l  n9_saved_input,input_port_handle
        move.l  n9_saved_qtype,port_query_type
        move.l  n9_saved_qidx,port_query_index
        move.l  n9_saved_bufsize,port_buf_size
        move.l  d7,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; A0=ADTS, D0=len, D1/D2=PTS, D3 reserved.
; N30: VPr8-style 64-KiB PCM batching. MintVID may still call once per ADTS
; packet, but 16 AAC frames are accumulated in the existing DMA-safe FAAD input
; staging buffer and decoded/submitted as one batch. This removes the thousands
; of per-frame ARM1 + MMAL transactions seen by N28 while preserving the N21
; four-slot video path and the N30/N29 two-slot audio renderer ownership model.
BVP_SendAudioN9:
        move.l  a6,bvp_libbase_global
        movem.l d4-d7/a1-a5,-(sp)
        move.l  d0,d4
        move.l  d1,d5
        move.l  d2,d6
        cmp.l   #BVP_STATE_OPEN,BVP_STATE(a6)
        beq.s   N9_SA_StateOK
        cmp.l   #BVP_STATE_PAUSED,BVP_STATE(a6)
        beq.s   N9_SA_StateOK
        moveq   #BVPERR_BADSTATE,d0
        bra.w   N9_SA_Done
N9_SA_StateOK:
        move.l  BVP_CONFIG_FLAGS(a6),d0
        btst    #1,d0
        beq.w   N9_SA_BadState
        tst.l   n9_audio_ready
        beq.w   N9_SA_NoBackend
        tst.l   n79p96g_audio_trace_state
        bne.s   n79p96g_sa_a01_done
        lea     n79p96g_a01,a1
        jsr     n12_log
        move.l  #1,n79p96g_audio_trace_state
n79p96g_sa_a01_done:
        ; N65: one nonblocking service pass on every AAC API entry.  This keeps
        ; renderer returns moving and publishes deferred PCM as soon as a slot
        ; and the single global BULK transport are immediately available.
        move.l  a0,-(sp)
        move.l  d4,-(sp)
        jsr     bvp_engine_env
        ; P96W4/P96W22: in the P96 window AAC, AC3 and E-AC3 decode
        ; asynchronously on CPU1 (same mailbox, buffers and module call).
        clr.l   p96w_async_on
        tst.l   bvp_p96_mode
        beq.s   p96w_sa_async_set
        move.l  #1,p96w_async_on
p96w_sa_async_set:
        jsr     p96w_present              ; P96W37
        jsr     p96w_async_poll_nb
        jsr     bvp_engine_env
        jsr     n65_service_pending_audio
        tst.l   d0
        bne.s   N69_SA_ServiceDone
        jsr     n66_service_pending_video
N69_SA_ServiceDone:
        move.l  d0,d1
        move.l  (sp)+,d4
        move.l  (sp)+,a0
        tst.l   d1
        bne.w   N9_SA_Backend
        move.l  a0,d0
        beq.w   N9_SA_BadParam
        tst.l   d4
        beq.w   N9_SA_BadParam
        cmpi.l  #VPV48_FAAD_INPUT_SIZE,d4
        bhi.w   N9_SA_TooLarge
        addq.l  #1,BVP_AUDIO_ATTEMPTS(a6)
        move.l  d5,BVP_LAST_APTS_HI(a6)
        move.l  d6,BVP_LAST_APTS_LO(a6)
        move.l  d4,BVP_LAST_AUDIO_LEN(a6)

        ; A single caller packet must fit behind the currently staged ADTS data.
        ; With trailer.mkv this is only a few hundred bytes per frame; the full
        ; VPr8 FAAD staging area is 128 KiB.
        move.l  n30_batch_bytes,d0
        add.l   d4,d0
        cmpi.l  #VPV48_FAAD_INPUT_SIZE,d0
        bhi.w   N9_SA_TooLarge

        ; The batch PTS is the PTS of its first AAC frame.
        tst.l   n30_batch_frames
        bne.s   n30_sa_have_pts
        move.l  d5,n30_batch_pts_hi
        move.l  d6,n30_batch_pts_lo
n30_sa_have_pts:

        ; Copy this ADTS packet into the already allocated CPU1 input staging
        ; buffer. It remains CPU-owned until n30_flush_audio_batch maps it.
        ; P96W4: async mode stages into a separate host buffer, because CPU1
        ; may still be reading vpv48_input_ptr for the previous batch.
        move.l  vpv48_input_ptr,a1
        tst.l   p96w_async_on
        beq.s   p96w_stage_sel_done
        lea     p96w_stage,a1
p96w_stage_sel_done:
        move.l  n30_batch_bytes,d0
        adda.l  d0,a1
        move.l  a0,a2
        move.l  d4,d3
        move.l  d3,d2
        lsr.l   #2,d2
        beq.s   n30_sa_copy_tail
n30_sa_copy_long:
        move.l  (a2)+,(a1)+
        subq.l  #1,d2
        bne.s   n30_sa_copy_long
n30_sa_copy_tail:
        andi.l  #3,d3
        beq.s   n30_sa_copy_done
n30_sa_copy_byte:
        move.b  (a2)+,(a1)+
        subq.l  #1,d3
        bne.s   n30_sa_copy_byte
n30_sa_copy_done:
        add.l   d4,n30_batch_bytes
        addq.l  #1,n30_batch_frames
        addq.l  #1,n30_total_aac_frames

        ; N79 VPr8 startup: before ANY H264 AU is admitted by mrberry, decode
        ; a tiny two-AAC prefix.  Frame 1 is FAAD priming; frame 2 yields real
        ; PCM on the tested trailer.  After the first PCM publish has armed the
        ; Audio-Master clock, return to the proven 16-frame / 64-KiB cadence.
        ; AC307A: codec-aware batch threshold. This replaces exactly the old
        ; N79Q 2/16-frame decision block; AAC behavior is preserved by helper.
        jsr     ac307_should_flush
        tst.l   d0
        beq.s   ac307_threshold_no_flush
        rept    16
        nop
        endr
        ; Existing N79Q flush sequence starts here (same original offset).
n73_sa_flush_batch:

        jsr     bvp_engine_env
        bsr     n30_flush_audio_batch
        tst.l   d0
        bne.w   N9_SA_Backend
N9_SA_OK:
ac307_threshold_no_flush:
        jsr     bvp_engine_env
        jsr     n66_service_pending_video
        tst.l   d0
        bne.w   N9_SA_Backend
        addq.l  #1,n11_audio_returns
        moveq   #BVP_OK,d0
        bra.s   N9_SA_Done
N9_SA_Backend:
        lea     n12_msg_a_backend_err,a1
        jsr     n12_log
        lea     n11_name_aerr,a1
        jsr     n12_log
        moveq   #BVPERR_BACKEND,d0
        bra.s   N9_SA_Done
N9_SA_Config:
        lea     n12_msg_a_config_err,a1
        jsr     n12_log
        moveq   #BVPERR_CONFIG,d0
        bra.s   N9_SA_Done
N9_SA_BadState:
        lea     n12_msg_a_badstate,a1
        jsr     n12_log
        moveq   #BVPERR_BADSTATE,d0
        bra.s   N9_SA_Done
N9_SA_BadParam:
        lea     n12_msg_a_badparam,a1
        jsr     n12_log
        moveq   #BVPERR_BADPARAM,d0
        bra.s   N9_SA_Done
N9_SA_NoBackend:
        lea     n12_msg_a_nobackend,a1
        jsr     n12_log
        moveq   #BVPERR_NOBACKEND,d0
        bra.s   N9_SA_Done
N9_SA_TooLarge:
        lea     n12_msg_a_toolarge,a1
        jsr     n12_log
        moveq   #BVPERR_TOOLARGE,d0
N9_SA_Done:
        move.l  bvp_libbase_global,a6
        move.l  d0,BVP_LAST_ERROR(a6)
        movem.l (sp)+,d4-d7/a1-a5
        rts

; ---------------------------------------------------------------------------
; N65 VPr8-style 64-KiB audio batching.
; Decode the ADTS bytes already staged in vpv48_input_ptr and submit the
; resulting large PCM block through N30/N29's two renderer slots. D0=0/1.
; This routine is intentionally synchronous only once per ~16 AAC frames;
; the next step can replace its CPU1 call with VPr8's async launch/poll if
; batching alone is still insufficient.
; ---------------------------------------------------------------------------
n30_flush_audio_batch:
        tst.l   p96w_async_on
        beq.s   n30_fab_sync
        jmp     p96w_async_flush
n30_fab_sync:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   n30_batch_frames
        bne.s   n30_fab_have
        moveq   #0,d0
        bra.w   n30_fab_done
n30_fab_have:
        ; N65 normally drains the previous PCM block from video/audio API idle
        ; opportunities.  This bounded fallback protects the single 64-KiB
        ; staging store before a later batch can overwrite it.
        tst.l   n65_audio_pending
        beq.s   n65_fab_previous_clear
        addq.l  #1,n65_audio_forced_waits
        jsr     n65_force_pending_audio
        tst.l   d0
        bne.w   n30_fab_fail
n65_fab_previous_clear:
        jsr     vpv98_read_sys_us
        move.l  d0,n54_flush_start_us
        move.l  vpv48_input_ptr,n9_audio_pending_ptr
        move.l  n30_batch_bytes,n9_audio_pending_len
        jsr     vpv98_read_sys_us
        move.l  d0,n54_phase_start_us
        bsr.w   ac307_decode_dispatch
        move.l  d0,n54_saved_result
        jsr     vpv98_read_sys_us
        sub.l   n54_phase_start_us,d0
        add.l   d0,n54_faad_total_us
        cmp.l   n54_faad_max_us,d0
        bls.s   n54_faad_time_ok
        move.l  d0,n54_faad_max_us
n54_faad_time_ok:
        move.l  n54_saved_result,d0
        tst.l   d0
        bne.w   n30_fab_fail

        ; For this test every staged batch must be consumed completely. If the
        ; FAAD output limit ever leaves compressed tail bytes, stop rather than
        ; silently dropping them; the trace counter makes that case explicit.
        move.l  vpv48_last_consumed,d0
        cmp.l   n30_batch_bytes,d0
        beq.s   n30_fab_consumed
        addq.l  #1,n30_partial_consumes
        bra.w   n30_fab_fail
n30_fab_consumed:
        addq.l  #1,n30_decode_batches
        move.l  vpv48_last_pcm_bytes,d0
        cmp.l   n30_pcm_max,d0
        bls.s   n30_fab_pcmmax_done
        move.l  d0,n30_pcm_max
n30_fab_pcmmax_done:
        tst.l   d0
        beq.w   n30_fab_reset_ok       ; FAAD priming-only batch
        cmpi.l  #1,n79p96g_audio_trace_state
        bne.s   n79p96g_fab_a02_done
        lea     n79p96g_a02,a1
        jsr     n12_log
        move.l  #2,n79p96g_audio_trace_state
n79p96g_fab_a02_done:
        move.l  bvp_libbase_global,a0
        move.l  BVP_AUDIO_RATE(a0),d1
        cmp.l   v19_pcm_rate,d1
        bne.w   n30_fab_fail
        cmpi.l  #VPV21_PCM_MAX_BYTES,d0
        bhi.w   n30_fab_fail

        ; N65: decoding is complete and vpv38_pcm_store is CPU-owned.  Do NOT
        ; wait here for a renderer slot or BULK_TX_DONE.  Keep the block pending
        ; and let subsequent SendAudio/SendVideo pacing opportunities publish it.
        move.l  vpv48_last_pcm_bytes,n65_audio_pending_bytes
        move.l  vpv48_last_samples_ch,n65_audio_pending_samples
        move.l  n30_batch_pts_lo,n65_audio_pending_pts_lo
        move.l  n30_batch_pts_hi,n65_audio_pending_pts_hi
        move.l  #1,n65_audio_pending
        addq.l  #1,n65_audio_deferred_blocks
        cmpi.l  #2,n79p96g_audio_trace_state
        bne.s   n79p96g_fab_a03_done
        lea     n79p96g_a03,a1
        jsr     n12_log
        move.l  #3,n79p96g_audio_trace_state
n79p96g_fab_a03_done:

        ; One immediate nonblocking attempt is cheap when a slot is already free.
        ; A successful publish waits only for its short serialized BULK_TX_DONE;
        ; it never waits for a renderer BUFFER_TO_HOST.
        jsr     n65_service_pending_audio
        tst.l   d0
        bne.w   n30_fab_fail

n30_fab_reset_ok:
        bsr     n54_finish_flush_timing
        clr.l   n30_batch_bytes
        clr.l   n30_batch_frames
        clr.l   n30_batch_pts_hi
        clr.l   n30_batch_pts_lo
        moveq   #0,d0
        bra.s   n30_fab_done
n30_fab_fail:
        bsr     n54_finish_flush_timing
        moveq   #1,d0
n30_fab_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

n54_finish_flush_timing:
        movem.l d0-d1,-(sp)
        jsr     vpv98_read_sys_us
        sub.l   n54_flush_start_us,d0
        add.l   d0,n54_flush_total_us
        cmp.l   n54_flush_max_us,d0
        bls.s   n54_fft_done
        move.l  d0,n54_flush_max_us
n54_fft_done:
        movem.l (sp)+,d0-d1
        rts

; ---------------------------------------------------------------------------
; N65 - deferred PCM service for the MintVID library API.
;
; Public library calls must still return with VCHIQ shared RAM CPU-owned.
; Therefore this is NOT the broken N56 model: no BULK remains live across an
; API return.  The key change is that SendAudio no longer waits for a free
; renderer slot.  A decoded 64-KiB block stays CPU-side until a later API/pacer
; opportunity sees transport + slot ready.  Publication then waits only for the
; short serialized AUDIO BULK_TX_DONE; renderer ownership may continue.
; D0=0 success/deferred, D0=1 hard failure.
; ---------------------------------------------------------------------------
n65_service_pending_audio:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   n65_audio_pending
        bne.s   n65_svc_have
        moveq   #0,d0
        bra.w   n65_svc_done
n65_svc_have:
        addq.l  #1,n65_audio_service_calls
        bsr     n29_audio_reap_slots

        ; Fast path: no ownership wait.  Publish only when the globally
        ; serialized transport and one renderer slot are free right now.
        tst.l   input_bulk_pending
        bne.s   n65_svc_poll_once
        tst.l   vpv39_audio_bulk_pending
        bne.s   n65_svc_poll_once
        ; P96W11: in the P96 window keep the VPberry/mkvr7 rule strictly:
        ; NO audio BULK_TX while the window-frame BULK_RX is active.
        tst.l   bvp_p96_mode
        beq.s   p96w11_fast_rx_ok
        tst.l   output_bulk_queued
        bne.s   n65_svc_poll_once
p96w11_fast_rx_ok:
        ; N79P96G diagnostic: allow AUDIO BULK_TX while P96 output BULK_RX is
        ; active. VIDEO BULK_TX remains blocked by bvp_wait_video_submit_ready.
        ; This isolates whether the old striping was caused specifically by
        ; compressed-video TX/RX overlap rather than opposite-direction audio.
        tst.l   vpv47_slot_state
        beq.s   n65_svc_slot0
        tst.l   vpv47_slot_state+4
        beq.s   n65_svc_slot1

n65_svc_poll_once:
        ; Give VideoCore one short service window and consume all RX messages
        ; already queued in that snapshot.  No bounded wait loop lives here.
        addq.l  #1,n65_audio_deferred_polls
        jsr     dma_pre_all
        jsr     short_delay
        jsr     dma_post_all
        moveq   #7,d7
n65_svc_rx_loop:
        move.l  slot_ptr,a0
        lea     60(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bls.s   n65_svc_after_rx
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   n65_svc_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,bulk_rx_size
        jsr     v9g_h19_dispatch
        tst.l   v10h_error_seen
        bne.w   n65_svc_fail
        dbra    d7,n65_svc_rx_loop
n65_svc_after_rx:
        bsr     n29_audio_reap_slots
        tst.l   input_bulk_pending
        bne.w   n65_svc_defer
        tst.l   vpv39_audio_bulk_pending
        bne.w   n65_svc_defer
        tst.l   bvp_p96_mode
        beq.s   p96w11_slow_rx_ok
        tst.l   output_bulk_queued
        bne.w   n65_svc_defer
p96w11_slow_rx_ok:
        ; N79P96G: AUDIO is the one exception to P96 RX serialization.
        ; Do not defer merely because output_bulk_queued is active.
        tst.l   vpv47_slot_state
        beq.s   n65_svc_slot0
        tst.l   vpv47_slot_state+4
        beq.s   n65_svc_slot1
        bra.w   n65_svc_defer

n65_svc_slot0:
        clr.l   n29_audio_selected_slot
        bra.s   n65_svc_publish
n65_svc_slot1:
        move.l  #1,n29_audio_selected_slot

n65_svc_publish:
        ; Recreate the proven N30 staging metadata from the deferred block.
        move.l  n65_audio_pending_bytes,d0
        tst.l   d0
        beq.w   n65_svc_fail
        move.l  d0,vpv38_pcm_store_total
        move.l  d0,vpv21_pcm_total_bytes
        lea     vpv38_pcm_block_sizes,a0
        move.l  d0,(a0)
        move.l  #1,vpv38_pcm_block_count
        move.l  n65_audio_pending_samples,d1
        move.l  d1,vpv21_pcm_total_samples
        clr.l   vpv39_audio_next_block

        move.l  n29_audio_selected_slot,d0
        jsr     vpv47_load_priming_to_slot
        tst.l   d0
        bne.w   n65_svc_fail

        move.l  n65_audio_pending_pts_lo,vpv43_audio_next_pts_ticks
        move.l  n65_audio_pending_pts_hi,vpv170_audio_next_pts_hi
        cmpi.l  #3,n79p96g_audio_trace_state
        bne.s   n79p96g_svc_a04_done
        lea     n79p96g_a04,a1
        jsr     n12_log
        move.l  #4,n79p96g_audio_trace_state
n79p96g_svc_a04_done:
        move.l  n29_audio_selected_slot,d0
        jsr     vpv47_send_audio_slot
        tst.l   d0
        bne.w   n65_svc_fail
        addq.l  #1,vpv47_inflight
        addq.l  #1,n30_pcm_submits
        addq.l  #1,n65_audio_service_publishes
        clr.l   n65_audio_pending

        move.l  vpv47_inflight,d0
        cmp.l   n29_audio_inflight_peak,d0
        bls.s   n65_svc_peak_done
        move.l  d0,n29_audio_inflight_peak
n65_svc_peak_done:
        ; vpv47_send_audio_slot deliberately leaves shared RAM DMA-owned.
        ; Wait only for the short global BULK completion so the public API can
        ; safely return CPU-owned.  Do not wait for renderer BTH/slot return.
        jsr     vpv98_read_sys_us
        move.l  d0,n54_phase_start_us
        bsr     n29_wait_audio_bulk_done
        move.l  d0,n54_saved_result
        jsr     vpv98_read_sys_us
        sub.l   n54_phase_start_us,d0
        add.l   d0,n54_bulk_total_us
        cmp.l   n54_bulk_max_us,d0
        bls.s   n65_svc_bulk_time_ok
        move.l  d0,n54_bulk_max_us
n65_svc_bulk_time_ok:
        move.l  n54_saved_result,d0
        tst.l   d0
        bne.s   n65_svc_fail
        cmpi.l  #4,n79p96g_audio_trace_state
        bne.s   n79p96g_svc_a05_done
        lea     n79p96g_a05,a1
        jsr     n12_log
        move.l  #5,n79p96g_audio_trace_state
n79p96g_svc_a05_done:

        ; N79: the clock/scheduler was already armed during ConfigAudio while
        ; transport was quiescent.  This point now proves the first real PCM
        ; BULK has actually been submitted only AFTER clock setup.
        tst.l   n73_clock_armed
        beq.s   n74_svc_clock_missing
        tst.l   n73_first_pcm_published
        bne.s   n73_svc_clock_done
        move.l  #1,n73_first_pcm_published
        bra.s   n73_svc_clock_done
n74_svc_clock_missing:
        addq.l  #1,n73_clock_arm_failures
        lea     n73_msg_clock_fail,a1
        jsr     n12_log
        bra.s   n65_svc_fail
n73_svc_clock_done:
        moveq   #0,d0
        bra.s   n65_svc_done

n65_svc_defer:
        addq.l  #1,n65_audio_service_defers
        moveq   #0,d0
        bra.s   n65_svc_done
n65_svc_fail:
        addq.l  #1,n65_audio_service_failures
        moveq   #1,d0
n65_svc_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; ---------------------------------------------------------------------------
; N69 - one-AU library-owned video pending bridge.
;
; This is the missing architectural boundary between mrberry and VPr8: public
; SendVideo can return while the next native-frame deadline is still in the
; future, so the caller may demux and deliver the intervening AAC packets.
; The queue is one AU because MintVID's next VIDEO call occurs only after all
; packets ordered before it have been handed to the bridge.  Larger AUs split
; by send_annexb are handled by the forced-old-pending path in-order.
; D0=0 success/deferred, D0=1 hard failure.
; ---------------------------------------------------------------------------
n66_service_pending_video:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   n66_video_pending
        bne.s   n66_vsvc_have
        moveq   #0,d0
        bra.w   n66_vsvc_done
n66_vsvc_have:
        addq.l  #1,n66_video_service_calls

        ; N79 scheduler mode: host no longer decides presentation time.  Once
        ; the first PCM block armed Audio-Master, submit compressed AUs as soon
        ; as transport/input ownership allows; PTS + video_scheduler decide when
        ; each decoded OPQV frame becomes visible.
        tst.l   n73_scheduler_graph_ready
        beq.s   n73_vsvc_host_pacer
        tst.l   n73_clock_armed
        bne.s   n81_vsvc_armed
        jsr     n81_try_free_clock        ; CLK81: cinema without audio
        tst.l   n73_clock_armed
        bne.s   n80_vsvc_clock_ok
        ; N80: the scheduler graph only plays once ConfigAudio armed the
        ; Audio-Master clock.  If ConfigAudio was never called (a caller
        ; that did not pass BVP_OPENF_NO_HDMI_AUDIO but has no HDMI audio)
        ; or its clock setup failed, no frame would ever be shown: fail the
        ; stream instead of waiting forever.
        tst.l   n73_clock_arm_attempts
        beq.s   n80_vsvc_no_clock
        tst.l   n73_clock_arm_failures
        beq.w   n80_defer_clock
n80_vsvc_no_clock:
        lea     n80_msg_no_clock,a1
        jsr     n12_log
        bra.w   n66_vsvc_fail
n80_vsvc_clock_ok:
n81_vsvc_armed:
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v08
        lea     n79_v08,a1
        jsr     n12_log
n79_no_v08:
        bra.w   n66_vsvc_due
n73_vsvc_host_pacer:

        ; Only FRAME_START advances the host native-frame deadline. Continuation
        ; chunks of one large AU must follow immediately once the first chunk ran.
        move.l  n66_video_pending_flags,d0
        andi.l  #BVP_PKT_FRAME_START,d0
        beq.s   n66_vsvc_due
        ; N71: direct decoder->renderer has no VideoCore scheduler queue.
        ; Feeding exactly at the nominal presentation deadline means decode +
        ; BULK latency is paid AFTER the deadline.  Allow a 25-ms compressed-AU
        ; decode lead while retaining the same absolute 23.976-fps deadline grid.
        jsr     n70_video_due_with_lead
        tst.l   d0
        beq.w   n80_defer_pacer

        ; Advance the established absolute timeline without waiting away the
        ; deliberate N79 lead. Late arrivals still use the proven pacer path.
        jsr     vpv98_read_sys_us
        move.l  d0,n63_video_phase_start_us
        jsr     n70_advance_frame_grid
        jsr     vpv98_read_sys_us
        sub.l   n63_video_phase_start_us,d0
        addq.l  #1,n63_video_pacer_calls
        add.l   d0,n63_video_pacer_total_us
        cmp.l   n63_video_pacer_max_us,d0
        bls.s   n66_vsvc_pacer_max_ok
        move.l  d0,n63_video_pacer_max_us
n66_vsvc_pacer_max_ok:
        cmpi.l  #20000,d0
        bls.s   n66_vsvc_due
        addq.l  #1,n63_video_pacer_gt20ms

n66_vsvc_due:
        ; P96W8: the previous AU's BULK_TX was not waited for at submit time.
        ; Finish it now (usually already complete), before the next feed.
        tst.l   bvp_p96_mode
        beq.s   p96w8_no_late_wait
        tst.l   input_bulk_pending
        beq.s   p96w8_no_late_wait
        jsr     p96w8_finish_tx
        tst.l   d0
        bne.w   n66_vsvc_fail
p96w8_no_late_wait:
        ; Do not introduce a new wait merely because all four decoder inputs are
        ; currently VideoCore-owned. Defer to a later API service opportunity.
        tst.l   input_bulk_pending
        bne.w   n80_defer_bulk
        move.l  input_in_use_count,d0
        cmpi.l  #INPUT_POOL_COUNT,d0
        bcc.w   n80_defer_pool

        lea     n66_video_buffer,a0
        move.l  a0,bvp_pending_ptr
        move.l  n66_video_pending_len,d0
        move.l  d0,bvp_pending_len
        move.l  n66_video_pending_flags,d0
        move.l  d0,bvp_pending_flags
        move.l  n66_video_pending_pts_hi,d0
        move.l  d0,bvp_pending_pts_hi
        move.l  n66_video_pending_pts_lo,d0
        move.l  d0,bvp_pending_pts_lo

        jsr     vpv98_read_sys_us
        move.l  d0,n63_video_phase_start_us
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v09
        lea     n79_v09,a1
        jsr     n12_log
n79_no_v09:
        jsr     bvp_wait_video_submit_ready
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v10
        lea     n79_v10,a1
        jsr     n12_log
n79_no_v10:
        move.l  d0,n63_video_saved_result
        jsr     vpv98_read_sys_us
        sub.l   n63_video_phase_start_us,d0
        add.l   d0,n63_video_submit_total_us
        cmp.l   n63_video_submit_max_us,d0
        bls.s   n66_vsvc_submit_max_ok
        move.l  d0,n63_video_submit_max_us
n66_vsvc_submit_max_ok:
        move.l  n63_video_saved_result,d0
        tst.l   d0
        bne.w   n66_vsvc_fail

        ; N79P96G: if the just-finished P96 RX exposed a waiting decoded PCM
        ; block, yield this Video turn once.  N69 immediately calls Audio first
        ; on the next dispatcher pass.  No RX/TX overlap is introduced.
        tst.l   n65_audio_pending
        bne.w   n80_defer_audio

n66_vsvc_feed_retry:
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v11
        lea     n79_v11,a1
        jsr     n12_log
n79_no_v11:
        ; N79: restore the exact video decoder endpoint immediately before
        ; every compressed-H264 feed. N35 proved this restore reaches
        ; VIDEO BULK_TX_DONE after Audio-Master/Scheduler setup.
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        ; P32/P31: retain active VCHIQ local service for external SendVideo.
        ; First run v12f_local_bits=0; persistent second run=$00001000.
        jsr     (p32_restore_vchiq_local_bits).l
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v18
        lea     n79_v18,a1
        jsr     n12_log
n79_no_v18:
        jsr     t31s_feed_next_input
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v12
        lea     n79_v12,a1
        jsr     n12_log
n79_no_v12:
        cmpi.l  #3,d0
        bne.s   n66_vsvc_feed_result
        addq.l  #1,bvp_n21_feed_retries
        jsr     bvp_wait_video_submit_ready
        tst.l   d0
        bne.w   n66_vsvc_fail
        bra.s   n66_vsvc_feed_retry
n66_vsvc_feed_result:
        tst.l   d0
        bne.w   n66_vsvc_fail

        jsr     vpv98_read_sys_us
        move.l  d0,n63_video_phase_start_us
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v16
        lea     n79_v16,a1
        jsr     n12_log
n79_no_v16:
        jsr     bvp_wait_video_bulk_done
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v17
        lea     n79_v17,a1
        jsr     n12_log
n79_no_v17:
        move.l  d0,n63_video_saved_result
        jsr     vpv98_read_sys_us
        sub.l   n63_video_phase_start_us,d0
        add.l   d0,n63_video_bulk_total_us
        cmp.l   n63_video_bulk_max_us,d0
        bls.s   n66_vsvc_bulk_max_ok
        move.l  d0,n63_video_bulk_max_us
n66_vsvc_bulk_max_ok:
        move.l  n63_video_saved_result,d0
        tst.l   d0
        bne.s   n66_vsvc_fail

        clr.l   n66_video_pending
        addq.l  #1,n66_video_service_submits
        moveq   #0,d0
        bra.s   n66_vsvc_done

; N80 diagnostics: say WHY the first AU is held back (logged on change).
n80_defer_clock:
        moveq   #1,d0
        bra.s   n80_defer_note
n80_defer_pacer:
        moveq   #2,d0
        bra.s   n80_defer_note
n80_defer_bulk:
        moveq   #3,d0
        bra.s   n80_defer_note
n80_defer_pool:
        moveq   #4,d0
        bra.s   n80_defer_note
n80_defer_audio:
        moveq   #5,d0
n80_defer_note:
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n66_vsvc_defer
        cmp.l   n80_last_defer,d0
        beq.s   n66_vsvc_defer
        move.l  d0,n80_last_defer
        lea     n80_pfx_reason,a1
        jsr     n15_log_hex32
        move.l  n73_scheduler_graph_ready,d0
        lea     n80_pfx_graph,a1
        jsr     n15_log_hex32
        move.l  n73_clock_armed,d0
        lea     n80_pfx_clock,a1
        jsr     n15_log_hex32
        move.l  input_bulk_pending,d0
        lea     n80_pfx_bulk,a1
        jsr     n15_log_hex32
        move.l  input_in_use_count,d0
        lea     n80_pfx_inuse,a1
        jsr     n15_log_hex32
        move.l  v32r_fastforward,d0
        lea     n80_pfx_ff,a1
        jsr     n15_log_hex32
        move.l  v41_display_style,d0
        lea     n80_pfx_style,a1
        jsr     n15_log_hex32
        move.l  v41e_hr_started,d0
        lea     n80_pfx_hrs,a1
        jsr     n15_log_hex32
        move.l  v41e_hr_target,d0
        lea     n80_pfx_hrt,a1
        jsr     n15_log_hex32
        jsr     v41e_hr_clock_poll
        lea     n80_pfx_hrn,a1
        jsr     n15_log_hex32
n66_vsvc_defer:
        addq.l  #1,n66_video_service_defers
        moveq   #0,d0
        bra.s   n66_vsvc_done
n66_vsvc_fail:
        addq.l  #1,n66_video_service_failures
        moveq   #1,d0
n66_vsvc_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; ---------------------------------------------------------------------------
; N79 - 35-ms direct-render decode lead.
;
; The failed N22/N23/N24/N57 scheduler branches are NOT reintroduced here.
; Current library video is decoder -> video_render and therefore pays decode/
; transport latency after a host deadline if an AU is submitted exactly on it.
; Return D0=1 once the current AU is at most 35 ms before its absolute target.
; D0=0 means keep servicing Audio/VCHIQ in the N69 dispatcher.
; ---------------------------------------------------------------------------
N79_VIDEO_LEAD_US equ 35000

n70_video_due_with_lead:
        movem.l d1-d2,-(sp)
        tst.l   v32r_fastforward
        bne.s   n70_due_yes
        cmpi.l  #3,v41_display_style
        bne.s   n70_due_fallback
        tst.l   v41e_hr_started
        beq.s   n70_due_yes              ; first visible AU remains immediate
        bsr     v41e_hr_clock_poll
        move.l  v41e_hr_target,d1
        cmp.l   d1,d0
        bcc.s   n70_due_late              ; already at/past target
        move.l  d1,d2
        sub.l   d0,d2                     ; positive microseconds until target
        cmpi.l  #N79_VIDEO_LEAD_US,d2
        bhi.s   n70_due_no
        addq.l  #1,n70_early_due_count
        cmp.l   n70_early_lead_max_us,d2
        bls.s   n70_due_yes
        move.l  d2,n70_early_lead_max_us
        bra.s   n70_due_yes
n70_due_late:
        addq.l  #1,n70_late_due_count
n70_due_yes:
        moveq   #1,d0
        bra.s   n70_due_done
n70_due_no:
        moveq   #0,d0
        bra.s   n70_due_done
n70_due_fallback:
        jsr     vpv72_video_due_now
n70_due_done:
        movem.l (sp)+,d1-d2
        rts

; Keep the exact absolute rational frame grid but do not busy-wait from the
; early threshold back to the nominal target.  A late/exact call still uses
; v41e_hr_pace_new_frame so existing lateness diagnostics remain meaningful.
n70_advance_frame_grid:
        movem.l d1-d2,-(sp)
        tst.l   v32r_fastforward
        bne.s   n70_grid_legacy
        cmpi.l  #3,v41_display_style
        bne.s   n70_grid_legacy
        tst.l   v41e_hr_started
        beq.s   n70_grid_legacy          ; initializes base + first target
        bsr     v41e_hr_clock_poll
        cmp.l   v41e_hr_target,d0
        bcc.s   n70_grid_legacy          ; exact/late: proven path has no wait
        bsr     v41e_hr_next_interval
        add.l   d0,v41e_hr_target
        addq.l  #1,v04_paced_frames
        bra.s   n70_grid_done
n70_grid_legacy:
        jsr     v41e_hr_pace_new_frame
n70_grid_done:
        movem.l (sp)+,d1-d2
        rts

; ---------------------------------------------------------------------------
; N69 - VPr8-style in-call dispatcher for the library ABI.
;
; N65 serviced Audio only once before entering the precise video wait.
; N66 avoided that busy-wait by returning to mrberry with one pending AU.
; N69 combines the useful parts: while the current AU is not due, remain in a
; bounded dispatcher loop, service deferred PCM on EVERY pass, and ask the
; nonblocking N66 video service whether the native deadline has arrived.
; Once due, n66_service_pending_video uses the common VCHIQ RX dispatcher and
; waits only for the serialized BULK_TX completion.
; D0=0 success, D0=1 hard failure/timeout.
; ---------------------------------------------------------------------------
n69_dispatch_pending_video:
        movem.l d1-d2,-(sp)
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v06
        lea     n79_v06,a1
        jsr     n12_log
n79_no_v06:
        addq.l  #1,n69_dispatch_entries
        move.l  #$00080000,d2
n69_dispatch_loop:
        move.l  #4,p96w_where        ; P96W33 hang marker
        tst.l   n66_video_pending
        beq.s   n69_dispatch_ok
        addq.l  #1,n69_dispatch_loops
        addq.l  #1,n69_dispatch_audio_calls
        jsr     n65_service_pending_audio
        tst.l   d0
        bne.s   n69_dispatch_fail
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v07
        lea     n79_v07,a1
        jsr     n12_log
n79_no_v07:
        jsr     n66_service_pending_video
        cmpi.l  #1,n79_first_video_trace_state
        bne.s   n79_no_v13
        lea     n79_v13,a1
        jsr     n12_log
n79_no_v13:
        tst.l   d0
        bne.s   n69_dispatch_fail
        tst.l   n66_video_pending
        beq.s   n69_dispatch_ok
        jsr     p96w9_idle_poll
        jsr     short_delay
        jsr     n81_heartbeat             ; CLK81 test: 1 line/s while waiting
        subq.l  #1,d2
        bne.w   n69_dispatch_loop
n69_dispatch_fail:
        addq.l  #1,n69_dispatch_failures
        moveq   #1,d0
        bra.s   n69_dispatch_done
n69_dispatch_ok:
        moveq   #0,d0
n69_dispatch_done:
        movem.l (sp)+,d1-d2
        rts

; Bounded legacy fallback retained for overwrite protection / CloseStream.
; Normal N69 SendVideo calls should leave no pending AU at API return.
n66_force_pending_video:
        movem.l d1-d2,-(sp)
        move.l  #$00080000,d2
n66_force_video_loop:
        move.l  #5,p96w_where        ; P96W33 hang marker
        tst.l   n66_video_pending
        beq.s   n66_force_video_ok
        jsr     n65_service_pending_audio
        tst.l   d0
        bne.s   n66_force_video_fail
        jsr     n66_service_pending_video
        tst.l   d0
        bne.s   n66_force_video_fail
        tst.l   n66_video_pending
        beq.s   n66_force_video_ok
        jsr     p96w9_idle_poll
        jsr     short_delay
        bsr     n80_break_pending
        bne.s   n69_dispatch_fail
        subq.l  #1,d2
        bne.s   n66_force_video_loop
n66_force_video_fail:
        moveq   #1,d0
        bra.s   n66_force_video_done
n66_force_video_ok:
        moveq   #0,d0
n66_force_video_done:
        movem.l (sp)+,d1-d2
        rts

; Bounded fallback for next-batch overwrite protection and CloseStream only.
n65_force_pending_audio:
        movem.l d1-d2,-(sp)
        tst.l   n65_audio_pending
        beq.s   n65_force_ok
        move.l  #$00040000,d2
n65_force_loop:
        jsr     n65_service_pending_audio
        tst.l   d0
        bne.s   n65_force_fail
        tst.l   n65_audio_pending
        beq.s   n65_force_ok
        jsr     short_delay
        bsr     n80_break_pending
        bne.s   n66_force_video_fail
        subq.l  #1,d2
        bne.s   n65_force_loop
n65_force_fail:
        moveq   #1,d0
        bra.s   n65_force_done
n65_force_ok:
        moveq   #0,d0
n65_force_done:
        movem.l (sp)+,d1-d2
        rts

; N80: Z clear (and D0=1) if the calling task has a pending Ctrl-C.
; MintVID's Stop button sends Ctrl-C to mrberry. The signal is only read,
; never cleared, so mrberry still sees it and stops normally once the
; library call returns. Without this the wait loops above ran their full
; bounded count with Stop ignored.
n80_break_pending:
        movem.l d1/a0-a1/a6,-(sp)
        move.l  4.w,a6
        moveq   #0,d0
        moveq   #0,d1
        jsr     SetSignal(a6)
        and.l   #SIGBREAKF_CTRL_C,d0
        beq.s   n80_break_none
        moveq   #1,d0
n80_break_none:
        movem.l (sp)+,d1/a0-a1/a6
        tst.l   d0
        rts

; ---------------------------------------------------------------------------
; N65 VPr8-style dual-audio helpers (no scheduler/clock).
; ---------------------------------------------------------------------------

; Initialize the two independent audio renderer slots only.
n29_audio_pipeline_init:
        movem.l d1-d2/a0,-(sp)
        clr.l   vpv39_audio_bulk_pending
        clr.l   vpv39_audio_failed
        move.l  #1,vpv39_audio_armed
        clr.l   vpv47_tx_slot
        clr.l   vpv47_inflight
        clr.l   vpv47_double_first_logged
        clr.l   vpv43_pts_mode
        clr.l   vpv43_audio_next_pts_ticks
        clr.l   vpv170_audio_next_pts_hi
        clr.l   n29_audio_selected_slot
        clr.l   n29_audio_inflight_peak
        clr.l   n29_audio_slot_waits
        clr.l   n29_audio_bulk_waits
        clr.l   n30_batch_bytes
        clr.l   n30_batch_frames
        clr.l   n30_batch_pts_hi
        clr.l   n30_batch_pts_lo
        clr.l   n30_total_aac_frames
        clr.l   n30_decode_batches
        clr.l   n30_pcm_submits
        clr.l   n30_partial_consumes
        clr.l   n30_pcm_max
        clr.l   n54_faad_total_us
        clr.l   n54_faad_max_us
        clr.l   n54_submit_total_us
        clr.l   n54_submit_max_us
        clr.l   n54_bulk_total_us
        clr.l   n54_bulk_max_us
        clr.l   n54_flush_total_us
        clr.l   n54_flush_max_us

        ; The renderer was configured with two INPUT buffers by the proven N9
        ; setup. Clear the two-slot ownership/PTS bookkeeping used by the VPr8
        ; audio sender, but deliberately do not create a scheduler or MMAL clock.
        lea     vpv47_slot_len,a0
        moveq   #((VPV47_AUDIO_SLOTS*6)-1),d0
n29_api_clear_slots:
        clr.l   (a0)+
        dbra    d0,n29_api_clear_slots
        clr.l   vpv135_slot_pts_lo
        clr.l   vpv135_slot_pts_lo+4
        clr.l   vpv135_slot_pts_hi
        clr.l   vpv135_slot_pts_hi+4
        movem.l (sp)+,d1-d2/a0
        moveq   #0,d0
        rts

; Reap audio slots for which both BULK_TX_DONE and the matching
; BUFFER_TO_HOST have arrived.  Only here is DMA ownership returned to CPU.
n29_audio_reap_slots:
        movem.l d0-d7/a0-a2/a6,-(sp)
        moveq   #0,d6
n29_ars_loop:
        cmpi.l  #VPV47_AUDIO_SLOTS,d6
        bcc.s   n29_ars_done
        move.l  d6,d5
        lsl.l   #2,d5
        lea     vpv47_slot_state,a0
        adda.l  d5,a0
        tst.l   (a0)
        beq.s   n29_ars_next
        lea     vpv47_slot_bulk_done,a1
        adda.l  d5,a1
        tst.l   (a1)
        beq.s   n29_ars_next
        lea     vpv47_slot_returned,a1
        adda.l  d5,a1
        tst.l   (a1)
        beq.s   n29_ars_next

        tst.l   d6
        bne.s   n29_ars_slot1
        move.l  vpv21_pcm_ptr,a0
        bra.s   n29_ars_have_ptr
n29_ars_slot1:
        move.l  vpv47_pcm1_ptr,a0
n29_ars_have_ptr:
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)

        move.l  d6,d5
        lsl.l   #2,d5
        lea     vpv47_slot_state,a0
        adda.l  d5,a0
        clr.l   (a0)
        lea     vpv47_slot_bulk_done,a0
        adda.l  d5,a0
        clr.l   (a0)
        lea     vpv47_slot_returned,a0
        adda.l  d5,a0
        clr.l   (a0)
        lea     vpv47_slot_dma_active,a0
        adda.l  d5,a0
        clr.l   (a0)
        tst.l   vpv47_inflight
        beq.s   n29_ars_next
        subq.l  #1,vpv47_inflight
n29_ars_next:
        addq.l  #1,d6
        bra.s   n29_ars_loop
n29_ars_done:
        movem.l (sp)+,d0-d7/a0-a2/a6
        rts

; CPU-owned on entry/return.  Selects a free audio slot into
; n29_audio_selected_slot and guarantees no VIDEO/AUDIO BULK_TX is active.
n29_wait_audio_submit_ready:
        jsr     p96w_wait_budget          ; P96W35: max ~6 s in the window
n29_wasr_check:
        bsr     n29_audio_reap_slots
        tst.l   input_bulk_pending
        bne.s   n29_wasr_need_poll
        tst.l   vpv39_audio_bulk_pending
        bne.s   n29_wasr_need_poll
        tst.l   vpv47_slot_state
        beq.s   n29_wasr_slot0
        tst.l   vpv47_slot_state+4
        beq.s   n29_wasr_slot1
        addq.l  #1,n29_audio_slot_waits
n29_wasr_need_poll:
        jsr     dma_pre_all
n29_wasr_poll:
        move.l  #6,p96w_where        ; P96W33 hang marker
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     60(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bls.s   n29_wasr_no_msg
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   n29_wasr_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,bulk_rx_size
        jsr     v9g_h19_dispatch
        tst.l   v10h_error_seen
        bne.w   n29_wasr_fail
        bsr     n29_audio_reap_slots
        tst.l   input_bulk_pending
        bne.s   n29_wasr_more
        tst.l   vpv39_audio_bulk_pending
        bne.s   n29_wasr_more
        tst.l   vpv47_slot_state
        beq.s   n29_wasr_slot0
        tst.l   vpv47_slot_state+4
        beq.s   n29_wasr_slot1
n29_wasr_more:
        jsr     dma_pre_all
        bra.s   n29_wasr_tick
n29_wasr_no_msg:
        bsr     n29_audio_reap_slots
        tst.l   input_bulk_pending
        bne.s   n29_wasr_not_ready
        tst.l   vpv39_audio_bulk_pending
        bne.s   n29_wasr_not_ready
        tst.l   vpv47_slot_state
        beq.s   n29_wasr_slot0
        tst.l   vpv47_slot_state+4
        beq.s   n29_wasr_slot1
n29_wasr_not_ready:
        jsr     dma_pre_all
n29_wasr_tick:
        subq.l  #1,bvp_wait_count
        jsr     p96w12_kick_maybe
        tst.l   bvp_wait_count            ; P96W12: flags for loop test
        bne.w   n29_wasr_poll
        jsr     dma_post_all
        jsr     p96w_dump_state
        lea     n29_msg_audio_submit_timeout,a1
        jsr     n12_log
        moveq   #BVPERR_TIMEOUT,d0
        rts
n29_wasr_slot0:
        clr.l   n29_audio_selected_slot
        moveq   #BVP_OK,d0
        rts
n29_wasr_slot1:
        move.l  #1,n29_audio_selected_slot
        moveq   #BVP_OK,d0
        rts
n29_wasr_fail:
        lea     n29_msg_audio_dispatch_err,a1
        jsr     n12_log
        moveq   #BVPERR_BACKEND,d0
        rts

; After publishing PCM, wait only for serialized BULK_TX_DONE.  The renderer
; may keep the slot afterwards; its BTH is consumed by later video/audio calls.
n29_wait_audio_bulk_done:
        addq.l  #1,n29_audio_bulk_waits
        jsr     p96w_wait_budget          ; P96W35: max ~6 s in the window
n29_wabd_loop:
        move.l  #7,p96w_where        ; P96W33 hang marker
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     60(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bls.s   n29_wabd_check
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   n29_wabd_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,bulk_rx_size
        jsr     v9g_h19_dispatch
        tst.l   v10h_error_seen
        bne.w   n29_wabd_fail
n29_wabd_check:
        tst.l   vpv39_audio_bulk_pending
        beq.s   n29_wabd_ok
        jsr     dma_pre_all
        subq.l  #1,bvp_wait_count
        jsr     p96w12_kick_maybe
        tst.l   bvp_wait_count            ; P96W12: flags for loop test
        bne.w   n29_wabd_loop
        jsr     dma_post_all
        jsr     p96w_dump_state
        lea     n29_msg_audio_bulk_timeout,a1
        jsr     n12_log
        moveq   #BVPERR_TIMEOUT,d0
        rts
n29_wabd_fail:
        lea     n29_msg_audio_dispatch_err,a1
        jsr     n12_log
        moveq   #BVPERR_BACKEND,d0
        rts
n29_wabd_ok:
        bsr     n29_audio_reap_slots
        moveq   #BVP_OK,d0
        rts

; Before video EOS only the serialized transport must be idle. Renderer-owned
; PCM slots are allowed to finish while BVP_CloseStream drains/tears down MMAL.
n29_wait_audio_transport_idle:
        move.l  #$00040000,bvp_wait_count
        tst.l   vpv39_audio_bulk_pending
        beq.s   n29_wati_ok
        ; Public ABI returns CPU-owned; give shared VCHIQ RAM back before wait.
        jsr     dma_pre_all
n29_wati_loop:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     60(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bls.s   n29_wati_more
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.s   n29_wati_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,bulk_rx_size
        jsr     v9g_h19_dispatch
        tst.l   v10h_error_seen
        bne.s   n29_wati_fail
        bsr     n29_audio_reap_slots
n29_wati_more:
        jsr     dma_pre_all
        subq.l  #1,bvp_wait_count
        bne.s   n29_wati_loop
        jsr     dma_post_all
n29_wati_fail:
        ; Failure branches are reached CPU-owned after dma_post_all.
        moveq   #1,d0
        rts
n29_wati_ok:
        moveq   #0,d0
        rts

; MMAL service is closed before this helper is called. Return CPU cache
; ownership for either still-marked PCM slot so the backing allocation can be
; released safely.
n29_audio_post_after_service_close:
        movem.l d0-d3/a0-a1/a6,-(sp)
        moveq   #0,d3
n29_apasc_loop:
        cmpi.l  #VPV47_AUDIO_SLOTS,d3
        bcc.s   n29_apasc_done
        move.l  d3,d0
        lsl.l   #2,d0
        lea     vpv47_slot_dma_active,a1
        adda.l  d0,a1
        tst.l   (a1)
        beq.s   n29_apasc_next
        tst.l   d3
        bne.s   n29_apasc_slot1
        move.l  vpv21_pcm_ptr,a0
        bra.s   n29_apasc_have
n29_apasc_slot1:
        move.l  vpv47_pcm1_ptr,a0
n29_apasc_have:
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
n29_apasc_next:
        addq.l  #1,d3
        bra.s   n29_apasc_loop
n29_apasc_done:
        movem.l (sp)+,d0-d3/a0-a1/a6
        rts

n11_stamp_audio_milestone:
        movem.l d0-d2/a1,-(sp)
        lea     n11_audio_table,a1
        bra.s   n11_stamp_milestone_common

n11_stamp_video_milestone:
        movem.l d0-d2/a1,-(sp)
        lea     n11_video_table,a1

n11_stamp_milestone_common:
        ; D0=current return count, A1=table of {count.l,name.l}, terminated by count=0.
n11_smc_loop:
        move.l  (a1)+,d1
        beq.s   n11_smc_done
        move.l  (a1)+,d2
        cmp.l   d1,d0
        bne.s   n11_smc_loop
        move.l  d2,a1
        jsr     n12_log
n11_smc_done:
        movem.l (sp)+,d0-d2/a1
        rts

n9_wait_audio_common:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  #V10_CLEANUP_POLL_COUNT,d7
n9_wac_loop:
        ; N19: no per-packet wait-entry DOS logging.
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bls.s   n9_wac_check_done
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.s   n9_wac_fail_cpu
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,bulk_rx_size
        jsr     v9g_h19_dispatch
        tst.l   v10h_error_seen
        beq.s   n12_wac_no_dispatch_err
        lea     n12_msg_a_dispatch_err,a1
        jsr     n12_log
        bra.s   n9_wac_fail_cpu
n12_wac_no_dispatch_err:
n9_wac_check_done:
        tst.l   vpv39_audio_bulk_pending
        bne.s   n9_wac_more
        tst.l   vpv21_audio_returned
        bne.s   n9_wac_success
n9_wac_more:
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   n9_wac_loop
        jsr     dma_post_all
        lea     n12_msg_a_wait_timeout,a1
        jsr     n12_log
        bra.s   n9_wac_fail_cpu
n9_wac_success:
        tst.l   vpv21_audio_dma_active
        beq.s   n9_wac_success_done
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  vpv21_pcm_ptr,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv21_audio_dma_active
n9_wac_success_done:
        clr.l   vpv39_audio_bulk_pending
        moveq   #0,d0
        bra.s   n9_wac_done
n9_wac_fail_cpu:
        clr.l   vpv39_audio_bulk_pending
        tst.l   vpv21_audio_dma_active
        beq.s   n9_wac_fail_done
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  vpv21_pcm_ptr,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv21_audio_dma_active
n9_wac_fail_done:
        moveq   #1,d0
n9_wac_done:
        clr.l   n12_audio_wait_logged
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

n9_audio_alloc_pcm:
        movem.l d1-d3/a0-a1/a6,-(sp)
        tst.l   vpv21_pcm_alloc
        bne.s   n9_aap_ok
        clr.l   vpv21_pcm_total_bytes
        clr.l   vpv21_pcm_total_samples
        clr.l   vpv21_audio_returned
        clr.l   vpv21_audio_dma_active
        clr.l   vpv38_pcm_block_count
        clr.l   vpv38_pcm_store_total
        clr.l   vpv48_batch_count
        move.l  a4,a6
        move.l  #VPV21_PCM_ALLOC_SIZE,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.s   n9_aap_fail
        move.l  d0,vpv21_pcm_alloc
        add.l   #$00000fff,d0
        and.l   #$fffff000,d0
        move.l  d0,vpv21_pcm_ptr
        move.l  d0,vpv21_pcm_write_ptr
        cmpi.l  #$3f000000,d0
        bcc.s   n9_aap_fail_free
        move.l  d0,d1
        add.l   #VPV21_PCM_DMA_SPAN-1,d1
        cmpi.l  #$3f000000,d1
        bcc.s   n9_aap_fail_free
        move.l  d0,d1
        or.l    #$c0000000,d1
        move.l  d1,vpv21_pcm_bus
        move.l  d0,d1
        add.l   #VPV21_PCM_PAGE_OFS,d1
        move.l  d1,vpv21_pcm_pagelist_ptr
        or.l    #$c0000000,d1
        move.l  d1,vpv21_pcm_pagelist_bus
        move.l  vpv21_pcm_ptr,d1
        add.l   #$00042000,d1
        move.l  d1,vpv47_pcm1_ptr
        move.l  d1,d2
        or.l    #$c0000000,d2
        move.l  d2,vpv47_pcm1_bus
        add.l   #VPV21_PCM_PAGE_OFS,d1
        move.l  d1,vpv47_pcm1_pagelist_ptr
        or.l    #$c0000000,d1
        move.l  d1,vpv47_pcm1_pagelist_bus
n9_aap_ok:
        moveq   #0,d0
        bra.s   n9_aap_done
n9_aap_fail_free:
        jsr     vpv21_free_pcm
n9_aap_fail:
        moveq   #1,d0
n9_aap_done:
        movem.l (sp)+,d1-d3/a0-a1/a6
        rts

; One caller-supplied ADTS packet through BerryFAAD03; PCM16 is byte-swapped
; into the existing VPv38 store exactly as in the proven CPU1 bridge.
n9_faad_decode_direct:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv48_last_consumed
        clr.l   vpv48_last_pcm_bytes
        clr.l   vpv48_last_samples_ch
        clr.l   vpv48_last_frames
        tst.l   vpv48_faad_ready
        beq.w   n9_fdd_fail
        move.l  n9_audio_pending_len,d5
        beq.w   n9_fdd_fail
        cmpi.l  #VPV48_FAAD_INPUT_SIZE,d5
        bhi.w   n9_fdd_fail
        move.l  n9_audio_pending_ptr,a1
        move.l  vpv48_input_ptr,a0
        move.l  d5,d3
        move.l  d3,d2
        lsr.l   #2,d2
        beq.s   n9_fdd_copy_tail
n9_fdd_copy_long:
        move.l  (a1)+,(a0)+
        subq.l  #1,d2
        bne.s   n9_fdd_copy_long
n9_fdd_copy_tail:
        and.l   #3,d3
        beq.s   n9_fdd_copy_done
n9_fdd_copy_byte:
        move.b  (a1)+,(a0)+
        subq.l  #1,d3
        bne.s   n9_fdd_copy_byte
n9_fdd_copy_done:
        move.l  d5,d0
        jsr     vpv48_map_input
        tst.l   d0
        bne.w   n9_fdd_fail
        move.l  vpv48_input_phys,vpv48_req_in_phys
        move.l  d5,vpv48_req_in_len
        move.l  vpv48_output_phys,vpv48_req_out_phys
        move.l  #VPV48_FAAD_OUT_SIZE,vpv48_req_out_len
        move.l  #3,vpv48_req_param0
        clr.l   vpv48_req_param1
        move.l  vpv48_work_phys,vpv48_req_work_phys
        move.l  #VPV48_FAAD_WORK_SIZE,vpv48_req_work_len
        moveq   #VPV48_CMD_CALL_MODULE,d0
        jsr     vpv48_send_request
        move.l  d0,d7
        jsr     vpv48_close_input
        jsr     vpv48_close_output_work
        tst.l   d7
        bne.w   n9_fdd_reopen_fail
        move.l  vpv48_output_ptr,a0
        cmpi.l  #VPV48_FAAD_OUT_MARKER,0(a0)
        bne.w   n9_fdd_reopen_fail
        cmpi.l  #VPV48_FAAD_BATCH_STATUS,4(a0)
        bne.w   n9_fdd_reopen_fail
        move.l  8(a0),d0
        tst.l   d0
        beq.w   n9_fdd_reopen_fail
        cmpi.l  #192000,d0
        bhi.w   n9_fdd_reopen_fail
        move.l  d0,v19_pcm_rate
        cmpi.l  #2,12(a0)
        bne.w   n9_fdd_reopen_fail
        tst.l   24(a0)
        bne.w   n9_fdd_reopen_fail
        move.l  16(a0),d4
        tst.l   d4
        beq.w   n9_fdd_reopen_fail
        cmp.l   d5,d4
        bhi.w   n9_fdd_reopen_fail
        move.l  d4,vpv48_last_consumed
        move.l  28(a0),vpv48_last_frame_index
        move.l  68(a0),vpv48_last_frames
        move.l  76(a0),d6
        move.l  d6,vpv48_last_pcm_bytes
        cmpi.l  #VPV38_PCM_STORE_BYTES,d6
        bhi.w   n9_fdd_reopen_fail
        move.l  20(a0),d2
        btst    #0,d2
        bne.w   n9_fdd_reopen_fail
        lsr.l   #1,d2
        move.l  d2,vpv48_last_samples_ch
        tst.l   d6
        beq.s   n9_fdd_remap_ok
        move.l  20(a0),d1
        lsl.l   #1,d1
        cmp.l   d6,d1
        bne.w   n9_fdd_reopen_fail
        lea     256(a0),a1
        lea     vpv38_pcm_store,a2
        move.l  d6,d3
        lsr.l   #1,d3
n9_fdd_pcm_loop:
        move.w  (a1)+,d0
        ror.w   #8,d0
        move.w  d0,(a2)+
        subq.l  #1,d3
        bne.s   n9_fdd_pcm_loop
        addq.l  #1,vpv48_batch_count
n9_fdd_remap_ok:
        jsr     vpv48_map_output_work
        tst.l   d0
        bne.s   n9_fdd_fail
        moveq   #0,d0
        bra.s   n9_fdd_done
n9_fdd_reopen_fail:
        jsr     vpv48_map_output_work
n9_fdd_fail:
        moveq   #1,d0
n9_fdd_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


; ============================================================================
; AC307A public ConfigAudio wrapper.
; AAC jumps to exact N79Q. AC3 (codec 3) and E-AC3 (codec 4) select
; separate CPU1 modules, then reuse the common N79Q stereo renderer.
; ============================================================================
ac307_ConfigAudio:
        cmpi.l  #4,d0
        beq.s   ac308_ca_eac3
        cmpi.l  #3,d0
        beq.s   ac307_ca_ac3
        clr.l   ac307_decoder_kind
        jmp     BVP_ConfigAudioN9
ac308_ca_eac3:
        clr.l   e4d_frame_counter          ; FAST04: new E-AC3 PCM diagnostic run
        ; AC308N3: keep the AC308N2 instruction geometry/relocations intact,
        ; but narrow the accepted E-AC3 input range from 2..6 to exactly 2.
        cmpi.l  #2,d2
        bcs.s   ac307_ca_bad_channels
        cmpi.l  #2,d2
        bhi.s   ac307_ca_bad_channels
        move.l  #2,ac307_decoder_kind
        moveq   #2,d0                     ; common AAC/stereo renderer setup
        moveq   #2,d2                     ; E-AC3 stereo remains stereo
        jmp     BVP_ConfigAudioN9
ac307_ca_ac3:
        cmpi.l  #1,d2
        bcs.s   ac307_ca_bad_channels
        cmpi.l  #6,d2
        bhi.s   ac307_ca_bad_channels
        move.l  #1,ac307_decoder_kind
        moveq   #2,d0                     ; feed common N79Q AAC/stereo setup
        moveq   #2,d2                     ; renderer and PCM output are stereo
        jmp     BVP_ConfigAudioN9
ac307_ca_bad_channels:
        ; Force the original N79Q validator to return BVPERR_BADPARAM (-3)
        ; and update BVP_LAST_ERROR in the normal way.
        moveq   #2,d0
        moveq   #0,d2
        jmp     BVP_ConfigAudioN9

; Return D0=1 when current compressed batch should be decoded now.
; AAC semantics are exactly N79Q: 2 frames before first PCM, then 16.
; AC3 remains AC307A: first packet, then 7-packet batches.
; AC308N E-AC3: decode every packet.  E-AC3 frames are normally 32 ms and
; waiting for seven packets can starve the audio-master scheduler on 50/60-fps
; material before mrberry reaches the next audio batch.
ac307_should_flush:
        move.l  ac307_decoder_kind,d0
        cmpi.l  #2,d0
        beq.s   ac308n_sf_eac3
        tst.l   d0
        bne.s   ac307_sf_ac3
        tst.l   n73_first_pcm_published
        bne.s   ac307_sf_aac_normal
        cmpi.l  #2,n30_batch_frames
        bcs.s   ac307_sf_no
        addq.l  #1,n73_prime_flushes
        moveq   #1,d0
        rts
ac307_sf_aac_normal:
        cmpi.l  #16,n30_batch_frames
        bcs.s   ac307_sf_no
        moveq   #1,d0
        rts
; FASTIMDCT10: retain hardware-confirmed FAST05 STARTPRIME2 behavior.
; First E-AC3 PCM publish contains 2 frames (64 ms), then one frame (32 ms).
ac308n_sf_eac3:
        tst.l   n73_first_pcm_published
        bne.s   ac309_sf_eac3_running
        cmpi.l  #2,n30_batch_frames
        bcs.s   ac307_sf_no
        addq.l  #1,n73_prime_flushes
        moveq   #1,d0
        rts
ac309_sf_eac3_running:
        tst.l   bvp_p96_mode
        bne.s   p96w23_sf_window
        cmpi.l  #1,n30_batch_frames
        bcs.s   ac307_sf_no
        moveq   #1,d0
        rts
ac307_sf_ac3:
        tst.l   n73_first_pcm_published
        bne.s   ac307_sf_ac3_normal
        cmpi.l  #1,n30_batch_frames
        bcs.s   ac307_sf_no
        addq.l  #1,n73_prime_flushes
        moveq   #1,d0
        rts
ac307_sf_ac3_normal:
        tst.l   bvp_p96_mode
        bne.s   p96w23_sf_window
        cmpi.l  #7,n30_batch_frames
        bcs.s   ac307_sf_no
        moveq   #1,d0
        rts
; P96W25: in the P96 window AC3/E-AC3 decode asynchronously on CPU1.
; CPU1 calls stay small (AC3 5 frames, E-AC3 2 frames: P96W23's 10 was
; refused by both modules); p96w_async_complete collects the PCM of several
; calls into one ~60-KiB block, so there are as few audio BULK_TX as AAC.
p96w23_sf_window:
        cmpi.l  #2,ac307_decoder_kind
        beq.s   p96w24_sf_eac3
        cmpi.l  #5,n30_batch_frames
        bcs.s   ac307_sf_no
        moveq   #1,d0
        rts
p96w24_sf_eac3:
        cmpi.l  #2,n30_batch_frames
        bcs.s   ac307_sf_no
        moveq   #1,d0
        rts
ac307_sf_no:
        moveq   #0,d0
        rts

; n30_flush_audio_batch calls here. AAC jumps straight to the original exact
; N79Q n9_faad_decode_direct; AC3/E-AC3 share the AC305-compatible parser below.
ac307_decode_dispatch:
        tst.l   ac307_decoder_kind
        bne.s   ac307_dd_ac3
        jmp     n9_faad_decode_direct
ac307_dd_ac3:
        jmp     ac307_ac3_decode_direct

; AC3/E-AC3 compressed batch -> selected CPU1 module -> PCM16 stereo.
; Uses the same N79Q mailbox, map/unmap helpers and vpv38_pcm_store.
; D0=0 success, D0=1 failure.
ac307_ac3_decode_direct:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv48_last_consumed       ; last_consumed
        clr.l   vpv48_last_pcm_bytes       ; last_pcm_bytes
        clr.l   vpv48_last_samples_ch       ; last_samples_ch
        clr.l   vpv48_last_frames       ; last_frames
        tst.l   vpv48_faad_ready       ; decoder ready
        beq.w   ac307_add_fail

        move.l  n9_audio_pending_len,d5    ; n9_audio_pending_len
        beq.w   ac307_add_fail
        cmpi.l  #$00020000,d5
        bhi.w   ac307_add_fail

        move.l  n9_audio_pending_ptr,a1    ; n9_audio_pending_ptr
        move.l  vpv48_input_ptr,a0    ; vpv48_input_ptr
        move.l  d5,d3
        move.l  d3,d2
        lsr.l   #2,d2
        beq.s   ac307_add_copy_tail
ac307_add_copy_long:
        move.l  (a1)+,(a0)+
        subq.l  #1,d2
        bne.s   ac307_add_copy_long
ac307_add_copy_tail:
        andi.l  #3,d3
        beq.s   ac307_add_copy_done
ac307_add_copy_byte:
        move.b  (a1)+,(a0)+
        subq.l  #1,d3
        bne.s   ac307_add_copy_byte
ac307_add_copy_done:

        move.l  d5,d0
        jsr     vpv48_map_input       ; map input
        tst.l   d0
        bne.w   ac307_add_fail

        move.l  vpv48_input_phys,vpv48_req_in_phys ; input phys
        move.l  d5,vpv48_req_in_len
        move.l  vpv48_output_phys,vpv48_req_out_phys ; output phys
        move.l  #$00011000,vpv48_req_out_len
        move.l  #3,vpv48_req_param0    ; streaming decode
        clr.l   vpv48_req_param1
        move.l  vpv48_work_phys,vpv48_req_work_phys ; work phys
        move.l  #$00040000,vpv48_req_work_len
        moveq   #4,d0                      ; CALL_MODULE
        jsr     vpv48_send_request
        move.l  d0,d7
        jsr     vpv48_close_input       ; close input DMA
        jsr     vpv48_close_output_work       ; close output/work DMA
        tst.l   d7
        bne.w   ac307_add_reopen_fail

        move.l  vpv48_output_ptr,a0    ; output ptr
        cmpi.l  #$41433334,(a0)            ; 'AC34'
        bne.w   ac307_add_reopen_fail
        cmpi.l  #4,4(a0)                   ; streaming-batch status
        bne.w   ac307_add_reopen_fail
        move.l  8(a0),d0                   ; actual AC3 sample rate
        tst.l   d0
        beq.w   ac307_add_reopen_fail
        cmpi.l  #192000,d0
        bhi.w   ac307_add_reopen_fail
        move.l  d0,v19_pcm_rate    ; v19_pcm_rate
        cmpi.l  #2,12(a0)                  ; module always emits stereo
        bne.w   ac307_add_reopen_fail
        tst.l   72(a0)                     ; error_stage
        bne.w   ac307_add_reopen_fail

        move.l  36(a0),d4                  ; bytes_consumed
        tst.l   d4
        beq.w   ac307_add_reopen_fail
        cmp.l   d5,d4
        bhi.w   ac307_add_reopen_fail
        move.l  d4,vpv48_last_consumed
        move.l  24(a0),vpv48_last_frames ; frames_decoded
        move.l  32(a0),d6                  ; pcm_bytes
        move.l  d6,vpv48_last_pcm_bytes
        cmpi.l  #$00010000,d6
        bhi.w   ac307_add_reopen_fail
        move.l  28(a0),d2                  ; samples_per_channel
        move.l  d2,vpv48_last_samples_ch

        tst.l   d6
        beq.s   ac307_add_remap_ok
        move.l  d2,d1
        lsl.l   #2,d1                      ; samples/ch * 2ch * 2 bytes
        cmp.l   d6,d1
        bne.w   ac307_add_reopen_fail
        lea     256(a0),a1
        lea     vpv38_pcm_store,a2     ; vpv38_pcm_store
        move.l  d6,d3
        lsr.l   #1,d3
ac307_add_pcm_loop:
        move.w  (a1)+,d0
        ror.w   #8,d0                      ; CPU1 BE PCM -> MMAL LE PCM
        move.w  d0,(a2)+
        subq.l  #1,d3
        bne.s   ac307_add_pcm_loop
        addq.l  #1,vpv48_batch_count    ; batch_count diagnostic
        jsr     e4d_pcm_diag               ; FAST04: sampled E-AC3 PCM stats only

ac307_add_remap_ok:
        jsr     vpv48_map_output_work       ; remap output/work for next call
        tst.l   d0
        bne.s   ac307_add_fail
        moveq   #0,d0
        bra.s   ac307_add_done
ac307_add_reopen_fail:
        jsr     vpv48_map_output_work
ac307_add_fail:
        moveq   #1,d0
ac307_add_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

        even

; ============================================================================
; FASTIMDCT04_DIAG
; Sample the already-decoded AC3-compatible PCM output without changing it.
; E-AC3 only.  Logs first 16 frames, every 32nd frame, every 8th frame from
; frame 1600 onward, and frame 1875 of the 60 s reference clip.
; Line format in N79_TRACE.TXT:
;   E4D F=........ P=........ NZ=........ CL=........
; P  = absolute PCM16 peak (0..0x8000)
; NZ = non-zero PCM16 samples in this frame
; CL = samples exactly +32767 or -32768 (hard clipping indicator)
; ============================================================================
e4d_pcm_diag:
        movem.l d0-d7/a0-a4,-(sp)
        ; FAST10: this routine is reachable only through the AC3/E-AC3 decoder
        ; path.  FAST09's decoder_kind filter suppressed every diagnostic line
        ; on hardware, so do not gate the probe on that selector here.
        ; Accumulate the module's actual frames_decoded count: the first
        ; STARTPRIME2 batch contains two E-AC3 frames, later batches one.
        move.l  24(a0),d0
        tst.l   d0
        beq.w   e4d_done
        add.l   d0,e4d_frame_counter
        move.l  e4d_frame_counter,d7

        cmpi.l  #16,d7
        bls.s   e4d_sample
        cmpi.l  #1875,d7
        beq.s   e4d_sample
        cmpi.l  #1600,d7
        bcs.s   e4d_before_tail
        move.l  d7,d0
        andi.l  #7,d0
        beq.s   e4d_sample
        bra.w   e4d_done

e4d_before_tail:
        move.l  d7,d0
        andi.l  #31,d0
        bne.w   e4d_done

e4d_sample:
        ; a0 = AC305-compatible CPU1 output base, d6 = PCM byte count.
        lea     256(a0),a1
        move.l  d6,d5
        lsr.l   #1,d5                      ; PCM16 sample count (L+R)
        clr.l   d4                         ; absolute peak
        clr.l   d3                         ; non-zero sample count
        clr.l   d2                         ; hard-clip sample count
        tst.l   d5
        beq.s   e4d_build

e4d_scan_loop:
        moveq   #0,d0
        move.w  (a1)+,d0
        cmpi.w  #$7FFF,d0
        beq.s   e4d_clip
        cmpi.w  #$8000,d0
        bne.s   e4d_not_clip

e4d_clip:
        addq.l  #1,d2

e4d_not_clip:
        ext.l   d0
        beq.s   e4d_next_sample
        addq.l  #1,d3
        move.l  d0,d1
        bpl.s   e4d_abs_ready
        neg.l   d1

e4d_abs_ready:
        cmp.l   d4,d1
        bls.s   e4d_next_sample
        move.l  d1,d4

e4d_next_sample:
        subq.l  #1,d5
        bne.s   e4d_scan_loop

e4d_build:
        ; Copy fixed template into writable BSS line buffer.
        lea     e4d_line_template,a1
        lea     e4d_line_buffer,a2
        moveq   #49,d5                     ; 50 bytes incl. terminating NUL

e4d_copy_template:
        move.b  (a1)+,(a2)+
        dbf     d5,e4d_copy_template

        ; Fill frame, peak, nonzero and clip counters as 8-digit hex.
        move.l  d7,d0
        lea     e4d_line_buffer+6,a1
        bsr.s   e4d_hex8
        move.l  d4,d0
        lea     e4d_line_buffer+17,a1
        bsr.s   e4d_hex8
        move.l  d3,d0
        lea     e4d_line_buffer+29,a1
        bsr.s   e4d_hex8
        move.l  d2,d0
        lea     e4d_line_buffer+41,a1
        bsr.s   e4d_hex8

        ; Use the proven N12 zero-terminated logger. FAST08 proved this
        ; logger writes correctly to N79_TRACE during playback.
        lea     e4d_line_buffer,a1
        jsr     n12_log       ; n12_log

e4d_done:
        movem.l (sp)+,d0-d7/a0-a4
        rts

; D0=value, A1=8-byte destination. Preserves all registers.
e4d_hex8:
        movem.l d0-d2,-(sp)
        moveq   #7,d2

e4d_hex_loop:
        rol.l   #4,d0
        move.l  d0,d1
        andi.w  #$000F,d1
        cmpi.w  #9,d1
        bls.s   e4d_hex_digit
        addi.w  #7,d1

e4d_hex_digit:
        addi.w  #'0',d1
        move.b  d1,(a1)+
        dbf     d2,e4d_hex_loop
        movem.l (sp)+,d0-d2
        rts

e4d_line_template:
        dc.b    "E4D F=00000000 P=00000000 NZ=00000000 CL=00000000",0
e4d_line_template_end:
        even

; ============================================================================
; FASTIMDCT13_LOGUPDATE
; Diagnostic-only tail trace. Playback code, MMAL PTS/DTS, decoder and host
; behavior are unchanged from FAST10/FAST12.
; Logged directly at the proven audio slot publication boundary, therefore all
; values are live registers from the actual buffer about to be sent:
;   F  = true cumulative decoded E-AC3 frame counter
;   S  = audio slot (0/1)
;   PH = submitted MMAL PTS high 32 bits
;   PL = submitted MMAL PTS low 32 bits
;   L  = PCM bytes in this submitted buffer
; ============================================================================

fast13_submit_trace_hook:
        movem.l d0-d6/a1-a2,-(sp)
        move.l  d5,d4                      ; preserve live PCM byte count for log
        move.l  e4d_frame_counter,d6
        cmpi.l  #1600,d6
        bcs.w   fast13_state_done

        ; One line per 16 E-AC3 frames (~512 ms), plus the true final frame.
        cmpi.l  #1875,d6
        beq.s   fast13_state_log
        move.l  d6,d0
        andi.l  #15,d0
        bne.w   fast13_state_done

fast13_state_log:
        lea     fast13_line_template,a1
        lea     fast13_line_buffer,a2
        moveq   #62,d5                     ; 63 bytes incl. NUL
fast13_copy_line:
        move.b  (a1)+,(a2)+
        dbf     d5,fast13_copy_line

        move.l  d6,d0
        lea     fast13_line_buffer+7,a1
        bsr     e4d_hex8

        move.l  d7,d0
        lea     fast13_line_buffer+18,a1
        bsr     e4d_hex8

        move.l  d3,d0
        lea     fast13_line_buffer+30,a1
        bsr     e4d_hex8

        move.l  d2,d0
        lea     fast13_line_buffer+42,a1
        bsr     e4d_hex8

        move.l  d4,d0
        lea     fast13_line_buffer+53,a1
        bsr     e4d_hex8

        lea     fast13_line_buffer,a1
        jsr     n12_log       ; proven n12_log

fast13_state_done:
        movem.l (sp)+,d0-d6/a1-a2
        move.l  d7,d0
        lsl.l   #2,d0
        lea     vpv135_slot_pts_lo,a0    ; original vpv135_slot_pts_lo
        rts

fast13_line_template:
        dc.b    "R13S F=00000000 S=00000000 PH=00000000 PL=00000000 L=00000000",0
fast13_line_template_end:
        even

; P32 carries the hardware-confirmed P31 VPr8 local-1 feed fix on top of
; FAST13. Appended after all FAST13 HUNK4 data so existing FAST13 geometry stays fixed.
p32_restore_vchiq_local_bits:
        move.l  v12f_local_bits,port_query_index
        rts
        even

