        dc.l    1,p96wd_n35,slot_ptr,MASTER_FIRST
        dc.l    1,p96wd_n36,slot_ptr,MASTER_LAST
        dc.l    0,p96wd_n37,h26a_padding_count,0
        dc.l    0,p96wd_n38,p96w_wait_timeouts,0
        dc.l    0,p96wd_n39,bulk_rx_msgid,0
